                                <InfoRow label="Land Balance" value={<span className="text-red-600">{formatCurrency(selectedClient.payment.balance)}</span>} />
                                <div className="my-2 border-t border-gray-200 dark:border-gray-700"></div>
                                <InfoRow label="Indenture Price" value={formatCurrency((selectedClient.payment as any).indenturePrice || 0)} />
                                <InfoRow label="Indenture Paid" value={<span className="text-green-600">{formatCurrency((selectedClient.payment as any).indenturePaid || 0)}</span>} />
                                <InfoRow label="Indenture Balance" value={<span className="text-red-600">{formatCurrency((selectedClient.payment as any).indentureBalance || 0)}</span>} />
