};

import React, { useState, useEffect } from 'react';
import { Client, Invoice, PaymentTransaction, ReceiptPattern, ReceiptAlert, Staff, Role } from '../types';
import { 
    FunnelIcon, 
    MagnifyingGlassIcon, 
    DocumentPlusIcon, 
    PencilIcon, 
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { FinancialRecordEditor } from '../components/FinancialRecordEditor';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: ReceiptPattern | null;
  setReceiptPattern: React.Dispatch<React.SetStateAction<ReceiptPattern | null>>;
  setReceiptAlerts: React.Dispatch<React.SetStateAction<ReceiptAlert[]>>;
  currentStaff: Staff;
  roles: Role[];
}

const getStatusBadge = (status: Invoice['status'] | string) => {
  let variant: 'success' | 'warning' | 'danger' | 'neutral' = 'neutral';
  switch (status) {
    case 'Paid': case 'Success': case 'On Time': variant = 'success'; break;
    case 'Pending': variant = 'warning'; break;
    case 'Overdue': case 'Failed': case 'Late': variant = 'danger'; break;
  }
  return <Badge variant={variant}>{status}</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ invoices, clients, onSaveClient, onSaveInvoice, clientForInvoice, setClientForInvoice, receiptPattern, setReceiptPattern, setReceiptAlerts, currentStaff, roles }) => {
  const [viewMode, setViewMode] = useState<'list' | 'editor'>('list');
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  useEffect(() => {
    if (clientForInvoice) {
        setEditingInvoice(null);
        setViewMode('editor');
    }
  }, [clientForInvoice]);

  const handleCreateInvoice = () => {
    setEditingInvoice(null);
    setClientForInvoice(null);
    setViewMode('editor');
  };

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setClientForInvoice(null);
    setViewMode('editor');
  };

  const handleBack = () => {
      setViewMode('list');
      setEditingInvoice(null);
      if (clientForInvoice) {
          setClientForInvoice(null);
      }
  };

  const handleSaveInvoice = async (invoiceToSave: Invoice, updatedClientData?: Client) => {
    if (updatedClientData) {
        await onSaveClient(updatedClientData);
    }

    if (invoiceToSave.amount > 0 || editingInvoice) {
        await onSaveInvoice(invoiceToSave);
    }

    handleBack();
  };

  const handleRecordPayment = async (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' }) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const isLand = paymentData.type === 'Land';
    const landPaid = isLand ? client.payment.paid + newTransaction.amount : client.payment.paid;
    const indenturePaid = !isLand ? ((client.payment as any).indenturePaid || 0) + newTransaction.amount : ((client.payment as any).indenturePaid || 0);

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: landPaid,
            balance: client.payment.total - landPaid,
            indenturePaid: indenturePaid,
            indentureBalance: ((client.payment as any).indenturePrice || 0) - indenturePaid,
        }
    } as Client;

    await onSaveClient(updatedClient);

    // Continuous 70% check
    const ratio = landPaid / client.payment.total;
    if (ratio >= 0.7) {
        // Trigger generic admin notification via interaction log (existing notification pattern)
        const updatedWithNotif = {
            ...updatedClient,
            interactions: [
                { id: Date.now(), type: 'Note', date: new Date().toISOString(), agent: 'System', notes: 'Client reached 70% payment threshold. Eligible for plot allocation.' },
                ...updatedClient.interactions
            ]
        };
        await onSaveClient(updatedWithNotif);
    }

    alert(`${paymentData.type} payment of ${formatCurrency(newTransaction.amount)} recorded.`);
  };

  if (viewMode === 'editor') {
      return (
        <FinancialRecordEditor 
            onBack={handleBack}
            clients={clients}
            onSave={handleSaveInvoice}
            onRecordPayment={handleRecordPayment}
            editingInvoice={editingInvoice}
            clientForInvoice={clientForInvoice}
            roles={roles}
        />
      );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Track land and indenture payments across all client accounts.</p>
        </div>
        <Button onClick={handleCreateInvoice} icon={<DocumentPlusIcon className="w-5 h-5" />}>
            Create Financial Record
        </Button>
      </div>

      <Card className="flex flex-wrap gap-4 justify-between items-center p-4">
        <div className="relative flex-grow sm:flex-grow-0 sm:w-80">
          <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 dark:text-gray-500" />
          <input
              type="text"
              placeholder="Search by client name..."
              className="pl-10 block w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <Button variant="secondary" icon={<FunnelIcon className="w-5 h-5" />}>Filter</Button>
      </Card>

      <TableContainer>
        <table className="w-full text-sm text-left text-gray-500 dark:text-gray-400">
            <Thead>
                <tr>
                    <Th>Prospective Client</Th>
                    <Th>Land Balance</Th>
                    <Th>Indenture Balance</Th>
                    <Th>Total Paid</Th>
                    <Th className="text-center">Threshold</Th>
                    <Th className="text-center">Actions</Th>
                </tr>
            </Thead>
            <Tbody>
                {invoices.map(invoice => {
                    const client = clients.find(c => c.id === invoice.clientId);
                    if (!client) return null;
                    const ratio = client.payment.paid / client.payment.total;
                    const indentureBal = ((client.payment as any).indentureBalance || 0);

                    return (
                        <Tr key={invoice.id}>
                            <Td className="font-medium text-indigo-600 dark:text-indigo-400 whitespace-nowrap">{client.name}</Td>
                            <Td className="font-semibold text-red-600">{formatCurrency(client.payment.balance)}</Td>
                            <Td className="font-semibold text-orange-600">{formatCurrency(indentureBal)}</Td>
                            <Td className="font-semibold text-green-600">{formatCurrency(client.payment.paid + ((client.payment as any).indenturePaid || 0))}</Td>
                            <Td className="text-center">
                                <Badge variant={ratio >= 0.7 ? 'success' : 'warning'}>{(ratio * 100).toFixed(0)}%</Badge>
                            </Td>
                            <Td className="text-center">
                                <button onClick={() => handleEditInvoice(invoice)} className="text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400 p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700">
                                    <PencilIcon className="w-5 h-5" />
                                </button>
                            </Td>
                        </Tr>
                    );
                })}
            </Tbody>
        </table>
        {invoices.length === 0 && (
            <div className="text-center py-10">
                <p className="text-gray-500 dark:text-gray-400">No transactions found.</p>
            </div>
        )}
      </TableContainer>
    </div>
  );
};

export default AccountManagementPage;

import React, { useState } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import LeadsManagementPage from './pages/LeadsManagementPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';

import { DataProvider, useData } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ROLES, GENERATED_REPORTS } from './data/mockData';
import { Client } from './types';

const AppContent: React.FC = () => {
    const { 
        clients, properties, invoices, staff, leads, promotions, 
        companySettings, activityLogs, roles, amendments,
        saveClient, deleteClient, saveProperty, saveInvoice, 
        saveLead, deleteLead, savePromotion, deletePromotion,
        updateStaff, setStaff, setRoles, setCompanySettings,
        addActivityLog, setAmendmentList, setClientList
    } = useData();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    // Helper for context-aware logger
    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                    roles={roles}
                 />;
            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
                return <PropertiesPage properties={properties} currentStaff={currentStaff} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
             case 'New Land Acquisition':
                return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
             case 'Promotions':
                return <PromotionsPage 
                    promotions={promotions} 
                    onSavePromotion={savePromotion}
                    onDeletePromotion={deletePromotion}
                    properties={properties} 
                    showForm={true} 
                    onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} 
                />;
            case 'Administration':
                return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Lead Management & Follow-Up':
                return <LeadsManagementPage 
                    leads={leads} 
                    onSaveLead={saveLead}
                    onDeleteLead={deleteLead}
                    clients={clients} 
                    onSaveClient={saveClient}
                    staffList={staff} 
                    roles={roles}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]} 
                    currentStaff={currentStaff} 
                    addActivityLog={handleAddActivityLog} 
                />;
            case 'Human Resources':
                return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts':
                return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot':
                return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation':
                return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Amendment Form':
                return <AmendmentFormPage client={pageContext} onBack={() => handleSetPage('Client Details', pageContext)} onSave={(data) => { setAmendmentList(prev => [data, ...prev]); alert('Amendment saved!'); handleSetPage('Client Details', pageContext);}} currentStaff={currentStaff} />;
            case 'Analytics & Reports':
                return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports':
                return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity':
                return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            default:
                return <div>Page not found</div>;
        }
    };

    const staffPermissions = ROLES.find(r => r.id === currentStaff.roleId)?.name === 'CEO' 
        ? { Dashboard: { view: true }, Clients: { view: true }, 'Account Management': { view: true }, Promotions: { view: true }, Team: { view: true }, 'Leads Management': { view: true }, Administration: { view: true }, 'CEO Hub': { view: true }, Settings: { view: true } }
        : { Dashboard: { view: true }, Clients: { view: true }, 'Account Management': { view: true }, Team: { view: true }, 'Leads Management': { view: true }, Settings: { view: true } };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff} 
            onLogout={logout}
            staffPermissions={staffPermissions as any}
            companySettings={companySettings}
        >
            {renderPage()}
        </Layout>
    );
};

const App: React.FC = () => {
    return (
        <DataProvider>
            <AuthProvider>
                <AppContent />
            </AuthProvider>
        </DataProvider>
    );
};

export default App;

