    const { currentStaff } = useAuth();
    const dropdownRef = useRef<HTMLDivElement>(null);
    const [selectedClientId, setSelectedClientId] = useState<number | null>(fixedClient ? fixedClient.id : null);
    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    // Financial State (Live UI State)
    const [landPrice, setLandPrice] = useState('0');
    const [indenturePrice, setIndenturePrice] = useState('0');
    const [paymentOption, setPaymentOption] = useState('Outright');
    const [otherMonths, setOtherMonths] = useState('');
    const [calculatedTotal, setCalculatedTotal] = useState<number | null>(null);

    // Derive initialization state
    const isInitialized = !!selectedClient?.payment?.isInitialized;
    const canAmend = useMemo(() => {
        if (!roles || !currentStaff) return false;
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'Accountant' || roleName === 'Chief Accountant';
    }, [currentStaff, roles]);

    // Outside Click Listener for Dropdown
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsClientDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setIndenturePrice(String((selectedClient.payment as any).indenturePrice || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
        }
    }, [selectedClient]);

    useEffect(() => {
        if (!selectedClient) return;
        const P = parseFloat(landPrice) || 0;
        const ANNUAL_RATE = 0.10;
        const r = ANNUAL_RATE / 12;
        let n = 0;
        if (paymentOption === '3') n = 3;
        else if (paymentOption === '6') n = 6;
        else if (paymentOption === 'Other' && otherMonths) n = parseInt(otherMonths, 10);

        if (n > 0 && paymentOption !== 'Outright') {
            const emi = (P * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
            setCalculatedTotal(emi * n);
        } else {
            setCalculatedTotal(P);
        }
    }, [paymentOption, otherMonths, landPrice, selectedClient]);

    const handleFormSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient) return;

        const finalLandPrice = calculatedTotal || parseFloat(landPrice) || 0;
        const finalIndenturePrice = parseFloat(indenturePrice) || 0;

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: finalLandPrice,
                balance: finalLandPrice - selectedClient.payment.paid,
                indenturePrice: finalIndenturePrice,
                indentureBalance: finalIndenturePrice - ((selectedClient.payment as any).indenturePaid || 0),
                planType: paymentOption === 'Outright' ? 'Outright Payment' : `${paymentOption}-Month Installment`,
                amendmentHistory: isInitialized ? [
                    ...(selectedClient.payment as any).amendmentHistory || [],
                    {
                        timestamp: new Date().toISOString(),
                        amendedBy: currentStaff?.fullName,
                        role: roles.find(r => r.id === currentStaff?.roleId)?.name,
                        changes: "Financial field amendment"
                    }
                ] : []
            }
        } as Client;

        onSave({ id: `INV-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
        setIsUnlocked(false);
    };

    const handleCommissionPaid = () => {
        if (!selectedClient) return;
        const updatedClient = {
            ...selectedClient,
            officeUse: {
                ...selectedClient.officeUse,
                commission: { ...selectedClient.officeUse.commission, status: 'Paid', paymentDate: new Date().toISOString() }
            },
            payment: {
                ...selectedClient.payment,
                commissionHistory: [
                    ...(selectedClient.payment as any).commissionHistory || [],
                    { date: new Date().toISOString(), amount: selectedClient.officeUse.commission.amount, status: 'Paid' }
                ]
            }
        } as Client;
        onSave({ id: 'N/A', clientId: 0, clientName: '', amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
    };

    const InfoRow = ({ label, value, isLarge = false }: any) => (
        <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700 last:border-b-0">
            <dt className="text-sm text-gray-500 dark:text-gray-400">{label}</dt>
            <dd className={`text-sm font-semibold text-gray-800 dark:text-gray-200 ${isLarge ? 'text-xl' : ''}`}>{value}</dd>
        </div>
    );

    const isFieldReadOnly = isInitialized && !isUnlocked;

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white">Create & View Financials</h2>
                        {isInitialized && <Badge variant="success" className="ml-2">Account Initialized</Badge>}
                    </div>
                </div>
                <div className="flex gap-2">
                    {!isInitialized || isUnlocked ? (
                         <Button onClick={handleFormSubmit} disabled={!selectedClient}>Save Record</Button>
                    ) : (
                        canAmend && <Button variant="secondary" icon={<PencilSquareIcon className="w-4 h-4"/>} onClick={() => setAuthModalOpen(true)}>Amend</Button>
                    )}
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-4 space-y-4 overflow-y-auto scrollbar-thin">
                    {!fixedClient && (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Client</label>
                            <button
                                type="button"
                                disabled={isInitialized && !isUnlocked}
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className={`flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all ${isInitialized && !isUnlocked ? 'opacity-75 cursor-not-allowed bg-gray-50 dark:bg-gray-800/50' : 'cursor-pointer hover:border-gray-400 dark:hover:border-gray-500'}`}
                            >
                                <span className="truncate">{selectedClient ? selectedClient.name : '-- Select a client --'}</span>
                                <ChevronDownIcon className={`w-4 h-4 text-gray-400 transition-transform pointer-events-none ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                            </button>

                            {isClientDropdownOpen && (
                                <div className="absolute left-0 right-0 mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-xl z-50 max-h-60 overflow-y-auto scrollbar-thin animate-in fade-in slide-in-from-top-1">
                                    {clients.map(client => (
                                        <button
                                            key={client.id}
                                            type="button"
                                            onClick={() => {
                                                setSelectedClientId(client.id);
                                                setIsClientDropdownOpen(false);
                                            }}
                                            className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 dark:hover:bg-indigo-900/30 transition-colors border-b border-gray-50 dark:border-gray-700 last:border-0 ${selectedClientId === client.id ? 'bg-indigo-50 dark:bg-indigo-900/40 font-semibold text-indigo-700 dark:text-indigo-300' : 'text-gray-700 dark:text-gray-300'}`}
                                        >
                                            {client.name}
                                        </button>
                                    ))}
                                    {clients.length === 0 && (
                                        <div className="px-4 py-3 text-xs text-gray-500 dark:text-gray-400 italic">No clients found.</div>
                                    )}
                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <>
                            <div className="flex items-center gap-3 p-3 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg">
                                <div className="w-12 h-12 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold">{selectedClient.initials}</div>
                                <div>
                                    <p className="font-bold text-gray-900 dark:text-white leading-tight">{selectedClient.name}</p>
                                    <p className="text-xs text-gray-500">{selectedClient.location}</p>
                                </div>
                            </div>
                            <div className="space-y-1">
                                {['overview', 'history', 'commission'].map(tab => (
                                    <button key={tab} onClick={() => setActiveTab(tab)} className={`w-full text-left p-2 rounded-md text-sm font-semibold transition-colors ${activeTab === tab ? 'bg-indigo-50 dark:bg-indigo-900/50 text-indigo-700 dark:text-indigo-300' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100'}`}>
                                        {tab.charAt(0).toUpperCase() + tab.slice(1)}
                                    </button>
                                ))}
                            </div>
                            <Card title="Live Financial Summary" className="bg-gray-50 dark:bg-gray-900 border-gray-200">
                                <InfoRow label="Land Price" value={formatCurrency(selectedClient.payment.total)} />
                                <InfoRow label="Land Paid" value={<span className="text-green-600">{formatCurrency(selectedClient.payment.paid)}</span>} />
                                <InfoRow label="Land Balance" value={<span className="text-red-600">{formatCurrency(selectedClient.payment.balance)}</span>} />
                                <div className="my-2 border-t border-gray-200 dark:border-gray-700"></div>
                                <InfoRow label="Indenture Price" value={formatCurrency((selectedClient.payment as any).indenturePrice || 0)} />
                                <InfoRow label="Indenture Paid" value={<span className="text-green-600">{formatCurrency((selectedClient.payment as any).indenturePaid || 0)}</span>} />
                                <InfoRow label="Indenture Balance" value={<span className="text-red-600">{formatCurrency((selectedClient.payment as any).indentureBalance || 0)}</span>} />
                                <div className="mt-2 p-2 bg-indigo-100 dark:bg-indigo-900/50 rounded flex justify-between">
                                    <span className="text-xs font-bold">Total Paid</span>
                                    <span className="text-xs font-bold">{formatCurrency(selectedClient.payment.paid + ((selectedClient.payment as any).indenturePaid || 0))}</span>
                                </div>
                            </Card>
                        </>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {!selectedClient ? (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50"><UserCircleIcon className="w-20 h-20 mb-2" /><p>Select a client to manage records</p></div>
                    ) : (
                        <div className="space-y-6 max-w-4xl mx-auto">
                            {activeTab === 'overview' && (
                                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                                    <div className="space-y-6">
                                        <Card title="Payment Configuration">
                                            <div className="space-y-4">
                                                <div className="relative">
                                                    <Input label="Land Purchase Price" type="number" value={landPrice} onChange={e => setLandPrice(e.target.value)} readOnly={isFieldReadOnly} />
                                                    {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                                </div>
                                                <div className="relative">
                                                    <Input label="Indenture Price" type="number" value={indenturePrice} onChange={e => setIndenturePrice(e.target.value)} readOnly={isFieldReadOnly} />
                                                    {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                                </div>
                                                <div className="relative">
                                                    <Select label="Payment Plan" value={paymentOption} onChange={e => setPaymentOption(e.target.value)} disabled={isFieldReadOnly}>
                                                        <option value="Outright">Outright Payment</option>
                                                        <option value="3">3 Months</option>
                                                        <option value="6">6 Months</option>
                                                        <option value="Other">Other</option>
                                                    </Select>
                                                    {isFieldReadOnly && <LockClosedIcon className="absolute right-8 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                                </div>
                                            </div>
                                        </Card>
                                        <div className={`p-4 rounded-lg flex items-start gap-3 border ${selectedClient.payment.paid / selectedClient.payment.total >= 0.7 ? 'bg-green-50 border-green-200 text-green-800' : 'bg-amber-50 border-amber-200 text-amber-800'}`}>
                                            <ExclamationTriangleIcon className="w-6 h-6 mt-0.5" />
                                            <div>
                                                <h4 className="font-bold text-sm">Allocation Status</h4>
                                                <p className="text-xs mt-1">Paid: {((selectedClient.payment.paid / selectedClient.payment.total) * 100).toFixed(1)}%. (Requires 70%)</p>
                                                {roles && roles.find(r => r.id === currentStaff?.roleId)?.name === 'Administrator' && (
                                                    <Button size="sm" className="mt-2" disabled={selectedClient.payment.paid / selectedClient.payment.total < 0.7}>Allocate Plot Now</Button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                    <div className="space-y-6">
                                        <Card title="Quick Actions">
                                            <Button className="w-full" variant="success" icon={<BanknotesIcon className="w-5 h-5"/>} onClick={() => setPaymentModalOpen(true)}>Record a Payment</Button>
                                            <p className="text-[10px] text-gray-500 mt-2 text-center">New payments update balances immediately.</p>
                                        </Card>
                                        {calculatedTotal && calculatedTotal > parseFloat(landPrice) && (
                                            <div className="p-4 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg border border-indigo-100 dark:border-indigo-800">
                                                <h4 className="text-xs font-bold text-indigo-700 dark:text-indigo-300 uppercase">Projected Installment Plan</h4>
                                                <InfoRow label="Total with Interest" value={formatCurrency(calculatedTotal)} />
                                                <InfoRow label="Monthly Installment" value={formatCurrency(calculatedTotal / (parseInt(paymentOption) || 1))} />
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}

                            {activeTab === 'history' && (
                                <div className="space-y-6">
                                    <Card title="Payment History" className="p-0">
                                        <div className="overflow-x-auto">
                                            <table className="w-full text-sm text-left">
                                                <thead className="text-xs uppercase bg-gray-50 dark:bg-gray-700">
                                                    <tr>
                                                        <th className="px-4 py-3">Date</th><th className="px-4 py-3">Type</th><th className="px-4 py-3">Amount</th><th className="px-4 py-3">Receipt</th><th className="px-4 py-3 text-center">Status</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-gray-100 dark:divide-gray-600">
                                                    {selectedClient.payment.paymentHistory.map((p: any) => (
                                                        <tr key={p.id}>
                                                            <td className="px-4 py-3">{p.date}</td>
                                                            <td className="px-4 py-3"><Badge variant={p.type === 'Indenture' ? 'purple' : 'info'}>{p.type || 'Land'}</Badge></td>
                                                            <td className="px-4 py-3 font-bold">{formatCurrency(p.amount)}</td>
                                                            <td className="px-4 py-3 font-mono text-indigo-600">{p.receiptNumber}</td>
                                                            <td className="px-4 py-3 text-center">{getStatusBadge(p.status)}</td>
                                                        </tr>
                                                    ))}
                                                    {selectedClient.payment.paymentHistory.length === 0 && <tr><td colSpan={5} className="p-8 text-center text-gray-400">No transactions recorded yet.</td></tr>}
                                                </tbody>
                                            </table>
                                        </div>
                                    </Card>
                                </div>
                            )}

                            {activeTab === 'commission' && (
                                <Card title="Commission Status">
                                    <dl className="mb-6">
                                        <InfoRow label="Assigned Rep" value={selectedClient.officeUse.salesRep} />
                                        <InfoRow label="Commission Amount" value={formatCurrency(selectedClient.officeUse.commission.amount)} />
                                        <InfoRow label="Status" value={getStatusBadge(selectedClient.officeUse.commission.status)} />
                                    </dl>
                                    <Button 
                                        variant="success" 
                                        className="w-full"
                                        disabled={selectedClient.officeUse.commission.status === 'Paid'} 
                                        onClick={handleCommissionPaid}
                                    >
                                        Mark Commission as Paid
                                    </Button>
                                    {(selectedClient.payment as any).commissionHistory?.length > 0 && (
                                        <div className="mt-6 border-t pt-4">
                                            <h4 className="text-xs font-bold text-gray-500 uppercase mb-2">History</h4>
                                            {(selectedClient.payment as any).commissionHistory.map((h: any, i: number) => (
                                                <div key={i} className="text-xs flex justify-between py-1">
                                                    <span>{new Date(h.date).toLocaleDateString()}</span>
                                                    <span className="font-bold text-green-600">Paid {formatCurrency(h.amount)}</span>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </Card>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {selectedClient && (
                <RecordPaymentModal 
                    isOpen={isPaymentModalOpen} 
                    onClose={() => setPaymentModalOpen(false)} 
                    onSave={(p) => onRecordPayment(selectedClient, p)} 
                    client={selectedClient}
                />
            )}

            <ReAuthModal 
                isOpen={isAuthModalOpen} 
                onClose={() => setAuthModalOpen(false)} 
                onSuccess={() => setIsUnlocked(true)} 
            />

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 6px; height: 6px; }
                .scrollbar-thin::-webkit-scrollbar-track { background: transparent; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
        </div>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import LeadsManagementPage from './pages/LeadsManagementPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';
import MappingsPage from './pages/MappingsPage';

import { DataProvider, usePermissions } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { 
    useClients, useProperties, useInvoices, useStaff, useLeads, 
    usePromotions, useActivityLogs, useRoles, useAmendments, useCompanySettings 
} from './hooks/useAppData';

const queryClient = new QueryClient();

const AppContent: React.FC = () => {
    // --- Data Hooks ---
    const { clients, saveClient, deleteClient } = useClients();
    const { properties, saveProperty } = useProperties();
    const { invoices, saveInvoice } = useInvoices();
    const { staff, updateStaff } = useStaff(); 
    const { leads, saveLead, deleteLead } = useLeads();
    const { promotions, savePromotion, deletePromotion } = usePromotions();
    const { activityLogs, addActivityLog } = useActivityLogs();
    const { roles, setRoles } = useRoles();
    const { amendments, setAmendmentList } = useAmendments();
    const { companySettings, setCompanySettings } = useCompanySettings();
    const { rolePermissions } = usePermissions();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    // Dynamic Favicon Update
    useEffect(() => {
        if (companySettings.favicon) {
            let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
            if (!link) {
                link = document.createElement('link');
                link.rel = 'icon';
                document.head.appendChild(link);
            }
            link.href = companySettings.favicon;
        }
    }, [companySettings.favicon]);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    // Calculate Permissions based on the User's Role ID from the Context.
    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};

        // Find all permissions associated with the current staff's role ID
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);

        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });

        // Fallback/Default if no permissions found
        if (Object.keys(userPermissions).length === 0) {
             userPermissions['Dashboard'] = { view: true, create: false, edit: false, delete: false, approve: false };
        }

        return userPermissions;
    }, [currentStaff, rolePermissions]);

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                    roles={roles}
                 />;
            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                    onUpdateStaff={updateStaff}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
