import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, Invoice, PaymentTransaction, Installment, Staff, Role } from '../types';
import { 
    BanknotesIcon,
    ChevronRightIcon,
    ArrowLeftIcon,
    LockClosedIcon,
    PencilSquareIcon,
    ShieldCheckIcon,
    ChevronDownIcon
} from './icons/DummyIcons';
import { XIcon } from './icons/XIcon';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Input, Select } from './ui/Input';
import { Badge } from './ui/Badge';
import { UserCircleIcon, CheckCircleIcon, ExclamationTriangleIcon } from './icons/DummyIcons';
import { useAuth } from '../context/AuthContext';

const getStatusBadge = (status: string) => {
  let variant: 'success' | 'warning' | 'danger' | 'neutral' = 'neutral';
  switch (status) {
    case 'Paid': case 'Success': case 'On Time': variant = 'success'; break;
    case 'Pending': variant = 'warning'; break;
    case 'Overdue': case 'Failed': case 'Late': variant = 'danger'; break;
  }
  return <Badge variant={variant}>{status}</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

/**
 * Re-authentication Modal for Amendments
 */
const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Verify Identity</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Re-authenticate to unlock financial fields.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Staff Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="email@faim.com" />
                        <Input label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const RecordPaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSave: (payment: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' }) => void;
    client: Client;
}> = ({ isOpen, onClose, onSave, client }) => {
    const [amount, setAmount] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [type, setType] = useState<'Land' | 'Indenture'>('Land');
    const [reference, setReference] = useState('');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            setAmount('');
            setDate(new Date().toISOString().split('T')[0]);
            setError('');
        }
    }, [isOpen]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const paidAmount = parseFloat(amount);
        if (isNaN(paidAmount) || paidAmount <= 0) {
            setError('Please enter a valid positive amount.');
            return;
        }

        const balance = type === 'Land' ? client.payment.balance : (client.payment as any).indentureBalance || 0;
        if (paidAmount > balance && balance > 0) {
            setError(`Amount cannot exceed the current ${type} balance.`);
            return;
        }

        if (!receiptNumber.trim()) {
            setError('Receipt number is required.');
            return;
        }
        onSave({ date, amount: paidAmount, method, reference, receiptNumber, type });
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-md p-0 overflow-hidden">
                <form onSubmit={handleSubmit}>
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700">
                        <h2 className="text-lg font-bold text-gray-800 dark:text-white">Record {type} Payment</h2>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XIcon className="w-6 h-6" /></button>
                    </div>
                    <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
                        {error && <div className="bg-red-50 text-red-700 p-3 rounded-md text-xs border border-red-200">{error}</div>}
                        <Select label="Payment Type*" value={type} onChange={e => setType(e.target.value as any)}>
                            <option value="Land">Land Purchase</option>
                            <option value="Indenture">Indenture/Documentation</option>
                        </Select>
                        <Input label="Payment Date*" type="date" value={date} onChange={e => setDate(e.target.value)} required />
                        <Input label="Amount Paid*" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" required className="no-spinner" />
                        <Input label="Receipt Number*" value={receiptNumber} onChange={e => setReceiptNumber(e.target.value)} required />
                        <Select label="Payment Method*" value={method} onChange={e => setMethod(e.target.value as any)}>
                            <option>Bank Transfer</option><option>Cash</option><option>MoMo</option><option>Cheque</option><option>Other</option>
                        </Select>
                    </div>
                    <div className="flex justify-end p-4 border-t border-gray-200 bg-gray-50 gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit">Save Payment</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const dropdownRef = useRef<HTMLDivElement>(null);
    const [selectedClientId, setSelectedClientId] = useState<number | null>(fixedClient ? fixedClient.id : null);
    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    // Financial State (Live UI State)
    const [landPrice, setLandPrice] = useState('0');
    const [indenturePrice, setIndenturePrice] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [discountValue, setDiscountValue] = useState('0');
    const [paymentOption, setPaymentOption] = useState('Outright');
    const [otherMonths, setOtherMonths] = useState('');
    const [calculatedTotal, setCalculatedTotal] = useState<number | null>(null);

    // Derive initialization state
    const isInitialized = !!selectedClient?.payment?.isInitialized;
    const canAmend = useMemo(() => {
        if (!roles || !currentStaff) return false;
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'Accountant' || roleName === 'Chief Accountant';
    }, [currentStaff, roles]);

    // Outside Click Listener for Dropdown
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsClientDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setIndenturePrice(String((selectedClient.payment as any).indenturePrice || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
            setDiscountValue(String((selectedClient.payment as any).discountValue || '0'));
            setDiscountType((selectedClient.payment as any).discountType || 'percentage');
        }
    }, [selectedClient]);

    useEffect(() => {
        if (!selectedClient) return;
        const P_initial = parseFloat(landPrice) || 0;
        const D = parseFloat(discountValue) || 0;

        // Calculate price after discount for interest calculation
        let P = P_initial;
        if (discountType === 'percentage') {
            P = P_initial * (1 - (D / 100));
        } else {
            P = Math.max(0, P_initial - D);
        }

        const ANNUAL_RATE = 0.10;
        const r = ANNUAL_RATE / 12;
        let n = 0;
        if (paymentOption === '3') n = 3;
        else if (paymentOption === '6') n = 6;
        else if (paymentOption === 'Other' && otherMonths) n = parseInt(otherMonths, 10);

        if (n > 0 && paymentOption !== 'Outright') {
            const emi = (P * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
            setCalculatedTotal(emi * n);
        } else {
            setCalculatedTotal(P);
        }
    }, [paymentOption, otherMonths, landPrice, selectedClient, discountType, discountValue]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient || isSaving) return;

        setIsSaving(true);
        const finalLandPrice = calculatedTotal || parseFloat(landPrice) || 0;
        const finalIndenturePrice = parseFloat(indenturePrice) || 0;

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: finalLandPrice,
                balance: finalLandPrice - selectedClient.payment.paid,
                indenturePrice: finalIndenturePrice,
                indentureBalance: finalIndenturePrice - ((selectedClient.payment as any).indenturePaid || 0),
                discountValue: parseFloat(discountValue) || 0,
                discountType: discountType,
                planType: paymentOption === 'Outright' ? 'Outright Payment' : `${paymentOption}-Month Installment`,
                amendmentHistory: isInitialized ? [
                    ...(selectedClient.payment as any).amendmentHistory || [],
                    {
                        timestamp: new Date().toISOString(),
                        amendedBy: currentStaff?.fullName,
                        role: roles.find(r => r.id === currentStaff?.roleId)?.name,
                        changes: "Financial field amendment"
                    }
                ] : []
            }
        } as Client;

        try {
            // FIX: Use safe string for temporary ID to avoid Firestore slash errors (even number of segments rule)
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
            setShowSuccessModal(true);
        } finally {
            setIsSaving(false);
        }
    };

    const handleCommissionPaid = () => {
        if (!selectedClient) return;
        const updatedClient = {
            ...selectedClient,
            officeUse: {
                ...selectedClient.officeUse,
                commission: { ...selectedClient.officeUse.commission, status: 'Paid', paymentDate: new Date().toISOString() }
            },
            payment: {
                ...selectedClient.payment,
                commissionHistory: [
                    ...(selectedClient.payment as any).commissionHistory || [],
                    { date: new Date().toISOString(), amount: selectedClient.officeUse.commission.amount, status: 'Paid' }
                ]
            }
        } as Client;
        // FIX: Use safe unique ID without slashes (slash in ID splits path segments)
        onSave({ id: `COMM-${Date.now()}`, clientId: 0, clientName: '', amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
    };

    const InfoRow = ({ label, value, isLarge = false }: any) => (
        <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700 last:border-b-0">
            <dt className="text-sm text-gray-500 dark:text-gray-400">{label}</dt>
            <dd className={`text-sm font-semibold text-gray-800 dark:text-gray-200 ${isLarge ? 'text-xl' : ''}`}>{value}</dd>
        </div>
    );

    const isFieldReadOnly = isInitialized && !isUnlocked;

    const paymentDescriptionTitle = (
        <div className="flex items-center gap-2">
            <span>Payment Description</span>
            {isInitialized && (
                <div 
                    className="w-2.5 h-2.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)] animate-pulse" 
                    title="Account initialized"
                ></div>
            )}
        </div>
    );

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white">Create & View Financials</h2>
                        {isInitialized && <Badge variant="success" className="ml-2">Account Initialized</Badge>}
                    </div>
                </div>
                <div className="flex gap-2">
                    {isInitialized && !isUnlocked && canAmend && (
                        <Button variant="secondary" icon={<PencilSquareIcon className="w-4 h-4"/>} onClick={() => setAuthModalOpen(true)}>Amend</Button>
                    )}
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-4 space-y-4 overflow-y-auto scrollbar-thin">
                    {!fixedClient && (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Client</label>
                            <button
                                type="button"
                                disabled={isInitialized && !isUnlocked}
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className={`flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all ${isInitialized && !isUnlocked ? 'opacity-75 cursor-not-allowed bg-gray-50 dark:bg-gray-800/50' : 'cursor-pointer hover:border-gray-400 dark:hover:border-gray-500'}`}
                            >
                                <span className="truncate">{selectedClient ? selectedClient.name : '-- Select a client --'}</span>
                                <ChevronDownIcon className={`w-4 h-4 text-gray-400 transition-transform pointer-events-none ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                            </button>

                            {isClientDropdownOpen && (
                                <div className="absolute left-0 right-0 mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-xl z-50 max-h-60 overflow-y-auto scrollbar-thin animate-in fade-in slide-in-from-top-1">
                                    {clients.map(client => (
                                        <button
                                            key={client.id}
                                            type="button"
                                            onClick={() => {
                                                setSelectedClientId(client.id);
                                                setIsClientDropdownOpen(false);
                                            }}
                                            className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 dark:hover:bg-indigo-900/30 transition-colors border-b border-gray-50 dark:border-gray-700 last:border-0 ${selectedClientId === client.id ? 'bg-indigo-50 dark:bg-indigo-900/40 font-semibold text-indigo-700 dark:text-indigo-300' : 'text-gray-700 dark:text-gray-300'}`}
                                        >
                                            {client.name}
                                        </button>
                                    ))}
                                    {clients.length === 0 && (
                                        <div className="px-4 py-3 text-xs text-gray-500 dark:text-gray-400 italic">No clients found.</div>
                                    )}
                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <>
                            <div className="flex items-center gap-3 p-3 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg">
                                <div className="w-12 h-12 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold">{selectedClient.initials}</div>
                                <div>
                                    <p className="font-bold text-gray-900 dark:text-white leading-tight">{selectedClient.name}</p>
                                    <p className="text-xs text-gray-500">{selectedClient.location}</p>
                                </div>
                            </div>
                            <div className="space-y-1">
                                {['overview', 'history', 'commission'].map(tab => (
                                    <button key={tab} onClick={() => setActiveTab(tab)} className={`w-full text-left p-2 rounded-md text-sm font-semibold transition-colors ${activeTab === tab ? 'bg-indigo-50 dark:bg-indigo-900/50 text-indigo-700 dark:text-indigo-300' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100'}`}>
                                        {tab.charAt(0).toUpperCase() + tab.slice(1)}
                                    </button>
                                ))}
                            </div>
                            <Card title="Live Financial Summary" className="bg-gray-50 dark:bg-gray-900 border-gray-200">
                                <InfoRow label="Land Price" value={formatCurrency(selectedClient.payment.total)} />
                                <InfoRow label="Land Paid" value={<span className="text-green-600">{formatCurrency(selectedClient.payment.paid)}</span>} />
                                <InfoRow label="Land Balance" value={<span className="text-red-600">{formatCurrency(selectedClient.payment.balance)}</span>} />
                                <div className="my-2 border-t border-gray-200 dark:border-gray-700"></div>
                                <InfoRow label="Indenture Price" value={formatCurrency((selectedClient.payment as any).indenturePrice || 0)} />
                                <InfoRow label="Indenture Paid" value={<span className="text-green-600">{formatCurrency((selectedClient.payment as any).indenturePaid || 0)}</span>} />
                                <InfoRow label="Indenture Balance" value={<span className="text-red-600">{formatCurrency((selectedClient.payment as any).indentureBalance || 0)}</span>} />
                                <div className="mt-2 p-2 bg-indigo-100 dark:bg-indigo-900/50 rounded flex justify-between">
                                    <span className="text-xs font-bold">Total Paid</span>
                                    <span className="text-xs font-bold">{formatCurrency(selectedClient.payment.paid + ((selectedClient.payment as any).indenturePaid || 0))}</span>
                                </div>
                            </Card>
                        </>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {!selectedClient ? (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50"><UserCircleIcon className="w-20 h-20 mb-2" /><p>Select a client to manage records</p></div>
                    ) : (
                        <div className="space-y-6 max-w-3xl mx-auto">
                            {activeTab === 'overview' && (
                                <div className="flex flex-col gap-6">
                                    {/* Primary Financial Setup Section */}
                                    <Card title={paymentDescriptionTitle}>
                                        <div className="space-y-4">
                                            <div className="relative">
                                                <Input label="Land Purchase Price" type="number" value={landPrice} onChange={e => setLandPrice(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                            </div>

                                            {/* Discount Row */}
                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                <div className="relative">
                                                    <Input 
                                                        label="Discount (Optional)" 
                                                        type="number" 
                                                        value={discountValue} 
                                                        onChange={e => setDiscountValue(e.target.value)} 
                                                        readOnly={isFieldReadOnly} 
                                                        className="no-spinner"
                                                        placeholder="0.00"
                                                    />
                                                    {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                                </div>
                                                <div className="flex flex-col">
                                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Discount Mode</label>
                                                    <div className="flex h-[38px] bg-gray-100 dark:bg-gray-900 p-1 rounded-md border border-gray-300 dark:border-gray-700">
                                                        <button 
                                                            type="button"
                                                            disabled={isFieldReadOnly}
                                                            onClick={() => setDiscountType('percentage')}
                                                            className={`flex-1 text-xs font-bold rounded transition-all ${discountType === 'percentage' ? 'bg-white dark:bg-gray-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                                                        >
                                                            Percentage (%)
                                                        </button>
                                                        <button 
                                                            type="button"
                                                            disabled={isFieldReadOnly}
                                                            onClick={() => setDiscountType('fixed')}
                                                            className={`flex-1 text-xs font-bold rounded transition-all ${discountType === 'fixed' ? 'bg-white dark:bg-gray-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                                                        >
                                                            Fixed (GHC)
                                                        </button>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="relative">
                                                <Input label="Indenture Price" type="number" value={indenturePrice} onChange={e => setIndenturePrice(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                            </div>
                                            <div className="relative">
                                                <Select label="Payment Plan" value={paymentOption} onChange={e => setPaymentOption(e.target.value)} disabled={isFieldReadOnly}>
                                                    <option value="Outright">Outright Payment</option>
                                                    <option value="3">3 Months</option>
                                                    <option value="6">6 Months</option>
                                                    <option value="Other">Other</option>
                                                </Select>
                                                {isFieldReadOnly && <LockClosedIcon className="absolute right-8 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                            </div>

                                            {(!isInitialized || isUnlocked) && (
                                                <div className="pt-2">
                                                    <Button 
                                                        onClick={handleFormSubmit} 
                                                        disabled={!selectedClient || isSaving} 
                                                        className="w-full"
                                                        isLoading={isSaving}
                                                    >
                                                        Save Record
                                                    </Button>
                                                </div>
                                            )}
                                        </div>
                                    </Card>

                                    {/* Quick Actions - Now vertically stacked beneath config */}
                                    <Card title="Quick Actions">
                                        <Button className="w-full" variant="success" icon={<BanknotesIcon className="w-5 h-5"/>} onClick={() => setPaymentModalOpen(true)}>Record a Payment</Button>
                                        <p className="text-[10px] text-gray-500 mt-2 text-center">New payments update balances immediately.</p>
                                    </Card>

                                    {/* Supplemental Information Indicators */}
                                    <div className={`p-4 rounded-lg flex items-start gap-3 border ${selectedClient.payment.paid / (parseFloat(landPrice) || 1) >= 0.7 ? 'bg-green-50 border-green-200 text-green-800' : 'bg-amber-50 border-amber-200 text-amber-800'}`}>
                                        <ExclamationTriangleIcon className="w-6 h-6 mt-0.5" />
                                        <div>
                                            <h4 className="font-bold text-sm">Allocation Status</h4>
                                            <p className="text-xs mt-1">Paid: {((selectedClient.payment.paid / (parseFloat(landPrice) || 1)) * 100).toFixed(1)}%. (Requires 70%)</p>
                                            {roles && roles.find(r => r.id === currentStaff?.roleId)?.name === 'Administrator' && (
                                                <Button size="sm" className="mt-2" disabled={selectedClient.payment.paid / (parseFloat(landPrice) || 1) < 0.7}>Allocate Plot Now</Button>
                                            )}
                                        </div>
                                    </div>

                                    {calculatedTotal && calculatedTotal > (parseFloat(landPrice) || 0) && (
                                        <div className="p-4 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg border border-indigo-100 dark:border-indigo-800">
                                            <h4 className="text-xs font-bold text-indigo-700 dark:text-indigo-300 uppercase">Projected Installment Plan</h4>
                                            <InfoRow label="Total with Interest" value={formatCurrency(calculatedTotal)} />
                                            <InfoRow label="Monthly Installment" value={formatCurrency(calculatedTotal / (parseInt(paymentOption) || 1))} />
                                        </div>
                                    )}
                                </div>
                            )}

                            {activeTab === 'history' && (
                                <div className="space-y-6">
                                    <Card title="Payment History" className="p-0">
                                        <div className="overflow-x-auto">
                                            <table className="w-full text-sm text-left">
                                                <thead className="text-xs uppercase bg-gray-50 dark:bg-gray-700">
                                                    <tr>
                                                        <th className="px-4 py-3">Date</th><th className="px-4 py-3">Type</th><th className="px-4 py-3">Amount</th><th className="px-4 py-3">Receipt</th><th className="px-4 py-3 text-center">Status</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-gray-100 dark:divide-gray-600">
                                                    {selectedClient.payment.paymentHistory.map((p: any) => (
                                                        <tr key={p.id}>
                                                            <td className="px-4 py-3">{p.date}</td>
                                                            <td className="px-4 py-3"><Badge variant={p.type === 'Indenture' ? 'purple' : 'info'}>{p.type || 'Land'}</Badge></td>
                                                            <td className="px-4 py-3 font-bold">{formatCurrency(p.amount)}</td>
                                                            <td className="px-4 py-3 font-mono text-indigo-600">{p.receiptNumber}</td>
                                                            <td className="px-4 py-3 text-center">{getStatusBadge(p.status)}</td>
                                                        </tr>
                                                    ))}
                                                    {selectedClient.payment.paymentHistory.length === 0 && <tr><td colSpan={5} className="p-8 text-center text-gray-400">No transactions recorded yet.</td></tr>}
                                                </tbody>
                                            </table>
                                        </div>
                                    </Card>
                                </div>
                            )}

                            {activeTab === 'commission' && (
                                <Card title="Commission Status">
                                    <dl className="mb-6">
                                        <InfoRow label="Assigned Rep" value={selectedClient.officeUse.salesRep} />
                                        <InfoRow label="Commission Amount" value={formatCurrency(selectedClient.officeUse.commission.amount)} />
                                        <InfoRow label="Status" value={getStatusBadge(selectedClient.officeUse.commission.status)} />
                                    </dl>
                                    <Button 
                                        variant="success" 
                                        className="w-full"
                                        disabled={selectedClient.officeUse.commission.status === 'Paid'} 
                                        onClick={handleCommissionPaid}
                                    >
                                        Mark Commission as Paid
                                    </Button>
                                    {(selectedClient.payment as any).commissionHistory?.length > 0 && (
                                        <div className="mt-6 border-t pt-4">
                                            <h4 className="text-xs font-bold text-gray-500 uppercase mb-2">History</h4>
                                            {(selectedClient.payment as any).commissionHistory.map((h: any, i: number) => (
                                                <div key={i} className="text-xs flex justify-between py-1">
                                                    <span>{new Date(h.date).toLocaleDateString()}</span>
                                                    <span className="font-bold text-green-600">Paid {formatCurrency(h.amount)}</span>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </Card>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {selectedClient && (
                <RecordPaymentModal 
                    isOpen={isPaymentModalOpen} 
                    onClose={() => setPaymentModalOpen(false)} 
                    onSave={(p) => onRecordPayment(selectedClient, p)} 
                    client={selectedClient}
                />
            )}

            <ReAuthModal 
                isOpen={isAuthModalOpen} 
                onClose={() => setAuthModalOpen(false)} 
                onSuccess={() => setIsUnlocked(true)} 
            />

            {/* Success Confirmation Popup */}
            {showSuccessModal && (
                <div className="fixed inset-0 bg-slate-900/50 z-[100] flex justify-center items-center p-4 backdrop-blur-sm">
                    <Card className="w-full max-w-xs p-6 text-center animate-in zoom-in duration-200">
                        <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <CheckCircleIcon className="w-6 h-6 text-green-600" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">New Record saved</h3>
                        <Button onClick={() => setShowSuccessModal(false)} className="w-full">OK</Button>
                    </Card>
                </div>
            )}

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 6px; height: 6px; }
                .scrollbar-thin::-webkit-scrollbar-track { background: transparent; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }

                /* Remove spinners for all number inputs with .no-spinner class or globally */
                .no-spinner::-webkit-outer-spin-button,
                .no-spinner::-webkit-inner-spin-button {
                    -webkit-appearance: none;
                    margin: 0;
                }
                .no-spinner[type=number] {
                    -moz-appearance: textfield;
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, Invoice, PaymentTransaction, Installment, Staff, Role } from '../types';
import { 
    BanknotesIcon,
    ChevronRightIcon,
    ArrowLeftIcon,
    LockClosedIcon,
    PencilSquareIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    ClockIcon,
    CheckCircleIcon,
    ExclamationTriangleIcon,
    UserCircleIcon
} from './icons/DummyIcons';
