                                    {/* Indenture Payments specific list if needed or combined as above */}
                                    {selectedClient.payment.paymentHistory.some((p:any) => p.type === 'Indenture') && (
                                        <Card title="Documentation & Indenture Payments" className="p-0 overflow-hidden">
                                            <div className="overflow-x-auto">
