const getStatusBadge = (status: string) => {
  let variant: 'success' | 'warning' | 'danger' | 'neutral' | 'purple' = 'neutral';
  switch (status) {
    case 'Paid': case 'Success': case 'On Time': variant = 'success'; break;
    case 'Pending': variant = 'warning'; break;
    case 'Overdue': case 'Failed': case 'Late': variant = 'danger'; break;
    case 'Expected': variant = 'purple'; break;
  }
  return <Badge variant={variant}>{status}</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

/**
 * Re-authentication Modal for Amendments
 */
const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Verify Identity</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Re-authenticate to unlock financial fields.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Staff Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="email@faim.com" />
                        <Input label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const RecordPaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSave: (payment: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    client: Client;
}> = ({ isOpen, onClose, onSave, client }) => {
    const [amount, setAmount] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>('Land');
    const [reference, setReference] = useState('');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            setAmount('');
            setDate(new Date().toISOString().split('T')[0]);
            setError('');
        }
    }, [isOpen]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const paidAmount = parseFloat(amount);
        if (isNaN(paidAmount) || paidAmount <= 0) {
            setError('Please enter a valid positive amount.');
            return;
        }

        let balance = 0;
        if (type === 'Land') balance = client.payment.balance;
        else if (type === 'Indenture') balance = (client.payment as any).indentureBalance || 0;
        else if (type === 'Commission') {
            const commTarget = client.officeUse.commission.amount;
            const commPaid = client.payment.paymentHistory
                .filter((p: any) => p.type === 'Commission')
                .reduce((sum, p) => sum + p.amount, 0);
            balance = commTarget - commPaid;
        }

        if (paidAmount > balance && balance > 0) {
            setError(`Amount cannot exceed the current ${type} balance.`);
            return;
        }

        if (!receiptNumber.trim()) {
            setError('Receipt number is required.');
            return;
        }
        onSave({ date, amount: paidAmount, method, reference, receiptNumber, type });
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-md p-0 overflow-hidden">
                <form onSubmit={handleSubmit}>
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700">
                        <h2 className="text-lg font-bold text-gray-800 dark:text-white">Record {type} Payment</h2>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XIcon className="w-6 h-6" /></button>
                    </div>
                    <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
                        {error && <div className="bg-red-50 text-red-700 p-3 rounded-md text-xs border border-red-200">{error}</div>}
                        <Select label="Payment Type*" value={type} onChange={e => setType(e.target.value as any)}>
                            <option value="Land">Land Purchase</option>
                            <option value="Indenture">Indenture/Documentation</option>
                            <option value="Commission">Commission Payment</option>
                        </Select>
                        <Input label="Payment Date*" type="date" value={date} onChange={e => setDate(e.target.value)} required />
                        <Input label="Amount Paid*" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" required className="no-spinner" />
                        <Input label="Receipt Number*" value={receiptNumber} onChange={e => setReceiptNumber(e.target.value)} required />
                        <Select label="Payment Method*" value={method} onChange={e => setMethod(e.target.value as any)}>
                            <option>Bank Transfer</option><option>Cash</option><option>MoMo</option><option>Cheque</option><option>Other</option>
                        </Select>
                    </div>
                    <div className="flex justify-end p-4 border-t border-gray-200 bg-gray-50 gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit">Save Payment</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const dropdownRef = useRef<HTMLDivElement>(null);
    const [selectedClientId, setSelectedClientId] = useState<number | null>(fixedClient ? fixedClient.id : null);
    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    // Financial State (Live UI State)
    const [landPrice, setLandPrice] = useState('0');
    const [indenturePrice, setIndenturePrice] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [discountValue, setDiscountValue] = useState('0');
    const [paymentOption, setPaymentOption] = useState('Outright');
    const [otherMonths, setOtherMonths] = useState('');
    const [calculatedTotal, setCalculatedTotal] = useState<number | null>(null);

    // Derive initialization state
    const isInitialized = !!selectedClient?.payment?.isInitialized;
    const canAmend = useMemo(() => {
        if (!roles || !currentStaff) return false;
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'Accountant' || roleName === 'Chief Accountant';
    }, [currentStaff, roles]);

    // Installment Schedule Logic
    const installmentSchedule = useMemo(() => {
        if (!selectedClient || paymentOption === 'Outright') return [];

        const count = paymentOption === 'Other' ? parseInt(otherMonths) || 0 : parseInt(paymentOption) || 0;
        if (count <= 0) return [];

        const basePrice = calculatedTotal || parseFloat(landPrice) || 0;
        const monthlyAmount = basePrice / count;
        const regDate = new Date(selectedClient.regDate);

        const landPayments = selectedClient.payment.paymentHistory.filter((p: any) => p.type === 'Land' || !p.type);

        return Array.from({ length: count }).map((_, i) => {
            const dueDate = new Date(regDate);
            dueDate.setMonth(dueDate.getMonth() + (i + 1));
            const actual = landPayments[i];

            return {
                index: i + 1,
                expectedDate: dueDate.toISOString().split('T')[0],
                expectedAmount: monthlyAmount,
                actualDate: actual?.date,
                actualAmount: actual?.amount,
                receipt: actual?.receiptNumber,
                status: actual ? 'Paid' : (new Date() > dueDate ? 'Overdue' : 'Pending')
            };
        });
    }, [selectedClient, paymentOption, otherMonths, landPrice, calculatedTotal]);

    // Outside Click Listener for Dropdown
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsClientDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setIndenturePrice(String((selectedClient.payment as any).indenturePrice || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
            setDiscountValue(String((selectedClient.payment as any).discountValue || '0'));
            setDiscountType((selectedClient.payment as any).discountType || 'percentage');
        }
    }, [selectedClient]);

    useEffect(() => {
        if (!selectedClient) return;
        const P_initial = parseFloat(landPrice) || 0;
        const D = parseFloat(discountValue) || 0;

        let P = P_initial;
        if (discountType === 'percentage') {
            P = P_initial * (1 - (D / 100));
        } else {
            P = Math.max(0, P_initial - D);
        }

        const ANNUAL_RATE = 0.10;
        const r = ANNUAL_RATE / 12;
        let n = 0;
        if (paymentOption === '3') n = 3;
        else if (paymentOption === '6') n = 6;
        else if (paymentOption === 'Other' && otherMonths) n = parseInt(otherMonths, 10);

        if (n > 0 && paymentOption !== 'Outright') {
            const emi = (P * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
            setCalculatedTotal(emi * n);
        } else {
            setCalculatedTotal(P);
        }
    }, [paymentOption, otherMonths, landPrice, selectedClient, discountType, discountValue]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient || isSaving) return;

        setIsSaving(true);
        const finalLandPrice = calculatedTotal || parseFloat(landPrice) || 0;
        const finalIndenturePrice = parseFloat(indenturePrice) || 0;

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: finalLandPrice,
                balance: finalLandPrice - selectedClient.payment.paid,
                indenturePrice: finalIndenturePrice,
                indentureBalance: finalIndenturePrice - ((selectedClient.payment as any).indenturePaid || 0),
                discountValue: parseFloat(discountValue) || 0,
                discountType: discountType,
                planType: paymentOption === 'Outright' ? 'Outright Payment' : `${paymentOption}-Month Installment`,
                amendmentHistory: isInitialized ? [
                    ...(selectedClient.payment as any).amendmentHistory || [],
                    {
                        timestamp: new Date().toISOString(),
                        amendedBy: currentStaff?.fullName,
                        role: roles.find(r => r.id === currentStaff?.roleId)?.name,
                        changes: "Financial field amendment"
                    }
                ] : []
            }
        } as Client;

        try {
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
            setShowSuccessModal(true);
        } finally {
            setIsSaving(false);
        }
    };

    const handleCommissionPaid = () => {
        if (!selectedClient) return;
        const commAmount = selectedClient.officeUse.commission.amount;

        const updatedClient = {
            ...selectedClient,
            officeUse: {
                ...selectedClient.officeUse,
                commission: { ...selectedClient.officeUse.commission, status: 'Paid', paymentDate: new Date().toISOString() }
            },
            payment: {
                ...selectedClient.payment,
                commissionHistory: [
                    ...(selectedClient.payment as any).commissionHistory || [],
                    { date: new Date().toISOString(), amount: commAmount, status: 'Paid' }
                ]
            }
        } as Client;
        onSave({ id: `COMM-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
    };

    const InfoRow = ({ label, value, isLarge = false }: any) => (
        <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700 last:border-b-0">
            <dt className="text-sm text-gray-500 dark:text-gray-400">{label}</dt>
            <dd className={`text-sm font-semibold text-gray-800 dark:text-gray-200 ${isLarge ? 'text-xl' : ''}`}>{value}</dd>
        </div>
    );

    const isFieldReadOnly = isInitialized && !isUnlocked;

    const paymentDescriptionTitle = (
        <div className="flex items-center gap-2">
            <span>Payment Description</span>
            {isInitialized && (
                <div 
                    className="w-2.5 h-2.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)] animate-pulse" 
                    title="Account initialized"
                ></div>
            )}
        </div>
    );

    const FinancialSummaryCard = () => (
        <Card title="Live Financial Summary" className="bg-gray-50 dark:bg-gray-900 border-gray-200 w-full">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div>
                    <h4 className="text-xs font-bold text-gray-400 uppercase mb-3">Land Purchase</h4>
                    <InfoRow label="Price" value={formatCurrency(selectedClient?.payment.total || 0)} />
                    <InfoRow label="Actual Paid" value={<span className="text-green-600 font-bold">{formatCurrency(selectedClient?.payment.paid || 0)}</span>} />
                    <InfoRow label="Current Balance" value={<span className="text-red-600 font-bold">{formatCurrency(selectedClient?.payment.balance || 0)}</span>} />
                </div>
                <div>
                    <h4 className="text-xs font-bold text-gray-400 uppercase mb-3">Indenture & Fees</h4>
                    <InfoRow label="Price" value={formatCurrency((selectedClient?.payment as any).indenturePrice || 0)} />
                    <InfoRow label="Actual Paid" value={<span className="text-green-600 font-bold">{formatCurrency((selectedClient?.payment as any).indenturePaid || 0)}</span>} />
                    <InfoRow label="Current Balance" value={<span className="text-red-600 font-bold">{formatCurrency((selectedClient?.payment as any).indentureBalance || 0)}</span>} />
                </div>
                <div className="bg-indigo-50 dark:bg-indigo-900/20 p-4 rounded-lg flex flex-col justify-center">
                    <div className="text-xs text-indigo-600 dark:text-indigo-400 font-bold uppercase mb-1">Total Realized Revenue</div>
                    <div className="text-2xl font-black text-gray-900 dark:text-white">
                        {formatCurrency((selectedClient?.payment.paid || 0) + ((selectedClient?.payment as any).indenturePaid || 0))}
                    </div>
                    <div className="mt-2 text-[10px] text-gray-500">Includes all confirmed transactions.</div>
                </div>
            </div>
        </Card>
    );

    // Dynamic Commission Logic
    const commissionData = useMemo(() => {
        if (!selectedClient) return null;
        const totalLandPrice = selectedClient.payment.total || 1; // prevent div by zero
        const commTargetAmount = selectedClient.officeUse.commission.amount;

        // Sum of all payments typed 'Commission'
        const commPaid = selectedClient.payment.paymentHistory
            .filter((p: any) => p.type === 'Commission')
            .reduce((sum, p) => sum + p.amount, 0);

        const commDue = Math.max(0, commTargetAmount - commPaid);

        return {
            target: commTargetAmount,
            paid: commPaid,
            due: commDue,
            pctPaid: ((commPaid / totalLandPrice) * 100).toFixed(2),
            pctDue: ((commDue / totalLandPrice) * 100).toFixed(2),
            status: commDue <= 0 ? 'Paid' : 'Owing'
        };
    }, [selectedClient]);

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white">Create & View Financials</h2>
                        {isInitialized && <Badge variant="success" className="ml-2">Account Initialized</Badge>}
                    </div>
                </div>
                <div className="flex gap-2">
                    {isInitialized && !isUnlocked && canAmend && (
                        <Button variant="secondary" icon={<PencilSquareIcon className="w-4 h-4"/>} onClick={() => setAuthModalOpen(true)}>Amend</Button>
                    )}
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-4 space-y-4 overflow-y-auto scrollbar-thin">
                    {!fixedClient && (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Client</label>
                            <button
                                type="button"
                                // FIX: Removed lock on client selection to allow switching context freely
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className={`flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer hover:border-gray-400 dark:hover:border-gray-500`}
                            >
                                <span className="truncate">{selectedClient ? selectedClient.name : '-- Select a client --'}</span>
                                <ChevronDownIcon className={`w-4 h-4 text-gray-400 transition-transform pointer-events-none ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
