                                        </div>
                                    </Card>

                                    <Card title="Quick Actions">
                                        <Button className="w-full" variant="success" icon={<BanknotesIcon className="w-5 h-5"/>} onClick={() => setPaymentModalOpen(true)}>Record a Payment</Button>
                                    </Card>

                                    <div className={`p-4 rounded-lg flex items-start gap-3 border ${selectedClient.payment.paid / (parseFloat(landPrice) || 1) >= 0.7 ? 'bg-green-50 border-green-200 text-green-800' : 'bg-amber-50 border-amber-200 text-amber-800'}`}>
                                        <ExclamationTriangleIcon className="w-6 h-6 mt-0.5" />
                                        <div>
                                            <h4 className="font-bold text-sm">Allocation Status</h4>
                                            <p className="text-xs mt-1">Paid: {((selectedClient.payment.paid / (parseFloat(landPrice) || 1)) * 100).toFixed(1)}%. (Requires 70%)</p>
                                            {roles && roles.find(r => r.id === currentStaff?.roleId)?.name === 'Administrator' && (
