                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <>
                            <div className="flex items-center gap-3 p-3 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg">
                                <div className="w-12 h-12 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold">{selectedClient.initials}</div>
                                <div>
                                    <p className="font-bold text-gray-900 dark:text-white leading-tight">{selectedClient.name}</p>
                                    <p className="text-xs text-gray-500">{selectedClient.location}</p>
                                </div>
                            </div>
                            <div className="space-y-1">
                                {['overview', 'history', 'commission'].map(tab => (
                                    <button key={tab} onClick={() => setActiveTab(tab)} className={`w-full text-left p-2 rounded-md text-sm font-semibold transition-colors ${activeTab === tab ? 'bg-indigo-50 dark:bg-indigo-900/50 text-indigo-700 dark:text-indigo-300' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100'}`}>
                                        {tab.charAt(0).toUpperCase() + tab.slice(1)}
                                    </button>
                                ))}
                            </div>
                            <div className="p-3 bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700">
                                <h4 className="text-xs font-bold text-gray-400 uppercase mb-2">Quick Stats</h4>
                                <div className="text-sm font-bold">Plan: {selectedClient.payment.planType || 'Not Set'}</div>
                                <div className="text-xs text-gray-500 mt-1">Reg Date: {selectedClient.regDate}</div>
                            </div>
                        </>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {!selectedClient ? (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50"><UserCircleIcon className="w-20 h-20 mb-2" /><p>Select a client to manage records</p></div>
                    ) : (
                        <div className="space-y-6 max-w-5xl mx-auto">
                            {activeTab === 'overview' && (
                                <div className="flex flex-col gap-6">
                                    <Card title={paymentDescriptionTitle}>
                                        <div className="space-y-4">
                                            <div className="relative">
                                                <Input label="Land Purchase Price" type="number" value={landPrice} onChange={e => setLandPrice(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                            </div>

                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                <div className="relative">
                                                    <Input label="Discount (Optional)" type="number" value={discountValue} onChange={e => setDiscountValue(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" placeholder="0.00" />
                                                    {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                                </div>
                                                <div className="flex flex-col">
                                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Discount Mode</label>
                                                    <div className="flex h-[38px] bg-gray-100 dark:bg-gray-900 p-1 rounded-md border border-gray-300 dark:border-gray-700">
                                                        <button type="button" disabled={isFieldReadOnly} onClick={() => setDiscountType('percentage')} className={`flex-1 text-xs font-bold rounded transition-all ${discountType === 'percentage' ? 'bg-white dark:bg-gray-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Percentage (%)</button>
                                                        <button type="button" disabled={isFieldReadOnly} onClick={() => setDiscountType('fixed')} className={`flex-1 text-xs font-bold rounded transition-all ${discountType === 'fixed' ? 'bg-white dark:bg-gray-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Fixed (GHC)</button>
