                                            <div className="relative">
                                                <Input label="Indenture Price" type="number" value={indenturePrice} onChange={e => setIndenturePrice(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
