                                                <Select label="Payment Plan" value={paymentOption} onChange={e => setPaymentOption(e.target.value)} disabled={isFieldReadOnly}>
                                                    <option value="Outright">Outright Payment</option>
                                                    <option value="3">3 Months</option>
                                                    <option value="6">6 Months</option>
