                                            {roles && roles.find(r => r.id === currentStaff?.roleId)?.name === 'Administrator' && (
                                                <Button size="sm" className="mt-2" disabled={selectedClient.payment.paid / (parseFloat(landPrice) || 1) < 0.7}>Allocate Plot Now</Button>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            )}

                            {activeTab === 'history' && (
                                <div className="space-y-6">
                                    <FinancialSummaryCard />

                                    <Card title="Payment Ledger (Installment Schedule vs Actuals)" className="p-0 overflow-hidden">
                                        <div className="overflow-x-auto">
                                            <table className="w-full text-sm text-left">
                                                <thead className="text-xs uppercase bg-gray-50 dark:bg-gray-700">
                                                    <tr>
                                                        <th className="px-4 py-3">Slot</th>
                                                        <th className="px-4 py-3 bg-indigo-50/30 dark:bg-indigo-900/10">Expected Date</th>
                                                        <th className="px-4 py-3">Actual Date</th>
                                                        <th className="px-4 py-3 bg-indigo-50/30 dark:bg-indigo-900/10 text-right">Expected Amount</th>
                                                        <th className="px-4 py-3 text-right">Actual Paid</th>
                                                        <th className="px-4 py-3">Receipt</th>
                                                        <th className="px-4 py-3 text-center">Status</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-gray-100 dark:divide-gray-600">
                                                    {installmentSchedule.length > 0 ? (
                                                        installmentSchedule.map((slot) => (
                                                            <tr key={slot.index} className="hover:bg-gray-50 dark:hover:bg-gray-700/30">
                                                                <td className="px-4 py-3 font-bold text-gray-400">#{slot.index}</td>
                                                                <td className="px-4 py-3 bg-indigo-50/30 dark:bg-indigo-900/10 font-mono text-xs">{slot.expectedDate}</td>
                                                                <td className="px-4 py-3 font-mono text-xs">{slot.actualDate || '---'}</td>
                                                                <td className="px-4 py-3 bg-indigo-50/30 dark:bg-indigo-900/10 text-right font-medium">{formatCurrency(slot.expectedAmount)}</td>
                                                                <td className={`px-4 py-3 text-right font-bold ${slot.actualAmount ? 'text-green-600' : 'text-gray-300'}`}>{slot.actualAmount ? formatCurrency(slot.actualAmount) : '---'}</td>
                                                                <td className="px-4 py-3 font-mono text-[10px] text-indigo-500 uppercase">{slot.receipt || '---'}</td>
                                                                <td className="px-4 py-3 text-center">{getStatusBadge(slot.status)}</td>
                                                            </tr>
                                                        ))
                                                    ) : (
                                                        selectedClient.payment.paymentHistory.map((p: any, idx: number) => (
                                                            <tr key={p.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30">
                                                                <td className="px-4 py-3 font-bold text-gray-400">TXN</td>
                                                                <td className="px-4 py-3 bg-indigo-50/30 dark:bg-indigo-900/10 font-mono text-xs">---</td>
                                                                <td className="px-4 py-3 font-mono text-xs">{p.date}</td>
                                                                <td className="px-4 py-3 bg-indigo-50/30 dark:bg-indigo-900/10 text-right">---</td>
                                                                <td className="px-4 py-3 text-right font-bold text-green-600">{formatCurrency(p.amount)}</td>
                                                                <td className="px-4 py-3 font-mono text-[10px] text-indigo-500 uppercase">{p.receiptNumber}</td>
                                                                <td className="px-4 py-3 text-center">{getStatusBadge('Paid')}</td>
                                                            </tr>
                                                        ))
                                                    )}
                                                    {selectedClient.payment.paymentHistory.length === 0 && installmentSchedule.length === 0 && (
                                                        <tr><td colSpan={7} className="p-8 text-center text-gray-400">No payment history or plan available.</td></tr>
                                                    )}
                                                </tbody>
                                            </table>
                                        </div>
                                    </Card>
                                </div>
                            )}

                            {activeTab === 'commission' && commissionData && (
                                <Card title="Commission Tracking & Metrics">
                                    <div className="mb-8">
                                        <div className="p-4 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg border border-indigo-100 dark:border-indigo-800">
                                            <h4 className="text-xs font-bold text-indigo-700 dark:text-indigo-300 uppercase mb-4">Commission Details</h4>
                                            <InfoRow label="Assigned Representative" value={selectedClient.officeUse.salesRep} />
                                            <InfoRow label="Realized Commission" value={<span className="text-green-600">{formatCurrency(commissionData.paid)}</span>} />
                                            <InfoRow label="Remaining Payable" value={<span className="text-red-600">{formatCurrency(commissionData.due)}</span>} />
                                            <div className="mt-4 flex justify-between items-center">
                                                <span className="text-xs font-bold text-gray-500">SETTLEMENT STATUS</span>
                                                {getStatusBadge(commissionData.status)}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex gap-3">
                                        <Button 
                                            variant="success" 
                                            className="flex-1"
                                            disabled={commissionData.due <= 0} 
                                            onClick={() => {
                                                // Pre-fill modal with remaining commission balance
                                                setPaymentModalOpen(true);
                                            }}
                                            icon={<CurrencyDollarIcon className="w-5 h-5"/>}
                                        >
                                            Record Commission Payment
                                        </Button>
                                    </div>

                                    {/* Detailed Commission History */}
                                    <div className="mt-8 border-t pt-6">
                                        <h4 className="text-sm font-bold text-gray-800 dark:text-white mb-4">Commission Payment History</h4>
                                        <div className="overflow-x-auto">
                                            <table className="w-full text-xs text-left">
                                                <thead className="bg-gray-50 dark:bg-gray-700 text-gray-500">
                                                    <tr>
                                                        <th className="px-4 py-2">Date</th>
                                                        <th className="px-4 py-2">Amount</th>
                                                        <th className="px-4 py-2">Receipt</th>
                                                        <th className="px-4 py-2">Method</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
                                                    {selectedClient.payment.paymentHistory.filter((p:any) => p.type === 'Commission').map((p: any) => (
                                                        <tr key={p.id}>
                                                            <td className="px-4 py-2">{p.date}</td>
                                                            <td className="px-4 py-2 font-bold text-green-600">{formatCurrency(p.amount)}</td>
                                                            <td className="px-4 py-2 font-mono">{p.receiptNumber}</td>
                                                            <td className="px-4 py-2">{p.method}</td>
                                                        </tr>
                                                    ))}
                                                    {selectedClient.payment.paymentHistory.filter((p:any) => p.type === 'Commission').length === 0 && (
                                                        <tr><td colSpan={4} className="p-4 text-center text-gray-400 italic">No commission payments recorded yet.</td></tr>
                                                    )}
                                                </tbody>
                                            </table>
                                        </div>
                                    </div>
                                </Card>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {selectedClient && (
                <RecordPaymentModal 
                    isOpen={isPaymentModalOpen} 
                    onClose={() => setPaymentModalOpen(false)} 
                    onSave={(p) => onRecordPayment(selectedClient, p)} 
                    client={selectedClient}
                />
            )}

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            {showSuccessModal && (
                <div className="fixed inset-0 bg-slate-900/50 z-[100] flex justify-center items-center p-4 backdrop-blur-sm">
                    <Card className="w-full max-w-xs p-6 text-center animate-in zoom-in duration-200">
                        <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <CheckCircleIcon className="w-6 h-6 text-green-600" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">New Record saved</h3>
                        <Button onClick={() => setShowSuccessModal(false)} className="w-full">OK</Button>
                    </Card>
                </div>
            )}

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 6px; height: 6px; }
                .scrollbar-thin::-webkit-scrollbar-track { background: transparent; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
                .no-spinner::-webkit-outer-spin-button, .no-spinner::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
                .no-spinner[type=number] { -moz-appearance: textfield; }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, ReceiptPattern, ReceiptAlert, Staff, Role } from '../types';
import { 
    FunnelIcon, 
    MagnifyingGlassIcon, 
    DocumentPlusIcon, 
    PencilIcon,
    XCircleIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { FinancialRecordEditor } from '../components/FinancialRecordEditor';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: ReceiptPattern | null;
  setReceiptPattern: React.Dispatch<React.SetStateAction<ReceiptPattern | null>>;
  setReceiptAlerts: React.Dispatch<React.SetStateAction<ReceiptAlert[]>>;
  currentStaff: Staff;
  roles: Role[];
}

const getPaymentStatusBadge = (client: Client | undefined) => {
  if (!client) return <Badge variant="neutral">Unknown</Badge>;

  const balance = client.payment.balance;

  // Strict standardization as per requirements
  if (balance === 0) return <Badge variant="success">Fully Paid</Badge>;
  if (balance > 0) return <Badge variant="danger">Owing</Badge>;
  return <Badge variant="purple">Overpaid</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ invoices, clients, onSaveClient, onSaveInvoice, clientForInvoice, setClientForInvoice, currentStaff, roles }) => {
  const [viewMode, setViewMode] = useState<'list' | 'editor'>('list');
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  // Filter States
  const [filterName, setFilterName] = useState('');
  const [filterLocation, setFilterLocation] = useState('');
  const [filterStatus, setFilterStatus] = useState<'All' | 'Fully Paid' | 'Owing' | 'Overpaid'>('All');

  useEffect(() => {
    if (clientForInvoice) {
        setEditingInvoice(null);
        setViewMode('editor');
    }
  }, [clientForInvoice]);

  const handleCreateInvoice = () => {
    setEditingInvoice(null);
    setClientForInvoice(null);
    setViewMode('editor');
  };

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setClientForInvoice(null);
    setViewMode('editor');
  };

  const handleNavigateToClientFinancials = (clientId: number) => {
    const client = clients.find(c => c.id === clientId);
    if (client) {
      setClientForInvoice(client);
      setEditingInvoice(null);
      setViewMode('editor');
    }
  };

  const handleBack = () => {
      setViewMode('list');
      setEditingInvoice(null);
      if (clientForInvoice) {
          setClientForInvoice(null);
      }
  };

  const handleSaveInvoice = async (invoiceToSave: Invoice, updatedClientData?: Client) => {
    if (updatedClientData) {
        const hasInvoice = invoices.some(inv => inv.clientId === updatedClientData!.id) || invoiceToSave.amount > 0;
        updatedClientData.isComplete = true && hasInvoice;
        await onSaveClient(updatedClientData);
    }

    if (invoiceToSave.amount > 0 || editingInvoice) {
        await onSaveInvoice(invoiceToSave);
    }

    handleBack();
  };

  const handleRecordPayment = async (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => {
    const newTransaction: PaymentTransaction = { ...paymentData, id: `TXN-${Date.now()}`, status: 'Success' };

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            // Only 'Land' payments affect the main land balance
            paid: paymentData.type === 'Land' ? client.payment.paid + newTransaction.amount : client.payment.paid,
            balance: paymentData.type === 'Land' ? client.payment.balance - newTransaction.amount : client.payment.balance,
            // Update indenture specific fields if applicable
            ...(paymentData.type === 'Indenture' && {
              indenturePaid: ((client.payment as any).indenturePaid || 0) + newTransaction.amount,
              indentureBalance: ((client.payment as any).indentureBalance || 0) - newTransaction.amount,
            })
        }
    } as Client;

    // Handle Commission Type updates
    if (paymentData.type === 'Commission') {
        const commTarget = client.officeUse.commission.amount;
        const totalCommPaid = updatedClient.payment.paymentHistory
            .filter((p: any) => p.type === 'Commission')
            .reduce((sum, p) => sum + p.amount, 0);

        updatedClient.officeUse.commission = {
            ...client.officeUse.commission,
            status: totalCommPaid >= commTarget ? 'Paid' : 'Pending',
            paymentDate: totalCommPaid >= commTarget ? new Date().toISOString() : client.officeUse.commission.paymentDate
        };
    }

    await onSaveClient(updatedClient);
  };

  const clearFilters = () => {
    setFilterName('');
    setFilterLocation('');
    setFilterStatus('All');
  };

  const filteredInvoices = useMemo(() => {
    return invoices.filter(invoice => {
      const client = clients.find(c => c.id === invoice.clientId);
      const clientLocation = client?.location || 'N/A';

      let paymentStatus = 'Unknown';
      if (client) {
          const bal = client.payment.balance;
          if (bal === 0) paymentStatus = 'Fully Paid';
          else if (bal > 0) paymentStatus = 'Owing';
          else paymentStatus = 'Overpaid';
      }

      const matchesName = invoice.clientName.toLowerCase().includes(filterName.toLowerCase());
      const matchesLocation = clientLocation.toLowerCase().includes(filterLocation.toLowerCase());
      const matchesStatus = filterStatus === 'All' || paymentStatus === filterStatus;

      return matchesName && matchesLocation && matchesStatus;
    });
  }, [invoices, clients, filterName, filterLocation, filterStatus]);

  if (viewMode === 'editor') {
      return (
        <FinancialRecordEditor 
            onBack={handleBack}
            clients={clients}
            onSave={handleSaveInvoice}
            onRecordPayment={handleRecordPayment}
            editingInvoice={editingInvoice}
            clientForInvoice={clientForInvoice}
            roles={roles}
        />
      );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Track invoices, payments, and client account statuses.</p>
        </div>
        <Button onClick={handleCreateInvoice} icon={<DocumentPlusIcon className="w-5 h-5" />}>
            Create Financial Record
        </Button>
      </div>

      {/* Advanced Filter Control */}
      <Card title="List Filters" className="p-0 overflow-hidden">
        <div className="p-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 bg-gray-50 dark:bg-gray-900/50">
          <div className="relative">
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Client Name</label>
            <div className="relative">
              <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                value={filterName}
                onChange={(e) => setFilterName(e.target.value)}
                placeholder="Search name..."
                className="pl-9 block w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-md text-sm text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Location</label>
            <input
              type="text"
              value={filterLocation}
              onChange={(e) => setFilterLocation(e.target.value)}
              placeholder="Filter location..."
              className="block w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-md text-sm text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Payment Status</label>
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as any)}
              className="block w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-md text-sm text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
            >
              <option value="All">All Statuses</option>
              <option value="Fully Paid">Fully Paid</option>
              <option value="Owing">Owing</option>
              <option value="Overpaid">Overpaid</option>
            </select>
          </div>

          <div className="flex items-end">
            <Button 
              variant="secondary" 
              className="w-full h-[38px] gap-2" 
              onClick={clearFilters}
              icon={<XCircleIcon className="w-4 h-4" />}
            >
              Reset
            </Button>
          </div>
        </div>
      </Card>

      <TableContainer>
        <table className="w-full text-sm text-left text-gray-500 dark:text-gray-400">
            <Thead>
                <tr>
                    <Th>Client</Th>
                    <Th>Amount</Th>
                    <Th>Plot Location</Th>
                    <Th>Due Date</Th>
                    <Th className="text-center">Status</Th>
                    <Th className="text-center">Actions</Th>
                </tr>
            </Thead>
            <Tbody>
                {filteredInvoices.map(invoice => {
                    const client = clients.find(c => c.id === invoice.clientId);
                    const clientLocation = client?.location || 'N/A';
                    return (
                        <Tr key={invoice.id}>
                            <Td className="whitespace-nowrap">
                              <button 
                                onClick={() => handleNavigateToClientFinancials(invoice.clientId)}
                                className="font-bold text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 transition-colors underline decoration-indigo-300 underline-offset-4"
                              >
                                {invoice.clientName}
                              </button>
                            </Td>
                            <Td className="font-semibold text-gray-700 dark:text-gray-200">{formatCurrency(invoice.amount)}</Td>
                            <Td>{clientLocation}</Td>
                            <Td>{invoice.dueDate}</Td>
                            <Td className="text-center">
                              {getPaymentStatusBadge(client)}
                            </Td>
                            <Td className="text-center">
                                <button onClick={() => handleEditInvoice(invoice)} className="text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400 p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700">
                                    <PencilIcon className="w-5 h-5" />
                                </button>
                            </Td>
                        </Tr>
                    );
                })}
            </Tbody>
        </table>
        {filteredInvoices.length === 0 && (
            <div className="text-center py-10">
                <p className="text-gray-500 dark:text-gray-400">No matching records found.</p>
            </div>
        )}
      </TableContainer>
    </div>
  );
};

export default AccountManagementPage;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, Invoice, PaymentTransaction, Installment, Staff, Role } from '../types';
import { 
    BanknotesIcon,
    ChevronRightIcon,
    ArrowLeftIcon,
    LockClosedIcon,
    PencilSquareIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    ClockIcon,
    CheckCircleIcon,
    ExclamationTriangleIcon,
    UserCircleIcon,
    CurrencyDollarIcon
} from './icons/DummyIcons';
import { XIcon } from './icons/XIcon';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Input, Select } from './ui/Input';
import { Badge } from './ui/Badge';
import { useAuth } from '../context/AuthContext';

const getStatusBadge = (status: string) => {
  let variant: 'success' | 'warning' | 'danger' | 'neutral' | 'purple' = 'neutral';
  switch (status) {
    case 'Paid': case 'Success': case 'On Time': case 'Fully Paid': variant = 'success'; break;
    case 'Pending': variant = 'warning'; break;
    case 'Overdue': case 'Failed': case 'Late': case 'Owing': variant = 'danger'; break;
    case 'Expected': case 'Overpaid': variant = 'purple'; break;
  }
  return <Badge variant={variant}>{status}</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

/**
 * Re-authentication Modal for Amendments
 */
const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Verify Identity</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Re-authenticate to unlock financial fields.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Staff Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="email@faim.com" />
                        <Input label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const RecordPaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSave: (payment: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    client: Client;
}> = ({ isOpen, onClose, onSave, client }) => {
    const [amount, setAmount] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>('Land');
    const [reference, setReference] = useState('');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            setAmount('');
            setDate(new Date().toISOString().split('T')[0]);
            setError('');
        }
    }, [isOpen]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const paidAmount = parseFloat(amount);
        if (isNaN(paidAmount) || paidAmount <= 0) {
            setError('Please enter a valid positive amount.');
            return;
        }

        let balance = 0;
        if (type === 'Land') balance = client.payment.balance;
        else if (type === 'Indenture') balance = (client.payment as any).indentureBalance || 0;
        else if (type === 'Commission') {
            const commTarget = client.officeUse.commission.amount;
            const commPaid = client.payment.paymentHistory
                .filter((p: any) => p.type === 'Commission')
                .reduce((sum, p) => sum + p.amount, 0);
            balance = commTarget - commPaid;
        }

        if (paidAmount > balance && balance > 0) {
            setError(`Amount cannot exceed the current ${type} balance.`);
            return;
        }

        if (!receiptNumber.trim()) {
            setError('Receipt number is required.');
            return;
        }
        onSave({ date, amount: paidAmount, method, reference, receiptNumber, type });
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-md p-0 overflow-hidden">
                <form onSubmit={handleSubmit}>
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700">
                        <h2 className="text-lg font-bold text-gray-800 dark:text-white">Record {type} Payment</h2>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XIcon className="w-6 h-6" /></button>
                    </div>
                    <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
                        {error && <div className="bg-red-50 text-red-700 p-3 rounded-md text-xs border border-red-200">{error}</div>}
                        <Select label="Payment Type*" value={type} onChange={e => setType(e.target.value as any)}>
                            <option value="Land">Land Purchase</option>
                            <option value="Indenture">Indenture/Documentation</option>
                            <option value="Commission">Commission Payment</option>
                        </Select>
                        <Input label="Payment Date*" type="date" value={date} onChange={e => setDate(e.target.value)} required />
                        <Input label="Amount Paid*" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" required className="no-spinner" />
                        <Input label="Receipt Number*" value={receiptNumber} onChange={e => setReceiptNumber(e.target.value)} required />
                        <Select label="Payment Method*" value={method} onChange={e => setMethod(e.target.value as any)}>
                            <option>Bank Transfer</option><option>Cash</option><option>MoMo</option><option>Cheque</option><option>Other</option>
                        </Select>
                    </div>
                    <div className="flex justify-end p-4 border-t border-gray-200 bg-gray-50 gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit">Save Payment</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const dropdownRef = useRef<HTMLDivElement>(null);
    const [selectedClientId, setSelectedClientId] = useState<number | null>(fixedClient ? fixedClient.id : null);
    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    // Financial State (Live UI State)
    const [landPrice, setLandPrice] = useState('0');
    const [indenturePrice, setIndenturePrice] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [discountValue, setDiscountValue] = useState('0');
    const [paymentOption, setPaymentOption] = useState('Outright');
    const [otherMonths, setOtherMonths] = useState('');
    const [calculatedTotal, setCalculatedTotal] = useState<number | null>(null);

    // Derive initialization state
    const isInitialized = !!selectedClient?.payment?.isInitialized;
    const canAmend = useMemo(() => {
        if (!roles || !currentStaff) return false;
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'Accountant' || roleName === 'Chief Accountant';
    }, [currentStaff, roles]);

    // Installment Schedule Logic
    const installmentSchedule = useMemo(() => {
        if (!selectedClient || paymentOption === 'Outright') return [];

        const count = paymentOption === 'Other' ? parseInt(otherMonths) || 0 : parseInt(paymentOption) || 0;
        if (count <= 0) return [];

        const basePrice = calculatedTotal || parseFloat(landPrice) || 0;
        const monthlyAmount = basePrice / count;
        const regDate = new Date(selectedClient.regDate);

        const landPayments = selectedClient.payment.paymentHistory.filter((p: any) => p.type === 'Land' || !p.type);

        return Array.from({ length: count }).map((_, i) => {
            const dueDate = new Date(regDate);
            dueDate.setMonth(dueDate.getMonth() + (i + 1));
            const actual = landPayments[i];

            return {
                index: i + 1,
                expectedDate: dueDate.toISOString().split('T')[0],
                expectedAmount: monthlyAmount,
                actualDate: actual?.date,
                actualAmount: actual?.amount,
                receipt: actual?.receiptNumber,
                status: actual ? 'Paid' : (new Date() > dueDate ? 'Overdue' : 'Pending')
            };
        });
    }, [selectedClient, paymentOption, otherMonths, landPrice, calculatedTotal]);

    // Outside Click Listener for Dropdown
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsClientDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setIndenturePrice(String((selectedClient.payment as any).indenturePrice || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
            setDiscountValue(String((selectedClient.payment as any).discountValue || '0'));
            setDiscountType((selectedClient.payment as any).discountType || 'percentage');
        }
    }, [selectedClient]);

    useEffect(() => {
        if (!selectedClient) return;
        const P_initial = parseFloat(landPrice) || 0;
        const D = parseFloat(discountValue) || 0;

        let P = P_initial;
        if (discountType === 'percentage') {
            P = P_initial * (1 - (D / 100));
        } else {
            P = Math.max(0, P_initial - D);
        }

        const ANNUAL_RATE = 0.10;
        const r = ANNUAL_RATE / 12;
        let n = 0;
        if (paymentOption === '3') n = 3;
        else if (paymentOption === '6') n = 6;
        else if (paymentOption === 'Other' && otherMonths) n = parseInt(otherMonths, 10);

        if (n > 0 && paymentOption !== 'Outright') {
            const emi = (P * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
            setCalculatedTotal(emi * n);
        } else {
            setCalculatedTotal(P);
        }
    }, [paymentOption, otherMonths, landPrice, selectedClient, discountType, discountValue]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient || isSaving) return;

        setIsSaving(true);
        const finalLandPrice = calculatedTotal || parseFloat(landPrice) || 0;
        const finalIndenturePrice = parseFloat(indenturePrice) || 0;

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: finalLandPrice,
                balance: finalLandPrice - selectedClient.payment.paid,
                indenturePrice: finalIndenturePrice,
                indentureBalance: finalIndenturePrice - ((selectedClient.payment as any).indenturePaid || 0),
                discountValue: parseFloat(discountValue) || 0,
                discountType: discountType,
                planType: paymentOption === 'Outright' ? 'Outright Payment' : `${paymentOption}-Month Installment`,
                amendmentHistory: isInitialized ? [
                    ...(selectedClient.payment as any).amendmentHistory || [],
                    {
                        timestamp: new Date().toISOString(),
                        amendedBy: currentStaff?.fullName,
                        role: roles.find(r => r.id === currentStaff?.roleId)?.name,
                        changes: "Financial field amendment"
                    }
                ] : []
            }
        } as Client;

        try {
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
            setShowSuccessModal(true);
        } finally {
            setIsSaving(false);
        }
    };

    const handleCommissionPaid = () => {
        if (!selectedClient) return;
        const commAmount = selectedClient.officeUse.commission.amount;

        const updatedClient = {
            ...selectedClient,
            officeUse: {
                ...selectedClient.officeUse,
                commission: { ...selectedClient.officeUse.commission, status: 'Paid', paymentDate: new Date().toISOString() }
            },
            payment: {
                ...selectedClient.payment,
                commissionHistory: [
                    ...(selectedClient.payment as any).commissionHistory || [],
                    { date: new Date().toISOString(), amount: commAmount, status: 'Paid' }
                ]
            }
        } as Client;
        onSave({ id: `COMM-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
    };

    const InfoRow = ({ label, value, isLarge = false }: any) => (
        <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700 last:border-b-0">
            <dt className="text-sm text-gray-500 dark:text-gray-400">{label}</dt>
            <dd className={`text-sm font-semibold text-gray-800 dark:text-gray-200 ${isLarge ? 'text-xl' : ''}`}>{value}</dd>
        </div>
    );

    const isFieldReadOnly = isInitialized && !isUnlocked;

    const paymentDescriptionTitle = (
        <div className="flex items-center gap-2">
            <span>Payment Description</span>
            {isInitialized && (
                <div 
                    className="w-2.5 h-2.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)] animate-pulse" 
                    title="Account initialized"
                ></div>
            )}
        </div>
    );

    const getStandardizedStatusLabel = (balance: number) => {
        if (balance === 0) return 'Fully Paid';
        if (balance > 0) return 'Owing';
        return 'Overpaid';
    };

    const FinancialSummaryCard = () => {
        const balance = selectedClient?.payment.balance || 0;
        const statusLabel = getStandardizedStatusLabel(balance);

        return (
            <Card 
                title={
                    <div className="flex items-center gap-3">
                        <span>Live Financial Summary</span>
                        {getStatusBadge(statusLabel)}
                    </div>
                } 
                className="bg-gray-50 dark:bg-gray-900 border-gray-200 w-full"
            >
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <div>
                        <h4 className="text-xs font-bold text-gray-400 uppercase mb-3">Land Purchase</h4>
                        <InfoRow label="Price" value={formatCurrency(selectedClient?.payment.total || 0)} />
                        <InfoRow label="Actual Paid" value={<span className="text-green-600 font-bold">{formatCurrency(selectedClient?.payment.paid || 0)}</span>} />
                        <InfoRow label="Current Balance" value={<span className={balance > 0 ? "text-red-600 font-bold" : "text-purple-600 font-bold"}>{formatCurrency(balance)}</span>} />
                    </div>
                    <div>
                        <h4 className="text-xs font-bold text-gray-400 uppercase mb-3">Indenture & Fees</h4>
                        <InfoRow label="Price" value={formatCurrency((selectedClient?.payment as any).indenturePrice || 0)} />
                        <InfoRow label="Actual Paid" value={<span className="text-green-600 font-bold">{formatCurrency((selectedClient?.payment as any).indenturePaid || 0)}</span>} />
                        <InfoRow label="Current Balance" value={<span className="text-red-600 font-bold">{formatCurrency((selectedClient?.payment as any).indentureBalance || 0)}</span>} />
                    </div>
                    <div className="bg-indigo-50 dark:bg-indigo-900/20 p-4 rounded-lg flex flex-col justify-center">
                        <div className="text-xs text-indigo-600 dark:text-indigo-400 font-bold uppercase mb-1">Total Realized Revenue</div>
                        <div className="text-2xl font-black text-gray-900 dark:text-white">
                            {formatCurrency((selectedClient?.payment.paid || 0) + ((selectedClient?.payment as any).indenturePaid || 0))}
                        </div>
                        <div className="mt-2 text-[10px] text-gray-500">Includes all confirmed transactions.</div>
                    </div>
                </div>
            </Card>
        );
    };

    // Dynamic Commission Logic
    const commissionData = useMemo(() => {
        if (!selectedClient) return null;
        const totalLandPrice = selectedClient.payment.total || 1; // prevent div by zero
        const commTargetAmount = selectedClient.officeUse.commission.amount;

        // Sum of all payments typed 'Commission'
        const commPaid = selectedClient.payment.paymentHistory
            .filter((p: any) => p.type === 'Commission')
            .reduce((sum, p) => sum + p.amount, 0);

        const commDue = Math.max(0, commTargetAmount - commPaid);

        return {
            target: commTargetAmount,
            paid: commPaid,
            due: commDue,
            pctPaid: ((commPaid / totalLandPrice) * 100).toFixed(2),
            pctDue: ((commDue / totalLandPrice) * 100).toFixed(2),
            status: commDue <= 0 ? 'Paid' : 'Owing'
        };
    }, [selectedClient]);

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white">Create & View Financials</h2>
                        {isInitialized && <Badge variant="success" className="ml-2">Account Initialized</Badge>}
                    </div>
                </div>
                <div className="flex gap-2">
                    {isInitialized && !isUnlocked && canAmend && (
                        <Button variant="secondary" icon={<PencilSquareIcon className="w-4 h-4"/>} onClick={() => setAuthModalOpen(true)}>Amend</Button>
                    )}
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-4 space-y-4 overflow-y-auto scrollbar-thin">
                    {!fixedClient && (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Client</label>
                            <button
                                type="button"
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className={`flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer hover:border-gray-400 dark:hover:border-gray-500`}
                            >
                                <span className="truncate">{selectedClient ? selectedClient.name : '-- Select a client --'}</span>
                                <ChevronDownIcon className={`w-4 h-4 text-gray-400 transition-transform pointer-events-none ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                            </button>

                            {isClientDropdownOpen && (
                                <div className="absolute left-0 right-0 mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-xl z-50 max-h-60 overflow-y-auto scrollbar-thin animate-in fade-in slide-in-from-top-1">
                                    {clients.map(client => (
                                        <button
                                            key={client.id}
                                            type="button"
                                            onClick={() => {
                                                setSelectedClientId(client.id);
                                                setIsClientDropdownOpen(false);
                                            }}
                                            className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 dark:hover:bg-indigo-900/30 transition-colors border-b border-gray-50 dark:border-gray-700 last:border-0 ${selectedClientId === client.id ? 'bg-indigo-50 dark:bg-indigo-900/40 font-semibold text-indigo-700 dark:text-indigo-300' : 'text-gray-700 dark:text-gray-300'}`}
                                        >
                                            {client.name}
