import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, ReceiptPattern, ReceiptAlert, Staff, Role } from '../types';
import { 
    MagnifyingGlassIcon, 
    DocumentPlusIcon, 
    PencilIcon,
    ChartBarIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { FinancialRecordEditor } from '../components/FinancialRecordEditor';
import { FinancialReportsView } from '../components/FinancialReportsView';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: ReceiptPattern | null;
  setReceiptPattern: React.Dispatch<React.SetStateAction<ReceiptPattern | null>>;
  setReceiptAlerts: React.Dispatch<React.SetStateAction<ReceiptAlert[]>>;
  currentStaff: Staff;
  roles: Role[];
}

const getPaymentStatusBadge = (client: Client | undefined) => {
  const balance = client?.payment.balance ?? 1; 

  if (balance === 0) return <Badge variant="success">Fully Paid</Badge>;
  if (balance > 0) return <Badge variant="danger">Owing</Badge>;
  return <Badge variant="purple">Overpaid</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ invoices, clients, onSaveClient, onSaveInvoice, clientForInvoice, setClientForInvoice, currentStaff, roles }) => {
  const [viewMode, setViewMode] = useState<'list' | 'editor' | 'reports'>('list');
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  // Filter States
  const [filterName, setFilterName] = useState('');
  const [filterLocation, setFilterLocation] = useState('');
  const [filterStatus, setFilterStatus] = useState<'All' | 'Fully Paid' | 'Owing' | 'Overpaid'>('All');

  useEffect(() => {
    if (clientForInvoice) {
        setEditingInvoice(null);
        setViewMode('editor');
    }
  }, [clientForInvoice]);

  const handleCreateInvoice = () => {
    setEditingInvoice(null);
    setClientForInvoice(null);
    setViewMode('editor');
  };

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setClientForInvoice(null);
    setViewMode('editor');
  };

  const handleNavigateToClientFinancials = (clientId: number) => {
    const client = clients.find(c => c.id === clientId);
    if (client) {
      setClientForInvoice(client);
      setEditingInvoice(null);
      setViewMode('editor');
    }
  };

  const handleBack = () => {
      setViewMode('list');
      setEditingInvoice(null);
      if (clientForInvoice) {
          setClientForInvoice(null);
      }
  };

  const handleSaveInvoice = async (invoiceToSave: Invoice, updatedClientData?: Client) => {
    if (updatedClientData) {
        const hasInvoice = invoices.some(inv => inv.clientId === updatedClientData!.id) || invoiceToSave.amount > 0;
        updatedClientData.isComplete = true && hasInvoice;
        await onSaveClient(updatedClientData);
    }

    if (invoiceToSave.amount > 0 || editingInvoice) {
        await onSaveInvoice(invoiceToSave);
    }

    handleBack();
  };

  const handleRecordPayment = async (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => {
    const newTransaction: PaymentTransaction = { ...paymentData, id: `TXN-${Date.now()}`, status: 'Success' };

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: paymentData.type === 'Land' ? client.payment.paid + newTransaction.amount : client.payment.paid,
            balance: paymentData.type === 'Land' ? client.payment.balance - newTransaction.amount : client.payment.balance,
            ...(paymentData.type === 'Indenture' && {
              indenturePaid: ((client.payment as any).indenturePaid || 0) + newTransaction.amount,
              indentureBalance: ((client.payment as any).indentureBalance || 0) - newTransaction.amount,
            })
        }
    } as Client;

    if (paymentData.type === 'Commission') {
        const commTarget = client.officeUse.commission.amount;
        const totalCommPaid = updatedClient.payment.paymentHistory
            .filter((p: any) => p.type === 'Commission')
            .reduce((sum, p) => sum + p.amount, 0);

        updatedClient.officeUse.commission = {
            ...client.officeUse.commission,
            status: totalCommPaid >= commTarget ? 'Paid' : 'Pending',
            paymentDate: totalCommPaid >= commTarget ? new Date().toISOString() : client.officeUse.commission.paymentDate
        };
    }

    await onSaveClient(updatedClient);
  };

  const filteredInvoices = useMemo(() => {
    return invoices.filter(invoice => {
      const client = clients.find(c => c.id === invoice.clientId);
      const clientLocation = client?.location || 'N/A';

      let paymentStatus = 'Owing'; 
      if (client) {
          const bal = client.payment.balance;
          if (bal === 0) paymentStatus = 'Fully Paid';
          else if (bal > 0) paymentStatus = 'Owing';
          else paymentStatus = 'Overpaid';
      }

      const matchesName = invoice.clientName.toLowerCase().includes(filterName.toLowerCase());
      const matchesLocation = clientLocation.toLowerCase().includes(filterLocation.toLowerCase());
      const matchesStatus = filterStatus === 'All' || paymentStatus === filterStatus;

      return matchesName && matchesLocation && matchesStatus;
    });
  }, [invoices, clients, filterName, filterLocation, filterStatus]);

  if (viewMode === 'editor') {
      return (
        <FinancialRecordEditor 
            onBack={handleBack}
            clients={clients}
            onSave={handleSaveInvoice}
            onRecordPayment={handleRecordPayment}
            editingInvoice={editingInvoice}
            clientForInvoice={clientForInvoice}
            roles={roles}
        />
      );
  }

  if (viewMode === 'reports') {
    return (
      <FinancialReportsView 
        onBack={handleBack} 
        clients={clients}
        staffList={[]} // Placeholder if needed
      />
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Track invoices, payments, and client account statuses.</p>
        </div>
        <div className="flex gap-3">
          <Button variant="secondary" onClick={() => setViewMode('reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
              Reporting & Audits
          </Button>
          <Button onClick={handleCreateInvoice} icon={<DocumentPlusIcon className="w-5 h-5" />}>
              Create Financial Record
          </Button>
        </div>
      </div>

      <Card title="Quick Search & Filters" className="p-0 overflow-hidden">
        <div className="p-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 bg-gray-50 dark:bg-gray-900/50">
          <div className="relative">
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Search Client Name</label>
            <div className="relative">
              <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                value={filterName}
                onChange={(e) => setFilterName(e.target.value)}
                placeholder="Type name to filter..."
                className="pl-9 block w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-md text-sm text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500 transition-all shadow-sm"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Filter by Location</label>
            <input
              type="text"
              value={filterLocation}
              onChange={(e) => setFilterLocation(e.target.value)}
              placeholder="Type location..."
              className="block w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-md text-sm text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500 transition-all shadow-sm"
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Payment Status</label>
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as any)}
              className="block w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-md text-sm text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500 transition-all shadow-sm"
            >
              <option value="All">All Statuses</option>
              <option value="Fully Paid">Fully Paid</option>
              <option value="Owing">Owing</option>
              <option value="Overpaid">Overpaid</option>
            </select>
          </div>
        </div>
      </Card>

      <TableContainer>
        <table className="w-full text-sm text-left text-gray-500 dark:text-gray-400">
            <Thead>
                <tr>
                    <Th>Client</Th>
                    <Th>Amount</Th>
                    <Th>Plot Location</Th>
                    <Th>Due Date</Th>
                    <Th className="text-center">Status</Th>
                    <Th className="text-center">Actions</Th>
                </tr>
            </Thead>
            <Tbody>
                {filteredInvoices.map(invoice => {
                    const client = clients.find(c => c.id === invoice.clientId);
                    const clientLocation = client?.location || 'N/A';
                    return (
                        <Tr key={invoice.id}>
                            <Td className="whitespace-nowrap">
                              <button 
                                onClick={() => handleNavigateToClientFinancials(invoice.clientId)}
                                className="font-bold text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 transition-colors underline decoration-indigo-300 underline-offset-4"
                              >
                                {invoice.clientName}
                              </button>
                            </Td>
                            <Td className="font-semibold text-gray-700 dark:text-gray-200">{formatCurrency(invoice.amount)}</Td>
                            <Td>{clientLocation}</Td>
                            <Td>{invoice.dueDate}</Td>
                            <Td className="text-center">
                              {getPaymentStatusBadge(client)}
                            </Td>
                            <Td className="text-center">
                                <button onClick={() => handleEditInvoice(invoice)} className="text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400 p-1 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700">
                                    <PencilIcon className="w-5 h-5" />
                                </button>
                            </Td>
                        </Tr>
                    );
                })}
            </Tbody>
        </table>
        {filteredInvoices.length === 0 && (
            <div className="text-center py-10">
                <p className="text-gray-500 dark:text-gray-400">No matching records found with current filters.</p>
            </div>
        )}
      </TableContainer>
    </div>
  );
};

