import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role } from '../types';
import { 
    BanknotesIcon,
    ArrowLeftIcon,
    LockClosedIcon,
    PencilSquareIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    CheckCircleIcon,
    ExclamationTriangleIcon,
    UserCircleIcon,
    CurrencyDollarIcon,
    ClockIcon
} from './icons/DummyIcons';
import { XIcon } from './icons/XIcon';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Input, Select } from './ui/Input';
import { Badge } from './ui/Badge';
import { useAuth } from '../context/AuthContext';

const getStatusBadge = (status: string) => {
  let variant: 'success' | 'warning' | 'danger' | 'neutral' | 'purple' = 'neutral';
  switch (status) {
    case 'Paid': case 'Success': case 'On Time': case 'Fully Paid': variant = 'success'; break;
    case 'Pending': variant = 'warning'; break;
    case 'Overdue': case 'Failed': case 'Late': case 'Owing': variant = 'danger'; break;
    case 'Expected': case 'Overpaid': variant = 'purple'; break;
  }
  return <Badge variant={variant}>{status}</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

/**
 * Re-authentication Modal for Amendments with mandatory Reason
 */
const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: (reason: string) => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login, currentStaff } = useAuth();
    const [password, setPassword] = useState('');
    const [reason, setReason] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!reason.trim() || reason.length < 10) {
            setError('Please provide a detailed reason (min 10 chars).');
            return;
        }
        setLoading(true);
        setError('');

        const res = await login(currentStaff?.email || '', password);
        if (res.success) {
            onSuccess(reason);
            setReason('');
            setPassword('');
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-amber-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700 bg-amber-50 dark:bg-amber-900/10">
                        <div className="w-12 h-12 bg-amber-100 dark:bg-amber-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-amber-600 dark:text-amber-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Authorize Amendment</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Verify credentials and state reason for manual modification.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Verify Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required placeholder="••••••••" />
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Reason for Change*</label>
                            <textarea 
                                value={reason} 
                                onChange={e => setReason(e.target.value)} 
                                required
                                rows={3}
                                className="block w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md text-sm text-gray-900 dark:text-white focus:ring-amber-500 focus:border-amber-500"
                                placeholder="E.g., Incorrect initial land price entry..."
                            />
                        </div>
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1 bg-amber-600 hover:bg-amber-700 border-none" isLoading={loading}>Log & Authorize</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const RecordPaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSave: (payment: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    client: Client;
}> = ({ isOpen, onClose, onSave, client }) => {
    const [amount, setAmount] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>('Land');
    const [reference, setReference] = useState('');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            setAmount('');
            setDate(new Date().toISOString().split('T')[0]);
            setError('');
        }
    }, [isOpen]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const paidAmount = parseFloat(amount);
        if (isNaN(paidAmount) || paidAmount <= 0) {
            setError('Please enter a valid positive amount.');
            return;
        }

        let balance = 0;
        if (type === 'Land') balance = client.payment.balance;
        else if (type === 'Indenture') balance = (client.payment as any).indentureBalance || 0;
        else if (type === 'Commission') {
            const commTarget = client.officeUse.commission.amount;
            const commPaid = client.payment.paymentHistory
                .filter((p: any) => p.type === 'Commission')
                .reduce((sum, p) => sum + p.amount, 0);
            balance = commTarget - commPaid;
        }

        if (paidAmount > balance && balance > 0) {
            setError(`Amount cannot exceed the current ${type} balance.`);
            return;
        }

        if (!receiptNumber.trim()) {
            setError('Receipt number is required.');
            return;
        }
        onSave({ date, amount: paidAmount, method, reference, receiptNumber, type });
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-md p-0 overflow-hidden">
                <form onSubmit={handleSubmit}>
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700">
                        <h2 className="text-lg font-bold text-gray-800 dark:text-white">Record {type} Payment</h2>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XIcon className="w-6 h-6" /></button>
                    </div>
                    <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
                        {error && <div className="bg-red-50 text-red-700 p-3 rounded-md text-xs border border-red-200">{error}</div>}
                        <Select label="Payment Type*" value={type} onChange={e => setType(e.target.value as any)}>
                            <option value="Land">Land Purchase</option>
                            <option value="Indenture">Indenture/Documentation</option>
                            <option value="Commission">Commission Payment</option>
                        </Select>
                        <Input label="Payment Date*" type="date" value={date} onChange={e => setDate(e.target.value)} required />
                        <Input label="Amount Paid*" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" required className="no-spinner" />
                        <Input label="Receipt Number*" value={receiptNumber} onChange={e => setReceiptNumber(e.target.value)} required />
                        <Select label="Payment Method*" value={method} onChange={e => setMethod(e.target.value as any)}>
                            <option>Bank Transfer</option><option>Cash</option><option>MoMo</option><option>Cheque</option><option>Other</option>
                        </Select>
                    </div>
                    <div className="flex justify-end p-4 border-t border-gray-200 bg-gray-50 gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit">Save Payment</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    // Financial State
    const [landPrice, setLandPrice] = useState('0');
    const [indenturePrice, setIndenturePrice] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [discountValue, setDiscountValue] = useState('0');
    const [paymentOption, setPaymentOption] = useState('Outright');
    const [otherMonths, setOtherMonths] = useState('');
    const [calculatedTotal, setCalculatedTotal] = useState<number | null>(null);

    const isInitialized = !!selectedClient?.payment?.isInitialized;
    const canAmend = useMemo(() => {
        if (!roles || !currentStaff) return false;
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'Accountant' || roleName === 'Chief Accountant' || roleName === 'Administrator' || roleName === 'CEO';
    }, [currentStaff, roles]);

    useEffect(() => {
        if (clientForInvoice) {
            setSelectedClientId(clientForInvoice.id);
        }
    }, [clientForInvoice]);

    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setIndenturePrice(String((selectedClient.payment as any).indenturePrice || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
            setDiscountValue(String((selectedClient.payment as any).discountValue || '0'));
            setDiscountType((selectedClient.payment as any).discountType || 'percentage');
        }
    }, [selectedClient]);

    useEffect(() => {
        if (!selectedClient) return;
        const P_initial = parseFloat(landPrice) || 0;
        const D = parseFloat(discountValue) || 0;
        let P = P_initial;
        if (discountType === 'percentage') P = P_initial * (1 - (D / 100));
        else P = Math.max(0, P_initial - D);

        const ANNUAL_RATE = 0.10;
        const r = ANNUAL_RATE / 12;
        let n = 0;
        if (paymentOption === '3') n = 3;
        else if (paymentOption === '6') n = 6;
        else if (paymentOption === 'Other' && otherMonths) n = parseInt(otherMonths, 10);

        if (n > 0 && paymentOption !== 'Outright') {
            const emi = (P * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
            setCalculatedTotal(emi * n);
        } else {
            setCalculatedTotal(P);
        }
    }, [paymentOption, otherMonths, landPrice, selectedClient, discountType, discountValue]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (isInitialized && !isUnlocked) {
            setAuthModalOpen(true);
            return;
        }
        await executeFinalSave("System Initialized");
    };

    const executeFinalSave = async (authorizedReason: string) => {
        if (!selectedClient || isSaving) return;
        setIsSaving(true);

        const finalLandPrice = calculatedTotal || parseFloat(landPrice) || 0;
        const finalIndenturePrice = parseFloat(indenturePrice) || 0;

        const changesMade = [];
        if (finalLandPrice !== selectedClient.payment.total) changesMade.push(`Total Land Price: ${formatCurrency(selectedClient.payment.total)} -> ${formatCurrency(finalLandPrice)}`);
        if (finalIndenturePrice !== (selectedClient.payment as any).indenturePrice) changesMade.push(`Indenture Price: ${formatCurrency((selectedClient.payment as any).indenturePrice || 0)} -> ${formatCurrency(finalIndenturePrice)}`);

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: finalLandPrice,
                balance: finalLandPrice - selectedClient.payment.paid,
                indenturePrice: finalIndenturePrice,
                indentureBalance: finalIndenturePrice - ((selectedClient.payment as any).indenturePaid || 0),
                discountValue: parseFloat(discountValue) || 0,
                discountType: discountType,
                planType: paymentOption === 'Outright' ? 'Outright Payment' : `${paymentOption}-Month Installment`,
                amendmentHistory: [
                    ...((selectedClient.payment as any).amendmentHistory || []),
                    {
                        timestamp: new Date().toISOString(),
                        amendedBy: currentStaff?.fullName,
                        role: roles.find(r => r.id === currentStaff?.roleId)?.name,
                        changes: changesMade.length > 0 ? changesMade.join(", ") : "Initialized values",
                        reason: authorizedReason
                    }
                ]
            }
        } as Client;

        try {
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
            setShowSuccessModal(true);
        } finally {
            setIsSaving(false);
        }
    };

    const InfoRow = ({ label, value, isLarge = false }: any) => (
        <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700 last:border-b-0">
            <dt className="text-sm text-gray-500 dark:text-gray-400">{label}</dt>
            <dd className={`text-sm font-semibold text-gray-800 dark:text-white ${isLarge ? 'text-xl' : ''}`}>{value}</dd>
        </div>
    );

    const isFieldReadOnly = isInitialized && !isUnlocked;

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white">Financial Record Editor</h2>
                        {isInitialized && <Badge variant="success" className="ml-2">Account Active</Badge>}
                    </div>
                </div>
                <div className="flex gap-2">
                    {isInitialized && !isUnlocked && canAmend && (
                        <Button variant="secondary" className="border-amber-300 text-amber-700" icon={<ShieldCheckIcon className="w-4 h-4"/>} onClick={() => setAuthModalOpen(true)}>Authorized Amendment</Button>
                    )}
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-4 space-y-4 overflow-y-auto scrollbar-thin">
                    {selectedClient && (
                        <>
                            <div className="flex items-center gap-3 p-3 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg">
                                <div className="w-12 h-12 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold">{selectedClient.initials}</div>
                                <div>
                                    <p className="font-bold text-gray-900 dark:text-white leading-tight">{selectedClient.name}</p>
                                    <p className="text-xs text-gray-500">{selectedClient.location}</p>
                                </div>
                            </div>
                            <div className="space-y-1">
                                {['overview', 'history', 'audit'].map(tab => (
                                    <button key={tab} onClick={() => setActiveTab(tab)} className={`w-full text-left p-2 rounded-md text-sm font-semibold transition-colors ${activeTab === tab ? 'bg-indigo-50 dark:bg-indigo-900/50 text-indigo-700 dark:text-indigo-300' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100'}`}>
                                        {tab.charAt(0).toUpperCase() + tab.slice(1)} {tab === 'audit' && (selectedClient.payment as any).amendmentHistory?.length > 0 && <span className="ml-1 text-[10px] bg-amber-500 text-white px-1.5 rounded-full">{(selectedClient.payment as any).amendmentHistory.length}</span>}
                                    </button>
                                ))}
                            </div>
                        </>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {!selectedClient ? (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50"><UserCircleIcon className="w-20 h-20 mb-2" /><p>Select a client to manage financials</p></div>
                    ) : (
                        <div className="space-y-6 max-w-5xl mx-auto">
                            {activeTab === 'overview' && (
                                <div className="space-y-6">
                                    <Card title="Payment Configuration" className={isUnlocked ? "ring-2 ring-amber-500 ring-opacity-50" : ""}>
                                        <form onSubmit={handleFormSubmit} className="space-y-4">
                                            <div className="relative">
                                                <Input label="Land Purchase Price" type="number" value={landPrice} onChange={e => setLandPrice(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400" />}
                                            </div>
                                            <div className="grid grid-cols-2 gap-4">
                                                <div className="relative">
                                                    <Input label="Discount" type="number" value={discountValue} onChange={e => setDiscountValue(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                    {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400" />}
                                                </div>
                                                <Select label="Mode" value={discountType} onChange={e => setDiscountType(e.target.value as any)} disabled={isFieldReadOnly}>
                                                    <option value="percentage">Percent (%)</option>
                                                    <option value="fixed">Fixed (GHC)</option>
                                                </Select>
                                            </div>
                                            <div className="relative">
                                                <Input label="Indenture/Fees" type="number" value={indenturePrice} onChange={e => setIndenturePrice(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400" />}
                                            </div>
                                            {(!isInitialized || isUnlocked) && (
                                                <div className="pt-2">
                                                    <Button type="submit" className="w-full" isLoading={isSaving} icon={<CheckCircleIcon className="w-5 h-5"/>}>
                                                        {isUnlocked ? "Log Amendment & Save" : "Initialize Account"}
                                                    </Button>
                                                </div>
                                            )}
                                        </form>
                                    </Card>
                                    <Button className="w-full" variant="success" icon={<BanknotesIcon className="w-5 h-5"/>} onClick={() => setPaymentModalOpen(true)}>Record a Payment</Button>
                                </div>
                            )}

                            {activeTab === 'audit' && (
                                <Card title="Authorization & Amendment History" className="p-0 overflow-hidden">
                                    <div className="overflow-x-auto">
                                        <table className="w-full text-xs text-left">
                                            <thead className="bg-gray-50 dark:bg-gray-700 text-gray-500 uppercase font-bold">
                                                <tr>
                                                    <th className="px-4 py-3">Timestamp</th>
                                                    <th className="px-4 py-3">Authorized By</th>
                                                    <th className="px-4 py-3">Justification/Reason</th>
                                                    <th className="px-4 py-3">Modifications</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                                {((selectedClient.payment as any).amendmentHistory || []).slice().reverse().map((entry: any, i: number) => (
                                                    <tr key={i} className="hover:bg-gray-50 dark:hover:bg-gray-800">
                                                        <td className="px-4 py-3 whitespace-nowrap text-gray-400 font-mono">{new Date(entry.timestamp).toLocaleString()}</td>
                                                        <td className="px-4 py-3">
                                                            <div className="font-bold text-gray-800 dark:text-white">{entry.amendedBy}</div>
                                                            <div className="text-[10px] text-gray-500">{entry.role}</div>
                                                        </td>
                                                        <td className="px-4 py-3 italic text-gray-600 dark:text-gray-400 max-w-xs">{entry.reason}</td>
                                                        <td className="px-4 py-3 text-amber-700 dark:text-amber-400 font-medium">{entry.changes}</td>
                                                    </tr>
                                                ))}
                                                {(!(selectedClient.payment as any).amendmentHistory || (selectedClient.payment as any).amendmentHistory.length === 0) && (
                                                    <tr><td colSpan={4} className="px-4 py-10 text-center text-gray-400 italic">No manual amendments recorded for this account.</td></tr>
                                                )}
                                            </tbody>
                                        </table>
                                    </div>
                                </Card>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {selectedClient && (
                <RecordPaymentModal 
                    isOpen={isPaymentModalOpen} 
                    onClose={() => setPaymentModalOpen(false)} 
                    onSave={(p) => onRecordPayment(selectedClient, p)} 
                    client={selectedClient}
                />
            )}

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={executeFinalSave} />

            {showSuccessModal && (
                <div className="fixed inset-0 bg-slate-900/50 z-[100] flex justify-center items-center p-4 backdrop-blur-sm">
                    <Card className="w-full max-w-xs p-6 text-center animate-in zoom-in duration-200">
                        <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <CheckCircleIcon className="w-6 h-6 text-green-600" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-2">Record Verified</h3>
                        <p className="text-xs text-gray-500 mb-4">Financial update has been logged in the audit trail.</p>
                        <Button onClick={() => setShowSuccessModal(false)} className="w-full">Dismiss</Button>
                    </Card>
                </div>
            )}
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { Client, PaymentTransaction } from '../types';
import { 
    ChartBarIcon,
    ArrowLeftIcon, 
    PrinterIcon, 
    ExclamationTriangleIcon, 
    ShieldCheckIcon,
    BanknotesIcon,
    CurrencyDollarIcon,
    UserGroupIcon
} from './icons/DummyIcons';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Badge } from './ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from './ui/Table';

interface FinancialReportsViewProps {
    onBack: () => void;
    clients: Client[];
    staffList: any[];
}

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

export const FinancialReportsView: React.FC<FinancialReportsViewProps> = ({ onBack, clients }) => {
    const [selectedMonth, setSelectedMonth] = useState(() => {
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    });

    const reportData = useMemo(() => {
        const [year, month] = selectedMonth.split('-').map(Number);

        const allTransactions: (PaymentTransaction & { clientName: string, clientId: number })[] = [];
        clients.forEach(client => {
            client.payment.paymentHistory.forEach(txn => {
                const txnDate = new Date(txn.date);
                if (txnDate.getFullYear() === year && txnDate.getMonth() === (month - 1)) {
                    allTransactions.push({ ...txn, clientName: client.name, clientId: client.id });
                }
            });
        });

        const revenueTxns = allTransactions.filter(t => (t as any).type === 'Land' || (t as any).type === 'Indenture');
        const totalRevenue = revenueTxns.reduce((sum, t) => sum + t.amount, 0);
        const commissionTxns = allTransactions.filter(t => (t as any).type === 'Commission');
        const totalCommissionPaid = commissionTxns.reduce((sum, t) => sum + t.amount, 0);

        const statusCounts = {
            fullyPaid: clients.filter(c => c.payment.balance === 0).length,
            owing: clients.filter(c => c.payment.balance > 0).length,
            overpaid: clients.filter(c => c.payment.balance < 0).length
        };

        const exceptions = {
            overpaid: clients.filter(c => c.payment.balance < 0).map(c => ({ name: c.name, amount: Math.abs(c.payment.balance) })),
            manualEdits: clients.filter(c => (c.payment as any).amendmentHistory?.some((a: any) => a.timestamp.startsWith(selectedMonth)))
        };

        return {
            allTransactions,
            totalRevenue,
            totalCommissionPaid,
            netInflow: totalRevenue - totalCommissionPaid,
            statusCounts,
            exceptions
        };
    }, [selectedMonth, clients]);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white">Monthly Audit Report</h2>
                        <p className="text-xs text-gray-500">Authenticated reconciliation view for {new Date(selectedMonth).toLocaleString('default', { month: 'long', year: 'numeric' })}</p>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <input 
                        type="month" 
                        value={selectedMonth}
                        onChange={(e) => setSelectedMonth(e.target.value)}
                        className="px-3 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm font-semibold focus:ring-2 focus:ring-indigo-500"
