            <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
                <div className="xl:col-span-2 space-y-6">
                    <Card title="Authenticated Payment Activity" className="p-0 overflow-hidden">
                        <TableContainer className="border-0 shadow-none rounded-none">
                            <table className="w-full text-sm">
                                <Thead>
                                    <tr>
                                        <Th>Date</Th>
                                        <Th>Client</Th>
                                        <Th className="text-right">Amount</Th>
                                        <Th>Receipt</Th>
                                        <Th className="text-center">Audit Flag</Th>
                                    </tr>
                                </Thead>
                                <Tbody>
                                    {reportData.allTransactions.map(t => {
                                        const client = clients.find(c => c.id === t.clientId);
                                        const isModified = (client?.payment as any).amendmentHistory?.length > 0;
                                        return (
                                            <Tr key={t.id}>
                                                <Td className="font-mono text-xs">{t.date}</Td>
                                                <Td className="font-bold">{t.clientName}</Td>
                                                <Td className="text-right font-black text-gray-800 dark:text-white">{formatCurrency(t.amount)}</Td>
                                                <Td className="font-mono text-[10px] text-gray-400 uppercase">{t.receiptNumber}</Td>
                                                <Td className="text-center">
                                                    {isModified && (
                                                        <div className="flex justify-center" title="This account has manual overrides.">
                                                            <ShieldCheckIcon className="w-5 h-5 text-amber-500" />
                                                        </div>
                                                    )}
                                                </Td>
                                            </Tr>
                                        );
                                    })}
                                    {reportData.allTransactions.length === 0 && (
                                        <Tr><Td colSpan={5} className="text-center py-8 text-gray-400 italic">No activity for this period.</Td></Tr>
                                    )}
                                </Tbody>
                            </table>
                        </TableContainer>
                    </Card>
                </div>

                <div className="space-y-6">
                    <Card title="Risk & Authorization Registry" className="bg-amber-50/30 dark:bg-amber-900/10 border-amber-200 dark:border-amber-900">
                        <div className="space-y-4">
                            <div className="flex items-start gap-3">
                                <ShieldCheckIcon className="w-5 h-5 text-amber-600 mt-0.5" />
                                <div className="flex-1">
                                    <h4 className="text-sm font-bold text-gray-800 dark:text-white">Manual Record Amendments</h4>
                                    <p className="text-[10px] text-gray-500 mb-2">Authenticated overrides during {selectedMonth}</p>
                                    <ul className="mt-2 space-y-2">
                                        {reportData.exceptions.manualEdits.map(c => (
                                            <li key={c.id} className="text-xs bg-white dark:bg-gray-800 p-2 rounded border border-amber-100 dark:border-amber-900/50">
                                                <div className="flex justify-between font-bold">
                                                    <span>{c.name}</span>
                                                    <span className="text-amber-600">MODIFIED</span>
                                                </div>
                                                <div className="text-[10px] text-gray-500 mt-1 italic">
                                                    Reason: {(c.payment as any).amendmentHistory?.slice(-1)[0]?.reason || "Not provided"}
                                                </div>
                                            </li>
                                        ))}
                                        {reportData.exceptions.manualEdits.length === 0 && <li className="text-xs text-gray-400 italic">No manual overrides detected</li>}
                                    </ul>
                                </div>
                            </div>
                        </div>
                    </Card>
                </div>
            </div>
        </div>
    );
};

