import React, { useState, useMemo } from 'react';
import { Client, PaymentTransaction, Staff } from '../types';
import { 
    ChartBarIcon,
    ArrowLeftIcon, 
    PrinterIcon, 
    ExclamationTriangleIcon, 
    ShieldCheckIcon,
    BanknotesIcon,
    CurrencyDollarIcon,
    UserGroupIcon
} from './icons/DummyIcons';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Badge } from './ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from './ui/Table';

interface FinancialReportsViewProps {
    onBack: () => void;
    clients: Client[];
    staffList: Staff[];
}

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

export const FinancialReportsView: React.FC<FinancialReportsViewProps> = ({ onBack, clients }) => {
    const [selectedMonth, setSelectedMonth] = useState(() => {
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    });

    const reportData = useMemo(() => {
        const [year, month] = selectedMonth.split('-').map(Number);

        const allTransactions: (PaymentTransaction & { clientName: string, clientId: number })[] = [];
        clients.forEach(client => {
            client.payment.paymentHistory.forEach(txn => {
                const txnDate = new Date(txn.date);
                if (txnDate.getFullYear() === year && txnDate.getMonth() === (month - 1)) {
                    allTransactions.push({ ...txn, clientName: client.name, clientId: client.id });
                }
            });
        });

        const revenueTxns = allTransactions.filter(t => (t as any).type === 'Land' || (t as any).type === 'Indenture');
        const totalRevenue = revenueTxns.reduce((sum, t) => sum + t.amount, 0);
        const commissionTxns = allTransactions.filter(t => (t as any).type === 'Commission');
        const totalCommissionPaid = commissionTxns.reduce((sum, t) => sum + t.amount, 0);

        const exceptions = {
            overpaid: clients.filter(c => c.payment.balance < 0).map(c => ({ name: c.name, amount: Math.abs(c.payment.balance) })),
            manualEdits: clients.filter(c => (c.payment as any).amendmentHistory?.some((a: any) => a.timestamp.startsWith(selectedMonth)))
        };

        return {
            allTransactions,
            totalRevenue,
            totalCommissionPaid,
            netInflow: totalRevenue - totalCommissionPaid,
            exceptions
        };
    }, [selectedMonth, clients]);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100 transition-colors"><ArrowLeftIcon className="w-6 h-6" /></button>
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white">Monthly Audit Report</h2>
                        <p className="text-xs text-gray-500">Authenticated reconciliation view for {new Date(selectedMonth).toLocaleString('default', { month: 'long', year: 'numeric' })}</p>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <input 
                        type="month" 
                        value={selectedMonth}
                        onChange={(e) => setSelectedMonth(e.target.value)}
                        className="px-3 py-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm font-semibold focus:ring-2 focus:ring-indigo-500"
                    />
                    <Button variant="secondary" icon={<PrinterIcon className="w-4 h-4"/>} onClick={() => window.print()}>Print</Button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <Card className="p-4 border-l-4 border-l-green-500">
                    <p className="text-xs font-bold text-gray-400 uppercase">Gross Revenue</p>
                    <h3 className="text-xl font-black text-gray-900 dark:text-white mt-1">{formatCurrency(reportData.totalRevenue)}</h3>
                </Card>
                <Card className="p-4 border-l-4 border-l-red-500">
                    <p className="text-xs font-bold text-gray-400 uppercase">Commission Costs</p>
                    <h3 className="text-xl font-black text-gray-900 dark:text-white mt-1">{formatCurrency(reportData.totalCommissionPaid)}</h3>
                </Card>
                <Card className="p-4 border-l-4 border-l-indigo-500">
                    <p className="text-xs font-bold text-gray-400 uppercase">Net Monthly Inflow</p>
                    <h3 className="text-xl font-black text-indigo-600 dark:text-indigo-400 mt-1">{formatCurrency(reportData.netInflow)}</h3>
                </Card>
                <Card className="p-4 border-l-4 border-l-amber-500">
                    <p className="text-xs font-bold text-gray-400 uppercase">Audit Exceptions</p>
                    <div className="flex gap-2 mt-1">
                        <Badge variant="danger">{reportData.exceptions.overpaid.length} Overpaid</Badge>
                        <Badge variant="warning">{reportData.exceptions.manualEdits.length} Edited</Badge>
                    </div>
                </Card>
            </div>

            <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
                <div className="xl:col-span-2 space-y-6">
                    <Card title="Activity Log & Verifications" className="p-0 overflow-hidden">
                        <TableContainer className="border-0 shadow-none rounded-none">
                            <table className="w-full text-sm">
                                <Thead>
                                    <tr>
                                        <Th>Date</Th>
                                        <Th>Client</Th>
                                        <Th className="text-right">Amount</Th>
                                        <Th className="text-center">Audit Flag</Th>
                                    </tr>
                                </Thead>
                                <Tbody>
                                    {reportData.allTransactions.map(t => {
                                        const client = clients.find(c => c.id === t.clientId);
                                        const isModified = (client?.payment as any).amendmentHistory?.length > 0;
                                        return (
                                            <Tr key={t.id}>
                                                <Td className="font-mono text-xs text-gray-500">{t.date}</Td>
                                                <Td className="font-bold">{t.clientName}</Td>
                                                <Td className="text-right font-black text-gray-800 dark:text-white">{formatCurrency(t.amount)}</Td>
                                                <Td className="text-center">
                                                    {isModified && (
                                                        <div className="flex justify-center" title="Manual Overrides Detected">
                                                            <ShieldCheckIcon className="w-5 h-5 text-amber-500" />
                                                        </div>
                                                    )}
                                                </Td>
                                            </Tr>
                                        );
                                    })}
                                    {reportData.allTransactions.length === 0 && (
                                        <Tr><Td colSpan={4} className="text-center py-8 text-gray-400 italic">No activity for this period.</Td></Tr>
                                    )}
                                </Tbody>
                            </table>
                        </TableContainer>
                    </Card>
                </div>

                <div className="space-y-6">
                    <Card title="Risk Authorization Registry" className="bg-amber-50/30 dark:bg-amber-900/10 border-amber-200 dark:border-amber-900">
                        <div className="space-y-4">
                            <div className="flex items-start gap-3">
                                <ShieldCheckIcon className="w-5 h-5 text-amber-600 mt-0.5" />
                                <div className="flex-1">
                                    <h4 className="text-sm font-bold text-gray-800 dark:text-white">Authenticated Overrides</h4>
                                    <p className="text-[10px] text-gray-500 mb-2 uppercase tracking-wider">Historical records modified in current period</p>
                                    <ul className="mt-2 space-y-2">
                                        {reportData.exceptions.manualEdits.map(c => {
                                            const lastAmendment = (c.payment as any).amendmentHistory?.slice().reverse()[0];
                                            return (
                                                <li key={c.id} className="text-xs bg-white dark:bg-gray-800 p-2 rounded border border-amber-100 dark:border-amber-900/50 shadow-sm">
                                                    <div className="flex justify-between font-bold">
                                                        <span>{c.name}</span>
                                                        <span className="text-amber-600 text-[10px]">VERIFIED</span>
                                                    </div>
                                                    <div className="text-[10px] text-gray-500 mt-1 italic leading-tight">
                                                        Reason: {lastAmendment?.reason || "No justification provided."}
                                                    </div>
                                                    <div className="text-[9px] text-gray-400 mt-1 flex justify-between">
                                                        <span>By: {lastAmendment?.amendedBy}</span>
                                                        <span>{new Date(lastAmendment?.timestamp).toLocaleDateString()}</span>
                                                    </div>
                                                </li>
                                            );
                                        })}
                                        {reportData.exceptions.manualEdits.length === 0 && <li className="text-xs text-gray-400 italic">No overrides recorded.</li>}
                                    </ul>
                                </div>
                            </div>
                        </div>
                    </Card>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Staff, ActivityLog } from '../../types';
import { 
    MagnifyingGlassIcon, 
    PlusCircleIcon, 
    TrashIcon, 
    InboxArrowDownIcon, 
    PaperAirplaneIcon, 
    UserCircleIcon,
    EnvelopeIcon,
    PaperClipIcon,
    ArrowDownTrayIcon,
    XMarkIcon,
    ArrowLeftIcon
} from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { useStaff, useActivityLogs } from '../../hooks/useAppData';
import { useAuth } from '../../context/AuthContext';
import { uploadFile } from '../../services/storageService';

// Standardized Interface for internal messages
interface InternalMessage {
    id: string;
    senderId: string;
    senderName: string;
    toIds: string[];
    ccIds: string[];
    subject: string;
    body: string;
    attachments: { name: string; url: string; type: string; size: number }[];
    timestamp: string;
    readBy: string[]; // User IDs who have read this
}

const MailingPage: React.FC = () => {
    const { staff } = useStaff();
    const { currentStaff } = useAuth();
    const { addActivityLog } = useActivityLogs();

    // UI State
    const [folder, setFolder] = useState<'inbox' | 'sent'>('inbox');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedMessage, setSelectedMessage] = useState<InternalMessage | null>(null);
    const [isComposeOpen, setComposeOpen] = useState(false);
    const [isMobileListOpen, setMobileListOpen] = useState(true);

    // Mock Messages State (In a real app, this comes from a useMessages hook/Firestore)
    // Initializing with some dummy data for preview
    const [messages, setMessages] = useState<InternalMessage[]>([
        {
            id: 'msg-1',
            senderId: '1',
            senderName: 'Araba CEO',
            toIds: [currentStaff?.id || '2'],
            ccIds: [],
            subject: 'Q3 Property Sales Targets',
            body: 'Hi team,\n\nPlease find the attached targets for the next quarter. We need to focus on East Legon Hills development.\n\nBest regards,\nAraba',
            attachments: [{ name: 'Targets_Q3.pdf', url: '#', type: 'application/pdf', size: 1024 * 500 }],
            timestamp: new Date(Date.now() - 3600000).toISOString(),
            readBy: []
        }
    ]);

    // Derived Data
    const filteredMessages = useMemo(() => {
        return messages.filter(m => {
            const isTarget = folder === 'inbox' 
                ? (m.toIds.includes(currentStaff?.id || '') || m.ccIds.includes(currentStaff?.id || ''))
                : m.senderId === currentStaff?.id;

            if (!isTarget) return false;

            const searchStr = searchTerm.toLowerCase();
            return m.subject.toLowerCase().includes(searchStr) || 
                   m.senderName.toLowerCase().includes(searchStr) ||
                   m.body.toLowerCase().includes(searchStr);
        }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [messages, folder, currentStaff, searchTerm]);

    const unreadCount = useMemo(() => {
        return messages.filter(m => 
            (m.toIds.includes(currentStaff?.id || '') || m.ccIds.includes(currentStaff?.id || '')) && 
            !m.readBy.includes(currentStaff?.id || '')
        ).length;
    }, [messages, currentStaff]);

    // Actions
    const handleSelectMessage = (msg: InternalMessage) => {
        setSelectedMessage(msg);
        setMobileListOpen(false);
        if (!msg.readBy.includes(currentStaff?.id || '')) {
            setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, readBy: [...m.readBy, currentStaff?.id || ''] } : m));
        }
    };

    const handleSendMessage = async (msgData: any) => {
        const newMessage: InternalMessage = {
            id: `MSG-${Date.now()}`,
            senderId: currentStaff?.id || '0',
            senderName: currentStaff?.fullName || 'Unknown',
            ...msgData,
            timestamp: new Date().toISOString(),
            readBy: [currentStaff?.id || '']
        };

        setMessages(prev => [newMessage, ...prev]);
        addActivityLog('Create', `Sent internal message: "${newMessage.subject}" to ${newMessage.toIds.length} recipients.`);
        setComposeOpen(false);
    };

    const handleDeleteMessage = (id: string) => {
        if (window.confirm('Are you sure you want to delete this message?')) {
            setMessages(prev => prev.filter(m => m.id !== id));
            if (selectedMessage?.id === id) setSelectedMessage(null);
            addActivityLog('Delete', `Deleted internal message with ID: ${id}`);
        }
    };

    return (
        <div className="flex flex-col h-[calc(100vh-120px)] space-y-4">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Mailing</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Internal communication and document sharing.</p>
                </div>
                <Button onClick={() => setComposeOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                    Compose Message
                </Button>
            </div>

            <div className="flex-grow flex bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
                {/* Sidebar Folders */}
                <div className="w-16 md:w-64 border-r border-gray-200 dark:border-gray-700 flex flex-col bg-gray-50 dark:bg-gray-900/50">
                    <nav className="p-3 space-y-2">
                        <button 
                            onClick={() => setFolder('inbox')}
                            className={`w-full flex items-center justify-between p-3 rounded-lg transition-colors ${folder === 'inbox' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-800'}`}
                        >
                            <div className="flex items-center gap-3">
                                <InboxArrowDownIcon className="w-5 h-5" />
                                <span className="hidden md:block font-semibold">Inbox</span>
                            </div>
                            {unreadCount > 0 && (
                                <span className={`hidden md:block px-2 py-0.5 text-[10px] font-bold rounded-full ${folder === 'inbox' ? 'bg-white text-blue-600' : 'bg-blue-600 text-white'}`}>
                                    {unreadCount}
                                </span>
                            )}
                        </button>
                        <button 
                            onClick={() => setFolder('sent')}
                            className={`w-full flex items-center gap-3 p-3 rounded-lg transition-colors ${folder === 'sent' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-800'}`}
                        >
                            <PaperAirplaneIcon className="w-5 h-5 -rotate-45" />
                            <span className="hidden md:block font-semibold">Sent Items</span>
                        </button>
                    </nav>
                </div>

                {/* Message List Pane */}
                <div className={`flex-grow md:flex-none md:w-96 flex flex-col border-r border-gray-200 dark:border-gray-700 ${!isMobileListOpen ? 'hidden md:flex' : 'flex'}`}>
                    <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                        <div className="relative">
                            <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                            <input 
                                type="text"
                                placeholder="Search messages..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pl-9 pr-4 py-2 bg-gray-100 dark:bg-gray-900 border-none rounded-lg text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white"
                            />
                        </div>
                    </div>
                    <div className="flex-grow overflow-y-auto scrollbar-thin">
                        {filteredMessages.length === 0 ? (
                            <div className="p-10 text-center text-gray-400 italic text-sm">No messages found.</div>
                        ) : (
                            filteredMessages.map(msg => {
                                const isUnread = folder === 'inbox' && !msg.readBy.includes(currentStaff?.id || '');
                                return (
                                    <div 
                                        key={msg.id}
                                        onClick={() => handleSelectMessage(msg)}
                                        className={`p-4 border-b border-gray-100 dark:border-gray-700/50 cursor-pointer transition-colors hover:bg-gray-50 dark:hover:bg-gray-700/30 ${selectedMessage?.id === msg.id ? 'bg-blue-50 dark:bg-blue-900/10 border-l-4 border-l-blue-600' : ''}`}
                                    >
                                        <div className="flex justify-between items-start mb-1">
                                            <span className={`text-xs font-bold truncate ${isUnread ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500'}`}>
                                                {folder === 'inbox' ? msg.senderName : `To: ${msg.toIds.length} recipient(s)`}
                                            </span>
                                            <span className="text-[10px] text-gray-400 whitespace-nowrap">{new Date(msg.timestamp).toLocaleDateString()}</span>
                                        </div>
                                        <div className={`text-sm truncate ${isUnread ? 'font-black text-gray-900 dark:text-white' : 'text-gray-700 dark:text-gray-300'}`}>
                                            {msg.subject}
                                        </div>
                                        <div className="text-xs text-gray-400 truncate mt-1">{msg.body.substring(0, 60)}...</div>
                                        <div className="flex items-center gap-2 mt-2">
                                            {msg.attachments.length > 0 && <PaperClipIcon className="w-3 h-3 text-gray-400" />}
                                            {isUnread && <div className="w-2 h-2 rounded-full bg-blue-600"></div>}
                                        </div>
                                    </div>
                                );
                            })
                        )}
                    </div>
                </div>

                {/* Content Pane */}
                <div className={`flex-grow flex flex-col bg-gray-50/50 dark:bg-gray-900/20 ${isMobileListOpen ? 'hidden md:flex' : 'flex'}`}>
                    {selectedMessage ? (
                        <div className="flex flex-col h-full animate-in fade-in slide-in-from-right-4 duration-300">
                            <div className="p-4 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center">
                                <div className="flex items-center gap-3">
                                    <button onClick={() => setMobileListOpen(true)} className="md:hidden p-2 text-gray-500">
                                        <ArrowLeftIcon className="w-5 h-5" />
                                    </button>
                                    <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold">
                                        {selectedMessage.senderName.substring(0, 2).toUpperCase()}
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-gray-900 dark:text-white">{selectedMessage.senderName}</h3>
                                        <p className="text-[10px] text-gray-500 uppercase tracking-widest">{new Date(selectedMessage.timestamp).toLocaleString()}</p>
                                    </div>
                                </div>
                                <div className="flex gap-2">
                                    <button 
                                        onClick={() => handleDeleteMessage(selectedMessage.id)}
                                        className="p-2 text-gray-400 hover:text-red-500 transition-colors"
                                    >
                                        <TrashIcon className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>

                            <div className="p-6 flex-grow overflow-y-auto bg-white dark:bg-gray-800">
                                <div className="mb-6">
                                    <h2 className="text-xl font-black text-gray-800 dark:text-white mb-2">{selectedMessage.subject}</h2>
                                    <div className="flex flex-wrap gap-2 text-xs text-gray-500">
                                        <span className="font-bold">To:</span> {selectedMessage.toIds.map(id => staff.find(s => s.id === id)?.fullName).join(', ')}
                                        {selectedMessage.ccIds.length > 0 && (
                                            <>
                                                <span className="font-bold ml-2">CC:</span> {selectedMessage.ccIds.map(id => staff.find(s => s.id === id)?.fullName).join(', ')}
                                            </>
                                        )}
                                    </div>
                                </div>
                                <div className="prose prose-sm max-w-none dark:prose-invert text-gray-800 dark:text-gray-300 whitespace-pre-wrap border-t border-gray-100 dark:border-gray-700 pt-6">
                                    {selectedMessage.body}
                                </div>

                                {selectedMessage.attachments.length > 0 && (
                                    <div className="mt-10 border-t border-gray-100 dark:border-gray-700 pt-6">
                                        <h4 className="text-xs font-bold text-gray-400 uppercase mb-4 flex items-center gap-2">
                                            <PaperClipIcon className="w-4 h-4" /> Attachments ({selectedMessage.attachments.length})
                                        </h4>
                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                            {selectedMessage.attachments.map((file, idx) => (
                                                <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg group transition-all hover:border-blue-300">
                                                    <div className="flex items-center gap-3 overflow-hidden">
                                                        <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900/30 rounded flex items-center justify-center text-blue-600">
                                                            {file.type.includes('pdf') ? 'PDF' : 'DOC'}
                                                        </div>
                                                        <div className="overflow-hidden">
                                                            <p className="text-sm font-bold text-gray-800 dark:text-white truncate">{file.name}</p>
                                                            <p className="text-[10px] text-gray-500">{(file.size / 1024).toFixed(1)} KB</p>
                                                        </div>
                                                    </div>
                                                    <a href={file.url} download className="p-2 text-gray-400 hover:text-blue-600 transition-colors">
                                                        <ArrowDownTrayIcon className="w-5 h-5" />
                                                    </a>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400">
                            <EnvelopeIcon className="w-20 h-20 mb-4 opacity-10" />
                            <p className="text-lg font-medium">Select a message to view content</p>
                            <p className="text-sm">Quickly communicate with your team members.</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Compose Modal */}
            <MessageComposeModal 
                isOpen={isComposeOpen}
                onClose={() => setComposeOpen(false)}
                staff={staff}
                onSend={handleSendMessage}
            />

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 5px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
        </div>
    );
};

// Internal Modal for Composition
const MessageComposeModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    staff: Staff[];
    onSend: (data: any) => void;
}> = ({ isOpen, onClose, staff, onSend }) => {
    const [toIds, setToIds] = useState<string[]>([]);
    const [ccIds, setCcIds] = useState<string[]>([]);
    const [subject, setSubject] = useState('');
    const [body, setBody] = useState('');
    const [files, setFiles] = useState<File[]>([]);
    const [isUploading, setIsUploading] = useState(false);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (toIds.length === 0 || !subject.trim() || !body.trim()) {
            alert('Please fill in all mandatory fields.');
            return;
        }

        setIsUploading(true);
        try {
            const attachmentData = await Promise.all(
                files.map(async (file) => {
                    const url = await uploadFile(file, `messages/tmp/${Date.now()}_${file.name}`);
                    return { name: file.name, url, type: file.type, size: file.size };
                })
            );

            onSend({ toIds, ccIds, subject, body, attachments: attachmentData });
            // Reset
            setToIds([]); setCcIds([]); setSubject(''); setBody(''); setFiles([]);
        } catch (error) {
            console.error(error);
            alert('Failed to send message/upload attachments.');
        } finally {
            setIsUploading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            setFiles(prev => [...prev, ...Array.from(e.target.files!)]);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-3xl p-0 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                <form onSubmit={handleSubmit} className="flex flex-col h-full">
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900">
                        <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            <EnvelopeIcon className="w-5 h-5 text-blue-600" /> Compose New Message
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    <div className="p-6 space-y-4 overflow-y-auto flex-grow bg-white dark:bg-gray-800 scrollbar-thin">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">To (Required)</label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm text-gray-900 dark:text-white min-h-[100px]"
                                    value={toIds}
                                    onChange={(e) => setToIds(Array.from(e.target.selectedOptions, opt => opt.value))}
                                >
                                    {staff.map(s => <option key={s.id} value={s.id}>{s.fullName}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">CC (Optional)</label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm text-gray-900 dark:text-white min-h-[100px]"
                                    value={ccIds}
                                    onChange={(e) => setCcIds(Array.from(e.target.selectedOptions, opt => opt.value))}
                                >
                                    {staff.map(s => <option key={s.id} value={s.id}>{s.fullName}</option>)}
                                </select>
                            </div>
                        </div>

                        <Input 
                            label="Subject*" 
                            value={subject} 
                            onChange={e => setSubject(e.target.value)} 
                            placeholder="Enter message subject..." 
                            required
                        />

                        <Textarea 
                            label="Message Content*" 
                            value={body} 
                            onChange={e => setBody(e.target.value)} 
                            rows={8}
                            placeholder="Type your message here..."
                            required
                        />

                        <div>
                            <label className="block text-xs font-bold text-gray-400 uppercase mb-2">Attachments</label>
                            <div className="flex flex-wrap gap-2 mb-3">
                                {files.map((f, i) => (
                                    <div key={i} className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 rounded-full text-xs font-bold border border-blue-100 dark:border-blue-800">
                                        <span className="truncate max-w-[150px]">{f.name}</span>
                                        <button type="button" onClick={() => setFiles(prev => prev.filter((_, idx) => idx !== i))} className="hover:text-red-500">
                                            <XMarkIcon className="w-3 h-3" />
                                        </button>
                                    </div>
                                ))}
                            </div>
                            <label className="inline-flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg text-sm font-semibold cursor-pointer hover:bg-gray-200 transition-colors border border-gray-300 dark:border-gray-600">
                                <PaperClipIcon className="w-4 h-4" /> Add Files
                                <input type="file" multiple className="sr-only" onChange={handleFileChange} />
                            </label>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit" isLoading={isUploading} icon={<PaperAirplaneIcon className="w-5 h-5 -rotate-45" />}>
                            Send Message
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

