                    <ul className="pl-6">
                      {item.subItems.map((subItem) => (
                        <li key={subItem.name}>
                          <a
                            href={subItem.href}
                            onClick={(e) => { e.preventDefault(); handleNavClick(subItem.name); }}
                            className={`flex items-center gap-3 pl-3 pr-4 py-2 my-1 rounded-md transition-colors duration-200 text-sm ${
