    // State initialized with mock data
    const [messages, setMessages] = useState<InternalMessage[]>([
        {
            id: 'm-1',
            senderId: 'admin-1',
            senderName: 'System Admin',
            toIds: [currentStaff?.id || ''],
            ccIds: [],
            subject: 'Welcome to the FAIM Internal Portal',
            body: 'Hello team,\n\nWe have successfully deployed the new Internal Mailing module. Please use this for all professional communication and document sharing.\n\nBest,\nAdmin',
            attachments: [],
            timestamp: new Date(Date.now() - 86400000).toISOString(),
            readBy: []
        }
    ]);

    const filteredMessages = useMemo(() => {
        return messages.filter(m => {
            const isInFolder = folder === 'inbox' 
                ? m.toIds.includes(currentStaff?.id || '') || m.ccIds.includes(currentStaff?.id || '')
                : m.senderId === currentStaff?.id;

            if (!isInFolder) return false;

            const search = searchTerm.toLowerCase();
            return m.subject.toLowerCase().includes(search) || 
                   m.senderName.toLowerCase().includes(search) ||
                   m.body.toLowerCase().includes(search);
