    }, [messages, folder, currentStaff, searchTerm]);

    const unreadCount = useMemo(() => {
        return messages.filter(m => 
            m.toIds.includes(currentStaff?.id || '') && !m.readBy.includes(currentStaff?.id || '')
        ).length;
    }, [messages, currentStaff]);

    const handleSelectMessage = (msg: InternalMessage) => {
        setSelectedMessage(msg);
        setIsMobileView('preview');
        if (!msg.readBy.includes(currentStaff?.id || '')) {
            setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, readBy: [...m.readBy, currentStaff?.id || ''] } : m));
        }
    };

    const handleSendMessage = async (msgData: any) => {
        const newMessage: InternalMessage = {
            id: `msg-${Date.now()}`,
            senderId: currentStaff?.id || '0',
            senderName: currentStaff?.fullName || 'Unknown',
            ...msgData,
            timestamp: new Date().toISOString(),
