        <div className="flex flex-col h-[calc(100vh-140px)] animate-in fade-in duration-500">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Internal Mailing</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Professional internal communication hub.</p>
                </div>
                <Button onClick={() => setComposeOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                    Compose Message
                </Button>
            </div>

            <div className="flex-grow flex bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden relative">

                {/* Folder Pane (Desktop & Mobile) */}
                <div className={`${isMobileView === 'folders' ? 'flex' : 'hidden md:flex'} w-full md:w-64 border-r border-gray-200 dark:border-gray-700 flex-col bg-gray-50 dark:bg-gray-900/50`}>
                    <nav className="p-4 space-y-2">
                        <button 
                            onClick={() => { setFolder('inbox'); setIsMobileView('list'); }}
                            className={`w-full flex items-center justify-between p-3 rounded-lg transition-all ${folder === 'inbox' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-800'}`}
                        >
                            <div className="flex items-center gap-3">
                                <InboxArrowDownIcon className="w-5 h-5" />
                                <span className="font-semibold">Inbox</span>
                            </div>
                            {unreadCount > 0 && <span className={`px-2 py-0.5 text-[10px] font-bold rounded-full ${folder === 'inbox' ? 'bg-white text-blue-600' : 'bg-blue-600 text-white'}`}>{unreadCount}</span>}
                        </button>
                        <button 
                            onClick={() => { setFolder('sent'); setIsMobileView('list'); }}
                            className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all ${folder === 'sent' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-800'}`}
                        >
                            <PaperAirplaneIcon className="w-5 h-5 -rotate-45" />
                            <span className="font-semibold">Sent Items</span>
                        </button>
