                </div>

                {/* Message List Pane */}
                <div className={`${isMobileView === 'list' ? 'flex' : 'hidden md:flex'} w-full md:w-96 flex-col border-r border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800`}>
                    <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex items-center gap-2">
                        <button onClick={() => setIsMobileView('folders')} className="md:hidden p-2 -ml-2 text-gray-400"><ArrowLeftIcon className="w-5 h-5" /></button>
                        <div className="relative flex-grow">
                            <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                            <input 
                                type="text"
                                placeholder="Search..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pl-9 pr-4 py-2 bg-gray-100 dark:bg-gray-900 border-none rounded-lg text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white"
                            />
                        </div>
                    </div>
                    <div className="overflow-y-auto scrollbar-thin">
                        {filteredMessages.map(msg => {
                            const isUnread = folder === 'inbox' && !msg.readBy.includes(currentStaff?.id || '');
                            return (
                                <div 
                                    key={msg.id}
                                    onClick={() => handleSelectMessage(msg)}
                                    className={`p-4 border-b border-gray-100 dark:border-gray-700/50 cursor-pointer transition-colors hover:bg-blue-50/50 dark:hover:bg-blue-900/10 ${selectedMessage?.id === msg.id ? 'bg-blue-50 dark:bg-blue-900/20 border-l-4 border-l-blue-600' : ''}`}
                                >
                                    <div className="flex justify-between items-start mb-1">
                                        <span className={`text-xs font-bold truncate ${isUnread ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500'}`}>
                                            {folder === 'inbox' ? msg.senderName : `To: ${msg.toIds.length} Recipient(s)`}
