                                        <span className="text-[10px] text-gray-400 whitespace-nowrap">{new Date(msg.timestamp).toLocaleDateString()}</span>
                                    </div>
                                    <div className={`text-sm truncate ${isUnread ? 'font-black text-gray-900 dark:text-white' : 'text-gray-700 dark:text-gray-300'}`}>
                                        {msg.subject}
                                    </div>
                                    <div className="text-xs text-gray-400 truncate mt-1">{msg.body}</div>
                                    <div className="flex items-center gap-2 mt-2">
                                        {msg.attachments.length > 0 && <PaperClipIcon className="w-3 h-3 text-gray-400" />}
                                        {isUnread && <div className="w-2 h-2 rounded-full bg-blue-600 animate-pulse"></div>}
                                    </div>
                                </div>
                            );
                        })}
                        {filteredMessages.length === 0 && <div className="p-10 text-center text-gray-400 italic">No messages found.</div>}
                    </div>
                </div>

                {/* Content Pane */}
                <div className={`${isMobileView === 'preview' ? 'flex' : 'hidden md:flex'} flex-grow flex-col bg-gray-50/30 dark:bg-gray-900/10`}>
                    {selectedMessage ? (
                        <div className="flex flex-col h-full animate-in slide-in-from-right-4 duration-300">
                            <div className="p-4 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center">
                                <div className="flex items-center gap-3">
                                    <button onClick={() => setIsMobileView('list')} className="md:hidden p-2 text-gray-500"><ArrowLeftIcon className="w-5 h-5" /></button>
                                    <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold">
                                        {selectedMessage.senderName.substring(0, 2).toUpperCase()}
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-gray-900 dark:text-white leading-tight">{selectedMessage.senderName}</h3>
                                        <p className="text-[10px] text-gray-500 uppercase tracking-widest">{new Date(selectedMessage.timestamp).toLocaleString()}</p>
                                    </div>
                                </div>
                                <div className="flex gap-2">
                                    <button className="p-2 text-gray-400 hover:text-red-500 transition-colors"><TrashIcon className="w-5 h-5" /></button>
                                </div>
                            </div>

                            <div className="p-6 flex-grow overflow-y-auto bg-white dark:bg-gray-800">
                                <div className="mb-6">
                                    <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-2">{selectedMessage.subject}</h2>
                                    <div className="flex flex-wrap gap-2 text-xs text-gray-500">
                                        <span className="font-bold">To:</span> {selectedMessage.toIds.map(id => staff.find(s => s.id === id)?.fullName).join(', ')}
                                        {selectedMessage.ccIds.length > 0 && (
                                            <><span className="font-bold ml-2">CC:</span> {selectedMessage.ccIds.map(id => staff.find(s => s.id === id)?.fullName).join(', ')}</>
                                        )}
                                    </div>
                                </div>
