                                                        <div className="w-9 h-9 bg-white dark:bg-gray-800 rounded border border-gray-200 dark:border-gray-700 flex items-center justify-center text-blue-600 text-[10px] font-bold">
                                                            {file.type.split('/')[1]?.toUpperCase() || 'FILE'}
                                                        </div>
                                                        <div className="overflow-hidden">
                                                            <p className="text-xs font-bold text-gray-800 dark:text-white truncate">{file.name}</p>
                                                            <p className="text-[10px] text-gray-500">{(file.size / 1024).toFixed(1)} KB</p>
                                                        </div>
                                                    </div>
                                                    <a href={file.url} download className="p-2 text-gray-400 hover:text-blue-600 transition-colors" title="Download">
                                                        <ArrowDownTrayIcon className="w-4 h-4" />
                                                    </a>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 p-10 text-center">
                            <EnvelopeIcon className="w-20 h-20 mb-4 opacity-10" />
                            <p className="text-lg font-medium">Select a communication thread</p>
                            <p className="text-sm max-w-xs text-gray-500">Access your professional mailbox and project documents here.</p>
                        </div>
                    )}
                </div>
            </div>

            <ComposeModal 
                isOpen={isComposeOpen}
                onClose={() => setComposeOpen(false)}
                staff={staff}
                onSend={handleSendMessage}
            />

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 5px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
        </div>
    );
};

const ComposeModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    staff: any[];
    onSend: (data: any) => void;
}> = ({ isOpen, onClose, staff, onSend }) => {
    const [toIds, setToIds] = useState<string[]>([]);
    const [ccIds, setCcIds] = useState<string[]>([]);
    const [subject, setSubject] = useState('');
    const [body, setBody] = useState('');
    const [files, setFiles] = useState<File[]>([]);
    const [isUploading, setIsUploading] = useState(false);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (toIds.length === 0 || !subject.trim() || !body.trim()) return;

        setIsUploading(true);
        try {
            const attachmentData = await Promise.all(
                files.map(async (file) => {
                    const url = await uploadFile(file, `internal_mail/tmp/${Date.now()}_${file.name}`);
                    return { name: file.name, url, type: file.type, size: file.size };
                })
            );
            onSend({ toIds, ccIds, subject, body, attachments: attachmentData });
        } finally {
            setIsUploading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-3xl p-0 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                <form onSubmit={handleSubmit} className="flex flex-col h-full">
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900">
                        <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            <EnvelopeIcon className="w-5 h-5 text-blue-600" /> New Internal Message
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    <div className="p-6 space-y-4 overflow-y-auto flex-grow bg-white dark:bg-gray-800 scrollbar-thin">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Recipients (To)*</label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm text-gray-900 dark:text-white min-h-[100px] focus:ring-2 focus:ring-blue-500"
                                    value={toIds}
                                    onChange={(e) => setToIds(Array.from(e.target.selectedOptions).map(o => (o as HTMLOptionElement).value))}
                                >
                                    {staff.map(s => <option key={s.id} value={s.id}>{s.fullName}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Copy (Cc)</label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm text-gray-900 dark:text-white min-h-[100px] focus:ring-2 focus:ring-blue-500"
                                    value={ccIds}
                                    onChange={(e) => setCcIds(Array.from(e.target.selectedOptions).map(o => (o as HTMLOptionElement).value))}
                                >
                                    {staff.map(s => <option key={s.id} value={s.id}>{s.fullName}</option>)}
                                </select>
                            </div>
                        </div>

                        <Input label="Subject*" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Enter a clear subject line" required />
                        <Textarea label="Message Content*" value={body} onChange={e => setBody(e.target.value)} rows={6} placeholder="Type your message here..." required />

                        <div>
                            <label className="block text-xs font-bold text-gray-400 uppercase mb-2">Attachments</label>
                            <div className="flex flex-wrap gap-2 mb-3">
                                {files.map((f, i) => (
                                    <div key={i} className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 rounded-full text-xs font-bold border border-blue-100 dark:border-blue-800">
                                        <span className="truncate max-w-[150px]">{f.name}</span>
                                        <button type="button" onClick={() => setFiles(prev => prev.filter((_, idx) => idx !== i))} className="hover:text-red-500"><XMarkIcon className="w-3 h-3" /></button>
                                    </div>
                                ))}
                            </div>
                            <label className="inline-flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg text-sm font-semibold cursor-pointer hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors border border-gray-300 dark:border-gray-600">
                                <PaperClipIcon className="w-4 h-4" /> Add Files
                                <input type="file" multiple className="sr-only" onChange={e => e.target.files && setFiles(prev => [...prev, ...Array.from(e.target.files!)])} />
                            </label>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Discard</Button>
                        <Button type="submit" isLoading={isUploading} icon={<PaperAirplaneIcon className="w-5 h-5 -rotate-45" />}>
                            Send Message
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export default InternalMailingPage;

