    }, [messages, folder, currentStaff, searchTerm, dateRange]);

    const unreadCount = useMemo(() => {
        return messages.filter(m => 
            (m.toIds.includes(currentStaff?.id || '') || m.ccIds.includes(currentStaff?.id || '')) && !m.readBy.includes(currentStaff?.id || '')
        ).length;
