                    <p className="text-gray-500 dark:text-gray-400 mt-1">Sub-module: Team Communication</p>
                </div>
                <Button onClick={() => setComposeOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                    Compose
                </Button>
            </div>

            <div className="flex-grow flex bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden relative">

                {/* Folder Pane (Folders) */}
                <div className={`${isMobileView === 'folders' ? 'flex' : 'hidden md:flex'} w-full md:w-56 border-r border-gray-200 dark:border-gray-700 flex-col bg-gray-50 dark:bg-gray-900/50`}>
                    <nav className="p-4 space-y-1">
                        <button 
                            onClick={() => { setFolder('inbox'); setIsMobileView('list'); setSelectedMessage(null); }}
                            className={`w-full flex items-center justify-between p-3 rounded-lg transition-all ${folder === 'inbox' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-800'}`}
                        >
                            <div className="flex items-center gap-3">
                                <InboxArrowDownIcon className="w-5 h-5" />
                                <span className="font-semibold">Inbox</span>
                            </div>
                            {unreadCount > 0 && <span className={`px-2 py-0.5 text-[10px] font-bold rounded-full ${folder === 'inbox' ? 'bg-white text-blue-600' : 'bg-blue-600 text-white'}`}>{unreadCount}</span>}
                        </button>
                        <button 
                            onClick={() => { setFolder('sent'); setIsMobileView('list'); setSelectedMessage(null); }}
                            className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all ${folder === 'sent' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-800'}`}
                        >
                            <PaperAirplaneIcon className="w-5 h-5 -rotate-45" />
                            <span className="font-semibold">Sent</span>
                        </button>
                    </nav>
                </div>

                {/* Message List Pane (List) */}
                <div className={`${isMobileView === 'list' ? 'flex' : 'hidden md:flex'} w-full md:w-96 flex-col border-r border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800`}>
                    <div className="p-4 border-b border-gray-200 dark:border-gray-700 space-y-3">
                        <div className="flex items-center gap-2">
                            <button onClick={() => setIsMobileView('folders')} className="md:hidden p-2 -ml-2 text-gray-400"><ArrowLeftIcon className="w-5 h-5" /></button>
                            <div className="relative flex-grow">
                                <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
