                                <input 
                                    type="date" 
                                    value={dateRange.end}
                                    onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))}
                                    className="w-full pl-7 pr-1 py-1.5 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded text-[10px] text-gray-700 dark:text-gray-300 focus:ring-1 focus:ring-blue-500"
                                />
                            </div>
                        </div>
                    </div>
                    <div className="overflow-y-auto scrollbar-thin">
                        {filteredMessages.map(msg => {
                            const isUnread = folder === 'inbox' && !msg.readBy.includes(currentStaff?.id || '');
