const ComposeModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    staff: any[];
    onSend: (data: any) => void;
}> = ({ isOpen, onClose, staff, onSend }) => {
    const [toIds, setToIds] = useState<string[]>([]);
    const [ccIds, setCcIds] = useState<string[]>([]);
    const [subject, setSubject] = useState('');
    const [body, setBody] = useState('');
    const [files, setFiles] = useState<File[]>([]);
    const [isUploading, setIsUploading] = useState(false);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (toIds.length === 0 || !subject.trim() || !body.trim()) {
            alert('Please specify recipients, a subject, and a message body.');
            return;
        }

        setIsUploading(true);
        try {
            const attachmentData = await Promise.all(
                files.map(async (file) => {
                    const url = await uploadFile(file, `internal_mail/${Date.now()}_${file.name}`);
                    return { name: file.name, url, type: file.type, size: file.size };
                })
            );
            onSend({ toIds, ccIds, subject, body, attachments: attachmentData });
        } finally {
            setIsUploading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-3xl p-0 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                <form onSubmit={handleSubmit} className="flex flex-col h-full">
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900">
                        <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            <EnvelopeIcon className="w-5 h-5 text-blue-600" /> New Internal Message
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    <div className="p-6 space-y-5 overflow-y-auto flex-grow bg-white dark:bg-gray-800 scrollbar-thin">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 flex items-center gap-1.5">
                                    <UserCircleIcon className="w-3 h-3" /> Recipients (To)*
                                </label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm text-gray-900 dark:text-white min-h-[120px] focus:ring-2 focus:ring-blue-500 transition-all shadow-inner"
                                    value={toIds}
                                    onChange={(e) => setToIds(Array.from(e.target.selectedOptions).map(o => (o as HTMLOptionElement).value))}
                                >
                                    {staff.map(s => <option key={s.id} value={s.id}>{s.fullName} ({s.email})</option>)}
                                </select>
                                <p className="text-[10px] text-gray-500 mt-1">Hold Ctrl/Cmd to select multiple recipients.</p>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 flex items-center gap-1.5">
                                    <EnvelopeIcon className="w-3 h-3" /> Carbon Copy (Cc)
                                </label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm text-gray-900 dark:text-white min-h-[120px] focus:ring-2 focus:ring-blue-500 transition-all shadow-inner"
                                    value={ccIds}
                                    onChange={(e) => setCcIds(Array.from(e.target.selectedOptions).map(o => (o as HTMLOptionElement).value))}
                                >
                                    {staff.map(s => <option key={s.id} value={s.id}>{s.fullName}</option>)}
                                </select>
                            </div>
                        </div>

                        <Input label="Subject Line*" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Subject of the message..." required />
                        <Textarea label="Message Details*" value={body} onChange={e => setBody(e.target.value)} rows={6} placeholder="Type your internal communication here..." required />

                        <div className="p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-100 dark:border-gray-700">
                            <label className="block text-xs font-bold text-gray-400 uppercase mb-3">Supporting Attachments</label>
                            <div className="flex flex-wrap gap-2 mb-4">
                                {files.map((f, i) => (
                                    <div key={i} className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 rounded-full text-[10px] font-black border border-blue-100 dark:border-blue-800 shadow-sm animate-in zoom-in duration-200">
                                        <span className="truncate max-w-[150px]">{f.name}</span>
                                        <button type="button" onClick={() => setFiles(prev => prev.filter((_, idx) => idx !== i))} className="hover:text-red-500 transition-colors"><XMarkIcon className="w-3.5 h-3.5" /></button>
                                    </div>
                                ))}
                            </div>
                            <label className="inline-flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 rounded-lg text-sm font-bold cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 transition-all border border-gray-200 dark:border-gray-700 shadow-sm">
                                <PaperClipIcon className="w-5 h-5 text-indigo-500" />
                                Attach Files
                                <input type="file" multiple className="sr-only" onChange={e => e.target.files && setFiles(prev => [...prev, ...Array.from(e.target.files!)])} />
                            </label>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Discard</Button>
                        <Button type="submit" isLoading={isUploading} icon={<PaperAirplaneIcon className="w-5 h-5 -rotate-45" />}>
                            Send Internal Message
                        </Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export default InternalMailingPage;

import React, { useState } from 'react';
import { XIcon } from './icons/XIcon';
import { 
  HomeIcon, 
  UsersIcon, 
  Cog6ToothIcon, 
  ChevronDownIcon, 
  DocumentPlusIcon, 
  BriefcaseIcon, 
  UserGroupIcon, 
  CalendarDaysIcon, 
  BookOpenIcon, 
  MegaphoneIcon, 
  ArrowRightOnRectangleIcon, 
  QuestionMarkCircleIcon, 
  ShieldCheckIcon, 
  AcademicCapIcon, 
  FaimLogoIcon, 
  TagIcon, 
  HashtagIcon,
  EnvelopeIcon
} from './icons/DummyIcons';
import { PermissionSet, CompanySettings } from '../types';

interface SidebarProps {
  isMobileOpen: boolean;
  onMobileClose: () => void;
  isDesktopCollapsed: boolean;
  activePage: string;
  setActivePage: (page: string) => void;
  staffPermissions: { [key: string]: PermissionSet };
  companySettings: CompanySettings;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  isMobileOpen, 
  onMobileClose,
  isDesktopCollapsed,
  activePage,
  setActivePage,
  staffPermissions,
  companySettings,
}) => {
  const [openMenus, setOpenMenus] = useState<Record<string, boolean>>({
    'Client Management': true,
    'Team': true
  });

  const toggleMenu = (name: string) => {
    setOpenMenus(prev => ({ ...prev, [name]: !prev[name] }));
  };

  const handleNavClick = (pageName: string) => {
    setActivePage(pageName);
    onMobileClose();
  };

  const allNavItems = [
    { name: 'Dashboard', icon: <HomeIcon />, href: '#', moduleId: 'Dashboard' },
    {
      name: 'Client Management',
      icon: <UsersIcon />,
      moduleId: 'Clients',
      subItems: [
        { name: 'Clients', icon: <UserGroupIcon />, href: '#', moduleId: 'Clients' },
        { name: 'Account Management', icon: <DocumentPlusIcon />, href: '#', moduleId: 'Account Management' },
      ],
    },
    { name: 'Promotions', icon: <TagIcon />, href: '#', moduleId: 'Promotions' },
    {
        name: 'Team',
        icon: <BriefcaseIcon />,
        moduleId: 'Team',
        subItems: [
            { name: 'Lead Management & Follow-Up', icon: <HashtagIcon />, href: '#', moduleId: 'Leads Management' },
            { name: 'Mailing', icon: <EnvelopeIcon />, href: '#', moduleId: 'Internal Mailing' },
            { name: 'Leave', icon: <ArrowRightOnRectangleIcon/>, href: '#', moduleId: 'Team' },
            { name: 'Knowledge Base', icon: <BookOpenIcon/>, href: '#', moduleId: 'Team' },
            { name: 'Event', icon: <CalendarDaysIcon/>, href: '#', moduleId: 'Team' },
            { name: 'Announcement', icon: <MegaphoneIcon/>, href: '#', moduleId: 'Team' },
        ]
    },
    { name: 'Administration', icon: <ShieldCheckIcon />, href: '#', moduleId: 'Administration'},
    { name: 'CEO Hub', icon: <AcademicCapIcon />, href: '#', moduleId: 'CEO Hub' },
    { name: 'Support', icon: <QuestionMarkCircleIcon />, href: '#', moduleId: 'Settings' },
    { name: 'Settings', icon: <Cog6ToothIcon />, href: '#', moduleId: 'Settings' },
  ];

  const visibleNavItems = allNavItems.filter(item => staffPermissions[item.moduleId]?.view).map(item => {
      if (item.subItems) {
          return {
              ...item,
              subItems: item.subItems.filter(subItem => staffPermissions[subItem.moduleId]?.view)
          };
      }
      return item;
  }).filter(item => !item.subItems || item.subItems.length > 0);

  const sidebarLogo = companySettings.appLogoDark || companySettings.appLogoLight || companySettings.logo;

  const sidebarContent = (
    <>
      <div className="flex flex-col items-center justify-center p-4 h-24 border-b border-gray-800 flex-shrink-0">
          {sidebarLogo ? (
            <img key={sidebarLogo} src={sidebarLogo} alt={`${companySettings.name} Logo`} className="w-12 h-12 object-contain" />
          ) : (
            <FaimLogoIcon className="w-10 h-10 text-white" />
          )}
          {!isDesktopCollapsed && (
            <h1 className="text-xl font-bold tracking-wider text-white mt-2">
              {companySettings.name.split(' ')[0]}<span className="text-blue-400">.</span>
            </h1>
          )}
        <button onClick={onMobileClose} className="md:hidden absolute top-5 right-4 text-gray-400 hover:text-white">
          <XIcon className="w-6 h-6" />
        </button>
      </div>
      <nav className="flex-grow p-2 overflow-y-auto">
        <ul>
          {visibleNavItems.map((item) => (
            <li key={item.name}>
              {item.subItems ? (
                <>
                  <button
                    onClick={() => toggleMenu(item.name)}
                    className={`flex items-center justify-between w-full gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                      activePage === item.name || item.subItems.some(sub => sub.name === activePage || (sub.name === 'Clients' && activePage === 'Client Details'))
                        ? 'text-white'
                        : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-6 h-6">{item.icon}</span>
                      {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                    </div>
                    {!isDesktopCollapsed && (
                      <ChevronDownIcon className={`w-5 h-5 transition-transform ${openMenus[item.name] ? 'rotate-180' : ''}`} />
                    )}
                  </button>
                  {(!isDesktopCollapsed && openMenus[item.name]) && (
                    <ul className="pl-6">
                      {item.subItems.map((subItem) => (
                        <li key={subItem.name}>
                          <a
                            href={subItem.href}
                            onClick={(e) => { e.preventDefault(); handleNavClick(subItem.name); }}
                            className={`flex items-center gap-3 pl-3 pr-4 py-2 my-1 rounded-md transition-colors duration-200 text-sm relative group ${
                              activePage === subItem.name || (subItem.name === 'Clients' && activePage === 'Client Details')
                                ? 'bg-blue-600 text-white shadow-lg'
                                : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                            }`}
                          >
                            <span className="w-6 h-6">{subItem.icon}</span>
                            <span className="font-medium">{subItem.name}</span>
                            {subItem.name === 'Mailing' && (
                                <span className="absolute right-2 top-1/2 -translate-y-1/2 w-2 h-2 bg-red-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(239,68,68,0.8)]"></span>
                            )}
                          </a>
                        </li>
                      ))}
                    </ul>
                  )}
                </>
              ) : (
                <a
                  href={item.href}
                  onClick={(e) => { e.preventDefault(); handleNavClick(item.name); }}
                  className={`flex items-center gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                    activePage === item.name
                      ? 'bg-blue-600 text-white shadow-lg'
                      : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                  }`}
                >
                  <span className="w-6 h-6">{item.icon}</span>
                  {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                </a>
              )}
            </li>
          ))}
        </ul>
      </nav>
    </>
  );

  return (
    <>
      <div
        className={`fixed inset-0 z-40 bg-black bg-opacity-50 transition-opacity md:hidden ${
          isMobileOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={onMobileClose}
      ></div>
      <aside
        className={`fixed inset-y-0 left-0 z-50 flex flex-col bg-gray-900 text-white w-64 transform transition-transform duration-300 ease-in-out md:hidden ${
          isMobileOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {sidebarContent}
      </aside>
      <aside className={`hidden md:flex flex-col bg-gray-900 text-white transition-all duration-300 ease-in-out ${isDesktopCollapsed ? 'w-20' : 'w-64'}`}>
        {sidebarContent}
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState, useMemo } from 'react';
import { 
    MagnifyingGlassIcon, 
    TrashIcon, 
    InboxArrowDownIcon, 
    PaperAirplaneIcon, 
    EnvelopeIcon,
    PaperClipIcon,
    ArrowDownTrayIcon,
    XMarkIcon,
    ArrowLeftIcon,
    PencilSquareIcon,
    PlusCircleIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Textarea } from '../components/ui/Input';
import { Badge } from '../components/ui/Badge';
import { useStaff, useActivityLogs } from '../hooks/useAppData';
import { useAuth } from '../context/AuthContext';
import { uploadFile } from '../services/storageService';

interface InternalMessage {
    id: string;
    senderId: string;
    senderName: string;
    toIds: string[];
    ccIds: string[];
    subject: string;
    body: string;
    attachments: { name: string; url: string; type: string; size: number }[];
    timestamp: string;
    readBy: string[];
}

const InternalMailingPage: React.FC = () => {
    const { staff } = useStaff();
    const { currentStaff } = useAuth();
    const { addActivityLog } = useActivityLogs();

    // State
    const [activeTab, setActiveTab] = useState<'inbox' | 'sent' | 'compose'>('inbox');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedMessage, setSelectedMessage] = useState<InternalMessage | null>(null);
    const [isSending, setIsSending] = useState(false);

    // Form State (Compose)
    const [composeData, setComposeData] = useState({ toIds: [] as string[], ccIds: [] as string[], subject: '', body: '' });
    const [pendingFiles, setPendingFiles] = useState<File[]>([]);

    // Mock Messages (Ideally synced with Firestore)
    const [messages, setMessages] = useState<InternalMessage[]>([
        {
            id: 'm-1',
            senderId: 'admin-1',
            senderName: 'System Operations',
            toIds: [currentStaff?.id || ''],
            ccIds: [],
            subject: 'System Maintenance Window: August 25th',
            body: 'Dear Team,\n\nPlease be advised that the portal will undergo routine maintenance this Sunday from 02:00 to 04:00 GMT.\n\nThank you,\nIT Dept.',
            attachments: [],
            timestamp: new Date(Date.now() - 3600000).toISOString(),
            readBy: []
        }
    ]);

    const filteredMessages = useMemo(() => {
        return messages.filter(m => {
            const isTarget = activeTab === 'inbox' 
                ? (m.toIds.includes(currentStaff?.id || '') || m.ccIds.includes(currentStaff?.id || ''))
                : m.senderId === currentStaff?.id;

            if (!isTarget) return false;

            const search = searchTerm.toLowerCase();
            return m.subject.toLowerCase().includes(search) || 
                   m.senderName.toLowerCase().includes(search) ||
                   m.body.toLowerCase().includes(search);
        }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [messages, activeTab, currentStaff, searchTerm]);

    const unreadCount = useMemo(() => {
        return messages.filter(m => 
            m.toIds.includes(currentStaff?.id || '') && !m.readBy.includes(currentStaff?.id || '')
        ).length;
    }, [messages, currentStaff]);

    const handleSelectMessage = (msg: InternalMessage) => {
        setSelectedMessage(msg);
        if (!msg.readBy.includes(currentStaff?.id || '')) {
            setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, readBy: [...m.readBy, currentStaff?.id || ''] } : m));
        }
    };

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        if (composeData.toIds.length === 0 || !composeData.subject.trim()) return;

        setIsSending(true);
        try {
            // Process Attachments
            const attachmentData = await Promise.all(
                pendingFiles.map(async (file) => {
                    const url = await uploadFile(file, `internal_mail/att/${Date.now()}_${file.name}`);
                    return { name: file.name, url, type: file.type, size: file.size };
                })
            );

            const newMessage: InternalMessage = {
                id: `msg-${Date.now()}`,
                senderId: currentStaff?.id || '0',
                senderName: currentStaff?.fullName || 'User',
                ...composeData,
                attachments: attachmentData,
                timestamp: new Date().toISOString(),
                readBy: [currentStaff?.id || '']
            };

            setMessages(prev => [newMessage, ...prev]);
            addActivityLog('Create', `Sent internal message: "${newMessage.subject}"`);

            // Reset
            setComposeData({ toIds: [], ccIds: [], subject: '', body: '' });
            setPendingFiles([]);
            setActiveTab('sent');
        } finally {
            setIsSending(false);
        }
    };

    const deleteMessage = (id: string) => {
        if (window.confirm("Permanently delete this message?")) {
            setMessages(prev => prev.filter(m => m.id !== id));
            setSelectedMessage(null);
        }
    };

    return (
        <div className="flex flex-col h-[calc(100vh-140px)] animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white flex items-center gap-3">
                        <EnvelopeIcon className="w-8 h-8 text-blue-600" /> Mailing
                    </h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Professional Internal Communication System</p>
                </div>
                {activeTab !== 'compose' && (
                    <Button onClick={() => { setActiveTab('compose'); setSelectedMessage(null); }} icon={<PlusCircleIcon className="w-5 h-5" />}>
                        Compose New
                    </Button>
                )}
            </div>

            {/* Navigation Tabs */}
            <div className="flex border-b border-gray-200 dark:border-gray-700 mb-6 bg-white dark:bg-gray-800 p-1 rounded-t-lg">
                <button 
                    onClick={() => { setActiveTab('inbox'); setSelectedMessage(null); }}
                    className={`flex items-center gap-2 px-6 py-3 font-bold transition-all border-b-2 ${activeTab === 'inbox' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                >
                    <InboxArrowDownIcon className="w-5 h-5" /> Inbox 
                    {unreadCount > 0 && <span className="bg-blue-600 text-white text-[10px] px-2 py-0.5 rounded-full">{unreadCount}</span>}
                </button>
                <button 
                    onClick={() => { setActiveTab('sent'); setSelectedMessage(null); }}
                    className={`flex items-center gap-2 px-6 py-3 font-bold transition-all border-b-2 ${activeTab === 'sent' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                >
                    <PaperAirplaneIcon className="w-5 h-5 -rotate-45" /> Sent Items
                </button>
                <button 
                    onClick={() => { setActiveTab('compose'); setSelectedMessage(null); }}
                    className={`flex items-center gap-2 px-6 py-3 font-bold transition-all border-b-2 ${activeTab === 'compose' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                >
                    <PencilSquareIcon className="w-5 h-5" /> Compose
                </button>
            </div>

            <div className="flex-grow flex bg-white dark:bg-gray-800 rounded-b-lg shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden relative">

                {/* LIST VIEW (Inbox & Sent) */}
                {activeTab !== 'compose' && (
                    <div className={`w-full md:w-96 flex flex-col border-r border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/10 ${selectedMessage ? 'hidden md:flex' : 'flex'}`}>
                        <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                            <div className="relative">
                                <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                <input 
                                    type="text"
                                    placeholder="Search mailing list..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full pl-9 pr-4 py-2 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white"
                                />
                            </div>
                        </div>
                        <div className="overflow-y-auto scrollbar-thin flex-grow">
                            {filteredMessages.map(msg => {
                                const isUnread = activeTab === 'inbox' && !msg.readBy.includes(currentStaff?.id || '');
                                return (
                                    <div 
                                        key={msg.id}
                                        onClick={() => handleSelectMessage(msg)}
                                        className={`p-4 border-b border-gray-100 dark:border-gray-700/50 cursor-pointer transition-colors hover:bg-white dark:hover:bg-gray-800/50 ${selectedMessage?.id === msg.id ? 'bg-white dark:bg-gray-800 border-l-4 border-l-blue-600 shadow-sm' : ''}`}
                                    >
                                        <div className="flex justify-between items-start mb-1">
                                            <span className={`text-xs font-black truncate ${isUnread ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500'}`}>
                                                {activeTab === 'inbox' ? msg.senderName : `To: ${msg.toIds.length} recipient(s)`}
                                            </span>
                                            <span className="text-[10px] text-gray-400 whitespace-nowrap">{new Date(msg.timestamp).toLocaleDateString()}</span>
                                        </div>
                                        <div className={`text-sm truncate ${isUnread ? 'font-black text-gray-900 dark:text-white' : 'text-gray-700 dark:text-gray-300'}`}>
                                            {msg.subject}
                                        </div>
                                        <div className="text-xs text-gray-400 truncate mt-1">{msg.body}</div>
                                        <div className="flex items-center gap-2 mt-2">
                                            {msg.attachments.length > 0 && <PaperClipIcon className="w-3 h-3 text-gray-400" />}
                                            {isUnread && <div className="w-2 h-2 rounded-full bg-blue-600 animate-pulse"></div>}
                                        </div>
                                    </div>
                                );
                            })}
                            {filteredMessages.length === 0 && <div className="p-10 text-center text-gray-400 italic text-sm">No messages found in this view.</div>}
                        </div>
                    </div>
                )}

                {/* CONTENT VIEW (Inbox & Sent) */}
                {activeTab !== 'compose' && (
                    <div className={`flex-grow flex-col bg-white dark:bg-gray-800 ${selectedMessage ? 'flex' : 'hidden md:flex'}`}>
                        {selectedMessage ? (
                            <div className="flex flex-col h-full animate-in slide-in-from-right-4 duration-300">
                                <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-900/30">
                                    <div className="flex items-center gap-3">
                                        <button onClick={() => setSelectedMessage(null)} className="md:hidden p-2 text-gray-500"><ArrowLeftIcon className="w-5 h-5" /></button>
                                        <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-black">
                                            {selectedMessage.senderName.substring(0, 2).toUpperCase()}
                                        </div>
                                        <div>
                                            <h3 className="font-bold text-gray-900 dark:text-white">{selectedMessage.senderName}</h3>
                                            <p className="text-[10px] text-gray-500 uppercase tracking-tighter">{new Date(selectedMessage.timestamp).toLocaleString()}</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        <button onClick={() => deleteMessage(selectedMessage.id)} className="p-2 text-gray-400 hover:text-red-500 transition-colors"><TrashIcon className="w-5 h-5" /></button>
                                    </div>
                                </div>

                                <div className="p-8 flex-grow overflow-y-auto">
                                    <div className="mb-8 border-b border-gray-100 dark:border-gray-700 pb-4">
                                        <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-3">{selectedMessage.subject}</h2>
                                        <div className="space-y-1">
                                            <div className="flex items-center gap-2 text-xs">
                                                <span className="font-bold text-gray-400 uppercase w-8">To:</span> 
                                                <span className="text-gray-700 dark:text-gray-300 font-semibold">{selectedMessage.toIds.map(id => staff.find(s => s.id === id)?.fullName).join(', ')}</span>
                                            </div>
                                            {selectedMessage.ccIds.length > 0 && (
                                                <div className="flex items-center gap-2 text-xs">
                                                    <span className="font-bold text-gray-400 uppercase w-8">Cc:</span> 
                                                    <span className="text-gray-700 dark:text-gray-300 italic">{selectedMessage.ccIds.map(id => staff.find(s => s.id === id)?.fullName).join(', ')}</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    <div className="prose prose-sm max-w-none dark:prose-invert text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                                        {selectedMessage.body}
                                    </div>

                                    {selectedMessage.attachments.length > 0 && (
                                        <div className="mt-12 pt-6 border-t border-gray-100 dark:border-gray-700">
                                            <h4 className="text-xs font-black text-gray-400 uppercase mb-4 flex items-center gap-2">
                                                <PaperClipIcon className="w-4 h-4" /> Attached Files ({selectedMessage.attachments.length})
                                            </h4>
                                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                                {selectedMessage.attachments.map((file, idx) => (
                                                    <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg hover:border-blue-400 transition-colors group">
                                                        <div className="flex items-center gap-3 overflow-hidden">
                                                            <div className="w-9 h-9 bg-white dark:bg-gray-800 rounded border border-gray-100 dark:border-gray-700 flex items-center justify-center text-blue-600 font-black text-[10px]">
                                                                {file.type.split('/')[1]?.toUpperCase() || 'FIL'}
                                                            </div>
                                                            <div className="overflow-hidden">
                                                                <p className="text-xs font-bold text-gray-800 dark:text-white truncate">{file.name}</p>
                                                                <p className="text-[10px] text-gray-500">{(file.size / 1024).toFixed(1)} KB</p>
                                                            </div>
                                                        </div>
                                                        <a href={file.url} download className="p-2 text-gray-400 hover:text-blue-600 transition-colors">
                                                            <ArrowDownTrayIcon className="w-4 h-4" />
                                                        </a>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center text-gray-400 p-10 text-center opacity-30">
                                <EnvelopeIcon className="w-24 h-24 mb-4" />
                                <p className="text-xl font-bold">Secure Mail Workspace</p>
                                <p className="text-sm max-w-xs">Select a conversation from the left to read its contents or create a new message.</p>
                            </div>
                        )}
                    </div>
                )}

                {/* COMPOSE VIEW */}
                {activeTab === 'compose' && (
                    <div className="w-full flex flex-col h-full bg-white dark:bg-gray-800 overflow-y-auto p-6 scrollbar-thin">
                        <form onSubmit={handleSendMessage} className="max-w-4xl mx-auto w-full space-y-6">
                            <div className="flex justify-between items-center mb-4">
                                <h3 className="text-xl font-black text-gray-800 dark:text-white">Draft Message</h3>
                                <div className="flex gap-3">
