import React, { useState, useMemo } from 'react';
import { Client, Property } from '../types';
import { 
    ArrowLeftIcon, 
    UserCheckIcon, 
    CheckCircleIcon, 
    ExclamationTriangleIcon,
    BanknotesIcon,
    MapPinIcon,
    ShieldCheckIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Select, Input } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { Badge } from '../components/ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { useClients } from '../hooks/useAppData';

interface AllocatePlotPageProps {
    onBack: () => void;
    clients: Client[];
    properties: Property[];
}

const AllocatePlotPage: React.FC<AllocatePlotPageProps> = ({ onBack, clients, properties }) => {
    const { saveClient } = useClients();

    // Selection State
    const [selectedClientId, setSelectedClientId] = useState<number | ''>('');
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [selectedPlots, setSelectedPlots] = useState<string[]>([]);
    const [isSaving, setIsSaving] = useState(false);
    const [allocationSuccess, setAllocationSuccess] = useState(false);

    // Data Derivation
    const selectedClient = useMemo(() => clients.find(c => c.id === selectedClientId), [selectedClientId, clients]);
    const selectedProperty = useMemo(() => properties.find(p => p.id === selectedPropertyId), [selectedPropertyId, properties]);

    // Qualification Logic
    const qualification = useMemo(() => {
        if (!selectedClient) return { isQualified: false, percentage: 0 };
        const total = selectedClient.payment.total || 1;
        const paid = selectedClient.payment.paid || 0;
        const percentage = (paid / total) * 100;
        return {
            percentage: Math.round(percentage),
            isQualified: percentage >= 70
        };
    }, [selectedClient]);

    const allocationType = useMemo(() => {
        if (!selectedClient) return 'N/A';
        return selectedClient.plot && selectedClient.plot !== 'N/A' ? 'Re-allocation' : 'First-time Allocation';
    }, [selectedClient]);

    // Simulated Plot Availability (In a real app, this checks specific plot number statuses in the DB)
    const availablePlotsList = useMemo(() => {
        if (!selectedProperty) return [];
        // Extracting sample plot numbers based on inventory count for UI demonstration
        const totalPlots = selectedProperty.inventory.reduce((acc, inv) => acc + inv.count, 0);
        return Array.from({ length: totalPlots }).map((_, i) => `${selectedProperty.location.substring(0,3).toUpperCase()}-${100 + i}`);
    }, [selectedProperty]);

    const handlePlotToggle = (plot: string) => {
        setSelectedPlots(prev => 
            prev.includes(plot) ? prev.filter(p => p !== plot) : [...prev, plot]
        );
    };

    const handleConfirmAllocation = async () => {
        if (!selectedClient || selectedPlots.length === 0) return;

        setIsSaving(true);
        try {
            const updatedClient: Client = {
                ...selectedClient,
                plot: selectedPlots.join(', '),
                status: 'Active Client', // Ensure status reflects active allocation
                interactions: [
                    {
                        id: Date.now(),
                        type: 'Note',
                        date: new Date().toISOString(),
                        agent: 'System Admin',
                        notes: `Plots ${selectedPlots.join(', ')} allocated at ${selectedProperty?.location}.`
                    },
                    ...selectedClient.interactions
                ]
            };

            await saveClient(updatedClient);
            setAllocationSuccess(true);
            setTimeout(() => {
                onBack();
            }, 2000);
        } catch (error) {
            alert('Failed to save allocation. Please try again.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to Administration
                    </button>
                    <div className="flex items-center gap-4">
                        <UserCheckIcon className="w-10 h-10 text-blue-600 dark:text-blue-400" />
                        <div>
                            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Allocate Plot</h1>
                            <p className="text-gray-500 dark:text-gray-400 mt-1">Verify qualification and assign plot numbers.</p>
                        </div>
                    </div>
                </div>
            </div>

            {allocationSuccess && (
                <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded shadow-md animate-bounce">
                    <div className="flex items-center">
                        <CheckCircleIcon className="w-6 h-6 mr-2" />
                        <p className="font-bold">Allocation Successful! Redirecting...</p>
                    </div>
                </div>
            )}

            {/* Selection Area */}
            <Card className="bg-gray-50/50 dark:bg-gray-900/20">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <Select 
                        label="1. Select Client Name" 
                        value={selectedClientId} 
                        onChange={(e) => {
                            setSelectedClientId(Number(e.target.value));
                            setSelectedPlots([]);
                        }}
                    >
                        <option value="">-- Choose a Client --</option>
                        {clients.map(client => (
                            <option key={client.id} value={client.id}>{client.name}</option>
                        ))}
                    </Select>
                    <Select 
                        label="2. Select Property Location" 
                        value={selectedPropertyId} 
                        onChange={(e) => {
                            setSelectedPropertyId(Number(e.target.value));
                            setSelectedPlots([]);
                        }}
                    >
                        <option value="">-- Choose a Location --</option>
                        {properties.map(prop => (
                            <option key={prop.id} value={prop.id}>{prop.location}</option>
                        ))}
                    </Select>
                </div>
            </Card>

            {selectedClient && selectedProperty && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Qualification Panel */}
                    <div className="lg:col-span-1 space-y-6">
                        <Card title="Client Qualification Status">
                            <div className="space-y-6">
                                <div className="text-center p-4 bg-white dark:bg-gray-900 rounded-lg border border-gray-100 dark:border-gray-800">
                                    <p className="text-xs font-bold text-gray-400 uppercase mb-2">Payment Progress</p>
                                    <div className="text-4xl font-black text-gray-900 dark:text-white mb-2">{qualification.percentage}%</div>
                                    <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 mb-4">
                                        <div 
                                            className={`h-2 rounded-full transition-all duration-1000 ${qualification.isQualified ? 'bg-green-500' : 'bg-amber-500'}`} 
                                            style={{ width: `${qualification.percentage}%` }}
                                        ></div>
                                    </div>
                                    {qualification.isQualified ? (
                                        <Badge variant="success" className="text-xs py-1 px-3">
                                            <CheckCircleIcon className="w-3 h-3 inline mr-1" /> Qualified for Allocation
                                        </Badge>
                                    ) : (
                                        <Badge variant="danger" className="text-xs py-1 px-3">
                                            <ExclamationTriangleIcon className="w-3 h-3 inline mr-1" /> Not Yet Qualified
                                        </Badge>
                                    )}
                                </div>

                                <div className="space-y-3">
                                    <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-800">
                                        <span className="text-sm text-gray-500">Allocation Type</span>
                                        <span className="text-sm font-bold text-gray-800 dark:text-gray-200">{allocationType}</span>
                                    </div>
                                    <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-800">
                                        <span className="text-sm text-gray-500">Current Plot(s)</span>
                                        <span className="text-sm font-bold text-indigo-600">{selectedClient.plot || 'None'}</span>
                                    </div>
                                    <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-800">
                                        <span className="text-sm text-gray-500">Plot Type Purchased</span>
                                        <span className="text-sm font-bold text-gray-800 dark:text-gray-200">{selectedClient.propertyType}</span>
                                    </div>
                                </div>
                            </div>
                        </Card>

                        <Card className="bg-blue-50/50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-800">
                            <h4 className="text-sm font-bold text-blue-800 dark:text-blue-300 flex items-center gap-2 mb-2">
                                <BanknotesIcon className="w-4 h-4" /> Financial Summary
                            </h4>
                            <div className="text-xs space-y-1.5 text-blue-700 dark:text-blue-400">
                                <p>Total Price: <span className="font-bold">{formatCurrency(selectedClient.payment.total)}</span></p>
                                <p>Total Paid: <span className="font-bold">{formatCurrency(selectedClient.payment.paid)}</span></p>
                                <p>Outstanding: <span className="font-bold">{formatCurrency(selectedClient.payment.balance)}</span></p>
                            </div>
                        </Card>
                    </div>

                    {/* Plot Selection */}
                    <div className="lg:col-span-2 space-y-6">
                        <Card 
                            title={`3. Select Plot(s) for ${selectedProperty.location}`}
                            action={
                                <div className="text-xs font-bold text-gray-400 uppercase">
                                    {selectedPlots.length} Plots Selected
                                </div>
                            }
                        >
                            {!qualification.isQualified ? (
                                <div className="p-10 text-center space-y-4">
                                    <ShieldCheckIcon className="w-16 h-16 text-gray-300 mx-auto" />
                                    <p className="text-gray-500 max-w-xs mx-auto">Plot selection is restricted until the client completes at least 70% of the payment.</p>
                                </div>
                            ) : (
                                <div className="space-y-6">
                                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 max-h-[400px] overflow-y-auto p-1 scrollbar-thin">
                                        {availablePlotsList.map(plot => {
                                            const isSelected = selectedPlots.includes(plot);
                                            return (
                                                <button
                                                    key={plot}
                                                    onClick={() => handlePlotToggle(plot)}
                                                    className={`p-3 rounded-lg border text-sm font-bold transition-all flex flex-col items-center gap-1 ${
                                                        isSelected 
                                                        ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' 
                                                        : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:border-blue-400'
                                                    }`}
                                                >
                                                    <MapPinIcon className={`w-4 h-4 ${isSelected ? 'text-white' : 'text-gray-400'}`} />
                                                    {plot}
                                                    <div className={`text-[10px] uppercase font-black px-1.5 rounded-full ${isSelected ? 'bg-blue-500 text-white' : 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'}`}>
                                                        {isSelected ? 'Selected' : 'Available'}
                                                    </div>
                                                </button>
                                            );
                                        })}
                                    </div>

                                    {/* Confirmation Summary Panel */}
                                    {selectedPlots.length > 0 && (
                                        <div className="mt-8 p-6 bg-gray-50 dark:bg-gray-900 rounded-xl border-2 border-dashed border-gray-200 dark:border-gray-700 animate-in slide-in-from-bottom-2">
                                            <h4 className="text-sm font-black text-gray-800 dark:text-white uppercase tracking-widest mb-4">Allocation Confirmation</h4>
                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Client Name</p>
                                                    <p className="text-sm font-bold">{selectedClient.name}</p>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Location</p>
                                                    <p className="text-sm font-bold">{selectedProperty.location}</p>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Selected Plot Numbers</p>
                                                    <div className="flex flex-wrap gap-2">
                                                        {selectedPlots.map(p => <Badge key={p} variant="purple">{p}</Badge>)}
                                                    </div>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Plot Sizes</p>
                                                    <p className="text-sm font-bold">{selectedProperty.inventory.map(inv => inv.size).join(', ')}</p>
                                                </div>
                                            </div>

                                            <div className="mt-8 flex justify-end">
                                                <Button 
                                                    onClick={handleConfirmAllocation} 
                                                    isLoading={isSaving}
                                                    className="px-10 py-3 shadow-lg hover:shadow-xl transition-all"
                                                    icon={<CheckCircleIcon className="w-5 h-5" />}
                                                >
                                                    Confirm & Save Allocation
                                                </Button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </Card>
                    </div>
                </div>
            )}

            {!selectedClient && (
                <div className="bg-white dark:bg-gray-800 p-20 rounded-xl border border-gray-200 dark:border-gray-700 text-center opacity-60">
                    <UserCheckIcon className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <h3 className="text-lg font-bold text-gray-800 dark:text-white">Ready to Allocate</h3>
                    <p className="text-gray-500 max-w-xs mx-auto">Please select a client and their intended property location above to begin the allocation workflow.</p>
                </div>
            )}

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 5px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
        </div>
    );
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

export default AllocatePlotPage;

import React, { useState, useMemo } from 'react';
import { Client, Property } from '../types';
import { 
    ArrowLeftIcon, 
    UserCheckIcon, 
    CheckCircleIcon, 
    ExclamationTriangleIcon,
    BanknotesIcon,
    MapPinIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    EyeIcon,
    ChartBarIcon,
    FunnelIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Select, Input } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { Badge } from '../components/ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { useClients } from '../hooks/useAppData';

interface AllocatePlotPageProps {
    onBack: () => void;
    clients: Client[];
    properties: Property[];
}

const AllocatePlotPage: React.FC<AllocatePlotPageProps> = ({ onBack, clients, properties }) => {
    const { saveClient } = useClients();

    // Selection State
    const [selectedClientId, setSelectedClientId] = useState<number | ''>('');
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [selectedPlots, setSelectedPlots] = useState<string[]>([]);
    const [isSaving, setIsSaving] = useState(false);
    const [allocationSuccess, setAllocationSuccess] = useState(false);

    // Master Allocation View State
    const [isViewAllOpen, setIsViewAllOpen] = useState(false);
    const [viewAllLocationId, setViewAllLocationId] = useState<number | ''>('');
    const [statusFilter, setStatusFilter] = useState<'All' | 'Allocated' | 'Available'>('All');
    const [sizeFilter, setSizeFilter] = useState<string>('All');

    // Data Derivation for Active Allocation
    const selectedClient = useMemo(() => clients.find(c => c.id === selectedClientId), [selectedClientId, clients]);
    const selectedProperty = useMemo(() => properties.find(p => p.id === selectedPropertyId), [selectedPropertyId, properties]);

    // Data Derivation for Master View
    const masterViewProperty = useMemo(() => properties.find(p => p.id === viewAllLocationId), [viewAllLocationId, properties]);

    const masterPlotList = useMemo(() => {
        if (!masterViewProperty) return [];

        // Generate plots for this property
        const totalCount = masterViewProperty.inventory.reduce((sum, inv) => sum + inv.count, 0);
        const prefix = masterViewProperty.location.substring(0, 3).toUpperCase();

        // Map plots to sizes
        const allPlots: { plotNumber: string; size: string; allocatedTo: string | null }[] = [];
        let plotCounter = 100;

        masterViewProperty.inventory.forEach(inv => {
            for (let i = 0; i < inv.count; i++) {
                const pNum = `${prefix}-${plotCounter++}`;
                // Check if any client has this plot assigned
                const client = clients.find(c => c.location === masterViewProperty.location && c.plot?.includes(pNum));

                allPlots.push({
                    plotNumber: pNum,
                    size: inv.size,
                    allocatedTo: client ? client.name : null
                });
            }
        });

        // Apply filters
        return allPlots.filter(p => {
            const matchesStatus = statusFilter === 'All' || 
                (statusFilter === 'Allocated' && p.allocatedTo !== null) || 
                (statusFilter === 'Available' && p.allocatedTo === null);
            const matchesSize = sizeFilter === 'All' || p.size === sizeFilter;
            return matchesStatus && matchesSize;
        });
    }, [masterViewProperty, clients, statusFilter, sizeFilter]);

    const masterStats = useMemo(() => {
        if (!masterViewProperty) return null;
        const total = masterPlotList.length;
        const allocated = masterPlotList.filter(p => p.allocatedTo !== null).length;
        const available = total - allocated;

        // Size breakdown for available plots
        const sizeBreakdown: Record<string, number> = {};
        masterPlotList.forEach(p => {
            if (p.allocatedTo === null) {
                sizeBreakdown[p.size] = (sizeBreakdown[p.size] || 0) + 1;
            }
        });

        return { total, allocated, available, sizeBreakdown };
    }, [masterPlotList, masterViewProperty]);

    // Qualification Logic
    const qualification = useMemo(() => {
        if (!selectedClient) return { isQualified: false, percentage: 0 };
        const total = selectedClient.payment.total || 1;
        const paid = selectedClient.payment.paid || 0;
        const percentage = (paid / total) * 100;
        return {
            percentage: Math.round(percentage),
            isQualified: percentage >= 70
        };
    }, [selectedClient]);

    const allocationType = useMemo(() => {
        if (!selectedClient) return 'N/A';
        return selectedClient.plot && selectedClient.plot !== 'N/A' ? 'Re-allocation' : 'First-time Allocation';
    }, [selectedClient]);

    const availablePlotsList = useMemo(() => {
        if (!selectedProperty) return [];
        const totalPlots = selectedProperty.inventory.reduce((acc, inv) => acc + inv.count, 0);
        return Array.from({ length: totalPlots }).map((_, i) => `${selectedProperty.location.substring(0,3).toUpperCase()}-${100 + i}`);
    }, [selectedProperty]);

    const handlePlotToggle = (plot: string) => {
        setSelectedPlots(prev => 
            prev.includes(plot) ? prev.filter(p => p !== plot) : [...prev, plot]
        );
    };

    const handleConfirmAllocation = async () => {
        if (!selectedClient || selectedPlots.length === 0) return;

        setIsSaving(true);
        try {
            const updatedClient: Client = {
                ...selectedClient,
                plot: selectedPlots.join(', '),
                status: 'Active Client',
                interactions: [
                    {
                        id: Date.now(),
                        type: 'Note',
                        date: new Date().toISOString(),
                        agent: 'System Admin',
                        notes: `Plots ${selectedPlots.join(', ')} allocated at ${selectedProperty?.location}.`
                    },
                    ...selectedClient.interactions
                ]
            };

            await saveClient(updatedClient);
            setAllocationSuccess(true);
            setTimeout(() => {
                onBack();
            }, 2000);
        } catch (error) {
            alert('Failed to save allocation. Please try again.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to Administration
                    </button>
                    <div className="flex items-center gap-4">
                        <UserCheckIcon className="w-10 h-10 text-blue-600 dark:text-blue-400" />
                        <div>
                            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Allocate Plot</h1>
                            <p className="text-gray-500 dark:text-gray-400 mt-1">Verify qualification and assign plot numbers.</p>
                        </div>
                    </div>
                </div>
            </div>

            {allocationSuccess && (
                <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded shadow-md animate-bounce">
                    <div className="flex items-center">
                        <CheckCircleIcon className="w-6 h-6 mr-2" />
                        <p className="font-bold">Allocation Successful! Redirecting...</p>
                    </div>
                </div>
            )}

            {/* Selection Area */}
            <Card className="bg-white dark:bg-gray-800">
                <div className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <Select 
                            label="1. Select Client Name" 
                            value={selectedClientId} 
                            onChange={(e) => {
                                setSelectedClientId(Number(e.target.value));
                                setSelectedPlots([]);
                            }}
                        >
                            <option value="">-- Choose a Client --</option>
                            {clients.map(client => (
                                <option key={client.id} value={client.id}>{client.name}</option>
                            ))}
                        </Select>
                        <Select 
                            label="2. Select Location" 
                            value={selectedPropertyId} 
                            onChange={(e) => {
                                setSelectedPropertyId(Number(e.target.value));
                                setSelectedPlots([]);
                            }}
                        >
                            <option value="">-- Choose a Location --</option>
                            {properties.map(prop => (
                                <option key={prop.id} value={prop.id}>{prop.location}</option>
                            ))}
                        </Select>
                    </div>

                    {/* Master View Toggle */}
                    <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                        <button 
                            onClick={() => setIsViewAllOpen(!isViewAllOpen)}
                            className="flex items-center gap-2 text-sm font-bold text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 transition-colors"
                        >
                            <EyeIcon className="w-5 h-5" />
                            View All Allocations
                            <ChevronDownIcon className={`w-4 h-4 transition-transform ${isViewAllOpen ? 'rotate-180' : ''}`} />
                        </button>

                        {isViewAllOpen && (
                            <div className="mt-4 p-5 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-800 animate-in slide-in-from-top-2">
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                                    <Select 
                                        label="Select Location to View" 
                                        value={viewAllLocationId} 
                                        onChange={(e) => setViewAllLocationId(e.target.value ? Number(e.target.value) : '')}
                                    >
                                        <option value="">-- Select a Location --</option>
                                        {properties.map(prop => (
                                            <option key={prop.id} value={prop.id}>{prop.location}</option>
                                        ))}
                                    </Select>
                                    <Select label="Filter by Status" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as any)}>
                                        <option value="All">All Plots</option>
                                        <option value="Allocated">Allocated Only</option>
                                        <option value="Available">Available Only</option>
                                    </Select>
                                    <Select label="Filter by Size" value={sizeFilter} onChange={(e) => setSizeFilter(e.target.value)}>
                                        <option value="All">All Sizes</option>
                                        <option value="70x100 ft">70x100 ft</option>
                                        <option value="70x50 ft">70x50 ft</option>
                                        <option value="60x80 ft">60x80 ft</option>
                                    </Select>
                                </div>

                                {masterViewProperty ? (
                                    <div className="space-y-6">
                                        <TableContainer className="max-h-[400px] overflow-y-auto">
                                            <table className="w-full text-sm text-left">
                                                <Thead>
                                                    <tr>
                                                        <Th>Plot Number</Th>
                                                        <Th>Allocated Client</Th>
                                                        <Th>Plot Size</Th>
                                                        <Th className="text-center">Status</Th>
                                                    </tr>
                                                </Thead>
                                                <Tbody>
                                                    {masterPlotList.map((p, idx) => (
                                                        <Tr key={idx}>
                                                            <Td className="font-mono font-bold text-gray-900 dark:text-white">{p.plotNumber}</Td>
                                                            <Td className="text-gray-600 dark:text-gray-400">
                                                                {p.allocatedTo || <span className="text-gray-300">—</span>}
                                                            </Td>
                                                            <Td>{p.size}</Td>
                                                            <Td className="text-center">
                                                                <Badge variant={p.allocatedTo ? 'danger' : 'success'}>
                                                                    {p.allocatedTo ? 'Allocated' : 'Available'}
                                                                </Badge>
                                                            </Td>
                                                        </Tr>
                                                    ))}
                                                </Tbody>
                                            </table>
                                        </TableContainer>

                                        {/* Master Summary Stats */}
                                        {masterStats && (
                                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 pt-4 border-t border-gray-100 dark:border-gray-800">
                                                <div className="p-4 bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-100 dark:border-gray-700">
                                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Plots</p>
                                                    <div className="text-2xl font-black text-gray-900 dark:text-white">{masterStats.total}</div>
                                                </div>
                                                <div className="p-4 bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-100 dark:border-gray-700">
                                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Allocated</p>
                                                    <div className="text-2xl font-black text-red-600">{masterStats.allocated}</div>
                                                </div>
                                                <div className="p-4 bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-100 dark:border-gray-700">
                                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Available</p>
                                                    <div className="text-2xl font-black text-green-600">{masterStats.available}</div>
                                                </div>
                                                <div className="p-4 bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-100 dark:border-gray-700">
                                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Available by Size</p>
                                                    <div className="flex flex-col gap-1 mt-1">
                                                        {Object.entries(masterStats.sizeBreakdown).map(([size, count]) => (
                                                            <div key={size} className="flex justify-between text-xs font-bold">
                                                                <span className="text-gray-500">{size}:</span>
                                                                <span className="text-indigo-600">{count}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                ) : (
                                    <div className="text-center py-10 opacity-40">
                                        <ChartBarIcon className="w-12 h-12 mx-auto mb-2 text-gray-400" />
                                        <p className="text-sm font-semibold">Select a location to see current availability stats.</p>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </Card>

            {selectedClient && selectedProperty && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Qualification Panel */}
                    <div className="lg:col-span-1 space-y-6">
                        <Card title="Client Qualification Status">
                            <div className="space-y-6">
                                <div className="text-center p-4 bg-white dark:bg-gray-900 rounded-lg border border-gray-100 dark:border-gray-800">
                                    <p className="text-xs font-bold text-gray-400 uppercase mb-2">Payment Progress</p>
                                    <div className="text-4xl font-black text-gray-900 dark:text-white mb-2">{qualification.percentage}%</div>
                                    <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 mb-4">
                                        <div 
                                            className={`h-2 rounded-full transition-all duration-1000 ${qualification.isQualified ? 'bg-green-500' : 'bg-amber-500'}`} 
                                            style={{ width: `${qualification.percentage}%` }}
                                        ></div>
                                    </div>
                                    {qualification.isQualified ? (
                                        <Badge variant="success" className="text-xs py-1 px-3">
                                            <CheckCircleIcon className="w-3 h-3 inline mr-1" /> Qualified for Allocation
                                        </Badge>
                                    ) : (
                                        <Badge variant="danger" className="text-xs py-1 px-3">
                                            <ExclamationTriangleIcon className="w-3 h-3 inline mr-1" /> Not Yet Qualified
                                        </Badge>
                                    )}
                                </div>

                                <div className="space-y-3">
                                    <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-800">
                                        <span className="text-sm text-gray-500">Allocation Type</span>
                                        <span className="text-sm font-bold text-gray-800 dark:text-gray-200">{allocationType}</span>
                                    </div>
                                    <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-800">
                                        <span className="text-sm text-gray-500">Current Plot(s)</span>
                                        <span className="text-sm font-bold text-indigo-600">{selectedClient.plot || 'None'}</span>
                                    </div>
                                    <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-800">
                                        <span className="text-sm text-gray-500">Plot Type Purchased</span>
                                        <span className="text-sm font-bold text-gray-800 dark:text-gray-200">{selectedClient.propertyType}</span>
                                    </div>
                                </div>
                            </div>
                        </Card>

                        <Card className="bg-blue-50/50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-800">
                            <h4 className="text-sm font-bold text-blue-800 dark:text-blue-300 flex items-center gap-2 mb-2">
                                <BanknotesIcon className="w-4 h-4" /> Financial Summary
                            </h4>
                            <div className="text-xs space-y-1.5 text-blue-700 dark:text-blue-400">
                                <p>Total Price: <span className="font-bold">{formatCurrency(selectedClient.payment.total)}</span></p>
                                <p>Total Paid: <span className="font-bold">{formatCurrency(selectedClient.payment.paid)}</span></p>
                                <p>Outstanding: <span className="font-bold">{formatCurrency(selectedClient.payment.balance)}</span></p>
                            </div>
                        </Card>
                    </div>

                    {/* Plot Selection */}
                    <div className="lg:col-span-2 space-y-6">
                        <Card 
                            title={`3. Select Plot(s) for ${selectedProperty.location}`}
                            action={
                                <div className="text-xs font-bold text-gray-400 uppercase">
                                    {selectedPlots.length} Plots Selected
                                </div>
                            }
                        >
                            {!qualification.isQualified ? (
                                <div className="p-10 text-center space-y-4">
                                    <ShieldCheckIcon className="w-16 h-16 text-gray-300 mx-auto" />
                                    <p className="text-gray-500 max-w-xs mx-auto">Plot selection is restricted until the client completes at least 70% of the payment.</p>
                                </div>
                            ) : (
                                <div className="space-y-6">
                                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 max-h-[400px] overflow-y-auto p-1 scrollbar-thin">
                                        {availablePlotsList.map(plot => {
                                            const isSelected = selectedPlots.includes(plot);
                                            return (
                                                <button
                                                    key={plot}
                                                    onClick={() => handlePlotToggle(plot)}
                                                    className={`p-3 rounded-lg border text-sm font-bold transition-all flex flex-col items-center gap-1 ${
                                                        isSelected 
                                                        ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' 
                                                        : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:border-blue-400'
                                                    }`}
                                                >
                                                    <MapPinIcon className={`w-4 h-4 ${isSelected ? 'text-white' : 'text-gray-400'}`} />
                                                    {plot}
                                                    <div className={`text-[10px] uppercase font-black px-1.5 rounded-full ${isSelected ? 'bg-blue-500 text-white' : 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'}`}>
                                                        {isSelected ? 'Selected' : 'Available'}
                                                    </div>
                                                </button>
                                            );
                                        })}
                                    </div>

                                    {/* Confirmation Summary Panel */}
                                    {selectedPlots.length > 0 && (
                                        <div className="mt-8 p-6 bg-gray-50 dark:bg-gray-900 rounded-xl border-2 border-dashed border-gray-200 dark:border-gray-700 animate-in slide-in-from-bottom-2">
                                            <h4 className="text-sm font-black text-gray-800 dark:text-white uppercase tracking-widest mb-4">Allocation Confirmation</h4>
                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Client Name</p>
                                                    <p className="text-sm font-bold">{selectedClient.name}</p>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Location</p>
                                                    <p className="text-sm font-bold">{selectedProperty.location}</p>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Selected Plot Numbers</p>
                                                    <div className="flex flex-wrap gap-2">
                                                        {selectedPlots.map(p => <Badge key={p} variant="purple">{p}</Badge>)}
                                                    </div>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Plot Sizes</p>
                                                    <p className="text-sm font-bold">{selectedProperty.inventory.map(inv => inv.size).join(', ')}</p>
                                                </div>
                                            </div>

                                            <div className="mt-8 flex justify-end">
                                                <Button 
                                                    onClick={handleConfirmAllocation} 
                                                    isLoading={isSaving}
                                                    className="px-10 py-3 shadow-lg hover:shadow-xl transition-all"
                                                    icon={<CheckCircleIcon className="w-5 h-5" />}
                                                >
                                                    Confirm & Save Allocation
                                                </Button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </Card>
                    </div>
                </div>
            )}

            {!selectedClient && (
                <div className="bg-white dark:bg-gray-800 p-20 rounded-xl border border-gray-200 dark:border-gray-700 text-center opacity-60">
                    <UserCheckIcon className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <h3 className="text-lg font-bold text-gray-800 dark:text-white">Ready to Allocate</h3>
                    <p className="text-gray-500 max-w-xs mx-auto">Please select a client and their intended property location above to begin the allocation workflow.</p>
                </div>
            )}

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 5px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
        </div>
    );
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

export default AllocatePlotPage;

