                                {masterViewProperty && (
                                    <TableContainer className="max-h-[400px] overflow-y-auto">
                                        <table className="w-full text-sm text-left">
                                            <Thead>
                                                <tr>
                                                    <Th>Plot Number</Th>
                                                    <Th>Allocated Client</Th>
