                                                            {p.plotNumber}
                                                        </Td>
                                                        <Td className="text-gray-600 dark:text-gray-400">
                                                            <div className="flex flex-col">
                                                                <span>{p.allocatedTo || <span className="text-gray-300">—</span>}</span>
                                                                {p.isProvisional && (
                                                                    <span className="text-[10px] text-amber-600 font-bold uppercase tracking-tighter">
                                                                        Provisionally Allocated – Pending 70% Payment
                                                                    </span>
                                                                )}
                                                            </div>
                                                        </Td>
                                                        <Td>{p.size}</Td>
                                                        <Td className="text-center">
                                                            <Badge variant={p.allocatedTo ? (p.isProvisional ? 'warning' : 'danger') : 'success'}>
                                                                {p.allocatedTo ? (p.isProvisional ? 'Provisional' : 'Permanent') : 'Available'}
                                                            </Badge>
                                                        </Td>
                                                    </Tr>
                                                ))}
                                            </Tbody>
                                        </table>
                                    </TableContainer>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </Card>

            {selectedClient && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4">
                    {/* Qualification Panel */}
                    <div className="lg:col-span-1 space-y-6">
                        <Card title="Client Qualification Status">
                            <div className="space-y-6">
                                <div className="p-4 rounded-lg border flex flex-col items-center text-center gap-2 bg-gray-50 dark:bg-gray-900/50 border-gray-100 dark:border-gray-700">
                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Payment Qualification</p>
                                    <div className={`text-sm font-bold flex items-center gap-2 ${qualification.isQualified ? 'text-green-600' : 'text-amber-600'}`}>
                                        {qualification.isQualified ? <CheckCircleIcon className="w-5 h-5" /> : <ClockIcon className="w-5 h-5" />}
                                        {qualification.status}
                                    </div>
                                    <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 mt-2">
                                        <div 
                                            className={`h-2 rounded-full transition-all duration-1000 ${qualification.isQualified ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.4)]' : 'bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.4)]'}`} 
                                            style={{ width: `${qualification.percentage}%` }}
                                        ></div>
                                    </div>
                                    <p className="text-xs font-bold text-gray-500 mt-1">{qualification.percentage}% of total paid</p>
                                </div>

                                <div className="p-4 rounded-lg border flex flex-col items-center text-center gap-2 bg-gray-50 dark:bg-gray-900/50 border-gray-100 dark:border-gray-700">
                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Allocation Permanence</p>
                                    <Badge variant={qualification.isQualified ? 'success' : 'warning'} className="text-xs py-1 px-4">
                                        {qualification.isQualified ? 'Permanent' : 'Provisional'}
                                    </Badge>
                                    <p className="text-[10px] text-gray-500 leading-tight mt-1">
                                        {qualification.isQualified 
                                            ? 'Client has met the 70% threshold. Plots are permanently assigned.' 
                                            : 'Plots assigned remain provisional until the 70% payment threshold is met.'}
                                    </p>
                                </div>
                            </div>
                        </Card>

                        {/* Entitlement Details */}
                        <Card title="Entitlement Details" className="border-indigo-100 dark:border-indigo-900/30">
                            <div className="space-y-4">
                                <div>
                                    <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Plot Size Entitlement</p>
                                    <p className="text-sm font-black text-indigo-600 dark:text-indigo-400">{entitlement?.size}</p>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Plots Entitled</p>
                                        <p className="text-sm font-black text-gray-800 dark:text-white">{entitlement?.countEntitled}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Plots Allocated</p>
                                        <p className="text-sm font-black text-gray-800 dark:text-white">{entitlement?.countAllocated}</p>
                                    </div>
                                </div>
                                {entitlement?.allocatedPlotNumbers.length ? (
                                    <div className="pt-3 border-t border-gray-100 dark:border-gray-700">
                                        <p className="text-[10px] font-bold text-gray-400 uppercase mb-2">Current Allocations</p>
                                        <div className="flex flex-wrap gap-2">
                                            {entitlement.allocatedPlotNumbers.map(pNum => (
                                                <div key={pNum} className="flex flex-col gap-0.5">
                                                    <Badge variant={qualification.isQualified ? 'success' : 'warning'} className="font-mono">
                                                        {pNum}
                                                    </Badge>
                                                    {entitlement.isProvisional && (
                                                        <span className="text-[8px] font-black text-amber-600 uppercase tracking-tighter">Provisional</span>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                ) : (
                                    <div className="pt-3 border-t border-gray-100 dark:border-gray-700 text-center py-4">
                                        <TagIcon className="w-8 h-8 text-gray-300 mx-auto mb-1" />
                                        <p className="text-xs text-gray-400 italic">No plots currently assigned</p>
                                    </div>
                                )}
                            </div>
                        </Card>
                    </div>

                    {/* Plot Selection & Configuration */}
                    <div className="lg:col-span-2 space-y-6">
                        {selectedProperty ? (
                            <Card 
                                title={`3. Select Plot(s) for ${selectedProperty.location}`}
                                action={
                                    <div className="text-xs font-bold text-gray-400 uppercase">
                                        {selectedPlots.length} Plots Selected
                                    </div>
                                }
                            >
                                <div className="space-y-6">
                                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 max-h-[400px] overflow-y-auto p-1 scrollbar-thin">
                                        {availablePlotsList.map(plot => {
                                            const isSelected = selectedPlots.includes(plot);
                                            return (
                                                <button
                                                    key={plot}
                                                    onClick={() => handlePlotToggle(plot)}
                                                    className={`p-3 rounded-lg border text-sm font-bold transition-all flex flex-col items-center gap-1 group relative ${
                                                        isSelected 
                                                        ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' 
                                                        : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:border-blue-400'
                                                    }`}
                                                >
                                                    <MapPinIcon className={`w-4 h-4 ${isSelected ? 'text-white' : 'text-gray-400 group-hover:text-blue-500'}`} />
                                                    {plot}
                                                    <div className={`text-[10px] uppercase font-black px-1.5 rounded-full ${isSelected ? 'bg-blue-500 text-white' : 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'}`}>
                                                        {isSelected ? 'Selected' : 'Available'}
                                                    </div>
                                                </button>
                                            );
                                        })}
                                    </div>

                                    {/* Confirmation Summary Panel */}
                                    {selectedPlots.length > 0 && (
                                        <div className="mt-8 p-6 bg-gray-50 dark:bg-gray-900 rounded-xl border-2 border-dashed border-gray-200 dark:border-gray-700 animate-in slide-in-from-bottom-2">
                                            <h4 className="text-sm font-black text-gray-800 dark:text-white uppercase tracking-widest mb-4">Allocation Confirmation</h4>
                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Client Name</p>
                                                    <p className="text-sm font-bold">{selectedClient.name}</p>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Allocation Type</p>
                                                    <Badge variant={qualification.isQualified ? 'success' : 'warning'}>
                                                        {qualification.isQualified ? 'Permanent Allocation' : 'Provisional Allocation'}
                                                    </Badge>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Selected Plot Numbers</p>
                                                    <div className="flex flex-wrap gap-2">
                                                        {selectedPlots.map(p => (
                                                            <div key={p} className="flex flex-col">
                                                                <Badge variant="purple">{p}</Badge>
                                                                {!qualification.isQualified && (
                                                                    <span className="text-[8px] font-black text-amber-600 uppercase">Provisional</span>
                                                                )}
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                                <div className="space-y-2">
                                                    <p className="text-xs text-gray-500">Property Location</p>
                                                    <p className="text-sm font-bold">{selectedProperty.location}</p>
                                                </div>
                                            </div>

                                            <div className="mt-8 flex justify-end">
                                                <Button 
                                                    onClick={handleConfirmAllocation} 
                                                    isLoading={isSaving}
                                                    className="px-10 py-3 shadow-lg hover:shadow-xl transition-all"
                                                    icon={<CheckCircleIcon className="w-5 h-5" />}
                                                >
                                                    Confirm & Save Allocation
                                                </Button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </Card>
                        ) : (
                            <div className="bg-white dark:bg-gray-800 p-20 rounded-xl border border-gray-200 dark:border-gray-700 text-center opacity-60">
                                <MapPinIcon className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                                <h3 className="text-lg font-bold text-gray-800 dark:text-white">Awaiting Location Selection</h3>
                                <p className="text-gray-500 max-w-xs mx-auto">Please select a property location to view available plots for allocation.</p>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {!selectedClient && (
                <div className="bg-white dark:bg-gray-800 p-20 rounded-xl border border-gray-200 dark:border-gray-700 text-center opacity-60">
                    <UserCheckIcon className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <h3 className="text-lg font-bold text-gray-800 dark:text-white">Ready to Allocate</h3>
                    <p className="text-gray-500 max-w-xs mx-auto">Please select a client above to verify their qualification and entitlement details.</p>
                </div>
            )}

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 5px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
