};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

export default AllocatePlotPage;

import React, { useState, useMemo } from 'react';
import { Client, Property } from '../types';
import { 
    ArrowLeftIcon, 
    UserCheckIcon, 
    CheckCircleIcon, 
    MapPinIcon, 
    ChevronDownIcon,
    EyeIcon,
    TagIcon,
    ClockIcon,
    LockClosedIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Select } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { Badge } from '../components/ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { useClients } from '../hooks/useAppData';

interface AllocatePlotPageProps {
    onBack: () => void;
    clients: Client[];
    properties: Property[];
}

const AllocatePlotPage: React.FC<AllocatePlotPageProps> = ({ onBack, clients, properties }) => {
    const { saveClient } = useClients();

    // Selection State
    const [selectedClientId, setSelectedClientId] = useState<number | ''>('');
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [selectedPlots, setSelectedPlots] = useState<string[]>([]);
    const [isSaving, setIsSaving] = useState(false);
    const [allocationSuccess, setAllocationSuccess] = useState(false);

    // Master Allocation View State
    const [isViewAllOpen, setIsViewAllOpen] = useState(false);
    const [viewAllLocationId, setViewAllLocationId] = useState<number | ''>('');
    const [statusFilter, setStatusFilter] = useState<'All' | 'Allocated' | 'Available'>('All');
    const [sizeFilter, setSizeFilter] = useState<string>('All');

    // Data Derivation for Active Allocation
    const selectedClient = useMemo(() => clients.find(c => c.id === selectedClientId), [selectedClientId, clients]);
    const selectedProperty = useMemo(() => properties.find(p => p.id === selectedPropertyId), [selectedPropertyId, properties]);

    // Qualification Logic
    const qualification = useMemo(() => {
        if (!selectedClient) return { isQualified: false, percentage: 0, status: 'N/A' };
        const total = selectedClient.payment.total || 1;
        const paid = selectedClient.payment.paid || 0;
        const percentage = (paid / total) * 100;
        const isQualified = percentage >= 70;
        return {
            percentage: Math.round(percentage),
            isQualified,
            status: isQualified ? 'Fully Qualified (≥70% paid)' : 'Provisionally Allocated (Pending 70% payment)'
        };
    }, [selectedClient]);

    // Entitlement Logic (Enhanced for clarity)
    const entitlement = useMemo(() => {
        if (!selectedClient) return null;
        const plotsAlreadyAllocated = selectedClient.plot && selectedClient.plot !== 'N/A' 
            ? selectedClient.plot.split(',').map(p => p.trim()).filter(Boolean)
            : [];

        return {
            size: selectedClient.propertyType || 'Residential',
            countEntitled: 1, // Mock value based on form logic
            countAllocated: plotsAlreadyAllocated.length,
            allocatedPlotNumbersList: plotsAlreadyAllocated.length > 0 ? plotsAlreadyAllocated.join(', ') : '—',
            isProvisional: !qualification.isQualified && plotsAlreadyAllocated.length > 0
        };
    }, [selectedClient, qualification]);

    // Global Plot Pool for selection logic
    const globalPlotStatus = useMemo(() => {
        const pool: Record<string, { allocated: boolean, owner?: string }> = {};
        clients.forEach(c => {
            if (c.plot && c.plot !== 'N/A') {
                c.plot.split(',').forEach(p => {
                    const plotNum = p.trim();
                    if (plotNum) {
                        pool[plotNum] = { allocated: true, owner: c.name };
                    }
                });
            }
        });
        return pool;
    }, [clients]);

    // Master View Data Derivation
    const masterViewProperty = useMemo(() => properties.find(p => p.id === viewAllLocationId), [viewAllLocationId, properties]);

    const masterPlotList = useMemo(() => {
        if (!masterViewProperty) return [];

        const totalCount = masterViewProperty.inventory.reduce((sum, inv) => sum + inv.count, 0);
        const prefix = masterViewProperty.location.substring(0, 3).toUpperCase();

        const allPlots: { plotNumber: string; size: string; allocatedTo: string | null; isProvisional?: boolean }[] = [];
        let plotCounter = 100;

        masterViewProperty.inventory.forEach(inv => {
            for (let i = 0; i < inv.count; i++) {
                const pNum = `${prefix}-${plotCounter++}`;
                const ownerInfo = globalPlotStatus[pNum];

                let isProvisional = false;
                if (ownerInfo?.allocated) {
                    const client = clients.find(c => c.name === ownerInfo.owner);
                    if (client) {
                        const pct = (client.payment.paid / (client.payment.total || 1)) * 100;
                        isProvisional = pct < 70;
                    }
                }

                allPlots.push({
                    plotNumber: pNum,
                    size: inv.size,
                    allocatedTo: ownerInfo?.owner || null,
                    isProvisional
                });
            }
        });

        return allPlots.filter(p => {
            const matchesStatus = statusFilter === 'All' || 
                (statusFilter === 'Allocated' && p.allocatedTo !== null) || 
                (statusFilter === 'Available' && p.allocatedTo === null);
            const matchesSize = sizeFilter === 'All' || p.size === sizeFilter;
            return matchesStatus && matchesSize;
        });
    }, [masterViewProperty, clients, statusFilter, sizeFilter, globalPlotStatus]);

    const availablePlotsList = useMemo(() => {
        if (!selectedProperty) return [];
        const totalPlots = selectedProperty.inventory.reduce((acc, inv) => acc + inv.count, 0);
        const prefix = selectedProperty.location.substring(0, 3).toUpperCase();
        return Array.from({ length: totalPlots }).map((_, i) => `${prefix}-${100 + i}`);
    }, [selectedProperty]);

    const handlePlotToggle = (plot: string) => {
        const isActuallyAllocated = globalPlotStatus[plot]?.allocated;
        if (isActuallyAllocated) return; // Prevent selection of already allocated plots

        setSelectedPlots(prev => 
            prev.includes(plot) ? prev.filter(p => p !== plot) : [...prev, plot]
        );
    };

    const handleConfirmAllocation = async () => {
        if (!selectedClient || selectedPlots.length === 0) return;

        setIsSaving(true);
        try {
            const updatedClient: Client = {
                ...selectedClient,
                plot: selectedPlots.join(', '),
                status: 'Active Client',
                interactions: [
                    {
                        id: Date.now(),
                        type: 'Note',
                        date: new Date().toISOString(),
                        agent: 'System Admin',
                        notes: `Plots ${selectedPlots.join(', ')} allocated at ${selectedProperty?.location}.`
                    },
                    ...selectedClient.interactions
                ]
            };

            await saveClient(updatedClient);
            setAllocationSuccess(true);
            setTimeout(() => {
                onBack();
            }, 2000);
        } catch (error) {
            alert('Failed to save allocation.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to Administration
                    </button>
                    <div className="flex items-center gap-4">
                        <UserCheckIcon className="w-10 h-10 text-blue-600 dark:text-blue-400" />
                        <div>
                            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Allocate Plot</h1>
                            <p className="text-gray-500 dark:text-gray-400 mt-1">Assign plots to clients and verify entitlements.</p>
                        </div>
                    </div>
                </div>
            </div>

            {allocationSuccess && (
                <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded shadow-md animate-bounce">
                    <div className="flex items-center">
                        <CheckCircleIcon className="w-6 h-6 mr-2" />
                        <p className="font-bold">Allocation Successful! Redirecting...</p>
                    </div>
                </div>
            )}

            {/* Selection Area */}
            <Card className="bg-white dark:bg-gray-800">
                <div className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <Select 
                            label="1. Select Client Name" 
                            value={selectedClientId} 
                            onChange={(e) => {
                                setSelectedClientId(Number(e.target.value));
                                setSelectedPlots([]);
                            }}
                        >
                            <option value="">-- Choose a Client --</option>
                            {clients.map(client => (
                                <option key={client.id} value={client.id}>{client.name}</option>
                            ))}
                        </Select>
                        <Select 
                            label="2. Select Location" 
                            value={selectedPropertyId} 
                            onChange={(e) => {
                                setSelectedPropertyId(Number(e.target.value));
                                setSelectedPlots([]);
                            }}
                        >
                            <option value="">-- Choose a Location --</option>
                            {properties.map(prop => (
                                <option key={prop.id} value={prop.id}>{prop.location}</option>
                            ))}
                        </Select>
                    </div>

                    <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                        <button 
                            onClick={() => setIsViewAllOpen(!isViewAllOpen)}
                            className="flex items-center gap-2 text-sm font-bold text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 transition-colors"
                        >
                            <EyeIcon className="w-5 h-5" />
                            View All Allocations
                            <ChevronDownIcon className={`w-4 h-4 transition-transform ${isViewAllOpen ? 'rotate-180' : ''}`} />
                        </button>

                        {isViewAllOpen && (
                            <div className="mt-4 p-5 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-800 animate-in slide-in-from-top-2">
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                                    <Select 
                                        label="Select Location to View" 
                                        value={viewAllLocationId} 
                                        onChange={(e) => setViewAllLocationId(e.target.value ? Number(e.target.value) : '')}
                                    >
                                        <option value="">-- Select a Location --</option>
                                        {properties.map(prop => (
                                            <option key={prop.id} value={prop.id}>{prop.location}</option>
                                        ))}
                                    </Select>
                                    <Select label="Filter by Status" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as any)}>
                                        <option value="All">All Plots</option>
                                        <option value="Allocated">Allocated Only</option>
                                        <option value="Available">Available Only</option>
                                    </Select>
                                    <Select label="Filter by Size" value={sizeFilter} onChange={(e) => setSizeFilter(e.target.value)}>
                                        <option value="All">All Sizes</option>
                                        <option value="70x100 ft">70x100 ft</option>
                                        <option value="70x50 ft">70x50 ft</option>
                                        <option value="60x80 ft">60x80 ft</option>
                                    </Select>
                                </div>

                                {masterViewProperty && (
                                    <TableContainer className="max-h-[400px] overflow-y-auto">
                                        <table className="w-full text-sm text-left">
                                            <Thead>
                                                <tr>
                                                    <Th>Plot Number</Th>
                                                    <Th>Allocated Client</Th>
                                                    <Th>Plot Size</Th>
                                                    <Th className="text-center">Status</Th>
                                                </tr>
                                            </Thead>
                                            <Tbody>
                                                {masterPlotList.map((p, idx) => (
                                                    <Tr key={idx}>
                                                        <Td className="font-mono font-bold text-gray-900 dark:text-white">
                                                            {p.plotNumber}
