                                <div className="p-4 rounded-lg border flex flex-col items-center text-center gap-2 bg-gray-50 dark:bg-gray-900/50 border-gray-100 dark:border-gray-700">
                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Payment Qualification</p>
                                    <div className={`text-sm font-bold flex items-center gap-2 ${qualification.isQualified ? 'text-green-600' : 'text-amber-600'}`}>
                                        {qualification.isQualified ? <CheckCircleIcon className="w-5 h-5" /> : <ClockIcon className="w-5 h-5" />}
                                        {qualification.status}
                                    </div>
                                    <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 mt-2">
                                        <div 
                                            className={`h-2 rounded-full transition-all duration-1000 ${qualification.isQualified ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.4)]' : 'bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.4)]'}`} 
                                            style={{ width: `${qualification.percentage}%` }}
                                        ></div>
                                    </div>
                                    <p className="text-xs font-bold text-gray-500 mt-1">{qualification.percentage}% of total paid</p>
