                                    <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Number of plots entitled:</p>
                                    <p className="text-sm font-black text-gray-900 dark:text-white">{entitlement?.countEntitled}</p>
                                </div>
                                <div className="flex justify-between items-start py-2">
                                    <p className="text-sm font-medium text-gray-600 dark:text-gray-400 w-1/2">Plot numbers currently allocated to the client:</p>
                                    <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 text-right w-1/2 break-words">
                                        {entitlement?.allocatedPlotNumbersList}
                                    </p>
                                </div>
                            </div>
                        </Card>
                    </div>

                    {/* Plot Selection & Configuration - ENHANCED SECTION 2 & 3 */}
                    <div className="lg:col-span-2 space-y-6">
                        {selectedProperty ? (
                            <Card 
                                title={`3. Select Plot(s) for ${selectedProperty.location}`}
                                action={
                                    <div className="text-xs font-bold text-gray-400 uppercase">
                                        {selectedPlots.length} Plots Selected
