export interface Promotion {
    id: number;
    title: string;
    description: string;
    promoType: 'Discount' | 'Free Plot' | 'Referral Bonus' | 'Seasonal Offer' | 'Other';
    startDate: string;
    endDate: string;
    discountValue: number;
    applicablePropertyId: number | 'all';
    status: 'Active' | 'Inactive';
    bannerImage?: string;
    // Enhanced fields for pricing logic
    targetPlotSize?: PlotSize;
    numberOfPlots?: number;
    originalPrice?: number;
    promoPrice?: number;
}

import React, { useState, ChangeEvent, FormEvent, useMemo } from 'react';
import { Promotion, Property, PlotSize } from '../types';
import { ArrowLeftIcon, PencilIcon, TrashIcon, UploadIcon, CurrencyDollarIcon, TagIcon } from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select, Textarea } from '../components/ui/Input';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { uploadFile } from '../services/storageService';

interface PromotionsPageProps {
    promotions: Promotion[];
    onSavePromotion: (promotion: Promotion) => Promise<void>;
    onDeletePromotion: (promotionId: number) => Promise<void>;
    properties: Property[];
    showForm?: boolean;
    onBack?: () => void;
}

const initialFormState: Omit<Promotion, 'id'> = {
    title: '',
    description: '',
    promoType: 'Discount',
    startDate: '',
    endDate: '',
    discountValue: 0,
    applicablePropertyId: 'all',
    status: 'Active',
    bannerImage: undefined,
    targetPlotSize: '70x100 ft',
    numberOfPlots: 1,
    originalPrice: 0,
    promoPrice: 0
};

const PromotionsPage: React.FC<PromotionsPageProps> = ({ promotions, onSavePromotion, onDeletePromotion, properties, showForm = false, onBack }) => {
    const [formData, setFormData] = useState<Omit<Promotion, 'id'>>(initialFormState);
    const [editingId, setEditingId] = useState<number | null>(null);
    const [bannerPreview, setBannerPreview] = useState<string | null>(null);
    const [bannerFile, setBannerFile] = useState<File | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    // Compute original price based on selected property
    const currentOriginalPrice = useMemo(() => {
        if (formData.applicablePropertyId === 'all') return 0;
        const prop = properties.find(p => p.id === formData.applicablePropertyId);
        return prop ? prop.price : 0;
    }, [formData.applicablePropertyId, properties]);

    // SECTION 1: Real-time Promotional Price computation
    const computedPromoPrice = useMemo(() => {
        const discount = formData.discountValue || 0;
        return Math.max(0, currentOriginalPrice - discount);
    }, [currentOriginalPrice, formData.discountValue]);

    const handleInputChange = (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        const isNumber = type === 'number';
        setFormData(prev => ({ ...prev, [name]: isNumber ? parseFloat(value) || 0 : value }));
    };

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setBannerFile(file);
            const reader = new FileReader();
            reader.onloadend = () => {
                setBannerPreview(reader.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleStatusToggle = (promo: Promotion) => {
        const updatedPromo: Promotion = { ...promo, status: promo.status === 'Active' ? 'Inactive' : 'Active' };
        onSavePromotion(updatedPromo);
    };

    const handleReset = () => {
        setFormData(initialFormState);
        setEditingId(null);
        setBannerPreview(null);
        setBannerFile(null);
        setIsSaving(false);
    };

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            let bannerUrl = formData.bannerImage;
            if (bannerFile) {
                bannerUrl = await uploadFile(bannerFile, `promotions/banners/${bannerFile.name}`);
            }

            const promoToSave: Promotion = {
                id: editingId !== null ? editingId : Date.now(),
                ...formData,
                originalPrice: currentOriginalPrice,
                promoPrice: computedPromoPrice,
                bannerImage: bannerUrl,
            };
            await onSavePromotion(promoToSave);
            handleReset();
        } catch (error) {
            console.error("Error saving promotion:", error);
            alert("Failed to save promotion.");
        } finally {
            setIsSaving(false);
        }
    };

    const handleEdit = (promo: Promotion) => {
        setEditingId(promo.id);
        setFormData({
            title: promo.title,
            description: promo.description,
            promoType: promo.promoType,
            startDate: promo.startDate,
            endDate: promo.endDate,
            discountValue: promo.discountValue,
            applicablePropertyId: promo.applicablePropertyId,
            status: promo.status,
            bannerImage: promo.bannerImage,
            targetPlotSize: promo.targetPlotSize || '70x100 ft',
            numberOfPlots: promo.numberOfPlots || 1,
            originalPrice: promo.originalPrice || 0,
            promoPrice: promo.promoPrice || 0
        });
        setBannerPreview(promo.bannerImage || null);
        setBannerFile(null);
        window.scrollTo(0, 0);
    };

    const handleDelete = (id: number) => {
        onDeletePromotion(id);
    };

    return (
        <div className="space-y-6">
            <div>
                 {onBack && (
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to CEO Hub
                    </button>
                )}
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Promotional Offers Management</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">Create, manage, and track all marketing promotions.</p>
            </div>

            {showForm && (
              <Card title={editingId ? 'Edit Promotion' : 'Create New Promotion'}>
                  <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      <Input label="Promo Title*" name="title" value={formData.title} onChange={handleInputChange} required />
                      <div className="md:col-span-2">
                          <Textarea label="Promo Description*" name="description" value={formData.description} onChange={handleInputChange} required rows={1} />
                      </div>

                      <Select label="Applicable Property*" name="applicablePropertyId" value={formData.applicablePropertyId} onChange={handleInputChange} required>
                          <option value="all">Select a Property...</option>
                          {properties.map(p => <option key={p.id} value={p.id}>{p.location}</option>)}
                      </Select>

                      <Select label="Target Plot Size*" name="targetPlotSize" value={formData.targetPlotSize} onChange={handleInputChange} required>
                          <option>70x100 ft</option>
                          <option>70x50 ft</option>
                          <option>60x80 ft</option>
                      </Select>

                      <Input label="Number of Plots for Promo*" type="number" name="numberOfPlots" value={formData.numberOfPlots} onChange={handleInputChange} required />

                      <Input label="Discount Value (GHC)*" type="number" name="discountValue" value={formData.discountValue} onChange={handleInputChange} required />

                      {/* Display computed prices */}
                      <div className="p-3 bg-gray-50 dark:bg-gray-900 rounded-lg border border-gray-100 dark:border-gray-800">
                          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Current Base Price</p>
                          <p className="text-sm font-bold text-gray-600 dark:text-gray-400">GHC {currentOriginalPrice.toLocaleString()}</p>
                      </div>

                      <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-100 dark:border-blue-800">
                          <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Generated Promo Price</p>
                          <p className="text-lg font-black text-blue-600 dark:text-blue-300">GHC {computedPromoPrice.toLocaleString()}</p>
                          <p className="text-[9px] text-blue-500 italic mt-1">Calculated from: Original Price - Discount</p>
                      </div>

                      <Input label="Start Date" type="date" name="startDate" value={formData.startDate} onChange={handleInputChange} />
                      <Input label="End Date" type="date" name="endDate" value={formData.endDate} onChange={handleInputChange} />

                      <Select label="Promo Status" name="status" value={formData.status} onChange={handleInputChange}>
                          <option value="Active">Active</option><option value="Inactive">Inactive</option>
                      </Select>

                       <div className="md:col-span-3">
                          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Upload Banner Image</label>
                          <div className="mt-1 flex items-center gap-4">
                             {bannerPreview && <img src={bannerPreview} alt="Banner" className="h-12 w-24 object-cover rounded-md" />}
                             <label htmlFor="banner-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 flex items-center gap-2 transition-colors">
                                <UploadIcon className="w-5 h-5"/>
                                <span>{bannerFile ? 'Change Image' : (bannerPreview ? 'Change Image' : 'Upload Image')}</span>
                                <input id="banner-upload" name="bannerImage" type="file" className="sr-only" onChange={handleFileChange} accept="image/*" />
                             </label>
                          </div>
                      </div>
                      <div className="md:col-span-3 flex justify-end gap-3 mt-4">
                          <Button type="button" variant="secondary" onClick={handleReset}>Cancel</Button>
                          <Button type="submit" isLoading={isSaving}>{editingId ? 'Update Promotion' : 'Save Promotion'}</Button>
                      </div>
                  </form>
              </Card>
            )}

            <TableContainer>
                <table className="w-full text-sm text-left">
                    <Thead>
                        <tr>
                            <Th>Title</Th>
                            <Th>Targeting</Th>
                            <Th>Promo Price</Th>
                            <Th>Duration</Th>
                            <Th className="text-center">Status</Th>
                            <Th className="text-center">Actions</Th>
                        </tr>
                    </Thead>
                    <Tbody>
                        {promotions.map(promo => (
                            <Tr key={promo.id}>
                                <Td className="font-medium text-gray-900 dark:text-white">
                                    <div className="flex flex-col">
                                        <span>{promo.title}</span>
                                        <span className="text-[10px] text-gray-400">{promo.promoType}</span>
                                    </div>
                                </Td>
                                <Td className="text-gray-600 dark:text-gray-300">
                                    <div className="text-xs">
                                        <p>{promo.targetPlotSize} @ {promo.applicablePropertyId === 'all' ? 'All' : properties.find(p=>p.id === promo.applicablePropertyId)?.location}</p>
                                        <p className="text-[10px] font-bold text-indigo-500 uppercase">{promo.numberOfPlots} Plots Available</p>
                                    </div>
                                </Td>
                                <Td>
                                    <div className="font-black text-blue-600 dark:text-blue-400">GHC {promo.promoPrice?.toLocaleString()}</div>
                                    <div className="text-[9px] text-gray-400 line-through">GHC {promo.originalPrice?.toLocaleString()}</div>
                                </Td>
                                <Td className="text-gray-600 dark:text-gray-300 text-xs">{promo.startDate} to {promo.endDate}</Td>
                                <Td className="text-center">
                                    <button onClick={() => handleStatusToggle(promo)}>
                                        <Badge variant={promo.status === 'Active' ? 'success' : 'danger'}>{promo.status}</Badge>
                                    </button>
                                </Td>
                                <Td className="text-center">
                                    <div className="flex items-center justify-center gap-2">
                                        <button onClick={() => handleEdit(promo)} className="text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400 p-1"><PencilIcon className="w-5 h-5"/></button>
                                        <button onClick={() => handleDelete(promo.id)} className="text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400 p-1"><TrashIcon className="w-5 h-5"/></button>
                                    </div>
                                </Td>
                            </Tr>
                        ))}
                    </Tbody>
                </table>
                {promotions.length === 0 && <div className="text-center py-10 text-gray-500 dark:text-gray-400">No promotions found.</div>}
            </TableContainer>
        </div>
    );
};

