                                <CurrencyDollarIcon className="w-5 h-5 text-red-600 mt-0.5" />
                                <div>
                                    <p className="text-xs font-bold text-red-800 dark:text-red-400">Arrears Alert</p>
                                    <p className="text-[10px] text-red-600 dark:text-red-300/80 mt-1">{clients.filter(c => (c.payment?.balance || 0) > (c.payment?.total || 0) * 0.5).length} clients have >50% outstanding balance.</p>
                                </div>
