interface PurchaseSaleManagementPageProps {
    onBack: () => void;
    properties: Property[];
    onSaveProperty: (property: Property) => Promise<void>;
    currentStaff: Staff;
}

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

const PurchaseSaleManagementPage: React.FC<PurchaseSaleManagementPageProps> = ({ onBack, properties, onSaveProperty, currentStaff }) => {
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [editSellingPrice, setEditSellingPrice] = useState<string>('');
    const [isSaving, setIsSaving] = useState(false);

    const selectedProperty = useMemo(() => 
        properties.find(p => p.id === selectedPropertyId), 
    [selectedPropertyId, properties]);

    // Initial state setup when property changes
    useEffect(() => {
        if (selectedProperty) {
            setEditSellingPrice(selectedProperty.price.toString());
        } else {
            setEditSellingPrice('');
        }
    }, [selectedProperty]);

    // Calculations for the P&L Panel
    const calculations = useMemo(() => {
        if (!selectedProperty) return null;

        const costPerPlot = selectedProperty.costPrice || 0;
        const currentSellingPrice = parseFloat(editSellingPrice) || 0;
        const totalPlots = selectedProperty.inventory.reduce((sum, inv) => sum + inv.count, 0);

        const margin = currentSellingPrice - costPerPlot;
        const marginPercentage = costPerPlot > 0 ? (margin / costPerPlot) * 100 : 0;
        const totalRevenue = currentSellingPrice * totalPlots;
        const totalCost = costPerPlot * totalPlots;
        const grossProfit = totalRevenue - totalCost;

        return {
            costPerPlot,
            currentSellingPrice,
            margin,
            marginPercentage,
            totalPlots,
            totalRevenue,
            totalCost,
            grossProfit
        };
    }, [selectedProperty, editSellingPrice]);

    const handleSave = async () => {
        if (!selectedProperty || !calculations) return;

        setIsSaving(true);
        try {
            const historyEntry: PriceHistory = {
                date: new Date().toISOString(),
                oldPrice: selectedProperty.price,
                newPrice: calculations.currentSellingPrice,
                changedBy: currentStaff.fullName
            };

            const updatedProperty: Property = {
                ...selectedProperty,
                price: calculations.currentSellingPrice,
                priceHistory: [historyEntry, ...(selectedProperty.priceHistory || [])]
            };

            await onSaveProperty(updatedProperty);
            alert("Selling price updated successfully.");
        } catch (error) {
            console.error(error);
            alert("Failed to update selling price.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" />
                        Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white mt-2 tracking-tight uppercase">Purchase & Sale Management</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Executive oversight of acquisition costs and market margins.</p>
                </div>
            </div>

            <Card className="bg-gray-50/50 dark:bg-gray-900/10">
                <div className="max-w-md">
                    <Select 
                        label="Select Property for Management"
                        value={selectedPropertyId}
                        onChange={(e) => setSelectedPropertyId(e.target.value ? Number(e.target.value) : '')}
                    >
                        <option value="">-- Choose an acquisition record --</option>
                        {properties.map(p => (
                            <option key={p.id} value={p.id}>{p.location}</option>
                        ))}
                    </Select>
                </div>
            </Card>

            {selectedProperty && calculations ? (
                <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                    {/* Management Work Area */}
                    <div className="xl:col-span-2 space-y-8">
                        <div className="flex items-center gap-4 p-6 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm">
                            <div className="p-3 rounded-full bg-blue-100 dark:bg-blue-900/30">
                                <BuildingLibraryIcon className="w-8 h-8 text-blue-600" />
                            </div>
                            <div>
                                <h2 className="text-2xl font-black text-gray-900 dark:text-white">{selectedProperty.location}</h2>
                                <p className="text-gray-500 dark:text-gray-400">{selectedProperty.description}</p>
                            </div>
                        </div>

                        <Card title="Price Management Controls">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Cost Price per Plot (Acquisition)</label>
                                        <div className="px-4 py-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg font-black text-gray-700 dark:text-gray-300">
                                            {formatCurrency(calculations.costPerPlot)}
                                        </div>
                                        <p className="text-[10px] text-gray-500 mt-1 italic">Read-only: Sourced from Vendor Purchase Agreement</p>
                                    </div>
                                    <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Previous Market Selling Price</label>
                                        <p className="text-lg font-bold text-gray-400 line-through">
                                            {formatCurrency(selectedProperty.price)}
                                        </p>
                                    </div>
                                </div>

                                <div className="space-y-6">
                                    <Input 
                                        label="New Selling Price per Plot (Market)"
                                        type="number"
                                        value={editSellingPrice}
                                        onChange={(e) => setEditSellingPrice(e.target.value)}
                                        placeholder="0.00"
                                        className="font-black text-xl text-blue-600"
                                    />

                                    <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-lg border border-blue-100 dark:border-blue-900/50">
                                        <p className="text-xs font-bold text-blue-800 dark:text-blue-300 mb-1 flex items-center gap-1">
                                            <ArrowTrendingUpIcon className="w-4 h-4" /> Margin Insight
                                        </p>
                                        <p className="text-sm font-medium text-blue-600 dark:text-blue-400">
                                            Applying a <span className="font-black">{calculations.marginPercentage.toFixed(1)}%</span> margin above acquisition cost.
                                        </p>
                                    </div>

                                    <div className="flex justify-end pt-4">
                                        <Button 
                                            onClick={handleSave} 
                                            isLoading={isSaving}
                                            className="px-10 py-3 shadow-lg uppercase tracking-wider"
                                        >
                                            Publish New Price
