                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

import { useMemo } from 'react';
import { Client, AppNotification } from '../types';

export const useNotificationTriggers = (clients: Client[]) => {
    const notifications = useMemo(() => {
        const alerts: AppNotification[] = [];
        const now = new Date();

        clients.forEach(client => {
            const totalCost = client.payment.total || 0;
            const paidAmount = client.payment.paid || 0;
            const paymentPercentage = totalCost > 0 ? (paidAmount / totalCost) * 100 : 0;
            const qualificationDate = client.regDate; // Mock qualification date as registration for logic

            // SECTION 1: Qualification (70%)
            if (paymentPercentage >= 70 && (!client.plot || client.plot === 'N/A')) {
                const hoursSinceQual = (now.getTime() - new Date(qualificationDate).getTime()) / (1000 * 60 * 60);

                if (hoursSinceQual >= 90) { // 42h + 48h Escalation
                    alerts.push({
                        id: `qual-esc-${client.id}`,
                        title: 'CRITICAL: Allocation Escalation',
                        message: `Client ${client.name} qualified >90 hours ago but has no plot allocation.`,
                        type: 'Escalation',
                        recipientRole: 'CEO',
                        timestamp: now.toISOString(),
                        isRead: false,
                        metadata: { clientId: client.id, clientName: client.name }
                    });
                } else if (hoursSinceQual >= 42) {
                    alerts.push({
                        id: `qual-rem-${client.id}`,
                        title: 'Reminder: Pending Allocation',
                        message: `Client ${client.name} reached 70% payment 42 hours ago. Allocation required.`,
                        type: 'Reminder',
                        recipientRole: 'Administrator',
                        timestamp: now.toISOString(),
                        isRead: false,
                        metadata: { clientId: client.id, clientName: client.name }
                    });
                } else {
                    alerts.push({
                        id: `qual-init-${client.id}`,
                        title: 'New Qualification',
                        message: `Client ${client.name} has reached 70% payment and now qualifies for plot allocation.`,
                        type: 'Qualification',
                        recipientRole: 'Administrator',
                        timestamp: now.toISOString(),
                        isRead: false,
                        metadata: { clientId: client.id, clientName: client.name }
                    });
                }
            }

            // SECTION 2: Indenture Follow-up
            const indentureBalance = (client.payment as any).indentureBalance || 0;
            if (paymentPercentage >= 70 && indentureBalance > 0) {
                const monthsSinceQual = (now.getTime() - new Date(qualificationDate).getTime()) / (1000 * 60 * 60 * 24 * 30);
                if (monthsSinceQual >= 1) {
                    alerts.push({
                        id: `ind-rem-${client.id}`,
                        title: 'Indenture Payment Follow-up',
                        message: `Client ${client.name} has not completed indenture payment. Follow-up required.`,
                        type: 'Reminder',
                        recipientRole: 'Front Desk Executive',
                        timestamp: now.toISOString(),
                        isRead: false,
                        metadata: { clientId: client.id, clientName: client.name }
                    });
                }
            }

            // SECTION 5: Default Escalation (3 Months)
            const lastPaymentDate = client.payment.paymentHistory.length > 0 
                ? new Date(client.payment.paymentHistory[client.payment.paymentHistory.length - 1].date)
                : new Date(client.regDate);
            const monthsSinceLastPayment = (now.getTime() - lastPaymentDate.getTime()) / (1000 * 60 * 60 * 24 * 30);

            if (monthsSinceLastPayment >= 3 && client.payment.balance > 0) {
                alerts.push({
                    id: `def-esc-ceo-${client.id}`,
                    title: 'Payment Default Escalation',
                    message: `Client ${client.name} has defaulted for 3 months. Review required.`,
                    type: 'Default',
                    recipientRole: 'CEO',
                    timestamp: now.toISOString(),
                    isRead: false,
                    metadata: { clientId: client.id, clientName: client.name }
                });
                alerts.push({
                    id: `def-esc-acc-${client.id}`,
                    title: 'Payment Default Escalation',
                    message: `Client ${client.name} has defaulted for 3 months. Review required.`,
                    type: 'Default',
                    recipientRole: 'Chief Accountant',
                    timestamp: now.toISOString(),
                    isRead: false,
                    metadata: { clientId: client.id, clientName: client.name }
                });
            }
        });

        // SECTION 3: Daily Outstanding Summary
        const owingClients = clients.filter(c => c.payment.balance > 0);
        if (owingClients.length > 0) {
            alerts.push({
                id: `daily-summary-${now.toDateString()}`,
                title: 'Daily Outstanding Summary',
                message: `There are ${owingClients.length} clients with outstanding balances totaling ${owingClients.reduce((s,c) => s + c.payment.balance, 0).toLocaleString()} GHC.`,
                type: 'Reminder',
                recipientRole: 'Chief Accountant',
                timestamp: now.toISOString(),
                isRead: false
            });
        }

        return alerts;
    }, [clients]);

    return notifications;
};

