import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { FinancialRecordEditor } from '../components/FinancialRecordEditor';
import { FinancialReportsView } from '../components/FinancialReportsView';
import { NotificationCenter } from '../components/NotificationCenter';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: ReceiptPattern | null;
  setReceiptPattern: React.Dispatch<React.SetStateAction<ReceiptPattern | null>>;
  setReceiptAlerts: React.Dispatch<React.SetStateAction<ReceiptAlert[]>>;
  currentStaff: Staff;
  roles: Role[];
}

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ invoices, clients, onSaveClient, onSaveInvoice, clientForInvoice, setClientForInvoice, currentStaff, roles }) => {
  const [viewMode, setViewMode] = useState<'list' | 'editor' | 'reports' | 'alerts'>('list');
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  // Real-time notification triggers
  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    // Merge generated alerts with state (simulating persistence)
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = useMemo(() => {
      return roles.find(r => r.id === currentStaff.roleId)?.name || 'Front Desk Executive';
  }, [roles, currentStaff]);

  // Filter States
  const [filterName, setFilterName] = useState('');
  const [filterLocation, setFilterLocation] = useState('');
  const [filterStatus, setFilterStatus] = useState<'All' | 'Fully Paid' | 'Owing' | 'Overpaid'>('All');

  useEffect(() => {
    if (clientForInvoice) {
        setEditingInvoice(null);
        setViewMode('editor');
    }
  }, [clientForInvoice]);

  const handleReschedule = (id: string, details: RescheduleDetails) => {
      setLocalNotifications(prev => prev.map(n => {
          if (n.id === id) {
              const history = n.metadata?.rescheduleHistory || [];
              return {
                  ...n,
                  metadata: { ...n.metadata, rescheduleHistory: [details, ...history] }
              };
          }
          return n;
      }));
  };

  const handleMarkRead = (id: string) => {
      setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n));
  };

  const filteredInvoices = useMemo(() => {
    return invoices.filter(invoice => {
      const client = clients.find(c => c.id === invoice.clientId);
      const clientLocation = client?.location || 'N/A';

      let paymentStatus = 'Owing'; 
      if (client) {
          const bal = client.payment.balance;
          if (bal === 0) paymentStatus = 'Fully Paid';
          else if (bal > 0) paymentStatus = 'Owing';
          else paymentStatus = 'Overpaid';
      }

      const matchesName = invoice.clientName.toLowerCase().includes(filterName.toLowerCase());
      const matchesLocation = clientLocation.toLowerCase().includes(filterLocation.toLowerCase());
      const matchesStatus = filterStatus === 'All' || paymentStatus === filterStatus;

      return matchesName && matchesLocation && matchesStatus;
    });
  }, [invoices, clients, filterName, filterLocation, filterStatus]);

  if (viewMode === 'editor') {
      return (
        <FinancialRecordEditor 
            onBack={() => setViewMode('list')}
            clients={clients}
            onSave={(inv, upd) => { if(upd) onSaveClient(upd); onSaveInvoice(inv); setViewMode('list'); }}
            onRecordPayment={(c, p) => { /* logic existed */ }}
            editingInvoice={editingInvoice}
            clientForInvoice={clientForInvoice}
            roles={roles}
        />
      );
  }

  if (viewMode === 'reports') {
    return <FinancialReportsView onBack={() => setViewMode('list')} clients={clients} staffList={[]} />;
  }

  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Financial oversight, payment tracking and escalation.</p>
        </div>
        <div className="flex gap-3">
          <Button 
            variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
            onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
            icon={<BellIcon className="w-5 h-5" />}
            className="relative"
          >
              Role Alerts
              {roleAlerts.length > 0 && (
                  <span className="absolute -top-1 -right-1 flex h-4 w-4">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                  </span>
              )}
          </Button>
          <Button variant="secondary" onClick={() => setViewMode('reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
              Reconciliation
          </Button>
          <Button onClick={() => setViewMode('editor')} icon={<DocumentPlusIcon className="w-5 h-5" />}>
              New Ledger
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-4 gap-6">
          <div className="xl:col-span-3 space-y-6">
              {viewMode === 'alerts' ? (
                  <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName as any}
                    onReschedule={handleReschedule}
                    onMarkRead={handleMarkRead}
                  />
              ) : (
                  <>
                    <Card title="Ledger Search & Filtering" className="p-0 overflow-hidden">
                        <div className="p-5 grid grid-cols-1 md:grid-cols-3 gap-6 bg-gray-50 dark:bg-gray-900/50">
                            <Input label="Client Name" value={filterName} onChange={e => setFilterName(e.target.value)} placeholder="Search..." />
                            <Input label="Location" value={filterLocation} onChange={e => setFilterLocation(e.target.value)} placeholder="Search..." />
                            <Select label="Status" value={filterStatus} onChange={e => setFilterStatus(e.target.value as any)}>
                                <option value="All">All Statuses</option>
                                <option value="Fully Paid">Fully Paid</option>
                                <option value="Owing">Owing</option>
                            </Select>
                        </div>
                    </Card>

                    <TableContainer>
                        <table className="w-full text-sm text-left">
                            <Thead>
                                <tr>
                                    <Th>Client Account</Th>
                                    <Th>Current Balance</Th>
                                    <Th>Location</Th>
                                    <Th className="text-center">Status</Th>
                                    <Th className="text-right">Actions</Th>
                                </tr>
                            </Thead>
                            <Tbody>
                                {filteredInvoices.map(invoice => (
                                    <Tr key={invoice.id}>
                                        <Td className="font-bold text-gray-900 dark:text-white">{invoice.clientName}</Td>
                                        <Td className="font-black">{formatCurrency(invoice.amount)}</Td>
                                        <Td className="text-gray-500">{clients.find(c => c.id === invoice.clientId)?.location}</Td>
                                        <Td className="text-center">
                                            <Badge variant={invoice.amount > 0 ? 'danger' : 'success'}>
                                                {invoice.amount > 0 ? 'Owing' : 'Settled'}
                                            </Badge>
                                        </Td>
                                        <Td className="text-right">
                                            <button onClick={() => { setEditingInvoice(invoice); setViewMode('editor'); }} className="p-2 text-gray-400 hover:text-blue-600 transition-colors">
                                                <PencilIcon className="w-5 h-5" />
                                            </button>
                                        </Td>
                                    </Tr>
                                ))}
                            </Tbody>
                        </table>
                    </TableContainer>
                  </>
              )}
          </div>

          <div className="xl:col-span-1">
              <Card title="Follow-up Statistics" className="bg-indigo-50/30 dark:bg-indigo-900/10">
                  <div className="space-y-6">
                      <div className="p-4 bg-white dark:bg-gray-800 rounded-lg border border-indigo-100 dark:border-indigo-900/50">
                          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Active Reminders</p>
                          <p className="text-2xl font-black text-indigo-600 dark:text-indigo-400">{localNotifications.filter(n => !n.isRead).length}</p>
                      </div>
                      <div className="p-4 bg-white dark:bg-gray-800 rounded-lg border border-red-100 dark:border-red-900/50">
                          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Urgent Defaults</p>
                          <p className="text-2xl font-black text-red-600 dark:text-red-400">
                              {localNotifications.filter(n => n.type === 'Default' && !n.isRead).length}
                          </p>
                      </div>
                      <div className="pt-4 border-t border-indigo-100 dark:border-indigo-900/50">
                          <h4 className="text-xs font-black text-gray-800 dark:text-white uppercase mb-3">System Logic</h4>
                          <ul className="text-[10px] text-gray-500 space-y-2 font-medium">
                              <li>• Allocation alerts triggered at 70% payment.</li>
                              <li>• Escalation to CEO after 90h inactivity.</li>
                              <li>• Default alerts triggered after 3mo inactivity.</li>
                          </ul>
                      </div>
                  </div>
              </Card>
          </div>
      </div>
    </div>
  );
};

export default AccountManagementPage;

