import React, { useState } from 'react';
import { AppNotification, RescheduleDetails } from '../types';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Input, Textarea } from './ui/Input';
import { Badge } from './ui/Badge';
import { 
    BellIcon, 
    ClockIcon, 
    ExclamationTriangleIcon, 
    UserCircleIcon, 
    CalendarDaysIcon,
    XMarkIcon,
    // FIX: Added missing CheckCircleIcon to imports
    CheckCircleIcon
} from './icons/DummyIcons';

interface NotificationCenterProps {
    notifications: AppNotification[];
    currentRole: string;
    onReschedule: (notificationId: string, details: RescheduleDetails) => void;
    onMarkRead: (notificationId: string) => void;
}

export const NotificationCenter: React.FC<NotificationCenterProps> = ({ 
    notifications, 
    currentRole, 
    onReschedule, 
    onMarkRead 
}) => {
    const [reschedulingId, setReschedulingId] = useState<string | null>(null);
    const [rescheduleForm, setRescheduleForm] = useState({ date: '', reason: '' });

    const filteredNotifications = notifications.filter(n => n.recipientRole === currentRole && !n.isRead);

    const handleRescheduleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (reschedulingId) {
            onReschedule(reschedulingId, {
                newDate: rescheduleForm.date,
                reason: rescheduleForm.reason,
                rescheduledBy: currentRole,
                timestamp: new Date().toISOString()
            });
            setReschedulingId(null);
            setRescheduleForm({ date: '', reason: '' });
        }
    };

    return (
        <div className="relative">
            <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-black text-gray-800 dark:text-white flex items-center gap-2">
                    <BellIcon className="w-5 h-5 text-blue-600" />
                    Role Alerts ({filteredNotifications.length})
                </h3>
            </div>

            <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2">
                {filteredNotifications.map(notification => (
                    <Card key={notification.id} className={`border-l-4 ${
                        notification.type === 'Escalation' || notification.type === 'Default' 
                        ? 'border-l-red-500' : 'border-l-blue-500'
                    } p-4`}>
                        <div className="flex justify-between items-start">
                            <div className="flex-1">
                                <div className="flex items-center gap-2 mb-1">
                                    <Badge variant={notification.type === 'Escalation' ? 'danger' : 'info'}>
                                        {notification.type}
                                    </Badge>
                                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-tight">
                                        {new Date(notification.timestamp).toLocaleString()}
                                    </span>
                                </div>
                                <h4 className="font-bold text-gray-900 dark:text-white">{notification.title}</h4>
                                <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">{notification.message}</p>

                                {notification.metadata?.rescheduleHistory && notification.metadata.rescheduleHistory.length > 0 && (
                                    <div className="mt-3 p-2 bg-gray-50 dark:bg-gray-900 rounded border border-gray-100 dark:border-gray-800">
                                        <p className="text-[10px] font-black text-blue-600 uppercase">Rescheduled Follow-up</p>
                                        <div className="flex items-center gap-2 text-xs font-bold text-gray-700 dark:text-gray-300 mt-1">
                                            <CalendarDaysIcon className="w-3 h-3" />
                                            Next: {notification.metadata.rescheduleHistory[0].newDate}
                                        </div>
                                        <p className="text-[10px] text-gray-500 italic mt-1">
                                            Reason: {notification.metadata.rescheduleHistory[0].reason}
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="flex gap-2 mt-4 pt-4 border-t border-gray-100 dark:border-gray-700">
                            <Button 
                                size="sm" 
                                variant="outline" 
                                className="flex-1"
                                onClick={() => setReschedulingId(notification.id)}
                            >
                                Reschedule
                            </Button>
                            <Button 
                                size="sm" 
                                variant="ghost" 
                                className="flex-1"
                                onClick={() => onMarkRead(notification.id)}
                            >
                                Dismiss
                            </Button>
                        </div>
                    </Card>
                ))}

                {filteredNotifications.length === 0 && (
                    <div className="py-12 text-center text-gray-400">
                        <CheckCircleIcon className="w-12 h-12 mx-auto mb-2 opacity-20" />
                        <p className="text-sm font-medium">All caught up!</p>
                    </div>
                )}
            </div>

            {/* Reschedule Modal */}
            {reschedulingId && (
                <div className="fixed inset-0 bg-black/60 z-[70] flex justify-center items-center p-4 backdrop-blur-sm">
                    <Card className="w-full max-w-sm p-6 shadow-2xl">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-lg font-bold text-gray-900 dark:text-white">Reschedule Follow-up</h3>
                            <button onClick={() => setReschedulingId(null)}><XMarkIcon className="w-5 h-5 text-gray-400" /></button>
                        </div>
                        <form onSubmit={handleRescheduleSubmit} className="space-y-4">
                            <Input 
                                label="New Follow-up Date" 
                                type="date" 
                                value={rescheduleForm.date}
                                onChange={e => setRescheduleForm({...rescheduleForm, date: e.target.value})}
                                required 
                            />
                            <Textarea 
                                label="Reason for Rescheduling" 
                                value={rescheduleForm.reason}
                                onChange={e => setRescheduleForm({...rescheduleForm, reason: e.target.value})}
                                placeholder="Explain why this action is being delayed..."
                                required 
                            />
                            <div className="flex gap-3 pt-2">
                                <Button type="button" variant="secondary" className="flex-1" onClick={() => setReschedulingId(null)}>Cancel</Button>
                                <Button type="submit" className="flex-1">Save Details</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { FaimLogoIcon, EyeIcon, EyeSlashIcon, ExclamationTriangleIcon } from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import { CompanySettings } from '../types';
import ThemeToggle from '../components/ThemeToggle';
import { useTheme } from '../context/ThemeContext';

interface LoginPageProps {
    onLogin: (email: string, password: string) => Promise<{ success: boolean, message: string }>;
    companySettings: CompanySettings;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin, companySettings }) => {
    const { theme } = useTheme();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            const result = await onLogin(email, password);

            if (!result.success) {
                // Handle Firebase 'invalid-credential' which usually means wrong email/password
                if (result.message.includes('invalid-credential')) {
                    setError('The email or password you entered is incorrect. Please try again.');
                } else {
                    setError(result.message);
                }
            }
        } catch (err) {
            setError('An unexpected error occurred during authentication.');
        } finally {
            setLoading(false);
        }
    };

    // Determine logos based on theme
    const activeAppLogo = theme === 'dark' ? (companySettings.appLogoDark || companySettings.appLogoLight) : (companySettings.appLogoLight || companySettings.appLogoDark);
    const activeCompanyLogo = theme === 'dark' ? (companySettings.companyLogoDark || companySettings.companyLogoLight) : (companySettings.companyLogoLight || companySettings.companyLogoDark);
    const legacyLogo = companySettings.logo;

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100 dark:bg-gray-950 p-4 transition-colors duration-200 relative">
            {/* Top Left App Branding */}
            <div className="absolute top-4 left-4 flex items-center gap-3">
                {activeAppLogo ? (
                    <img key={activeAppLogo} src={activeAppLogo} alt="App Logo" className="w-10 h-10 object-contain" />
                ) : (
                    <FaimLogoIcon className="w-8 h-8 text-blue-600 dark:text-blue-400" />
                )}
                <span className="font-bold text-xl text-gray-800 dark:text-white tracking-wide">
                    {companySettings.name.split(' ')[0]}<span className="text-blue-500">.</span>
                </span>
            </div>

            <div className="absolute top-4 right-4">
                <ThemeToggle />
            </div>

            <div className="w-full max-w-md p-8 space-y-8 bg-white dark:bg-gray-800 rounded-xl shadow-2xl transition-colors duration-200 mt-12 sm:mt-0">
                <div className="flex flex-col items-center">
                    {(activeCompanyLogo || legacyLogo) ? (
                        <img key={activeCompanyLogo || legacyLogo} src={activeCompanyLogo || legacyLogo} alt="Company Logo" className="w-32 h-32 object-contain mb-4" />
                    ) : (
                        <div className="w-24 h-24 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center mb-4">
                            <span className="text-4xl">🏢</span>
                        </div>
                    )}

                    <p className="text-gray-500 dark:text-gray-400 text-sm">Enterprise Resource Planning</p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 text-red-700 dark:text-red-200 p-4 rounded-md animate-in fade-in slide-in-from-top-1 duration-200" role="alert">
                        <div className="flex items-start">
                            <ExclamationTriangleIcon className="w-5 h-5 mr-2 shrink-0" />
                            <p className="text-sm font-medium">{error}</p>
                        </div>
                        {error.includes('incorrect') && (
                            <p className="mt-2 text-xs opacity-75 italic">Tip: Ensure you have an active account in the system and caps lock is off.</p>
                        )}
                    </div>
                )}

                <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
                    <div className="rounded-md shadow-sm -space-y-px">
                        <div>
                            <label htmlFor="email-address" className="sr-only">Email address</label>
                            <input
                                id="email-address"
                                name="email"
                                type="email"
                                autoComplete="email"
                                required
                                className="appearance-none rounded-none relative block w-full px-3 py-3 border border-gray-300 dark:border-gray-600 placeholder-gray-500 dark:placeholder-gray-400 text-gray-900 dark:text-white bg-white dark:bg-gray-900 rounded-t-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 focus:z-10 sm:text-sm"
                                placeholder="Email address"
                                value={email}
                                onChange={e => setEmail(e.target.value)}
                            />
                        </div>
                        <div className="relative">
                            <label htmlFor="password" className="sr-only">Password</label>
                            <input
                                id="password"
                                name="password"
                                type={showPassword ? "text" : "password"}
                                autoComplete="current-password"
                                required
                                className="appearance-none rounded-none relative block w-full px-3 py-3 border border-gray-300 dark:border-gray-600 placeholder-gray-500 dark:placeholder-gray-400 text-gray-900 dark:text-white bg-white dark:bg-gray-900 rounded-b-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 focus:z-10 sm:text-sm pr-10"
                                placeholder="Password"
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                            />
                            <button
                                type="button"
                                className="absolute inset-y-0 right-0 flex items-center pr-3 z-20 text-gray-400 hover:text-gray-600 dark:text-gray-400 dark:hover:text-gray-200 focus:outline-none"
                                onClick={() => setShowPassword(!showPassword)}
                            >
                                {showPassword ? (
                                    <EyeSlashIcon className="w-5 h-5" aria-hidden="true" />
                                ) : (
                                    <EyeIcon className="w-5 h-5" aria-hidden="true" />
                                )}
                            </button>
                        </div>
                    </div>

                    <div className="flex items-center justify-between">
                        <div className="flex items-center">
                            <input id="remember-me" name="remember-me" type="checkbox" className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700" />
                            <label htmlFor="remember-me" className="ml-2 block text-sm text-gray-900 dark:text-gray-300">Remember me</label>
                        </div>
                        <div className="text-sm">
                            <a href="#" className="font-medium text-blue-600 hover:text-blue-500 dark:text-blue-400 dark:hover:text-blue-300">Forgot your password?</a>
                        </div>
                    </div>

                    <div>
                        <button
                            type="submit"
                            disabled={loading}
                            className="group relative w-full flex justify-center py-2.5 px-4 border border-transparent text-sm font-bold rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-400 dark:disabled:bg-blue-800 transition-all shadow-md active:scale-[0.98]"
                        >
                            {loading ? (
                                <span className="flex items-center gap-2">
                                    <LoaderIcon className="w-4 h-4 animate-spin" /> Authenticating...
                                </span>
                            ) : (
                                "Sign In to FAIM"
                            )}
                        </button>
                    </div>
                </form>

                <div className="pt-4 border-t border-gray-100 dark:border-gray-700 text-center">
                    <p className="text-xs text-gray-400">Authorized Personnel Only. Logins are monitored.</p>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;

import React, { useState } from 'react';
import { AppNotification, RescheduleDetails } from '../types';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Input, Textarea } from './ui/Input';
import { Badge } from './ui/Badge';
import { 
    BellIcon, 
    ClockIcon, 
    ExclamationTriangleIcon, 
    CalendarDaysIcon,
    XMarkIcon,
    CheckCircleIcon,
    InformationCircleIcon,
    ArrowTrendingUpIcon
} from './icons/DummyIcons';

interface NotificationCenterProps {
    notifications: AppNotification[];
    currentRole: string;
    onReschedule: (notificationId: string, details: RescheduleDetails) => void;
    onMarkRead: (notificationId: string) => void;
}

const getVisualClassification = (type: AppNotification['type']) => {
    switch (type) {
        case 'Escalation':
            return {
                label: 'Escalated',
                variant: 'danger' as const,
                icon: <ExclamationTriangleIcon className="w-4 h-4" />
            };
        case 'Default':
            return {
                label: 'Critical',
                variant: 'danger' as const,
                icon: <XMarkIcon className="w-4 h-4" />
            };
        case 'Reminder':
            return {
                label: 'Reminder',
                variant: 'warning' as const,
                icon: <ClockIcon className="w-4 h-4" />
            };
        case 'Qualification':
        default:
            return {
                label: 'Informational',
                variant: 'info' as const,
                icon: <InformationCircleIcon className="w-4 h-4" />
            };
    }
};

export const NotificationCenter: React.FC<NotificationCenterProps> = ({ 
    notifications, 
    currentRole, 
    onReschedule, 
    onMarkRead 
}) => {
    const [reschedulingId, setReschedulingId] = useState<string | null>(null);
    const [rescheduleForm, setRescheduleForm] = useState({ date: '', reason: '' });

    const filteredNotifications = notifications.filter(n => n.recipientRole === currentRole);

    const handleRescheduleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (reschedulingId) {
            onReschedule(reschedulingId, {
                newDate: rescheduleForm.date,
                reason: rescheduleForm.reason,
                rescheduledBy: currentRole,
                timestamp: new Date().toISOString()
            });
            setReschedulingId(null);
            setRescheduleForm({ date: '', reason: '' });
        }
    };

    return (
        <div className="relative">
            <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-black text-gray-900 dark:text-white flex items-center gap-2 uppercase tracking-tight">
                    <BellIcon className="w-6 h-6 text-blue-600" />
                    Notification Audit Trail
                </h3>
            </div>

            <div className="space-y-6 max-h-[700px] overflow-y-auto pr-4 scrollbar-thin">
                {filteredNotifications.map(notification => {
                    const classification = getVisualClassification(notification.type);
                    const isRescheduled = notification.metadata?.rescheduleHistory && notification.metadata.rescheduleHistory.length > 0;

                    return (
                        <Card key={notification.id} className={`border-l-4 ${
                            notification.type === 'Escalation' || notification.type === 'Default' 
                            ? 'border-l-red-600' : notification.type === 'Reminder' ? 'border-l-amber-500' : 'border-l-blue-500'
                        } p-0 overflow-hidden shadow-sm hover:shadow-md transition-shadow`}>
                            <div className="p-5">
                                <div className="flex justify-between items-start mb-3">
                                    <div className="flex flex-wrap gap-2">
                                        <Badge variant={classification.variant} className="flex items-center gap-1.5 px-3 py-1 uppercase tracking-widest text-[10px] font-black">
                                            {classification.icon}
                                            {classification.label}
                                        </Badge>
                                        <Badge variant="neutral" className="px-3 py-1 uppercase tracking-widest text-[10px] font-black">
                                            Target: {notification.recipientRole}
                                        </Badge>
                                    </div>
                                    <div className="text-right">
                                        <span className="text-[10px] text-gray-400 font-black uppercase tracking-widest block">Generated On</span>
                                        <span className="text-xs text-gray-600 dark:text-gray-400 font-bold">
                                            {new Date(notification.timestamp).toLocaleString()}
                                        </span>
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <h4 className="text-lg font-black text-gray-900 dark:text-white leading-tight">
                                        {notification.metadata?.clientName ? `${notification.metadata.clientName}: ` : ''}{notification.title}
                                    </h4>
                                    <p className="text-sm text-gray-700 dark:text-gray-300 font-medium">
                                        Trigger Reason: <span className="font-normal italic">{notification.message}</span>
                                    </p>
                                </div>

                                {/* RESCHEDULE AUDIT PANEL */}
                                {isRescheduled && (
                                    <div className="mt-4 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-800 space-y-3">
                                        <p className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest flex items-center gap-1.5">
                                            <ArrowTrendingUpIcon className="w-3.5 h-3.5" />
                                            Audit Trail: Action Rescheduled
                                        </p>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <p className="text-[10px] text-gray-400 uppercase font-black">Original Date</p>
                                                <p className="text-xs font-bold line-through text-gray-500">
                                                    {new Date(notification.timestamp).toLocaleDateString()}
                                                </p>
                                            </div>
                                            <div>
                                                <p className="text-[10px] text-indigo-400 uppercase font-black">New Follow-Up Date</p>
                                                <p className="text-xs font-black text-indigo-600 dark:text-indigo-400 flex items-center gap-1">
                                                    <CalendarDaysIcon className="w-3 h-3" />
                                                    {notification.metadata!.rescheduleHistory![0].newDate}
                                                </p>
                                            </div>
                                        </div>
                                        <div className="pt-2 border-t border-gray-200 dark:border-gray-800">
                                            <p className="text-[10px] text-gray-400 uppercase font-black mb-1">Reschedule Rationale</p>
                                            <p className="text-xs text-gray-600 dark:text-gray-400 italic">
                                                "{notification.metadata!.rescheduleHistory![0].reason}"
                                            </p>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {!notification.isRead && (
                                <div className="flex gap-px bg-gray-200 dark:bg-gray-700 border-t border-gray-200 dark:border-gray-700">
                                    <button 
                                        disabled={isRescheduled}
                                        className={`flex-1 flex items-center justify-center gap-2 py-3 text-xs font-black uppercase tracking-widest transition-colors ${
                                            isRescheduled 
                                            ? 'bg-gray-50 dark:bg-gray-900 text-gray-400 cursor-not-allowed' 
                                            : 'bg-white dark:bg-gray-800 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20'
                                        }`}
                                        onClick={() => setReschedulingId(notification.id)}
                                    >
                                        <CalendarDaysIcon className="w-4 h-4" />
                                        {isRescheduled ? 'Read-Only (Rescheduled)' : 'Reschedule Action'}
                                    </button>
                                    <button 
                                        className="flex-1 flex items-center justify-center gap-2 py-3 bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-900 transition-colors text-xs font-black uppercase tracking-widest"
                                        onClick={() => onMarkRead(notification.id)}
                                    >
                                        <CheckCircleIcon className="w-4 h-4" />
                                        Acknowledge
                                    </button>
                                </div>
                            )}
                        </Card>
                    );
                })}

                {filteredNotifications.length === 0 && (
                    <div className="py-20 text-center bg-gray-50 dark:bg-gray-900/50 rounded-2xl border-2 border-dashed border-gray-200 dark:border-gray-800">
                        <CheckCircleIcon className="w-16 h-16 mx-auto mb-4 text-gray-200 dark:text-gray-800" />
                        <p className="text-lg font-black text-gray-400 uppercase tracking-widest">No Alerts Flagged</p>
                    </div>
                )}
            </div>

            {/* Reschedule Modal - Immutable post-submission */}
            {reschedulingId && (
                <div className="fixed inset-0 bg-black/80 z-[70] flex justify-center items-center p-4 backdrop-blur-sm">
                    <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border border-indigo-500/30">
                        <form onSubmit={handleRescheduleSubmit}>
                            <div className="p-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 flex justify-between items-center">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Reschedule Protocol</h3>
                                <button type="button" onClick={() => setReschedulingId(null)} className="p-1 hover:bg-gray-200 dark:hover:bg-gray-800 rounded-full transition-colors"><XMarkIcon className="w-5 h-5 text-gray-400" /></button>
                            </div>
                            <div className="p-6 space-y-5">
                                <div className="p-3 bg-amber-50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-900/50 rounded flex gap-3">
                                    <ExclamationTriangleIcon className="w-5 h-5 text-amber-600 shrink-0" />
                                    <p className="text-[10px] text-amber-800 dark:text-amber-400 font-bold leading-relaxed uppercase">
                                        Alert: This action is permanent and will be logged in the system audit trail.
                                    </p>
                                </div>
                                <Input 
                                    label="New Follow-up Commitment Date" 
                                    type="date" 
                                    value={rescheduleForm.date}
                                    onChange={e => setRescheduleForm({...rescheduleForm, date: e.target.value})}
                                    required 
                                    className="font-bold"
                                />
                                <Textarea 
                                    label="Justification for Delay" 
                                    value={rescheduleForm.reason}
                                    onChange={e => setRescheduleForm({...rescheduleForm, reason: e.target.value})}
                                    placeholder="Provide business justification..."
                                    required 
                                    rows={4}
                                />
                            </div>
                            <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex gap-3">
                                <Button type="button" variant="secondary" className="flex-1 uppercase font-black text-[10px]" onClick={() => setReschedulingId(null)}>Abort</Button>
                                <Button type="submit" className="flex-1 uppercase font-black text-[10px]">Commit Change</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 4px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #334155; }
            `}</style>
        </div>
    );
};

