import React, { useState, useMemo, useEffect } from 'react';
import { Property, Staff, PriceHistory } from '../types';
import { ArrowLeftIcon, BanknotesIcon, ChartBarIcon, ClockIcon, BuildingLibraryIcon, ArrowTrendingUpIcon, Cog6ToothIcon } from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Input, Select } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';

interface PurchaseSaleManagementPageProps {
    onBack: () => void;
    properties: Property[];
    onSaveProperty: (property: Property) => Promise<void>;
    currentStaff: Staff;
}

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

const PurchaseSaleManagementPage: React.FC<PurchaseSaleManagementPageProps> = ({ onBack, properties, onSaveProperty, currentStaff }) => {
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [editSellingPrice, setEditSellingPrice] = useState<string>('');
    const [plotsPerAcre, setPlotsPerAcre] = useState<string>('6'); // Default system value
    const [isSaving, setIsSaving] = useState(false);

    const selectedProperty = useMemo(() => 
        properties.find(p => p.id === selectedPropertyId), 
    [selectedPropertyId, properties]);

    useEffect(() => {
        if (selectedProperty) {
            setEditSellingPrice(selectedProperty.price.toString());
            // If the property already has specific plot mapping logic, we could load it here
        } else {
            setEditSellingPrice('');
        }
    }, [selectedProperty]);

    const calculations = useMemo(() => {
        if (!selectedProperty) return null;

        const totalAcquisitionCost = (selectedProperty as any).totalAcquisitionCost || 0; 
        const totalSizeAcres = selectedProperty.size || 0;
        const configPlotsPerAcre = parseFloat(plotsPerAcre) || 1;

        // SECTION 1 & 2: Derive Plot counts and Cost Price
        const calculatedTotalPlots = totalSizeAcres * configPlotsPerAcre;
        const costPricePerPlot = calculatedTotalPlots > 0 ? totalAcquisitionCost / calculatedTotalPlots : 0;

        const currentSellingPrice = parseFloat(editSellingPrice) || 0;
        const margin = currentSellingPrice - costPricePerPlot;
        const marginPercentage = costPricePerPlot > 0 ? (margin / costPricePerPlot) * 100 : 0;

        const projectedTotalRevenue = currentSellingPrice * calculatedTotalPlots;
        const grossProfit = projectedTotalRevenue - totalAcquisitionCost;

        return {
            totalAcquisitionCost,
            totalSizeAcres,
            configPlotsPerAcre,
            calculatedTotalPlots,
            costPricePerPlot,
            currentSellingPrice,
            margin,
            marginPercentage,
            projectedTotalRevenue,
            grossProfit
        };
    }, [selectedProperty, editSellingPrice, plotsPerAcre]);

    const handleSave = async () => {
        if (!selectedProperty || !calculations) return;

        setIsSaving(true);
        try {
            const historyEntry: PriceHistory = {
                date: new Date().toISOString(),
                oldPrice: selectedProperty.price,
                newPrice: calculations.currentSellingPrice,
                changedBy: currentStaff.fullName
            };

            const updatedProperty: Property = {
                ...selectedProperty,
                price: calculations.currentSellingPrice,
                priceHistory: [historyEntry, ...(selectedProperty.priceHistory || [])]
            };

            await onSaveProperty(updatedProperty);
            alert("Pricing configuration updated and published.");
        } catch (error) {
            console.error(error);
            alert("Failed to update pricing.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" />
                        Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white mt-2 tracking-tight uppercase">Sales & Management</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Configure pricing models and monitor plot acquisition margins.</p>
                </div>
            </div>

            <Card className="bg-gray-50/50 dark:bg-gray-900/10">
                <div className="max-w-md">
                    <Select 
                        label="Select Property Portfolio"
                        value={selectedPropertyId}
                        onChange={(e) => setSelectedPropertyId(e.target.value ? Number(e.target.value) : '')}
                    >
                        <option value="">-- Choose an acquisition record --</option>
                        {properties.map(p => (
                            <option key={p.id} value={p.id}>{p.location}</option>
                        ))}
                    </Select>
                </div>
            </Card>

            {selectedProperty && calculations ? (
                <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                    <div className="xl:col-span-2 space-y-8">
                        <div className="flex items-center gap-4 p-6 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm">
                            <div className="p-3 rounded-full bg-blue-100 dark:bg-blue-900/30">
                                <BuildingLibraryIcon className="w-8 h-8 text-blue-600" />
                            </div>
                            <div>
                                <h2 className="text-2xl font-black text-gray-900 dark:text-white">{selectedProperty.location}</h2>
                                <p className="text-gray-500 dark:text-gray-400">Total Size: {calculations.totalSizeAcres} Acres</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {/* SECTION 1: Plots-to-Acre Configuration */}
                            <Card title="Land Partitioning Configuration">
                                <div className="space-y-4">
                                    <Input 
                                        label="Number of Plots per Acre"
                                        type="number"
                                        value={plotsPerAcre}
                                        onChange={(e) => setPlotsPerAcre(e.target.value)}
                                        placeholder="e.g. 6"
                                        className="font-bold text-lg"
                                        icon={<Cog6ToothIcon className="w-4 h-4" />}
                                    />
                                    <div className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700">
                                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Resulting Plot Inventory</p>
                                        <p className="text-lg font-black text-gray-800 dark:text-white">{calculations.calculatedTotalPlots.toFixed(1)} Plots</p>
                                        <p className="text-[10px] text-gray-500 mt-1 italic">Calculated from: Total Acres × Plots per Acre</p>
                                    </div>
                                </div>
                            </Card>

                            {/* SECTION 2 & 3: Cost Price per Plot (Read-Only) */}
                            <Card title="Cost Basis (Acquisition)">
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Cost Price per Plot</label>
                                        <div className="px-4 py-3 bg-gray-100 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg font-black text-xl text-gray-600 dark:text-gray-300">
                                            {formatCurrency(calculations.costPricePerPlot)}
                                        </div>
                                        <p className="text-[10px] text-blue-600 dark:text-blue-400 mt-2 font-medium">
                                            Calculated from: Total Acquisition Cost ÷ Number of Plots per Acre
                                        </p>
                                    </div>
                                    <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <p className="text-xs text-gray-500">
                                            Total Acquisition Cost for {selectedProperty.location}: <span className="font-bold">{formatCurrency(calculations.totalAcquisitionCost)}</span>
                                        </p>
                                    </div>
                                </div>
                            </Card>
                        </div>

                        <Card title="Market Pricing Strategy">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div className="space-y-6">
                                    <Input 
                                        label="Target Selling Price per Plot"
                                        type="number"
                                        value={editSellingPrice}
                                        onChange={(e) => setEditSellingPrice(e.target.value)}
                                        placeholder="0.00"
                                        className="font-black text-2xl text-blue-600"
                                    />

                                    <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-lg border border-blue-100 dark:border-blue-900/50">
                                        <p className="text-xs font-bold text-blue-800 dark:text-blue-300 mb-1 flex items-center gap-1">
                                            <ArrowTrendingUpIcon className="w-4 h-4" /> Margin Breakdown
                                        </p>
                                        <p className="text-sm font-medium text-blue-600 dark:text-blue-400">
                                            Projected Profit: <span className="font-black">{formatCurrency(calculations.margin)}</span> per plot.
                                        </p>
                                        <p className="text-[10px] text-blue-500 mt-1 italic">
                                            Calculated from: Selling Price − Cost Price per Plot
                                        </p>
                                    </div>

                                    <div className="flex justify-end pt-4">
                                        <Button 
                                            onClick={handleSave} 
                                            isLoading={isSaving}
                                            className="px-10 py-3 shadow-lg uppercase tracking-wider"
                                        >
                                            Update Published Price
                                        </Button>
                                    </div>
                                </div>

                                <div className="space-y-4 bg-gray-50 dark:bg-gray-900/40 p-6 rounded-xl border border-gray-200 dark:border-gray-700">
                                    <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Pricing Rules Audit</h4>
                                    <div className="space-y-3">
                                        <div className="flex justify-between text-sm">
                                            <span className="text-gray-500">System Default Plots/Acre:</span>
                                            <span className="font-bold text-gray-700 dark:text-gray-300">6.0</span>
                                        </div>
                                        <div className="flex justify-between text-sm">
                                            <span className="text-gray-500">Current Override:</span>
                                            <span className="font-bold text-blue-600">{plotsPerAcre}</span>
                                        </div>
                                        <div className="flex justify-between text-sm pt-2 border-t border-gray-200 dark:border-gray-700">
                                            <span className="text-gray-500">Margin Percentage:</span>
                                            <Badge variant={calculations.marginPercentage >= 20 ? 'success' : 'warning'}>
                                                {calculations.marginPercentage.toFixed(1)}%
                                            </Badge>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </Card>
                    </div>

                    <div className="space-y-6">
                        <div className="bg-gray-900 dark:bg-black text-white rounded-2xl shadow-2xl p-8 border border-gray-700">
                            <h3 className="text-lg font-black uppercase tracking-widest border-b border-gray-800 pb-4 mb-6 flex items-center gap-2">
                                <ChartBarIcon className="w-6 h-6 text-blue-400" /> Executive P&L Summary
                            </h3>

                            <div className="space-y-8">
                                <div className="p-4 bg-gray-800/50 rounded-xl border border-gray-700">
                                    <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Total Projected Revenue</p>
                                    <p className="text-2xl font-black text-blue-400">{formatCurrency(calculations.projectedTotalRevenue)}</p>
                                    <p className="text-[10px] text-gray-500 mt-1 italic">Calculated from: Selling Price × Calculated Total Plots</p>
                                </div>

                                <div className="p-4 bg-gray-800/50 rounded-xl border border-gray-700">
                                    <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Fixed Acquisition Cost</p>
                                    <p className="text-2xl font-black text-gray-300">{formatCurrency(calculations.totalAcquisitionCost)}</p>
