import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, Invoice, Role } from '../types';
import { 
    BanknotesIcon,
    ArrowLeftIcon,
    LockClosedIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    ChevronRightIcon,
    CheckCircleIcon,
    CurrencyDollarIcon,
    PlusCircleIcon
} from './icons/DummyIcons';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Input, Select } from './ui/Input';
import { Badge } from './ui/Badge';
import { useAuth } from '../context/AuthContext';

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

/**
 * Re-authentication Modal for Amendments
 */
const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Verify Identity</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Re-authenticate to unlock financial fields.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Staff Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="email@faim.com" />
                        <Input label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: any) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const selectedClient = useMemo(() => 
        fixedClient || clients.find(c => c.id === selectedClientId),
    [selectedClientId, clients, fixedClient]);

    const [landPrice, setLandPrice] = useState('0');
    const [indenturePrice, setIndenturePrice] = useState('0');
    const [discountValue, setDiscountValue] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [paymentOption, setPaymentOption] = useState('Outright');

    const isInitialized = !!selectedClient?.payment?.isInitialized;
    const canAmend = useMemo(() => {
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'CEO' || roleName === 'Administrator' || roleName === 'Chief Accountant';
    }, [currentStaff, roles]);

    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setIndenturePrice(String((selectedClient.payment as any).indenturePrice || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
            setDiscountValue(String((selectedClient.payment as any).discountValue || '0'));
            setDiscountType((selectedClient.payment as any).discountType || 'percentage');
            setIsUnlocked(false);
        }
    }, [selectedClient]);

    const calculatedTotal = useMemo(() => {
        const P_initial = parseFloat(landPrice) || 0;
        const D = parseFloat(discountValue) || 0;
        let P = discountType === 'percentage' ? P_initial * (1 - (D / 100)) : Math.max(0, P_initial - D);

        if (paymentOption !== 'Outright') {
            const months = parseInt(paymentOption) || 1;
            const annualRate = 0.10;
            const monthlyRate = annualRate / 12;
            const emi = (P * monthlyRate * Math.pow(1 + monthlyRate, months)) / (Math.pow(1 + monthlyRate, months) - 1);
            return emi * months;
        }
        return P;
    }, [landPrice, discountValue, discountType, paymentOption]);

    // SECTION 2: STATUS INDICATOR DERIVATION
    const financialStatus = useMemo(() => {
        if (!selectedClient) return null;
        const paid = selectedClient.payment.paid || 0;
        const total = isInitialized ? selectedClient.payment.total : calculatedTotal;
        const balance = total - paid;

        if (balance === 0 && total > 0) return 'Fully Paid';
        if (balance < 0) return 'Overpaid';
        return 'Owing';
    }, [selectedClient, isInitialized, calculatedTotal]);

    const handleFormSubmit = async () => {
        if (!selectedClient || isSaving) return;
        setIsSaving(true);
        const finalLandPrice = calculatedTotal || parseFloat(landPrice) || 0;
        const finalIndenturePrice = parseFloat(indenturePrice) || 0;

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: finalLandPrice,
                balance: finalLandPrice - selectedClient.payment.paid,
                indenturePrice: finalIndenturePrice,
                discountValue: parseFloat(discountValue) || 0,
                discountType: discountType,
                planType: paymentOption === 'Outright' ? 'Outright Payment' : `${paymentOption}-Month Installment`,
            }
        } as Client;

        try {
            await onSave({ id: `INV-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
            alert("Financial data initialized successfully.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className={`space-y-6 ${className}`}>
            {/* Header / Navigation */}
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div className="flex items-center gap-4">
                    {onBack && (
                        <button onClick={onBack} className="p-2 bg-white dark:bg-gray-800 rounded-full border border-gray-200 dark:border-gray-700 hover:shadow-md transition-all">
                            <ArrowLeftIcon className="w-5 h-5 text-gray-600" />
                        </button>
                    )}
                    <div className="flex items-center gap-3">
                        <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Create & View Financials</h1>
                        {selectedClient && (
                            <Badge 
                                variant={financialStatus === 'Fully Paid' ? 'success' : financialStatus === 'Overpaid' ? 'purple' : 'danger'}
                                className="text-sm px-4 py-1 font-black uppercase tracking-widest border-2"
                            >
                                {financialStatus}
                            </Badge>
                        )}
                    </div>
                </div>

                {isInitialized && !isUnlocked && canAmend && (
                    <Button variant="secondary" icon={<ShieldCheckIcon className="w-4 h-4"/>} onClick={() => setAuthModalOpen(true)}>
                        Unlock for Amendment
                    </Button>
                )}
            </div>

            {/* SECTION 2: CLIENT SWITCHER DROPDOWN */}
            <Card className="p-4 bg-indigo-50/30 dark:bg-indigo-900/10 border-indigo-100 dark:border-indigo-900/50">
                <div className="max-w-md relative" ref={dropdownRef}>
                    <label className="block text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest mb-1.5 ml-1">Active Client Selection</label>
                    <button
                        type="button"
                        onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                        className="flex items-center justify-between w-full px-4 py-3 bg-white dark:bg-gray-800 border-2 border-indigo-200 dark:border-indigo-800 rounded-xl shadow-sm text-sm font-bold text-gray-900 dark:text-white hover:border-indigo-400 transition-all"
                    >
                        <div className="flex items-center gap-3">
                            <div className="w-6 h-6 rounded-full bg-indigo-600 text-white flex items-center justify-center text-[10px]">
                                {selectedClient?.initials || '?'}
                            </div>
                            <span>{selectedClient ? selectedClient.name : 'Select a client to manage...'}</span>
                        </div>
                        <ChevronDownIcon className={`w-5 h-5 text-indigo-400 transition-transform ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                    </button>

                    {isClientDropdownOpen && (
                        <div className="absolute left-0 right-0 mt-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-2xl z-[60] max-h-64 overflow-y-auto scrollbar-thin py-2">
                            {clients.map(client => (
                                <button 
                                    key={client.id} 
                                    onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }}
                                    className={`w-full text-left px-4 py-3 text-sm transition-colors flex items-center justify-between ${selectedClientId === client.id ? 'bg-indigo-50 dark:bg-indigo-900/40 text-indigo-700 dark:text-indigo-300 font-bold' : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50'}`}
                                >
                                    <span>{client.name}</span>
                                    {client.payment?.isInitialized && <Badge variant="success">Initialized</Badge>}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </Card>

            {selectedClient ? (
                <div className="space-y-8 animate-in fade-in duration-500">

                    {/* SECTION 1: LIVE FINANCIAL SUMMARY (Top Positioning) */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <Card className="border-l-4 border-l-blue-600 bg-white dark:bg-gray-800">
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Initialization Amount</p>
                            <div className="text-2xl font-black text-gray-900 dark:text-white mt-1">
                                {formatCurrency(calculatedTotal)}
                            </div>
                            <p className="text-[10px] text-blue-600 mt-1 font-bold italic">Live Computed Total</p>
                        </Card>
                        <Card className="border-l-4 border-l-green-600 bg-white dark:bg-gray-800">
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Receipts to Date</p>
                            <div className="text-2xl font-black text-green-600 dark:text-green-400 mt-1">
                                {formatCurrency(selectedClient.payment.paid)}
                            </div>
                            <p className="text-[10px] text-green-600 mt-1 font-bold italic">Actual Payments Only</p>
                        </Card>
                        <Card className="border-l-4 border-l-amber-600 bg-white dark:bg-gray-800">
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Outstanding Balance</p>
                            <div className="text-2xl font-black text-amber-600 dark:text-amber-400 mt-1">
                                {formatCurrency(Math.max(0, calculatedTotal - selectedClient.payment.paid))}
                            </div>
                            <p className="text-[10px] text-amber-600 mt-1 font-bold italic">Real-time Calculation</p>
                        </Card>
                    </div>

                    {/* SECTION 2: PAYMENT DESCRIPTION (Below Summary) */}
                    <Card title="Payment Description & Configuration">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-6">
                                <div className="relative">
                                    <Input 
                                        label="Base Land Purchase Price" 
                                        type="number" 
                                        value={landPrice} 
                                        onChange={e => setLandPrice(e.target.value)} 
                                        readOnly={isInitialized && !isUnlocked} 
                                        className="font-bold no-spinner"
                                    />
                                    {isInitialized && !isUnlocked && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400" />}
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <Input 
                                        label="Adjustment / Discount" 
