                                        value={discountValue} 
                                        onChange={e => setDiscountValue(e.target.value)} 
                                        readOnly={isInitialized && !isUnlocked}
                                        className="no-spinner"
                                    />
                                    <Select 
                                        label="Discount Unit" 
                                        value={discountType} 
                                        onChange={e => setDiscountType(e.target.value as any)}
                                        disabled={isInitialized && !isUnlocked}
                                    >
                                        <option value="percentage">Percentage (%)</option>
                                        <option value="fixed">Fixed Amount (GHC)</option>
                                    </Select>
                                </div>

                                <Input 
                                    label="Indenture & Documentation Fee" 
                                    type="number" 
                                    value={indenturePrice} 
                                    onChange={e => setIndenturePrice(e.target.value)} 
                                    readOnly={isInitialized && !isUnlocked}
                                    className="no-spinner"
                                />
                            </div>

                            <div className="space-y-6 bg-gray-50 dark:bg-gray-900/50 p-6 rounded-2xl border border-gray-100 dark:border-gray-800">
                                <Select 
                                    label="Repayment Strategy" 
                                    value={paymentOption} 
                                    onChange={e => setPaymentOption(e.target.value)}
                                    disabled={isInitialized && !isUnlocked}
                                >
                                    <option value="Outright">Outright Settlement</option>
                                    <option value="3">3 Months Installment</option>
                                    <option value="6">6 Months Installment</option>
                                    <option value="12">12 Months Installment</option>
                                </Select>

                                <div className="pt-4 border-t border-gray-200 dark:border-gray-700">
                                    <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Financial Protocol Audit</h4>
                                    <div className="space-y-3">
                                        <div className="flex justify-between text-sm">
                                            <span className="text-gray-500">Initialization Status:</span>
                                            {isInitialized ? <Badge variant="success">Active</Badge> : <Badge variant="warning">Draft</Badge>}
                                        </div>
                                        <div className="flex justify-between text-sm">
                                            <span className="text-gray-500">Computed APR Adjustment:</span>
