import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, Invoice, Role } from '../types';
import { 
    ArrowLeftIcon,
    LockClosedIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    CheckCircleIcon,
    CurrencyDollarIcon,
    CalculatorIcon,
    TagIcon
} from './icons/DummyIcons';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Input, Select } from './ui/Input';
import { Badge } from './ui/Badge';
import { useAuth } from '../context/AuthContext';

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

/**
 * Re-authentication Modal for Amendments
 */
const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Verify Identity</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Re-authenticate to unlock financial fields.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Staff Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="email@faim.com" />
                        <Input label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: any) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const selectedClient = useMemo(() => 
        fixedClient || clients.find(c => c.id === selectedClientId),
    [selectedClientId, clients, fixedClient]);

    // UI Form State
    const [landPrice, setLandPrice] = useState('0');
    const [discountValue, setDiscountValue] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [paymentOption, setPaymentOption] = useState('Outright');
    const [validationError, setValidationError] = useState<string | null>(null);

    const isInitialized = !!selectedClient?.payment?.isInitialized;
    const canAmend = useMemo(() => {
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'CEO' || roleName === 'Administrator' || roleName === 'Chief Accountant';
    }, [currentStaff, roles]);

    // Handle initial data loading and client switching
    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
            setDiscountValue(String((selectedClient.payment as any).discountValue || '0'));
            setDiscountType((selectedClient.payment as any).discountType || 'percentage');
            setIsUnlocked(false);
        }
    }, [selectedClient]);

    // Financial Calculation Logic
    const financials = useMemo(() => {
        if (!selectedClient) return null;

        const basePrice = parseFloat(landPrice) || 0;
        const discValue = parseFloat(discountValue) || 0;

        // 1. Calculate Price after Discount
        let priceAfterDiscount = discountType === 'percentage' 
            ? basePrice * (1 - (discValue / 100)) 
            : Math.max(0, basePrice - discValue);

        // 2. Compute EMI and Service Fees (Simulation: 10% APR for installments)
        let emiAmount = 0;
        let finalPrice = priceAfterDiscount;
        const months = paymentOption === 'Outright' ? 0 : parseInt(paymentOption);

        if (months > 0) {
            const annualRate = 0.10;
            const monthlyRate = annualRate / 12;
            emiAmount = (priceAfterDiscount * monthlyRate * Math.pow(1 + monthlyRate, months)) / (Math.pow(1 + monthlyRate, months) - 1);
            finalPrice = emiAmount * months;
        }

        return {
            priceAfterDiscount,
            emiAmount,
            finalPrice,
            months,
            plotCount: selectedClient.plot?.split(',').length || 1
        };
    }, [selectedClient, landPrice, discountValue, discountType, paymentOption]);

    // Validation wrapper for manual numeric entries
    const handleNumericChange = (setter: (v: string) => void, value: string) => {
        if (value === '' || /^\d*\.?\d*$/.test(value)) {
            setter(value);
            setValidationError(null);
        } else {
            setValidationError("Alphabetic characters detected. Please enter numeric values only.");
        }
    };

    const handleFormSubmit = async () => {
        if (!selectedClient || isSaving || validationError) return;
        setIsSaving(true);

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: financials?.finalPrice || 0,
                balance: (financials?.finalPrice || 0) - selectedClient.payment.paid,
                discountValue: parseFloat(discountValue) || 0,
                discountType: discountType,
                planType: paymentOption === 'Outright' ? 'Outright Payment' : `${paymentOption}-Month Installment`,
            }
        } as Client;

        try {
            await onSave({ id: `INV-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
            alert("Payment protocol finalized.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className={`space-y-6 ${className}`}>
            {/* Page Header */}
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div className="flex items-center gap-4">
                    {onBack && (
                        <button onClick={onBack} className="p-2 bg-white dark:bg-gray-800 rounded-full border border-gray-200 dark:border-gray-700 hover:shadow-md transition-all">
                            <ArrowLeftIcon className="w-5 h-5 text-gray-600" />
                        </button>
                    )}
                    <div>
                        <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Create & View Financials</h1>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">Configure payment structures and financial initialization.</p>
                    </div>
                </div>

                {isInitialized && !isUnlocked && canAmend && (
                    <Button variant="secondary" icon={<ShieldCheckIcon className="w-4 h-4"/>} onClick={() => setAuthModalOpen(true)}>
                        Unlock Protocol
                    </Button>
                )}
            </div>

            {/* Client Selection Dropdown */}
            <Card className="p-4 bg-indigo-50/30 dark:bg-indigo-900/10 border-indigo-100 dark:border-indigo-900/50">
                <div className="max-w-md relative" ref={dropdownRef}>
                    <label className="block text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest mb-1.5 ml-1">Account Portfolio</label>
                    <button
                        type="button"
                        onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                        className="flex items-center justify-between w-full px-4 py-3 bg-white dark:bg-gray-800 border-2 border-indigo-200 dark:border-indigo-800 rounded-xl shadow-sm text-sm font-bold text-gray-900 dark:text-white hover:border-indigo-400 transition-all"
                    >
                        <div className="flex items-center gap-3">
                            <div className="w-6 h-6 rounded-full bg-indigo-600 text-white flex items-center justify-center text-[10px] font-black">
                                {selectedClient?.initials || '?'}
                            </div>
                            <span>{selectedClient ? selectedClient.name : 'Choose Client...'}</span>
                        </div>
                        <ChevronDownIcon className={`w-5 h-5 text-indigo-400 transition-transform ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                    </button>

                    {isClientDropdownOpen && (
                        <div className="absolute left-0 right-0 mt-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-2xl z-[60] max-h-64 overflow-y-auto scrollbar-thin py-2">
                            {clients.map(client => (
                                <button 
                                    key={client.id} 
                                    onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }}
                                    className={`w-full text-left px-4 py-3 text-sm transition-colors flex items-center justify-between ${selectedClientId === client.id ? 'bg-indigo-50 dark:bg-indigo-900/40 text-indigo-700 dark:text-indigo-300 font-black' : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50'}`}
                                >
                                    <span>{client.name}</span>
                                    {client.payment?.isInitialized && <Badge variant="success">Protocol Active</Badge>}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </Card>

            {selectedClient ? (
                <div className="space-y-8">

                    {/* SECTION 1: LIVE FINANCIAL SUMMARY */}
                    <Card className="border-l-4 border-l-blue-600 bg-blue-50/20 dark:bg-blue-900/5">
                        <div className="flex items-center gap-2 mb-4">
                            <CalculatorIcon className="w-5 h-5 text-blue-600" />
                            <h3 className="text-sm font-black text-blue-600 uppercase tracking-widest">Live Financial Summary</h3>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-y-6 gap-x-12">
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Target Client</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{selectedClient.name}</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Purchase Price</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{formatCurrency(parseFloat(landPrice) || 0)}</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Inventory Allocation</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{financials?.plotCount} Plot(s)</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Installment Option</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{financials?.months || 0} Months</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-wider">Monthly Installment (EMI)</p>
                                <p className="text-lg font-black text-indigo-600 dark:text-indigo-400">{formatCurrency(financials?.emiAmount || 0)}</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-green-600 uppercase tracking-wider">New Adjusted Price</p>
                                <p className="text-2xl font-black text-green-600 dark:text-green-400">{formatCurrency(financials?.finalPrice || 0)}</p>
                            </div>
                        </div>
                    </Card>

                    {/* SECTION 2: PAYMENT DESCRIPTION */}
                    <Card className="relative">
                        <div className="flex items-center justify-between mb-6">
                            <div className="flex items-center gap-2">
                                {isInitialized && <div className="w-2.5 h-2.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>}
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Payment Description</h3>
                            </div>
                            {validationError && (
                                <Badge variant="danger" className="animate-pulse">
                                    <ExclamationTriangleIcon className="w-3 h-3 mr-1" />
                                    {validationError}
                                </Badge>
                            )}
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-6">
                                <div className="relative">
                                    <Input 
                                        label="Base Land Purchase Price*" 
                                        type="text" 
                                        value={landPrice} 
                                        onChange={e => handleNumericChange(setLandPrice, e.target.value)} 
                                        readOnly={isInitialized && !isUnlocked} 
                                        className="font-black text-lg no-spinner"
                                        placeholder="0.00"
                                    />
                                    {isInitialized && !isUnlocked && <LockClosedIcon className="absolute right-3 top-[38px] w-4 h-4 text-gray-400" />}
                                </div>

                                <div className="space-y-4">
                                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest">Pricing Adjustments (Optional)</label>
                                    <div className="flex gap-px bg-gray-200 dark:bg-gray-700 border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
                                        <button 
                                            type="button"
                                            disabled={isInitialized && !isUnlocked}
                                            onClick={() => { setDiscountType('percentage'); setDiscountValue('0'); }}
                                            className={`flex-1 py-2 text-xs font-black transition-colors ${discountType === 'percentage' ? 'bg-indigo-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-500 hover:bg-gray-50'}`}
                                        >
                                            PERCENTAGE (%)
                                        </button>
                                        <button 
                                            type="button"
                                            disabled={isInitialized && !isUnlocked}
                                            onClick={() => { setDiscountType('fixed'); setDiscountValue('0'); }}
                                            className={`flex-1 py-2 text-xs font-black transition-colors ${discountType === 'fixed' ? 'bg-indigo-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-500 hover:bg-gray-50'}`}
                                        >
                                            FIXED AMOUNT (GHC)
                                        </button>
                                    </div>
                                    <Input 
                                        label={`Enter ${discountType === 'percentage' ? 'Percentage Value' : 'Discount Amount'}`} 
                                        type="text" 
                                        value={discountValue} 
                                        onChange={e => handleNumericChange(setDiscountValue, e.target.value)} 
                                        readOnly={isInitialized && !isUnlocked}
                                        placeholder="0"
                                    />
                                </div>
                            </div>

                            <div className="space-y-6 bg-gray-50 dark:bg-gray-900/50 p-6 rounded-2xl border border-gray-100 dark:border-gray-800">
                                <Select 
                                    label="Repayment Protocol*" 
                                    value={paymentOption} 
                                    onChange={e => setPaymentOption(e.target.value)}
                                    disabled={isInitialized && !isUnlocked}
                                    className="font-bold"
                                >
                                    <option value="Outright">Outright Settlement (No Service Fee)</option>
                                    <option value="3">3 Months (Standard Interest)</option>
                                    <option value="6">6 Months (Standard Interest)</option>
                                    <option value="12">12 Months (Extended Term)</option>
                                </Select>

                                <div className="pt-4 border-t border-gray-200 dark:border-gray-700 space-y-4">
                                    <div className="flex items-center gap-2 text-xs text-blue-600 font-bold">
                                        <TagIcon className="w-4 h-4" /> System computed adjustment: {paymentOption === 'Outright' ? '0.00%' : '10.00% APR'}
                                    </div>

                                    {(!isInitialized || isUnlocked) && (
                                        <Button 
