import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, Invoice, Role } from '../types';
import { 
    ArrowLeftIcon,
    LockClosedIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    CheckCircleIcon,
    CurrencyDollarIcon,
    CalculatorIcon,
    TagIcon,
    // FIX: Added missing ExclamationTriangleIcon import
    ExclamationTriangleIcon
} from './icons/DummyIcons';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { Input, Select } from './ui/Input';
import { Badge } from './ui/Badge';
import { useAuth } from '../context/AuthContext';

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

/**
 * Re-authentication Modal for Amendments
 */
const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Verify Identity</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Re-authenticate to unlock financial fields.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Staff Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="email@faim.com" />
                        <Input label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: any) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const selectedClient = useMemo(() => 
        fixedClient || clients.find(c => c.id === selectedClientId),
    [selectedClientId, clients, fixedClient]);

    // UI Form State
    const [landPrice, setLandPrice] = useState('0');
    const [discountValue, setDiscountValue] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [paymentOption, setPaymentOption] = useState('Outright');
    const [validationError, setValidationError] = useState<string | null>(null);

    const isInitialized = !!selectedClient?.payment?.isInitialized;
    const canAmend = useMemo(() => {
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'CEO' || roleName === 'Administrator' || roleName === 'Chief Accountant';
    }, [currentStaff, roles]);

    // Handle initial data loading and client switching
    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
            setDiscountValue(String((selectedClient.payment as any).discountValue || '0'));
            setDiscountType((selectedClient.payment as any).discountType || 'percentage');
            setIsUnlocked(false);
        }
    }, [selectedClient]);

    // Financial Calculation Logic
    const financials = useMemo(() => {
        if (!selectedClient) return null;

        const basePrice = parseFloat(landPrice) || 0;
        const discValue = parseFloat(discountValue) || 0;

        // 1. Calculate Price after Discount
        let priceAfterDiscount = discountType === 'percentage' 
            ? basePrice * (1 - (discValue / 100)) 
            : Math.max(0, basePrice - discValue);

        // 2. Compute EMI and Service Fees (Simulation: 10% APR for installments)
        let emiAmount = 0;
        let finalPrice = priceAfterDiscount;
        const months = paymentOption === 'Outright' ? 0 : parseInt(paymentOption);

        if (months > 0) {
            const annualRate = 0.10;
            const monthlyRate = annualRate / 12;
            emiAmount = (priceAfterDiscount * monthlyRate * Math.pow(1 + monthlyRate, months)) / (Math.pow(1 + monthlyRate, months) - 1);
            finalPrice = emiAmount * months;
        }

        return {
            priceAfterDiscount,
            emiAmount,
            finalPrice,
            months,
            plotCount: selectedClient.plot?.split(',').length || 1
        };
    }, [selectedClient, landPrice, discountValue, discountType, paymentOption]);

    // Validation wrapper for manual numeric entries
    const handleNumericChange = (setter: (v: string) => void, value: string) => {
        if (value === '' || /^\d*\.?\d*$/.test(value)) {
            setter(value);
            setValidationError(null);
        } else {
            setValidationError("Alphabetic characters detected. Please enter numeric values only.");
        }
    };

    const handleFormSubmit = async () => {
        if (!selectedClient || isSaving || validationError) return;
        setIsSaving(true);

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: financials?.finalPrice || 0,
                balance: (financials?.finalPrice || 0) - selectedClient.payment.paid,
                discountValue: parseFloat(discountValue) || 0,
                discountType: discountType,
                planType: paymentOption === 'Outright' ? 'Outright Payment' : `${paymentOption}-Month Installment`,
            }
        } as Client;

        try {
            await onSave({ id: `INV-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
            alert("Payment protocol finalized.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className={`space-y-6 ${className}`}>
            {/* Page Header */}
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div className="flex items-center gap-4">
                    {onBack && (
                        <button onClick={onBack} className="p-2 bg-white dark:bg-gray-800 rounded-full border border-gray-200 dark:border-gray-700 hover:shadow-md transition-all">
                            <ArrowLeftIcon className="w-5 h-5 text-gray-600" />
                        </button>
                    )}
                    <div>
                        <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Create & View Financials</h1>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">Configure payment structures and financial initialization.</p>
                    </div>
                </div>

                {isInitialized && !isUnlocked && canAmend && (
                    <Button variant="secondary" icon={<ShieldCheckIcon className="w-4 h-4"/>} onClick={() => setAuthModalOpen(true)}>
                        Unlock Protocol
                    </Button>
                )}
            </div>

            {/* Client Selection Dropdown */}
            <Card className="p-4 bg-indigo-50/30 dark:bg-indigo-900/10 border-indigo-100 dark:border-indigo-900/50">
                <div className="max-w-md relative" ref={dropdownRef}>
                    <label className="block text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest mb-1.5 ml-1">Account Portfolio</label>
                    <button
                        type="button"
                        onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                        className="flex items-center justify-between w-full px-4 py-3 bg-white dark:bg-gray-800 border-2 border-indigo-200 dark:border-indigo-800 rounded-xl shadow-sm text-sm font-bold text-gray-900 dark:text-white hover:border-indigo-400 transition-all"
                    >
                        <div className="flex items-center gap-3">
                            <div className="w-6 h-6 rounded-full bg-indigo-600 text-white flex items-center justify-center text-[10px] font-black">
                                {selectedClient?.initials || '?'}
                            </div>
                            <span>{selectedClient ? selectedClient.name : 'Choose Client...'}</span>
                        </div>
                        <ChevronDownIcon className={`w-5 h-5 text-indigo-400 transition-transform ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                    </button>

                    {isClientDropdownOpen && (
                        <div className="absolute left-0 right-0 mt-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-2xl z-[60] max-h-64 overflow-y-auto scrollbar-thin py-2">
                            {clients.map(client => (
                                <button 
                                    key={client.id} 
                                    onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }}
                                    className={`w-full text-left px-4 py-3 text-sm transition-colors flex items-center justify-between ${selectedClientId === client.id ? 'bg-indigo-50 dark:bg-indigo-900/40 text-indigo-700 dark:text-indigo-300 font-black' : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50'}`}
                                >
                                    <span>{client.name}</span>
                                    {client.payment?.isInitialized && <Badge variant="success">Protocol Active</Badge>}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </Card>

            {selectedClient ? (
                <div className="space-y-8">

                    {/* SECTION 1: LIVE FINANCIAL SUMMARY */}
                    <Card className="border-l-4 border-l-blue-600 bg-blue-50/20 dark:bg-blue-900/5">
                        <div className="flex items-center gap-2 mb-4">
                            <CalculatorIcon className="w-5 h-5 text-blue-600" />
                            <h3 className="text-sm font-black text-blue-600 uppercase tracking-widest">Live Financial Summary</h3>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-y-6 gap-x-12">
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Target Client</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{selectedClient.name}</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Purchase Price</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{formatCurrency(parseFloat(landPrice) || 0)}</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Inventory Allocation</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{financials?.plotCount} Plot(s)</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Installment Option</p>
                                <p className="text-lg font-black text-gray-900 dark:text-white">{financials?.months || 0} Months</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-wider">Monthly Installment (EMI)</p>
                                <p className="text-lg font-black text-indigo-600 dark:text-indigo-400">{formatCurrency(financials?.emiAmount || 0)}</p>
                            </div>
                            <div className="space-y-1">
                                <p className="text-[10px] font-bold text-green-600 uppercase tracking-wider">New Adjusted Price</p>
                                <p className="text-2xl font-black text-green-600 dark:text-green-400">{formatCurrency(financials?.finalPrice || 0)}</p>
                            </div>
                        </div>
                    </Card>

                    {/* SECTION 2: PAYMENT DESCRIPTION */}
                    <Card className="relative">
                        <div className="flex items-center justify-between mb-6">
                            <div className="flex items-center gap-2">
                                {isInitialized && <div className="w-2.5 h-2.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>}
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Payment Description</h3>
                            </div>
                            {validationError && (
                                <Badge variant="danger" className="animate-pulse">
                                    <ExclamationTriangleIcon className="w-3 h-3 mr-1" />
                                    {validationError}
                                </Badge>
                            )}
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-6">
                                <div className="relative">
                                    <Input 
                                        label="Base Land Purchase Price*" 
                                        type="text" 
                                        value={landPrice} 
                                        onChange={e => handleNumericChange(setLandPrice, e.target.value)} 
                                        readOnly={isInitialized && !isUnlocked} 
                                        className="font-black text-lg no-spinner"
                                        placeholder="0.00"
                                    />
                                    {isInitialized && !isUnlocked && <LockClosedIcon className="absolute right-3 top-[38px] w-4 h-4 text-gray-400" />}
                                </div>

                                <div className="space-y-4">
                                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest">Pricing Adjustments (Optional)</label>
                                    <div className="flex gap-px bg-gray-200 dark:bg-gray-700 border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
                                        <button 
                                            type="button"
                                            disabled={isInitialized && !isUnlocked}
                                            onClick={() => { setDiscountType('percentage'); setDiscountValue('0'); }}
                                            className={`flex-1 py-2 text-xs font-black transition-colors ${discountType === 'percentage' ? 'bg-indigo-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-500 hover:bg-gray-50'}`}
                                        >
                                            PERCENTAGE (%)
                                        </button>
                                        <button 
                                            type="button"
                                            disabled={isInitialized && !isUnlocked}
                                            onClick={() => { setDiscountType('fixed'); setDiscountValue('0'); }}
                                            className={`flex-1 py-2 text-xs font-black transition-colors ${discountType === 'fixed' ? 'bg-indigo-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-500 hover:bg-gray-50'}`}
                                        >
                                            FIXED AMOUNT (GHC)
                                        </button>
                                    </div>
                                    <Input 
                                        label={`Enter ${discountType === 'percentage' ? 'Percentage Value' : 'Discount Amount'}`} 
                                        type="text" 
                                        value={discountValue} 
                                        onChange={e => handleNumericChange(setDiscountValue, e.target.value)} 
                                        readOnly={isInitialized && !isUnlocked}
                                        placeholder="0"
                                    />
                                </div>
                            </div>

                            <div className="space-y-6 bg-gray-50 dark:bg-gray-900/50 p-6 rounded-2xl border border-gray-100 dark:border-gray-800">
                                <Select 
                                    label="Repayment Protocol*" 
                                    value={paymentOption} 
                                    onChange={e => setPaymentOption(e.target.value)}
                                    disabled={isInitialized && !isUnlocked}
                                    className="font-bold"
                                >
                                    <option value="Outright">Outright Settlement (No Service Fee)</option>
                                    <option value="3">3 Months (Standard Interest)</option>
                                    <option value="6">6 Months (Standard Interest)</option>
                                    <option value="12">12 Months (Extended Term)</option>
                                </Select>

                                <div className="pt-4 border-t border-gray-200 dark:border-gray-700 space-y-4">
                                    <div className="flex items-center gap-2 text-xs text-blue-600 font-bold">
                                        <TagIcon className="w-4 h-4" /> System computed adjustment: {paymentOption === 'Outright' ? '0.00%' : '10.00% APR'}
                                    </div>

                                    {(!isInitialized || isUnlocked) && (
                                        <Button 
                                            onClick={handleFormSubmit} 
                                            className="w-full py-4 shadow-lg text-lg font-black uppercase tracking-wider" 
                                            isLoading={isSaving}
                                            disabled={!!validationError}
                                            icon={<CheckCircleIcon className="w-5 h-5" />}
                                        >
                                            Initialize Protocol
                                        </Button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </Card>
                </div>
            ) : (
                <div className="py-40 text-center bg-white dark:bg-gray-800 rounded-3xl border border-dashed border-gray-300 dark:border-gray-700 opacity-60">
                    <CurrencyDollarIcon className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <h2 className="text-xl font-bold text-gray-400 uppercase tracking-widest">Select Account Portfolio</h2>
                    <p className="text-sm text-gray-400 mt-2">Select a client from the dropdown above to manage their financial initialization.</p>
                </div>
            )}

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 5px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #334155; }
                .no-spinner::-webkit-inner-spin-button, .no-spinner::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, ChangeEvent, FormEvent } from 'react';
import { Property, VendorLandPurchase, Payee, PlotInventory, PlotSize } from '../types';
import { ArrowLeftIcon, CheckCircleIcon, PlusCircleIcon, TrashIcon, UploadIcon, BanknotesIcon } from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Input, Select, Textarea } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { uploadFile } from '../services/storageService';

interface LandPurchaseFormPageProps {
  onBack: () => void;
  properties: Property[];
  onSaveProperty: (property: Property) => Promise<void>;
}

const PLOT_SIZE_SQFT: Record<string, number> = {
    '70x100 ft': 7000,
    '70x50 ft': 3500,
    '60x80 ft': 4800,
};
const ACRE_SQFT = 43560;

const FileUploadField: React.FC<{ id: string; label: string; file: File | null | undefined; onChange: (e: ChangeEvent<HTMLInputElement>) => void; accept: string; }> = ({ id, label, file, onChange, accept }) => (
    <div className="sm:col-span-1">
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">{label}</label>
        <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 dark:border-gray-700 border-dashed rounded-md hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
            <div className="space-y-1 text-center">
                <UploadIcon className="mx-auto h-12 w-12 text-gray-400 dark:text-gray-500" />
                <div className="flex text-sm text-gray-600 dark:text-gray-400">
                    <label htmlFor={id} className="relative cursor-pointer rounded-md font-medium text-blue-600 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                        <span>Upload a file</span>
                        <input id={id} name={id} type="file" className="sr-only" onChange={onChange} accept={accept} />
                    </label>
                    <p className="pl-1">or drag and drop</p>
                </div>
                <p className="text-xs text-gray-500 dark:text-gray-500">{file ? file.name : "PDF, PNG, JPG up to 10MB"}</p>
            </div>
        </div>
    </div>
);

const initialFormData: VendorLandPurchase & { plotsPerAcre: string; pricePerPlot: string } = {
    ownerNames: '',
    location: '',
    registrationStatus: '',
    purchaseAgreementDate: '',
    totalSizeAcres: '',
    pricePerAcre: '',
    totalPrice: '',
    familyName: '',
    nameOnSearch: '',
    officialSearchDoc: null,
    sitePlanDoc: null,
    leadNegotiators: '',
    familyContactPerson: '',
    phoneNumbers: ['', '', ''],
    additionalNotes: '',
    paymentAmountPerMonth: '',
    paymentPeriodMonths: '',
    recurringPaymentTime: '',
    payees: [],
    plotInventory: [{ size: '70x100 ft', count: '' }],
    signingDate: new Date().toISOString().split('T')[0],
    familyRepSignature: { name: '', date: ''},
    ceoSignature: { name: '', date: '' },
    managingDirectorSignature: { name: '', date: '' },
    accountsHeadSignature: { name: '', date: '' },
    // New pricing reference fields
    plotsPerAcre: '6', // Default standard
    pricePerPlot: '',
};


const LandPurchaseFormPage: React.FC<LandPurchaseFormPageProps> = ({ onBack, properties, onSaveProperty }) => {
    const [formData, setFormData] = useState<typeof initialFormData & { customDimensions: Record<number, { length: string, width: string }> }>(() => ({
        ...initialFormData,
        customDimensions: {}
    }));
    const [isSaved, setIsSaved] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [plotsPerAcreError, setPlotsPerAcreError] = useState('');

    useEffect(() => {
        const totalSqFt = formData.plotInventory.reduce((sum, item, index) => {
            const count = parseInt(item.count) || 0;
            let sqft = 0;
            if (item.size === 'Other') {
                const dims = formData.customDimensions[index];
                if (dims) {
                    sqft = (parseFloat(dims.length) || 0) * (parseFloat(dims.width) || 0);
                }
            } else {
                sqft = PLOT_SIZE_SQFT[item.size] || 0;
            }
            return sum + (sqft * count);
        }, 0);

        const totalAcres = totalSqFt > 0 ? (totalSqFt / ACRE_SQFT).toFixed(4) : '';
        const price = parseFloat(formData.pricePerAcre);
        const totalPriceVal = (!isNaN(parseFloat(totalAcres)) && !isNaN(price)) ? (parseFloat(totalAcres) * price) : 0;

        // Price Per Plot Calculation Logic
        const ppa = parseFloat(formData.plotsPerAcre);
        let calculatedPricePerPlot = '';
        if (ppa > 0 && !isNaN(price)) {
            // Price Per Plot = Price Per Acre / Plots Per Acre
            calculatedPricePerPlot = (price / ppa).toFixed(2);
        }

        setFormData(prev => ({
            ...prev, 
            totalSizeAcres: totalAcres,
            totalPrice: totalPriceVal > 0 ? totalPriceVal.toFixed(2) : '',
            pricePerPlot: calculatedPricePerPlot
        }));
    }, [formData.plotInventory, formData.pricePerAcre, formData.customDimensions, formData.plotsPerAcre]);

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value } = e.target;

        if (name === 'plotsPerAcre') {
            if (value !== '' && !/^\d*\.?\d*$/.test(value)) {
                setPlotsPerAcreError('Please enter numbers only.');
                return;
            }
            setPlotsPerAcreError('');
        }

        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (index: number, value: string) => {
        const newPhones = [...formData.phoneNumbers];
        newPhones[index] = value;
        setFormData(prev => ({...prev, phoneNumbers: newPhones}));
    };

    const handleSignatureChange = (signatory: keyof VendorLandPurchase, field: 'name' | 'date', value: string) => {
        setFormData(prev => ({
            ...prev,
            [signatory]: { ...(prev[signatory] as object), [field]: value }
        }));
    };

    const addPayee = () => {
        if (formData.payees.length < 10) {
            setFormData(prev => ({
                ...prev,
                payees: [...prev.payees, { id: Date.now().toString(), name: '', acres: '', amount: '' }]
            }));
        }
    };

    const handlePayeeChange = (index: number, field: keyof Omit<Payee, 'id'>, value: string) => {
        const newPayees = [...formData.payees];
        newPayees[index] = { ...newPayees[index], [field]: value };
        setFormData(prev => ({ ...prev, payees: newPayees }));
    };

    const removePayee = (id: string) => {
        setFormData(prev => ({ ...prev, payees: prev.payees.filter(p => p.id !== id) }));
    };

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        const { name, files } = e.target;
        setFormData(prev => ({ ...prev, [name]: (files && files.length > 0) ? files[0] : null }));
    };

    const handleInventoryChange = (index: number, field: 'size' | 'count', value: string) => {
        const newInventory = [...formData.plotInventory];
        newInventory[index] = {...newInventory[index], [field]: value as PlotSize};

        if (field === 'size' && value === 'Other') {
            setFormData(prev => ({
                ...prev,
                plotInventory: newInventory,
                customDimensions: { ...prev.customDimensions, [index]: { length: '', width: '' } }
            }));
        } else {
            setFormData(prev => ({ ...prev, plotInventory: newInventory }));
        }
    };

    const handleDimensionChange = (index: number, dimension: 'length' | 'width', value: string) => {
        setFormData(prev => ({
            ...prev,
            customDimensions: {
                ...prev.customDimensions,
                [index]: { ...prev.customDimensions[index], [dimension]: value }
            }
        }));
    };

    const addInventoryRow = () => {
        setFormData(prev => ({...prev, plotInventory: [...prev.plotInventory, {size: '70x100 ft', count: ''}]}));
    };

    const removeInventoryRow = (index: number) => {
        if (formData.plotInventory.length > 1) {
            const newInventory = formData.plotInventory.filter((_, i) => i !== index);
            const newDims = { ...formData.customDimensions };
            delete newDims[index];
            setFormData(prev => ({...prev, plotInventory: newInventory, customDimensions: newDims}));
        }
    };

    const formatCurrency = (val: string) => {
        const num = parseFloat(val);
        if (isNaN(num)) return '0.00';
        return new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(num);
    };

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        if (plotsPerAcreError || parseFloat(formData.plotsPerAcre) <= 0) {
            alert('Please provide a valid number of plots per acre.');
            return;
        }
        setIsSaving(true);

        try {
            const regStatusMap: Record<string, Property['registrationStatus']> = {
                'LRD': 'Titled', 'PVLMD': 'Indenture', 'SMD': 'Plotted', 'LVD': 'Indenture'
            };

            const totalSizeAcres = parseFloat(formData.totalSizeAcres) || 0;

            const finalInventory: PlotInventory[] = formData.plotInventory
                .filter(item => parseInt(item.count) > 0)
                .map((item, index) => {
                    let sizeLabel = item.size;
                    if (item.size === 'Other') {
                        const dims = formData.customDimensions[index];
                        sizeLabel = `${dims?.length || 0}x${dims?.width || 0} ft` as any;
                    }
                    return {
                        size: sizeLabel as any,
                        count: parseInt(item.count),
                        sold: 0
                    };
                });

            const propertyId = Date.now();

            let officialSearchDocUrl = '';
            if (formData.officialSearchDoc) {
                officialSearchDocUrl = await uploadFile(formData.officialSearchDoc, `properties/${propertyId}/legal/${formData.officialSearchDoc.name}`);
            }

            let sitePlanDocUrl = '';
            if (formData.sitePlanDoc) {
                sitePlanDocUrl = await uploadFile(formData.sitePlanDoc, `properties/${propertyId}/legal/${formData.sitePlanDoc.name}`);
            }

            const newProperty: Property = {
                id: propertyId,
                location: formData.location,
                description: `Land acquired from ${formData.ownerNames}`,
                size: totalSizeAcres,
                price: parseFloat(formData.pricePerPlot) || 0, // Save calculated plot price as baseline
                costPrice: parseFloat(formData.pricePerPlot) || 0, // Set acquisition cost price
                inventory: finalInventory,
                registrationStatus: regStatusMap[formData.registrationStatus] || 'Plotted',
            };

            await onSaveProperty(newProperty);

            setIsSaved(true);
            window.scrollTo(0, 0);
            setTimeout(() => {
                setIsSaved(false);
                setFormData({ ...initialFormData, customDimensions: {} });
            }, 4000);
        } catch (error) {
            console.error("Error saving property:", error);
            alert("Failed to save property.");
        } finally {
            setIsSaving(false);
        }
    };

    const signatureFields: {key: 'familyRepSignature' | 'ceoSignature' | 'managingDirectorSignature' | 'accountsHeadSignature', label: string}[] = [
        {key: 'familyRepSignature', label: 'Family Representative'},
        {key: 'ceoSignature', label: 'CEO'},
        {key: 'managingDirectorSignature', label: 'Managing Director/Administrator'},
        {key: 'accountsHeadSignature', label: 'Accounts Head of Department'}
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                 <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" />
                        Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white mt-2 tracking-tight uppercase">New Land Acquisition</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Record details for newly purchased land assets.</p>
                </div>
            </div>

            {isSaved && (
                <div className="bg-green-100 dark:bg-green-900/30 border-l-4 border-green-500 text-green-700 dark:text-green-300 p-4 rounded-lg shadow-md" role="alert">
                    <div className="flex items-center">
                        <CheckCircleIcon className="w-6 h-6 mr-3"/>
                        <div>
                            <p className="font-bold">Acquisition Success!</p>
                            <p>Land record finalized and added to master property inventory.</p>
                        </div>
                    </div>
                </div>
            )}

            <form id="land-purchase-form" onSubmit={handleSubmit} className="space-y-6 pb-20">
                <Card title="Section 1: Land, Inventory & Ownership Details">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <Input id="ownerNames" name="ownerNames" label="Name of Owner(s)" value={formData.ownerNames} onChange={handleChange} required containerClassName="md:col-span-2" />
                        <Input id="location" name="location" label="Location of Property" value={formData.location} onChange={handleChange} required />
                    </div>
                    <div className="mt-6 pt-4 border-t border-gray-200 dark:border-gray-700">
                        <h4 className="text-lg font-medium text-gray-800 dark:text-white">Plot Partitioning</h4>
                        <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">Specify the number of plots for each available size to compute total acreage.</p>
                        <div className="space-y-6">
                           {formData.plotInventory.map((item, index) => {
                               const isOther = item.size === 'Other';
                               const currentDims = formData.customDimensions[index];
                               const computedSqFt = isOther && currentDims 
                                    ? (parseFloat(currentDims.length) || 0) * (parseFloat(currentDims.width) || 0)
                                    : (PLOT_SIZE_SQFT[item.size] || 0);

                               return (
                                   <div key={index} className="p-4 bg-white dark:bg-gray-800/50 border border-gray-100 dark:border-gray-700 rounded-xl space-y-4 shadow-sm relative group transition-all hover:border-blue-200">
                                       <button type="button" onClick={() => removeInventoryRow(index)} className="absolute top-4 right-4 text-gray-400 hover:text-red-500 transition-colors">
                                           <TrashIcon className="w-5 h-5"/>
                                       </button>

                                       <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
                                           <Select id={`plot-size-${index}`} label="Plot Size Category" value={item.size} onChange={(e) => handleInventoryChange(index, 'size', e.target.value)}>
                                                <option>70x100 ft</option>
                                                <option>70x50 ft</option>
                                                <option>60x80 ft</option>
                                                <option value="Other">Other (Custom Dimensions)</option>
                                           </Select>

                                           {isOther && (
                                               <div className="md:col-span-2 grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-left-2 duration-300">
                                                   <Input 
                                                       label="Length (feet)" 
                                                       type="text" 
                                                       value={currentDims?.length || ''} 
                                                       onChange={e => handleDimensionChange(index, 'length', e.target.value)} 
                                                       placeholder="e.g. 50" 
                                                       required
                                                       className="no-spinner"
                                                   />
                                                   <Input 
                                                       label="Width (feet)" 
                                                       type="text" 
                                                       value={currentDims?.width || ''} 
                                                       onChange={e => handleDimensionChange(index, 'width', e.target.value)} 
                                                       placeholder="e.g. 50"
                                                       required
                                                       className="no-spinner"
                                                   />
                                               </div>
                                           )}

                                           <Input id={`plot-count-${index}`} label="Number of Plots" type="number" value={item.count} onChange={(e) => handleInventoryChange(index, 'count', e.target.value)} placeholder="0" containerClassName="md:col-span-1" className="no-spinner" />

                                            <div className="md:col-span-1 p-3 bg-gray-50 dark:bg-gray-900 rounded-lg border border-gray-100 dark:border-gray-800">
                                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Plot Area</p>
                                                <div className="text-sm font-bold text-blue-600 dark:text-blue-400">
                                                    {computedSqFt.toLocaleString()} sq ft
                                                </div>
                                            </div>
                                       </div>
                                   </div>
                               );
                           })}
                        </div>
                        <button type="button" onClick={addInventoryRow} className="mt-4 flex items-center gap-2 text-sm font-black text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300 transition-colors uppercase tracking-wider">
                            <PlusCircleIcon className="w-5 h-5"/> Add Another Entry
                        </button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-6 pt-4 border-t border-gray-200 dark:border-gray-700">
                        <Select id="registrationStatus" name="registrationStatus" label="Legal Registration Status" value={formData.registrationStatus} onChange={handleChange} required>
                            <option value="">Select status...</option>
                            <option value="LRD">LRD Registered</option>
                            <option value="PVLMD">PVLMD Licensed</option>
                            <option value="SMD">SMD Verified</option>
                            <option value="LVD">LVD Documented</option>
                        </Select>
                        <Input id="purchaseAgreementDate" name="purchaseAgreementDate" label="Date of Final Signing" type="date" value={formData.purchaseAgreementDate} onChange={handleChange} required />
                        <Input id="pricePerAcre" name="pricePerAcre" label="Cost Per Acre (GHC)" type="number" value={formData.pricePerAcre} onChange={handleChange} placeholder="0.00" className="no-spinner font-bold" />
                        <Input id="totalSizeAcres" name="totalSizeAcres" label="Computed Size (Acres)" type="text" value={formData.totalSizeAcres} readOnly containerClassName="bg-gray-50/50" className="font-mono text-gray-500" />
                        <Input id="totalPrice" name="totalPrice" label="Computed Total Price (GHC)" type="text" value={formatCurrency(formData.totalPrice)} readOnly containerClassName="md:col-span-2 bg-gray-50/50" className="font-black text-gray-700" />
                    </div>

                    {/* NEW PRICING REFERENCE FIELDS */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6 pt-6 border-t-2 border-dashed border-gray-200 dark:border-gray-700 bg-blue-50/20 dark:bg-blue-900/5 p-4 rounded-xl">
                        <Input 
                            id="plotsPerAcre" 
                            name="plotsPerAcre" 
                            label="Number of Plots Per Acre*" 
                            type="text" 
                            value={formData.plotsPerAcre} 
                            onChange={handleChange} 
                            error={plotsPerAcreError}
                            placeholder="e.g. 6"
                            className="font-bold text-lg text-blue-700 dark:text-blue-300"
                        />

                        <div className="relative">
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Price Per Plot (Calculated Cost)</label>
                            <div className={`flex items-center px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm h-[42px] transition-colors ${!formData.pricePerPlot ? 'bg-gray-100 opacity-60' : ''}`}>
                                <BanknotesIcon className="w-5 h-5 text-gray-400 mr-2" />
                                {formData.pricePerPlot ? (
                                    <span className="font-black text-lg text-gray-900 dark:text-white">
                                        GHC {formatCurrency(formData.pricePerPlot)}
                                    </span>
                                ) : (
                                    <span className="text-xs text-amber-600 dark:text-amber-400 italic">
                                        Enter plots per acre to calculate
                                    </span>
                                )}
                            </div>
                            {formData.pricePerPlot && (
                                <p className="text-[10px] text-gray-500 mt-1 italic">
                                    Logic: Cost Per Acre / Plots Per Acre
                                </p>
                            )}
                        </div>
                    </div>
                </Card>

                <Card title="Section 2: Official & Legal Documentation">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <Input id="familyName" name="familyName" label="Official Name of Granting Family" value={formData.familyName} onChange={handleChange} />
                        <Input id="nameOnSearch" name="nameOnSearch" label="Official Search Subject Name" value={formData.nameOnSearch} onChange={handleChange} />
                        <FileUploadField id="officialSearchDoc" label="Official Search Result (Scan)" file={formData.officialSearchDoc} onChange={handleFileChange} accept=".pdf,image/*" />
                        <FileUploadField id="sitePlanDoc" label="Certified Site Plan" file={formData.sitePlanDoc} onChange={handleFileChange} accept=".pdf,image/*" />
                    </div>
                </Card>

                <Card title="Section 3: Family Contacts & Negotiators">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        <Textarea id="leadNegotiators" name="leadNegotiators" label="Lead Negotiators / Facilitators" value={formData.leadNegotiators} onChange={handleChange} placeholder="Enter names of primary brokers..." containerClassName="lg:col-span-3"/>
                        <Input id="familyContactPerson" name="familyContactPerson" label="Family Liaison Person" value={formData.familyContactPerson} onChange={handleChange} />
                        <Input id="phone1" name="phone1" label="Primary Phone" type="tel" value={formData.phoneNumbers[0]} onChange={(e) => handlePhoneChange(0, e.target.value)} />
                        <Input id="phone2" name="phone2" label="Secondary Phone" type="tel" value={formData.phoneNumbers[1]} onChange={(e) => handlePhoneChange(1, e.target.value)} />
                        <Textarea id="additionalNotes" name="additionalNotes" label="Acquisition Remarks" value={formData.additionalNotes} onChange={handleChange} containerClassName="lg:col-span-3" />
                    </div>
                </Card>

                <Card title="Section 4: Disbursement Schedule">
                    <div className="bg-gray-50 dark:bg-gray-900 p-4 rounded-lg border border-gray-200 dark:border-gray-700 grid grid-cols-1 md:grid-cols-3 gap-4">
                         <Input id="paymentAmountPerMonth" name="paymentAmountPerMonth" label="Installment Amount (GHC)" type="number" value={formData.paymentAmountPerMonth} onChange={handleChange} className="no-spinner font-bold" />
                         <Input id="paymentPeriodMonths" name="paymentPeriodMonths" label="Term Length (Months)" type="number" value={formData.paymentPeriodMonths} onChange={handleChange} className="no-spinner" />
