import React, { useState } from 'react';
import { XIcon } from './icons/XIcon';
import { 
  HomeIcon, 
  UsersIcon, 
  Cog6ToothIcon, 
  ChevronDownIcon, 
  DocumentPlusIcon, 
  BriefcaseIcon, 
  UserGroupIcon, 
  CalendarDaysIcon, 
  BookOpenIcon, 
  MegaphoneIcon, 
  ArrowRightOnRectangleIcon, 
  QuestionMarkCircleIcon, 
  ShieldCheckIcon, 
  AcademicCapIcon, 
  FaimLogoIcon, 
  TagIcon, 
  HashtagIcon,
  EnvelopeIcon
} from './icons/DummyIcons';
import { PermissionSet, CompanySettings } from '../types';

interface SidebarProps {
  isMobileOpen: boolean;
  onMobileClose: () => void;
  isDesktopCollapsed: boolean;
  activePage: string;
  setActivePage: (page: string) => void;
  staffPermissions: { [key: string]: PermissionSet };
  companySettings: CompanySettings;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  isMobileOpen, 
  onMobileClose,
  isDesktopCollapsed,
  activePage,
  setActivePage,
  staffPermissions,
  companySettings,
}) => {
  const [openMenus, setOpenMenus] = useState<Record<string, boolean>>({
    'Client Management': true,
    'Team': true
  });

  const toggleMenu = (name: string) => {
    setOpenMenus(prev => ({ ...prev, [name]: !prev[name] }));
  };

  const handleNavClick = (pageName: string) => {
    setActivePage(pageName);
    onMobileClose();
  };

  const allNavItems = [
    { name: 'Dashboard', icon: <HomeIcon />, href: '#', moduleId: 'Dashboard' },
    {
      name: 'Client Management',
      icon: <UsersIcon />,
      moduleId: 'Clients',
      subItems: [
        { name: 'Clients', icon: <UserGroupIcon />, href: '#', moduleId: 'Clients' },
        { name: 'Account Management', icon: <DocumentPlusIcon />, href: '#', moduleId: 'Account Management' },
      ],
    },
    {
      name: 'Team',
      icon: <BriefcaseIcon />,
      moduleId: 'Team',
      subItems: [
        { name: 'Leads & Follow-Ups', icon: <UsersIcon />, href: '#', moduleId: 'Leads Management' },
        { name: 'Mailing', icon: <EnvelopeIcon />, href: '#', moduleId: 'Internal Mailing' },
        { name: 'Leave', icon: <CalendarDaysIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Events', icon: <BookOpenIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Announcements', icon: <MegaphoneIcon />, href: '#', moduleId: 'Administration' },
      ],
    },
    { name: 'Promotions', icon: <TagIcon />, href: '#', moduleId: 'Promotions' },
    { name: 'Administration', icon: <ShieldCheckIcon />, href: '#', moduleId: 'Administration'},
    { name: 'CEO Hub', icon: <AcademicCapIcon />, href: '#', moduleId: 'CEO Hub' },
    { name: 'Support', icon: <QuestionMarkCircleIcon />, href: '#', moduleId: 'Settings' },
    { name: 'Settings', icon: <Cog6ToothIcon />, href: '#', moduleId: 'Settings' },
  ];

  const visibleNavItems = allNavItems.filter(item => staffPermissions[item.moduleId]?.view).map(item => {
      if (item.subItems) {
          return {
              ...item,
              subItems: item.subItems.filter(subItem => staffPermissions[subItem.moduleId]?.view)
          };
      }
      return item;
  }).filter(item => !item.subItems || item.subItems.length > 0);

  const sidebarLogo = companySettings.appLogoDark || companySettings.appLogoLight || companySettings.logo;

  const sidebarContent = (
    <>
      <div className="flex flex-col items-center justify-center p-4 h-24 border-b border-gray-800 flex-shrink-0">
          {sidebarLogo ? (
            <img key={sidebarLogo} src={sidebarLogo} alt={`${companySettings.name} Logo`} className="w-12 h-12 object-contain" />
          ) : (
            <FaimLogoIcon className="w-10 h-10 text-white" />
          )}
          {!isDesktopCollapsed && (
            <h1 className="text-xl font-bold tracking-wider text-white mt-2">
              {companySettings.name.split(' ')[0]}<span className="text-blue-400">.</span>
            </h1>
          )}
        <button onClick={onMobileClose} className="md:hidden absolute top-5 right-4 text-gray-400 hover:text-white">
          <XIcon className="w-6 h-6" />
        </button>
      </div>
      <nav className="flex-grow p-2 overflow-y-auto">
        <ul>
          {visibleNavItems.map((item) => (
            <li key={item.name}>
              {item.subItems ? (
                <>
                  <button
                    onClick={() => toggleMenu(item.name)}
                    className={`flex items-center justify-between w-full gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                      activePage === item.name || item.subItems.some(sub => sub.name === activePage || (sub.name === 'Clients' && activePage === 'Client Details'))
                        ? 'text-white'
                        : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-6 h-6">{item.icon}</span>
                      {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                    </div>
                    {!isDesktopCollapsed && (
                      <ChevronDownIcon className={`w-5 h-5 transition-transform ${openMenus[item.name] ? 'rotate-180' : ''}`} />
                    )}
                  </button>
                  {(!isDesktopCollapsed && openMenus[item.name]) && (
                    <ul className="pl-6">
                      {item.subItems.map((subItem) => (
                        <li key={subItem.name}>
                          <a
                            href={subItem.href}
                            onClick={(e) => { e.preventDefault(); handleNavClick(subItem.name); }}
                            className={`flex items-center gap-3 pl-3 pr-4 py-2 my-1 rounded-md transition-colors duration-200 text-sm relative group ${
                              activePage === subItem.name || (subItem.name === 'Clients' && activePage === 'Client Details')
                                ? 'bg-blue-600 text-white shadow-lg'
                                : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                            }`}
                          >
                            <span className="w-6 h-6">{subItem.icon}</span>
                            <span className="font-medium">{subItem.name}</span>
                          </a>
                        </li>
                      ))}
                    </ul>
                  )}
                </>
              ) : (
                <a
                  href={item.href}
                  onClick={(e) => { e.preventDefault(); handleNavClick(item.name); }}
                  className={`flex items-center gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                    activePage === item.name
                      ? 'bg-blue-600 text-white shadow-lg'
                      : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                  }`}
                >
                  <span className="w-6 h-6">{item.icon}</span>
                  {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                </a>
              )}
            </li>
          ))}
        </ul>
      </nav>
    </>
  );

  return (
    <>
      <div
        className={`fixed inset-0 z-40 bg-black bg-opacity-50 transition-opacity md:hidden ${
          isMobileOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={onMobileClose}
      ></div>
      <aside
        className={`fixed inset-y-0 left-0 z-50 flex flex-col bg-gray-900 text-white w-64 transform transition-transform duration-300 ease-in-out md:hidden ${
          isMobileOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {sidebarContent}
      </aside>
      <aside className={`hidden md:flex flex-col bg-gray-900 text-white transition-all duration-300 ease-in-out ${isDesktopCollapsed ? 'w-20' : 'w-64'}`}>
        {sidebarContent}
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PurchaseSaleManagementPage from './pages/PurchaseSaleManagementPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';
import MappingsPage from './pages/MappingsPage';

// Team Module Pages
import LeadsManagementPage from './pages/LeadsManagementPage';
import MailingPage from './pages/team/MailingPage';
import LeavePage from './pages/team/LeavePage';
import EventsPage from './pages/team/EventsPage';
import AnnouncementsPage from './pages/team/AnnouncementsPage';

import { DataProvider, usePermissions } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { 
    useClients, useProperties, useInvoices, useStaff, useLeads, 
    usePromotions, useActivityLogs, useRoles, useAmendments, useCompanySettings 
} from './hooks/useAppData';

const queryClient = new QueryClient();

const AppContent: React.FC = () => {
    const { clients, saveClient, deleteClient } = useClients();
    const { properties, saveProperty } = useProperties();
    const { invoices, saveInvoice } = useInvoices();
    const { staff, updateStaff } = useStaff(); 
    const { leads, saveLead, deleteLead } = useLeads();
    const { promotions, savePromotion, deletePromotion } = usePromotions();
    const { activityLogs, addActivityLog } = useActivityLogs();
    const { roles, setRoles } = useRoles();
    const { amendments, setAmendmentList } = useAmendments();
    const { companySettings, setCompanySettings } = useCompanySettings();
    const { rolePermissions } = usePermissions();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    useEffect(() => {
        if (companySettings.favicon) {
            let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
            if (!link) {
                link = document.createElement('link');
                link.rel = 'icon';
                document.head.appendChild(link);
            }
            link.href = companySettings.favicon;
        }
    }, [companySettings.favicon]);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);
        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });
        if (Object.keys(userPermissions).length === 0) {
             userPermissions['Dashboard'] = { view: true, create: false, edit: false, delete: false, approve: false };
        }
        return userPermissions;
    }, [currentStaff, rolePermissions]);

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                    roles={roles}
                 />;

            // Team Sub-modules
            case 'Leads & Follow-Ups':
                return <LeadsManagementPage 
                    onSaveLead={saveLead}
                    onDeleteLead={deleteLead}
                    clients={clients}
                    onSaveClient={saveClient}
                    staffList={staff}
                    roles={roles}
                    properties={properties}
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]}
                    currentStaff={currentStaff}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Mailing':
                return <MailingPage />;
            case 'Leave':
                return <LeavePage />;
            case 'Events':
                return <EventsPage />;
            case 'Announcements':
                return <AnnouncementsPage />;

            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                    onUpdateStaff={updateStaff}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
                return <PropertiesPage properties={properties} currentStaff={currentStaff} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
             case 'New Land Acquisition':
                return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
             case 'Purchase & Sale Management':
                return <PurchaseSaleManagementPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} currentStaff={currentStaff} />;
             case 'Promotions':
                return <PromotionsPage 
                    promotions={promotions} 
                    onSavePromotion={savePromotion}
                    onDeletePromotion={deletePromotion}
                    properties={properties} 
                    showForm={true} 
                    onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} 
                />;
            case 'Administration':
                return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Human Resources':
                return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts':
                return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot':
                return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation':
                return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings':
                return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form':
                return (
                    <AmendmentFormPage 
                        client={pageContext} 
                        onBack={() => handleSetPage('Client Details', pageContext)} 
                        onSave={async (data, updatedClient) => { 
                            setAmendmentList(prev => [data, ...prev]); 
                            await saveClient(updatedClient);
                            handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`);
                            alert('Amendment processed and client record updated successfully!'); 
                            handleSetPage('Client Details', updatedClient);
                        }} 
                        currentStaff={currentStaff} 
                    />
                );
            case 'Analytics & Reports':
                return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports':
                return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity':
                return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Support':
                return <PlaceholderPage title={activePage} onBack={() => handleSetPage('Dashboard')} />;
            default:
                // Redirect to safe default page for any attempted access to removed routes
                return <Dashboard />;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
        </Layout>
    );
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <AuthProvider>
                    <DataProvider>
                        <AppContent />
                    </DataProvider>
                </AuthProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { 
    CalendarDaysIcon, 
    PlusCircleIcon, 
    MapPinIcon, 
    ClockIcon, 
    XMarkIcon,
    CheckCircleIcon,
    UserCircleIcon
} from '../../components/icons/DummyIcons';
import { useAuth } from '../../context/AuthContext';
import { useActivityLogs, useRoles } from '../../hooks/useAppData';

interface InternalEvent {
    id: string;
    title: string;
    dateTime: string;
    location: string;
    description: string;
    createdBy: string;
    rsvps: Record<string, 'Yes' | 'No'>;
}

const EventsPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    const [events, setEvents] = useState<InternalEvent[]>([
        {
            id: 'evt-1',
            title: 'Q4 Strategy Meeting',
            dateTime: '2024-12-01T10:00',
            location: 'Conference Room A',
            description: 'Discussing goals and budgets for the upcoming year.',
            createdBy: 'Araba CEO',
            rsvps: { '1': 'Yes' }
        }
    ]);

    const [isModalOpen, setModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const userRole = roles.find(r => r.id === currentStaff?.roleId)?.name;
    const canCreate = userRole === 'CEO' || userRole === 'Administrator';

    const { upcoming, past } = useMemo(() => {
        const now = new Date();
        const sorted = [...events].sort((a, b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime());
        return {
            upcoming: sorted.filter(e => new Date(e.dateTime) >= now),
            past: sorted.filter(e => new Date(e.dateTime) < now).reverse()
        };
    }, [events]);

    const handleCreateEvent = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSaving(true);
        const formData = new FormData(e.currentTarget);

        const newEvent: InternalEvent = {
            id: `EVT-${Date.now()}`,
            title: formData.get('title') as string,
            dateTime: formData.get('dateTime') as string,
            location: formData.get('location') as string,
            description: formData.get('description') as string,
            createdBy: currentStaff?.fullName || 'System',
            rsvps: {}
        };

        setEvents(prev => [...prev, newEvent]);
        addActivityLog('Create', `Created internal event: ${newEvent.title}`);
        setModalOpen(false);
        setIsSaving(false);
    };

    const handleRSVP = (eventId: string, status: 'Yes' | 'No') => {
        setEvents(prev => prev.map(e => {
            if (e.id === eventId) {
                return { ...e, rsvps: { ...e.rsvps, [currentStaff?.id || '']: status } };
            }
            return e;
        }));
    };

    const EventCard = ({ event, isPast }: { event: InternalEvent; isPast?: boolean }) => (
        <Card className={`overflow-hidden border-l-4 ${isPast ? 'border-l-gray-400 grayscale' : 'border-l-blue-600 shadow-md'}`}>
            <div className="flex flex-col md:flex-row justify-between gap-4">
                <div className="space-y-3">
                    <h3 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">{event.title}</h3>
                    <div className="flex flex-wrap gap-4 text-xs font-bold text-gray-500 uppercase tracking-widest">
                        <span className="flex items-center gap-1.5"><ClockIcon className="w-4 h-4 text-blue-500" /> {new Date(event.dateTime).toLocaleString()}</span>
                        <span className="flex items-center gap-1.5"><MapPinIcon className="w-4 h-4 text-blue-500" /> {event.location}</span>
                        <span className="flex items-center gap-1.5"><UserCircleIcon className="w-4 h-4 text-blue-500" /> Host: {event.createdBy}</span>
                    </div>
                    <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed">{event.description}</p>
                </div>
                {!isPast && (
                    <div className="flex flex-col items-center justify-center gap-2 bg-gray-50 dark:bg-gray-900/50 p-4 rounded-xl border border-gray-100 dark:border-gray-800 min-w-[120px]">
                        <p className="text-[10px] font-black text-gray-400 uppercase mb-2">Going?</p>
                        <div className="flex gap-2">
                            <button 
                                onClick={() => handleRSVP(event.id, 'Yes')}
                                className={`p-2 rounded-lg transition-all ${event.rsvps[currentStaff?.id || ''] === 'Yes' ? 'bg-green-600 text-white shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-400 border border-gray-200 hover:border-green-500'}`}
                            >
                                <CheckCircleIcon className="w-6 h-6" />
                            </button>
                            <button 
                                onClick={() => handleRSVP(event.id, 'No')}
                                className={`p-2 rounded-lg transition-all ${event.rsvps[currentStaff?.id || ''] === 'No' ? 'bg-red-600 text-white shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-400 border border-gray-200 hover:border-red-500'}`}
                            >
                                <XMarkIcon className="w-6 h-6" />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </Card>
    );

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Company Events</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Calendar coordination and team gatherings.</p>
                </div>
                {canCreate && (
                    <Button onClick={() => setModalOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                        Create Event
                    </Button>
                )}
            </div>

            <div className="space-y-8">
                <section>
                    <h2 className="text-xs font-black text-blue-600 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <CalendarDaysIcon className="w-4 h-4" /> Upcoming Events
                    </h2>
                    {upcoming.length === 0 ? (
                        <div className="py-20 text-center border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-3xl opacity-40">
                            <CalendarDaysIcon className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                            <p className="text-lg font-bold text-gray-400">No upcoming events scheduled</p>
                        </div>
                    ) : (
                        <div className="grid gap-6">{upcoming.map(e => <EventCard key={e.id} event={e} />)}</div>
                    )}
                </section>

                {past.length > 0 && (
                    <section>
                        <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Past Events</h2>
                        <div className="grid gap-4 opacity-70">{past.map(e => <EventCard key={e.id} event={e} isPast />)}</div>
                    </section>
                )}
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
                    <Card className="w-full max-w-xl p-0 overflow-hidden shadow-2xl border border-blue-500/30">
                        <form onSubmit={handleCreateEvent}>
                            <div className="p-5 border-b border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">New Company Event</h3>
                                <button type="button" onClick={() => setModalOpen(false)} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                            </div>
                            <div className="p-6 space-y-4">
                                <Input label="Event Title*" name="title" required placeholder="e.g. End of Year Awards" />
                                <div className="grid grid-cols-2 gap-4">
                                    <Input label="Date & Time*" name="dateTime" type="datetime-local" required />
                                    <Input label="Location" name="location" placeholder="e.g. Accra Office Lounge" />
                                </div>
                                <Textarea label="Event Description" name="description" rows={4} placeholder="What should attendees know?" />
                            </div>
                            <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800 flex justify-end gap-3">
                                <Button type="button" variant="secondary" onClick={() => setModalOpen(false)}>Cancel</Button>
                                <Button type="submit" isLoading={isSaving}>Publish Event</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

export default EventsPage;

import React, { useState, useMemo } from 'react';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { 
    MegaphoneIcon, 
    PlusCircleIcon, 
    ClockIcon, 
    UserCircleIcon,
    XMarkIcon,
    PaperClipIcon,
    ArrowDownTrayIcon
} from '../../components/icons/DummyIcons';
import { useAuth } from '../../context/AuthContext';
import { useActivityLogs, useRoles } from '../../hooks/useAppData';
import { uploadFile } from '../../services/storageService';

interface Announcement {
    id: string;
    title: string;
    body: string;
    author: string;
    date: string;
    attachmentUrl?: string;
    readBy: string[];
}

const AnnouncementsPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    const [announcements, setAnnouncements] = useState<Announcement[]>([
        {
            id: 'ann-1',
            title: 'New Client Referral Bonus Program',
            body: 'Effective immediately, staff members are entitled to a 5% bonus on all successful land sale referrals. Documentation is attached.',
            author: 'Araba CEO',
            date: new Date(Date.now() - 86400000).toISOString(),
            attachmentUrl: '#',
            readBy: []
        }
    ]);

    const [isModalOpen, setModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [pendingFile, setPendingFile] = useState<File | null>(null);

    const userRole = roles.find(r => r.id === currentStaff?.roleId)?.name;
    const canPost = userRole === 'CEO' || userRole === 'Administrator';

    const sortedAnnouncements = useMemo(() => 
        [...announcements].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    , [announcements]);

    const handleMarkAsRead = (id: string) => {
        if (!currentStaff) return;
        setAnnouncements(prev => prev.map(a => {
            if (a.id === id && !a.readBy.includes(currentStaff.id)) {
                return { ...a, readBy: [...a.readBy, currentStaff.id] };
            }
            return a;
        }));
    };

    const handleCreateAnnouncement = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSaving(true);
        const formData = new FormData(e.currentTarget);

        try {
            let fileUrl = '';
            if (pendingFile) {
                fileUrl = await uploadFile(pendingFile, `announcements/${Date.now()}_${pendingFile.name}`);
            }

            const newAnn: Announcement = {
                id: `ANN-${Date.now()}`,
                title: formData.get('title') as string,
                body: formData.get('body') as string,
                author: currentStaff?.fullName || 'Management',
                date: new Date().toISOString(),
                attachmentUrl: fileUrl,
                readBy: [currentStaff?.id || '']
            };

            setAnnouncements(prev => [newAnn, ...prev]);
            addActivityLog('Create', `Posted announcement: ${newAnn.title}`);
            setModalOpen(false);
            setPendingFile(null);
        } catch (error) {
            alert('Failed to post announcement.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Internal Announcements</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Official company notices and team updates.</p>
                </div>
                {canPost && (
                    <Button onClick={() => setModalOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                        Post Announcement
                    </Button>
                )}
            </div>

            <div className="space-y-6">
                {sortedAnnouncements.length === 0 ? (
                    <div className="py-32 text-center bg-white dark:bg-gray-800 rounded-3xl border border-gray-200 dark:border-gray-700 opacity-40">
                        <MegaphoneIcon className="w-20 h-20 mx-auto mb-6 text-gray-300" />
                        <p className="text-xl font-bold text-gray-400">No active announcements</p>
                    </div>
                ) : (
                    sortedAnnouncements.map(ann => {
                        const isUnread = !ann.readBy.includes(currentStaff?.id || '');
                        return (
                            <Card 
                                key={ann.id} 
                                onMouseEnter={() => isUnread && handleMarkAsRead(ann.id)}
                                className={`transition-all ${isUnread ? 'ring-2 ring-blue-600/50 shadow-lg' : ''}`}
                            >
                                <div className="flex justify-between items-start mb-4">
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-2">
                                            {isUnread && <div className="w-2.5 h-2.5 rounded-full bg-blue-600 animate-pulse" />}
                                            <h3 className="text-xl font-black text-gray-900 dark:text-white leading-tight uppercase tracking-tighter">{ann.title}</h3>
                                        </div>
                                        <div className="flex items-center gap-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                            <span className="flex items-center gap-1"><UserCircleIcon className="w-3 h-3 text-blue-500" /> {ann.author}</span>
                                            <span className="flex items-center gap-1"><ClockIcon className="w-3 h-3 text-blue-500" /> {new Date(ann.date).toLocaleString()}</span>
                                        </div>
                                    </div>
                                    <Badge variant={isUnread ? 'info' : 'neutral'}>{isUnread ? 'NEW' : 'READ'}</Badge>
                                </div>
                                <div className="prose prose-sm max-w-none dark:prose-invert text-gray-700 dark:text-gray-300 whitespace-pre-wrap mb-6 leading-relaxed">
                                    {ann.body}
                                </div>
                                {ann.attachmentUrl && (
                                    <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <a 
                                            href={ann.attachmentUrl} 
                                            className="inline-flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-lg text-xs font-bold hover:bg-blue-100 transition-colors"
                                            target="_blank"
                                            rel="noopener noreferrer"
                                        >
                                            <PaperClipIcon className="w-4 h-4" /> View Attachment <ArrowDownTrayIcon className="w-3 h-3" />
                                        </a>
                                    </div>
                                )}
                            </Card>
                        );
                    })
                )}
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
                    <Card className="w-full max-w-2xl p-0 overflow-hidden shadow-2xl border border-indigo-500/30">
                        <form onSubmit={handleCreateAnnouncement}>
                            <div className="p-5 border-b border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">New Company Notice</h3>
                                <button type="button" onClick={() => setModalOpen(false)} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                            </div>
                            <div className="p-6 space-y-4">
                                <Input label="Announcement Title*" name="title" required placeholder="e.g. Policy Update regarding Plot Allocations" />
                                <Textarea label="Message Body*" name="body" required rows={8} placeholder="Type your announcement content here..." />
                                <div>
                                    <label className="block text-xs font-black text-gray-400 uppercase mb-2">Optional Attachment</label>
                                    <label className="flex items-center gap-3 p-3 bg-white dark:bg-gray-800 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-xl cursor-pointer hover:border-indigo-400 transition-colors">
                                        <PaperClipIcon className="w-6 h-6 text-gray-400" />
                                        <span className="text-sm font-bold text-gray-500">{pendingFile ? pendingFile.name : 'Select file (PDF/IMG)'}</span>
                                        <input type="file" className="sr-only" onChange={e => setPendingFile(e.target.files?.[0] || null)} />
                                    </label>
                                </div>
                            </div>
                            <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800 flex justify-end gap-3">
                                <Button type="button" variant="secondary" onClick={() => setModalOpen(false)}>Cancel</Button>
                                <Button type="submit" isLoading={isSaving} icon={<MegaphoneIcon className="w-5 h-5" />}>Post to Board</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

export default AnnouncementsPage;

import React, { useState, useMemo } from 'react';
import { XIcon } from './icons/XIcon';
import { 
  HomeIcon, 
  UsersIcon, 
  Cog6ToothIcon, 
  ChevronDownIcon, 
  DocumentPlusIcon, 
  BriefcaseIcon, 
  UserGroupIcon, 
  CalendarDaysIcon, 
  BookOpenIcon, 
  MegaphoneIcon, 
  ArrowRightOnRectangleIcon, 
  QuestionMarkCircleIcon, 
  ShieldCheckIcon, 
  AcademicCapIcon, 
  FaimLogoIcon, 
  TagIcon, 
  EnvelopeIcon
} from './icons/DummyIcons';
import { PermissionSet, CompanySettings } from '../types';

interface SidebarProps {
  isMobileOpen: boolean;
  onMobileClose: () => void;
  isDesktopCollapsed: boolean;
  activePage: string;
  setActivePage: (page: string) => void;
  staffPermissions: { [key: string]: PermissionSet };
  companySettings: CompanySettings;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  isMobileOpen, 
  onMobileClose,
  isDesktopCollapsed,
  activePage,
  setActivePage,
  staffPermissions,
  companySettings,
}) => {
  const [openMenus, setOpenMenus] = useState<Record<string, boolean>>({
    'Client Management': true,
    'Team': true
  });

  // Mocking unread count - in production this would come from a context/hook
  const unreadMails = 1; 

  const toggleMenu = (name: string) => {
    setOpenMenus(prev => ({ ...prev, [name]: !prev[name] }));
  };

  const handleNavClick = (pageName: string) => {
    setActivePage(pageName);
    onMobileClose();
  };

  const allNavItems = [
    { name: 'Dashboard', icon: <HomeIcon />, href: '#', moduleId: 'Dashboard' },
    {
      name: 'Client Management',
      icon: <UsersIcon />,
      moduleId: 'Clients',
      subItems: [
        { name: 'Clients', icon: <UserGroupIcon />, href: '#', moduleId: 'Clients' },
        { name: 'Account Management', icon: <DocumentPlusIcon />, href: '#', moduleId: 'Account Management' },
      ],
    },
    {
      name: 'Team',
      icon: <BriefcaseIcon />,
      moduleId: 'Team',
      subItems: [
        { name: 'Leads & Follow-Ups', icon: <UsersIcon />, href: '#', moduleId: 'Leads Management' },
        { name: 'Mailing', icon: <EnvelopeIcon />, href: '#', moduleId: 'Internal Mailing', badge: unreadMails },
        { name: 'Leave', icon: <CalendarDaysIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Events', icon: <BookOpenIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Announcements', icon: <MegaphoneIcon />, href: '#', moduleId: 'Administration' },
      ],
    },
    { name: 'Promotions', icon: <TagIcon />, href: '#', moduleId: 'Promotions' },
    { name: 'Administration', icon: <ShieldCheckIcon />, href: '#', moduleId: 'Administration'},
    { name: 'CEO Hub', icon: <AcademicCapIcon />, href: '#', moduleId: 'CEO Hub' },
    { name: 'Support', icon: <QuestionMarkCircleIcon />, href: '#', moduleId: 'Settings' },
    { name: 'Settings', icon: <Cog6ToothIcon />, href: '#', moduleId: 'Settings' },
  ];

  const visibleNavItems = allNavItems.filter(item => staffPermissions[item.moduleId]?.view).map(item => {
      if (item.subItems) {
          return {
              ...item,
              subItems: item.subItems.filter(subItem => staffPermissions[subItem.moduleId]?.view)
          };
      }
      return item;
  }).filter(item => !item.subItems || item.subItems.length > 0);

  const sidebarLogo = companySettings.appLogoDark || companySettings.appLogoLight || companySettings.logo;

  const sidebarContent = (
    <>
      <div className="flex flex-col items-center justify-center p-4 h-24 border-b border-gray-800 flex-shrink-0">
          {sidebarLogo ? (
            <img key={sidebarLogo} src={sidebarLogo} alt={`${companySettings.name} Logo`} className="w-12 h-12 object-contain" />
          ) : (
            <FaimLogoIcon className="w-10 h-10 text-white" />
          )}
          {!isDesktopCollapsed && (
            <h1 className="text-xl font-bold tracking-wider text-white mt-2">
              {companySettings.name.split(' ')[0]}<span className="text-blue-400">.</span>
            </h1>
          )}
        <button onClick={onMobileClose} className="md:hidden absolute top-5 right-4 text-gray-400 hover:text-white">
          <XIcon className="w-6 h-6" />
        </button>
      </div>
      <nav className="flex-grow p-2 overflow-y-auto">
        <ul>
          {visibleNavItems.map((item) => (
            <li key={item.name}>
              {item.subItems ? (
                <>
                  <button
                    onClick={() => toggleMenu(item.name)}
                    className={`flex items-center justify-between w-full gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                      activePage === item.name || item.subItems.some(sub => sub.name === activePage || (sub.name === 'Clients' && activePage === 'Client Details'))
                        ? 'text-white'
                        : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-6 h-6">{item.icon}</span>
                      {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                    </div>
                    {!isDesktopCollapsed && (
                      <ChevronDownIcon className={`w-5 h-5 transition-transform ${openMenus[item.name] ? 'rotate-180' : ''}`} />
                    )}
                  </button>
                  {(!isDesktopCollapsed && openMenus[item.name]) && (
                    <ul className="pl-6">
                      {item.subItems.map((subItem) => (
                        <li key={subItem.name}>
                          <a
                            href={subItem.href}
                            onClick={(e) => { e.preventDefault(); handleNavClick(subItem.name); }}
                            className={`flex items-center justify-between pl-3 pr-4 py-2 my-1 rounded-md transition-colors duration-200 text-sm relative group ${
                              activePage === subItem.name || (subItem.name === 'Clients' && activePage === 'Client Details')
                                ? 'bg-blue-600 text-white shadow-lg'
                                : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                            }`}
                          >
                            <div className="flex items-center gap-3">
                              <span className="w-6 h-6">{subItem.icon}</span>
                              <span className="font-medium">{subItem.name}</span>
                            </div>
                            {subItem.badge !== undefined && subItem.badge > 0 && (
                                <span className="bg-red-500 text-white text-[10px] font-black px-1.5 py-0.5 rounded-full ring-2 ring-gray-900 group-hover:ring-gray-800 transition-all">
                                    {subItem.badge}
                                </span>
                            )}
                          </a>
                        </li>
                      ))}
                    </ul>
                  )}
                </>
              ) : (
                <a
                  href={item.href}
                  onClick={(e) => { e.preventDefault(); handleNavClick(item.name); }}
                  className={`flex items-center gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                    activePage === item.name
                      ? 'bg-blue-600 text-white shadow-lg'
                      : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                  }`}
                >
                  <span className="w-6 h-6">{item.icon}</span>
                  {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                </a>
              )}
            </li>
          ))}
        </ul>
      </nav>
    </>
  );

  return (
    <>
      <div
        className={`fixed inset-0 z-40 bg-black bg-opacity-50 transition-opacity md:hidden ${
          isMobileOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={onMobileClose}
      ></div>
      <aside
        className={`fixed inset-y-0 left-0 z-50 flex flex-col bg-gray-900 text-white w-64 transform transition-transform duration-300 ease-in-out md:hidden ${
          isMobileOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {sidebarContent}
      </aside>
      <aside className={`hidden md:flex flex-col bg-gray-900 text-white transition-all duration-300 ease-in-out ${isDesktopCollapsed ? 'w-20' : 'w-64'}`}>
        {sidebarContent}
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState, useMemo } from 'react';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { 
    CalendarDaysIcon, 
    PlusCircleIcon, 
    MapPinIcon, 
    ClockIcon, 
    XMarkIcon,
    CheckCircleIcon,
    UserCircleIcon
} from '../../components/icons/DummyIcons';
import { useAuth } from '../../context/AuthContext';
import { useActivityLogs, useRoles } from '../../hooks/useAppData';

interface InternalEvent {
    id: string;
    title: string;
    dateTime: string;
    location: string;
    description: string;
    createdBy: string;
    rsvps: Record<string, 'Yes' | 'No'>;
}

const EventsPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    const [events, setEvents] = useState<InternalEvent[]>([
        {
            id: 'evt-1',
            title: 'Q4 Strategy Meeting',
            dateTime: '2024-12-01T10:00',
            location: 'Conference Room A',
            description: 'Discussing goals and budgets for the upcoming year.',
            createdBy: 'Araba CEO',
            rsvps: { '1': 'Yes' }
        }
    ]);

    const [isModalOpen, setModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const userRole = roles.find(r => r.id === currentStaff?.roleId)?.name;
    const canCreate = userRole === 'CEO' || userRole === 'Administrator';

    const { upcoming, past } = useMemo(() => {
        const now = new Date();
        const sorted = [...events].sort((a, b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime());
        return {
            upcoming: sorted.filter(e => new Date(e.dateTime) >= now),
            past: sorted.filter(e => new Date(e.dateTime) < now).reverse()
        };
    }, [events]);

    const handleCreateEvent = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSaving(true);
        const formData = new FormData(e.currentTarget);

        const newEvent: InternalEvent = {
            id: `EVT-${Date.now()}`,
            title: formData.get('title') as string,
            dateTime: formData.get('dateTime') as string,
            location: formData.get('location') as string,
            description: formData.get('description') as string,
            createdBy: currentStaff?.fullName || 'System',
            rsvps: {}
        };

        setEvents(prev => [...prev, newEvent]);
        addActivityLog('Create', `Created internal event: ${newEvent.title}`);
        setModalOpen(false);
        setIsSaving(false);
    };

    const handleRSVP = (eventId: string, status: 'Yes' | 'No') => {
        setEvents(prev => prev.map(e => {
            if (e.id === eventId) {
                return { ...e, rsvps: { ...e.rsvps, [currentStaff?.id || '']: status } };
            }
            return e;
        }));
    };

    // FIX: Typed as React.FC to ensure key is handled correctly as a reserved React prop
    const EventCard: React.FC<{ event: InternalEvent; isPast?: boolean }> = ({ event, isPast }) => (
        <Card className={`overflow-hidden border-l-4 ${isPast ? 'border-l-gray-400 grayscale' : 'border-l-blue-600 shadow-md'}`}>
            <div className="flex flex-col md:flex-row justify-between gap-4">
                <div className="space-y-3">
                    <h3 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">{event.title}</h3>
                    <div className="flex flex-wrap gap-4 text-xs font-bold text-gray-500 uppercase tracking-widest">
                        <span className="flex items-center gap-1.5"><ClockIcon className="w-4 h-4 text-blue-500" /> {new Date(event.dateTime).toLocaleString()}</span>
                        <span className="flex items-center gap-1.5"><MapPinIcon className="w-4 h-4 text-blue-500" /> {event.location}</span>
                        <span className="flex items-center gap-1.5"><UserCircleIcon className="w-4 h-4 text-blue-500" /> Host: {event.createdBy}</span>
                    </div>
                    <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed">{event.description}</p>
                </div>
                {!isPast && (
                    <div className="flex flex-col items-center justify-center gap-2 bg-gray-50 dark:bg-gray-900/50 p-4 rounded-xl border border-gray-100 dark:border-gray-800 min-w-[120px]">
                        <p className="text-[10px] font-black text-gray-400 uppercase mb-2">Going?</p>
                        <div className="flex gap-2">
                            <button 
                                onClick={() => handleRSVP(event.id, 'Yes')}
                                className={`p-2 rounded-lg transition-all ${event.rsvps[currentStaff?.id || ''] === 'Yes' ? 'bg-green-600 text-white shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-400 border border-gray-200 hover:border-green-500'}`}
                            >
                                <CheckCircleIcon className="w-6 h-6" />
                            </button>
                            <button 
                                onClick={() => handleRSVP(event.id, 'No')}
                                className={`p-2 rounded-lg transition-all ${event.rsvps[currentStaff?.id || ''] === 'No' ? 'bg-red-600 text-white shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-400 border border-gray-200 hover:border-red-500'}`}
                            >
                                <XMarkIcon className="w-6 h-6" />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </Card>
    );

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Company Events</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Calendar coordination and team gatherings.</p>
                </div>
                {canCreate && (
                    <Button onClick={() => setModalOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                        Create Event
                    </Button>
                )}
            </div>

            <div className="space-y-8">
                <section>
                    <h2 className="text-xs font-black text-blue-600 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <CalendarDaysIcon className="w-4 h-4" /> Upcoming Events
                    </h2>
                    {upcoming.length === 0 ? (
                        <div className="py-20 text-center border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-3xl opacity-40">
                            <CalendarDaysIcon className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                            <p className="text-lg font-bold text-gray-400">No upcoming events scheduled</p>
                        </div>
                    ) : (
                        <div className="grid gap-6">{upcoming.map(e => <EventCard key={e.id} event={e} />)}</div>
                    )}
                </section>

                {past.length > 0 && (
                    <section>
                        <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Past Events</h2>
                        <div className="grid gap-4 opacity-70">{past.map(e => <EventCard key={e.id} event={e} isPast />)}</div>
                    </section>
                )}
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
                    <Card className="w-full max-w-xl p-0 overflow-hidden shadow-2xl border border-blue-500/30">
                        <form onSubmit={handleCreateEvent}>
                            <div className="p-5 border-b border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">New Company Event</h3>
                                <button type="button" onClick={() => setModalOpen(false)} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                            </div>
