import React, { useState, useMemo, useEffect } from 'react';
import { Staff, Role } from '../../types';
import { 
    MagnifyingGlassIcon, 
    PlusCircleIcon, 
    TrashIcon, 
    InboxArrowDownIcon, 
    PaperAirplaneIcon, 
    UserCircleIcon,
    EnvelopeIcon,
    PaperClipIcon,
    ArrowDownTrayIcon,
    XMarkIcon,
    ArrowLeftIcon,
    DocumentDuplicateIcon,
    ClockIcon,
    ChartBarIcon
} from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { useStaff, useActivityLogs, useRoles } from '../../hooks/useAppData';
import { useAuth } from '../../context/AuthContext';
import { uploadFile } from '../../services/storageService';

type MailFolder = 'dashboard' | 'inbox' | 'sent' | 'drafts' | 'trash';

interface InternalMail {
    id: string;
    senderId: string;
    senderName: string;
    recipientIds: string[];
    groupIds: string[]; // e.g. "ALL_STAFF", "ROLE_CEO"
    subject: string;
    body: string;
    attachments: { name: string; url: string; size: number }[];
    timestamp: string;
    readBy: string[];
    isDraft?: boolean;
    isDeleted?: boolean;
}

const MailingPage: React.FC = () => {
    const { staff } = useStaff();
    const { roles } = useRoles();
    const { currentStaff } = useAuth();
    const { addActivityLog } = useActivityLogs();

    // UI State
    const [activeFolder, setActiveFolder] = useState<MailFolder>('dashboard');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedMail, setSelectedMail] = useState<InternalMail | null>(null);
    const [isComposeOpen, setComposeOpen] = useState(false);
    const [isMobileListOpen, setMobileListOpen] = useState(true);

    // Mock Database for Mails
    const [mails, setMails] = useState<InternalMail[]>([
        {
            id: 'm-101',
            senderId: '1',
            senderName: 'Araba CEO',
            recipientIds: [currentStaff?.id || ''],
            groupIds: [],
            subject: 'Welcome to the New Internal Mailing System',
            body: 'Hello Team,\n\nWe have successfully deployed our standalone internal communication module. Use this for all project-related updates and document sharing.\n\nRegards,\nManagement',
            attachments: [],
            timestamp: new Date(Date.now() - 86400000).toISOString(),
            readBy: []
        }
    ]);

    // Computed Lists
    const folderMails = useMemo(() => {
        return mails.filter(m => {
            const isRelated = m.senderId === currentStaff?.id || m.recipientIds.includes(currentStaff?.id || '');
            if (!isRelated) return false;

            if (activeFolder === 'trash') return m.isDeleted;
            if (m.isDeleted) return false;

            switch (activeFolder) {
                case 'inbox': return m.recipientIds.includes(currentStaff?.id || '') && !m.isDraft;
                case 'sent': return m.senderId === currentStaff?.id && !m.isDraft;
                case 'drafts': return m.isDraft;
                default: return true;
            }
        }).filter(m => {
            const search = searchTerm.toLowerCase();
            return m.subject.toLowerCase().includes(search) || m.senderName.toLowerCase().includes(search);
        }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [mails, activeFolder, currentStaff, searchTerm]);

    const stats = useMemo(() => ({
        unread: mails.filter(m => m.recipientIds.includes(currentStaff?.id || '') && !m.readBy.includes(currentStaff?.id || '') && !m.isDeleted && !m.isDraft).length,
        sent: mails.filter(m => m.senderId === currentStaff?.id && !m.isDraft && !m.isDeleted).length,
        drafts: mails.filter(m => m.senderId === currentStaff?.id && m.isDraft && !m.isDeleted).length,
        trash: mails.filter(m => m.isDeleted && (m.senderId === currentStaff?.id || m.recipientIds.includes(currentStaff?.id || ''))).length
    }), [mails, currentStaff]);

    // Actions
    const handleOpenMail = (mail: InternalMail) => {
        setSelectedMail(mail);
        setMobileListOpen(false);
        if (!mail.readBy.includes(currentStaff?.id || '')) {
            setMails(prev => prev.map(m => m.id === mail.id ? { ...m, readBy: [...m.readBy, currentStaff?.id || ''] } : m));
        }
    };

    const handleSend = (mailData: any) => {
        const newMail: InternalMail = {
            id: `MAIL-${Date.now()}`,
            senderId: currentStaff?.id || '0',
            senderName: currentStaff?.fullName || 'System',
            ...mailData,
            timestamp: new Date().toISOString(),
            readBy: [currentStaff?.id || ''],
            isDraft: false,
            isDeleted: false
        };
        setMails(prev => [newMail, ...prev]);
        addActivityLog('Create', `Sent internal mail: ${newMail.subject}`);
        setComposeOpen(false);
        setActiveFolder('sent');
    };

    const handleAction = (id: string, action: 'delete' | 'restore' | 'permanent') => {
        if (action === 'delete') {
            setMails(prev => prev.map(m => m.id === id ? { ...m, isDeleted: true } : m));
            if (selectedMail?.id === id) setSelectedMail(null);
        } else if (action === 'restore') {
            setMails(prev => prev.map(m => m.id === id ? { ...m, isDeleted: false } : m));
            if (selectedMail?.id === id) setSelectedMail(null);
        } else if (action === 'permanent') {
            if (confirm('Delete permanently?')) setMails(prev => prev.filter(m => m.id !== id));
            if (selectedMail?.id === id) setSelectedMail(null);
        }
    };

    return (
        <div className="flex flex-col h-[calc(100vh-120px)] space-y-4">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Internal Mailing</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Secure communication within the organization.</p>
                </div>
                <Button onClick={() => setComposeOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                    Compose Mail
                </Button>
            </div>

            <div className="flex-grow flex bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden">
                {/* Sidebar Navigation */}
                <div className="w-16 md:w-64 border-r border-gray-200 dark:border-gray-700 flex flex-col bg-gray-50 dark:bg-gray-900/50 shrink-0">
                    <nav className="p-3 space-y-1">
                        {[
                            { id: 'dashboard', label: 'Dashboard', icon: <ChartBarIcon className="w-5 h-5" /> },
                            { id: 'inbox', label: 'Inbox', icon: <InboxArrowDownIcon className="w-5 h-5" />, badge: stats.unread },
                            { id: 'sent', label: 'Sent', icon: <PaperAirplaneIcon className="w-5 h-5 -rotate-45" /> },
                            { id: 'drafts', label: 'Drafts', icon: <DocumentDuplicateIcon className="w-5 h-5" />, badge: stats.drafts },
                            { id: 'trash', label: 'Trash', icon: <TrashIcon className="w-5 h-5" /> }
                        ].map(item => (
                            <button 
                                key={item.id}
                                onClick={() => { setActiveFolder(item.id as MailFolder); setSelectedMail(null); setMobileListOpen(true); }}
                                className={`w-full flex items-center justify-between p-3 rounded-lg font-bold transition-all ${activeFolder === item.id ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-800'}`}
                            >
                                <div className="flex items-center gap-3">
                                    {item.icon}
                                    <span className="hidden md:block text-sm uppercase tracking-wider">{item.label}</span>
                                </div>
                                {item.badge ? (
                                    <span className={`hidden md:block px-2 py-0.5 text-[10px] rounded-full ${activeFolder === item.id ? 'bg-white text-blue-600' : 'bg-blue-600 text-white'}`}>
                                        {item.badge}
                                    </span>
                                ) : null}
                            </button>
                        ))}
                    </nav>
                </div>

                {/* Dashboard View */}
                {activeFolder === 'dashboard' ? (
                    <div className="flex-grow p-8 overflow-y-auto scrollbar-thin space-y-8">
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                            <Card className="p-4 border-l-4 border-blue-600">
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Unread Mails</p>
                                <p className="text-3xl font-black text-blue-600">{stats.unread}</p>
                            </Card>
                            <Card className="p-4 border-l-4 border-green-600">
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Sent</p>
                                <p className="text-3xl font-black text-green-600">{stats.sent}</p>
                            </Card>
                            <Card className="p-4 border-l-4 border-amber-600">
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Pending Drafts</p>
                                <p className="text-3xl font-black text-amber-600">{stats.drafts}</p>
                            </Card>
                            <Card className="p-4 border-l-4 border-red-600">
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trash Size</p>
                                <p className="text-3xl font-black text-red-600">{stats.trash}</p>
                            </Card>
                        </div>

                        <div>
                            <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Recent Correspondence</h3>
                            <div className="space-y-3">
                                {mails.slice(0, 5).map(m => (
                                    <div key={m.id} onClick={() => { setActiveFolder('inbox'); handleOpenMail(m); }} className="flex items-center gap-4 p-4 bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl cursor-pointer hover:border-blue-300 transition-all">
                                        <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold">{m.senderName.substring(0,2)}</div>
                                        <div className="flex-grow">
                                            <p className="text-sm font-bold text-gray-900 dark:text-white">{m.subject}</p>
                                            <p className="text-xs text-gray-500">From: {m.senderName} • {new Date(m.timestamp).toLocaleDateString()}</p>
                                        </div>
                                        {!m.readBy.includes(currentStaff?.id || '') && <div className="w-2 h-2 rounded-full bg-blue-600"></div>}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : (
                    <>
                        {/* List Pane */}
                        <div className={`w-full md:w-96 flex flex-col border-r border-gray-200 dark:border-gray-700 ${!isMobileListOpen ? 'hidden md:flex' : 'flex'}`}>
                            <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                                <div className="relative">
                                    <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input 
                                        type="text"
                                        placeholder="Search in folder..."
                                        value={searchTerm}
                                        onChange={(e) => setSearchTerm(e.target.value)}
                                        className="w-full pl-9 pr-4 py-2 bg-gray-100 dark:bg-gray-900 border-none rounded-lg text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white"
                                    />
                                </div>
                            </div>
                            <div className="flex-grow overflow-y-auto scrollbar-thin">
                                {folderMails.length === 0 ? (
                                    <div className="p-10 text-center text-gray-400 italic text-sm">Empty folder.</div>
                                ) : (
                                    folderMails.map(mail => {
                                        const isUnread = activeFolder === 'inbox' && !mail.readBy.includes(currentStaff?.id || '');
                                        return (
                                            <div 
                                                key={mail.id}
                                                onClick={() => handleOpenMail(mail)}
                                                className={`p-4 border-b border-gray-100 dark:border-gray-700/50 cursor-pointer transition-all hover:bg-gray-50 dark:hover:bg-gray-700/30 ${selectedMail?.id === mail.id ? 'bg-blue-50 dark:bg-blue-900/10 border-l-4 border-l-blue-600' : ''}`}
                                            >
                                                <div className="flex justify-between items-start mb-1">
                                                    <span className={`text-[10px] font-black uppercase tracking-widest ${isUnread ? 'text-blue-600' : 'text-gray-400'}`}>
                                                        {activeFolder === 'sent' ? `To: ${mail.recipientIds.length} Recipient(s)` : mail.senderName}
                                                    </span>
                                                    <span className="text-[10px] text-gray-400 font-bold">{new Date(mail.timestamp).toLocaleDateString()}</span>
                                                </div>
                                                <div className={`text-sm truncate ${isUnread ? 'font-black text-gray-900 dark:text-white' : 'text-gray-700 dark:text-gray-300'}`}>
                                                    {mail.subject}
                                                </div>
                                                <div className="text-xs text-gray-400 truncate mt-1">{mail.body.substring(0, 50)}...</div>
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        </div>

                        {/* Content Pane */}
                        <div className={`flex-grow flex flex-col bg-white dark:bg-gray-800 ${isMobileListOpen ? 'hidden md:flex' : 'flex'}`}>
                            {selectedMail ? (
