import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import ClientsPage from './pages/ClientsPage';
import ClientDetailPage from './pages/ClientDetailPage';
import SettingsPage from './pages/SettingsPage';
import PropertiesPage from './pages/PropertiesPage';
import AccountManagementPage from './pages/AccountManagementPage';
import CEOHub from './pages/CEOHub';
import LandPurchaseFormPage from './pages/LandPurchaseFormPage';
import PurchaseSaleManagementPage from './pages/PurchaseSaleManagementPage';
import PromotionsPage from './pages/PromotionsPage';
import AdministrationPage from './pages/AdministrationPage';
import HumanResourcesPage from './pages/HumanResourcesPage';
import AllLandLayoutsPage from './pages/AllLandLayoutsPage';
import AllocatePlotPage from './pages/AllocatePlotPage';
import ClientDocumentationPage from './pages/ClientDocumentationPage';
import AmendmentFormPage from './pages/AmendmentFormPage';
import AnalyticsPage from './pages/AnalyticsPage';
import AdvancedReportsPage from './pages/AdvancedReportsPage';
import UserActivityPage from './pages/UserActivityPage';
import PlaceholderPage from './pages/PlaceholderPage';
import MappingsPage from './pages/MappingsPage';
import SupportPage from './pages/SupportPage';

// Team Module Pages
import LeadsManagementPage from './pages/LeadsManagementPage';
import MailingPage from './pages/team/MailingPage';
import LeavePage from './pages/team/LeavePage';
import EventsPage from './pages/team/EventsPage';
import AnnouncementsPage from './pages/team/AnnouncementsPage';

import { DataProvider, usePermissions } from './context/DataContext';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import { GENERATED_REPORTS } from './data/mockData';
import { Client, PermissionSet } from './types';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { 
    useClients, useProperties, useInvoices, useStaff, useLeads, 
    usePromotions, useActivityLogs, useRoles, useAmendments, useCompanySettings 
} from './hooks/useAppData';

const queryClient = new QueryClient();

const AppContent: React.FC = () => {
    const { clients, saveClient, deleteClient } = useClients();
    const { properties, saveProperty } = useProperties();
    const { invoices, saveInvoice } = useInvoices();
    const { staff, updateStaff } = useStaff(); 
    const { leads, saveLead, deleteLead } = useLeads();
    const { promotions, savePromotion, deletePromotion } = usePromotions();
    const { activityLogs, addActivityLog } = useActivityLogs();
    const { roles, setRoles } = useRoles();
    const { amendments, setAmendmentList } = useAmendments();
    const { companySettings, setCompanySettings } = useCompanySettings();
    const { rolePermissions } = usePermissions();

    const { currentStaff, login, logout, isAuthenticated } = useAuth();

    const [activePage, setActivePage] = useState('Dashboard');
    const [pageContext, setPageContext] = useState<any>(null);
    const [clientForInvoice, setClientForInvoice] = useState<Client | null>(null);

    useEffect(() => {
        if (companySettings.favicon) {
            let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
            if (!link) {
                link = document.createElement('link');
                link.rel = 'icon';
                document.head.appendChild(link);
            }
            link.href = companySettings.favicon;
        }
    }, [companySettings.favicon]);

    const handleAddActivityLog = (type: any, description: string) => {
        if (currentStaff) {
            addActivityLog(type, description, currentStaff.id);
        }
    };

    const handleSetPage = (page: string, context: any = null) => {
        setActivePage(page);
        setPageContext(context);
    };

    const staffPermissions = useMemo(() => {
        if (!currentStaff) return {};
        const userPermissions: { [key: string]: PermissionSet } = {};
        const rolePerms = rolePermissions.filter(rp => rp.roleId === currentStaff.roleId);
        rolePerms.forEach(rp => {
            userPermissions[rp.moduleId] = rp.permissions;
        });
        if (Object.keys(userPermissions).length === 0) {
             userPermissions['Dashboard'] = { view: true, create: false, edit: false, delete: false, approve: false };
        }
        return userPermissions;
    }, [currentStaff, rolePermissions]);

    if (!isAuthenticated || !currentStaff) {
        return <LoginPage onLogin={login} companySettings={companySettings} />;
    }

    const renderPage = () => {
        switch (activePage) {
            case 'Dashboard':
                return <Dashboard />;
            case 'Clients':
                return <ClientsPage 
                    clients={clients} 
                    onSaveClient={saveClient}
                    onDeleteClient={deleteClient}
                    properties={properties} 
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }, { acronym: 'PAYM', label: 'Payment', progress: 40 }, { acronym: 'IND', label: 'Indenture', progress: 70 }, { acronym: 'COMP', label: 'Completed', progress: 100 }]}
                    onClientSelect={(client) => handleSetPage('Client Details', client)} 
                    setActivePage={handleSetPage}
                    setClientForInvoice={setClientForInvoice}
                    invoices={invoices}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Client Details':
                return <ClientDetailPage 
                    client={pageContext} 
                    properties={properties}
                    onBack={() => handleSetPage('Clients')}
                    currentStaff={currentStaff}
                    roles={roles}
                    setActivePage={handleSetPage}
                />;
            case 'Account Management':
                 return <AccountManagementPage 
                    clients={clients}
                    onSaveClient={saveClient}
                    onClientSelect={(client) => handleSetPage('Client Details', client)}
                    invoices={invoices}
                    onSaveInvoice={saveInvoice}
                    clientForInvoice={clientForInvoice}
                    setClientForInvoice={setClientForInvoice}
                    receiptPattern={null} 
                    setReceiptPattern={() => {}}
                    setReceiptAlerts={() => {}}
                    currentStaff={currentStaff}
                    roles={roles}
                 />;

            // Team Sub-modules
            case 'Leads & Follow-Ups':
                return <LeadsManagementPage 
                    onSaveLead={saveLead}
                    onDeleteLead={deleteLead}
                    clients={clients}
                    onSaveClient={saveClient}
                    staffList={staff}
                    roles={roles}
                    properties={properties}
                    milestones={[{ acronym: 'REG', label: 'Registration', progress: 10 }]}
                    currentStaff={currentStaff}
                    addActivityLog={handleAddActivityLog}
                />;
            case 'Mailing':
                return <MailingPage />;
            case 'Leave':
                return <LeavePage />;
            case 'Events':
                return <EventsPage />;
            case 'Announcements':
                return <AnnouncementsPage />;

            case 'Settings':
                return <SettingsPage 
                    currentStaff={currentStaff} 
                    staff={staff}
                    roles={roles}
                    setRoles={setRoles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    companySettings={companySettings}
                    setCompanySettings={setCompanySettings}
                    onUpdateStaff={updateStaff}
                />;
            case 'CEO Hub':
                 return <CEOHub
                    setActivePage={handleSetPage}
                    properties={properties}
                    clients={clients}
                    invoices={invoices}
                    staff={staff}
                    roles={roles}
                    onViewStaffActivity={(staff) => handleSetPage('Staff Activity', staff)}
                    addActivityLog={handleAddActivityLog}
                />;
             case 'Properties':
                return <PropertiesPage properties={properties} currentStaff={currentStaff} onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} />;
             case 'New Land Acquisition':
                return <LandPurchaseFormPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} />;
             case 'Purchase & Sale Management':
                return <PurchaseSaleManagementPage onBack={() => handleSetPage('CEO Hub')} properties={properties} onSaveProperty={saveProperty} currentStaff={currentStaff} />;
             case 'Promotions':
                return <PromotionsPage 
                    promotions={promotions} 
                    onSavePromotion={savePromotion}
                    onDeletePromotion={deletePromotion}
                    properties={properties} 
                    showForm={true} 
                    onBack={pageContext?.from === 'CEO Hub' ? () => handleSetPage('CEO Hub') : undefined} 
                />;
            case 'Administration':
                return <AdministrationPage setActivePage={handleSetPage} />;
            case 'Human Resources':
                return <HumanResourcesPage onBack={() => handleSetPage('Administration')} staff={staff} roles={roles} addActivityLog={handleAddActivityLog} />;
            case 'All Land Layouts':
                return <AllLandLayoutsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Allocate Plot':
                return <AllocatePlotPage onBack={() => handleSetPage('Administration')} clients={clients} properties={properties}/>;
            case 'Client Documentation':
                return <ClientDocumentationPage onBack={() => handleSetPage('Administration')} clients={clients} onSaveClient={saveClient} />;
            case 'Mappings':
                return <MappingsPage onBack={() => handleSetPage('Administration')} properties={properties} />;
            case 'Amendment Form':
                return (
                    <AmendmentFormPage 
                        client={pageContext} 
                        onBack={() => handleSetPage('Client Details', pageContext)} 
                        onSave={async (data, updatedClient) => { 
                            setAmendmentList(prev => [data, ...prev]); 
                            await saveClient(updatedClient);
                            handleAddActivityLog('Update', `Processed amendment request for client: ${updatedClient.name}`);
                            alert('Amendment processed and client record updated successfully!'); 
                            handleSetPage('Client Details', updatedClient);
                        }} 
                        currentStaff={currentStaff} 
                    />
                );
            case 'Analytics & Reports':
                return <AnalyticsPage onBack={() => handleSetPage('CEO Hub')} clients={clients} properties={properties} invoices={invoices} staff={staff} addActivityLog={handleAddActivityLog} />;
            case 'Advanced Reports':
                return <AdvancedReportsPage onBack={() => handleSetPage('CEO Hub')} reports={GENERATED_REPORTS} addActivityLog={handleAddActivityLog} />;
            case 'Staff Activity':
                return <UserActivityPage staffMember={pageContext} logs={activityLogs.filter(l => l.userId === pageContext.id)} onBack={() => handleSetPage('Settings')} />;
            case 'Support':
                return <SupportPage />;
            default:
                return <Dashboard />;
        }
    };

    return (
        <Layout 
            activePage={activePage} 
            setActivePage={handleSetPage} 
            currentStaff={currentStaff} 
            onLogout={logout}
            staffPermissions={staffPermissions}
            companySettings={companySettings}
        >
            {renderPage()}
        </Layout>
    );
};

const App: React.FC = () => {
    return (
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <AuthProvider>
                    <DataProvider>
                        <AppContent />
                    </DataProvider>
                </AuthProvider>
            </ThemeProvider>
        </QueryClientProvider>
    );
};

export default App;

import React, { useState, useMemo } from 'react';
import { XIcon } from './icons/XIcon';
import { 
  HomeIcon, 
  UsersIcon, 
  Cog6ToothIcon, 
  ChevronDownIcon, 
  DocumentPlusIcon, 
  BriefcaseIcon, 
  UserGroupIcon, 
  CalendarDaysIcon, 
  BookOpenIcon, 
  MegaphoneIcon, 
  ArrowRightOnRectangleIcon, 
  QuestionMarkCircleIcon, 
  ShieldCheckIcon, 
  AcademicCapIcon, 
  FaimLogoIcon, 
  TagIcon, 
  EnvelopeIcon
} from './icons/DummyIcons';
import { PermissionSet, CompanySettings } from '../types';

interface SidebarProps {
  isMobileOpen: boolean;
  onMobileClose: () => void;
  isDesktopCollapsed: boolean;
  activePage: string;
  setActivePage: (page: string) => void;
  staffPermissions: { [key: string]: PermissionSet };
  companySettings: CompanySettings;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  isMobileOpen, 
  onMobileClose,
  isDesktopCollapsed,
  activePage,
  setActivePage,
  staffPermissions,
  companySettings,
}) => {
  const [openMenus, setOpenMenus] = useState<Record<string, boolean>>({
    'Client Management': true,
    'Team': true
  });

  // Mocking unread count - in production this would come from a context/hook
  const unreadMails = 1; 

  const toggleMenu = (name: string) => {
    setOpenMenus(prev => ({ ...prev, [name]: !prev[name] }));
  };

  const handleNavClick = (pageName: string) => {
    setActivePage(pageName);
    onMobileClose();
  };

  const allNavItems = [
    { name: 'Dashboard', icon: <HomeIcon />, href: '#', moduleId: 'Dashboard' },
    {
      name: 'Client Management',
      icon: <UsersIcon />,
      moduleId: 'Clients',
      subItems: [
        { name: 'Clients', icon: <UserGroupIcon />, href: '#', moduleId: 'Clients' },
        { name: 'Account Management', icon: <DocumentPlusIcon />, href: '#', moduleId: 'Account Management' },
      ],
    },
    {
      name: 'Team',
      icon: <BriefcaseIcon />,
      moduleId: 'Team',
      subItems: [
        { name: 'Leads & Follow-Ups', icon: <UsersIcon />, href: '#', moduleId: 'Leads Management' },
        { name: 'Mailing', icon: <EnvelopeIcon />, href: '#', moduleId: 'Internal Mailing', badge: unreadMails },
        { name: 'Leave', icon: <CalendarDaysIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Events', icon: <BookOpenIcon />, href: '#', moduleId: 'Administration' },
        { name: 'Announcements', icon: <MegaphoneIcon />, href: '#', moduleId: 'Administration' },
      ],
    },
    { name: 'Promotions', icon: <TagIcon />, href: '#', moduleId: 'Promotions' },
    { name: 'Administration', icon: <ShieldCheckIcon />, href: '#', moduleId: 'Administration'},
    { name: 'CEO Hub', icon: <AcademicCapIcon />, href: '#', moduleId: 'CEO Hub' },
    { name: 'Support', icon: <QuestionMarkCircleIcon />, href: '#', moduleId: 'Settings' },
    { name: 'Settings', icon: <Cog6ToothIcon />, href: '#', moduleId: 'Settings' },
  ];

  const visibleNavItems = allNavItems.filter(item => staffPermissions[item.moduleId]?.view).map(item => {
      if (item.subItems) {
          return {
              ...item,
              subItems: item.subItems.filter(subItem => staffPermissions[subItem.moduleId]?.view)
          };
      }
      return item;
  }).filter(item => !item.subItems || item.subItems.length > 0);

  const sidebarLogo = companySettings.appLogoDark || companySettings.appLogoLight || companySettings.logo;

  const sidebarContent = (
    <>
      <div className="flex flex-col items-center justify-center p-4 h-24 border-b border-gray-800 flex-shrink-0">
          {sidebarLogo ? (
            <img key={sidebarLogo} src={sidebarLogo} alt={`${companySettings.name} Logo`} className="w-12 h-12 object-contain" />
          ) : (
            <FaimLogoIcon className="w-10 h-10 text-white" />
          )}
          {!isDesktopCollapsed && (
            <h1 className="text-xl font-bold tracking-wider text-white mt-2">
              {companySettings.name.split(' ')[0]}<span className="text-blue-400">.</span>
            </h1>
          )}
        <button onClick={onMobileClose} className="md:hidden absolute top-5 right-4 text-gray-400 hover:text-white">
          <XIcon className="w-6 h-6" />
        </button>
      </div>
      <nav className="flex-grow p-2 overflow-y-auto">
        <ul>
          {visibleNavItems.map((item) => (
            <li key={item.name}>
              {item.subItems ? (
                <>
                  <button
                    onClick={() => toggleMenu(item.name)}
                    className={`flex items-center justify-between w-full gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                      activePage === item.name || item.subItems.some(sub => sub.name === activePage || (sub.name === 'Clients' && activePage === 'Client Details'))
                        ? 'text-white'
                        : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-6 h-6">{item.icon}</span>
                      {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                    </div>
                    {!isDesktopCollapsed && (
                      <ChevronDownIcon className={`w-5 h-5 transition-transform ${openMenus[item.name] ? 'rotate-180' : ''}`} />
                    )}
                  </button>
                  {(!isDesktopCollapsed && openMenus[item.name]) && (
                    <ul className="pl-6">
                      {item.subItems.map((subItem) => (
                        <li key={subItem.name}>
                          <a
                            href={subItem.href}
                            onClick={(e) => { e.preventDefault(); handleNavClick(subItem.name); }}
                            className={`flex items-center justify-between pl-3 pr-4 py-2 my-1 rounded-md transition-colors duration-200 text-sm relative group ${
                              activePage === subItem.name || (subItem.name === 'Clients' && activePage === 'Client Details')
                                ? 'bg-blue-600 text-white shadow-lg'
                                : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                            }`}
                          >
                            <div className="flex items-center gap-3">
                              <span className="w-6 h-6">{subItem.icon}</span>
                              <span className="font-medium">{subItem.name}</span>
                            </div>
                            {subItem.badge !== undefined && subItem.badge > 0 && (
                                <span className="bg-red-500 text-white text-[10px] font-black px-1.5 py-0.5 rounded-full ring-2 ring-gray-900 group-hover:ring-gray-800 transition-all">
                                    {subItem.badge}
                                </span>
                            )}
                          </a>
                        </li>
                      ))}
                    </ul>
                  )}
                </>
              ) : (
                <a
                  href={item.href}
                  onClick={(e) => { e.preventDefault(); handleNavClick(item.name); }}
                  className={`flex items-center gap-3 px-3 py-3 my-1 rounded-md transition-colors duration-200 ${
                    activePage === item.name
                      ? 'bg-blue-600 text-white shadow-lg'
                      : 'hover:bg-gray-800 text-gray-400 hover:text-white'
                  }`}
                >
                  <span className="w-6 h-6">{item.icon}</span>
                  {!isDesktopCollapsed && <span className="font-medium">{item.name}</span>}
                </a>
              )}
            </li>
          ))}
        </ul>
      </nav>
    </>
  );

  return (
    <>
      <div
        className={`fixed inset-0 z-40 bg-black bg-opacity-50 transition-opacity md:hidden ${
          isMobileOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={onMobileClose}
      ></div>
      <aside
        className={`fixed inset-y-0 left-0 z-50 flex flex-col bg-gray-900 text-white w-64 transform transition-transform duration-300 ease-in-out md:hidden ${
          isMobileOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {sidebarContent}
      </aside>
      <aside className={`hidden md:flex flex-col bg-gray-900 text-white transition-all duration-300 ease-in-out ${isDesktopCollapsed ? 'w-20' : 'w-64'}`}>
        {sidebarContent}
      </aside>
    </>
  );
};

export default Sidebar;

