import React, { useMemo } from 'react';
import StatCard from '../components/StatCard';
import { BanknotesIcon, CheckCircleIcon, ClockIcon, DocumentDuplicateIcon, ExclamationTriangleIcon, UserGroupIcon } from '../components/icons/DummyIcons';
import { useClients, useProperties, useInvoices } from '../hooks/useAppData';
import { useTheme } from '../context/ThemeContext';
import { 
    AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
    BarChart, Bar, PieChart, Pie, Cell, Legend
} from 'recharts';

const Dashboard: React.FC = () => {
    const { clients } = useClients();
    const { properties } = useProperties();
    const { invoices } = useInvoices();
    const { theme } = useTheme();

    const isDark = theme === 'dark';

    // -- Dynamic Real-Time Aggregation --
    const statsData = useMemo(() => {
        const totalClients = clients.length;
        const activeProcesses = clients.filter(c => c.stage !== 'COMP').length;
        const completedDeals = clients.filter(c => c.stage === 'COMP').length;
        const totalRevenue = clients.reduce((acc, client) => acc + (client.payment?.paid || 0), 0);
        const pendingPayments = invoices.filter(i => i.status === 'Pending' || i.status === 'Overdue').length;
        const availablePlots = properties.reduce((acc, prop) => {
            const totalPlots = prop.inventory?.reduce((sum, inv) => sum + (inv.count || 0), 0) || 0;
            const plotsSold = prop.inventory?.reduce((sum, inv) => sum + (inv.sold || 0), 0) || 0;
            return acc + (totalPlots - plotsSold);
        }, 0);

        return { totalClients, activeProcesses, completedDeals, totalRevenue, pendingPayments, availablePlots };
    }, [clients, properties, invoices]);

    // -- Chart Data Transformation --
    const revenueData = useMemo(() => {
        const monthlyRevenue: Record<string, number> = {};
        clients.forEach(client => {
            client.payment?.paymentHistory?.forEach(txn => {
                if (txn.date && txn.status === 'Success') {
                    const month = txn.date.substring(0, 7);
                    monthlyRevenue[month] = (monthlyRevenue[month] || 0) + txn.amount;
                }
            });
        });
        return Object.entries(monthlyRevenue)
            .map(([date, amount]) => ({
                name: new Date(date).toLocaleDateString('en-US', { month: 'short' }),
                revenue: amount,
                dateStr: date
            }))
            .sort((a, b) => a.dateStr.localeCompare(b.dateStr))
            .slice(-6);
    }, [clients]);

    const formatCurrencyCompact = (amount: number) => {
        return new Intl.NumberFormat('en-GH', { 
            style: 'currency', 
            currency: 'GHC', 
            notation: 'compact', 
            maximumFractionDigits: 1 
        }).format(amount);
    };

    const stats = [
        { title: "Total Clients", value: statsData.totalClients.toLocaleString(), rawValue: statsData.totalClients, change: "+12%", changeType: "increase" as const, icon: <UserGroupIcon className="w-6 h-6 text-blue-500" /> },
        { title: "Active Deals", value: statsData.activeProcesses.toLocaleString(), rawValue: statsData.activeProcesses, change: "+5%", changeType: "increase" as const, icon: <ClockIcon className="w-6 h-6 text-orange-500" /> },
        { title: "Revenue", value: formatCurrencyCompact(statsData.totalRevenue), rawValue: statsData.totalRevenue, change: "+18%", changeType: "increase" as const, icon: <BanknotesIcon className="w-6 h-6 text-teal-500" /> },
        { title: "Pending", value: statsData.pendingPayments.toLocaleString(), rawValue: statsData.pendingPayments, change: "-2%", changeType: "decrease" as const, icon: <ExclamationTriangleIcon className="w-6 h-6 text-red-500" /> },
        { title: "Inventory", value: statsData.availablePlots.toLocaleString(), rawValue: statsData.availablePlots, change: "Stable", changeType: "increase" as const, icon: <DocumentDuplicateIcon className="w-6 h-6 text-purple-500" /> },
        { title: "Success", value: statsData.completedDeals.toLocaleString(), rawValue: statsData.completedDeals, change: "+8%", changeType: "increase" as const, icon: <CheckCircleIcon className="w-6 h-6 text-green-500" /> },
    ];

    const COLORS = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6'];
    const GRID_COLOR = isDark ? '#1e293b' : '#f1f5f9';

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Business Intel</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1 font-medium italic">Real-time indicators across all operational modules.</p>
                </div>
            </div>

            {/* Dynamic Markers Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
                {stats.map(stat => (
                    <StatCard key={stat.title} {...stat} />
                ))}
            </div>

            {/* Graphs Section */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <Card title="Monthly Revenue Performance" className="h-[400px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={revenueData}>
                            <defs>
                                <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#3B82F6" stopOpacity={0.3}/>
                                    <stop offset="95%" stopColor="#3B82F6" stopOpacity={0}/>
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={GRID_COLOR} />
                            <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} dy={10} />
                            <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => `GHC ${v/1000}k`} />
                            <Tooltip 
                                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)', backgroundColor: isDark ? '#0f172a' : '#fff' }}
                                formatter={(v: number) => [`GHC ${v.toLocaleString()}`, 'Revenue']}
                            />
                            <Area type="monotone" dataKey="revenue" stroke="#3B82F6" strokeWidth={3} fillOpacity={1} fill="url(#colorRev)" />
                        </AreaChart>
                    </ResponsiveContainer>
                </Card>

                <Card title="Acquisition Distribution" className="h-[400px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                            <Pie
                                data={[
                                    { name: 'East Legon', value: properties.find(p => p.location.includes('Legon'))?.inventory.reduce((s,i) => s + i.sold, 0) || 0 },
                                    { name: 'Appolonia', value: properties.find(p => p.location.includes('Appolonia'))?.inventory.reduce((s,i) => s + i.sold, 0) || 0 },
                                    { name: 'Other', value: 5 }
                                ].filter(d => d.value > 0)}
                                cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value"
                            >
                                {COLORS.map((color, index) => <Cell key={index} fill={color} />)}
                            </Pie>
                            <Tooltip />
                            <Legend verticalAlign="bottom" iconType="circle" />
                        </PieChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        </div>
    );
};

export default Dashboard;

import React from 'react';
import { Client, Milestone } from '../types';
import { EyeIcon, PencilIcon, ChevronDownIcon, CheckCircleIcon, ExclamationTriangleIcon, TrashIcon, BanknotesIcon } from './icons/DummyIcons';

interface ClientListItemProps {
  client: Client;
  onViewDetails: (client: Client) => void;
  onEdit: (client: Client) => void;
  onDelete: (clientId: number) => void;
  milestones: Milestone[];
  style?: React.CSSProperties;
  isExpanded?: boolean;
  onToggleExpand?: () => void;
}

const getStatusVisuals = (client: Client) => {
  const balance = client.payment?.balance || 0;
  if (balance === 0 && (client.payment?.paid || 0) > 0) {
      return { label: 'Fully Paid', color: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300' };
  }
  if (balance < 0) {
      return { label: 'Overpaid', color: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300' };
  }
  return { label: 'Owing', color: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300' };
};

const ClientListItem: React.FC<ClientListItemProps> = ({ client, onViewDetails, onEdit, onDelete, milestones, style, isExpanded, onToggleExpand }) => {
  const currentMilestone = milestones.find(m => m.acronym === client.stage) || milestones[0];
  const { label: statusLabel, color: statusColor } = getStatusVisuals(client);

  // Real-time calculation based on payment data
  const paymentProgress = Math.min(100, Math.round(((client.payment?.paid || 0) / (client.payment?.total || 1)) * 100));

  return (
    <div style={style} className="px-2 py-2">
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 grid grid-cols-12 gap-4 items-center hover:shadow-md transition-all duration-200 h-full group">
            {/* Name & Milestone Indicator */}
            <div className="col-span-12 md:col-span-4 flex items-center gap-3">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center font-black text-white shrink-0 shadow-inner ${client.isComplete ? 'bg-blue-600' : 'bg-gray-400'}`}>
                    {client.initials}
                </div>
                <div className="flex-grow min-w-0">
                    <p className="font-bold text-gray-900 dark:text-white truncate flex items-center gap-1.5">
                        {client.name}
                        {client.isComplete ? <CheckCircleIcon className="w-4 h-4 text-green-500" /> : <ExclamationTriangleIcon className="w-4 h-4 text-amber-500" />}
                    </p>
                    <div className="flex items-center gap-2 mt-1">
                        <div className="flex-grow bg-gray-100 dark:bg-gray-700 rounded-full h-1.5 overflow-hidden">
                            <div 
                                className="bg-blue-500 h-full transition-all duration-700 ease-out" 
                                style={{ width: `${currentMilestone?.progress || 0}%` }}
                                title={`Stage: ${currentMilestone?.label} (${currentMilestone?.progress}%)`}
                            />
                        </div>
                        <span className="text-[9px] font-black text-gray-400 uppercase">{client.stage}</span>
                    </div>
                </div>
            </div>

            {/* Financial Marker */}
            <div className="col-span-6 md:col-span-3">
                <div className="flex flex-col gap-1">
                    <div className="flex justify-between items-center text-[10px] font-bold text-gray-400 uppercase tracking-tighter">
                        <span>Payment Coverage</span>
                        <span>{paymentProgress}%</span>
                    </div>
                    <div className="w-full bg-gray-100 dark:bg-gray-700 rounded-full h-2 overflow-hidden shadow-inner">
                        <div 
                            className={`h-full transition-all duration-1000 ${paymentProgress >= 100 ? 'bg-green-500' : paymentProgress >= 50 ? 'bg-blue-500' : 'bg-amber-500'}`}
                            style={{ width: `${paymentProgress}%` }}
                        />
                    </div>
                </div>
            </div>

            {/* Status Indicator */}
            <div className="col-span-3 md:col-span-2 text-center">
                <span 
                    className={`px-3 py-1 text-[10px] font-black uppercase tracking-widest rounded-full border border-transparent transition-all group-hover:border-current ${statusColor}`}
                    title={`Balance: GHC ${(client.payment?.balance || 0).toLocaleString()}`}
                >
                    {statusLabel}
                </span>
            </div>

            {/* Actions */}
            <div className="col-span-3 md:col-span-3 flex justify-end gap-1">
                <button onClick={() => onViewDetails(client)} className="p-2 text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 transition-colors" title="View Dossier"><EyeIcon className="w-5 h-5"/></button>
                <button onClick={() => onEdit(client)} className="p-2 text-gray-400 hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors" title="Quick Edit"><PencilIcon className="w-5 h-5"/></button>
                <button onClick={() => onDelete(client.id)} className="p-2 text-gray-400 hover:text-red-600 transition-colors" title="Archive"><TrashIcon className="w-5 h-5"/></button>
            </div>
        </div>
    </div>
  );
};

export default ClientListItem;

import React from 'react';
import { Client } from '../types';
import { Badge } from './ui/Badge';

interface PaymentSummaryProps {
  payment: Client['payment'];
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-GH', { 
        style: 'currency', 
        currency: 'GHC',
        minimumFractionDigits: 2 
    }).format(Math.abs(amount));
};

const PaymentSummary: React.FC<PaymentSummaryProps> = ({ payment }) => {
    const total = payment.total || 0;
    const paid = payment.paid || 0;
    const balance = payment.balance || 0;
    const progress = total > 0 ? Math.min(100, Math.round((paid / total) * 100)) : 0;

    return (
        <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 transition-all duration-300">
            <div className="flex justify-between items-start mb-6">
                <h3 className="text-sm font-black text-gray-900 dark:text-white uppercase tracking-widest">Financial Standing</h3>
                <Badge variant={balance <= 0 ? 'success' : 'danger'}>
                    {balance <= 0 ? 'Account Settled' : 'Action Required'}
                </Badge>
            </div>

            <div className="space-y-6">
                <div className="relative pt-1">
                    <div className="flex mb-2 items-center justify-between">
                        <div>
                            <span className="text-[10px] font-black inline-block py-1 px-2 uppercase rounded-full text-blue-600 bg-blue-100 dark:bg-blue-900/30 dark:text-blue-400">
                                Payment Coverage
                            </span>
                        </div>
                        <div className="text-right">
                            <span className="text-sm font-black text-blue-600 dark:text-blue-400 tabular-nums">
                                {progress}%
                            </span>
                        </div>
                    </div>
                    <div className="overflow-hidden h-3 mb-4 text-xs flex rounded-full bg-gray-100 dark:bg-gray-700 shadow-inner">
                        <div 
                            style={{ width: `${progress}%` }} 
                            className={`shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center transition-all duration-1000 ease-out ${progress === 100 ? 'bg-green-500' : 'bg-blue-500'}`}
                        />
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="p-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-700">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">Total Invoiced</p>
                        <p className="text-sm font-bold text-gray-900 dark:text-white mt-1 tabular-nums">{formatCurrency(total)}</p>
                    </div>
                    <div className="p-3 bg-green-50 dark:bg-green-900/10 rounded-xl border border-green-100 dark:border-green-900/50">
                        <p className="text-[10px] font-black text-green-600 uppercase tracking-tighter">Receipted</p>
                        <p className="text-sm font-bold text-green-700 dark:text-green-400 mt-1 tabular-nums">{formatCurrency(paid)}</p>
                    </div>
                    <div className={`col-span-2 p-4 rounded-xl border-2 shadow-sm ${balance > 0 ? 'bg-red-50 border-red-100 dark:bg-red-900/10 dark:border-red-900/50' : 'bg-indigo-50 border-indigo-100 dark:bg-indigo-900/10 dark:border-indigo-900/50'}`}>
                        <div className="flex justify-between items-center">
                            <p className="text-xs font-black text-gray-500 uppercase tracking-widest">{balance > 0 ? 'Outstanding Arrears' : 'Credit Balance'}</p>
                            <p className={`text-lg font-black tabular-nums ${balance > 0 ? 'text-red-600' : 'text-indigo-600 dark:text-indigo-400'}`}>
                                {formatCurrency(balance)}
                            </p>
                        </div>
                    </div>
                </div>

                {balance > 0 && (
                    <div className="pt-4 border-t border-gray-100 dark:border-gray-700 text-center">
                        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mb-1">Upcoming Commitment</p>
                        <p className="text-base font-black text-blue-600 dark:text-blue-400">
                           {payment.dueDate || 'Pending Schedule'}
                        </p>
                    </div>
                )}
            </div>
        </div>
    );
};

