import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
    ChevronDownIcon, 
    DocumentPlusIcon, 
    MagnifyingGlassIcon, 
    UploadIcon 
} from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import ClientListItem from '../components/ClientListItem';
import { Client, Milestone, Property, Invoice, ActivityLog } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { VariableSizeList as List } from 'react-window';
import AutoSizer from 'react-virtualized-auto-sizer';
import { useClients } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';

interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string) => void;
    setClientForInvoice: (client: Client) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (data: Partial<Client>): boolean => {
    // Defines core system requirements for a "Complete" status
    const required: (keyof Client | string)[] = [ 
        'surname', 'otherNames', 'phone', 'location', 'plot',
        'nextOfKin.name', 'nextOfKin.phone', 'witness.name', 'witness.phone',
        'officeUse.salesRep', 'officeUse.clerk'
    ];

    for (const path of required) {
        const parts = path.split('.');
        let val: any = data;
        for (const part of parts) {
            val = val ? val[part] : undefined;
        }
        if (!val || String(val).trim() === '' || val === 'N/A') return false;
    }
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});
    const [scrollOffset, setScrollOffset] = useState(0);
    const MAX_SCROLL = 80;

    const handleScroll = ({ scrollOffset: offset }: { scrollOffset: number }) => {
        setScrollOffset(Math.min(offset, MAX_SCROLL));
    };

    const headerOpacity = Math.max(0, 1 - scrollOffset / (MAX_SCROLL * 0.8));
    const headerHeight = Math.max(0, 48 - (scrollOffset / MAX_SCROLL) * 48);
    const controlsTranslate = (scrollOffset / MAX_SCROLL) * -52;

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const getItemSize = (index: number) => {
        const client = clients[index];
        return expandedIds[client?.id] ? 140 : 100;
    };

    const handleImportLeads = async (importedData: any[]) => {
        const highestId = clients.length > 0 ? Math.max(...clients.map(c => c.id)) : 0;

        const mappedClients: Client[] = importedData.map((row, index) => {
            const fullName = row['Primary Contact'] || 'Unknown Client';
            const nameParts = fullName.split(' ');
            const surname = nameParts.length > 1 ? nameParts.pop() : '';
            const otherNames = nameParts.join(' ');
            const initials = (fullName.split(' ').map((n:string) => n[0]).join('')).toUpperCase().substring(0, 2);

            const clientObj: Client = {
                id: highestId + 1 + index,
                name: fullName,
                surname: surname || fullName,
                otherNames: otherNames || '',
                initials: initials || '??',
                regDate: row['First Payment Date'] || new Date().toISOString().split('T')[0],
                email: row['Email'] || '',
                phone: row['Telephone'] || row['Phone'] || '',
                dateOfBirth: row['Date of Birth'] || '',
                gender: (row['Gender'] || 'Other') as any,
                location: row['Location'] || row['Land Location'] || 'N/A',
                plot: row['Plot Number'] || 'N/A',
                status: (row['Client Status'] || 'Active Client') as any,
                stage: milestones[0].acronym,
                payment: {
                    total: parseFloat(row['Total Invoiced']) || 0,
                    paid: parseFloat(row['Payment Received']) || 0,
                    balance: parseFloat(row['Due']) || 0,
                    dueDate: 'N/A',
                    planType: row['Payment Method'] || 'N/A',
                    paymentHistory: [],
                    installments: []
                },
                interactions: [],
                witness: { 
                    name: row['Witness Name'] || '', 
                    address: row['Witness Address'] || '', 
                    phone: row['Witness Phone'] || '' 
                },
                nextOfKin: { 
                    name: row['Next of Kin Name'] || '', 
                    phone: row['Next of Kin Phone'] || '', 
                    relationship: row['Next of Kin Relationship'] || '',
                    email: row['Next of Kin Email'] || '',
                    address: row['Next of Kin Address'] || ''
                },
                indenture: { 
                    name: row['Indenture Name'] || '', 
                    address: row['Indenture Address'] || '' 
                },
                officeUse: {
                    salesRep: row['Sales Rep'] || '',
                    salesManager: row['Sales Manager'] || '',
                    accountsHead: row['Accounts Head'] || '',
                    clerk: row['Clerk'] || '',
                    commission: { type: 'Percentage', amount: 0, status: 'Pending' }
                },
                documentation: { status: 'Pending' },
                isComplete: false, // Calculated below
                filledFormPdf: null,
            };

            clientObj.isComplete = isClientDataComplete(clientObj);
            return clientObj;
        });

        for (const client of mappedClients) {
            await onSaveClient(client);
        }

        addActivityLog('Import', `Imported ${mappedClients.length} clients via structured CSV.`);
        setImportWizardOpen(false);
    };

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);
            setClientToDelete(null);
        }
    };

    const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => {
        const client = clients[index];
        if (!client) return null;
        return (
            <ClientListItem 
                key={client.id} 
                client={client} 
                onViewDetails={onClientSelect} 
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }} 
                onDelete={(id) => setClientToDelete(clients.find(c => c.id === id) || null)} 
                milestones={milestones}
                style={style}
                isExpanded={!!expandedIds[client.id]}
                onToggleExpand={() => toggleExpand(client.id, index)}
            />
        );
    };

    // STRICT COLUMN ORDER DEFINITION
    const strictHeaders = [
        "Primary Contact", "Phone", "Client Groups", "Labels", "Projects", 
        "Total Invoiced", "Payment Received", "Due", "Land Location", "Number of Plots", 
        "Client Status", "Date of Birth", "Current Address", "Telephone", "Email", 
        "Gender", "Place of Work", "Profession", "Position", "Next of Kin Name", 
        "Next of Kin Address", "Next of Kin Phone", "Next of Kin Relationship", 
        "Next of Kin Email", "Witness Name", "Witness Address", "Witness Phone", 
        "First Payment Date", "Payment Method", "Location", "Plot Number", 
        "Property Type", "Year of Planned Development", "Indenture Name", 
        "Indenture Address", "Sales Rep", "Sales Manager", "Accounts Head", "Clerk"
    ];

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            <div className="bg-gray-100 dark:bg-gray-950 z-20 flex-shrink-0 transition-all duration-300 ease-out"
                 style={{ transform: `translateY(${controlsTranslate}px)` }}>

                <div style={{ opacity: headerOpacity, height: headerHeight, overflow: 'hidden' }} 
                     className="flex flex-wrap items-center justify-between gap-4 px-1">
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">
                        Clients ({clients.length}{hasNextPage && '+'})
                    </h1>
                    <div className="flex items-center gap-3">
                        <button onClick={() => setImportWizardOpen(true)} className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-bold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 transition-all flex items-center gap-2 text-sm shadow-sm">
                            <UploadIcon className="w-4 h-4" /> Import
                        </button>
                        <button onClick={() => { setEditingClient(null); setClientFormOpen(true); }} className="bg-blue-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-blue-700 transition-all flex items-center gap-2 text-sm shadow-md">
                            <DocumentPlusIcon className="w-4 h-4" /> New Client
                        </button>
                    </div>
                </div>

                <div className="mt-4 bg-white dark:bg-gray-800 p-3 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 mx-1">
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-center">
                        <div className="md:col-span-6 relative">
                            <div className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400">
                                {isLoading ? <LoaderIcon className="animate-spin" /> : <MagnifyingGlassIcon />}
                            </div>
                            <input
                                type="text"
                                placeholder="Quick search database..."
                                className="bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg pl-9 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm dark:text-white"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <div className="md:col-span-3">
                            <select className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 py-2 px-3 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                                <option>All Statuses</option>
                                <option>Active Client</option>
                                <option>Refunded</option>
                                <option>Reallocated</option>
                            </select>
                        </div>
                        <div className="md:col-span-3">
                            <select className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 py-2 px-3 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                                <option>All Locations</option>
                                {properties.map(p => <option key={p.id}>{p.location}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <div className="hidden md:grid grid-cols-12 gap-4 px-5 py-3 text-[10px] font-black text-gray-400 uppercase tracking-widest bg-transparent">
                    <div className="col-span-4">Client Dossier</div>
                    <div className="col-span-2">Contact Details</div>
                    <div className="col-span-2">Allocation</div>
                    <div className="col-span-1 text-center">Status</div>
                    <div className="col-span-2">Financials</div>
                    <div className="col-span-1 text-right pr-2">Manage</div>
                </div>
            </div>

            <div className="flex-grow relative mt-1">
                <AutoSizer>
                    {({ height, width }) => (
                        <List
                            ref={listRef}
                            height={height}
                            itemCount={clients.length}
                            itemSize={getItemSize}
                            width={width}
                            onScroll={handleScroll}
                            className="scrollbar-thin"
                        >
                            {Row}
                        </List>
                    )}
                </AutoSizer>
            </div>

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={handleImportLeads}
                requiredHeaders={strictHeaders}
                sampleHeaders={strictHeaders.join(',')}
                sampleData={`${strictHeaders.map(() => 'Sample Data').join(',')}`}
                wizardTitle="Structured Client Import"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />
            {isClientFormOpen && (
                <ClientForm
                    isOpen={isClientFormOpen}
                    onClose={() => { setClientFormOpen(false); setEditingClient(null); }}
                    onSave={async (f, fl) => { 
                        const newId = editingClient?.id || (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);
                        const c = editingClient || {} as Client;
                        await onSaveClient({...c, ...f as any, id: newId});
                        setClientFormOpen(false);
                    }}
                    onSaveAndPay={() => {}}
                    properties={properties}
                    editingClient={editingClient}
                />
            )}
        </div>
    );
};

