  wizardTitle: string;
}

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [validationResults, setValidationResults] = useState<{ data: any; errors: string[] }[]>([]);
    const [errors, setErrors] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setParsedData([]);
        setValidationResults([]);
        setErrors([]);
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const selectedFile = e.target.files[0];
            if (selectedFile.name.endsWith('.csv')) {
                 setFile(selectedFile);
                 setErrors([]);
            } else {
                setErrors(['Incorrect format. Please upload a standard .csv file.']);
                setFile(null);
            }
        }
    };

    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (char === '"') {
                if (inQuotes && text[i + 1] === '"') {
                    cell += '"';
                    i++;
                } else {
                    inQuotes = !inQuotes;
                }
            } else if (char === ',' && !inQuotes) {
                result.push(cell.trim());
                cell = '';
            } else {
                cell += char;
            }
        }
        result.push(cell.trim());
        return result;
    };

    const processFile = useCallback(() => {
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 2) {
                    setErrors(['The file is empty or missing content rows.']);
                    setIsLoading(false);
                    return;
                }

                const headerLine = lines[0].replace(/^\uFEFF/, ''); 
                const header = parseCSVLine(headerLine).map(h => h.replace(/^"|"$/g, '').trim());

                // Block if column count doesn't match the strict 39 required
                if (header.length < requiredHeaders.length) {
                    setErrors([`Invalid file structure. Found ${header.length} columns but 39 are required in strict order.`]);
                    setIsLoading(false);
                    return;
                }

                const validatedData = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);
                    if (values.length === 1 && values[0] === '') continue;

                    const rowData: { [key: string]: string } = {};
                    header.forEach((h, index) => {
                        // Strict mapping by header name found in file
                        rowData[h] = values[index] ? values[index].replace(/^"|"$/g, '') : '';
                    });

                    // Ensure all expected strict headers are at least keys in the object
                    requiredHeaders.forEach(rh => {
                        if (rowData[rh] === undefined) rowData[rh] = '';
                    });

                    validatedData.push({ data: rowData, errors: [] });
                }

                setValidationResults(validatedData);
                setParsedData(validatedData.map(v => v.data));
                setStep(3);
            } catch (error) {
                 setErrors(['System could not parse this file. Check for special characters.']);
            } finally {
                setIsLoading(false);
            }
        };
        reader.readAsText(file);
    }, [file, requiredHeaders]);

    const handleConfirmImport = () => {
        setIsLoading(true);
        setTimeout(() => {
            onImport(parsedData);
            setStep(4);
            setIsLoading(false);
        }, 300);
    };

    const downloadSampleCSV = () => {
        const csvContent = `${sampleHeaders}\n${sampleData}`;
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.setAttribute("href", url);
        link.setAttribute("download", "erp_client_import_template.csv");
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">{wizardTitle}</h2>
                    <button onClick={handleClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"><XIcon className="w-6 h-6" /></button>
                </div>

                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div className="animate-in fade-in slide-in-from-bottom-4">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">1. Format Preparation</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                This tool requires a strictly ordered 39-column CSV file. Missing data fields are acceptable and will be marked as "Incomplete" for later verification.
                            </p>
                            <div className="mt-6 p-4 bg-indigo-50 dark:bg-indigo-900/20 border-2 border-dashed border-indigo-200 dark:border-indigo-800 rounded-lg">
                                <h4 className="text-[10px] font-black text-indigo-800 dark:text-indigo-300 uppercase tracking-widest">Required Column Order:</h4>
                                <div className="text-[11px] text-indigo-700 dark:text-indigo-200 mt-2 font-mono leading-relaxed">
                                    {requiredHeaders.map((h, i) => <span key={h} className="inline-block mr-2">{i+1}. {h} |</span>)}
                                </div>
                            </div>
                            <div className="mt-6">
                                <Button onClick={downloadSampleCSV} icon={<DocumentTextIcon className="w-5 h-5" />}>Download Standard Template</Button>
                            </div>
                        </div>
                   )}
                   {step === 2 && (
                       <div className="animate-in fade-in slide-in-from-bottom-4">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">2. Upload File</h3>
                            <div className="mt-6 flex justify-center px-6 pt-10 pb-10 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md">
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                        <label className="relative cursor-pointer rounded-md font-black text-blue-600 hover:text-blue-500 uppercase tracking-widest">
                                            <span>Attach CSV Document</span>
                                            <input type="file" className="sr-only" onChange={handleFileChange} accept=".csv" />
                                        </label>
                                    </div>
                                    <p className="text-xs text-gray-500">{file ? `Selected: ${file.name}` : "File must follow strict 39-column rule"}</p>
                                </div>
                            </div>
                            {errors.length > 0 && <div className="mt-4 p-3 bg-red-50 text-red-700 text-xs font-bold rounded border border-red-100">{errors[0]}</div>}
                        </div>
                   )}
                   {step === 3 && (
                        <div className="animate-in fade-in slide-in-from-bottom-4">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">3. Import Review</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                <span className="font-bold text-green-600 uppercase">Ready:</span> {parsedData.length} entries found. System will auto-populate matching fields.
                            </p>
                            <div className="mt-4 border border-gray-200 dark:border-gray-700 rounded-lg overflow-x-auto max-h-80">
                                <table className="w-full text-[11px] text-left">
                                    <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0">
                                        <tr>
                                            <th className="px-4 py-2 font-black uppercase text-gray-500">Row</th>
                                            {requiredHeaders.slice(0, 8).map(h => <th key={h} className="px-4 py-2 font-black uppercase text-gray-500 whitespace-nowrap">{h}</th>)}
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white dark:bg-gray-800 divide-y dark:divide-gray-700">
                                        {parsedData.slice(0, 10).map((row, index) => (
                                            <tr key={index}>
                                                <td className="px-4 py-2 font-bold text-gray-400">{index + 1}</td>
                                                {requiredHeaders.slice(0, 8).map(h => <td key={h} className="px-4 py-2 truncate max-w-[150px] dark:text-gray-300">{row[h] || '---'}</td>)}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                            <p className="text-[10px] text-gray-400 mt-2 italic text-center">Entries with missing mandatory data will be flagged as "Incomplete" after ingestion.</p>
                        </div>
                   )}
                   {step === 4 && (
                       <div className="text-center py-10 animate-in zoom-in duration-300">
                            <CheckCircleIcon className="mx-auto h-20 w-20 text-green-500" />
                            <h3 className="mt-4 text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Import Finalized</h3>
                            <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">
                                Entries added to the database. Check status indicators for incomplete records.
                            </p>
                        </div>
                   )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>
                        {step > 1 && step < 4 && (
                            <button onClick={() => setStep(step - 1)} className="flex items-center gap-1 text-xs font-black uppercase tracking-widest text-gray-500 hover:text-gray-800"><ChevronLeftIcon className="w-4 h-4" /> Back</button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        {step < 3 && (
                            <Button onClick={step === 2 ? processFile : () => setStep(step + 1)} disabled={(step === 2 && !file) || isLoading} icon={<ChevronRightIcon className="w-4 h-4" />}>
                                {isLoading ? 'Validating...' : 'Continue'}
                            </Button>
                        )}
                        {step === 3 && (
                            <Button variant="success" onClick={handleConfirmImport} disabled={parsedData.length === 0 || isLoading} icon={<CheckCircleIcon className="w-4 h-4" />}>
                                Confirm Ingestion
                            </Button>
                        )}
                        {step === 4 && <Button onClick={handleClose}>Return to Database</Button>}
                    </div>
                </div>
            </div>
        </div>
    );
};

