import React from 'react';
import { Client, Milestone } from '../types';
import { EyeIcon, PencilIcon, ChevronDownIcon, CheckCircleIcon, ExclamationTriangleIcon, TrashIcon } from './icons/DummyIcons';

interface ClientListItemProps {
  client: Client;
  onViewDetails: (client: Client) => void;
  onEdit: (client: Client) => void;
  onDelete: (clientId: number) => void;
  milestones: Milestone[];
  style?: React.CSSProperties;
  isExpanded?: boolean;
  onToggleExpand?: () => void;
}

const getStatusColor = (client: Client) => {
  if (!client.isComplete) return 'bg-amber-100 text-amber-800 dark:bg-amber-900/40 dark:text-amber-300 border-amber-200';

  switch (client.status) {
    case 'Active Client':
      return 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-300 border-green-200';
    case 'Refunded':
      return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-300 border-yellow-200';
    case 'Reallocated':
      return 'bg-purple-100 text-purple-800 dark:bg-purple-900/40 dark:text-purple-300 border-purple-200';
    default:
      return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300 border-gray-200';
  }
};

const formatCurrency = (amount: number) => {
    return `GHC ${new Intl.NumberFormat('en-GH').format(amount)}`;
};

const ClientListItem: React.FC<ClientListItemProps> = ({ client, onViewDetails, onEdit, onDelete, milestones, style, isExpanded, onToggleExpand }) => {
  const currentMilestone = milestones.find(m => m.acronym === client.stage) || { progress: 0, label: 'Unknown' };

  return (
    <div style={style} className="px-2 py-2">
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 grid grid-cols-12 gap-4 items-center hover:shadow-md transition-all duration-200 h-full group">
            {/* Client Profile */}
            <div className="col-span-12 md:col-span-4 flex items-center gap-3">
                <div 
                    title={client.isComplete ? 'Record Complete' : 'Record Incomplete - Mandatory fields missing'}
                    className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shrink-0 shadow-inner ${client.isComplete ? 'bg-blue-600' : 'bg-amber-500'}`}
                >
                    {client.initials}
                </div>
                <div className="flex-grow min-w-0">
                    <p className="font-bold text-gray-900 dark:text-white flex items-center gap-1.5 truncate">
                        {client.name}
                        {client.isComplete ? (
                            <CheckCircleIcon className="w-4 h-4 text-green-500" />
                        ) : (
                            <div className="flex items-center gap-1">
                                <ExclamationTriangleIcon className="w-4 h-4 text-amber-500" />
                                <span className="text-[8px] font-black text-amber-600 uppercase tracking-tighter hidden group-hover:block">Update Profile</span>
                            </div>
                        )}
                    </p>
                    <div className="flex items-center gap-2 mt-1">
                        <div className="flex-grow bg-gray-100 dark:bg-gray-700 rounded-full h-1.5 overflow-hidden">
                            <div className="bg-blue-500 h-full transition-all duration-500" style={{ width: `${currentMilestone.progress}%` }}></div>
                        </div>
                        <span className="text-[9px] font-black text-gray-400 uppercase">{client.stage}</span>
                    </div>
                </div>
                {onToggleExpand && (
                    <button onClick={onToggleExpand} className="p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
                        <ChevronDownIcon className={`w-4 h-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                    </button>
                )}
            </div>

            {/* Contact */}
            <div className="col-span-12 md:col-span-2 text-xs text-gray-600 dark:text-gray-400 truncate">
                <p className="font-semibold text-gray-900 dark:text-gray-200">{client.phone}</p>
                <p className="truncate">{client.email || 'No Email'}</p>
            </div>

            {/* Allocation */}
            <div className="col-span-12 md:col-span-2 text-xs truncate">
                <p className="font-semibold text-gray-900 dark:text-gray-200">{client.location}</p>
                <p className="text-gray-500">Plot: {client.plot}</p>
            </div>

            {/* Status Indicator */}
            <div className="col-span-6 md:col-span-1 text-center">
                <span className={`px-2 py-1 text-[10px] font-black uppercase tracking-widest rounded-full border transition-all ${getStatusColor(client)}`}>
                    {client.isComplete ? client.status : 'Incomplete'}
                </span>
            </div>

            {/* Financials */}
            <div className="col-span-12 md:col-span-2 text-[10px]">
                <div className="flex justify-between">
                    <span className="text-gray-400 font-bold uppercase">Total:</span>
                    <span className="font-black text-gray-900 dark:text-gray-200">{formatCurrency(client.payment.total)}</span>
                </div>
                <div className="flex justify-between text-red-500">
                    <span className="font-bold uppercase">Due:</span>
                    <span className="font-black">{formatCurrency(client.payment.balance)}</span>
                </div>
            </div>

            {/* Actions */}
            <div className="col-span-12 md:col-span-1 flex items-center gap-1 justify-end">
                <button onClick={() => onViewDetails(client)} className="p-2 text-gray-400 hover:text-blue-600 transition-colors" title="View Dossier"><EyeIcon className="w-5 h-5"/></button>
                <button onClick={() => onEdit(client)} className={`p-2 transition-colors ${!client.isComplete ? 'text-amber-500 hover:text-amber-600 animate-pulse' : 'text-gray-400 hover:text-green-600'}`} title="Quick Edit"><PencilIcon className="w-5 h-5"/></button>
                <button onClick={() => onDelete(client.id)} className="p-2 text-gray-400 hover:text-red-600 transition-colors" title="Archive"><TrashIcon className="w-5 h-5"/></button>
            </div>
        </div>
    </div>
  );
};

export default ClientListItem;

import React, { useState, useCallback, ChangeEvent } from 'react';
import { XIcon } from './icons/XIcon';
import { UploadIcon, DocumentTextIcon, ExclamationTriangleIcon, CheckCircleIcon, ChevronLeftIcon, ChevronRightIcon } from './icons/DummyIcons';
import { Button } from './ui/Button';

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[];
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
}

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [errors, setErrors] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setParsedData([]);
        setErrors([]);
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const selectedFile = e.target.files[0];
            if (selectedFile.name.endsWith('.csv')) {
                 setFile(selectedFile);
                 setErrors([]);
            } else {
                setErrors(['Strict Format Required: Please upload a standard .csv file.']);
                setFile(null);
            }
        }
    };

    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (char === '"') {
                if (inQuotes && text[i + 1] === '"') {
                    cell += '"';
                    i++;
                } else {
                    inQuotes = !inQuotes;
                }
            } else if (char === ',' && !inQuotes) {
                result.push(cell.trim());
                cell = '';
            } else {
                cell += char;
            }
        }
        result.push(cell.trim());
        return result;
    };

    const processFile = useCallback(() => {
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 1) {
                    setErrors(['File is empty.']);
                    setIsLoading(false);
                    return;
                }

                const headerLine = lines[0].replace(/^\uFEFF/, ''); 
                const fileHeaders = parseCSVLine(headerLine).map(h => h.replace(/^"|"$/g, '').trim());

                // VALIDATION: Structure/Contract check
                if (fileHeaders.length < requiredHeaders.length) {
                    setErrors([`INVALID STRUCTURE: Expected 39 columns in specific order. Found ${fileHeaders.length}.`]);
                    setIsLoading(false);
                    return;
                }

                const localParsed = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);
                    if (values.length === 1 && values[0] === '') continue;

                    const rowData: Record<string, string> = {};
                    // Map by index to ensure strict column order adherence
                    requiredHeaders.forEach((key, idx) => {
                        rowData[key] = values[idx] ? values[idx].replace(/^"|"$/g, '') : '';
                    });
                    localParsed.push(rowData);
                }

                setParsedData(localParsed);
                setStep(3);
            } catch (error) {
                 setErrors(['Internal parser error. Ensure CSV encoding is UTF-8.']);
            } finally {
                setIsLoading(false);
            }
        };
        reader.readAsText(file);
    }, [file, requiredHeaders]);

    const handleConfirmImport = () => {
        setIsLoading(true);
        setTimeout(() => {
            onImport(parsedData);
            setStep(4);
            setIsLoading(false);
        }, 500);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">{wizardTitle}</h2>
                    <button onClick={handleClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"><XIcon className="w-6 h-6" /></button>
                </div>

                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">1. Format Contract</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                This import tool enforces a <span className="font-bold text-red-600">Strict 39-Column Order</span>. Entries with missing mandatory fields will be automatically flagged as "Incomplete".
                            </p>
                            <div className="mt-6 p-4 bg-blue-50 dark:bg-blue-900/20 border-2 border-dashed border-blue-200 dark:border-blue-800 rounded-lg">
                                <h4 className="text-[10px] font-black text-blue-800 dark:text-blue-300 uppercase tracking-widest mb-2">Required Sequence:</h4>
                                <div className="text-[10px] text-blue-700 dark:text-blue-200 font-mono leading-relaxed grid grid-cols-2 md:grid-cols-3 gap-1">
                                    {requiredHeaders.map((h, i) => <div key={h} className="truncate">{i+1}. {h}</div>)}
                                </div>
                            </div>
                        </div>
                   )}
                   {step === 2 && (
                       <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">2. Data Ingestion</h3>
                            <div className="mt-6 flex justify-center px-6 pt-10 pb-10 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md">
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                        <label className="relative cursor-pointer rounded-md font-black text-blue-600 hover:text-blue-500 uppercase tracking-widest">
                                            <span>Select Import File</span>
                                            <input type="file" className="sr-only" onChange={handleFileChange} accept=".csv" />
                                        </label>
                                    </div>
                                    <p className="text-xs text-gray-500 italic">{file ? `Selected: ${file.name}` : "File must be valid .csv format"}</p>
                                </div>
                            </div>
                            {errors.length > 0 && (
                                <div className="mt-4 p-4 bg-red-50 text-red-700 border border-red-200 rounded-lg flex items-start gap-3">
                                    <ExclamationTriangleIcon className="w-5 h-5 shrink-0" />
                                    <div className="text-xs font-bold uppercase tracking-tight">{errors[0]}</div>
                                </div>
                            )}
                        </div>
                   )}
                   {step === 3 && (
                        <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">3. Verify Mapping</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                Ready to ingest <span className="font-bold text-green-600 uppercase">{parsedData.length} records</span>. Mandatory fields missing in rows will be marked for manual completion.
                            </p>
                            <div className="mt-4 border border-gray-200 dark:border-gray-700 rounded-lg overflow-x-auto max-h-80">
                                <table className="w-full text-[10px] text-left">
                                    <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0">
                                        <tr>
                                            <th className="px-4 py-2 font-black uppercase text-gray-500">Row</th>
                                            {requiredHeaders.slice(0, 10).map(h => <th key={h} className="px-4 py-2 font-black uppercase text-gray-500 whitespace-nowrap">{h}</th>)}
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white dark:bg-gray-800 divide-y dark:divide-gray-700">
                                        {parsedData.slice(0, 10).map((row, index) => (
                                            <tr key={index}>
                                                <td className="px-4 py-2 font-bold text-gray-400">{index + 1}</td>
                                                {requiredHeaders.slice(0, 10).map(h => (
                                                    <td key={h} className={`px-4 py-2 truncate max-w-[150px] ${!row[h] ? 'bg-amber-50 dark:bg-amber-900/10 italic text-amber-600' : 'dark:text-gray-300'}`}>
                                                        {row[h] || 'BLANK'}
                                                    </td>
                                                ))}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                   )}
                   {step === 4 && (
                       <div className="text-center py-10 animate-in zoom-in duration-500">
                            <CheckCircleIcon className="mx-auto h-20 w-20 text-green-500" />
                            <h3 className="mt-4 text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Ingestion Finalized</h3>
                            <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">Records added to the master ledger. Status indicators in the client list will highlight incomplete profiles.</p>
                        </div>
                   )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>
                        {step > 1 && step < 4 && (
                            <button onClick={() => setStep(step - 1)} className="flex items-center gap-1 text-xs font-black uppercase tracking-widest text-gray-500 hover:text-gray-800"><ChevronLeftIcon className="w-4 h-4" /> Back</button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        {step < 3 && (
                            <Button onClick={step === 2 ? processFile : () => setStep(step + 1)} disabled={(step === 2 && !file) || isLoading} icon={<ChevronRightIcon className="w-4 h-4" />}>
                                {isLoading ? 'Processing Contract...' : 'Proceed'}
                            </Button>
                        )}
                        {step === 3 && (
                            <Button variant="success" onClick={handleConfirmImport} disabled={parsedData.length === 0 || isLoading} icon={<CheckCircleIcon className="w-4 h-4" />}>
                                Ingest Records
                            </Button>
                        )}
                        {step === 4 && <Button onClick={handleClose}>Return to Database</Button>}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CSVImportWizard;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
    ChevronDownIcon, 
    DocumentPlusIcon, 
    MagnifyingGlassIcon, 
    UploadIcon 
} from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import ClientListItem from '../components/ClientListItem';
import { Client, Milestone, Property, Invoice, ActivityLog } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
