import React, { useState, useCallback, ChangeEvent } from 'react';
import { XIcon } from './icons/XIcon';
import { UploadIcon, DocumentTextIcon, ExclamationTriangleIcon, CheckCircleIcon, ChevronLeftIcon, ChevronRightIcon } from './icons/DummyIcons';
import { Button } from './ui/Button';

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[];
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
}

/**
 * FUZZY LABEL MATCHING LOGIC
 * Maps various common header names to internal system keys.
 */
const HEADER_MAP: Record<string, string[]> = {
    fullName: ['full name', 'client name', 'name', 'primary contact', 'contact'],
    surname: ['surname', 'last name', 'family name'],
    otherNames: ['other names', 'first name', 'given names'],
    phone: ['phone', 'phone number', 'telephone', 'mobile', 'contact number'],
    email: ['email', 'email address', 'mail'],
    location: ['location', 'property location', 'land location', 'site'],
    plot: ['plot', 'plot number', 'plot no', 'partition'],
    totalPrice: ['total', 'price', 'contract sum', 'total cost'],
    paidAmount: ['paid', 'deposit', 'amount paid', 'receipted'],
    salesRep: ['sales rep', 'agent', 'officer', 'representative'],
    witnessName: ['witness', 'witness name'],
    kinName: ['next of kin', 'kin name', 'emergency contact']
};

const findSystemKey = (header: string): string | null => {
    const cleanHeader = header.toLowerCase().trim();
    for (const [key, aliases] of Object.entries(HEADER_MAP)) {
        if (aliases.some(alias => cleanHeader.includes(alias) || alias.includes(cleanHeader))) {
            return key;
        }
    }
    return null;
};

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [unmappedHeaders, setUnmappedHeaders] = useState<string[]>([]);
    const [errors, setErrors] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setParsedData([]);
        setUnmappedHeaders([]);
        setErrors([]);
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (char === '"') {
                if (inQuotes && text[i + 1] === '"') {
                    cell += '"';
                    i++;
                } else {
                    inQuotes = !inQuotes;
                }
            } else if (char === ',' && !inQuotes) {
                result.push(cell.trim());
                cell = '';
            } else {
                cell += char;
            }
        }
        result.push(cell.trim());
        return result;
    };

    const processFile = useCallback(() => {
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 2) {
                    setErrors(['File must contain a header and data rows.']);
                    setIsLoading(false);
                    return;
                }

                const headerLine = lines[0].replace(/^\uFEFF/, ''); 
                const rawHeaders = parseCSVLine(headerLine).map(h => h.replace(/^"|"$/g, '').trim());

                // Map raw headers to system keys
                const mappedKeys: (string | null)[] = rawHeaders.map(findSystemKey);
                const unmapped = rawHeaders.filter((_, i) => !mappedKeys[i]);
                setUnmappedHeaders(unmapped);

                const dataRows = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);
                    const entry: Record<string, any> = {};

                    mappedKeys.forEach((key, index) => {
                        if (key) {
                            entry[key] = values[index] ? values[index].replace(/^"|"$/g, '') : '';
                        }
                    });
                    dataRows.push(entry);
                }

                setParsedData(dataRows);
                setStep(3);
            } catch (error) {
                 setErrors(['Failed to parse file. Ensure it is a valid CSV.']);
            } finally {
                setIsLoading(false);
            }
        };
        reader.readAsText(file);
    }, [file]);

    const handleConfirmImport = () => {
        setIsLoading(true);
        setTimeout(() => {
            onImport(parsedData);
            setStep(4);
            setIsLoading(false);
        }, 300);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">{wizardTitle}</h2>
                    <button onClick={handleClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"><XIcon className="w-6 h-6" /></button>
                </div>

                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">1. Format Recognition</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                This tool automatically maps your CSV headers to system fields. Missing data is acceptable and can be updated later.
                            </p>
                            <div className="mt-6 p-4 bg-blue-50 dark:bg-blue-900/20 border-2 border-dashed border-blue-200 dark:border-blue-800 rounded-lg">
                                <h4 className="text-[10px] font-black text-blue-800 dark:text-blue-300 uppercase tracking-widest mb-2">Supported Mappings:</h4>
                                <div className="grid grid-cols-2 gap-2 text-[10px] text-blue-700 dark:text-blue-200 font-mono">
                                    {Object.entries(HEADER_MAP).map(([key, aliases]) => (
                                        <div key={key} className="truncate"><strong>{key}:</strong> {aliases.join(', ')}</div>
                                    ))}
                                </div>
                            </div>
                            <Button onClick={() => setStep(2)} className="mt-6">Proceed to Upload</Button>
                        </div>
                   )}
                   {step === 2 && (
                       <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">2. Data Ingestion</h3>
                            <div className="mt-6 flex justify-center px-6 pt-10 pb-10 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md">
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                        <label className="relative cursor-pointer rounded-md font-black text-blue-600 hover:text-blue-500 uppercase tracking-widest">
                                            <span>Attach Client CSV</span>
                                            <input type="file" className="sr-only" onChange={(e) => setFile(e.target.files?.[0] || null)} accept=".csv" />
                                        </label>
                                    </div>
                                    <p className="text-xs text-gray-500 italic">{file ? file.name : "System will map headers automatically"}</p>
                                </div>
                            </div>
                            {errors.length > 0 && <div className="mt-4 p-3 bg-red-50 text-red-700 text-xs font-bold rounded border border-red-200">{errors[0]}</div>}
                            <Button onClick={processFile} disabled={!file || isLoading} className="mt-4 w-full">Ingest Data</Button>
                        </div>
                   )}
                   {step === 3 && (
                        <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
                            <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-widest">3. Import Summary</h3>
                            <p className="mt-2 text-sm text-gray-600 dark:text-gray-300">
                                We identified <span className="font-bold text-blue-600">{parsedData.length} records</span>. Mandatory missing fields will be marked "Incomplete".
                            </p>

                            {unmappedHeaders.length > 0 && (
                                <div className="mt-4 p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg">
                                    <h4 className="text-[10px] font-black text-amber-800 dark:text-amber-300 uppercase tracking-widest flex items-center gap-2">
                                        <ExclamationTriangleIcon className="w-4 h-4" /> Unrecognized Columns
                                    </h4>
                                    <p className="text-xs text-amber-700 dark:text-amber-200 mt-1">The following columns were ignored: {unmappedHeaders.join(', ')}</p>
                                </div>
                            )}

                            <div className="mt-4 border border-gray-200 dark:border-gray-700 rounded-lg overflow-x-auto max-h-80">
                                <table className="w-full text-[10px] text-left">
                                    <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0">
                                        <tr>
                                            {Object.keys(parsedData[0] || {}).map(key => <th key={key} className="px-4 py-2 font-black uppercase text-gray-500 whitespace-nowrap">{key}</th>)}
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white dark:bg-gray-800 divide-y dark:divide-gray-700">
                                        {parsedData.slice(0, 10).map((row, index) => (
                                            <tr key={index}>
                                                {Object.values(row).map((val: any, i) => <td key={i} className="px-4 py-2 truncate max-w-[150px] dark:text-gray-300">{val || <span className="italic text-gray-400">blank</span>}</td>)}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                   )}
                   {step === 4 && (
                       <div className="text-center py-10 animate-in zoom-in duration-500">
                            <CheckCircleIcon className="mx-auto h-20 w-20 text-green-500" />
                            <h3 className="mt-4 text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Ingestion Complete</h3>
                            <p className="mt-2 text-sm text-gray-500 dark:text-gray-400">All rows have been added. Visit the client list to fill missing details.</p>
                        </div>
                   )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <Button variant="secondary" onClick={handleClose}>Cancel</Button>
                    <div className="flex gap-3">
                        {step === 3 && (
                            <Button variant="success" onClick={handleConfirmImport} isLoading={isLoading}>Finalize Import</Button>
                        )}
                        {step === 4 && <Button onClick={handleClose}>Return to List</Button>}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CSVImportWizard;

