const DeletePropertyModal: React.FC<{ 
  property: Property | null; 
  onClose: () => void; 
  onConfirm: () => Promise<void> 
}> = ({ property, onClose, onConfirm }) => {
  const { login } = useAuth();
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);

  if (!property) return null;

  const handleAuthConfirm = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsDeleting(true);

    // Deletion interaction logic: Require staff re-auth
    const authResult = await login(process.env.STAFF_EMAIL || '', password);

    if (authResult.success) {
      await onConfirm();
      onClose();
    } else {
      setError('Authorization Failed: Incorrect credentials.');
    }
    setIsDeleting(false);
  };

  return (
    <div className="fixed inset-0 bg-black/80 z-[60] flex justify-center items-center p-4 backdrop-blur-md animate-in zoom-in duration-200">
      <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border border-red-500/30">
        <form onSubmit={handleAuthConfirm}>
          <div className="p-6 text-center bg-red-50 dark:bg-red-900/10 border-b border-red-100 dark:border-red-900/50">
            <div className="w-12 h-12 bg-red-100 dark:bg-red-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
              <TrashIcon className="w-6 h-6 text-red-600" />
            </div>
            <h3 className="text-lg font-black text-red-900 dark:text-red-400 uppercase tracking-tighter">Irreversible Deletion</h3>
            <p className="text-xs text-red-700 dark:text-red-300 mt-1">This will permanently remove <strong>{property.location}</strong> from all catalogs.</p>
          </div>
          <div className="p-6 space-y-4 bg-white dark:bg-gray-800">
            {error && <div className="p-2 text-[10px] font-bold text-red-600 bg-red-50 rounded border border-red-100">{error}</div>}
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Verify Admin Password</label>
              <Input type="password" value={password} onChange={e => setPassword(e.target.value)} required placeholder="••••••••" className="font-mono" />
            </div>
          </div>
          <div className="p-4 bg-gray-50 dark:bg-gray-900 flex gap-2 border-t border-gray-100 dark:border-gray-700">
            <Button type="button" variant="secondary" className="flex-1" onClick={onClose} disabled={isDeleting}>Abort</Button>
            <Button type="submit" variant="danger" className="flex-1" isLoading={isDeleting}>Confirm Delete</Button>
          </div>
        </form>
      </Card>
    </div>
  );
};

