                                <div className="h-full flex flex-col items-center justify-center text-gray-400 p-10 text-center">
                                    <div className="w-20 h-20 bg-gray-50 dark:bg-gray-900/50 rounded-full flex items-center justify-center mb-4">
                                        <EnvelopeIcon className="w-10 h-10 opacity-20" />
                                    </div>
                                    <p className="text-lg font-black uppercase tracking-tighter">Workspace Idle</p>
                                    <p className="text-xs max-w-xs mt-1">Select a message from the list to begin reading or manage your folder.</p>
                                </div>
                            )}
                        </div>
                    </>
                )}
            </div>

            {/* Compose Modal */}
            <MessageComposeModal 
                isOpen={isComposeOpen}
                onClose={() => setComposeOpen(false)}
                staff={staff}
                roles={roles}
                onSend={handleSend}
            />

            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 4px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #475569; }
            `}</style>
        </div>
    );
};

const MessageComposeModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    staff: Staff[];
    roles: Role[];
    onSend: (data: any) => void;
}> = ({ isOpen, onClose, staff, roles, onSend }) => {
    const [targetType, setTargetType] = useState<'individual' | 'group'>('individual');
    const [recipientIds, setRecipientIds] = useState<string[]>([]);
    const [groupIds, setGroupIds] = useState<string[]>([]);
    const [subject, setSubject] = useState('');
    const [body, setBody] = useState('');
    const [pendingFiles, setPendingFiles] = useState<File[]>([]);
    const [isProcessing, setIsProcessing] = useState(false);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsProcessing(true);
        try {
            const attachmentData = await Promise.all(
                pendingFiles.map(async (file) => {
                    const url = await uploadFile(file, `internal_mail/tmp/${Date.now()}_${file.name}`);
                    return { name: file.name, url, size: file.size };
                })
            );

            // Resolve recipients if group is selected
            let finalRecipientIds = [...recipientIds];
            if (targetType === 'group') {
                if (groupIds.includes('ALL_STAFF')) {
                    finalRecipientIds = staff.map(s => s.id);
                } else {
                    finalRecipientIds = staff.filter(s => groupIds.includes(s.roleId)).map(s => s.id);
                }
            }

            onSend({ recipientIds: finalRecipientIds, groupIds, subject, body, attachments: attachmentData });
        } finally {
            setIsProcessing(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-3xl p-0 overflow-hidden shadow-2xl flex flex-col max-h-[85vh]">
                <form onSubmit={handleSubmit} className="flex flex-col h-full overflow-hidden">
                    <div className="p-5 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900 shrink-0">
                        <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">Draft Correspondence</h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    <div className="p-6 space-y-5 overflow-y-auto scrollbar-thin flex-grow bg-white dark:bg-gray-800">
                        <div className="flex gap-4 border-b border-gray-100 dark:border-gray-700 pb-4">
                            <button type="button" onClick={() => setTargetType('individual')} className={`text-xs font-black uppercase tracking-widest pb-1 ${targetType === 'individual' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-400'}`}>To Individual</button>
                            <button type="button" onClick={() => setTargetType('group')} className={`text-xs font-black uppercase tracking-widest pb-1 ${targetType === 'group' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-400'}`}>To Group</button>
                        </div>

                        {targetType === 'individual' ? (
                            <div className="space-y-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Select Recipients*</label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl text-sm min-h-[100px] focus:ring-2 focus:ring-blue-500"
                                    value={recipientIds}
                                    onChange={(e) => setRecipientIds(Array.from(e.target.selectedOptions).map(o => (o as HTMLOptionElement).value))}
                                    required
                                >
                                    {staff.map(s => <option key={s.id} value={s.id}>{s.fullName} ({s.email})</option>)}
                                </select>
                            </div>
                        ) : (
                            <div className="space-y-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Select User Groups*</label>
                                <select 
                                    multiple 
                                    className="w-full p-2 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl text-sm min-h-[100px] focus:ring-2 focus:ring-blue-500"
                                    value={groupIds}
                                    onChange={(e) => setGroupIds(Array.from(e.target.selectedOptions).map(o => (o as HTMLOptionElement).value))}
                                    required
                                >
                                    <option value="ALL_STAFF">ALL STAFF</option>
                                    {roles.map(r => <option key={r.id} value={r.id}>DEPT: {r.name.toUpperCase()}</option>)}
                                </select>
                            </div>
                        )}

                        <Input label="Subject Line*" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Main purpose of message..." required />

                        <div className="space-y-1">
                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Message Body* (Rich Text Supported)</label>
                            <textarea 
                                value={body} 
                                onChange={e => setBody(e.target.value)} 
                                rows={10} 
                                className="w-full p-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl text-sm focus:ring-2 focus:ring-blue-500"
                                placeholder="Type your internal message here..."
                                required 
                            />
                        </div>

                        <div className="p-4 bg-gray-50 dark:bg-gray-900/50 rounded-xl border border-gray-100 dark:border-gray-700">
                            <p className="text-[10px] font-black text-gray-400 uppercase mb-3 tracking-widest">Internal Attachments</p>
                            <div className="flex flex-wrap gap-2 mb-4">
                                {pendingFiles.map((f, i) => (
                                    <Badge key={i} variant="info" className="flex items-center gap-2 font-bold px-3 py-1.5">
                                        <span className="truncate max-w-[150px]">{f.name}</span>
                                        <button type="button" onClick={() => setPendingFiles(prev => prev.filter((_, idx) => idx !== i))} className="hover:text-red-500"><XMarkIcon className="w-3.5 h-3.5" /></button>
                                    </Badge>
                                ))}
                            </div>
                            <label className="inline-flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-lg text-xs font-black uppercase tracking-widest cursor-pointer hover:bg-gray-100 border border-gray-200 dark:border-gray-700 shadow-sm transition-all">
                                <PaperClipIcon className="w-4 h-4 text-blue-600" /> Add Resource
                                <input type="file" multiple className="sr-only" onChange={e => e.target.files && setPendingFiles(prev => [...prev, ...Array.from(e.target.files!)])} />
                            </label>
                        </div>
                    </div>

                    <div className="p-5 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3 shrink-0">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="button" variant="secondary" onClick={() => { /* Mock Draft Logic */ onClose(); }}>Save as Draft</Button>
                        <Button type="submit" isLoading={isProcessing} icon={<PaperAirplaneIcon className="w-5 h-5 -rotate-45" />}>Send Now</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export default MailingPage;

import React, { useState, useMemo, useEffect } from 'react';
import { LeaveRequest, LeaveType, LeaveStatus } from '../../types';
import { 
    PlusCircleIcon, 
    EyeIcon, 
    CheckCircleIcon, 
    XMarkIcon,
    CalendarDaysIcon,
    DocumentTextIcon,
    PaperClipIcon,
    ArrowDownTrayIcon,
    UserCircleIcon,
    ClockIcon
} from '../../components/icons/DummyIcons';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../../components/ui/Table';
import { useAuth } from '../../context/AuthContext';
import { useActivityLogs, useStaff, useRoles } from '../../hooks/useAppData';
import { uploadFile } from '../../services/storageService';

const LeavePage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    // UI States
    const [isRequestModalOpen, setRequestModalOpen] = useState(false);
    const [viewingRequest, setViewingRequest] = useState<LeaveRequest | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Mock Data Persistence (In production, this would be managed by a useLeave hook connected to Firestore)
    const [requests, setRequests] = useState<LeaveRequest[]>([
        {
            id: 'LR-101',
            employeeId: '1',
            employeeName: 'Araba CEO',
            type: 'Annual Leave',
            startDate: '2024-12-20',
            endDate: '2024-12-27',
            days: 5,
            reason: 'End of year family vacation.',
            status: 'Approved',
            requestDate: '2024-11-01',
            processedBy: 'System',
            processedDate: '2024-11-02'
        }
    ]);

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff?.roleId)?.name, [roles, currentStaff]);
    const isAdmin = userRole === 'CEO' || userRole === 'Administrator';

    const filteredRequests = useMemo(() => {
        if (isAdmin) return requests.sort((a, b) => new Date(b.requestDate).getTime() - new Date(a.requestDate).getTime());
        return requests.filter(r => r.employeeId === currentStaff?.id).sort((a, b) => new Date(b.requestDate).getTime() - new Date(a.requestDate).getTime());
    }, [requests, isAdmin, currentStaff]);

    const handleCreateRequest = async (data: any) => {
        setIsSubmitting(true);
        try {
            let attachmentUrl = '';
            if (data.file) {
                attachmentUrl = await uploadFile(data.file, `leave_requests/${currentStaff?.id}/${Date.now()}_${data.file.name}`);
            }

            const newRequest: LeaveRequest = {
                id: `LR-${Math.floor(Math.random() * 10000)}`,
                employeeId: currentStaff?.id || '0',
                employeeName: currentStaff?.fullName || 'Unknown',
                type: data.type as LeaveType,
                startDate: data.startDate,
                endDate: data.endDate,
                days: data.days,
                reason: data.reason,
                status: 'Pending',
                attachmentUrl,
                requestDate: new Date().toISOString().split('T')[0],
            };

            setRequests(prev => [newRequest, ...prev]);
            // FIX: Added currentStaff.id as the required third argument for addActivityLog
            if (currentStaff) {
                addActivityLog('Create', `Submitted a ${newRequest.type} request for ${newRequest.days} days.`, currentStaff.id);
            }
            setRequestModalOpen(false);
        } catch (error) {
            alert('Failed to submit request. Please try again.');
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleProcessRequest = (id: string, newStatus: LeaveStatus) => {
        setRequests(prev => prev.map(r => 
            r.id === id ? { 
                ...r, 
                status: newStatus, 
                processedBy: currentStaff?.fullName, 
                processedDate: new Date().toISOString().split('T')[0] 
            } : r
        ));
        // FIX: Added currentStaff.id as the required third argument for addActivityLog
        if (currentStaff) {
            addActivityLog('Update', `${newStatus} leave request ${id}.`, currentStaff.id);
        }
        setViewingRequest(null);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Leave Management</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">
                        {isAdmin ? 'Review and manage company-wide leave requests.' : 'Submit and track your leave applications.'}
                    </p>
                </div>
                <Button onClick={() => setRequestModalOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                    Request Leave
                </Button>
            </div>

            <Card className="p-0 overflow-hidden">
                <TableContainer className="border-0 shadow-none">
                    <table className="w-full text-sm text-left">
                        <Thead>
                            <tr>
                                <Th>Employee</Th>
                                <Th>Leave Type</Th>
                                <Th>Duration</Th>
                                <Th>Days</Th>
                                <Th className="text-center">Status</Th>
                                <Th className="text-right">Actions</Th>
                            </tr>
                        </Thead>
                        <Tbody>
                            {filteredRequests.map(req => (
                                <Tr key={req.id}>
                                    <Td className="font-bold text-gray-900 dark:text-white">
                                        <div className="flex items-center gap-2">
                                            <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center text-blue-600 text-[10px]">
                                                {req.employeeName.substring(0,2).toUpperCase()}
                                            </div>
                                            {req.employeeName}
                                        </div>
                                    </Td>
                                    <Td>{req.type}</Td>
                                    <Td className="text-gray-500">
                                        <div className="flex flex-col">
                                            <span>{req.startDate}</span>
                                            <span className="text-[10px] text-gray-400 font-bold uppercase">to {req.endDate}</span>
                                        </div>
                                    </Td>
                                    <Td className="font-semibold">{req.days} days</Td>
                                    <Td className="text-center">
                                        <Badge variant={req.status === 'Approved' ? 'success' : req.status === 'Rejected' ? 'danger' : 'warning'}>
                                            {req.status}
                                        </Badge>
                                    </Td>
                                    <Td className="text-right">
                                        <button 
                                            onClick={() => setViewingRequest(req)}
                                            className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                                            title="View Details"
                                        >
                                            <EyeIcon className="w-5 h-5" />
                                        </button>
                                    </Td>
                                </Tr>
                            ))}
                            {filteredRequests.length === 0 && (
                                <Tr>
                                    <Td colSpan={6} className="py-20 text-center text-gray-400 italic">
                                        No leave requests found.
                                    </Td>
                                </Tr>
                            )}
                        </Tbody>
                    </table>
                </TableContainer>
            </Card>

            <RequestModal 
                isOpen={isRequestModalOpen} 
                onClose={() => setRequestModalOpen(false)} 
                onSubmit={handleCreateRequest}
                loading={isSubmitting}
            />

            <DetailModal 
                request={viewingRequest} 
                onClose={() => setViewingRequest(null)} 
                isAdmin={isAdmin}
                onAction={handleProcessRequest}
            />
        </div>
    );
};

const RequestModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    loading: boolean;
}> = ({ isOpen, onClose, onSubmit, loading }) => {
    const [formData, setFormData] = useState({
        type: 'Annual Leave',
        startDate: '',
        endDate: '',
        days: 0,
        reason: '',
        file: null as File | null
    });

    useEffect(() => {
        if (formData.startDate && formData.endDate) {
            const start = new Date(formData.startDate);
            const end = new Date(formData.endDate);
            const diffTime = Math.abs(end.getTime() - start.getTime());
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
            setFormData(prev => ({ ...prev, days: diffDays > 0 ? diffDays : 0 }));
        }
    }, [formData.startDate, formData.endDate]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-xl p-0 overflow-hidden shadow-2xl animate-in zoom-in duration-200 flex flex-col max-h-[80vh]">
                <form onSubmit={(e) => { e.preventDefault(); onSubmit(formData); }} className="flex flex-col h-full overflow-hidden">
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900 shrink-0">
                        <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            <CalendarDaysIcon className="w-5 h-5 text-blue-600" /> Application for Leave
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    {/* Scrollable Container */}
                    <div className="p-6 space-y-4 overflow-y-auto scrollbar-thin">
                        <Select label="Leave Type*" value={formData.type} onChange={e => setFormData({...formData, type: e.target.value})} required>
                            <option>Annual Leave</option>
                            <option>Sick Leave</option>
                            <option>Casual Leave</option>
                            <option>Emergency Leave</option>
                            <option>Other</option>
                        </Select>
                        <div className="grid grid-cols-2 gap-4">
                            <Input label="Start Date*" type="date" value={formData.startDate} onChange={e => setFormData({...formData, startDate: e.target.value})} required />
                            <Input label="End Date*" type="date" value={formData.endDate} onChange={e => setFormData({...formData, endDate: e.target.value})} required />
                        </div>
                        <Input label="Total Days" type="number" value={formData.days} readOnly className="bg-gray-50 font-bold text-blue-600" />
                        <Textarea label="Reason for Leave*" rows={4} value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} required placeholder="Provide context for your application..." />

                        <div className="pt-2">
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Supporting Document (Optional)</label>
                            <div className="flex items-center justify-center w-full">
                                <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-gray-300 border-dashed rounded-lg cursor-pointer bg-gray-50 dark:bg-gray-900 hover:bg-gray-100 dark:border-gray-600 dark:hover:bg-gray-800 transition-colors">
                                    <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                        <PaperClipIcon className="w-8 h-8 mb-3 text-gray-400" />
                                        <p className="mb-2 text-sm text-gray-500 dark:text-gray-400 font-semibold">{formData.file ? formData.file.name : 'Click to upload attachment'}</p>
                                        <p className="text-xs text-gray-500 dark:text-gray-400">PDF, PNG, JPG (MAX. 5MB)</p>
                                    </div>
                                    <input type="file" className="hidden" onChange={e => setFormData({...formData, file: e.target.files?.[0] || null})} />
                                </label>
                            </div>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3 shrink-0">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit" isLoading={loading}>Submit Application</Button>
                    </div>
                </form>
            </Card>
            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 6px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #334155; }
            `}</style>
        </div>
    );
};

const DetailModal: React.FC<{
    request: LeaveRequest | null;
    onClose: () => void;
