import React, { useState, useMemo } from 'react';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { 
    CalendarDaysIcon, 
    PlusCircleIcon, 
    MapPinIcon, 
    ClockIcon, 
    XMarkIcon,
    CheckCircleIcon,
    UserCircleIcon
} from '../../components/icons/DummyIcons';
import { useAuth } from '../../context/AuthContext';
import { useActivityLogs, useRoles } from '../../hooks/useAppData';

interface InternalEvent {
    id: string;
    title: string;
    dateTime: string;
    location: string;
    description: string;
    createdBy: string;
    rsvps: Record<string, 'Yes' | 'No'>;
}

const EventsPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    const [events, setEvents] = useState<InternalEvent[]>([
        {
            id: 'evt-1',
            title: 'Q4 Strategy Meeting',
            dateTime: '2024-12-01T10:00',
            location: 'Conference Room A',
            description: 'Discussing goals and budgets for the upcoming year.',
            createdBy: 'Araba CEO',
            rsvps: { '1': 'Yes' }
        }
    ]);

    const [isModalOpen, setModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const userRole = roles.find(r => r.id === currentStaff?.roleId)?.name;
    const canCreate = userRole === 'CEO' || userRole === 'Administrator';

    const { upcoming, past } = useMemo(() => {
        const now = new Date();
        const sorted = [...events].sort((a, b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime());
        return {
            upcoming: sorted.filter(e => new Date(e.dateTime) >= now),
            past: sorted.filter(e => new Date(e.dateTime) < now).reverse()
        };
    }, [events]);

    const handleCreateEvent = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSaving(true);
        const formData = new FormData(e.currentTarget);

        const newEvent: InternalEvent = {
            id: `EVT-${Date.now()}`,
            title: formData.get('title') as string,
            dateTime: formData.get('dateTime') as string,
            location: formData.get('location') as string,
            description: formData.get('description') as string,
            createdBy: currentStaff?.fullName || 'System',
            rsvps: {}
        };

        setEvents(prev => [...prev, newEvent]);
        // FIX: Added currentStaff.id as the required third argument for addActivityLog
        if (currentStaff) {
            addActivityLog('Create', `Created internal event: ${newEvent.title}`, currentStaff.id);
        }
        setModalOpen(false);
        setIsSaving(false);
    };

    const handleRSVP = (eventId: string, status: 'Yes' | 'No') => {
        setEvents(prev => prev.map(e => {
            if (e.id === eventId) {
                return { ...e, rsvps: { ...e.rsvps, [currentStaff?.id || '']: status } };
            }
            return e;
        }));
    };

    // Typed as React.FC to ensure key is handled correctly as a reserved React prop
    const EventCard: React.FC<{ event: InternalEvent; isPast?: boolean }> = ({ event, isPast }) => (
        <Card className={`overflow-hidden border-l-4 ${isPast ? 'border-l-gray-400 grayscale' : 'border-l-blue-600 shadow-md'}`}>
            <div className="flex flex-col md:flex-row justify-between gap-4">
                <div className="space-y-3">
                    <h3 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">{event.title}</h3>
                    <div className="flex flex-wrap gap-4 text-xs font-bold text-gray-500 uppercase tracking-widest">
                        <span className="flex items-center gap-1.5"><ClockIcon className="w-4 h-4 text-blue-500" /> {new Date(event.dateTime).toLocaleString()}</span>
                        <span className="flex items-center gap-1.5"><MapPinIcon className="w-4 h-4 text-blue-500" /> {event.location}</span>
                        <span className="flex items-center gap-1.5"><UserCircleIcon className="w-4 h-4 text-blue-500" /> Host: {event.createdBy}</span>
                    </div>
                    <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed">{event.description}</p>
                </div>
                {!isPast && (
                    <div className="flex flex-col items-center justify-center gap-2 bg-gray-50 dark:bg-gray-900/50 p-4 rounded-xl border border-gray-100 dark:border-gray-800 min-w-[120px]">
                        <p className="text-[10px] font-black text-gray-400 uppercase mb-2">Going?</p>
                        <div className="flex gap-2">
                            <button 
                                onClick={() => handleRSVP(event.id, 'Yes')}
                                className={`p-2 rounded-lg transition-all ${event.rsvps[currentStaff?.id || ''] === 'Yes' ? 'bg-green-600 text-white shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-400 border border-gray-200 hover:border-green-500'}`}
                            >
                                <CheckCircleIcon className="w-6 h-6" />
                            </button>
                            <button 
                                onClick={() => handleRSVP(event.id, 'No')}
                                className={`p-2 rounded-lg transition-all ${event.rsvps[currentStaff?.id || ''] === 'No' ? 'bg-red-600 text-white shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-400 border border-gray-200 hover:border-red-500'}`}
                            >
                                <XMarkIcon className="w-6 h-6" />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </Card>
    );

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Company Events</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Calendar coordination and team gatherings.</p>
                </div>
                {canCreate && (
                    <Button onClick={() => setModalOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                        Create Event
                    </Button>
                )}
            </div>

            <div className="space-y-8">
                <section>
                    <h2 className="text-xs font-black text-blue-600 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <CalendarDaysIcon className="w-4 h-4" /> Upcoming Events
                    </h2>
                    {upcoming.length === 0 ? (
                        <div className="py-20 text-center border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-3xl opacity-40">
                            <CalendarDaysIcon className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                            <p className="text-lg font-bold text-gray-400">No upcoming events scheduled</p>
                        </div>
                    ) : (
                        <div className="grid gap-6">{upcoming.map(e => <EventCard key={e.id} event={e} />)}</div>
                    )}
                </section>

                {past.length > 0 && (
                    <section>
                        <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Past Events</h2>
                        <div className="grid gap-4 opacity-70">{past.map(e => <EventCard key={e.id} event={e} isPast />)}</div>
                    </section>
                )}
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
                    <Card className="w-full max-w-xl p-0 overflow-hidden shadow-2xl border border-blue-500/30 flex flex-col max-h-[80vh]">
                        <form onSubmit={handleCreateEvent} className="flex flex-col h-full overflow-hidden">
                            <div className="p-5 border-b border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center flex-shrink-0">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">New Company Event</h3>
                                <button type="button" onClick={() => setModalOpen(false)} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                            </div>

                            {/* Scrollable Container */}
                            <div className="p-6 space-y-4 overflow-y-auto scrollbar-thin">
                                <Input label="Event Title*" name="title" required placeholder="e.g. End of Year Awards" />
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                    <Input label="Date & Time*" name="dateTime" type="datetime-local" required />
                                    <Input label="Location" name="location" placeholder="e.g. Accra Office Lounge" />
                                </div>
                                <Textarea label="Event Description" name="description" rows={6} placeholder="What should attendees know?" />

                                {/* Placeholder for potential future sections like attachments or guest list to ensure scrolling is validated */}
                                <div className="pt-2">
                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Visibility</p>
                                    <Badge variant="info">Internal Staff Only</Badge>
                                </div>
                            </div>

                            <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800 flex justify-end gap-3 flex-shrink-0">
                                <Button type="button" variant="secondary" onClick={() => setModalOpen(false)}>Cancel</Button>
                                <Button type="submit" isLoading={isSaving}>Publish Event</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 6px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #334155; }
            `}</style>
        </div>
    );
};

export default EventsPage;

import React, { useState, useMemo } from 'react';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input, Textarea } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { 
    MegaphoneIcon, 
    PlusCircleIcon, 
    ClockIcon, 
    UserCircleIcon,
    XMarkIcon,
    PaperClipIcon,
    ArrowDownTrayIcon
} from '../../components/icons/DummyIcons';
import { useAuth } from '../../context/AuthContext';
import { useActivityLogs, useRoles } from '../../hooks/useAppData';
import { uploadFile } from '../../services/storageService';

interface Announcement {
    id: string;
    title: string;
    body: string;
    author: string;
    date: string;
    attachmentUrl?: string;
    readBy: string[];
}

const AnnouncementsPage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    const [announcements, setAnnouncements] = useState<Announcement[]>([
        {
            id: 'ann-1',
            title: 'New Client Referral Bonus Program',
            body: 'Effective immediately, staff members are entitled to a 5% bonus on all successful land sale referrals. Documentation is attached.',
            author: 'Araba CEO',
            date: new Date(Date.now() - 86400000).toISOString(),
            attachmentUrl: '#',
            readBy: []
        }
    ]);

    const [isModalOpen, setModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [pendingFile, setPendingFile] = useState<File | null>(null);

    const userRole = roles.find(r => r.id === currentStaff?.roleId)?.name;
    const canPost = userRole === 'CEO' || userRole === 'Administrator';

    const sortedAnnouncements = useMemo(() => 
        [...announcements].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    , [announcements]);

    const handleMarkAsRead = (id: string) => {
        if (!currentStaff) return;
        setAnnouncements(prev => prev.map(a => {
            if (a.id === id && !a.readBy.includes(currentStaff.id)) {
                return { ...a, readBy: [...a.readBy, currentStaff.id] };
            }
            return a;
        }));
    };

    const handleCreateAnnouncement = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSaving(true);
        const formData = new FormData(e.currentTarget);

        try {
            let fileUrl = '';
            if (pendingFile) {
                fileUrl = await uploadFile(pendingFile, `announcements/${Date.now()}_${pendingFile.name}`);
            }

            const newAnn: Announcement = {
                id: `ANN-${Date.now()}`,
                title: formData.get('title') as string,
                body: formData.get('body') as string,
                author: currentStaff?.fullName || 'Management',
                date: new Date().toISOString(),
                attachmentUrl: fileUrl,
                readBy: [currentStaff?.id || '']
            };

            setAnnouncements(prev => [newAnn, ...prev]);
            // FIX: Added currentStaff.id as the required third argument for addActivityLog
            if (currentStaff) {
                addActivityLog('Create', `Posted announcement: ${newAnn.title}`, currentStaff.id);
            }
            setModalOpen(false);
            setPendingFile(null);
        } catch (error) {
            alert('Failed to post announcement.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Internal Announcements</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Official company notices and team updates.</p>
                </div>
                {canPost && (
                    <Button onClick={() => setModalOpen(true)} icon={<PlusCircleIcon className="w-5 h-5" />}>
                        Post Announcement
                    </Button>
                )}
            </div>

            <div className="space-y-6">
                {sortedAnnouncements.length === 0 ? (
                    <div className="py-32 text-center bg-white dark:bg-gray-800 rounded-3xl border border-gray-200 dark:border-gray-700 opacity-40">
                        <MegaphoneIcon className="w-20 h-20 mx-auto mb-6 text-gray-300" />
                        <p className="text-xl font-bold text-gray-400">No active announcements</p>
                    </div>
                ) : (
                    sortedAnnouncements.map(ann => {
                        const isUnread = !ann.readBy.includes(currentStaff?.id || '');
                        return (
                            <Card 
                                key={ann.id} 
                                onMouseEnter={() => isUnread && handleMarkAsRead(ann.id)}
                                className={`transition-all ${isUnread ? 'ring-2 ring-blue-600/50 shadow-lg' : ''}`}
                            >
                                <div className="flex justify-between items-start mb-4">
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-2">
                                            {isUnread && <div className="w-2.5 h-2.5 rounded-full bg-blue-600 animate-pulse" />}
                                            <h3 className="text-xl font-black text-gray-900 dark:text-white leading-tight uppercase tracking-tighter">{ann.title}</h3>
                                        </div>
                                        <div className="flex items-center gap-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                            <span className="flex items-center gap-1"><UserCircleIcon className="w-3 h-3 text-blue-500" /> {ann.author}</span>
                                            <span className="flex items-center gap-1"><ClockIcon className="w-3 h-3 text-blue-500" /> {new Date(ann.date).toLocaleString()}</span>
                                        </div>
                                    </div>
                                    <Badge variant={isUnread ? 'info' : 'neutral'}>{isUnread ? 'NEW' : 'READ'}</Badge>
                                </div>
                                <div className="prose prose-sm max-w-none dark:prose-invert text-gray-700 dark:text-gray-300 whitespace-pre-wrap mb-6 leading-relaxed">
                                    {ann.body}
                                </div>
                                {ann.attachmentUrl && (
                                    <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <a 
                                            href={ann.attachmentUrl} 
                                            className="inline-flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-lg text-xs font-bold hover:bg-blue-100 transition-colors"
                                            target="_blank"
                                            rel="noopener noreferrer"
                                        >
                                            <PaperClipIcon className="w-4 h-4" /> View Attachment <ArrowDownTrayIcon className="w-3 h-3" />
                                        </a>
                                    </div>
                                )}
                            </Card>
                        );
                    })
                )}
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 bg-slate-950/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
                    <Card className="w-full max-w-2xl p-0 overflow-hidden shadow-2xl border border-indigo-500/30 flex flex-col max-h-[85vh]">
                        <form onSubmit={handleCreateAnnouncement} className="flex flex-col h-full overflow-hidden">
                            <div className="p-5 border-b border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex justify-between items-center shrink-0">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">New Company Notice</h3>
                                <button type="button" onClick={() => setModalOpen(false)} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                            </div>

                            {/* Scrollable Container */}
                            <div className="p-6 space-y-4 overflow-y-auto scrollbar-thin flex-grow">
                                <Input label="Announcement Title*" name="title" required placeholder="e.g. Policy Update regarding Plot Allocations" />
                                <Textarea label="Message Body*" name="body" required rows={10} placeholder="Type your announcement content here..." />
                                <div>
                                    <label className="block text-xs font-black text-gray-400 uppercase mb-2">Optional Attachment</label>
                                    <label className="flex items-center gap-3 p-3 bg-white dark:bg-gray-800 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-xl cursor-pointer hover:border-indigo-400 transition-colors">
                                        <PaperClipIcon className="w-6 h-6 text-gray-400" />
                                        <span className="text-sm font-bold text-gray-500">{pendingFile ? pendingFile.name : 'Select file (PDF/IMG)'}</span>
                                        <input type="file" className="sr-only" onChange={e => setPendingFile(e.target.files?.[0] || null)} />
                                    </label>
                                </div>
                            </div>

                            <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800 flex justify-end gap-3 shrink-0">
                                <Button type="button" variant="secondary" onClick={() => setModalOpen(false)}>Cancel</Button>
                                <Button type="submit" isLoading={isSaving} icon={<MegaphoneIcon className="w-5 h-5" />}>Post to Board</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 6px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #334155; }
            `}</style>
        </div>
    );
};

export default AnnouncementsPage;

import { useQuery, useMutation, useQueryClient, useInfiniteQuery } from '@tanstack/react-query';
import * as dbService from '../services/dbService';
import { auth } from '../services/firebase';
import { 
    Client, Property, Invoice, Staff, Lead, Promotion, 
    ActivityLog, Role, AmendmentRequest, CompanySettings 
} from '../types';
import React, { useState } from 'react';

// --- Clients ---
export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const {
        data,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
        isLoading
    } = useInfiniteQuery({
        queryKey: ['clients', searchTerm],
        queryFn: ({ pageParam }) => 
            searchTerm 
                ? dbService.searchClients(searchTerm).then(data => ({ data, lastDoc: null }))
                : dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc,
        enabled: isAuthenticated,
    });

    const clients = data?.pages.flatMap(page => page.data) || [];

    const saveClientMutation = useMutation({
        mutationFn: dbService.persistClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
