import React, { useState, useMemo, useEffect } from 'react';
import { Staff, Role } from '../../types';
import { 
    MagnifyingGlassIcon, 
    PlusCircleIcon, 
    TrashIcon, 
    InboxArrowDownIcon, 
    PaperAirplaneIcon, 
    UserCircleIcon,
    EnvelopeIcon,
    PaperClipIcon,
    ArrowDownTrayIcon,
