                                                <div className="text-xs text-gray-400 truncate mt-1">{mail.body.substring(0, 50)}...</div>
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        </div>

                        {/* Content Pane */}
                        <div className={`flex-grow flex flex-col bg-white dark:bg-gray-800 ${isMobileListOpen ? 'hidden md:flex' : 'flex'}`}>
                            {selectedMail ? (
                                <div className="flex flex-col h-full overflow-hidden animate-in fade-in slide-in-from-right-4 duration-300">
                                    <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center shrink-0">
                                        <div className="flex items-center gap-3">
                                            <button onClick={() => setMobileListOpen(true)} className="md:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-full"><ArrowLeftIcon className="w-5 h-5" /></button>
                                            <div className="w-10 h-10 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold uppercase">{selectedMail.senderName.substring(0,2)}</div>
                                            <div>
                                                <h3 className="font-bold text-gray-900 dark:text-white">{selectedMail.senderName}</h3>
                                                <p className="text-[10px] text-gray-500 uppercase font-black tracking-tighter">{new Date(selectedMail.timestamp).toLocaleString()}</p>
                                            </div>
                                        </div>
                                        <div className="flex gap-2">
                                            {activeFolder === 'trash' ? (
                                                <>
