                    <div className="flex items-center justify-between">
                        <div className="flex items-center">
                            <input id="remember-me" name="remember-me" type="checkbox" className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700" />
                            <label htmlFor="remember-me" className="ml-2 block text-sm text-gray-900 dark:text-gray-300">Remember me</label>
                        </div>
                        <div className="text-sm">
                            <a href="#" className="font-medium text-blue-600 hover:text-blue-500 dark:text-blue-400 dark:hover:text-blue-300">Forgot your password?</a>
                        </div>
                    </div>

                    <div>
                        <button
                            type="submit"
                            disabled={loading}
                            className="group relative w-full flex justify-center py-2.5 px-4 border border-transparent text-sm font-bold rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-400 dark:disabled:bg-blue-800 transition-all shadow-md active:scale-[0.98]"
                        >
                            {loading ? (
                                <span className="flex items-center gap-2">
                                    <LoaderIcon className="w-4 h-4 animate-spin" /> Authenticating...
                                </span>
                            ) : (
                                "Sign In to FAIM"
                            )}
                        </button>
                    </div>
                </form>

                <div className="pt-4 border-t border-gray-100 dark:border-gray-700 text-center">
                    <p className="text-xs text-gray-400">Authorized Personnel Only. Logins are monitored.</p>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;

import React, { useState, useEffect, ChangeEvent, FormEvent } from 'react';
import { Property, VendorLandPurchase, Payee } from '../types';
import { ArrowLeftIcon, CheckCircleIcon, PlusCircleIcon, TrashIcon, UploadIcon, BanknotesIcon } from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Input, Select, Textarea } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { uploadFile } from '../services/storageService';

interface LandPurchaseFormPageProps {
  onBack: () => void;
  properties: Property[];
  onSaveProperty: (property: Property) => Promise<void>;
}

const FileUploadField: React.FC<{ id: string; label: string; file: File | null | undefined; onChange: (e: ChangeEvent<HTMLInputElement>) => void; accept: string; }> = ({ id, label, file, onChange, accept }) => (
