};

export default LandPurchaseFormPage;

import React, { useState, useMemo, useEffect } from 'react';
import { Property, Staff, PriceHistory, PlotInventory, PlotSize } from '../types';
import { 
    ArrowLeftIcon, 
    BanknotesIcon, 
    ChartBarIcon, 
    ClockIcon, 
    BuildingLibraryIcon, 
    ArrowTrendingUpIcon,
    HashtagIcon,
    ExclamationTriangleIcon,
    InformationCircleIcon,
    PlusCircleIcon,
    TrashIcon,
    MapIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Input, Select } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';

interface PurchaseSaleManagementPageProps {
    onBack: () => void;
    properties: Property[];
    onSaveProperty: (property: Property) => Promise<void>;
    currentStaff: Staff;
}

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

const PurchaseSaleManagementPage: React.FC<PurchaseSaleManagementPageProps> = ({ onBack, properties, onSaveProperty, currentStaff }) => {
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [editSellingPrice, setEditSellingPrice] = useState<string>('');
    const [plotPrefix, setPlotPrefix] = useState<string>('');
    const [prefixError, setPrefixError] = useState<string>('');
    const [isSaving, setIsSaving] = useState(false);

    // Inventory state for Plot Partitioning
    const [inventory, setInventory] = useState<(PlotInventory & { zone?: string })[]>([]);

    const selectedProperty = useMemo(() => 
        properties.find(p => p.id === selectedPropertyId), 
    [selectedPropertyId, properties]);

    // Initial state setup when property changes
    useEffect(() => {
        if (selectedProperty) {
            setEditSellingPrice(selectedProperty.price.toString());
            setPlotPrefix((selectedProperty as any).plotPrefix || '');
            // Clone inventory from property
            setInventory(selectedProperty.inventory.map(inv => ({ ...inv })));
        } else {
            setEditSellingPrice('');
            setPlotPrefix('');
            setInventory([]);
        }
        setPrefixError('');
    }, [selectedProperty]);

    // Inventory Handlers
    const addInventoryRow = () => {
        setInventory(prev => [...prev, { size: '70x100 ft', count: 0, sold: 0, zone: '' }]);
    };

    const removeInventoryRow = (index: number) => {
        setInventory(prev => prev.filter((_, i) => i !== index));
    };

    const updateInventoryItem = (index: number, field: string, value: any) => {
        setInventory(prev => {
            const next = [...prev];
            next[index] = { ...next[index], [field]: value };
            return next;
        });
    };

    // Validation for Prefix
    const validatePrefix = (val: string) => {
        const regex = /^[a-zA-Z0-9\s-]*$/;
        if (!regex.test(val)) {
            setPrefixError('Invalid characters. Use letters, numbers, spaces, or dashes only.');
        } else {
            setPrefixError('');
        }
        setPlotPrefix(val.toUpperCase());
    };

    // Plot Numbering Preview Logic
    const plotPreview = useMemo(() => {
        if (!selectedProperty) return [];
        const prefix = plotPrefix.trim();
        const samples = [1, 2, 23];
        return samples.map(num => prefix ? `${prefix}-${num}` : `${num}`);
    }, [plotPrefix, selectedProperty]);

    // Calculations for the P&L Panel
    const calculations = useMemo(() => {
        if (!selectedProperty) return null;

        const costPerPlot = selectedProperty.costPrice || 0;
        const currentSellingPrice = parseFloat(editSellingPrice) || 0;
        const totalPlots = inventory.reduce((sum, inv) => sum + (Number(inv.count) || 0), 0);

        const margin = currentSellingPrice - costPerPlot;
        const marginPercentage = costPerPlot > 0 ? (margin / costPerPlot) * 100 : 0;
        const totalRevenue = currentSellingPrice * totalPlots;
        const totalCost = costPerPlot * totalPlots;
        const grossProfit = totalRevenue - totalCost;

        return {
            costPerPlot,
            currentSellingPrice,
            margin,
            marginPercentage,
            totalPlots,
            totalRevenue,
            totalCost,
            grossProfit
        };
    }, [selectedProperty, editSellingPrice, inventory]);

    const handleSave = async () => {
        if (!selectedProperty || !calculations || prefixError) return;

        // Edge Case: Validate Partitioning
        if (inventory.length === 0) {
            alert("Please define at least one plot partitioning entry before publishing.");
            return;
        }

        const invalidRows = inventory.some(inv => !inv.count || inv.count <= 0);
        if (invalidRows) {
            alert("Please ensure all partitioning entries have a valid number of plots.");
            return;
        }

        setIsSaving(true);
        try {
            const historyEntry: PriceHistory = {
                date: new Date().toISOString(),
                oldPrice: selectedProperty.price,
                newPrice: calculations.currentSellingPrice,
                changedBy: currentStaff.fullName
            };

            const updatedProperty: Property = {
                ...selectedProperty,
                price: calculations.currentSellingPrice,
                priceHistory: [historyEntry, ...(selectedProperty.priceHistory || [])],
                inventory: inventory.map(inv => ({
                    size: inv.size,
                    count: Number(inv.count),
                    sold: inv.sold || 0,
                    zone: inv.zone
                }) as any),
                //@ts-ignore
                plotPrefix: plotPrefix.trim() 
            };

            await onSaveProperty(updatedProperty);
            alert("Property management configuration updated successfully.");
        } catch (error) {
            console.error(error);
            alert("Failed to update property configuration.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" />
                        Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white mt-2 tracking-tight uppercase">Purchase & Sale Management</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Executive oversight of acquisition costs and market margins.</p>
                </div>
            </div>

            <Card className="bg-gray-50/50 dark:bg-gray-900/10">
                <div className="max-w-md">
                    <Select 
                        label="Select Property for Management"
                        value={selectedPropertyId}
                        onChange={(e) => setSelectedPropertyId(e.target.value ? Number(e.target.value) : '')}
                    >
                        <option value="">-- Choose an acquisition record --</option>
                        {properties.map(p => (
                            <option key={p.id} value={p.id}>{p.location}</option>
                        ))}
                    </Select>
                </div>
            </Card>

            {selectedProperty && calculations ? (
                <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                    {/* Management Work Area */}
                    <div className="xl:col-span-2 space-y-8">
                        <div className="flex items-center gap-4 p-6 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm">
                            <div className="p-3 rounded-full bg-blue-100 dark:bg-blue-900/30">
                                <BuildingLibraryIcon className="w-8 h-8 text-blue-600" />
                            </div>
                            <div>
                                <h2 className="text-2xl font-black text-gray-900 dark:text-white">{selectedProperty.location}</h2>
                                <p className="text-gray-500 dark:text-gray-400">{selectedProperty.description}</p>
                            </div>
                        </div>

                        <Card title="Management Controls">
                            <div className="space-y-8">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                    {/* Price Controls */}
                                    <div className="space-y-6">
                                        <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                            <BanknotesIcon className="w-4 h-4" /> Financial Configuration
                                        </h3>
                                        <div>
                                            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Cost Price per Plot (Acquisition)</label>
                                            <div className="px-4 py-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg font-black text-gray-700 dark:text-gray-300">
                                                {formatCurrency(calculations.costPerPlot)}
                                            </div>
                                        </div>

                                        <Input 
                                            label="New Selling Price per Plot (Market)"
                                            type="number"
                                            value={editSellingPrice}
                                            onChange={(e) => setEditSellingPrice(e.target.value)}
                                            placeholder="0.00"
                                            className="font-black text-xl text-blue-600"
                                        />

                                        <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-lg border border-blue-100 dark:border-blue-900/50">
                                            <p className="text-xs font-bold text-blue-800 dark:text-blue-300 mb-1 flex items-center gap-1">
                                                <ArrowTrendingUpIcon className="w-4 h-4" /> Margin Insight
                                            </p>
                                            <p className="text-sm font-medium text-blue-600 dark:text-blue-400">
                                                Applying a <span className="font-black">{calculations.marginPercentage.toFixed(1)}%</span> margin above acquisition cost.
                                            </p>
                                        </div>
                                    </div>

                                    {/* Plot Numbering Configuration */}
                                    <div className="space-y-6 border-l border-gray-100 dark:border-gray-700 md:pl-8">
                                        <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                            <HashtagIcon className="w-4 h-4" /> Identifier Configuration
                                        </h3>

                                        <div className="space-y-4">
                                            <Input 
                                                label="Plot Number Prefix"
                                                value={plotPrefix}
                                                onChange={(e) => validatePrefix(e.target.value)}
                                                placeholder="e.g. EAF, ZONE-C"
                                                error={prefixError}
                                                className="font-bold uppercase"
                                            />

                                            <div className="bg-gray-50 dark:bg-gray-900/50 p-4 rounded-xl border border-gray-200 dark:border-gray-800">
                                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">Live Numbering Preview</p>
                                                <div className="flex flex-wrap gap-2">
                                                    {plotPreview.map((p, i) => (
                                                        <Badge key={i} variant="info" className="font-mono text-xs py-1 px-2">
                                                            {p}
                                                        </Badge>
                                                    ))}
                                                    <span className="text-gray-400 text-xs flex items-center">...</span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {/* SECTION: Plot Partitioning (Relocated) */}
                                <div className="pt-8 border-t border-gray-100 dark:border-gray-700">
                                    <div className="flex items-center justify-between mb-4">
                                        <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                            <MapIcon className="w-4 h-4" /> Plot Partitioning
                                        </h3>
                                        <button 
                                            type="button" 
                                            onClick={addInventoryRow}
                                            className="flex items-center gap-1 text-xs font-black text-blue-600 dark:text-blue-400 hover:text-blue-800 uppercase"
                                        >
                                            <PlusCircleIcon className="w-4 h-4" /> Add Row
                                        </button>
                                    </div>

                                    <div className="space-y-3">
                                        {inventory.map((item, idx) => (
                                            <div key={idx} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-4 bg-gray-50/50 dark:bg-gray-900/30 rounded-xl border border-gray-100 dark:border-gray-800 relative group">
                                                <button 
                                                    onClick={() => removeInventoryRow(idx)}
                                                    className="absolute -top-2 -right-2 p-1 bg-red-100 dark:bg-red-900 text-red-600 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                                >
                                                    <TrashIcon className="w-4 h-4" />
                                                </button>
                                                <Select 
                                                    label="Size" 
                                                    value={item.size} 
                                                    onChange={e => updateInventoryItem(idx, 'size', e.target.value)}
                                                >
                                                    <option value="70x100 ft">70x100 ft</option>
                                                    <option value="70x50 ft">70x50 ft</option>
                                                    <option value="60x80 ft">60x80 ft</option>
                                                </Select>
                                                <Input 
                                                    label="Number of Plots" 
                                                    type="number" 
                                                    value={item.count} 
                                                    onChange={e => updateInventoryItem(idx, 'count', Number(e.target.value))}
                                                    className="no-spinner"
                                                />
                                                <Input 
                                                    label="Zone / Phase Name" 
                                                    value={item.zone || ''} 
                                                    onChange={e => updateInventoryItem(idx, 'zone', e.target.value)}
                                                    placeholder="e.g. Zone A"
                                                />
                                                <div className="flex flex-col justify-end">
                                                    <div className="p-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg">
                                                        <p className="text-[9px] font-black text-gray-400 uppercase">Status</p>
                                                        <p className="text-xs font-bold text-gray-700 dark:text-gray-300">
                                                            {item.sold || 0} Sold / {item.count || 0} Total
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}

                                        {inventory.length === 0 && (
                                            <div className="p-12 text-center border-2 border-dashed border-gray-100 dark:border-gray-800 rounded-2xl">
                                                <p className="text-sm text-gray-400 font-medium">No partitions defined. Click 'Add Row' to start defining plots.</p>
                                            </div>
                                        )}
                                    </div>
                                </div>

                                <div className="flex justify-end pt-6">
                                    <Button 
                                        onClick={handleSave} 
                                        isLoading={isSaving}
                                        className="px-10 py-3 shadow-lg uppercase tracking-wider"
                                        disabled={!!prefixError}
                                    >
                                        Publish Configuration
                                    </Button>
                                </div>
                            </div>
                        </Card>

                        <Card title="Historical Price Audit">
                            <TableContainer className="border-0 shadow-none">
                                <table className="w-full text-sm text-left">
                                    <Thead>
                                        <tr>
                                            <Th>Change Date</Th>
                                            <Th>Previous Price</Th>
                                            <Th>New Price</Th>
                                            <Th>Approved By</Th>
                                        </tr>
                                    </Thead>
                                    <Tbody>
                                        {selectedProperty.priceHistory?.map((entry, idx) => (
                                            <Tr key={idx}>
                                                <Td className="font-mono text-xs">{new Date(entry.date).toLocaleString()}</Td>
                                                <Td className="text-gray-400">{formatCurrency(entry.oldPrice)}</Td>
                                                <Td className="font-bold text-green-600">{formatCurrency(entry.newPrice)}</Td>
                                                <Td>{entry.changedBy}</Td>
                                            </Tr>
                                        ))}
                                        {(!selectedProperty.priceHistory || selectedProperty.priceHistory.length === 0) && (
                                            <Tr>
                                                <Td colSpan={4} className="text-center py-8 text-gray-400 italic">No price change history available.</Td>
                                            </Tr>
                                        )}
                                    </Tbody>
                                </table>
                            </TableContainer>
                        </Card>
                    </div>

