                                                            <p className="text-sm font-black text-amber-900 dark:text-amber-300">{formatCurrency(promo.promoPrice || 0)}</p>
                                                            <p className="text-[9px] text-amber-500 font-bold mt-1">Saves: {formatCurrency((promo.originalPrice || 0) - (promo.promoPrice || 0))}</p>
                                                        </button>
                                                    ))}
                                                </div>
                                            </div>
                                        </Card>
                                    )}

                                    <Card title="Payment Description">
                                        <div className="space-y-4">
                                            <div className="relative">
                                                <Input label="Land Purchase Price" type="number" value={landPrice} onChange={e => setLandPrice(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                {isFieldReadOnly && <LockClosedIcon className="absolute right-3 top-[34px] w-4 h-4 text-gray-400 pointer-events-none" />}
                                            </div>
                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                <Input label="Discount (Optional)" type="number" value={discountValue} onChange={e => setDiscountValue(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                                <div className="flex flex-col">
                                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Discount Mode</label>
                                                    <div className="flex h-[38px] bg-gray-100 dark:bg-gray-900 p-1 rounded-md border border-gray-300 dark:border-gray-700">
                                                        <button type="button" disabled={isFieldReadOnly} onClick={() => setDiscountType('percentage')} className={`flex-1 text-xs font-bold rounded ${discountType === 'percentage' ? 'bg-white dark:bg-gray-700 text-indigo-600 shadow-sm' : 'text-gray-500'}`}>%</button>
                                                        <button type="button" disabled={isFieldReadOnly} onClick={() => setDiscountType('fixed')} className={`flex-1 text-xs font-bold rounded ${discountType === 'fixed' ? 'bg-white dark:bg-gray-700 text-indigo-600 shadow-sm' : 'text-gray-500'}`}>GHC</button>
                                                    </div>
                                                </div>
                                            </div>
                                            <Input label="Indenture Price" type="number" value={indenturePrice} onChange={e => setIndenturePrice(e.target.value)} readOnly={isFieldReadOnly} className="no-spinner" />
                                            <Select label="Payment Plan" value={paymentOption} onChange={e => setPaymentOption(e.target.value)} disabled={isFieldReadOnly}>
                                                <option value="Outright">Outright Payment</option>
                                                <option value="3">3 Months</option>
                                                <option value="6">6 Months</option>
                                                <option value="Other">Other</option>
                                            </Select>

                                            {/* SAVE RECORD BUTTON - PERSISTENT BEHAVIOR */}
                                            {(!isInitialized || isUnlocked) && (
                                                <div className="pt-4 mt-4 border-t border-gray-100 dark:border-gray-700">
                                                    <Button 
                                                        onClick={handleFormSubmit} 
                                                        className="w-full py-4 text-lg uppercase tracking-widest shadow-lg" 
                                                        isLoading={isSaving}
                                                        disabled={isSaveDisabled}
                                                    >
                                                        Save Record
                                                    </Button>
