                                    </Card>

                                    <div className={`p-4 rounded-lg flex items-start gap-3 border ${selectedClient.payment.paid / (parseFloat(landPrice) || 1) >= 0.7 ? 'bg-green-50 border-green-200 text-green-800' : 'bg-amber-50 border-amber-200 text-amber-800'}`}>
                                        <ExclamationTriangleIcon className="w-6 h-6 mt-0.5" />
                                        <div>
                                            <h4 className="font-bold text-sm">Allocation Status</h4>
                                            <p className="text-xs mt-1">Paid: {((selectedClient.payment.paid / (parseFloat(landPrice) || 1)) * 100).toFixed(1)}%. (Requires 70%)</p>
                                        </div>
                                    </div>
                                </div>
                            )}
                            {activeTab === 'history' && (
                                <Card title="Payment Ledger" className="p-0 overflow-hidden">
                                    <div className="overflow-x-auto">
                                        <table className="w-full text-sm text-left">
                                            <thead className="bg-gray-50 dark:bg-gray-700">
                                                <tr>
                                                    <th className="px-4 py-3">Slot</th>
                                                    <th className="px-4 py-3">Expected Date</th>
                                                    <th className="px-4 py-3">Actual Date</th>
                                                    <th className="px-4 py-3 text-right">Expected Amount</th>
                                                    <th className="px-4 py-3 text-right">Actual Paid</th>
                                                    <th className="px-4 py-3 text-center">Status</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-gray-100 dark:divide-gray-600">
                                                {installmentSchedule.map(slot => (
                                                    <tr key={slot.index}>
                                                        <td className="px-4 py-3 font-bold">#{slot.index}</td>
                                                        <td className="px-4 py-3">{slot.expectedDate}</td>
                                                        <td className="px-4 py-3">{slot.actualDate || '---'}</td>
                                                        <td className="px-4 py-3 text-right">{formatCurrency(slot.expectedAmount)}</td>
                                                        <td className="px-4 py-3 text-right">{slot.actualAmount ? formatCurrency(slot.actualAmount) : '---'}</td>
                                                        <td className="px-4 py-3 text-center">{getStatusBadge(slot.status)}</td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
