            </div>

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            {showSuccessModal && (
                <div className="fixed inset-0 bg-slate-900/50 z-[100] flex justify-center items-center p-4 backdrop-blur-sm">
                    <Card className="w-full max-w-xs p-6 text-center animate-in zoom-in duration-200">
                        <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <CheckCircleIcon className="w-6 h-6 text-green-600" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">Record Saved</h3>
                        <Button onClick={() => setShowSuccessModal(false)} className="w-full">OK</Button>
                    </Card>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
