import { 
    BanknotesIcon,
    ChevronRightIcon,
    ArrowLeftIcon,
    LockClosedIcon,
    PencilSquareIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    ClockIcon,
    // FIX: Imported XMarkIcon to resolve the error in RecordPaymentModal
    XMarkIcon,
    CheckCircleIcon,
    ExclamationTriangleIcon,
    UserCircleIcon,
    CurrencyDollarIcon,
    TagIcon,
    ChartPieIcon
} from './icons/DummyIcons';
