        await onSave({ id: `COMM-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Paid', issueDate: data.date, dueDate: data.date }, updatedClient);
        setPaymentModalOpen(false);
