}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const { promotions } = usePromotions();
    const { properties } = useProperties();
    const { saveClient } = useClients();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [paymentForcedType, setPaymentForcedType] = useState<'Land' | 'Indenture' | 'Commission' | undefined>();

    // Commission State
    const [isAmendingCommission, setIsAmendingCommission] = useState(false);
    const [amendmentError, setAmendmentError] = useState('');
    const [tempCommissionAmount, setTempCommissionAmount] = useState<string>('0');

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);
    const isCEO = useMemo(() => {
        const roleName = roles.find(r => r.id === currentStaff?.roleId)?.name;
        return roleName === 'CEO';
    }, [currentStaff, roles]);

    // Computed Commission Details (4% Rule)
    const commissionStats = useMemo(() => {
        if (!selectedClient) return null;
        const totalPaid = selectedClient.payment.paid || 0;
        const autoAmount = (totalPaid * 0.04);

        // Use manually stored amount if it was amended, else 4%
        const dueAmount = (selectedClient.officeUse.commission as any).isAmended 
            ? selectedClient.officeUse.commission.amount 
            : autoAmount;

        const paidToDate = selectedClient.payment.paymentHistory
            .filter((p: any) => p.type === 'Commission')
            .reduce((sum, p) => sum + p.amount, 0);

        return {
            repName: selectedClient.officeUse.salesRep,
            dueAmount,
            paidToDate,
            outstanding: Math.max(0, dueAmount - paidToDate),
            status: paidToDate >= dueAmount && dueAmount > 0 ? 'Settled' : 'Pending'
        };
    }, [selectedClient]);

    const handleCommissionAmendmentClick = () => {
        if (!isCEO) {
            setAmendmentError('Only CEO accounts are authorized to amend or waive commissions.');
            setTimeout(() => setAmendmentError(''), 5000);
            return;
        }
        setTempCommissionAmount(commissionStats?.dueAmount.toString() || '0');
        setIsAmendingCommission(true);
    };

    const handleSaveCommissionAmendment = async () => {
        if (!selectedClient) return;
        const val = parseFloat(tempCommissionAmount);
        const updatedClient = {
            ...selectedClient,
            officeUse: {
                ...selectedClient.officeUse,
                commission: {
                    ...selectedClient.officeUse.commission,
                    amount: isNaN(val) ? 0 : val,
                    isAmended: true
                }
            }
        } as Client;
        await saveClient(updatedClient);
        setIsAmendingCommission(false);
    };

    const handleCommissionPayment = async (data: any) => {
        if (!selectedClient) return;
        onRecordPayment(selectedClient, data);
        setPaymentModalOpen(false);
    };

    useEffect(() => {
        if (selectedClient) {
            // ... (existing field initializers)
        }
    }, [selectedClient]);

    return (
