    PencilSquareIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    ClockIcon,
    XMarkIcon,
    CheckCircleIcon,
    ExclamationTriangleIcon,
    UserCircleIcon,
    CurrencyDollarIcon,
    TagIcon,
    ChartPieIcon,
    InformationCircleIcon,
    UserCheckIcon,
    ChatBubbleLeftEllipsisIcon
} from './icons/DummyIcons';
