                                        <div className="flex items-center justify-between mb-4 text-purple-700 dark:text-purple-400">
                                            <div className="flex items-center gap-2">
                                                <UserCheckIcon className="w-5 h-5" />
                                                <h3 className="text-sm font-black uppercase tracking-widest">Intermediary Details</h3>
                                            </div>
                                            <Badge variant="purple">4% Fixed Rate</Badge>
                                        </div>
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                            <div>
                                                <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Representative Name</p>
                                                <p className="text-xl font-black text-gray-900 dark:text-white mt-1">{commissionStats.repName}</p>
                                            </div>
                                            <div className="flex justify-end items-center">
                                                {isAmendingCommission ? (
                                                    <div className="flex items-end gap-2 bg-white dark:bg-gray-800 p-3 rounded-lg border border-indigo-200 shadow-sm">
                                                        <Input 
