                                                        <Td className="text-center">
                                                            {getStatusBadge(txn.computedStatus)}
                                                        </Td>
                                                    </Tr>
                                                ))}
                                                {integratedHistory.length === 0 && (
                                                    <Tr><Td colSpan={5} className="text-center py-10 text-gray-400 italic">No payment records found.</Td></Tr>
                                                )}
                                            </Tbody>
                                        </table>
                                    </TableContainer>
                                </Card>
                            )}

                            {activeTab === 'overview' && (
                                <div className="text-center py-20 opacity-40">
                                    <InformationCircleIcon className="w-16 h-16 mx-auto mb-4" />
                                    <p>Account Overview Active</p>
                                </div>
                            )}

                        </div>
                    )}
                </div>
            </div>

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            <RecordPaymentModal 
              isOpen={isPaymentModalOpen} 
              onClose={() => setPaymentModalOpen(false)} 
              client={selectedClient!}
              forcedType={paymentForcedType}
              onSave={(data) => {
                if (data.type === 'Commission') {
                    handleCommissionPayment(data);
                } else {
                    onRecordPayment(selectedClient!, data);
                    setPaymentModalOpen(false);
                }
              }}
            />
        </div>
    );
};

