const getStatusBadge = (status: string) => {
  let variant: 'success' | 'warning' | 'danger' | 'neutral' | 'purple' = 'neutral';
  switch (status) {
    case 'Paid': case 'Success': case 'On Time': case 'Fully Paid': variant = 'success'; break;
    case 'Pending': variant = 'warning'; break;
    case 'Outstanding': case 'Overdue': case 'Failed': case 'Late': case 'Delayed': variant = 'danger'; break;
    case 'Expected': case 'Overpaid': variant = 'purple'; break;
  }
  return <Badge variant={variant}>{status}</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Verify Identity</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Re-authenticate to unlock financial fields.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Staff Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="email@faim.com" />
                        <Input label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const RecordPaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSave: (payment: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    client: Client;
    forcedType?: 'Land' | 'Indenture' | 'Commission';
}> = ({ isOpen, onClose, onSave, client, forcedType }) => {
    const [amount, setAmount] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>(forcedType || 'Land');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [notes, setNotes] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            setAmount('');
            setDate(new Date().toISOString().split('T')[0]);
            setNotes('');
            setError('');
            if (forcedType) setType(forcedType);
        }
    }, [isOpen, forcedType]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const paidAmount = parseFloat(amount);

        if (!date) {
            setError('Payment date is required.');
            return;
        }
        if (isNaN(paidAmount) || paidAmount <= 0) {
            setError('Please enter a valid positive amount.');
            return;
        }

        // Outstanding Balance Check (Rule F)
        const currentBalance = client.payment.balance;
        if (paidAmount > currentBalance) {
            setError(`Payment amount exceeds the outstanding balance of ${formatCurrency(currentBalance)}.`);
            return;
        }

        if (!receiptNumber.trim()) {
            setError('Receipt/Reference number is required.');
            return;
        }

        onSave({ date, amount: paidAmount, method, reference: receiptNumber, receiptNumber, type, notes } as any);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-md p-0 overflow-hidden shadow-2xl">
                <form onSubmit={handleSubmit}>
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                        <h2 className="text-lg font-black text-gray-800 dark:text-white uppercase tracking-tight">Make {type} Payment</h2>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
                          <XMarkIcon className="w-6 h-6" />
                        </button>
                    </div>
                    <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto bg-gray-50 dark:bg-gray-900">
                        {error && (
                          <div className="bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-200 p-3 rounded-md text-xs border border-red-200 dark:border-red-800 flex items-center gap-2">
                            <ExclamationTriangleIcon className="w-4 h-4 shrink-0" />
                            {error}
                          </div>
                        )}
                        <Select label="Payment Purpose*" value={type} onChange={e => setType(e.target.value as any)} disabled={!!forcedType}>
                            <option value="Land">Land Purchase Payment</option>
                            <option value="Indenture">Indenture / Documentation Payment</option>
                            <option value="Commission">Sales Commission Payment</option>
                        </Select>
                        <div className="grid grid-cols-2 gap-4">
                          <Input label="Payment Date*" type="date" value={date} onChange={e => setDate(e.target.value)} required />
                          <Input label="Amount (GHC)*" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" required className="no-spinner font-bold" />
                        </div>
                        <Input label="Receipt / Reference No.*" value={receiptNumber} onChange={e => setReceiptNumber(e.target.value)} placeholder="Enter unique ID" required />
                        <Select label="Payment Method*" value={method} onChange={e => setMethod(e.target.value as any)}>
                            <option value="Bank Transfer">Bank Transfer</option>
                            <option value="Cash">Cash</option>
                            <option value="MoMo">Mobile Money (MoMo)</option>
                            <option value="Cheque">Cheque</option>
                            <option value="Other">Other</option>
                        </Select>
                        <div className="space-y-1">
                          <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Internal Notes</label>
                          <textarea 
                            value={notes} 
                            onChange={e => setNotes(e.target.value)} 
                            placeholder="Add payment context..." 
                            className="w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-md text-sm focus:ring-2 focus:ring-blue-500 min-h-[80px]"
                          />
                        </div>
                    </div>
                    <div className="flex justify-end p-4 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit" icon={<CheckCircleIcon className="w-4 h-4" />}>Confirm Payment</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const { properties } = useProperties();
    const { saveClient } = useClients();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [paymentForcedType, setPaymentForcedType] = useState<'Land' | 'Indenture' | 'Commission' | undefined>();

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    // Rule E: Land Price Auto-Generation
    useEffect(() => {
        if (selectedClient && !selectedClient.payment.isInitialized) {
            const property = properties.find(p => p.location === selectedClient.location);
            if (property) {
                // Instantly populate land price field
                setLandPrice(String(property.price));
            } else {
                setLandPrice('0');
            }
        }
    }, [selectedClient, properties]);

    const [landPrice, setLandPrice] = useState('0');
    const [indenturePrice, setIndenturePrice] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [discountValue, setDiscountValue] = useState('0');
    const [paymentOption, setPaymentOption] = useState('Outright');
    const [otherMonths, setOtherMonths] = useState('');
    const [calculatedTotal, setCalculatedTotal] = useState<number | null>(null);

    // History Synchronization Logic (Rule E)
    const processedHistory = useMemo(() => {
        if (!selectedClient) return [];

        let rollingBalance = selectedClient.payment.total;
        let prevDate = selectedClient.regDate; // Start date

        return selectedClient.payment.paymentHistory.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map((txn, idx) => {
            // Due Date: 30 days after previous date
            const dueDateObj = new Date(prevDate);
            dueDateObj.setDate(dueDateObj.getDate() + 30);
            const dueDateStr = dueDateObj.toISOString().split('T')[0];

            // Status determination
            const isLate = new Date(txn.date) > dueDateObj;
            const status = isLate ? 'Late' : 'Paid';

            rollingBalance -= txn.amount;
            prevDate = txn.date;

            return {
                ...txn,
                dueDate: dueDateStr,
                balanceRemaining: Math.max(0, rollingBalance),
                status
            };
        });
    }, [selectedClient]);

    const isInitialized = !!selectedClient?.payment?.isInitialized;

    useEffect(() => {
        if (selectedClient) {
            setLandPrice(String(selectedClient.payment.total || 0));
            setIndenturePrice(String((selectedClient.payment as any).indenturePrice || 0));
            setPaymentOption(selectedClient.payment.planType?.includes('3-Month') ? '3' : selectedClient.payment.planType?.includes('6-Month') ? '6' : 'Outright');
            setDiscountValue(String((selectedClient.payment as any).discountValue || '0'));
            setDiscountType((selectedClient.payment as any).discountType || 'percentage');
        }
    }, [selectedClient]);

    useEffect(() => {
        if (!selectedClient) return;
        const P_initial = parseFloat(landPrice) || 0;
        const D = parseFloat(discountValue) || 0;
        let P = P_initial;
        if (discountType === 'percentage') {
            P = P_initial * (1 - (D / 100));
        } else {
            P = Math.max(0, P_initial - D);
        }
        setCalculatedTotal(P);
    }, [landPrice, discountType, discountValue, selectedClient]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient || isSaving) return;

        // Validation: Prevent saving if location has no price (Rule F)
        const prop = properties.find(p => p.location === selectedClient.location);
        if (!prop) {
            alert('Warning: Selected land location has no linked market price. Please configure property pricing first.');
            return;
        }

        setIsSaving(true);
        const finalLandPrice = calculatedTotal || parseFloat(landPrice) || 0;
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: finalLandPrice,
                balance: finalLandPrice - selectedClient.payment.paid,
            }
        } as Client;

        try {
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
            setShowSuccessModal(true);
        } finally {
            setIsSaving(false);
        }
    };

    const handleRecordPaymentLocal = async (paymentData: any) => {
        if (!selectedClient) return;

        // Rule E: Deduct amount and recalculate instantly
        const newPaid = selectedClient.payment.paid + paymentData.amount;
        const newBalance = Math.max(0, selectedClient.payment.total - newPaid);

        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                paid: newPaid,
                balance: newBalance,
                paymentHistory: [
                  ...selectedClient.payment.paymentHistory,
                  { ...paymentData, id: `TXN-${Date.now()}`, status: 'Success' }
                ]
            }
        } as Client;

        // Final paid mark (Rule E)
        if (newBalance === 0) {
            updatedClient.status = 'Active Client'; // Or specific "Fully Paid" logic if stage needs changing
        }

        await saveClient(updatedClient);
        setPaymentModalOpen(false);
    };

    const isFieldReadOnly = isInitialized && !isUnlocked;

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <div>
                        <h2 className="text-xl font-bold text-gray-800 dark:text-white">Financial Record Editor</h2>
                    </div>
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-4 space-y-4 overflow-y-auto scrollbar-thin">
                    {!fixedClient && (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Client</label>
                            <button
                                type="button"
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className={`flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 cursor-pointer`}
                            >
                                <span className="truncate">{selectedClient ? selectedClient.name : '-- Select a client --'}</span>
                                <ChevronDownIcon className={`w-4 h-4 text-gray-400 transition-transform ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                            </button>
                            {isClientDropdownOpen && (
                                <div className="absolute left-0 right-0 mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-xl z-50 max-h-60 overflow-y-auto scrollbar-thin">
                                    {clients.map(client => (
                                        <button key={client.id} type="button" onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }} className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 dark:hover:bg-indigo-900/30 transition-colors border-b border-gray-50 dark:border-gray-700 last:border-0 ${selectedClientId === client.id ? 'bg-indigo-50 font-semibold text-indigo-700' : 'text-gray-700 dark:text-gray-300'}`}>{client.name}</button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <div className="space-y-1">
                            {['overview', 'history', 'commission'].map(tab => (
                                <button key={tab} onClick={() => setActiveTab(tab)} className={`w-full text-left p-2 rounded-md text-sm font-semibold transition-colors ${activeTab === tab ? 'bg-indigo-50 dark:bg-indigo-900/50 text-indigo-700 dark:text-indigo-300' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100'}`}>{tab.charAt(0).toUpperCase() + tab.slice(1)}</button>
                            ))}
                        </div>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {selectedClient && (
                        <div className="space-y-6 max-w-5xl mx-auto">
                            <Card className="border-l-4 border-l-green-500 bg-green-50/20 dark:bg-green-900/10">
                                <div className="flex items-center gap-2 mb-4 text-green-700 dark:text-green-400">
                                    <ChartPieIcon className="w-5 h-5" />
                                    <h3 className="text-sm font-black uppercase tracking-widest">Active Payment Summary</h3>
                                </div>
                                <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                                    <div>
                                        <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Settlement Agreement</p>
                                        <p className="text-lg font-black text-gray-900 dark:text-white">{formatCurrency(selectedClient.payment.total)}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Amount Paid</p>
                                        <p className="text-lg font-black text-green-600">{formatCurrency(selectedClient.payment.paid)}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Outstanding</p>
                                        <div className="flex items-center gap-2">
                                          <p className="text-lg font-black text-red-600">{formatCurrency(selectedClient.payment.balance)}</p>
                                          {selectedClient.payment.balance <= 0 && <Badge variant="success">Fully Paid</Badge>}
                                        </div>
                                    </div>
                                </div>
                            </Card>

                            {activeTab === 'overview' && (
