                                        </div>
                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                            <Input label="Discount" type="number" value={discountValue} onChange={e => setDiscountValue(e.target.value)} readOnly={isFieldReadOnly} />
                                            <Select label="Discount Type" value={discountType} onChange={e => setDiscountType(e.target.value as any)} disabled={isFieldReadOnly}>
                                                <option value="percentage">Percentage (%)</option>
                                                <option value="fixed">Fixed Amount (GHC)</option>
                                            </Select>
                                        </div>
                                        <div className="p-3 bg-blue-50 dark:bg-blue-900/10 rounded-lg border border-blue-100">
