                                                        <td className="px-4 py-3 text-gray-500 italic">{txn.dueDate}</td>
                                                        <td className="px-4 py-3 font-medium">{txn.date}</td>
                                                        <td className="px-4 py-3 text-right font-black">{formatCurrency(txn.balanceRemaining)}</td>
                                                        <td className="px-4 py-3 text-center">{getStatusBadge(txn.status)}</td>
                                                    </tr>
                                                ))}
                                                {processedHistory.length === 0 && (
                                                    <tr>
                                                        <td colSpan={6} className="p-10 text-center text-gray-400 italic">No payments recorded yet.</td>
                                                    </tr>
                                                )}
                                            </tbody>
                                        </table>
                                    </div>
                                </Card>
                            )}
                        </div>
                    )}
                </div>
            </div>

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            <RecordPaymentModal 
              isOpen={isPaymentModalOpen} 
              onClose={() => setPaymentModalOpen(false)} 
              client={selectedClient!}
              forcedType={paymentForcedType}
              onSave={handleRecordPaymentLocal}
            />
        </div>
    );
};

