                                        </div>
                                        <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700">
                                            <span className="text-sm font-medium text-gray-500 uppercase tracking-widest">Installment Count</span>
                                            <span className="text-lg font-bold text-gray-800 dark:text-white">{financialSummary.installmentCount} Months</span>
                                        </div>
                                        <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700">
                                            <span className="text-sm font-medium text-gray-500 uppercase tracking-widest">EMI Amount</span>
                                            <span className="text-lg font-black text-blue-600">{financialSummary.emiAmount > 0 ? formatCurrency(financialSummary.emiAmount) : 'N/A'}</span>
                                        </div>
                                        <div className="flex justify-between items-center py-4 mt-2 bg-gray-50 dark:bg-gray-800 px-3 rounded-lg border border-gray-200 dark:border-gray-700">
