                                                </div>
                                                <span className="text-xs font-black text-gray-500 uppercase tracking-widest">Outstanding Balance</span>
                                            </div>
                                            <div className="text-xl font-black text-red-600">
                                                {formatCurrency(financialSummary.outstandingBalance)}
