                                        </div>
                                        <div className="flex justify-center pt-2">
                                            {financialSummary.outstandingBalance <= 0 && financialSummary.totalPaid > 0 && <Badge variant="success" className="px-6 py-1 font-black uppercase">Fully Settled</Badge>}
                                        </div>
                                    </div>
                                </Card>
                            </div>

                            <div className="flex justify-end pt-4 gap-3">
                                {isReadOnly ? (
                                    <Button variant="ghost" onClick={() => setAuthModalOpen(true)} icon={<LockClosedIcon className="w-4 h-4" />}>
