                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1 font-bold uppercase text-[10px] tracking-widest">Client Account</label>
                            <button
                                type="button"
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
