                                    {clients.map(client => (
                                        <button key={client.id} type="button" onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }} className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 dark:hover:bg-indigo-900/30 border-b border-gray-50 dark:border-gray-700 last:border-0 ${selectedClientId === client.id ? 'bg-indigo-50 font-semibold text-indigo-700' : 'text-gray-700 dark:text-gray-300'}`}>{client.name}</button>
