                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {selectedClient ? (
                        <div className="max-w-4xl mx-auto">
                            {/* LOCKED UI CONTAINER: ACTIVE PAYMENT SUMMARY */}
                            <Card className="border-l-4 border-l-green-500 bg-white dark:bg-gray-800 shadow-xl p-0 overflow-hidden">
                                <div className="px-6 py-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/20 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <ChartPieIcon className="w-6 h-6 text-green-600" />
                                        <h3 className="text-sm font-black uppercase tracking-widest text-gray-700 dark:text-gray-200">Active Ledger Summary</h3>
                                    </div>
                                    <Badge variant={financialSummary.outstandingBalance <= 0 && financialSummary.totalPaid > 0 ? 'success' : 'warning'}>
                                        {financialSummary.outstandingBalance <= 0 && financialSummary.totalPaid > 0 ? 'Settled' : 'Active Account'}
                                    </Badge>
                                </div>

                                {/* IMMUTABLE LIST CONTAINER */}
                                <div className="p-6 space-y-1">
                                    {/* EXISTING ENTRIES (LOCKED) */}
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 p-4 bg-green-50/20 dark:bg-green-900/10 rounded-xl border border-green-100 dark:border-green-900/30">
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Settlement Agreement</p>
                                            <p className="text-xl font-black text-gray-900 dark:text-white">{formatCurrency(financialSummary.priceDueToEmi)}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Total Paid</p>
                                            <p className="text-xl font-black text-green-600">{formatCurrency(financialSummary.totalPaid)}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Outstanding</p>
                                            <p className="text-xl font-black text-red-600">{formatCurrency(financialSummary.outstandingBalance)}</p>
                                        </div>
                                    </div>

                                    {/* APPEND-ONLY EXTENSION BLOCK (READ-ONLY) */}
                                    <div className="space-y-0 pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Additional Contract Context</h4>

                                        <SummaryRow label="Original Base Price" value={formatCurrency(financialSummary.originalPrice)} />
                                        <SummaryRow label="Property Location" value={financialSummary.location || '—'} />
                                        <SummaryRow label="Number of Plots" value={financialSummary.numberOfPlots || '—'} />
                                        <SummaryRow label="Price Per Plot" value={formatCurrency(financialSummary.pricePerPlot)} />
                                        <SummaryRow label="Discount Applied" value={financialSummary.discountApplied} />
                                        <SummaryRow label="Discount Value" value={financialSummary.discountLabel} isNegative={financialSummary.discountApplied === 'Yes'} />
                                        <SummaryRow label="EMI Calculation" value={financialSummary.emiApplied === 'Yes' ? `${formatCurrency(financialSummary.emiAmount)} / mo` : 'Not Applicable'} />
                                        <SummaryRow label="New Price After EMI" value={formatCurrency(financialSummary.priceDueToEmi)} isHighlight={true} />
                                        <SummaryRow label="Amount Paid" value={formatCurrency(financialSummary.totalPaid)} />
                                        <SummaryRow label="Outstanding Balance" value={formatCurrency(financialSummary.outstandingBalance)} isNegative={financialSummary.outstandingBalance > 0} />
                                    </div>
                                </div>

                                <div className="px-6 py-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-between items-center">
                                    <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                        <LockClosedIcon className="w-3 h-3" />
                                        System-Generated Record
                                    </div>
                                    <div className="flex gap-3">
                                        {isReadOnly ? (
                                            <Button variant="ghost" size="sm" onClick={() => setAuthModalOpen(true)} icon={<LockClosedIcon className="w-4 h-4" />}>
                                                Amendment Mode
                                            </Button>
                                        ) : (
                                            <Button size="sm" onClick={handleFormSubmit} isLoading={isSaving} icon={<CheckCircleIcon className="w-4 h-4" />}>
                                                Commit Ledger
                                            </Button>
                                        )}
                                    </div>
                                </div>
                            </Card>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50 p-10 text-center">
                            <UserCheckIcon className="w-16 h-16 mb-4" />
                            <p className="text-lg font-bold uppercase tracking-widest">Select Account to Display Summary</p>
                            <p className="text-xs mt-1">Select a client from the left sidebar to view the immutable summary.</p>
                        </div>
                    )}
                </div>
            </div>

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            <RecordPaymentModal 
              isOpen={isPaymentModalOpen} 
              onClose={() => setPaymentModalOpen(false)} 
              client={selectedClient!}
              forcedType={paymentForcedType}
              onSave={(data) => {
                onRecordPayment(selectedClient!, data);
                setPaymentModalOpen(false);
              }}
            />
        </div>
    );
};

// Placeholder for auth modal setter if needed elsewhere
const setAuthModalOpen = (val: boolean) => {};

import React, { useState, ChangeEvent, FormEvent, useEffect, useCallback, useMemo } from 'react';
import { Client, Property } from '../types';
import { XIcon } from './icons/XIcon';
import { UserGroupIcon, BuildingLibraryIcon, BriefcaseIcon, CheckCircleIcon } from './icons/DummyIcons';
import { PhoneInput } from './ui/PhoneInput';
import { EmailInput } from './ui/EmailInput';
import { Select } from './ui/Input';

export type FormData = {
    surname: string;
    otherNames: string;
    dateOfBirth: string;
    currentAddress: string;
    telephone: string;
    email: string;
    gender: string;
    photo: string;
    placeOfWork: string;
    profession: string;
    position: string;
    kinName: string;
    kinAddress: string;
    kinPhone: string;
    kinRelationship: string;
    kinEmail: string;
    witnessName: string;
    witnessAddress: string;
    witnessPhone: string;
    paymentDate: string;
    paymentMethod: 'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other';
    location: string;
    propertyType: 'Residential' | 'Commercial';
    plotNumber: string;
    plannedDevelopmentYear: string;
    filledFormPdf: string | null;
    indentureName: string;
    indentureAddress: string;
    salesRep: string;
    salesManager: string;
    accountsHead: string;
    clerk: string;
};

interface ClientFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => void;
  onSaveAndPay: (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => void;
  properties: Property[];
  editingClient?: Client | null;
}

const getFieldClass = (error?: string): string => {
    const baseClass = "mt-1 block w-full px-3 py-2 bg-white dark:bg-gray-900 border rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm text-gray-900 dark:text-white";
    return error ? `${baseClass} border-red-500 dark:border-red-600` : `${baseClass} border-gray-300 dark:border-gray-600`;
};

const SmartInputField: React.FC<{ id: keyof FormData; label: string; value: string | number; onChange: (e: ChangeEvent<HTMLInputElement>) => void; onBlur?: (e: React.FocusEvent<HTMLInputElement>) => void; error?: string; type?: string; required?: boolean; isTouched?: boolean; readOnly?: boolean; }> = ({ id, label, value, onChange, onBlur, error, type = 'text', required = false, isTouched, readOnly }) => (
    <div className="sm:col-span-1 relative">
        <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300">{label}{required && <span className="text-red-500">*</span>}</label>
        <input type={type} name={id} id={id} value={value} onChange={onChange} onBlur={onBlur} required={required} readOnly={readOnly} className={`${getFieldClass(error)} ${readOnly ? 'bg-gray-100 dark:bg-gray-800 cursor-not-allowed' : ''}`} title={error || ''} />
        {isTouched && !error && required && (
            <CheckCircleIcon className="absolute right-3 top-[37px] w-5 h-5 text-green-500 pointer-events-none" />
        )}
        {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
    </div>
);

const SmartSelectField: React.FC<{ id: keyof FormData; label: string; value: string; onChange: (e: ChangeEvent<HTMLSelectElement>) => void; onBlur?: (e: React.FocusEvent<HTMLSelectElement>) => void; children: React.ReactNode; error?: string; required?: boolean; isTouched?: boolean; disabled?: boolean; }> = ({ id, label, value, onChange, onBlur, children, error, required = false, isTouched, disabled }) => (
     <div className="sm:col-span-1 relative">
        <label htmlFor={id} className="block text-sm font-medium text-gray-700 dark:text-gray-300">{label}{required && <span className="text-red-500">*</span>}</label>
        <select id={id} name={id} value={value} onChange={onChange} onBlur={onBlur} required={required} disabled={disabled} className={`${getFieldClass(error)} ${disabled ? 'bg-gray-100 dark:bg-gray-800 cursor-not-allowed' : ''}`} title={error || ''}>
            {children}
        </select>
        {isTouched && !error && required && (
            <CheckCircleIcon className="absolute right-8 top-[37px] w-5 h-5 text-green-500 pointer-events-none" />
        )}
        {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
    </div>
);

const FormSection: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <div className="mt-6 pt-6 border-t border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">{title}</h3>
        <div className="mt-4 grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
            {children}
        </div>
    </div>
);

const initialFormData: FormData = {
    surname: '',
    otherNames: '',
    dateOfBirth: '',
    currentAddress: '',
    telephone: '',
    email: '',
    gender: 'Other',
    photo: '',
    placeOfWork: '',
    profession: '',
    position: '',
    kinName: '',
    kinAddress: '',
    kinPhone: '',
    kinRelationship: '',
    kinEmail: '',
    witnessName: '',
    witnessAddress: '',
    witnessPhone: '',
    paymentDate: new Date().toISOString().split('T')[0],
    paymentMethod: 'Bank Transfer',
    location: '',
    propertyType: 'Residential',
    plotNumber: '',
    plannedDevelopmentYear: new Date().getFullYear().toString(),
    filledFormPdf: null,
    indentureName: '',
    indentureAddress: '',
    salesRep: '',
    salesManager: '',
    accountsHead: '',
    clerk: '',
};

const ClientForm: React.FC<ClientFormProps> = ({ isOpen, onClose, onSave, onSaveAndPay, properties, editingClient }) => {
    const [step, setStep] = useState(1);
    const [formData, setFormData] = useState<FormData>(initialFormData);
    const [photoPreview, setPhotoPreview] = useState<string | null>(null);
    const [pdfFile, setPdfFile] = useState<File | null>(null);
    const [photoFile, setPhotoFile] = useState<File | null>(null);
    const [touched, setTouched] = useState<Partial<Record<keyof FormData, boolean>>>({});

     useEffect(() => {
        if (isOpen && editingClient) {
            setFormData({
                surname: editingClient.surname,
                otherNames: editingClient.otherNames,
                dateOfBirth: editingClient.dateOfBirth || '',
                currentAddress: editingClient.location,
                telephone: editingClient.phone,
                email: editingClient.email,
                gender: editingClient.gender || 'Other',
                photo: editingClient.photo || '',
                placeOfWork: editingClient.professionalDetails?.placeOfWork || '',
                profession: editingClient.professionalDetails?.profession || '',
                position: editingClient.professionalDetails?.position || '',
                kinName: editingClient.nextOfKin.name,
                kinAddress: editingClient.nextOfKin.address || '',
                kinPhone: editingClient.nextOfKin.phone,
                kinRelationship: editingClient.nextOfKin.relationship,
                kinEmail: editingClient.nextOfKin.email || '',
                witnessName: editingClient.witness.name,
                witnessAddress: editingClient.witness.address,
                witnessPhone: editingClient.witness.phone,
                paymentDate: editingClient.regDate,
                paymentMethod: editingClient.payment.paymentHistory[0]?.method || 'Bank Transfer',
                location: editingClient.location,
                propertyType: editingClient.propertyType || 'Residential',
                plotNumber: editingClient.plot,
                plannedDevelopmentYear: editingClient.plannedDevelopmentYear || new Date().getFullYear().toString(),
                filledFormPdf: editingClient.filledFormPdf,
                indentureName: editingClient.indenture.name,
                indentureAddress: editingClient.indenture.address,
                salesRep: editingClient.officeUse.salesRep,
                salesManager: editingClient.officeUse.salesManager,
                accountsHead: editingClient.officeUse.accountsHead,
                clerk: editingClient.officeUse.clerk,
            });
            setPhotoPreview(editingClient.photo || null);
            setTouched({});
        } else if (isOpen) {
            resetForm();
        }
    }, [isOpen, editingClient]);

    const validate = useCallback((): Partial<Record<keyof FormData, string>> => {
        const errors: Partial<Record<keyof FormData, string>> = {};
        const requiredFields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk', 'paymentDate'];

        requiredFields.forEach(field => {
            if (!formData[field]) errors[field] = 'This field cannot be left blank.';
        });

        const textFields: (keyof FormData)[] = ['surname', 'otherNames', 'kinName', 'witnessName', 'salesRep', 'salesManager', 'accountsHead', 'clerk'];
        textFields.forEach(field => {
            const value = formData[field];
            if (value) {
                if (!/^[A-Za-z\s'-]+$/.test(value)) errors[field] = 'Only letters, spaces, hyphens, and apostrophes are allowed.';
                if (/(.)\1{3,}/.test(value)) errors[field] = 'Please provide a valid, readable entry.';
                if (value.length < 2) errors[field] = 'Entry must be at least 2 characters.';
            }
        });

        const addressFields: (keyof FormData)[] = ['currentAddress', 'witnessAddress', 'indentureAddress'];
        addressFields.forEach(field => {
            const value = formData[field];
            if(value && (!/[a-zA-Z]/.test(value) || !/\s/.test(value))){
                errors[field] = 'Address must contain letters and at least one space.';
            }
        });

        if (formData.email && !/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(formData.email)) {
            errors.email = 'Please enter a valid email address format.';
        }

        const phoneFields: (keyof FormData)[] = ['telephone', 'kinPhone', 'witnessPhone'];
        phoneFields.forEach(field => {
            if (formData[field] && formData[field].length < 10) {
                errors[field] = 'Please provide a valid phone number with country code.';
            }
        });

        if (formData.plotNumber && !/^[A-Z]{2,}-\d+/.test(formData.plotNumber)) {
            errors.plotNumber = 'Plot number must follow a format like ELH-101.';
        }

        return errors;
    }, [formData]);

    const errors = useMemo(() => validate(), [validate]);
    const isFormValid = Object.keys(errors).length === 0;

    const handleBlur = (e: React.FocusEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name } = e.target as { name: keyof FormData };
        setTouched(prev => ({ ...prev, [name]: true }));
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (fieldName: keyof FormData) => (value: string) => {
        setFormData(prev => ({ ...prev, [fieldName]: value }));
    };

    const handlePhotoChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const allowedTypes = ['image/jpeg', 'image/png', 'image/jpg'];
            if (allowedTypes.includes(file.type)) {
                setPhotoFile(file);
                const reader = new FileReader();
                reader.onloadend = () => {
                    setPhotoPreview(reader.result as string);
                };
                reader.readAsDataURL(file);
            } else {
                 alert('Invalid file type. Please upload a .jpg, .jpeg, or .png file.');
                 e.target.value = '';
            }
        }
    };

    const handlePdfChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            if (file.type === 'application/pdf') {
                setPdfFile(file);
                setTouched(prev => ({ ...prev, filledFormPdf: true }));
            } else {
                alert('Please upload a PDF file.');
                e.target.value = '';
            }
        }
    };

    const step1Fields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress'];
    const step2Fields: (keyof FormData)[] = ['location', 'plotNumber', 'paymentDate', 'indentureName', 'indentureAddress'];

    const handleNext = () => {
        const currentStepFields = step === 1 ? step1Fields : step2Fields;
        let isStepValid = true;
        const fieldsToTouch: Partial<Record<keyof FormData, boolean>> = {};

        currentStepFields.forEach(field => {
            fieldsToTouch[field] = true;
            if (errors[field]) {
                isStepValid = false;
            }
        });

        if (!isStepValid) {
            setTouched(prev => ({ ...prev, ...fieldsToTouch }));
            alert('Please complete all required fields correctly before continuing.');
            return;
        }
        setStep(prev => Math.min(prev + 1, 3));
    };
    const handleBack = () => setStep(prev => Math.max(prev - 1, 1));

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        if (!isFormValid) {
            const allFields = Object.keys(initialFormData) as (keyof FormData)[];
            const allTouched = allFields.reduce((acc, key) => ({...acc, [key]: true}), {});
            setTouched(allTouched);
            alert("Some fields contain invalid or incomplete data. Please correct them before saving.");
            return;
        }
        onSave(formData, { photo: photoFile, pdf: pdfFile });
        resetForm();
    };

    const handleSubmitAndPay = (e: FormEvent) => {
        e.preventDefault();
         if (!isFormValid) {
            const allFields = Object.keys(initialFormData) as (keyof FormData)[];
            const allTouched = allFields.reduce((acc, key) => ({...acc, [key]: true}), {});
            setTouched(allTouched);
            alert("Some fields contain invalid or incomplete data. Please correct them before saving.");
            return;
        }
        onSaveAndPay(formData, { photo: photoFile, pdf: pdfFile });
        resetForm();
    };

    const resetForm = () => {
        setFormData(initialFormData);
        setPhotoPreview(null);
        setPdfFile(null);
        setPhotoFile(null);
        setStep(1);
        setTouched({});
    };

    if (!isOpen) return null;

    const steps = [
        { name: 'Client Information', icon: <UserGroupIcon className="w-5 h-5" /> },
        { name: 'Acquisition Details', icon: <BuildingLibraryIcon className="w-5 h-5" /> },
        { name: 'Office Details', icon: <BriefcaseIcon className="w-5 h-5" /> },
    ];

    const isPropertyAvailable = properties && properties.length > 0;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" aria-modal="true" role="dialog">
            <div className="bg-gray-50 dark:bg-gray-900 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">{editingClient ? 'Edit Client Details' : 'New Client Registration'}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                    <nav aria-label="Progress">
                         <ol role="list" className="flex items-center">
