    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const { properties } = useProperties();
    const { saveClient } = useClients();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [paymentForcedType, setPaymentForcedType] = useState<'Land' | 'Indenture' | 'Commission' | undefined>();

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    const [originalPrice, setOriginalPrice] = useState('0');
    const [discountValue, setDiscountValue] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [installmentCount, setInstallmentCount] = useState('1');

    const financialSummary = useMemo(() => {
        const P_orig = parseFloat(originalPrice) || 0;
        const D_val = parseFloat(discountValue) || 0;
        const I_count = parseInt(installmentCount) || 1;

        const discountAmount = discountType === 'percentage' 
            ? P_orig * (D_val / 100) 
            : D_val;

        const priceAfterDiscount = Math.max(0, P_orig - discountAmount);
        const emiAmount = I_count > 1 ? priceAfterDiscount / I_count : 0;
        const priceDueToEmi = priceAfterDiscount; 

        const totalPaid = selectedClient?.payment.paid || 0;
        const outstandingBalance = Math.max(0, priceDueToEmi - totalPaid);

        const location = selectedClient?.location || '—';
        const plotNumbers = selectedClient?.plot || '—';
        const numberOfPlots = plotNumbers !== '—' && plotNumbers !== 'N/A' ? plotNumbers.split(',').length : 0;
        const pricePerPlot = numberOfPlots > 0 ? P_orig / numberOfPlots : 0;

        return {
            originalPrice: P_orig,
            location,
            plotNumbers,
            numberOfPlots,
            pricePerPlot,
            discountApplied: discountAmount > 0 ? 'Yes' : 'No',
            discountLabel: discountType === 'percentage' ? `${D_val}%` : formatCurrency(D_val),
            discountAmount,
            priceAfterDiscount,
            emiApplied: I_count > 1 ? 'Yes' : 'No',
            emiAmount,
            installmentCount: I_count,
            priceDueToEmi,
            totalPaid,
            outstandingBalance
        };
    }, [originalPrice, discountValue, discountType, installmentCount, selectedClient]);

    useEffect(() => {
        if (selectedClient && !selectedClient.payment.isInitialized) {
            const property = properties.find(p => p.location === selectedClient.location);
            if (property) setOriginalPrice(String(property.price));
        } else if (selectedClient?.payment.isInitialized) {
            setOriginalPrice(String(selectedClient.payment.total));
        }
    }, [selectedClient, properties]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient || isSaving) return;

        setIsSaving(true);
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: financialSummary.priceDueToEmi,
                balance: financialSummary.outstandingBalance,
                planType: financialSummary.emiApplied === 'Yes' ? `${financialSummary.installmentCount}-Month EMI` : 'Outright'
            }
        } as Client;

        try {
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
        } finally {
            setIsSaving(false);
        }
    };

    const isReadOnly = !!selectedClient?.payment?.isInitialized && !isUnlocked;

    const SummaryRow: React.FC<{ label: string; value: string | number; isNegative?: boolean; isHighlight?: boolean }> = ({ label, value, isNegative, isHighlight }) => (
        <div className={`flex justify-between items-center py-3 border-b border-gray-100 dark:border-gray-700 last:border-0 ${isHighlight ? 'bg-indigo-50/30 dark:bg-indigo-900/10 px-2 rounded' : ''}`}>
            <span className="text-sm font-medium text-gray-500 uppercase tracking-widest leading-none">{label}</span>
            <span className={`text-sm font-black tracking-tight ${isNegative ? 'text-red-600' : isHighlight ? 'text-indigo-700 dark:text-indigo-300' : 'text-gray-900 dark:text-white'}`}>
                {value}
            </span>
        </div>
    );

    const isClientListEmpty = !clients || clients.length === 0;

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">Active Payment Summary</h2>
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-4 space-y-4 overflow-y-auto scrollbar-thin">
                    {!fixedClient && (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1 font-bold uppercase text-[10px] tracking-widest">Client Account</label>
                            <button
                                type="button"
                                disabled={isClientListEmpty}
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className={`flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm text-gray-900 dark:text-white ${isClientListEmpty ? 'cursor-not-allowed opacity-60' : 'cursor-pointer'}`}
                            >
                                <span className="truncate">
                                    {isClientListEmpty 
                                        ? 'No clients available' 
                                        : (selectedClient ? selectedClient.name : '-- Select Account --')}
                                </span>
                                <ChevronDownIcon className={`w-4 h-4 text-gray-400 transition-transform ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                            </button>
                            {isClientDropdownOpen && (
                                <div className="absolute left-0 right-0 mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-xl z-50 max-h-60 overflow-y-auto scrollbar-thin">
                                    {clients.map(client => (
                                        <button key={client.id} type="button" onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }} className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 dark:hover:bg-indigo-900/30 border-b border-gray-50 dark:border-gray-700 last:border-0 ${selectedClientId === client.id ? 'bg-indigo-50 font-semibold text-indigo-700' : 'text-gray-700 dark:text-gray-300'}`}>{client.name}</button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <div className="space-y-4">
                            <Card title="Ledger Input" className="p-4 border-dashed border-2">
                                <div className="space-y-4">
                                    <Input label="Base Land Price (GHC)" type="number" value={originalPrice} onChange={e => setOriginalPrice(e.target.value)} readOnly={isReadOnly} />
                                    <div className="grid grid-cols-2 gap-2">
                                        <Input label="Discount" type="number" value={discountValue} onChange={e => setDiscountValue(e.target.value)} readOnly={isReadOnly} />
                                        <Select label="Type" value={discountType} onChange={e => setDiscountType(e.target.value as any)} disabled={isReadOnly}>
                                            <option value="percentage">%</option>
                                            <option value="fixed">GHC</option>
                                        </Select>
                                    </div>
                                    <Input label="Term (Months)" type="number" value={installmentCount} onChange={e => setInstallmentCount(e.target.value)} readOnly={isReadOnly} min="1" max="12" />
                                </div>
                            </Card>
                            <Button variant="success" onClick={() => setPaymentModalOpen(true)} className="w-full py-4 font-black uppercase tracking-widest shadow-lg" icon={<BanknotesIcon className="w-6 h-6" />}>Record Payment</Button>
                        </div>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {selectedClient ? (
                        <div className="max-w-4xl mx-auto">
                            <Card className="border-l-4 border-l-green-500 bg-white dark:bg-gray-800 shadow-xl p-0 overflow-hidden">
                                <div className="px-6 py-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/20 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <ChartPieIcon className="w-6 h-6 text-green-600" />
                                        <h3 className="text-sm font-black uppercase tracking-widest text-gray-700 dark:text-gray-200">Active Ledger Summary</h3>
                                    </div>
                                    <Badge variant={financialSummary.outstandingBalance <= 0 && financialSummary.totalPaid > 0 ? 'success' : 'warning'}>
                                        {financialSummary.outstandingBalance <= 0 && financialSummary.totalPaid > 0 ? 'Settled' : 'Active Account'}
                                    </Badge>
                                </div>

                                <div className="p-6 space-y-1">
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 p-4 bg-green-50/20 dark:bg-green-900/10 rounded-xl border border-green-100 dark:border-green-900/30">
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Settlement Agreement</p>
                                            <p className="text-xl font-black text-gray-900 dark:text-white">{formatCurrency(financialSummary.priceDueToEmi)}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Total Paid</p>
                                            <p className="text-xl font-black text-green-600">{formatCurrency(financialSummary.totalPaid)}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Outstanding</p>
                                            <p className="text-xl font-black text-red-600">{formatCurrency(financialSummary.outstandingBalance)}</p>
                                        </div>
                                    </div>

                                    <div className="space-y-0 pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Additional Contract Context</h4>

                                        <SummaryRow label="Original Base Price" value={formatCurrency(financialSummary.originalPrice)} />
                                        <SummaryRow label="Property Location" value={financialSummary.location || '—'} />
                                        <SummaryRow label="Number of Plots" value={financialSummary.numberOfPlots || '—'} />
                                        <SummaryRow label="Price Per Plot" value={formatCurrency(financialSummary.pricePerPlot)} />
                                        <SummaryRow label="Discount Applied" value={financialSummary.discountApplied} />
                                        <SummaryRow label="Discount Value" value={financialSummary.discountLabel} isNegative={financialSummary.discountApplied === 'Yes'} />
                                        <SummaryRow label="EMI Calculation" value={financialSummary.emiApplied === 'Yes' ? `${formatCurrency(financialSummary.emiAmount)} / mo` : 'Not Applicable'} />
                                        <SummaryRow label="New Price After EMI" value={formatCurrency(financialSummary.priceDueToEmi)} isHighlight={true} />
                                        <SummaryRow label="Amount Paid" value={formatCurrency(financialSummary.totalPaid)} />
                                        <SummaryRow label="Outstanding Balance" value={formatCurrency(financialSummary.outstandingBalance)} isNegative={financialSummary.outstandingBalance > 0} />
                                    </div>
                                </div>

                                <div className="px-6 py-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-between items-center">
                                    <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                        <LockClosedIcon className="w-3 h-3" />
                                        System-Generated Record
                                    </div>
                                    <div className="flex gap-3">
                                        {isReadOnly ? (
                                            <Button variant="ghost" size="sm" onClick={() => setAuthModalOpen(true)} icon={<LockClosedIcon className="w-4 h-4" />}>
                                                Amendment Mode
                                            </Button>
                                        ) : (
                                            <Button size="sm" onClick={handleFormSubmit} isLoading={isSaving} icon={<CheckCircleIcon className="w-4 h-4" />}>
                                                Commit Ledger
                                            </Button>
                                        )}
                                    </div>
                                </div>
                            </Card>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50 p-10 text-center">
                            <UserCheckIcon className="w-16 h-16 mb-4" />
                            <p className="text-lg font-bold uppercase tracking-widest">
                                {isClientListEmpty ? 'Database is Empty' : 'Select Account to Display Summary'}
                            </p>
                            <p className="text-xs mt-1">
                                {isClientListEmpty 
                                    ? 'No client accounts found. Register a new client to begin.' 
                                    : 'Select a client from the left sidebar to view the immutable summary.'}
                            </p>
                        </div>
                    )}
                </div>
            </div>

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            <RecordPaymentModal 
                isOpen={isPaymentModalOpen} 
                onClose={() => setPaymentModalOpen(false)} 
                client={selectedClient!}
                forcedType={paymentForcedType}
                onSave={(data) => {
                    onRecordPayment(selectedClient!, data);
                    setPaymentModalOpen(false);
                }}
            />
        </div>
    );
};

const setAuthModalOpen = (val: boolean) => {};

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification, RescheduleDetails } from '../types';
import { 
    MagnifyingGlassIcon, 
    PencilIcon,
    ChartBarIcon,
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    CheckCircleIcon,
    LockClosedIcon,
    ChevronRightIcon,
    BanknotesIcon,
    DocumentTextIcon,
    ShieldCheckIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select } from '../components/ui/Input';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { useAuth } from '../context/AuthContext';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ clients, onSaveClient, currentStaff, roles, setActivePage }) => {
  const [selectedClientId, setSelectedClientId] = useState<number | null>(null);
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');

  // Internal state for "Payment Details" form
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isSaving, setIsSaving] = useState(false);

  const selectedClient = useMemo(() => clients.find(c => c.id === selectedClientId), [clients, selectedClientId]);
  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);

  // Financial Constants Sourced from selected client/property
  const originalPricePerPlot = 250000; // Mock base from properties logic
  const discountAmount = selectedClient?.payment.promoDetails ? 25000 : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  // EMI Logic Calculation (Rule E.2.C)
  const emiBreakdown = useMemo(() => {
    let months = 1;
    if (installmentOption === '3 Months') months = 3;
    else if (installmentOption === '6 Months') months = 6;
    else if (installmentOption === '12 Months') months = 12;

    if (installmentOption === 'Outright') return null;

    return {
      monthlyAmount: priceAfterDiscount / months,
      installments: months,
      totalPayable: priceAfterDiscount
    };
  }, [installmentOption, priceAfterDiscount]);

  const handleInitialSave = async () => {
    if (!selectedClient) return;
    setIsSaving(true);

    const updatedClient = {
        ...selectedClient,
        payment: {
            ...selectedClient.payment,
            isInitialized: true, // Custom flag to lock UI
            planType: installmentOption,
            total: priceAfterDiscount,
            balance: priceAfterDiscount - selectedClient.payment.paid
        }
    };

    await onSaveClient(updatedClient);
    setIsSaving(false);
  };

  const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

  return (
    <div className="flex flex-col h-[calc(100vh-120px)] animate-in fade-in duration-500">
      {/* Top Search & Client Selector */}
      <div className="flex justify-between items-center mb-6 bg-white dark:bg-gray-800 p-4 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm">
        <div className="flex items-center gap-4 flex-1">
          <div className="w-64">
            <Select 
              label="Active Account Selection" 
              value={selectedClientId || ''} 
              onChange={(e) => setSelectedClientId(Number(e.target.value))}
            >
              <option value="">-- Select Client --</option>
              {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>
          </div>
          {selectedClient && (
            <div className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-100 dark:border-blue-800">
              <UserCircleIcon className="w-5 h-5 text-blue-600" />
              <span className="text-sm font-bold text-blue-700 dark:text-blue-300">{selectedClient.name}</span>
            </div>
          )}
        </div>
      </div>

      <div className="flex-grow flex gap-6 overflow-hidden">
        {/* SIDEBAR NAVIGATION (Rule E.1) */}
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col overflow-hidden shrink-0">
          <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/50">
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Sub-Modules</p>
          </div>
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ChartBarIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        {/* CONTENT AREA */}
        <div className="flex-grow overflow-y-auto scrollbar-thin pr-2">
          {!selectedClient ? (
            <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40">
              <ShieldCheckIcon className="w-16 h-16 text-gray-300 mb-4" />
              <p className="text-xl font-black uppercase text-gray-400">Select a Client to Open Ledger</p>
            </div>
          ) : activeSubModule === 'overview' ? (
            <div className="space-y-6">
              {/* Rule E.2.A: Active Account Ledger (Top Section) */}
              <Card title="Active Account Ledger">
                <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                  <div>
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Property Location</p>
                    <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.location || '—'}</p>
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Number of Plots</p>
                    <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.plot.split(',').length}</p>
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Price Per Plot</p>
                    <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(originalPricePerPlot)}</p>
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Discount Applied</p>
                    <Badge variant={discountAmount > 0 ? 'success' : 'neutral'}>{discountAmount > 0 ? 'YES' : 'NO'}</Badge>
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">EMI Option Selected</p>
                    <Badge variant="info">{selectedClient.payment.planType || 'N/A'}</Badge>
                  </div>
                </div>

                {/* Rule E.2.B: Save Payment Details Button */}
                <div className="mt-8 border-t border-gray-100 dark:border-gray-700 pt-6">
                    <Button 
                        onClick={handleInitialSave}
                        disabled={!!(selectedClient.payment as any).isInitialized}
                        isLoading={isSaving}
                        icon={<CheckCircleIcon className="w-5 h-5" />}
                        className="w-full md:w-auto px-12"
                    >
                        {(selectedClient.payment as any).isInitialized ? 'Payment Structure Locked' : 'Save Payment Details'}
                    </Button>
                    {(selectedClient.payment as any).isInitialized && (
                        <p className="text-xs text-gray-400 mt-2 italic flex items-center gap-1">
                            <LockClosedIcon className="w-3 h-3" /> Initial save complete. Fields are now read-only.
                        </p>
                    )}
                </div>
              </Card>

              {/* Rule E.2.C: Payment Details Section */}
              <Card title="Payment Details">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <Input 
                    label="Original Price Per Plot" 
                    value={formatCurrency(originalPricePerPlot)} 
                    readOnly 
                    className="bg-gray-50 font-bold" 
                  />
                  <Input 
                    label="Price After Discount" 
                    value={formatCurrency(priceAfterDiscount)} 
                    readOnly 
                    className="bg-gray-50 font-bold text-green-600" 
                  />
                  <Select 
                    label="Installment Options*" 
                    value={installmentOption} 
                    onChange={(e) => setInstallmentOption(e.target.value)}
                    disabled={!!(selectedClient.payment as any).isInitialized}
                  >
                    <option>Outright</option>
                    <option>3 Months</option>
                    <option>6 Months</option>
                    <option>12 Months</option>
                    <option>Other</option>
                  </Select>
                </div>

                {/* EMI Breakdown Logic (Rule E.2.C Behavior) */}
                {emiBreakdown && (
                  <div className="mt-8 p-6 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-100 dark:border-blue-800 animate-in slide-in-from-top-2">
                    <h4 className="text-xs font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <BanknotesIcon className="w-4 h-4" /> EMI Calculation Results
                    </h4>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div>
                            <p className="text-[10px] font-black text-blue-400 uppercase">Monthly Amount</p>
                            <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(emiBreakdown.monthlyAmount)}</p>
                        </div>
                        <div>
                            <p className="text-[10px] font-black text-blue-400 uppercase">Installments</p>
                            <p className="text-xl font-black text-blue-700 dark:text-blue-300">{emiBreakdown.installments} Months</p>
                        </div>
                        <div>
                            <p className="text-[10px] font-black text-blue-400 uppercase">Total Payable</p>
