          ) : (
            /* Rule E.3: HISTORY SUB-MODULE */
            <div className="space-y-6">
                <Card title="Transactional History Ledger" action={
                    <Button 
                        variant="secondary" 
                        size="sm" 
                        disabled={!isCEO}
