                                    <Th>Actual Date</Th>
                                    <Th className="text-right">Amount Due</Th>
                                    <Th className="text-right">Amount Paid</Th>
                                    <Th className="text-center">Status</Th>
                                    <Th className="text-right">Balance</Th>
                                </tr>
                            </Thead>
                            <Tbody>
                                {selectedClient.payment.paymentHistory.length === 0 ? (
                                    <Tr>
                                        <Td colSpan={6} className="text-center py-12 text-gray-400 italic">No payments recorded in history.</Td>
                                    </Tr>
                                ) : (
                                    selectedClient.payment.paymentHistory.map((txn, i) => {
                                        const isOverdue = new Date(txn.date) > new Date(selectedClient.payment.dueDate);
                                        return (
                                            <Tr key={txn.id}>
