                                                    <Badge variant={isOverdue ? 'danger' : 'success'}>
                                                        {isOverdue ? 'OVERDUE' : 'ON TRACK'}
                                                    </Badge>
                                                </Td>
                                                <Td className="text-right font-black text-gray-900 dark:text-white">
                                                    {formatCurrency(selectedClient.payment.balance)}
                                                </Td>
                                            </Tr>
                                        );
                                    })
                                )}
                            </Tbody>
                        </table>
                    </TableContainer>
                    {!isCEO && (
                        <p className="text-[10px] text-red-500 mt-4 font-bold uppercase flex items-center gap-1">
                            <ShieldCheckIcon className="w-3 h-3" /> Note: Only the CEO account is permitted to amend financial structures.
                        </p>
                    )}
                </Card>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

