interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    invoices, clients, onSaveClient, onSaveInvoice, 
    clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage 
}) => {
  const [viewMode, setViewMode] = useState<'list' | 'editor' | 'reports' | 'alerts'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(null);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);

  // Local form state for new account details
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isSaving, setIsSaving] = useState(false);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (clientForInvoice?.id || selectedClientId))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);
  const canMakePayment = useMemo(() => {
    // Logic for payment permissions
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  // Financial Constants derived from selected client context
  const originalPricePerPlot = 250000; 
  const discountAmount = selectedClient?.payment.promoDetails ? 25000 : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const emiBreakdown = useMemo(() => {
    if (installmentOption === 'Outright') return null;
    let months = parseInt(installmentOption) || 1;
    return {
      monthlyAmount: priceAfterDiscount / months,
      installments: months,
      totalPayable: priceAfterDiscount
    };
  }, [installmentOption, priceAfterDiscount]);

  // Payment Aggregation Logic (Rule E.5)
  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land'; // Fallback for legacy data
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async () => {
    if (!selectedClient) return;
    setIsSaving(true);

    const updatedClient = {
        ...selectedClient,
        payment: {
            ...selectedClient.payment,
            isInitialized: true,
            planType: installmentOption,
            total: priceAfterDiscount,
            balance: priceAfterDiscount - selectedClient.payment.paid
        }
    };

    await onSaveClient(updatedClient);
    setIsSaving(false);
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: client.payment.paid + newTransaction.amount,
            balance: client.payment.balance - newTransaction.amount,
        }
    };

    await onSaveClient(updatedClient);
    setIsPaymentModalOpen(false);
  };

  const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

  // Existing Notification Logic
  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);
  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = useMemo(() => roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff', [roles, currentStaff]);
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  if (viewMode === 'reports') return <FinancialReportsView onBack={() => setViewMode('list')} clients={clients} staffList={[]} />;

  return (
    <div className="flex flex-col h-[calc(100vh-120px)] space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Bookkeeping ledger and client transaction history.</p>
