                            <Button 
                                variant="secondary" 
                                size="sm" 
                                disabled={!isCEO}
                                onClick={() => setActivePage('Amendment Form', selectedClient)}
                                icon={<ShieldCheckIcon className="w-4 h-4" />}
                                title={!isCEO ? "CEO Authorization Required" : "Open Amendment Interface"}
                            >
                                Authorize Amendment
                            </Button>
                        </div>
                    }>
                        <TableContainer className="border-0 shadow-none">
                            <table className="w-full text-sm text-left">
                                <Thead>
                                    <tr>
                                        <Th>Type</Th>
                                        <Th>Expected Date</Th>
                                        <Th>Actual Date</Th>
                                        <Th className="text-right">Amount Paid</Th>
                                        <Th className="text-center">Status</Th>
                                        <Th className="text-right">Balance</Th>
                                    </tr>
                                </Thead>
                                <Tbody>
                                    {selectedClient.payment.paymentHistory.length === 0 ? (
                                        <Tr>
                                            <Td colSpan={6} className="text-center py-12 text-gray-400 italic">No historical transactions found for this account.</Td>
                                        </Tr>
                                    ) : (
                                        selectedClient.payment.paymentHistory.map((txn, idx) => {
                                            const isOverdue = new Date(txn.date) > new Date(selectedClient.payment.dueDate);
                                            const isFuture = new Date(txn.date) > new Date();
                                            return (
                                                <Tr key={txn.id || idx}>
                                                    <Td className="font-bold text-gray-600 dark:text-gray-400">
                                                        {(txn as any).type || 'Land'}
                                                    </Td>
                                                    <Td className="text-gray-500 font-medium">{selectedClient.payment.dueDate || '—'}</Td>
                                                    <Td className="font-bold text-gray-900 dark:text-white">{txn.date || '—'}</Td>
                                                    <Td className="text-right font-black text-green-600">{formatCurrency(txn.amount)}</Td>
                                                    <Td className="text-center">
                                                        <Badge variant={isFuture ? 'info' : (isOverdue ? 'danger' : 'success')}>
                                                            {isFuture ? 'SCHEDULED' : (isOverdue ? 'OVERDUE' : 'ON TRACK')}
                                                        </Badge>
                                                    </Td>
                                                    <Td className="text-right font-black text-gray-900 dark:text-white">
                                                        {formatCurrency(selectedClient.payment.total - selectedClient.payment.paymentHistory.slice(0, idx + 1).reduce((s,t)=>s+t.amount,0))}
                                                    </Td>
                                                </Tr>
                                            );
                                        })
                                    )}
                                </Tbody>
                            </table>
                        </TableContainer>

                        {/* Running Totals (Rule E.5) */}
                        <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4 border-t border-gray-100 dark:border-gray-700 pt-6">
                            <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-100 dark:border-blue-900/50">
                                <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Total Land Payments Made</p>
                                <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(paymentAggregation.land)}</p>
                            </div>
                            <div className="p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-xl border border-emerald-100 dark:border-emerald-900/50">
                                <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Total Indenture Payments Made</p>
                                <p className="text-xl font-black text-emerald-700 dark:text-emerald-300">{formatCurrency(paymentAggregation.indenture)}</p>
                            </div>
                        </div>

                        {!isCEO && (
                            <div className="mt-4 p-3 bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-900/50 rounded flex items-center gap-2">
                                <ShieldCheckIcon className="w-4 h-4 text-red-600" />
                                <span className="text-[10px] text-red-600 dark:text-red-400 font-bold uppercase">Security Protocol: Financial amendments restricted to CEO level access only.</span>
                            </div>
                        )}
                    </Card>
                </div>
            )}
        </div>

        {/* MAKE PAYMENT MODAL (Rule E.2) */}
        {selectedClient && (
            <RecordPaymentModal 
                isOpen={isPaymentModalOpen} 
                onClose={() => setIsPaymentModalOpen(false)} 
                client={selectedClient}
                onSave={(data) => handleRecordPayment(selectedClient, data)}
            />
        )}
    </div>
  );
};

export default AccountManagementPage;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification, RescheduleDetails } from '../types';
import { 
    MagnifyingGlassIcon, 
    DocumentPlusIcon, 
    PencilIcon,
    ChartBarIcon,
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    CheckCircleIcon,
    LockClosedIcon,
    ChevronRightIcon,
    BanknotesIcon,
    ShieldCheckIcon,
    DocumentTextIcon,
    PlusCircleIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select } from '../components/ui/Input';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { RecordPaymentModal } from '../components/FinancialRecordEditor';
import { FinancialReportsView } from '../components/FinancialReportsView';
import { NotificationCenter } from '../components/NotificationCenter';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useAuth } from '../context/AuthContext';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    invoices, clients, onSaveClient, onSaveInvoice, 
    clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage 
}) => {
  const [viewMode, setViewMode] = useState<'list' | 'editor' | 'reports' | 'alerts'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(null);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);

  // Local form state for new account details
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [isSaving, setIsSaving] = useState(false);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (clientForInvoice?.id || selectedClientId))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);
  const canMakePayment = useMemo(() => {
    // Logic for payment permissions
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  // Financial Constants derived from selected client context
  const originalPricePerPlot = 250000; 
  const discountAmount = selectedClient?.payment.promoDetails ? 25000 : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const emiBreakdown = useMemo(() => {
    if (installmentOption === 'Outright') return null;
    let months = parseInt(installmentOption) || 1;
    return {
      monthlyAmount: priceAfterDiscount / months,
      installments: months,
      totalPayable: priceAfterDiscount
    };
  }, [installmentOption, priceAfterDiscount]);

  // Payment Aggregation Logic (Rule E.5)
  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land'; // Fallback for legacy data
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async () => {
    if (!selectedClient) return;
    setIsSaving(true);

    const updatedClient = {
        ...selectedClient,
        payment: {
            ...selectedClient.payment,
            isInitialized: true,
            planType: installmentOption,
            total: priceAfterDiscount,
            balance: priceAfterDiscount - selectedClient.payment.paid
        }
    };

    await onSaveClient(updatedClient);
    setIsSaving(false);
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: client.payment.paid + newTransaction.amount,
            balance: client.payment.balance - newTransaction.amount,
        }
    };

    await onSaveClient(updatedClient);
    setIsPaymentModalOpen(false);
  };

  const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

  // Existing Notification Logic
  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);
  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = useMemo(() => roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff', [roles, currentStaff]);
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  if (viewMode === 'reports') return <FinancialReportsView onBack={() => setViewMode('list')} clients={clients} staffList={[]} />;

  return (
    <div className="flex flex-col h-[calc(100vh-120px)] space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Bookkeeping ledger and client transaction history.</p>
        </div>
        <div className="flex gap-3">
          <Button 
            variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
            onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
            icon={<BellIcon className="w-5 h-5" />}
            className="relative"
          >
              Role Alerts
              {roleAlerts.length > 0 && (
                  <span className="absolute -top-1 -right-1 flex h-4 w-4">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                  </span>
              )}
          </Button>
          <Button variant="secondary" onClick={() => setViewMode('reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
              Reconciliation
          </Button>
        </div>
      </div>

      <div className="flex-grow flex gap-6 overflow-hidden">
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
             <Select 
              label="Select Client Account" 
              value={selectedClientId || ''} 
              onChange={(e) => {
                  setSelectedClientId(Number(e.target.value));
                  setClientForInvoice(null);
              }}
            >
              <option value="">-- Choose Client --</option>
              {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>
          </div>
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName}
                    onReschedule={() => {}}
                    onMarkRead={(id) => setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">Select a Client to Load Ledger</p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <Card title="Active Account Ledger">
                        <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Property Location</p>
                                <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.location || '—'}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Number of Plots</p>
                                <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.plot.split(',').length}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Price Per Plot</p>
                                <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(originalPricePerPlot)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Discount Applied</p>
                                <Badge variant={discountAmount > 0 ? 'success' : 'neutral'}>{discountAmount > 0 ? 'YES' : 'NO'}</Badge>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">EMI Selection</p>
                                <Badge variant="info">{selectedClient.payment.planType || 'N/A'}</Badge>
                            </div>
                        </div>

                        <div className="mt-8 border-t border-gray-100 dark:border-gray-700 pt-6">
                            <Button 
                                onClick={handleInitialSave}
                                disabled={!!(selectedClient.payment as any).isInitialized}
                                isLoading={isSaving}
                                icon={<CheckCircleIcon className="w-5 h-5" />}
                                className="w-full md:w-auto px-12 py-3"
                            >
                                {(selectedClient.payment as any).isInitialized ? 'Details Locked' : 'Save Payment Details'}
                            </Button>
                        </div>
                    </Card>

                    <Card title="Payment Details">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <Input label="Original Price Per Plot" value={formatCurrency(originalPricePerPlot)} readOnly className="bg-gray-50 font-bold" />
                            <Input label="Price After Discount" value={formatCurrency(priceAfterDiscount)} readOnly className="bg-gray-50 font-bold text-green-600" />
                            <Select 
                                label="Installment Options*" 
                                value={installmentOption} 
                                onChange={(e) => setInstallmentOption(e.target.value)}
                                disabled={!!(selectedClient.payment as any).isInitialized}
                            >
                                <option value="Outright">Outright</option>
                                <option value="3">3 Months</option>
                                <option value="6">6 Months</option>
                                <option value="12">12 Months</option>
                            </Select>
                        </div>

                        {emiBreakdown && (
                            <div className="mt-8 p-6 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-100 dark:border-blue-800 animate-in slide-in-from-top-2">
                                <h4 className="text-xs font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                    <BanknotesIcon className="w-4 h-4" /> EMI Calculation Breakdown
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                    <div>
                                        <p className="text-[10px] font-black text-blue-400 uppercase">Monthly Installment</p>
                                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(emiBreakdown.monthlyAmount)}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-black text-blue-400 uppercase">Term Length</p>
                                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{emiBreakdown.installments} Months</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-black text-blue-400 uppercase">Total Commitment</p>
                                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(emiBreakdown.totalPayable)}</p>
                                    </div>
                                </div>
                            </div>
                        )}
                    </Card>

                    {/* Live Balance Summary in Overview */}
                    <Card title="Current Ledger Standing" className="bg-gray-50/50 dark:bg-gray-900/20 border-dashed">
                         <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Contract Total</p>
                                <p className="text-2xl font-black text-gray-900 dark:text-white">{formatCurrency(selectedClient.payment.total)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Amount Paid</p>
                                <p className="text-2xl font-black text-green-600">{formatCurrency(selectedClient.payment.paid)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Outstanding Balance</p>
                                <p className={`text-2xl font-black ${selectedClient.payment.balance < 0 ? 'text-purple-600' : 'text-red-600'}`}>
                                    {formatCurrency(selectedClient.payment.balance)}
                                    {selectedClient.payment.balance < 0 && <span className="text-[10px] block uppercase text-purple-400 font-black">Account Overpaid</span>}
                                </p>
                            </div>
                        </div>
                    </Card>
                </div>
            ) : (
                /* HISTORY SUB-MODULE (Rule E.3) */
                <div className="space-y-6 animate-in fade-in duration-300">
                    <Card title="Transactional Ledger History" action={
                        <div className="flex gap-2">
                             <Button 
                                variant="primary" 
                                size="sm" 
                                disabled={!canMakePayment}
                                onClick={() => setIsPaymentModalOpen(true)}
                                icon={<PlusCircleIcon className="w-4 h-4" />}
                                title={!canMakePayment ? "Insufficient permissions to record payments" : "Post new payment"}
                            >
                                Make Payment
                            </Button>
                            <Button 
                                variant="secondary" 
                                size="sm" 
                                disabled={!isCEO}
                                onClick={() => setActivePage('Amendment Form', selectedClient)}
                                icon={<ShieldCheckIcon className="w-4 h-4" />}
                                title={!isCEO ? "CEO Authorization Required" : "Open Amendment Interface"}
                            >
                                Authorize Amendment
                            </Button>
                        </div>
                    }>
                        <TableContainer className="border-0 shadow-none">
                            <table className="w-full text-sm text-left">
                                <Thead>
                                    <tr>
                                        <Th>Type</Th>
                                        <Th>Expected Date</Th>
                                        <Th>Actual Date</Th>
                                        <Th className="text-right">Amount Paid</Th>
                                        <Th className="text-center">Status</Th>
                                        <Th className="text-right">Balance</Th>
                                    </tr>
                                </Thead>
                                <Tbody>
                                    {selectedClient.payment.paymentHistory.length === 0 ? (
                                        <Tr>
                                            <Td colSpan={6} className="text-center py-12 text-gray-400 italic">No historical transactions found for this account.</Td>
                                        </Tr>
                                    ) : (
                                        selectedClient.payment.paymentHistory.map((txn, idx) => {
                                            const isOverdue = new Date(txn.date) > new Date(selectedClient.payment.dueDate);
                                            const isFuture = new Date(txn.date) > new Date();
                                            return (
                                                <Tr key={txn.id || idx}>
                                                    <Td className="font-bold text-gray-600 dark:text-gray-400">
                                                        {(txn as any).type || 'Land'}
                                                    </Td>
                                                    <Td className="text-gray-500 font-medium">{selectedClient.payment.dueDate || '—'}</Td>
                                                    <Td className="font-bold text-gray-900 dark:text-white">{txn.date || '—'}</Td>
                                                    <Td className="text-right font-black text-green-600">{formatCurrency(txn.amount)}</Td>
                                                    <Td className="text-center">
                                                        <Badge variant={isFuture ? 'info' : (isOverdue ? 'danger' : 'success')}>
                                                            {isFuture ? 'SCHEDULED' : (isOverdue ? 'OVERDUE' : 'ON TRACK')}
                                                        </Badge>
                                                    </Td>
                                                    <Td className="text-right font-black text-gray-900 dark:text-white">
                                                        {formatCurrency(selectedClient.payment.total - selectedClient.payment.paymentHistory.slice(0, idx + 1).reduce((s,t)=>s+t.amount,0))}
                                                    </Td>
                                                </Tr>
                                            );
                                        })
                                    )}
                                </Tbody>
                            </table>
                        </TableContainer>

                        {/* Running Totals (Rule E.5) */}
                        <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4 border-t border-gray-100 dark:border-gray-700 pt-6">
                            <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-100 dark:border-blue-900/50">
                                <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Total Land Payments Made</p>
                                <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(paymentAggregation.land)}</p>
                            </div>
                            <div className="p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-xl border border-emerald-100 dark:border-emerald-900/50">
                                <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Total Indenture Payments Made</p>
                                <p className="text-xl font-black text-emerald-700 dark:text-emerald-300">{formatCurrency(paymentAggregation.indenture)}</p>
                            </div>
                        </div>

                        {!isCEO && (
                            <div className="mt-4 p-3 bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-900/50 rounded flex items-center gap-2">
                                <ShieldCheckIcon className="w-4 h-4 text-red-600" />
                                <span className="text-[10px] text-red-600 dark:text-red-400 font-bold uppercase">Security Protocol: Financial amendments restricted to CEO level access only.</span>
                            </div>
                        )}
                    </Card>
                </div>
            )}
        </div>

        {/* MAKE PAYMENT MODAL (Rule E.2) */}
        {selectedClient && (
            <RecordPaymentModal 
                isOpen={isPaymentModalOpen} 
                onClose={() => setIsPaymentModalOpen(false)} 
                client={selectedClient}
                onSave={(data) => handleRecordPayment(selectedClient, data)}
            />
        )}
    </div>
  );
};

