import { useActivityLogs, useStaff, useRoles } from '../../hooks/useAppData';
import { uploadFile } from '../../services/storageService';

const LeavePage: React.FC = () => {
    const { currentStaff } = useAuth();
    const { roles } = useRoles();
    const { addActivityLog } = useActivityLogs();

    // UI States
    const [isRequestModalOpen, setRequestModalOpen] = useState(false);
    const [viewingRequest, setViewingRequest] = useState<LeaveRequest | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Mock Data Persistence
    const [requests, setRequests] = useState<LeaveRequest[]>([
        {
            id: 'LR-101',
            employeeId: '1',
            employeeName: 'Araba CEO',
            type: 'Annual Leave',
            startDate: '2024-12-20',
            endDate: '2024-12-27',
            days: 5,
            reason: 'End of year family vacation.',
            status: 'Approved',
            requestDate: '2024-11-01',
            processedBy: 'System',
            processedDate: '2024-11-02'
        }
    ]);

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff?.roleId)?.name, [roles, currentStaff]);
    const isAdmin = userRole === 'CEO' || userRole === 'Administrator';

    const filteredRequests = useMemo(() => {
        if (isAdmin) return requests.sort((a, b) => new Date(b.requestDate).getTime() - new Date(a.requestDate).getTime());
        return requests.filter(r => r.employeeId === currentStaff?.id).sort((a, b) => new Date(b.requestDate).getTime() - new Date(a.requestDate).getTime());
    }, [requests, isAdmin, currentStaff]);

    const handleCreateRequest = async (data: any) => {
        setIsSubmitting(true);
        try {
            let attachmentUrl = '';
            if (data.file) {
                attachmentUrl = await uploadFile(data.file, `leave_requests/${currentStaff?.id}/${Date.now()}_${data.file.name}`);
            }

            const newRequest: LeaveRequest = {
                id: `LR-${Math.floor(Math.random() * 10000)}`,
                employeeId: currentStaff?.id || '0',
                employeeName: currentStaff?.fullName || 'Unknown',
                type: data.type as LeaveType,
                startDate: data.startDate,
                endDate: data.endDate,
                days: data.days,
                reason: data.reason,
                status: 'Pending',
                attachmentUrl,
                requestDate: new Date().toISOString().split('T')[0],
            };

            setRequests(prev => [newRequest, ...prev]);
            if (currentStaff) {
                addActivityLog('Create', `Submitted a ${newRequest.type} request for ${newRequest.days} days.`, currentStaff.id);
            }
            setRequestModalOpen(false);
        } catch (error) {
            alert('Failed to submit request. Please try again.');
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleProcessRequest = (id: string, newStatus: LeaveStatus) => {
        setRequests(prev => prev.map(r => 
            r.id === id ? { 
                ...r, 
                status: newStatus, 
                processedBy: currentStaff?.fullName, 
                processedDate: new Date().toISOString().split('T')[0] 
            } : r
        ));
        if (currentStaff) {
            addActivityLog('Update', `${newStatus} leave request ${id}.`, currentStaff.id);
        }
        setViewingRequest(null);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Leave Management</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">
                        {isAdmin ? 'Review and manage company-wide leave requests.' : 'Submit and track your leave applications.'}
                    </p>
                </div>
                <button 
                  onClick={() => setRequestModalOpen(true)} 
                  className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors"
                >
                    <PlusCircleIcon className="w-5 h-5" />
                    Request Leave
                </button>
            </div>

            <Card className="p-0 overflow-hidden">
                <TableContainer className="border-0 shadow-none">
                    <table className="w-full text-sm text-left">
                        <Thead>
                            <tr>
                                <Th>Employee</Th>
                                <Th>Leave Type</Th>
                                <Th>Duration</Th>
                                <Th>Days</Th>
                                <Th className="text-center">Status</Th>
                                <Th className="text-right">Actions</Th>
                            </tr>
                        </Thead>
                        <Tbody>
                            {filteredRequests.map(req => (
                                <Tr key={req.id}>
                                    <Td className="font-bold text-gray-900 dark:text-white">
                                        <div className="flex items-center gap-2">
                                            <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center text-blue-600 text-[10px]">
                                                {req.employeeName.substring(0,2).toUpperCase()}
                                            </div>
                                            {req.employeeName}
                                        </div>
                                    </Td>
                                    <Td>{req.type}</Td>
                                    <Td className="text-gray-500">
                                        <div className="flex flex-col">
                                            <span>{req.startDate}</span>
                                            <span className="text-[10px] text-gray-400 font-bold uppercase">to {req.endDate}</span>
                                        </div>
                                    </Td>
                                    <Td className="font-semibold">{req.days} days</Td>
                                    <Td className="text-center">
                                        <Badge variant={req.status === 'Approved' ? 'success' : req.status === 'Rejected' ? 'danger' : 'warning'}>
                                            {req.status}
                                        </Badge>
                                    </Td>
                                    <Td className="text-right">
                                        <button 
                                            onClick={() => setViewingRequest(req)}
                                            className="p-2 text-gray-400 hover:text-blue-600 transition-colors"
                                            title="View Details"
                                        >
                                            <EyeIcon className="w-5 h-5" />
                                        </button>
                                    </Td>
                                </Tr>
                            ))}
                            {filteredRequests.length === 0 && (
                                <Tr>
                                    <Td colSpan={6} className="py-20 text-center text-gray-400 italic">
                                        No leave requests found.
                                    </Td>
                                </Tr>
                            )}
                        </Tbody>
                    </table>
                </TableContainer>
            </Card>

            <RequestModal 
                isOpen={isRequestModalOpen} 
                onClose={() => setRequestModalOpen(false)} 
                onSubmit={handleCreateRequest}
                loading={isSubmitting}
            />

            <DetailModal 
                request={viewingRequest} 
                onClose={() => setViewingRequest(null)} 
                isAdmin={isAdmin}
                onAction={handleProcessRequest}
            />
        </div>
    );
};

const RequestModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    loading: boolean;
}> = ({ isOpen, onClose, onSubmit, loading }) => {
    const [formData, setFormData] = useState({
        type: 'Annual Leave',
        startDate: '',
        endDate: '',
        days: 0,
        reason: '',
        file: null as File | null
    });

    useEffect(() => {
        if (formData.startDate && formData.endDate) {
            const start = new Date(formData.startDate);
            const end = new Date(formData.endDate);
            const diffTime = Math.abs(end.getTime() - start.getTime());
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
            setFormData(prev => ({ ...prev, days: diffDays > 0 ? diffDays : 0 }));
        }
    }, [formData.startDate, formData.endDate]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
            {/* CONTAINER MODIFICATION: max-h-[90vh] ensures the modal fits viewport, flex-col allows internal layout */}
            <Card className="w-full max-w-xl p-0 overflow-hidden shadow-2xl animate-in zoom-in duration-200 flex flex-col max-h-[90vh]">
                <form onSubmit={(e) => { e.preventDefault(); onSubmit(formData); }} className="flex flex-col h-full overflow-hidden">
                    <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-900 shrink-0">
                        <h3 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            <CalendarDaysIcon className="w-5 h-5 text-blue-600" /> Application for Leave
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                    </div>

                    {/* SCROLLABLE CONTAINER: overflow-y-auto enables the scrollbar only for form fields */}
                    <div className="p-6 space-y-4 overflow-y-auto scrollbar-thin flex-grow bg-white dark:bg-gray-800">
                        <Select label="Leave Type*" value={formData.type} onChange={e => setFormData({...formData, type: e.target.value})} required>
                            <option>Annual Leave</option>
                            <option>Sick Leave</option>
                            <option>Casual Leave</option>
                            <option>Emergency Leave</option>
                            <option>Other</option>
                        </Select>
                        <div className="grid grid-cols-2 gap-4">
                            <Input label="Start Date*" type="date" value={formData.startDate} onChange={e => setFormData({...formData, startDate: e.target.value})} required />
                            <Input label="End Date*" type="date" value={formData.endDate} onChange={e => setFormData({...formData, endDate: e.target.value})} required />
                        </div>
                        <Input label="Total Days" type="number" value={formData.days} readOnly className="bg-gray-50 font-bold text-blue-600" />
                        <Textarea label="Reason for Leave*" rows={4} value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})} required placeholder="Provide context for your application..." />

                        <div className="pt-2">
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Supporting Document (Optional)</label>
                            <div className="flex items-center justify-center w-full">
                                <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-gray-300 border-dashed rounded-lg cursor-pointer bg-gray-50 dark:bg-gray-900 hover:bg-gray-100 dark:border-gray-600 dark:hover:bg-gray-800 transition-colors">
                                    <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                        <PaperClipIcon className="w-8 h-8 mb-3 text-gray-400" />
                                        <p className="mb-2 text-sm text-gray-500 dark:text-gray-400 font-semibold">{formData.file ? formData.file.name : 'Click to upload attachment'}</p>
                                        <p className="text-xs text-gray-500 dark:text-gray-400">PDF, PNG, JPG (MAX. 5MB)</p>
                                    </div>
                                    <input type="file" className="hidden" onChange={e => setFormData({...formData, file: e.target.files?.[0] || null})} />
                                </label>
                            </div>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-3 shrink-0">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit" isLoading={loading}>Submit Application</Button>
                    </div>
                </form>
            </Card>
            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 6px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #334155; }
            `}</style>
        </div>
    );
};

