const getStatusBadge = (status: string) => {
  let variant: 'success' | 'warning' | 'danger' | 'neutral' | 'purple' = 'neutral';
  switch (status) {
    case 'Paid': case 'Success': case 'Settled': case 'On Time': case 'Fully Paid': variant = 'success'; break;
    case 'Pending': variant = 'warning'; break;
    case 'Outstanding': case 'Overdue': case 'Failed': case 'Late': case 'Delayed': variant = 'danger'; break;
    case 'Expected': case 'Overpaid': variant = 'purple'; break;
  }
  return <Badge variant={variant}>{status}</Badge>;
};

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Verify Identity</h3>
                        <p className="text-xs text-gray-500 mt-1">Authorized personnel only: Re-authenticate to unlock financial fields.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 dark:bg-red-900/20 p-2 rounded border border-red-200 dark:border-red-800">{error}</div>}
                        <Input label="Staff Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="email@faim.com" />
                        <Input label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const RecordPaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSave: (payment: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    client: Client;
    forcedType?: 'Land' | 'Indenture' | 'Commission';
}> = ({ isOpen, onClose, onSave, client, forcedType }) => {
    const [amount, setAmount] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>(forcedType || 'Land');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [notes, setNotes] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            setAmount('');
            setDate(new Date().toISOString().split('T')[0]);
            setNotes('');
            setError('');
            if (forcedType) setType(forcedType);
        }
    }, [isOpen, forcedType]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const paidAmount = parseFloat(amount);

        if (!date) {
            setError('Payment date is required.');
            return;
        }
        if (isNaN(paidAmount) || paidAmount <= 0) {
            setError('Please enter a valid positive amount.');
            return;
        }

        const currentBalance = client.payment.balance;
        if (paidAmount > currentBalance) {
            setError(`Payment amount exceeds the outstanding balance of ${formatCurrency(currentBalance)}.`);
            return;
        }

        if (!receiptNumber.trim()) {
            setError('Receipt/Reference number is required.');
            return;
        }

        onSave({ date, amount: paidAmount, method, reference: receiptNumber, receiptNumber, type, notes } as any);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-md p-0 overflow-hidden shadow-2xl">
                <form onSubmit={handleSubmit}>
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                        <h2 className="text-lg font-black text-gray-800 dark:text-white uppercase tracking-tight">Make {type} Payment</h2>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
                          <XMarkIcon className="w-6 h-6" />
                        </button>
                    </div>
                    <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto bg-gray-50 dark:bg-gray-900">
                        {error && (
                          <div className="bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-200 p-3 rounded-md text-xs border border-red-200 dark:border-red-800 flex items-center gap-2">
                            <ExclamationTriangleIcon className="w-4 h-4 shrink-0" />
                            {error}
                          </div>
                        )}
                        <Select label="Payment Purpose*" value={type} onChange={e => setType(e.target.value as any)} disabled={!!forcedType}>
                            <option value="Land">Land Purchase Payment</option>
                            <option value="Indenture">Indenture / Documentation Payment</option>
                            <option value="Commission">Sales Commission Payment</option>
                        </Select>
                        <div className="grid grid-cols-2 gap-4">
                          <Input label="Payment Date*" type="date" value={date} onChange={e => setDate(e.target.value)} required />
                          <Input label="Amount (GHC)*" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" required className="no-spinner font-bold" />
                        </div>
                        <Input label="Receipt / Reference No.*" value={receiptNumber} onChange={e => setReceiptNumber(e.target.value)} placeholder="Enter unique ID" required />
                        <Select label="Payment Method*" value={method} onChange={e => setMethod(e.target.value as any)}>
                            <option value="Bank Transfer">Bank Transfer</option>
                            <option value="Cash">Cash</option>
                            <option value="MoMo">Mobile Money (MoMo)</option>
                            <option value="Cheque">Cheque</option>
                            <option value="Other">Other</option>
                        </Select>
                        <div className="space-y-1">
                          <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Internal Notes</label>
                          <textarea 
                            value={notes} 
                            onChange={e => setNotes(e.target.value)} 
                            placeholder="Add payment context..." 
                            className="w-full px-3 py-2 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-md text-sm focus:ring-2 focus:ring-blue-500 min-h-[80px]"
                          />
                        </div>
                    </div>
                    <div className="flex justify-end p-4 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit" icon={<CheckCircleIcon className="w-4 h-4" />}>Confirm Payment</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const { properties } = useProperties();
    const { saveClient } = useClients();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [activeTab, setActiveTab] = useState('overview');
    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [paymentForcedType, setPaymentForcedType] = useState<'Land' | 'Indenture' | 'Commission' | undefined>();

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    const [originalPrice, setOriginalPrice] = useState('0');
    const [discountValue, setDiscountValue] = useState('0');
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [installmentCount, setInstallmentCount] = useState('1');
    const [priceError, setPriceError] = useState<string>('');

    // BINDING RULE: Auto-populate latest published price for new/uninitialized accounts
    useEffect(() => {
        if (selectedClient && !selectedClient.payment.isInitialized) {
            // Find property in published catalog
            const propertyMatch = properties.find(p => p.location === selectedClient.location);

            if (propertyMatch) {
                // Determine if a price has actually been published in Purchase & Sale Management
                // (Using 'price' as the market/published value)
                if (propertyMatch.price > 0) {
                    setOriginalPrice(String(propertyMatch.price));
                    setPriceError('');
                } else {
                    setOriginalPrice('0');
                    setPriceError('Price not yet published for this location.');
                }
            } else {
                setOriginalPrice('0');
                setPriceError('Property details not found in strategic hub.');
            }
        } else if (selectedClient?.payment.isInitialized) {
            // HISTORICAL PRESERVATION RULE: Retain price active at time of creation
            setOriginalPrice(String(selectedClient.payment.total));
            setPriceError('');
        }
    }, [selectedClient, properties]);

    const financialSummary = useMemo(() => {
        const P_orig = parseFloat(originalPrice) || 0;
        const D_val = parseFloat(discountValue) || 0;
        const I_count = parseInt(installmentCount) || 1;

        const discountAmount = discountType === 'percentage' 
            ? P_orig * (D_val / 100) 
            : D_val;

        const priceAfterDiscount = Math.max(0, P_orig - discountAmount);
        const emiAmount = I_count > 1 ? priceAfterDiscount / I_count : 0;
        const priceDueToEmi = priceAfterDiscount; 

        const totalPaid = selectedClient?.payment.paid || 0;
        const outstandingBalance = Math.max(0, priceDueToEmi - totalPaid);

        const location = selectedClient?.location || '—';
        const plotNumbers = selectedClient?.plot || '—';
        const numberOfPlots = plotNumbers !== '—' && plotNumbers !== 'N/A' ? plotNumbers.split(',').length : 0;
        const pricePerPlot = numberOfPlots > 0 ? P_orig / numberOfPlots : 0;

        return {
            originalPrice: P_orig,
            location,
            plotNumbers,
            numberOfPlots,
            pricePerPlot,
            discountApplied: discountAmount > 0 ? 'Yes' : 'No',
            discountLabel: discountType === 'percentage' ? `${D_val}%` : formatCurrency(D_val),
            discountAmount,
            priceAfterDiscount,
            emiApplied: I_count > 1 ? 'Yes' : 'No',
            emiAmount,
            installmentCount: I_count,
            priceDueToEmi,
            totalPaid,
            outstandingBalance
        };
    }, [originalPrice, discountValue, discountType, installmentCount, selectedClient]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient || isSaving || priceError) return;

        setIsSaving(true);
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: financialSummary.priceDueToEmi,
                balance: financialSummary.outstandingBalance,
                planType: financialSummary.emiApplied === 'Yes' ? `${financialSummary.installmentCount}-Month EMI` : 'Outright'
            }
        } as Client;

        try {
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
        } finally {
            setIsSaving(false);
        }
    };

    // READ-ONLY RULE: Locked if initialized unless re-auth authorized
    const isReadOnly = !!selectedClient?.payment?.isInitialized && !isUnlocked;

    const SummaryRow: React.FC<{ label: string; value: string | number; isNegative?: boolean; isHighlight?: boolean }> = ({ label, value, isNegative, isHighlight }) => (
        <div className={`flex justify-between items-center py-3 border-b border-gray-100 dark:border-gray-700 last:border-0 ${isHighlight ? 'bg-indigo-50/30 dark:bg-indigo-900/10 px-2 rounded' : ''}`}>
            <span className="text-sm font-medium text-gray-500 uppercase tracking-widest leading-none">{label}</span>
            <span className={`text-sm font-black tracking-tight ${isNegative ? 'text-red-600' : isHighlight ? 'text-indigo-700 dark:text-indigo-300' : 'text-gray-900 dark:text-white'}`}>
                {value}
            </span>
        </div>
    );

    const isClientListEmpty = !clients || clients.length === 0;

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full hover:bg-gray-100"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">Active Payment Summary</h2>
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-4 space-y-4 overflow-y-auto scrollbar-thin">
                    {!fixedClient && (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1 font-bold uppercase text-[10px] tracking-widest">Client Account</label>
                            <button
                                type="button"
                                disabled={isClientListEmpty}
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className={`flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm text-sm text-gray-900 dark:text-white ${isClientListEmpty ? 'cursor-not-allowed opacity-60' : 'cursor-pointer'}`}
                            >
                                <span className="truncate">
                                    {isClientListEmpty 
                                        ? 'No clients available' 
                                        : (selectedClient ? selectedClient.name : '-- Select Account --')}
                                </span>
                                <ChevronDownIcon className={`w-4 h-4 text-gray-400 transition-transform ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                            </button>
                            {isClientDropdownOpen && (
                                <div className="absolute left-0 right-0 mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-xl z-50 max-h-60 overflow-y-auto scrollbar-thin">
                                    {clients.map(client => (
                                        <button key={client.id} type="button" onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }} className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 dark:hover:bg-indigo-900/30 border-b border-gray-50 dark:border-gray-700 last:border-0 ${selectedClientId === client.id ? 'bg-indigo-50 font-semibold text-indigo-700' : 'text-gray-700 dark:text-gray-300'}`}>{client.name}</button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <div className="space-y-4">
                            <Card title="Ledger Input" className="p-4 border-dashed border-2">
                                <div className="space-y-4">
                                    <div>
                                        <Input 
                                            label="Latest Published Price (GHC)" 
                                            type="number" 
                                            value={originalPrice} 
                                            onChange={e => setOriginalPrice(e.target.value)} 
                                            readOnly={isReadOnly} 
                                            error={priceError}
                                        />
                                        {priceError && (
                                            <div className="mt-1 flex items-center gap-1 text-[10px] text-amber-600 font-bold uppercase animate-pulse">
                                                <ExclamationTriangleIcon className="w-3 h-3" />
                                                Action Required: Check CEO Hub
                                            </div>
                                        )}
                                    </div>
                                    <div className="grid grid-cols-2 gap-2">
                                        <Input label="Discount" type="number" value={discountValue} onChange={e => setDiscountValue(e.target.value)} readOnly={isReadOnly} />
                                        <Select label="Type" value={discountType} onChange={e => setDiscountType(e.target.value as any)} disabled={isReadOnly}>
                                            <option value="percentage">%</option>
                                            <option value="fixed">GHC</option>
                                        </Select>
                                    </div>
                                    <Input label="Term (Months)" type="number" value={installmentCount} onChange={e => setInstallmentCount(e.target.value)} readOnly={isReadOnly} min="1" max="12" />
                                </div>
                            </Card>
                            <Button variant="success" onClick={() => setPaymentModalOpen(true)} className="w-full py-4 font-black uppercase tracking-widest shadow-lg" icon={<BanknotesIcon className="w-6 h-6" />}>Record Payment</Button>
                        </div>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {selectedClient ? (
                        <div className="max-w-4xl mx-auto">
                            <Card className="border-l-4 border-l-green-500 bg-white dark:bg-gray-800 shadow-xl p-0 overflow-hidden">
                                <div className="px-6 py-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/20 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <ChartPieIcon className="w-6 h-6 text-green-600" />
                                        <h3 className="text-sm font-black uppercase tracking-widest text-gray-700 dark:text-gray-200">Active Ledger Summary</h3>
                                    </div>
                                    <Badge variant={financialSummary.outstandingBalance <= 0 && financialSummary.totalPaid > 0 ? 'success' : 'warning'}>
                                        {financialSummary.outstandingBalance <= 0 && financialSummary.totalPaid > 0 ? 'Settled' : 'Active Account'}
                                    </Badge>
                                </div>

                                <div className="p-6 space-y-1">
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 p-4 bg-green-50/20 dark:bg-green-900/10 rounded-xl border border-green-100 dark:border-green-900/30">
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Settlement Agreement</p>
                                            <p className="text-xl font-black text-gray-900 dark:text-white">{formatCurrency(financialSummary.priceDueToEmi)}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Total Paid</p>
                                            <p className="text-xl font-black text-green-600">{formatCurrency(financialSummary.totalPaid)}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Outstanding</p>
                                            <p className="text-xl font-black text-red-600">{formatCurrency(financialSummary.outstandingBalance)}</p>
                                        </div>
                                    </div>

                                    <div className="space-y-0 pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Additional Contract Context</h4>

                                        <SummaryRow label="Original Base Price" value={formatCurrency(financialSummary.originalPrice)} />
                                        <SummaryRow label="Property Location" value={financialSummary.location || '—'} />
                                        <SummaryRow label="Number of Plots" value={financialSummary.numberOfPlots || '—'} />
                                        <SummaryRow label="Price Per Plot" value={formatCurrency(financialSummary.pricePerPlot)} />
                                        <SummaryRow label="Discount Applied" value={financialSummary.discountApplied} />
                                        <SummaryRow label="Discount Value" value={financialSummary.discountLabel} isNegative={financialSummary.discountApplied === 'Yes'} />
                                        <SummaryRow label="EMI Calculation" value={financialSummary.emiApplied === 'Yes' ? `${formatCurrency(financialSummary.emiAmount)} / mo` : 'Not Applicable'} />
                                        <SummaryRow label="New Price After EMI" value={formatCurrency(financialSummary.priceDueToEmi)} isHighlight={true} />
                                        <SummaryRow label="Amount Paid" value={formatCurrency(financialSummary.totalPaid)} />
                                        <SummaryRow label="Outstanding Balance" value={formatCurrency(financialSummary.outstandingBalance)} isNegative={financialSummary.outstandingBalance > 0} />
                                    </div>
                                </div>

                                <div className="px-6 py-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-between items-center">
                                    <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                        <LockClosedIcon className="w-3 h-3" />
                                        System-Generated Record
                                    </div>
                                    <div className="flex gap-3">
                                        {isReadOnly ? (
                                            <Button variant="ghost" size="sm" onClick={() => setAuthModalOpen(true)} icon={<LockClosedIcon className="w-4 h-4" />}>
                                                Amendment Mode
                                            </Button>
                                        ) : (
                                            <Button size="sm" onClick={handleFormSubmit} isLoading={isSaving} icon={<CheckCircleIcon className="w-4 h-4" />} disabled={!!priceError}>
                                                Commit Ledger
                                            </Button>
                                        )}
                                    </div>
                                </div>
                            </Card>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50 p-10 text-center">
                            <UserCheckIcon className="w-16 h-16 mb-4" />
                            <p className="text-lg font-bold uppercase tracking-widest">
                                {isClientListEmpty ? 'Database is Empty' : 'Select Account to Display Summary'}
                            </p>
                            <p className="text-xs mt-1">
                                {isClientListEmpty 
                                    ? 'No client accounts found. Register a new client to begin.' 
                                    : 'Select a client from the left sidebar to view the immutable summary.'}
                            </p>
                        </div>
                    )}
                </div>
            </div>

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            <RecordPaymentModal 
                isOpen={isPaymentModalOpen} 
                onClose={() => setPaymentModalOpen(false)} 
                client={selectedClient!}
                forcedType={paymentForcedType}
                onSave={(data) => {
                    onRecordPayment(selectedClient!, data);
                    setPaymentModalOpen(false);
                }}
            />
        </div>
    );
};

const setAuthModalOpen = (val: boolean) => {};

import React, { useState, useMemo, useEffect } from 'react';
import { Property, Staff, PriceHistory, PlotInventory, PlotSize } from '../types';
import { 
    ArrowLeftIcon, 
    BanknotesIcon, 
    ChartBarIcon, 
    ClockIcon, 
    BuildingLibraryIcon, 
    ArrowTrendingUpIcon,
    HashtagIcon,
    ExclamationTriangleIcon,
    InformationCircleIcon,
    PlusCircleIcon,
    TrashIcon,
    MapIcon,
    CheckCircleIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Input, Select } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { useProperties } from '../hooks/useAppData';

interface PurchaseSaleManagementPageProps {
    onBack: () => void;
    properties: Property[];
    onSaveProperty: (property: Property) => Promise<void>;
    currentStaff: Staff;
}

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

const PurchaseSaleManagementPage: React.FC<PurchaseSaleManagementPageProps> = ({ onBack, properties, onSaveProperty, currentStaff }) => {
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [editSellingPrice, setEditSellingPrice] = useState<string>('');
    const [plotPrefix, setPlotPrefix] = useState<string>('');
    const [prefixError, setPrefixError] = useState<string>('');
    const [isSaving, setIsSaving] = useState(false);

    const [inventory, setInventory] = useState<(PlotInventory & { zone?: string })[]>([]);

    const selectedProperty = useMemo(() => 
        properties.find(p => p.id === selectedPropertyId), 
    [selectedPropertyId, properties]);

    useEffect(() => {
        if (selectedProperty) {
            setEditSellingPrice(selectedProperty.price.toString());
            setPlotPrefix((selectedProperty as any).plotPrefix || '');
            setInventory(selectedProperty.inventory.map(inv => ({ ...inv })));
        } else {
            setEditSellingPrice('');
            setPlotPrefix('');
            setInventory([]);
        }
        setPrefixError('');
    }, [selectedProperty]);

    const addInventoryRow = () => {
        setInventory(prev => [...prev, { size: '70x100 ft', count: 0, sold: 0, zone: '' }]);
    };

    const removeInventoryRow = (index: number) => {
        setInventory(prev => prev.filter((_, i) => i !== index));
    };

    const updateInventoryItem = (index: number, field: string, value: any) => {
        setInventory(prev => {
            const next = [...prev];
            next[index] = { ...next[index], [field]: value };
            return next;
        });
    };

    const validatePrefix = (val: string) => {
        const regex = /^[a-zA-Z0-9\s-]*$/;
        if (!regex.test(val)) {
            setPrefixError('Invalid characters. Use letters, numbers, spaces, or dashes only.');
        } else {
            setPrefixError('');
        }
        setPlotPrefix(val.toUpperCase());
    };

    const calculations = useMemo(() => {
        if (!selectedProperty) return null;
        const costPerPlot = selectedProperty.costPrice || 0;
        const currentSellingPrice = parseFloat(editSellingPrice) || 0;
        const totalPlots = inventory.reduce((sum, inv) => sum + (Number(inv.count) || 0), 0);
        const margin = currentSellingPrice - costPerPlot;
        const marginPercentage = costPerPlot > 0 ? (margin / costPerPlot) * 100 : 0;
        const totalRevenue = currentSellingPrice * totalPlots;
        const totalCost = costPerPlot * totalPlots;
        const grossProfit = totalRevenue - totalCost;

        return { costPerPlot, currentSellingPrice, margin, marginPercentage, totalPlots, totalRevenue, totalCost, grossProfit };
    }, [selectedProperty, editSellingPrice, inventory]);

    const handleSave = async () => {
        if (!selectedProperty || !calculations || prefixError) return;
        if (inventory.length === 0) {
            alert("Please define at least one plot partitioning entry before publishing.");
            return;
        }
        const invalidRows = inventory.some(inv => !inv.count || inv.count <= 0);
        if (invalidRows) {
            alert("Please ensure all partitioning entries have a valid number of plots.");
            return;
        }

        setIsSaving(true);
        try {
            const historyEntry: PriceHistory = {
                date: new Date().toISOString(),
                oldPrice: selectedProperty.price,
                newPrice: calculations.currentSellingPrice,
                changedBy: currentStaff.fullName
            };

            const updatedProperty: Property = {
                ...selectedProperty,
                price: calculations.currentSellingPrice,
                priceHistory: [historyEntry, ...(selectedProperty.priceHistory || [])],
                inventory: inventory.map(inv => ({
                    size: inv.size,
                    count: Number(inv.count),
                    sold: inv.sold || 0,
                    zone: inv.zone
                }) as any),
                //@ts-ignore
                plotPrefix: plotPrefix.trim(),
                //@ts-ignore
                isPublished: true, // AUTHORITY FLAG
                //@ts-ignore
                lastPublishedAt: new Date().toISOString()
            };

            await onSaveProperty(updatedProperty);
            alert("Pricing Authority: Configuration Published and Locked for System Consumption.");
        } catch (error) {
            console.error(error);
            alert("Failed to update property configuration.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white mt-2 tracking-tight uppercase">Purchase & Sale Management</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1 font-medium">Single Source of Truth for Property Pricing Authority.</p>
                </div>
            </div>

            <Card className="bg-gray-50/50 dark:bg-gray-900/10">
                <div className="flex items-end gap-4 max-w-2xl">
                    <Select 
                        label="Select Property for Pricing Authority"
                        value={selectedPropertyId}
                        onChange={(e) => setSelectedPropertyId(e.target.value ? Number(e.target.value) : '')}
                        containerClassName="flex-grow"
                    >
                        <option value="">-- Choose an acquisition record --</option>
                        {properties.map(p => (
                            <option key={p.id} value={p.id}>{p.location} {(p as any).isPublished ? '✓' : '(Unpublished)'}</option>
                        ))}
                    </Select>
                    {(selectedProperty as any)?.isPublished && (
                        <div className="mb-1">
                            <Badge variant="success" className="py-2 px-4 flex items-center gap-2">
                                <CheckCircleIcon className="w-4 h-4" /> Published Price Active
                            </Badge>
                        </div>
                    )}
                </div>
            </Card>

            {selectedProperty && calculations ? (
                <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                    <div className="xl:col-span-2 space-y-8">
                        <Card title="Price & Inventory Configuration">
                            <div className="space-y-8">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                    <div className="space-y-6">
                                        <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                            <BanknotesIcon className="w-4 h-4" /> Master Price Control
                                        </h3>
                                        <div>
                                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Acquisition Cost (Fixed)</label>
                                            <div className="px-4 py-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg font-black text-gray-500">
                                                {formatCurrency(calculations.costPerPlot)}
                                            </div>
                                        </div>

                                        <Input 
                                            label="Published Selling Price per Plot*"
                                            type="number"
                                            value={editSellingPrice}
                                            onChange={(e) => setEditSellingPrice(e.target.value)}
                                            className="font-black text-xl text-blue-600"
                                        />
                                        <p className="text-[10px] text-amber-600 font-bold uppercase tracking-tighter">This price will be pushed to all modules upon publishing.</p>
                                    </div>

                                    <div className="space-y-6 border-l border-gray-100 dark:border-gray-700 md:pl-8">
