            if (file.type === 'application/pdf') {
                setPdfFile(file);
                setTouched(prev => ({ ...prev, filledFormPdf: true }));
            }
        }
    };

    const validate = useCallback((): Partial<Record<keyof FormData, string>> => {
        const errors: Partial<Record<keyof FormData, string>> = {};
        const requiredFields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk', 'paymentDate'];
        requiredFields.forEach(field => { if (!formData[field]) errors[field] = 'Required field.'; });

        // CEO AUTHORITY VALIDATION
        if (formData.location && !authorityData.isPublished) {
            errors.location = 'Pricing for this location is not yet published by CEO Hub.';
        }

        return errors;
    }, [formData, authorityData.isPublished]);

    const errors = useMemo(() => validate(), [validate]);
    const isFormValid = Object.keys(errors).length === 0;

    const handleNext = () => {
        const currentStepFields: (keyof FormData)[] = step === 1 ? ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress'] : ['location', 'plotNumber', 'paymentDate', 'indentureName', 'indentureAddress'];
        let isValid = true;
        currentStepFields.forEach(f => { if (errors[f]) isValid = false; });
        if (!isValid) { 
            const newTouched = { ...touched };
            currentStepFields.forEach(f => newTouched[f] = true);
            setTouched(newTouched);
            return; 
        }
        setStep(prev => Math.min(prev + 1, 3));
    };

    if (!isOpen) return null;

    const steps = [{ name: 'Client Information', icon: <UserGroupIcon className="w-5 h-5" /> }, { name: 'Acquisition Details', icon: <BuildingLibraryIcon className="w-5 h-5" /> }, { name: 'Office Details', icon: <BriefcaseIcon className="w-5 h-5" /> }];

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4">
            <div className="bg-gray-50 dark:bg-gray-900 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col">
                <div className="flex justify-between items-center p-5 border-b bg-white dark:bg-gray-800">
                    <h2 className="text-xl font-bold">{editingClient ? 'Edit Client' : 'New Registration'}</h2>
                    <button onClick={onClose}><XIcon className="w-6 h-6" /></button>
                </div>
                <div className="p-6 border-b bg-gray-50">
                    <nav className="flex items-center">
                        {steps.map((s, idx) => (
                            <div key={s.name} className={`flex items-center ${idx !== steps.length - 1 ? 'flex-grow' : ''}`}>
                                <div className={`relative w-8 h-8 rounded-full flex items-center justify-center font-bold ${step > idx ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-400'}`}>{s.icon}</div>
                                {idx !== steps.length - 1 && <div className={`h-0.5 flex-grow mx-4 ${step > idx + 1 ? 'bg-blue-600' : 'bg-gray-200'}`} />}
                            </div>
                        ))}
                    </nav>
                </div>

                <form className="p-6 overflow-y-auto flex-grow space-y-8">
                    {step === 1 && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <SmartInputField id="surname" label="Surname" value={formData.surname} onChange={handleChange} required onBlur={handleBlur} error={touched.surname ? errors.surname : undefined} />
                            <SmartInputField id="otherNames" label="Other Names" value={formData.otherNames} onChange={handleChange} required onBlur={handleBlur} error={touched.otherNames ? errors.otherNames : undefined} />
                            <SmartInputField id="currentAddress" label="Address" value={formData.currentAddress} onChange={handleChange} required onBlur={handleBlur} error={touched.currentAddress ? errors.currentAddress : undefined} />
                            <PhoneInput value={formData.telephone} onChange={handlePhoneChange('telephone')} label="Phone" required />
                        </div>
                    )}
                    {step === 2 && (
                        <div className="space-y-6">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <SmartSelectField id="location" label="Location*" value={formData.location} onChange={handleChange} required onBlur={handleBlur} error={touched.location ? errors.location : undefined}>
                                    <option value="">-- Select --</option>
                                    {properties.map(p => <option key={p.id} value={p.location}>{p.location} {(p as any).isPublished ? '' : '(Pending CEO Authority)'}</option>)}
                                </SmartSelectField>
                                <SmartInputField id="plotNumber" label="Plot Number(s)" value={formData.plotNumber} onChange={handleChange} required onBlur={handleBlur} error={touched.plotNumber ? errors.plotNumber : undefined} />
                            </div>

                            {formData.location && (
                                <div className="p-6 bg-indigo-50 dark:bg-indigo-900/10 border-2 border-dashed border-indigo-200 rounded-xl space-y-4">
                                    <div className="flex items-center gap-2 text-xs font-black uppercase text-indigo-600">
                                        <ShieldCheckIcon className="w-5 h-5" /> 
                                        Pricing Authority Check
                                    </div>
                                    {!authorityData.isPublished ? (
                                        <div className="flex gap-3 text-red-600">
                                            <ExclamationTriangleIcon className="w-6 h-6 shrink-0" />
                                            <div>
                                                <p className="font-bold text-sm">Action Required: Price Authority Missing</p>
                                                <p className="text-xs">The CEO has not published active pricing for this location. Registration is blocked.</p>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div>
                                                <label className="text-[10px] font-black text-indigo-400 uppercase">Unit Price (Read-Only)</label>
                                                <div className="text-lg font-black text-indigo-700">{formatCurrency(authorityData.pricePerPlot)}</div>
                                                <p className="text-[9px] text-indigo-500 italic flex items-center gap-1 mt-1"><LockClosedIcon className="w-3 h-3" /> System Generated from CEO Hub</p>
                                            </div>
                                            <div>
                                                <label className="text-[10px] font-black text-indigo-400 uppercase">Snapshot Total Commit</label>
                                                <div className="text-lg font-black text-indigo-700">{formatCurrency(totalAuthorityValue)}</div>
                                                <p className="text-[9px] text-indigo-500 italic mt-1">{plotsCount} Plot(s) @ Published Market Rate</p>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    )}
                    {step === 3 && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <SmartInputField id="salesRep" label="Intermediary Sales Rep" value={formData.salesRep} onChange={handleChange} required />
                            <SmartInputField id="salesManager" label="Approving Manager" value={formData.salesManager} onChange={handleChange} required />
                        </div>
                    )}
                </form>

                <div className="p-5 border-t flex justify-between bg-white dark:bg-gray-800">
                    <button onClick={step === 1 ? onClose : () => setStep(s => s - 1)} className="px-4 py-2 border rounded-lg font-bold">Back</button>
                    <button onClick={step === 3 ? () => onSave(formData) : handleNext} disabled={!isFormValid && step === 2} className={`px-8 py-2 rounded-lg font-bold text-white transition-all ${!isFormValid && step === 2 ? 'bg-gray-400 cursor-not-allowed' : 'bg-blue-600'}`}>
                        {step === 3 ? 'Finalize Registration' : 'Continue'}
                    </button>
                </div>
            </div>
        </div>
    );
};

const formatCurrency = (val: number) => `GHC ${new Intl.NumberFormat('en-GH').format(val)}`;

