const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

const ReAuthModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        const res = await login(email, password);
        if (res.success) {
            onSuccess();
            onClose();
        } else {
            setError(res.message);
        }
        setLoading(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex justify-center items-center p-4 backdrop-blur-md">
            <Card className="w-full max-w-sm p-0 overflow-hidden shadow-2xl border-indigo-500/50">
                <form onSubmit={handleAuth}>
                    <div className="p-6 text-center border-b border-gray-100 dark:border-gray-700">
                        <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/50 rounded-full flex items-center justify-center mx-auto mb-3">
                            <ShieldCheckIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Price Amendment Authorization</h3>
                        <p className="text-xs text-gray-500 mt-1">CEO ONLY: Re-authenticate to override system-locked pricing.</p>
                    </div>
                    <div className="p-6 space-y-4">
                        {error && <div className="text-xs text-red-500 bg-red-50 p-2 rounded border border-red-200">{error}</div>}
                        <Input label="CEO Email" type="email" value={email} onChange={e => setEmail(e.target.value)} required />
                        <Input label="Security Password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
                    </div>
                    <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
                        <Button type="button" variant="secondary" className="flex-1" onClick={onClose}>Cancel</Button>
                        <Button type="submit" className="flex-1" isLoading={loading}>Verify & Unlock</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const RecordPaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onSave: (payment: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    client: Client;
    forcedType?: 'Land' | 'Indenture' | 'Commission';
}> = ({ isOpen, onClose, onSave, client, forcedType }) => {
    const [amount, setAmount] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [method, setMethod] = useState<'Cash' | 'Bank Transfer' | 'MoMo' | 'Cheque' | 'Other'>('Bank Transfer');
    const [type, setType] = useState<'Land' | 'Indenture' | 'Commission'>(forcedType || 'Land');
    const [receiptNumber, setReceiptNumber] = useState('');
    const [notes, setNotes] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            setAmount('');
            setDate(new Date().toISOString().split('T')[0]);
            setNotes('');
            setError('');
            if (forcedType) setType(forcedType);
        }
    }, [isOpen, forcedType]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const paidAmount = parseFloat(amount);
        if (!date) { setError('Payment date is required.'); return; }
        if (isNaN(paidAmount) || paidAmount <= 0) { setError('Please enter a valid positive amount.'); return; }
        if (paidAmount > client.payment.balance) { setError(`Amount exceeds balance of ${formatCurrency(client.payment.balance)}.`); return; }
        if (!receiptNumber.trim()) { setError('Receipt number is required.'); return; }
        onSave({ date, amount: paidAmount, method, reference: receiptNumber, receiptNumber, type, notes } as any);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
            <Card className="w-full max-w-md p-0 overflow-hidden shadow-2xl">
                <form onSubmit={handleSubmit}>
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 bg-white dark:bg-gray-800">
                        <h2 className="text-lg font-black text-gray-800 dark:text-white uppercase tracking-tight">Record {type} Payment</h2>
                        <button type="button" onClick={onClose} className="text-gray-400"><XMarkIcon className="w-6 h-6" /></button>
                    </div>
                    <div className="p-6 space-y-4 bg-gray-50 dark:bg-gray-900">
                        {error && <div className="bg-red-50 text-red-700 p-3 rounded text-xs border border-red-200">{error}</div>}
                        <Select label="Purpose" value={type} onChange={e => setType(e.target.value as any)} disabled={!!forcedType}>
                            <option value="Land">Land Purchase</option>
                            <option value="Indenture">Documentation</option>
                            <option value="Commission">Commission</option>
                        </Select>
                        <div className="grid grid-cols-2 gap-4">
                          <Input label="Date" type="date" value={date} onChange={e => setDate(e.target.value)} required />
                          <Input label="Amount (GHC)*" type="number" value={amount} onChange={e => setAmount(e.target.value)} required className="font-bold" />
                        </div>
                        <Input label="Receipt / Ref No.*" value={receiptNumber} onChange={e => setReceiptNumber(e.target.value)} required />
                        <Select label="Method" value={method} onChange={e => setMethod(e.target.value as any)}>
                            <option value="Bank Transfer">Bank Transfer</option>
                            <option value="Cash">Cash</option>
                            <option value="MoMo">MoMo</option>
                            <option value="Cheque">Cheque</option>
                        </Select>
                    </div>
                    <div className="flex justify-end p-4 border-t border-gray-200 gap-3">
                        <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                        <Button type="submit">Confirm Payment</Button>
                    </div>
                </form>
            </Card>
        </div>
    );
};

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { currentStaff } = useAuth();
    const { properties } = useProperties();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
    const [isAuthModalOpen, setAuthModalOpen] = useState(false);
    const [isUnlocked, setIsUnlocked] = useState(false);
    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    // PRICE AUTHORITY DATA BINDING
    const publishedPriceData = useMemo(() => {
        if (!selectedClient) return { price: 0, isPublished: false };
        const property = properties.find(p => p.location === selectedClient.location);
        return {
            price: property ? property.price : 0,
            isPublished: property ? (property as any).isPublished : false
        };
    }, [selectedClient, properties]);

    // Local override for price (only editable via CEO re-auth)
    const [manualPrice, setManualPrice] = useState<string>('0');

    // Sync manual price with authority source on selection
    useEffect(() => {
        if (selectedClient) {
            setManualPrice(publishedPriceData.price.toString());
        }
    }, [selectedClient, publishedPriceData.price]);

    const financialSummary = useMemo(() => {
        const p_authority = parseFloat(manualPrice) || 0;
        const totalPaid = selectedClient?.payment.paid || 0;
        const outstandingBalance = Math.max(0, p_authority - totalPaid);

        return {
            authoritativePrice: p_authority,
            outstandingBalance,
            totalPaid,
            isAuthorityPublished: publishedPriceData.isPublished
        };
    }, [manualPrice, selectedClient, publishedPriceData.isPublished]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient || isSaving || !financialSummary.isAuthorityPublished) return;

        setIsSaving(true);
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: financialSummary.authoritativePrice,
                balance: financialSummary.outstandingBalance
            }
        } as Client;

        try {
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
            setIsUnlocked(false);
        } finally {
            setIsSaving(false);
        }
    };

    const isReadOnly = !isUnlocked; // Global Read-Only logic for price field

    // Fixed: Added definition for paymentForcedType
    const paymentForcedType: 'Land' | 'Indenture' | 'Commission' | undefined = undefined;

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1 rounded-full"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">Financial Commitment Ledger</h2>
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r p-4 space-y-4 overflow-y-auto">
                    {!fixedClient && (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Client Selection</label>
                            <button
                                type="button"
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className="flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border rounded-md shadow-sm text-sm text-gray-900 dark:text-white"
                            >
                                <span className="truncate">{selectedClient ? selectedClient.name : '-- Select Account --'}</span>
                                <ChevronDownIcon className={`w-4 h-4 transition-transform ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                            </button>
                            {isClientDropdownOpen && (
                                <div className="absolute left-0 right-0 mt-1 bg-white border rounded-md shadow-xl z-50 max-h-60 overflow-y-auto">
                                    {clients.map(client => (
                                        <button key={client.id} onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }} className="w-full text-left px-4 py-2.5 text-sm hover:bg-gray-50">{client.name}</button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <div className="space-y-4">
                            <Card title="Price Authority Control" className="p-4 border-dashed border-2 border-indigo-200">
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Published Unit Price (CEO Hub)</label>
                                        <div className="relative">
                                            <Input 
                                                type="number" 
                                                value={manualPrice} 
                                                onChange={e => setManualPrice(e.target.value)} 
                                                readOnly={isReadOnly} 
                                                className={`font-black text-lg ${isReadOnly ? 'bg-gray-50 text-gray-500 opacity-60 cursor-not-allowed' : 'text-blue-600'}`}
                                            />
                                            {isReadOnly && (
                                                <div className="absolute inset-0 bg-transparent flex items-center justify-end pr-3">
                                                    <LockClosedIcon className="w-4 h-4 text-gray-300" />
                                                </div>
                                            )}
                                        </div>
                                        <p className="mt-1 text-[9px] text-gray-400 uppercase font-bold italic">Source: Published in Strategic Hub</p>
                                        {!financialSummary.isAuthorityPublished && (
                                            <div className="mt-3 p-2 bg-red-50 border border-red-100 rounded flex gap-2 items-start">
                                                <ExclamationTriangleIcon className="w-4 h-4 text-red-500 shrink-0" />
                                                <p className="text-[10px] text-red-600 font-bold uppercase">Price not yet published by CEO for this location.</p>
                                            </div>
                                        )}
                                    </div>
                                    <div className="pt-2 border-t border-gray-100">
                                        <Button 
                                            variant="ghost" 
                                            size="sm" 
                                            className="w-full text-[10px] font-black uppercase"
                                            onClick={() => setAuthModalOpen(true)}
                                            disabled={currentStaff.roleId !== 'CEO'}
                                        >
                                            <ShieldCheckIcon className="w-4 h-4 mr-2" /> 
                                            {currentStaff.roleId === 'CEO' ? 'CEO Price Amendment' : 'Price Authority Locked'}
                                        </Button>
                                    </div>
                                </div>
                            </Card>
                            <Button variant="success" onClick={() => setPaymentModalOpen(true)} className="w-full py-4 font-black uppercase tracking-widest" icon={<BanknotesIcon className="w-6 h-6" />}>Post Payment</Button>
                        </div>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto">
                    {selectedClient ? (
                        <div className="max-w-4xl mx-auto space-y-6">
                            <Card className="border-l-4 border-l-green-500 shadow-xl p-0 overflow-hidden">
                                <div className="px-6 py-5 border-b bg-gray-50/50 flex items-center justify-between">
                                    <h3 className="text-sm font-black uppercase tracking-widest text-gray-700">Authoritative Ledger Standing</h3>
                                    <Badge variant={financialSummary.isAuthorityPublished ? 'success' : 'warning'}>
                                        {financialSummary.isAuthorityPublished ? 'Price Active' : 'Unpublished'}
                                    </Badge>
                                </div>
                                <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-8">
                                    <div><p className="text-[10px] font-bold text-gray-500 uppercase">Master Contract Value</p><p className="text-2xl font-black text-gray-900">{formatCurrency(financialSummary.authoritativePrice)}</p></div>
                                    <div><p className="text-[10px] font-bold text-gray-500 uppercase">Liquidation Progress</p><p className="text-2xl font-black text-green-600">{formatCurrency(financialSummary.totalPaid)}</p></div>
                                    <div><p className="text-[10px] font-bold text-gray-500 uppercase">Outstanding Commit</p><p className="text-2xl font-black text-red-600">{formatCurrency(financialSummary.outstandingBalance)}</p></div>
                                </div>
                                <div className="px-6 py-4 bg-gray-50 border-t flex justify-end">
                                    <Button size="sm" onClick={handleFormSubmit} isLoading={isSaving} icon={<CheckCircleIcon className="w-4 h-4" />} disabled={!financialSummary.isAuthorityPublished}>
                                        Commit Ledger Snapshot
                                    </Button>
                                </div>
                            </Card>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50 p-10 text-center">
                            <UserCheckIcon className="w-16 h-16 mb-4" />
                            <p className="text-lg font-black uppercase tracking-widest">Select Account to Display Summary</p>
                        </div>
                    )}
                </div>
            </div>

            <ReAuthModal isOpen={isAuthModalOpen} onClose={() => setAuthModalOpen(false)} onSuccess={() => setIsUnlocked(true)} />

            <RecordPaymentModal 
                isOpen={isPaymentModalOpen} 
                onClose={() => setPaymentModalOpen(false)} 
                client={selectedClient!}
                forcedType={paymentForcedType}
                onSave={(data) => {
                    onRecordPayment(selectedClient!, data);
                    setPaymentModalOpen(false);
                }}
            />
        </div>
    );
};

const setAuthModalOpen = (val: boolean) => {};

import React, { useState, useMemo, useEffect } from 'react';
import { Property, Staff, PriceHistory, PlotInventory, PlotSize } from '../types';
import { 
    ArrowLeftIcon, 
    BanknotesIcon, 
    ChartBarIcon, 
    ClockIcon, 
    BuildingLibraryIcon, 
    ArrowTrendingUpIcon,
    HashtagIcon,
    ExclamationTriangleIcon,
    InformationCircleIcon,
    PlusCircleIcon,
    TrashIcon,
    MapIcon,
    CheckCircleIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Input, Select } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';

interface PurchaseSaleManagementPageProps {
    onBack: () => void;
    properties: Property[];
    onSaveProperty: (property: Property) => Promise<void>;
    currentStaff: Staff;
}

const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

const PurchaseSaleManagementPage: React.FC<PurchaseSaleManagementPageProps> = ({ onBack, properties, onSaveProperty, currentStaff }) => {
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [editSellingPrice, setEditSellingPrice] = useState<string>('');
    const [plotPrefix, setPlotPrefix] = useState<string>('');
    const [prefixError, setPrefixError] = useState<string>('');
    const [isSaving, setIsSaving] = useState(false);
    const [inventory, setInventory] = useState<(PlotInventory & { zone?: string })[]>([]);

    const selectedProperty = useMemo(() => 
        properties.find(p => p.id === selectedPropertyId), 
    [selectedPropertyId, properties]);

    useEffect(() => {
        if (selectedProperty) {
            setEditSellingPrice(selectedProperty.price.toString());
            setPlotPrefix((selectedProperty as any).plotPrefix || '');
            setInventory(selectedProperty.inventory.map(inv => ({ ...inv })));
        } else {
            setEditSellingPrice('');
            setPlotPrefix('');
            setInventory([]);
        }
        setPrefixError('');
    }, [selectedProperty]);

    const addInventoryRow = () => {
        setInventory(prev => [...prev, { size: '70x100 ft', count: 0, sold: 0, zone: '' }]);
    };

    const removeInventoryRow = (index: number) => {
        setInventory(prev => prev.filter((_, i) => i !== index));
    };

    const updateInventoryItem = (index: number, field: string, value: any) => {
        setInventory(prev => {
            const next = [...prev];
            next[index] = { ...next[index], [field]: value };
            return next;
        });
    };

    const validatePrefix = (val: string) => {
        const regex = /^[a-zA-Z0-9\s-]*$/;
        if (!regex.test(val)) {
            setPrefixError('Invalid characters. Use letters, numbers, spaces, or dashes only.');
        } else {
            setPrefixError('');
        }
        setPlotPrefix(val.toUpperCase());
    };

    const calculations = useMemo(() => {
        if (!selectedProperty) return null;
        const costPerPlot = selectedProperty.costPrice || 0;
        const currentSellingPrice = parseFloat(editSellingPrice) || 0;
        const totalPlots = inventory.reduce((sum, inv) => sum + (Number(inv.count) || 0), 0);
        const margin = currentSellingPrice - costPerPlot;
        const marginPercentage = costPerPlot > 0 ? (margin / costPerPlot) * 100 : 0;
        const totalRevenue = currentSellingPrice * totalPlots;
        const totalCost = costPerPlot * totalPlots;
        const grossProfit = totalRevenue - totalCost;

        return { costPerPlot, currentSellingPrice, margin, marginPercentage, totalPlots, totalRevenue, totalCost, grossProfit };
    }, [selectedProperty, editSellingPrice, inventory]);

    const handleSave = async () => {
        if (!selectedProperty || !calculations || prefixError) return;
        if (inventory.length === 0) {
            alert("Please define at least one plot partitioning entry before publishing.");
            return;
        }

        setIsSaving(true);
        try {
            const historyEntry: PriceHistory = {
                date: new Date().toISOString(),
                oldPrice: selectedProperty.price,
                newPrice: calculations.currentSellingPrice,
                changedBy: currentStaff.fullName
            };

            const updatedProperty: Property = {
                ...selectedProperty,
                price: calculations.currentSellingPrice,
                priceHistory: [historyEntry, ...(selectedProperty.priceHistory || [])],
                inventory: inventory.map(inv => ({
                    size: inv.size,
                    count: Number(inv.count),
                    sold: inv.sold || 0,
                    zone: inv.zone
                }) as any),
                //@ts-ignore
                plotPrefix: plotPrefix.trim(),
                //@ts-ignore
                isPublished: true // Authority trigger
            };

            await onSaveProperty(updatedProperty);
            alert("Pricing Authority: Configuration Published and Locked for System consumption.");
        } catch (error) {
            alert("Failed to publish property configuration.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white mt-2 tracking-tight uppercase">Purchase & Sale Management</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1 font-medium">Single Source of Truth for Property Pricing Authority.</p>
                </div>
            </div>

            <Card className="bg-gray-50/50 dark:bg-gray-900/10">
                <div className="flex items-end gap-4 max-w-2xl">
                    <Select 
                        label="Select Property for Pricing Authority"
                        value={selectedPropertyId}
                        onChange={(e) => setSelectedPropertyId(e.target.value ? Number(e.target.value) : '')}
                        containerClassName="flex-grow"
                    >
                        <option value="">-- Choose an acquisition record --</option>
                        {properties.map(p => (
                            <option key={p.id} value={p.id}>{p.location} {(p as any).isPublished ? '✓' : '(Draft)'}</option>
                        ))}
                    </Select>
                    {(selectedProperty as any)?.isPublished && (
                        <div className="mb-1">
                            <Badge variant="success" className="py-2 px-4 flex items-center gap-2">
                                <CheckCircleIcon className="w-4 h-4" /> Published
                            </Badge>
                        </div>
                    )}
                </div>
            </Card>

            {selectedProperty && calculations ? (
                <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                    <div className="xl:col-span-2 space-y-8">
                        <Card title="Pricing & Inventory Configuration">
                            <div className="space-y-8">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                    <div className="space-y-6">
                                        <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                            <BanknotesIcon className="w-4 h-4" /> Financials
                                        </h3>
                                        <div>
                                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Acquisition Cost</label>
                                            <div className="px-4 py-3 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg font-black text-gray-500">
                                                {formatCurrency(calculations.costPerPlot)}
                                            </div>
                                        </div>
                                        <Input 
                                            label="Published Unit Price*"
                                            type="number"
                                            value={editSellingPrice}
                                            onChange={(e) => setEditSellingPrice(e.target.value)}
                                            className="font-black text-xl text-blue-600"
                                        />
                                    </div>
                                    <div className="space-y-6 border-l border-gray-100 dark:border-gray-700 md:pl-8">
                                        <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                            <HashtagIcon className="w-4 h-4" /> Plot Prefix
                                        </h3>
                                        <Input 
                                            label="Prefix"
                                            value={plotPrefix}
                                            onChange={(e) => validatePrefix(e.target.value)}
                                            placeholder="e.g. EAF"
                                            error={prefixError}
                                            className="font-bold uppercase"
                                        />
                                    </div>
                                </div>
                                <div className="pt-8 border-t border-gray-100 dark:border-gray-700">
                                    <div className="flex items-center justify-between mb-4">
                                        <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                            <MapIcon className="w-4 h-4" /> Plot Partitioning
                                        </h3>
                                        <button type="button" onClick={addInventoryRow} className="text-xs font-black text-blue-600 uppercase">Add Row</button>
                                    </div>
                                    <div className="space-y-3">
                                        {inventory.map((item, idx) => (
                                            <div key={idx} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-4 bg-gray-50/50 dark:bg-gray-900/30 rounded-xl border border-gray-100 dark:border-gray-800 relative group">
                                                <button onClick={() => removeInventoryRow(idx)} className="absolute -top-2 -right-2 p-1 bg-red-100 text-red-600 rounded-full opacity-0 group-hover:opacity-100"><TrashIcon className="w-4 h-4" /></button>
                                                <Select label="Size" value={item.size} onChange={e => updateInventoryItem(idx, 'size', e.target.value)}>
                                                    <option value="70x100 ft">70x100 ft</option>
                                                    <option value="70x50 ft">70x50 ft</option>
                                                    <option value="60x80 ft">60x80 ft</option>
                                                </Select>
                                                <Input label="Count" type="number" value={item.count} onChange={e => updateInventoryItem(idx, 'count', Number(e.target.value))} />
                                                <Input label="Zone" value={item.zone || ''} onChange={e => updateInventoryItem(idx, 'zone', e.target.value)} />
                                                <div className="flex flex-col justify-end"><Badge variant="neutral">{item.sold || 0} Sold</Badge></div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                                <div className="flex justify-end pt-6">
                                    <Button onClick={handleSave} isLoading={isSaving} className="px-12 py-4 shadow-xl uppercase font-black tracking-widest" disabled={!!prefixError}>
                                        Publish Pricing Authority
                                    </Button>
                                </div>
                            </div>
                        </Card>
                    </div>
                    <div className="space-y-6">
                        <div className="bg-gray-900 text-white rounded-2xl shadow-2xl p-8 border border-gray-800">
                            <h3 className="text-xs font-black uppercase tracking-widest border-b border-gray-800 pb-4 mb-6 flex items-center gap-2 text-blue-400">
                                <ChartBarIcon className="w-5 h-5" /> ROI Projection
                            </h3>
                            <div className="space-y-8">
                                <div className={`p-6 rounded-xl border-2 ${calculations.grossProfit >= 0 ? 'bg-green-500/10 border-green-500/40' : 'bg-red-500/10 border-red-500/40'}`}>
                                    <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-1">Gross Profit</p>
                                    <p className={`text-4xl font-black ${calculations.grossProfit >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                                        {formatCurrency(calculations.grossProfit)}
                                    </p>
                                </div>
                                <div className="space-y-4 pt-4 border-t border-gray-800">
                                    <div className="flex justify-between text-xs"><span className="text-gray-500">Margin %:</span><span className="font-bold">{calculations.marginPercentage.toFixed(1)}%</span></div>
                                    <div className="flex justify-between text-xs"><span className="text-gray-500">Revenue:</span><span className="font-bold text-blue-400">{formatCurrency(calculations.totalRevenue)}</span></div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="p-32 text-center bg-white dark:bg-gray-800 rounded-3xl border border-gray-200 opacity-60">
                    <BanknotesIcon className="w-20 h-20 text-gray-300 mx-auto mb-6" />
                    <h2 className="text-2xl font-black uppercase tracking-tighter">Awaiting Portfolio Selection</h2>
                </div>
            )}
        </div>
    );
};

export default PurchaseSaleManagementPage;

