    ChevronRightIcon,
    ArrowLeftIcon,
    LockClosedIcon,
    PencilSquareIcon,
    ShieldCheckIcon,
    ChevronDownIcon,
    ClockIcon,
    XMarkIcon,
    CheckCircleIcon,
    ExclamationTriangleIcon,
    UserCircleIcon,
    CurrencyDollarIcon,
    TagIcon,
    ChartPieIcon,
    InformationCircleIcon,
    UserCheckIcon,
    ChatBubbleLeftEllipsisIcon,
    MapPinIcon,
    HashtagIcon
} from './icons/DummyIcons';
