const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

export const FinancialRecordEditor: React.FC<{
    onBack?: () => void;
    clients: Client[];
    onSave: (invoice: Invoice, updatedClient?: Client) => void;
    onRecordPayment: (client: Client, paymentData: Omit<PaymentTransaction, 'id' | 'status'> & { type: 'Land' | 'Indenture' | 'Commission' }) => void;
    editingInvoice: Invoice | null;
    clientForInvoice: Client | null;
    fixedClient?: Client;
    className?: string;
    roles: Role[];
}> = ({ onBack, clients, onSave, onRecordPayment, editingInvoice, clientForInvoice, fixedClient, className, roles = [] }) => {
    const { properties } = useProperties();
    const dropdownRef = useRef<HTMLDivElement>(null);

    const [selectedClientId, setSelectedClientId] = useState<number | null>(() => {
        if (fixedClient) return fixedClient.id;
        if (clientForInvoice) return clientForInvoice.id;
        return null;
    });

    const [isClientDropdownOpen, setIsClientDropdownOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [originalPrice, setOriginalPrice] = useState('0');
    const [discountValue, setDiscountValue] = useState('0');
    const [installmentCount, setInstallmentCount] = useState('1');
    const [priceError, setPriceError] = useState<string>('');

    const selectedClient = fixedClient || clients.find(c => c.id === selectedClientId);

    // AUTHORITY BINDING: Auto-fetch and lock price from CEO Hub
    useEffect(() => {
        if (selectedClient && !selectedClient.payment.isInitialized) {
            const propertyMatch = properties.find(p => p.location === selectedClient.location);

            if (propertyMatch) {
                if ((propertyMatch as any).isPublished) {
                    setOriginalPrice(String(propertyMatch.price));
                    setPriceError('');
                } else {
                    setOriginalPrice('0');
                    setPriceError('Authority Lock: Price not yet published in CEO Hub.');
                }
            } else {
                setOriginalPrice('0');
                setPriceError('Reference Error: Property location not found.');
            }
        } else if (selectedClient?.payment.isInitialized) {
            // SNAPSHOT RULE: Retain price active at time of creation
            setOriginalPrice(String(selectedClient.payment.total));
            setPriceError('');
        }
    }, [selectedClient, properties]);

    const financialSummary = useMemo(() => {
        const P_orig = parseFloat(originalPrice) || 0;
        const D_val = parseFloat(discountValue) || 0;
        const I_count = parseInt(installmentCount) || 1;
        const priceAfterDiscount = Math.max(0, P_orig - D_val);
        const totalPaid = selectedClient?.payment.paid || 0;
        const outstandingBalance = Math.max(0, priceAfterDiscount - totalPaid);

        return {
            originalPrice: P_orig,
            priceAfterDiscount,
            totalPaid,
            outstandingBalance
        };
    }, [originalPrice, discountValue, installmentCount, selectedClient]);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedClient || isSaving || priceError) return;

        setIsSaving(true);
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                total: financialSummary.priceAfterDiscount,
                balance: financialSummary.outstandingBalance
            }
        } as Client;

        try {
            await onSave({ id: `AUTO-${Date.now()}`, clientId: selectedClient.id, clientName: selectedClient.name, amount: 0, status: 'Pending', issueDate: '', dueDate: '' }, updatedClient);
        } finally {
            setIsSaving(false);
        }
    };

    const isClientListEmpty = !clients || clients.length === 0;

    return (
        <div className={`flex flex-col bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 transition-all duration-200 ${className || 'h-[calc(100vh-9rem)]'}`}>
            <div className="flex justify-between items-center p-5 border-b bg-white dark:bg-gray-800">
                <div className="flex items-center gap-4">
                    {onBack && <button onClick={onBack} className="text-gray-500 p-1"><ArrowLeftIcon className="w-6 h-6" /></button>}
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white uppercase tracking-tight">Active Financial Ledger</h2>
                </div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row overflow-hidden bg-gray-50 dark:bg-gray-900">
                <div className="w-full md:w-1/3 xl:w-1/4 bg-white dark:bg-gray-800 border-r p-4 space-y-4 overflow-y-auto">
                    {!fixedClient && (
                        <div className="relative">
                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Select Account</label>
                            <button
                                type="button"
                                onClick={() => setIsClientDropdownOpen(!isClientDropdownOpen)}
                                className="flex items-center justify-between w-full px-3 py-2 bg-white dark:bg-gray-900 border rounded-md text-sm"
                            >
                                <span className="truncate">{selectedClient ? selectedClient.name : '-- Choose Client --'}</span>
                                <ChevronDownIcon className={`w-4 h-4 text-gray-400 ${isClientDropdownOpen ? 'rotate-180' : ''}`} />
                            </button>
                            {isClientDropdownOpen && (
                                <div className="absolute left-0 right-0 mt-1 bg-white border rounded-md shadow-xl z-50 max-h-60 overflow-y-auto">
                                    {clients.map(client => (
                                        <button key={client.id} onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }} className="w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 border-b last:border-0">{client.name}</button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <div className="space-y-4">
                            <Card title="Price Authority (Read-Only)" className="p-4 border-dashed border-2 border-blue-100">
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-[10px] font-black text-indigo-400 uppercase mb-1">System Published Price (GHC)</label>
                                        <div className="relative">
                                            <Input 
                                                type="number" 
                                                value={originalPrice} 
                                                readOnly={true} 
                                                className="bg-gray-50 font-black text-lg text-gray-500 opacity-70"
                                            />
                                            <LockClosedIcon className="absolute right-3 top-3 w-4 h-4 text-gray-400" />
                                        </div>
                                        {priceError && (
                                            <div className="mt-2 p-2 bg-red-50 text-red-600 rounded text-[10px] font-bold flex items-start gap-1">
                                                <ExclamationTriangleIcon className="w-3 h-3 shrink-0 mt-0.5" />
                                                {priceError}
                                            </div>
                                        )}
                                    </div>
                                    <Input label="Discount (GHC)" type="number" value={discountValue} onChange={e => setDiscountValue(e.target.value)} />
                                    <Input label="Installments (Months)" type="number" value={installmentCount} onChange={e => setInstallmentCount(e.target.value)} min="1" max="12" />
                                </div>
                            </Card>
                            <Button size="sm" onClick={handleFormSubmit} isLoading={isSaving} icon={<CheckCircleIcon className="w-4 h-4" />} disabled={!!priceError} className="w-full py-4 uppercase font-black">Commit Financial Snapshot</Button>
                        </div>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto">
                    {selectedClient ? (
                        <div className="max-w-3xl mx-auto space-y-6">
                            <Card className="border-l-4 border-l-green-500 shadow-xl p-0 overflow-hidden">
                                <div className="px-6 py-5 border-b bg-gray-50/50 flex items-center justify-between">
                                    <h3 className="text-sm font-black uppercase tracking-widest text-gray-700">Authoritative Ledger Standing</h3>
                                    <Badge variant={priceError ? 'danger' : 'success'}>{priceError ? 'Blocked' : 'Active Agreement'}</Badge>
                                </div>
                                <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-8">
                                    <div><p className="text-[10px] font-bold text-gray-500 uppercase">Snapshot Total</p><p className="text-2xl font-black text-gray-900">{formatCurrency(financialSummary.priceAfterDiscount)}</p></div>
                                    <div><p className="text-[10px] font-bold text-gray-500 uppercase">Paid to Date</p><p className="text-2xl font-black text-green-600">{formatCurrency(financialSummary.totalPaid)}</p></div>
                                    <div><p className="text-[10px] font-bold text-gray-500 uppercase">Balance Due</p><p className="text-2xl font-black text-red-600">{formatCurrency(financialSummary.outstandingBalance)}</p></div>
                                </div>
                                <div className="px-6 py-4 bg-gray-50 border-t flex items-center gap-2 text-[9px] text-gray-400 font-bold uppercase">
                                    <LockClosedIcon className="w-3 h-3" /> System generated from CEO Hub source
                                </div>
                            </Card>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50 p-10 text-center">
                            <UserCheckIcon className="w-16 h-16 mb-4" />
                            <p className="text-lg font-black uppercase tracking-widest">Select Account to display ledger</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

