                                    {clients.map(client => (
                                        <button key={client.id} type="button" onClick={() => { setSelectedClientId(client.id); setIsClientDropdownOpen(false); }} className="w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 dark:hover:bg-indigo-900/30 border-b border-gray-50 dark:border-gray-700 last:border-0">{client.name}</button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                    {selectedClient && (
                        <div className="space-y-4">
                            <Card title="Ledger Source" className="p-4 border-dashed border-2">
                                <div className="space-y-4">
                                    <div>
                                        <Input 
                                            label="Published Price (GHC)" 
                                            type="number" 
                                            value={originalPrice} 
                                            readOnly={true} // AUTHORITY ENFORCED: READ-ONLY
                                            className="bg-gray-50 dark:bg-gray-900/50 font-bold opacity-75 cursor-not-allowed"
                                        />
                                        <p className="text-[9px] text-gray-400 mt-1 uppercase font-bold tracking-tighter">Read-only: Sourced from CEO Hub</p>
                                    </div>
                                    <div className="grid grid-cols-2 gap-2">
                                        <Input label="Discount" type="number" value={discountValue} onChange={e => setDiscountValue(e.target.value)} />
                                        <Select label="Type" value={discountType} onChange={e => setDiscountType(e.target.value as any)}>
                                            <option value="percentage">%</option>
                                            <option value="fixed">GHC</option>
                                        </Select>
                                    </div>
                                    <Input label="Term (Months)" type="number" value={installmentCount} onChange={e => setInstallmentCount(e.target.value)} min="1" max="12" />
                                </div>
                            </Card>
                            <Button variant="success" onClick={() => {}} className="w-full py-4 font-black uppercase tracking-widest shadow-lg" icon={<BanknotesIcon className="w-6 h-6" />}>Record Payment</Button>
                        </div>
                    )}
                </div>

                <div className="flex-grow p-6 overflow-y-auto scrollbar-thin">
                    {selectedClient ? (
                        <div className="max-w-4xl mx-auto">
                            <Card className="border-l-4 border-l-green-500 bg-white dark:bg-gray-800 shadow-xl p-0 overflow-hidden">
                                <div className="px-6 py-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/20 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <ChartPieIcon className="w-6 h-6 text-green-600" />
                                        <h3 className="text-sm font-black uppercase tracking-widest text-gray-700 dark:text-gray-200">Commitment Summary</h3>
                                    </div>
                                    <Badge variant={financialSummary.outstandingBalance <= 0 && financialSummary.totalPaid > 0 ? 'success' : 'warning'}>
                                        Active Ledger
                                    </Badge>
                                </div>

                                <div className="p-6 space-y-1">
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 p-4 bg-green-50/20 dark:bg-green-900/10 rounded-xl border border-green-100 dark:border-green-900/30">
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Agreed Total</p>
                                            <p className="text-xl font-black text-gray-900 dark:text-white">{formatCurrency(financialSummary.priceAfterDiscount)}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Total Paid</p>
                                            <p className="text-xl font-black text-green-600">{formatCurrency(financialSummary.totalPaid)}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Outstanding</p>
                                            <p className="text-xl font-black text-red-600">{formatCurrency(financialSummary.outstandingBalance)}</p>
                                        </div>
                                    </div>

                                    <div className="space-y-0 pt-4 border-t border-gray-100 dark:border-gray-700">
                                        <div className="flex justify-between py-2 border-b border-gray-50 dark:border-gray-700">
                                            <span className="text-sm text-gray-500">Base Price (CEO Hub)</span>
                                            <span className="text-sm font-bold">{formatCurrency(financialSummary.originalPrice)}</span>
                                        </div>
                                        <div className="flex justify-between py-2 border-b border-gray-50 dark:border-gray-700">
                                            <span className="text-sm text-gray-500">Discount Amount</span>
                                            <span className="text-sm font-bold text-red-500">-{formatCurrency(financialSummary.discountAmount)}</span>
                                        </div>
                                        <div className="flex justify-between py-2">
                                            <span className="text-sm text-gray-500">Final Contract Total</span>
                                            <span className="text-sm font-black text-blue-600">{formatCurrency(financialSummary.priceAfterDiscount)}</span>
                                        </div>
                                    </div>
                                </div>

                                <div className="px-6 py-4 bg-gray-50 dark:bg-gray-900 border-t border-gray-100 dark:border-gray-700 flex justify-between items-center">
                                    <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                        <LockClosedIcon className="w-3 h-3" />
                                        System-Generated Record
                                    </div>
                                    <Button size="sm" onClick={handleFormSubmit} isLoading={isSaving} icon={<CheckCircleIcon className="w-4 h-4" />}>
                                        Commit Snapshot
                                    </Button>
                                </div>
                            </Card>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-50 p-10 text-center">
                            <UserCheckIcon className="w-16 h-16 mb-4" />
                            <p className="text-lg font-bold uppercase tracking-widest">Select Account</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification, Promotion } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    CheckCircleIcon,
    LockClosedIcon,
    BanknotesIcon,
    ShieldCheckIcon,
    DocumentTextIcon,
    PlusCircleIcon,
    ChartBarIcon,
    TagIcon,
    ExclamationTriangleIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select } from '../components/ui/Input';
import { Badge } from '../components/ui/Badge';
import { RecordPaymentModal } from '../components/FinancialRecordEditor';
import { FinancialReportsView } from '../components/FinancialReportsView';
import { NotificationCenter } from '../components/NotificationCenter';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useAuth } from '../context/AuthContext';
import { usePromotions } from '../hooks/useAppData';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage 
}) => {
  const { promotions } = usePromotions();
  const [viewMode, setViewMode] = useState<'list' | 'alerts' | 'reports'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(null);
  const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [selectedPromoId, setSelectedPromoId] = useState<number | 'none'>('none');

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (clientForInvoice?.id || selectedClientId))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);

  // PROMO AUTHORITY LOGIC
  const activePropertyPromo = useMemo(() => {
    if (!selectedClient || !promotions) return null;
    return promotions.find(p => 
        (p.applicablePropertyId === 'all' || p.applicablePropertyId === (selectedClient as any).propertyId) &&
        p.status === 'Active'
    );
  }, [selectedClient, promotions]);

  const selectedPromo = useMemo(() => {
    if (selectedPromoId === 'none') return null;
    return promotions.find(p => p.id === selectedPromoId);
  }, [selectedPromoId, promotions]);

  const isPromoExpired = useMemo(() => {
    if (!selectedPromo) return false;
    return new Date(selectedPromo.endDate) < new Date();
  }, [selectedPromo]);

  // Pricing constants derived from CEO Hub Authority
  const originalPricePerPlot = 250000; 
  const currentPromoDiscount = selectedPromo ? (originalPricePerPlot - (selectedPromo.promoPrice || originalPricePerPlot)) : 0;
  const priceAfterDiscount = originalPricePerPlot - currentPromoDiscount;

  const emiBreakdown = useMemo(() => {
    if (installmentOption === 'Outright') return null;
    let months = parseInt(installmentOption) || 1;
    return {
      monthlyAmount: priceAfterDiscount / months,
      installments: months,
      totalPayable: priceAfterDiscount
    };
  }, [installmentOption, priceAfterDiscount]);

  const handleInitialSave = async () => {
    if (!selectedClient || isPromoExpired) return;
    setIsSaving(true);
    try {
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: installmentOption,
                total: priceAfterDiscount,
                balance: priceAfterDiscount - selectedClient.payment.paid,
                promoDetails: selectedPromo ? `Promo: ${selectedPromo.title} (Locked)` : undefined
            }
        };
        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: client.payment.paid + newTransaction.amount,
            balance: client.payment.balance - newTransaction.amount,
        }
    };
    await onSaveClient(updatedClient);
    setPaymentModalOpen(false);
  };

  const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

  // Notifications logic
  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  if (viewMode === 'reports') return <FinancialReportsView onBack={() => setViewMode('list')} clients={clients} staffList={[]} />;

  return (
    <div className="flex flex-col h-[calc(100vh-120px)] space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm font-medium">Single Source Pricing Consumption & Ledger Audit.</p>
        </div>
        <div className="flex gap-3">
          <Button 
            variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
            onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
            icon={<BellIcon className="w-5 h-5" />}
            className="relative"
          >
              Alerts
              {roleAlerts.length > 0 && (
                  <span className="absolute -top-1 -right-1 flex h-4 w-4">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                  </span>
              )}
          </Button>
          <Button variant="secondary" onClick={() => setViewMode('reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
              Reconciliation
          </Button>
        </div>
      </div>

      <div className="flex-grow flex gap-6 overflow-hidden">
        {/* Sub-module Sidebar */}
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
             <Select 
              label="Active Account" 
              value={selectedClientId || ''} 
              onChange={(e) => {
                  setSelectedClientId(Number(e.target.value));
                  setClientForInvoice(null);
                  setSelectedPromoId('none');
              }}
            >
              <option value="">-- Choose Client --</option>
              {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>
          </div>
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        {/* Workspace Area */}
        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName}
                    onReschedule={() => {}}
                    onMarkRead={(id) => setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">Select Client to Load Ledger</p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <Card title="Executive Account Ledger">
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Standard Unit Price</p>
                                <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(originalPricePerPlot)}</p>
                            </div>
                            <div className="md:col-span-2">
                                <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1 block">Apply Published Promotion</label>
                                <div className="flex gap-2">
                                    <Select 
                                        value={selectedPromoId} 
                                        onChange={(e) => setSelectedPromoId(e.target.value as any)}
                                        disabled={!!(selectedClient.payment as any).isInitialized}
                                        containerClassName="flex-grow"
                                    >
                                        <option value="none">No Promo Applied (Standard Pricing)</option>
                                        {promotions.filter(p => p.applicablePropertyId === 'all' || p.applicablePropertyId === (selectedClient as any).propertyId).map(promo => (
                                            <option key={promo.id} value={promo.id}>
                                                {promo.title} {new Date(promo.endDate) < new Date() ? '(EXPIRED)' : ''}
                                            </option>
                                        ))}
                                    </Select>
                                    {selectedPromo && (
                                        <Badge variant={isPromoExpired ? 'danger' : 'success'} className="flex items-center gap-1 uppercase font-black px-4">
                                            {isPromoExpired ? 'Expired' : 'Active'}
                                        </Badge>
                                    )}
                                </div>
                                {isPromoExpired && (
                                    <p className="text-[10px] text-red-500 font-bold mt-1 flex items-center gap-1">
                                        <ExclamationTriangleIcon className="w-3 h-3" />
                                        Locked: Expired promotions cannot be applied to new snapshots.
                                    </p>
                                )}
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Snapshot Status</p>
                                <Badge variant={(selectedClient.payment as any).isInitialized ? 'success' : 'warning'}>
                                    {(selectedClient.payment as any).isInitialized ? 'LOCKED' : 'DRAFT'}
                                </Badge>
                            </div>
                        </div>
                    </Card>

                    <Card title="Financial Snapshot Configuration" action={<Badge variant="info">Authority: CEO Hub</Badge>}>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Base Price Consumption</label>
                                <Input value={formatCurrency(originalPricePerPlot)} readOnly className="bg-gray-50 font-bold opacity-70" />
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-indigo-400 uppercase mb-1 block">Promo Adjustment</label>
                                <Input value={`- ${formatCurrency(currentPromoDiscount)}`} readOnly className="bg-gray-50 font-bold text-red-600 opacity-70" />
                            </div>
                            <Select 
                                label="Snapshot Payment Plan*" 
                                value={installmentOption} 
                                onChange={(e) => setInstallmentOption(e.target.value)}
                                disabled={!!(selectedClient.payment as any).isInitialized}
                            >
                                <option value="Outright">Outright Payment</option>
                                <option value="3">3 Month Plan</option>
                                <option value="6">6 Month Plan</option>
                                <option value="12">12 Month Plan</option>
                            </Select>
                        </div>
                        {emiBreakdown && (
                            <div className="mt-8 p-6 bg-indigo-50 dark:bg-indigo-900/20 rounded-xl border border-indigo-100 dark:border-indigo-800">
                                <h4 className="text-xs font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                    <TagIcon className="w-4 h-4" /> Locked Plan Breakdown
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                    <div>
                                        <p className="text-[10px] font-black text-indigo-400 uppercase">Per Installment</p>
                                        <p className="text-xl font-black text-indigo-700 dark:text-indigo-300">{formatCurrency(emiBreakdown.monthlyAmount)}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-black text-indigo-400 uppercase">Agreed Total</p>
                                        <p className="text-xl font-black text-indigo-700 dark:text-indigo-300">{formatCurrency(emiBreakdown.totalPayable)}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-black text-indigo-400 uppercase">Promo Applied</p>
                                        <p className="text-sm font-bold text-indigo-600 truncate">{selectedPromo?.title || 'None'}</p>
                                    </div>
                                </div>
                            </div>
                        )}
                        <div className="mt-8 pt-6 border-t border-gray-100 dark:border-gray-700 flex justify-between items-center">
                            <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                <LockClosedIcon className="w-3 h-3" />
                                Pricing Authority enforced via CEO Hub
                            </div>
                            <Button 
                                onClick={handleInitialSave}
                                disabled={!!(selectedClient.payment as any).isInitialized || isPromoExpired}
                                isLoading={isSaving}
                                icon={<CheckCircleIcon className="w-5 h-5" />}
                                className="px-12 py-3 shadow-lg"
                            >
                                {(selectedClient.payment as any).isInitialized ? 'Snapshot Locked' : 'Initialize & Lock Snapshot'}
                            </Button>
                        </div>
                    </Card>

                    <Card title="Account Standing" className="bg-gray-50/50 dark:bg-gray-900/20 border-dashed">
                         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-center md:text-left">
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Snapshot Commitment</p>
                                <p className="text-2xl font-black text-gray-900 dark:text-white">{formatCurrency(selectedClient.payment.total)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Credited</p>
                                <p className="text-2xl font-black text-green-600">{formatCurrency(selectedClient.payment.paid)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Remaining Liability</p>
                                <p className={`text-2xl font-black ${selectedClient.payment.balance < 0 ? 'text-purple-600' : 'text-red-600'}`}>
                                    {formatCurrency(selectedClient.payment.balance)}
                                </p>
                            </div>
                        </div>
                    </Card>
                </div>
            ) : (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <Card title="Transactional Audit Log" action={
                        <div className="flex gap-2">
                             <Button 
                                variant="primary" 
                                size="sm" 
                                disabled={!isCEO && currentStaff.roleId !== 'Administrator'}
                                onClick={() => setPaymentModalOpen(true)}
                                icon={<PlusCircleIcon className="w-4 h-4" />}
                            >
                                Post Transaction
                            </Button>
                        </div>
                    }>
                        <TableContainer className="border-0 shadow-none">
                            <table className="w-full text-sm text-left">
                                <Thead>
                                    <tr>
                                        <Th>Protocol</Th>
                                        <Th>Scheduled</Th>
                                        <Th>Execution Date</Th>
                                        <Th className="text-right">Credit Amount</Th>
                                        <Th className="text-center">Verification</Th>
                                        <Th className="text-right">Running Balance</Th>
                                    </tr>
                                </Thead>
                                <Tbody>
                                    {selectedClient.payment.paymentHistory.length === 0 ? (
                                        <Tr>
                                            <Td colSpan={6} className="text-center py-12 text-gray-400 italic font-medium uppercase tracking-tighter">Awaiting first ledger transaction entry</Td>
                                        </Tr>
                                    ) : (
                                        selectedClient.payment.paymentHistory.map((txn, idx) => (
                                            <Tr key={txn.id || idx}>
                                                <Td className="font-bold text-gray-600 dark:text-gray-400 uppercase tracking-tighter text-xs">{(txn as any).type || 'Lump Sum'}</Td>
                                                <Td className="text-gray-500 font-medium">{selectedClient.payment.dueDate || '—'}</Td>
                                                <Td className="font-bold text-gray-900 dark:text-white">{txn.date || '—'}</Td>
                                                <Td className="text-right font-black text-green-600">{formatCurrency(txn.amount)}</Td>
                                                <Td className="text-center">
                                                    <Badge variant="success">VERIFIED</Badge>
                                                </Td>
                                                <Td className="text-right font-black text-gray-900 dark:text-white">
                                                    {formatCurrency(selectedClient.payment.total - selectedClient.payment.paymentHistory.slice(0, idx + 1).reduce((s,t)=>s+t.amount,0))}
                                                </Td>
                                            </Tr>
                                        ))
                                    )}
                                </Tbody>
                            </table>
                        </TableContainer>
                    </Card>
                </div>
            )}
        </div>

        {selectedClient && (
            <RecordPaymentModal 
                isOpen={isPaymentModalOpen} 
                onClose={() => setPaymentModalOpen(false)} 
                client={selectedClient}
                onSave={(data) => handleRecordPayment(selectedClient, data)}
            />
        )}
      </div>
    </div>
  );
};

export default AccountManagementPage;

import React, { useState, ChangeEvent, FormEvent, useMemo } from 'react';
import { Promotion, Property, PlotSize } from '../types';
import { ArrowLeftIcon, PencilIcon, TrashIcon, UploadIcon, CurrencyDollarIcon, TagIcon, ClockIcon } from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select, Textarea } from '../components/ui/Input';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { uploadFile } from '../services/storageService';

interface PromotionsPageProps {
    promotions: Promotion[];
    onSavePromotion: (promotion: Promotion) => Promise<void>;
    onDeletePromotion: (promotionId: number) => Promise<void>;
    properties: Property[];
    showForm?: boolean;
    onBack?: () => void;
}

const initialFormState: Omit<Promotion, 'id'> = {
    title: '',
    description: '',
    promoType: 'Discount',
    startDate: '',
    endDate: '',
    discountValue: 0,
    applicablePropertyId: 'all',
    status: 'Active',
    bannerImage: undefined,
    targetPlotSize: '70x100 ft',
    numberOfPlots: 1,
    originalPrice: 0,
    promoPrice: 0
};

const PromotionsPage: React.FC<PromotionsPageProps> = ({ promotions, onSavePromotion, onDeletePromotion, properties, showForm = false, onBack }) => {
    const [formData, setFormData] = useState<Omit<Promotion, 'id'>>(initialFormState);
    const [editingId, setEditingId] = useState<number | null>(null);
    const [bannerPreview, setBannerPreview] = useState<string | null>(null);
    const [bannerFile, setBannerFile] = useState<File | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    // Compute original price based on selected property
    const currentOriginalPrice = useMemo(() => {
        if (formData.applicablePropertyId === 'all') return 0;
        const prop = properties.find(p => p.id === formData.applicablePropertyId);
        return prop ? prop.price : 0;
    }, [formData.applicablePropertyId, properties]);

    const computedPromoPrice = useMemo(() => {
        const discount = formData.discountValue || 0;
        return Math.max(0, currentOriginalPrice - discount);
    }, [currentOriginalPrice, formData.discountValue]);

    const handleInputChange = (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        const isNumber = type === 'number';
        setFormData(prev => ({ ...prev, [name]: isNumber ? parseFloat(value) || 0 : value }));
    };

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setBannerFile(file);
            const reader = new FileReader();
            reader.onloadend = () => {
                setBannerPreview(reader.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleStatusToggle = (promo: Promotion) => {
        const updatedPromo: Promotion = { ...promo, status: promo.status === 'Active' ? 'Inactive' : 'Active' };
        onSavePromotion(updatedPromo);
    };

    const handleReset = () => {
        setFormData(initialFormState);
        setEditingId(null);
        setBannerPreview(null);
        setBannerFile(null);
        setIsSaving(false);
    };

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        try {
            let bannerUrl = formData.bannerImage;
            if (bannerFile) {
                bannerUrl = await uploadFile(bannerFile, `promotions/banners/${bannerFile.name}`);
            }

            const promoToSave: Promotion = {
                id: editingId !== null ? editingId : Date.now(),
                ...formData,
                originalPrice: currentOriginalPrice,
                promoPrice: computedPromoPrice,
                bannerImage: bannerUrl,
            };
            await onSavePromotion(promoToSave);
            handleReset();
        } catch (error) {
            console.error("Error saving promotion:", error);
            alert("Failed to save promotion.");
        } finally {
            setIsSaving(false);
        }
    };

    const handleEdit = (promo: Promotion) => {
        setEditingId(promo.id);
        setFormData({
            title: promo.title,
            description: promo.description,
            promoType: promo.promoType,
            startDate: promo.startDate,
            endDate: promo.endDate,
            discountValue: promo.discountValue,
            applicablePropertyId: promo.applicablePropertyId,
            status: promo.status,
            bannerImage: promo.bannerImage,
            targetPlotSize: promo.targetPlotSize || '70x100 ft',
            numberOfPlots: promo.numberOfPlots || 1,
            originalPrice: promo.originalPrice || 0,
            promoPrice: promo.promoPrice || 0
        });
        setBannerPreview(promo.bannerImage || null);
        setBannerFile(null);
        window.scrollTo(0, 0);
    };

    const handleDelete = (id: number) => {
        if (confirm('Permanently delete this promotion? It will be removed from all future snapshots.')) {
            onDeletePromotion(id);
        }
    };

    return (
        <div className="space-y-6">
            <div>
                 {onBack && (
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" /> Back to CEO Hub
                    </button>
                )}
                <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Promotional Pricing Authority</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1 font-medium">Offers created here define snapshots in Account Management.</p>
            </div>

            {showForm && (
              <Card title={editingId ? 'Edit Authorized Promotion' : 'Authorize New Promotion'}>
                  <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      <Input label="Protocol Title*" name="title" value={formData.title} onChange={handleInputChange} required placeholder="e.g. 2024 Anniversary Special" />
                      <div className="md:col-span-2">
                          <Textarea label="Executive Description*" name="description" value={formData.description} onChange={handleInputChange} required rows={1} placeholder="Internal rationale for this discount tier..." />
                      </div>

                      <Select label="Jurisdiction*" name="applicablePropertyId" value={formData.applicablePropertyId} onChange={handleInputChange} required>
                          <option value="all">Global Availability (All Properties)</option>
                          {properties.map(p => <option key={p.id} value={p.id}>{p.location}</option>)}
                      </Select>

                      <Select label="Target Plot Scale" name="targetPlotSize" value={formData.targetPlotSize} onChange={handleInputChange} required>
                          <option>70x100 ft</option>
                          <option>70x50 ft</option>
                          <option>60x80 ft</option>
                      </Select>

                      <Input label="Volume Cap*" type="number" name="numberOfPlots" value={formData.numberOfPlots} onChange={handleInputChange} required />

                      <Input label="Authority Discount (GHC)*" type="number" name="discountValue" value={formData.discountValue} onChange={handleInputChange} required className="font-bold text-red-600" />

                      <div className="p-3 bg-gray-50 dark:bg-gray-900 rounded-lg border border-gray-100 dark:border-gray-800">
                          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Standard Market Rate</p>
                          <p className="text-sm font-bold text-gray-600 dark:text-gray-400">GHC {currentOriginalPrice.toLocaleString()}</p>
                      </div>

                      <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-100 dark:border-blue-800">
                          <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Target Promo Snapshot</p>
                          <p className="text-lg font-black text-blue-600 dark:text-blue-300">GHC {computedPromoPrice.toLocaleString()}</p>
                          <p className="text-[9px] text-blue-500 italic mt-1">Calculated Price Consumption</p>
                      </div>

                      <Input label="Activation Date" type="date" name="startDate" value={formData.startDate} onChange={handleInputChange} />
                      <Input label="Expiry Date" type="date" name="endDate" value={formData.endDate} onChange={handleInputChange} />

                      <Select label="Operational Status" name="status" value={formData.status} onChange={handleInputChange}>
                          <option value="Active">Authorized / Active</option>
                          <option value="Inactive">Revoked / Inactive</option>
                      </Select>

                       <div className="md:col-span-3">
                          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 uppercase text-[10px] font-black mb-1">Banner Asset</label>
                          <div className="mt-1 flex items-center gap-4">
                             {bannerPreview && <img src={bannerPreview} alt="Banner" className="h-12 w-24 object-cover rounded-md border border-gray-200" />}
                             <label htmlFor="banner-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 flex items-center gap-2 transition-colors">
                                <UploadIcon className="w-5 h-5"/>
                                <span className="uppercase text-[10px] font-black">{bannerFile ? 'Change' : (bannerPreview ? 'Change' : 'Upload')}</span>
                                <input id="banner-upload" name="bannerImage" type="file" className="sr-only" onChange={handleFileChange} accept="image/*" />
                             </label>
                          </div>
                      </div>
                      <div className="md:col-span-3 flex justify-end gap-3 mt-4">
                          <Button type="button" variant="secondary" onClick={handleReset}>Cancel</Button>
                          <Button type="submit" isLoading={isSaving} className="uppercase font-black tracking-tighter">{editingId ? 'Update Protocol' : 'Publish Offer'}</Button>
                      </div>
                  </form>
              </Card>
            )}

            <TableContainer>
                <table className="w-full text-sm text-left">
                    <Thead>
                        <tr>
                            <Th>Protocol</Th>
                            <Th>Targeting</Th>
                            <Th>Authority Pricing</Th>
                            <Th>Lifecycle</Th>
                            <Th className="text-center">Status</Th>
                            <Th className="text-center">Manage</Th>
                        </tr>
                    </Thead>
                    <Tbody>
                        {promotions.map(promo => {
                            const isExpired = new Date(promo.endDate) < new Date();
                            return (
                                <Tr key={promo.id}>
                                    <Td className="font-bold text-gray-900 dark:text-white">
                                        <div className="flex flex-col">
                                            <span>{promo.title}</span>
                                            <span className="text-[10px] text-indigo-500 font-black uppercase tracking-widest">{promo.promoType}</span>
                                        </div>
                                    </Td>
                                    <Td className="text-gray-600 dark:text-gray-400">
                                        <div className="text-xs">
                                            <p className="font-medium">{promo.targetPlotSize} @ {promo.applicablePropertyId === 'all' ? 'GLOBAL' : properties.find(p=>p.id === promo.applicablePropertyId)?.location}</p>
                                            <p className="text-[10px] font-black text-gray-400 uppercase">{promo.numberOfPlots} Slots Available</p>
                                        </div>
                                    </Td>
                                    <Td>
                                        <div className="font-black text-blue-600 dark:text-blue-400">GHC {promo.promoPrice?.toLocaleString()}</div>
                                        <div className="text-[9px] text-gray-400 line-through">MKT: GHC {promo.originalPrice?.toLocaleString()}</div>
                                    </Td>
                                    <Td className="text-gray-500 text-xs">
                                        <div className="flex items-center gap-1 font-semibold uppercase tracking-tighter">
                                            <ClockIcon className="w-3 h-3" /> {promo.startDate} <span className="text-gray-300">→</span> {promo.endDate}
                                        </div>
                                        {isExpired && <span className="text-[9px] text-red-500 font-black uppercase tracking-widest mt-1 block">Term Expired</span>}
                                    </Td>
                                    <Td className="text-center">
                                        <button onClick={() => handleStatusToggle(promo)}>
                                            <Badge variant={isExpired ? 'danger' : (promo.status === 'Active' ? 'success' : 'neutral')}>
                                                {isExpired ? 'EXPIRED' : promo.status.toUpperCase()}
                                            </Badge>
                                        </button>
                                    </Td>
                                    <Td className="text-center">
                                        <div className="flex items-center justify-center gap-2">
                                            <button onClick={() => handleEdit(promo)} className="text-gray-400 hover:text-blue-600 p-1"><PencilIcon className="w-5 h-5"/></button>
                                            <button onClick={() => handleDelete(promo.id)} className="text-gray-400 hover:text-red-600 p-1"><TrashIcon className="w-5 h-5"/></button>
                                        </div>
                                    </Td>
                                </Tr>
                            );
                        })}
                    </Tbody>
                </table>
                {promotions.length === 0 && <div className="text-center py-20 text-gray-400 italic font-black uppercase tracking-widest">No promotion protocols configured.</div>}
            </TableContainer>
        </div>
    );
};

export default PromotionsPage;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification, Promotion } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    CheckCircleIcon,
    LockClosedIcon,
    BanknotesIcon,
    ShieldCheckIcon,
    DocumentTextIcon,
    PlusCircleIcon,
    ChartBarIcon,
    TagIcon,
    ExclamationTriangleIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select } from '../components/ui/Input';
import { Badge } from '../components/ui/Badge';
// FIX: Import Table UI components to resolve compilation errors
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { RecordPaymentModal } from '../components/FinancialRecordEditor';
import { FinancialReportsView } from '../components/FinancialReportsView';
import { NotificationCenter } from '../components/NotificationCenter';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useAuth } from '../context/AuthContext';
import { usePromotions } from '../hooks/useAppData';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage 
}) => {
  const { promotions } = usePromotions();
  const [viewMode, setViewMode] = useState<'list' | 'alerts' | 'reports'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(null);
  const [isPaymentModalOpen, setPaymentModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');
  const [selectedPromoId, setSelectedPromoId] = useState<number | 'none'>('none');

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (clientForInvoice?.id || selectedClientId))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);

  // PROMO AUTHORITY LOGIC
  const activePropertyPromo = useMemo(() => {
    if (!selectedClient || !promotions) return null;
    return promotions.find(p => 
        (p.applicablePropertyId === 'all' || p.applicablePropertyId === (selectedClient as any).propertyId) &&
        p.status === 'Active'
    );
  }, [selectedClient, promotions]);

  const selectedPromo = useMemo(() => {
    if (selectedPromoId === 'none') return null;
    return promotions.find(p => p.id === selectedPromoId);
  }, [selectedPromoId, promotions]);

  const isPromoExpired = useMemo(() => {
    if (!selectedPromo) return false;
    return new Date(selectedPromo.endDate) < new Date();
  }, [selectedPromo]);

  // Pricing constants derived from CEO Hub Authority
  const originalPricePerPlot = 250000; 
  const currentPromoDiscount = selectedPromo ? (originalPricePerPlot - (selectedPromo.promoPrice || originalPricePerPlot)) : 0;
  const priceAfterDiscount = originalPricePerPlot - currentPromoDiscount;

  const emiBreakdown = useMemo(() => {
    if (installmentOption === 'Outright') return null;
    let months = parseInt(installmentOption) || 1;
    return {
      monthlyAmount: priceAfterDiscount / months,
      installments: months,
      totalPayable: priceAfterDiscount
    };
  }, [installmentOption, priceAfterDiscount]);

  const handleInitialSave = async () => {
    if (!selectedClient || isPromoExpired) return;
    setIsSaving(true);
    try {
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: installmentOption,
                total: priceAfterDiscount,
                balance: priceAfterDiscount - selectedClient.payment.paid,
                promoDetails: selectedPromo ? `Promo: ${selectedPromo.title} (Locked)` : undefined
            }
        };
        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: client.payment.paid + newTransaction.amount,
            balance: client.payment.balance - newTransaction.amount,
        }
    };
    await onSaveClient(updatedClient);
    setPaymentModalOpen(false);
  };

  const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

  // Notifications logic
  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  if (viewMode === 'reports') return <FinancialReportsView onBack={() => setViewMode('list')} clients={clients} staffList={[]} />;

  return (
    <div className="flex flex-col h-[calc(100vh-120px)] space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
            <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm font-medium">Single Source Pricing Consumption & Ledger Audit.</p>
        </div>
        <div className="flex gap-3">
          <Button 
            variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
            onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
            icon={<BellIcon className="w-5 h-5" />}
            className="relative"
          >
              Alerts
              {roleAlerts.length > 0 && (
                  <span className="absolute -top-1 -right-1 flex h-4 w-4">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                  </span>
              )}
          </Button>
          <Button variant="secondary" onClick={() => setViewMode('reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
              Reconciliation
          </Button>
        </div>
      </div>

      <div className="flex-grow flex gap-6 overflow-hidden">
        {/* Sub-module Sidebar */}
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
             <Select 
              label="Active Account" 
              value={selectedClientId || ''} 
              onChange={(e) => {
                  setSelectedClientId(Number(e.target.value));
                  setClientForInvoice(null);
                  setSelectedPromoId('none');
              }}
            >
              <option value="">-- Choose Client --</option>
              {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>
          </div>
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        {/* Workspace Area */}
        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName}
                    onReschedule={() => {}}
                    onMarkRead={(id) => setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">Select Client to Load Ledger</p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <Card title="Executive Account Ledger">
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Standard Unit Price</p>
                                <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(originalPricePerPlot)}</p>
                            </div>
                            <div className="md:col-span-2">
                                <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1 block">Apply Published Promotion</label>
                                <div className="flex gap-2">
                                    <Select 
                                        value={selectedPromoId} 
                                        onChange={(e) => setSelectedPromoId(e.target.value as any)}
                                        disabled={!!(selectedClient.payment as any).isInitialized}
                                        containerClassName="flex-grow"
                                    >
                                        <option value="none">No Promo Applied (Standard Pricing)</option>
                                        {promotions.filter(p => p.applicablePropertyId === 'all' || p.applicablePropertyId === (selectedClient as any).propertyId).map(promo => (
                                            <option key={promo.id} value={promo.id}>
                                                {promo.title} {new Date(promo.endDate) < new Date() ? '(EXPIRED)' : ''}
                                            </option>
                                        ))}
                                    </Select>
                                    {selectedPromo && (
                                        <Badge variant={isPromoExpired ? 'danger' : 'success'} className="flex items-center gap-1 uppercase font-black px-4">
                                            {isPromoExpired ? 'Expired' : 'Active'}
                                        </Badge>
                                    )}
                                </div>
                                {isPromoExpired && (
                                    <p className="text-[10px] text-red-500 font-bold mt-1 flex items-center gap-1">
                                        <ExclamationTriangleIcon className="w-3 h-3" />
                                        Locked: Expired promotions cannot be applied to new snapshots.
                                    </p>
                                )}
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Snapshot Status</p>
                                <Badge variant={(selectedClient.payment as any).isInitialized ? 'success' : 'warning'}>
                                    {(selectedClient.payment as any).isInitialized ? 'LOCKED' : 'DRAFT'}
