                    {step === 2 && (
                        <div>
                             <FormSection title="Property & Transaction Details">
                                <div className="sm:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4">
                                    <SmartSelectField 
                                        id="location" 
                                        label="Location*" 
                                        value={formData.location} 
                                        onChange={handleLocationChange} 
                                        onBlur={handleBlur} 
                                        required 
                                        disabled={!isPropertyAvailable}
                                        error={touched.location ? errors.location : undefined} 
                                        isTouched={touched.location}
                                    >
                                        <option value="">{isPropertyAvailable ? '-- Select Location --' : 'No properties available'}</option>
                                        {properties.map(p => (
                                            <option key={p.id} value={p.location}>{p.location}</option>
                                        ))}
                                    </SmartSelectField>

                                    <SmartInputField 
                                        id="numberOfPlots" 
                                        label="Number of Plots*" 
                                        type="number" 
                                        value={formData.numberOfPlots} 
                                        onChange={handlePlotsChange} 
                                        onBlur={handleBlur} 
                                        required 
                                        placeholder="1"
                                        error={touched.numberOfPlots ? errors.numberOfPlots : undefined} 
                                        isTouched={touched.numberOfPlots} 
                                    />

                                    <SmartInputField 
                                        id="price" 
                                        label="Total Price (GHC)*" 
                                        value={formData.price} 
                                        readOnly 
                                        required
                                        error={touched.price ? errors.price : undefined}
                                        isTouched={touched.price}
                                        placeholder="Auto-calculated"
                                    />
                                </div>

                                {!isPropertyAvailable && (
                                    <p className="sm:col-span-2 text-xs text-amber-600 dark:text-amber-400 font-medium">
