                                    </p>
                                )}
                                <SmartInputField id="plotNumber" label="Plot Number(s)" value={formData.plotNumber} onChange={handleChange} onBlur={handleBlur} required error={touched.plotNumber ? errors.plotNumber : undefined} isTouched={touched.plotNumber}/>
                                <SmartSelectField id="propertyType" label="Property Type" value={formData.propertyType} onChange={handleChange} onBlur={handleBlur} error={touched.propertyType ? errors.propertyType : undefined} isTouched={touched.propertyType}>
                                    <option>Residential</option>
                                    <option>Commercial</option>
                                </SmartSelectField>
                                <SmartInputField id="plannedDevelopmentYear" label="Year of Planned Development" type="number" value={formData.plannedDevelopmentYear} onChange={handleChange} onBlur={handleBlur} error={touched.plannedDevelopmentYear ? errors.plannedDevelopmentYear : undefined} isTouched={touched.plannedDevelopmentYear}/>
                                <SmartInputField id="paymentDate" label="Date of Initial Payment" type="date" value={formData.paymentDate} onChange={handleChange} onBlur={handleBlur} required error={touched.paymentDate ? errors.paymentDate : undefined} isTouched={touched.paymentDate}/>
                                <SmartSelectField id="paymentMethod" label="Initial Payment Method" value={formData.paymentMethod} onChange={handleChange} onBlur={handleBlur} error={touched.paymentMethod ? errors.paymentMethod : undefined} isTouched={touched.paymentMethod}>
                                    <option>Cash</option>
                                    <option>Bank Transfer</option>
                                    <option>MoMo</option>
                                    <option>Cheque</option>
                                    <option>Other</option>
                                </SmartSelectField>
                                <div className={`sm:col-span-2 p-3 rounded-md border relative ${touched.filledFormPdf && errors.filledFormPdf ? 'border-red-500 dark:border-red-600' : 'border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800'}`}>
                                    <label htmlFor="filledFormPdf" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Upload Filled Client Form <span className="text-gray-400 text-xs">(Optional)</span></label>
                                    <div className="mt-1 flex items-center">
                                        <label htmlFor="filledFormPdf-upload" className="relative cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm leading-4 font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                                            <span>{pdfFile ? pdfFile.name : (formData.filledFormPdf ? 'File uploaded' : 'Select file')}</span>
                                            <input id="filledFormPdf-upload" name="filledFormPdf" type="file" className="sr-only" onChange={handlePdfChange} accept="application/pdf" />
                                        </label>
                                        {(pdfFile || formData.filledFormPdf) && <span className="ml-3 text-sm text-green-600">✔ PDF selected</span>}
                                    </div>
                                    {touched.filledFormPdf && errors.filledFormPdf && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{errors.filledFormPdf}</p>}
                                    {touched.filledFormPdf && !errors.filledFormPdf && (
                                        <CheckCircleIcon className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-green-500 pointer-events-none" />
                                    )}
                                </div>
                             </FormSection>

                            <FormSection title="What Name & Address Do You Want to Appear on Your Indenture?">
                                <SmartInputField id="indentureName" label="Full Name" value={formData.indentureName} onChange={handleChange} onBlur={handleBlur} required error={touched.indentureName ? errors.indentureName : undefined} isTouched={touched.indentureName}/>
                                <SmartInputField id="indentureAddress" label="Postal Address" value={formData.indentureAddress} onChange={handleChange} onBlur={handleBlur} required error={touched.indentureAddress ? errors.indentureAddress : undefined} isTouched={touched.indentureAddress}/>
                            </FormSection>
                        </div>
                    )}
                    {step === 3 && (
                        <div>
                             <FormSection title="For Office Use Only">
                                <SmartInputField id="salesRep" label="Intermediary Sales Rep" value={formData.salesRep} onChange={handleChange} onBlur={handleBlur} required error={touched.salesRep ? errors.salesRep : undefined} isTouched={touched.salesRep}/>
                                <SmartInputField id="salesManager" label="Approving Sales Manager Name" value={formData.salesManager} onChange={handleChange} onBlur={handleBlur} required error={touched.salesManager ? errors.salesManager : undefined} isTouched={touched.salesManager}/>
                                <SmartInputField id="accountsHead" label="Approval Accounts Head Name" value={formData.accountsHead} onChange={handleChange} onBlur={handleBlur} required error={touched.accountsHead ? errors.accountsHead : undefined} isTouched={touched.accountsHead}/>
                                <SmartInputField id="clerk" label="Receiving Clerk on Duty Name" value={formData.clerk} onChange={handleChange} onBlur={handleBlur} required error={touched.clerk ? errors.clerk : undefined} isTouched={touched.clerk}/>
                            </FormSection>
                        </div>
                    )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>
                        {step > 1 && (
                            <button type="button" onClick={handleBack} className="bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors">
                                Back
                            </button>
                        )}
                    </div>
                    <div>
                        {step < 3 ? (
                             <button type="button" onClick={handleNext} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors">
                                Next: {step === 1 ? 'Acquisition Details' : 'Office Details'}
                            </button>
                        ) : (
                            <div className="flex items-center gap-4">
                                {!editingClient ? (
                                    <button 
                                        type="button" 
                                        onClick={handleAddPaymentDetails} 
                                        disabled={!isFormValid || !isPropertyAvailable || isProcessing} 
                                        className="bg-blue-600 text-white font-black uppercase tracking-widest py-2.5 px-8 rounded-lg hover:bg-blue-700 transition-all shadow-lg hover:shadow-blue-500/20 disabled:bg-gray-400 disabled:cursor-not-allowed flex items-center gap-2"
                                    >
                                        {isProcessing ? 'Processing...' : 'Add Payment Details'}
                                        {!isProcessing && <CheckCircleIcon className="w-5 h-5" />}
                                    </button>
                                ) : (
                                    <button 
                                        type="button" 
                                        onClick={handleAddPaymentDetails} 
                                        disabled={!isFormValid || !isPropertyAvailable || isProcessing} 
                                        className="bg-green-600 text-white font-semibold py-2 px-6 rounded-lg hover:bg-green-700 transition-colors"
                                    >
                                        Update Details
                                    </button>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ClientForm;

import React, { useMemo, useState } from 'react';
import { 
    BanknotesIcon, 
    BuildingLibraryIcon, 
    UsersIcon, 
    BriefcaseIcon, 
    DocumentPlusIcon, 
    EyeIcon, 
    MegaphoneIcon, 
    ChartBarIcon, 
    CurrencyDollarIcon, 
    ChartPieIcon, 
    DocumentTextIcon, 
    PlusCircleIcon, 
    PencilIcon, 
    TrashIcon, 
    ArrowTrendingUpIcon,
    DocumentDuplicateIcon
} from '../components/icons/DummyIcons';
import { Property, Client, Staff, Role, Invoice, ActivityLog } from '../types';
import UserFormModal from '../components/UserFormModal';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { useStaff } from '../hooks/useAppData';

interface CEOHubProps {
    setActivePage: (page: string, context?: any) => void;
    properties: Property[];
    clients: Client[];
    invoices: Invoice[];
    staff: Staff[];
    roles: Role[];
    onViewStaffActivity: (staff: Staff) => void;
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const CEOStatCard: React.FC<{ icon: React.ReactNode; title: string; value: string; bgColor: string; darkBgColor: string }> = ({ icon, title, value, bgColor, darkBgColor }) => (
  <Card className="flex flex-row items-center space-x-4 p-4">
    <div className={`p-3 rounded-full ${bgColor} ${darkBgColor}`}>
      {icon}
    </div>
    <div>
      <p className="text-sm font-medium text-gray-500 dark:text-gray-400">{title}</p>
      <p className="text-2xl font-bold text-gray-800 dark:text-white">{value}</p>
    </div>
  </Card>
);

const QuickActionButton: React.FC<{ icon: React.ReactNode; label: string; color: string; hoverColor: string; onClick?: () => void; }> = ({ icon, label, color, hoverColor, onClick }) => (
    <button onClick={onClick} className={`flex-1 flex flex-col items-center justify-center p-4 rounded-lg text-white font-semibold transition-colors ${color} ${hoverColor} shadow-md`}>
        {icon}
        <span className="mt-2 text-sm text-center">{label}</span>
    </button>
);

const CEOHub: React.FC<CEOHubProps> = ({ setActivePage, properties, clients, staff, roles, onViewStaffActivity, addActivityLog, invoices }) => {
    const { saveStaff, deleteStaff } = useStaff();

    const [isStaffModalOpen, setStaffModalOpen] = useState(false);
    const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
    const [staffToDelete, setStaffToDelete] = useState<Staff | null>(null);

    const statsData = useMemo(() => {
        const totalRevenue = clients.reduce((sum, client) => sum + (client.payment?.paid || 0), 0);
        const totalLands = properties.length;
        const totalClients = clients.length;
        const activeDeals = clients.filter(c => (c.payment?.balance || 0) > 0).length;
        const plotsSold = properties.reduce((acc, p) => acc + (p.inventory?.reduce((sum, inv) => sum + (inv.sold || 0), 0) || 0), 0);
        const totalPlots = properties.reduce((acc, p) => acc + (p.inventory?.reduce((sum, inv) => sum + (inv.count || 0), 0) || 0), 0);
        return { totalRevenue, totalLands, totalClients, activeDeals, plotsSold, totalPlots };
    }, [clients, properties]);

    const handleSaveStaff = async (staffData: Partial<Staff>) => {
        try {
            if(editingStaff) {
                const updatedStaff = { ...editingStaff, ...staffData } as Staff;
                await saveStaff(updatedStaff);
                addActivityLog('Update', `Updated staff details for ${staffData.fullName}.`);
            } else {
                const nameParts = (staffData.fullName || 'User Name').split(' ');
                const initials = (nameParts[0]?.[0] || '' + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();
                const newStaff: Staff = { 
                    id: String(Date.now()), 
                    fullName: staffData.fullName!,
                    email: staffData.email!,
                    phone: staffData.phone,
                    password: staffData.password, 
                    roleId: staffData.roleId!,
                    status: staffData.status!,
                    lastLogin: 'Never',
                    initials: initials
                };
                await saveStaff(newStaff);
                addActivityLog('Create', `Created new staff account: ${newStaff.fullName}.`);
            }
            setStaffModalOpen(false);
            setEditingStaff(null);
        } catch (error: any) {
            alert(`Error saving staff: ${error.message || 'Unknown error'}`);
        }
    };

    const confirmDeleteStaff = async () => {
        if (staffToDelete) {
            await deleteStaff(staffToDelete.id);
            addActivityLog('Delete', `Deleted staff account: ${staffToDelete.fullName}.`);
            setStaffToDelete(null);
        }
    }

    const handleToggleStaffStatus = async (staffId: string) => {
        const staffMember = staff.find(s => s.id === staffId);
        if (staffMember) {
            const newStatus: Staff['status'] = staffMember.status === 'Active' ? 'Inactive' : 'Active';
            const updatedStaff = { ...staffMember, status: newStatus };
            await saveStaff(updatedStaff);
            addActivityLog('Update', `Set status for ${staffMember.fullName} to ${newStatus}.`);
        }
    };

    const formatCurrency = (amount: number) => {
        if (amount >= 1000000) return `GHC ${(amount / 1000000).toFixed(1)}M`;
        if (amount >= 1000) return `GHC ${(amount / 1000).toFixed(1)}k`;
        return `GHC ${amount.toLocaleString()}`;
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <h1 className="text-4xl font-black text-gray-900 dark:text-white tracking-tight">CEO Strategic Hub</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1 font-medium">Executive oversight and portfolio management.</p>
                </div>
            </div>

            {/* Top Level Stats */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
                <CEOStatCard icon={<BanknotesIcon className="w-6 h-6 text-green-600"/>} title="Gross Revenue" value={formatCurrency(statsData.totalRevenue)} bgColor="bg-green-100" darkBgColor="dark:bg-green-900/30" />
                <CEOStatCard icon={<BuildingLibraryIcon className="w-6 h-6 text-blue-600"/>} title="Land Portfolio" value={String(statsData.totalLands)} bgColor="bg-blue-100" darkBgColor="dark:bg-blue-900/30" />
                <CEOStatCard icon={<UsersIcon className="w-6 h-6 text-purple-600"/>} title="Total Clients" value={String(statsData.totalClients)} bgColor="bg-purple-100" darkBgColor="dark:bg-purple-900/30" />
                <CEOStatCard icon={<ArrowTrendingUpIcon className="w-6 h-6 text-orange-600"/>} title="Active Deals" value={String(statsData.activeDeals)} bgColor="bg-orange-100" darkBgColor="dark:bg-orange-900/30" />
                <CEOStatCard icon={<ChartPieIcon className="w-6 h-6 text-teal-600"/>} title="Plots Sold" value={String(statsData.plotsSold)} bgColor="bg-teal-100" darkBgColor="dark:bg-teal-900/30" />
                <CEOStatCard icon={<DocumentDuplicateIcon className="w-6 h-6 text-indigo-600"/>} title="Total Plots" value={String(statsData.totalPlots)} bgColor="bg-indigo-100" darkBgColor="dark:bg-indigo-900/30" />
            </div>

            {/* Quick Strategic Actions */}
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4">
                <QuickActionButton 
                    icon={<PlusCircleIcon className="w-6 h-6" />} 
                    label="New Land Acquisition" 
                    color="bg-blue-600" 
                    hoverColor="hover:bg-blue-700" 
                    onClick={() => setActivePage('New Land Acquisition')}
                />
                <QuickActionButton 
                    icon={<ChartBarIcon className="w-6 h-6" />} 
                    label="Purchase & Sale Management" 
                    color="bg-indigo-600" 
                    hoverColor="hover:bg-indigo-700" 
                    onClick={() => setActivePage('Purchase & Sale Management')}
                />
                <QuickActionButton 
                    icon={<MegaphoneIcon className="w-6 h-6" />} 
                    label="Marketing Promotions" 
                    color="bg-purple-600" 
                    hoverColor="hover:bg-purple-700" 
                    onClick={() => setActivePage('Promotions', { from: 'CEO Hub' })}
                />
                <QuickActionButton 
                    icon={<ChartBarIcon className="w-6 h-6" />} 
                    label="AI Data Analytics" 
                    color="bg-teal-600" 
                    hoverColor="hover:bg-teal-700" 
                    onClick={() => setActivePage('Analytics & Reports')}
                />
                 <QuickActionButton 
                    icon={<DocumentTextIcon className="w-6 h-6" />} 
                    label="Strategic Reports" 
                    color="bg-amber-600" 
                    hoverColor="hover:bg-amber-700" 
                    onClick={() => setActivePage('Advanced Reports')}
                />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Staff Management Table */}
                <div className="lg:col-span-2">
                    <Card title="Executive Team Management" action={<Button size="sm" onClick={() => {setEditingStaff(null); setStaffModalOpen(true);}} icon={<PlusCircleIcon className="w-4 h-4"/>}>Add Executive</Button>}>
                        <TableContainer className="border-0 shadow-none">
                            <table className="w-full text-sm text-left">
                                <Thead>
                                    <tr>
                                        <Th>Executive</Th>
                                        <Th>Role</Th>
                                        <Th className="text-center">Status</Th>
                                        <Th className="text-right">Actions</Th>
                                    </tr>
                                </Thead>
                                <Tbody>
                                    {staff.map(member => (
                                        <Tr key={member.id}>
                                            <Td className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center font-bold text-xs text-blue-600 dark:text-blue-300">
                                                    {member.initials}
                                                </div>
                                                <div>
                                                    <div className="font-bold text-gray-900 dark:text-white">{member.fullName}</div>
                                                    <div className="text-[10px] text-gray-400">{member.email}</div>
                                                </div>
                                            </Td>
                                            <Td>
                                                <Badge variant="info">{roles.find(r => r.id === member.roleId)?.name || 'Executive'}</Badge>
                                            </Td>
                                            <Td className="text-center">
                                                <button onClick={() => handleToggleStaffStatus(member.id)}>
