const initialFormData = {
    ownerNames: '',
    location: '',
    registrationStatus: '',
    purchaseAgreementDate: '',
    totalSizeAcres: '',
    pricePerAcre: '',
    totalPrice: '',
    familyName: '',
    nameOnSearch: '',
    officialSearchDoc: null,
    sitePlanDoc: null,
    leadNegotiators: '',
    familyContactPerson: '',
    phoneNumbers: ['', '', ''],
    additionalNotes: '',
    paymentAmountPerMonth: '',
    paymentPeriodMonths: '',
    recurringPaymentTime: '',
    payees: [],
    signingDate: new Date().toISOString().split('T')[0],
    plotsPerAcre: '6',
    pricePerPlot: '',
    // Data from Property Dossier Page 1
    plotPrefix: 'REF',
    inventory: [
        { size: '70x100 ft', count: 0, sold: 0, zone: '' }
    ] as (PlotInventory & { zone: string })[]
};

const LandPurchaseFormPage: React.FC<LandPurchaseFormPageProps> = ({ onBack, properties, onSaveProperty }) => {
    const [formData, setFormData] = useState<any>(() => ({
        ...initialFormData
    }));
    const [isSaved, setIsSaved] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [plotsPerAcreError, setPlotsPerAcreError] = useState('');

    useEffect(() => {
        const acres = parseFloat(formData.totalSizeAcres) || 0;
        const priceAcre = parseFloat(formData.pricePerAcre) || 0;
        const plotsAcre = parseFloat(formData.plotsPerAcre) || 0;
        const computedTotalCost = acres * priceAcre;
        const computedCostPerPlot = plotsAcre > 0 ? (priceAcre / plotsAcre) : 0;

        setFormData(prev => ({
            ...prev,
            totalPrice: computedTotalCost > 0 ? computedTotalCost.toFixed(2) : '',
            pricePerPlot: computedCostPerPlot > 0 ? computedCostPerPlot.toFixed(2) : ''
        }));
    }, [formData.totalSizeAcres, formData.pricePerAcre, formData.plotsPerAcre]);

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value } = e.target;

        if (name === 'plotsPerAcre' || name === 'totalSizeAcres' || name === 'pricePerAcre') {
            if (value !== '' && !/^\d*\.?\d*$/.test(value)) {
                if(name === 'plotsPerAcre') setPlotsPerAcreError('Please enter numbers only.');
                return;
            }
            if(name === 'plotsPerAcre') setPlotsPerAcreError('');
        }

        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (index: number, value: string) => {
        const newPhones = [...formData.phoneNumbers];
        newPhones[index] = value;
        setFormData(prev => ({...prev, phoneNumbers: newPhones}));
    };

    const addPayee = () => {
        if (formData.payees.length < 10) {
            setFormData(prev => ({
                ...prev,
                payees: [...prev.payees, { id: Date.now().toString(), name: '', acres: '', amount: '' }]
            }));
        }
    };

    const handlePayeeChange = (index: number, field: string, value: string) => {
        const newPayees = [...formData.payees];
        newPayees[index] = { ...newPayees[index], [field]: value };
        setFormData(prev => ({ ...prev, payees: newPayees }));
    };

    const removePayee = (id: string) => {
        setFormData(prev => ({ ...prev, payees: prev.payees.filter(p => p.id !== id) }));
    };

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        const { name, files } = e.target;
        setFormData(prev => ({ ...prev, [name]: (files && files.length > 0) ? files[0] : null }));
    };

    const formatCurrencyString = (val: string) => {
        const num = parseFloat(val);
        if (isNaN(num)) return '0.00';
        return new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(num);
    };

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        if (plotsPerAcreError || parseFloat(formData.plotsPerAcre) <= 0) {
            alert('Please provide a valid number of plots per acre.');
            return;
        }
        setIsSaving(true);

        try {
            const regStatusMap: Record<string, Property['registrationStatus']> = {
                'LRD': 'Titled', 'PVLMD': 'Indenture', 'SMD': 'Plotted', 'LVD': 'Indenture'
            };

            const totalSizeAcres = parseFloat(formData.totalSizeAcres) || 0;
            const propertyId = Date.now();

            let officialSearchDocUrl = '';
            if (formData.officialSearchDoc) {
                officialSearchDocUrl = await uploadFile(formData.officialSearchDoc, `properties/${propertyId}/legal/${formData.officialSearchDoc.name}`);
            }

            let sitePlanDocUrl = '';
            if (formData.sitePlanDoc) {
                sitePlanDocUrl = await uploadFile(formData.sitePlanDoc, `properties/${propertyId}/legal/${formData.sitePlanDoc.name}`);
            }

            const newProperty: Property = {
                id: propertyId,
                location: formData.location,
                description: `Land acquired from ${formData.ownerNames}`,
                size: totalSizeAcres,
                price: parseFloat(formData.pricePerPlot) || 0,
                costPrice: parseFloat(formData.pricePerPlot) || 0,
                inventory: formData.inventory.map(({ size, count, sold }: any) => ({ size, count, sold })), 
                registrationStatus: regStatusMap[formData.registrationStatus] || 'Plotted',
                plotPrefix: formData.plotPrefix
            } as any;

            await onSaveProperty(newProperty);
            setIsSaved(true);
            window.scrollTo(0, 0);
            setTimeout(() => {
                setIsSaved(false);
                setFormData({ ...initialFormData });
            }, 4000);
        } catch (error) {
            console.error("Error saving property:", error);
            alert("Failed to save property.");
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-wrap items-center justify-between gap-4">
                 <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors">
                        <ArrowLeftIcon className="w-5 h-5" />
                        Back to CEO Hub
                    </button>
                    <h1 className="text-3xl font-bold text-gray-800 dark:text-white mt-2 tracking-tight uppercase">New Land Acquisition</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Record details for newly purchased land assets.</p>
                </div>
            </div>

            {isSaved && (
                <div className="bg-green-100 dark:bg-green-900/30 border-l-4 border-green-500 text-green-700 dark:text-green-300 p-4 rounded-lg shadow-md" role="alert">
                    <div className="flex items-center">
                        <CheckCircleIcon className="w-6 h-6 mr-3"/>
                        <div>
                            <p className="font-bold">Acquisition Success!</p>
                            <p>Land record finalized and added to master property inventory.</p>
                        </div>
                    </div>
                </div>
            )}

            <form id="land-purchase-form" onSubmit={handleSubmit} className="space-y-6 pb-20">
                <Card title="Section 1: Land & Ownership Details">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <Input id="ownerNames" name="ownerNames" label="Name of Owner(s)" value={formData.ownerNames} onChange={handleChange} required containerClassName="md:col-span-2" />
                        <Input id="location" name="location" label="Location of Property" value={formData.location} onChange={handleChange} required />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-6 pt-4 border-t border-gray-200 dark:border-gray-700">
                        <Select id="registrationStatus" name="registrationStatus" label="Legal Registration Status" value={formData.registrationStatus} onChange={handleChange} required>
                            <option value="">Select status...</option>
                            <option value="LRD">LRD Registered</option>
                            <option value="PVLMD">PVLMD Licensed</option>
                            <option value="SMD">SMD Verified</option>
                            <option value="LVD">LVD Documented</option>
                        </Select>
                        <Input id="purchaseAgreementDate" name="purchaseAgreementDate" label="Date of Final Signing" type="date" value={formData.purchaseAgreementDate} onChange={handleChange} required />

                        <Input id="totalSizeAcres" name="totalSizeAcres" label="Number of Acres*" type="text" value={formData.totalSizeAcres} onChange={handleChange} placeholder="0.00" required />

                        <Input id="pricePerAcre" name="pricePerAcre" label="Cost per Acre (GHC)*" type="number" value={formData.pricePerAcre} onChange={handleChange} placeholder="0.00" className="no-spinner font-bold" required />

                        <Input id="totalPrice" name="totalPrice" label="Total Cost of Land (GHC)" type="text" value={formatCurrencyString(formData.totalPrice)} readOnly containerClassName="md:col-span-2 bg-gray-50/50" className="font-black text-gray-700 dark:text-white" />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6 pt-6 border-t-2 border-dashed border-gray-200 dark:border-gray-700 bg-blue-50/20 dark:bg-blue-900/5 p-4 rounded-xl">
                        <Input 
                            id="plotsPerAcre" 
                            name="plotsPerAcre" 
                            label="Number of Plots Per Acre*" 
                            type="text" 
                            value={formData.plotsPerAcre} 
                            onChange={handleChange} 
                            error={plotsPerAcreError}
                            placeholder="e.g. 6"
                            className="font-bold text-lg text-blue-700 dark:text-blue-300"
                        />

                        <div className="relative">
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Cost per Plot (GHC)</label>
                            <div className={`flex items-center px-3 py-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm h-[42px] transition-colors ${!formData.pricePerPlot ? 'bg-gray-100 opacity-60' : ''}`}>
                                <BanknotesIcon className="w-5 h-5 text-gray-400 mr-2" />
                                {formData.pricePerPlot ? (
                                    <span className="font-black text-lg text-gray-900 dark:text-white">
                                        GHC {formatCurrencyString(formData.pricePerPlot)}
                                    </span>
                                ) : (
                                    <span className="text-xs text-amber-600 dark:text-amber-400 italic">
                                        Enter cost per acre to calculate
                                    </span>
                                )}
                            </div>
                        </div>
                    </div>
                </Card>

                <Card title="Section 2: Official & Legal Documentation">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <Input id="familyName" name="familyName" label="Official Name of Granting Family" value={formData.familyName} onChange={handleChange} />
                        <Input id="nameOnSearch" name="nameOnSearch" label="Official Search Subject Name" value={formData.nameOnSearch} onChange={handleChange} />
                        <FileUploadField id="officialSearchDoc" label="Official Search Result (Scan)" file={formData.officialSearchDoc} onChange={handleFileChange} accept=".pdf,image/*" />
                        <FileUploadField id="sitePlanDoc" label="Certified Site Plan" file={formData.sitePlanDoc} onChange={handleFileChange} accept=".pdf,image/*" />
                    </div>
                </Card>

                <Card title="Section 3: Family Contacts & Negotiators">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        <Textarea id="leadNegotiators" name="leadNegotiators" label="Lead Negotiators / Facilitators" value={formData.leadNegotiators} onChange={handleChange} placeholder="Enter names of primary brokers..." containerClassName="lg:col-span-3"/>
                        <Input id="familyContactPerson" name="familyContactPerson" label="Family Liaison Person" value={formData.familyContactPerson} onChange={handleChange} />
                        <Input id="phone1" name="phone1" label="Primary Phone" type="tel" value={formData.phoneNumbers[0]} onChange={(e) => handlePhoneChange(0, e.target.value)} />
                        <Input id="phone2" name="phone2" label="Secondary Phone" type="tel" value={formData.phoneNumbers[1]} onChange={(e) => handlePhoneChange(1, e.target.value)} />
                        <Textarea id="additionalNotes" name="additionalNotes" label="Acquisition Remarks" value={formData.additionalNotes} onChange={handleChange} containerClassName="lg:col-span-3" />
                    </div>
                </Card>

                <Card title="Section 4: Disbursement Schedule">
                    <div className="bg-gray-50 dark:bg-gray-900 p-4 rounded-lg border border-gray-200 dark:border-gray-700 grid grid-cols-1 md:grid-cols-3 gap-4">
                         <Input id="paymentAmountPerMonth" name="paymentAmountPerMonth" label="Installment Amount (GHC)" type="number" value={formData.paymentAmountPerMonth} onChange={handleChange} className="no-spinner font-bold" />
                         <Input id="paymentPeriodMonths" name="paymentPeriodMonths" label="Term Length (Months)" type="number" value={formData.paymentPeriodMonths} onChange={handleChange} className="no-spinner" />
                         <Select id="recurringPaymentTime" name="recurringPaymentTime" label="Disbursement Frequency" value={formData.recurringPaymentTime} onChange={handleChange}>
                            <option value="">Select frequency...</option>
                            <option>Monthly</option>
                            <option>Bi-Monthly</option>
                            <option>Quarterly</option>
                            <option>Annually</option>
                        </Select>
                    </div>
                    <div className="mt-6">
                        <h4 className="text-lg font-medium text-gray-800 dark:text-white mb-2">Designated Payees</h4>
                        <div className="mt-2 overflow-x-auto border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden shadow-sm">
                            <table className="w-full text-sm">
                                <thead className="bg-gray-50 dark:bg-gray-900 text-left text-gray-700 dark:text-gray-300">
                                    <tr>
                                        <th className="p-3 font-black uppercase tracking-widest text-[10px]">Beneficiary Name</th>
                                        <th className="p-3 font-black uppercase tracking-widest text-[10px]">Acreage Proxy</th>
                                        <th className="p-3 font-black uppercase tracking-widest text-[10px]">Designated Sum (GHC)</th>
                                        <th className="p-3 w-12"></th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-100 dark:divide-gray-700">
                                    {formData.payees.map((payee: any, index: number) => (
                                        <tr key={payee.id}>
                                            <td className="p-2"><input type="text" value={payee.name} onChange={(e) => handlePayeeChange(index, 'name', e.target.value)} className="w-full p-2 border border-gray-200 dark:border-gray-700 rounded bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-1 focus:ring-blue-500 text-sm"/></td>
                                            <td className="p-2"><input type="number" value={payee.acres} onChange={(e) => handlePayeeChange(index, 'acres', e.target.value)} className="w-full p-2 border border-gray-200 dark:border-gray-700 rounded bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-1 focus:ring-blue-500 text-sm no-spinner"/></td>
                                            <td className="p-2"><input type="number" value={payee.amount} onChange={(e) => handlePayeeChange(index, 'amount', e.target.value)} className="w-full p-2 border border-gray-200 dark:border-gray-700 rounded bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-1 focus:ring-blue-500 text-sm no-spinner font-bold"/></td>
                                            <td className="p-2 text-center"><button type="button" onClick={() => removePayee(payee.id)} className="text-gray-400 p-2 hover:text-red-500 transition-colors"><TrashIcon className="w-5 h-5"/></button></td>
                                        </tr>
                                    ))}
                                    {formData.payees.length === 0 && (
                                        <tr>
                                            <td colSpan={4} className="p-6 text-center text-gray-400 italic">No designated payees specified.</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                        {formData.payees.length < 10 && (
                            <button type="button" onClick={addPayee} className="mt-3 flex items-center gap-2 text-xs font-black text-blue-600 dark:text-blue-400 hover:text-blue-800 uppercase tracking-widest">
                                <PlusCircleIcon className="w-4 h-4"/> Add Designated Payee
                            </button>
                        )}
                    </div>
                </Card>

                {/* REPLACED SECTION 5 WITH DOSSIER PAGE 1: SALES & PURCHASE MANAGEMENT DATA */}
                <div className="space-y-6">
                    <div className="border-b-4 border-blue-600 pb-2">
                        <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase flex items-center gap-2">
                            <BanknotesIcon className="w-6 h-6 text-blue-600" />
                            Section 5: Sales & Purchase Management Data
                        </h2>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <Card title="Financial Configuration">
                            <div className="space-y-4">
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-[10px] font-black text-gray-400 uppercase">Acquisition Cost (Total)</label>
                                        <Input 
                                            type="number" 
                                            name="costPrice"
                                            value={formData.pricePerPlot} 
                                            readOnly={true}
                                            className="bg-gray-50 dark:bg-gray-900/50 opacity-75"
                                        />
                                    </div>
                                    <div>
                                        <label className="text-[10px] font-black text-gray-400 uppercase">Selling Price (Market)</label>
                                        <Input 
                                            type="number" 
                                            name="price"
                                            value={formData.pricePerPlot} 
                                            onChange={(e) => setFormData({...formData, pricePerPlot: e.target.value})}
                                            className="font-bold text-blue-600"
                                        />
                                    </div>
                                </div>
                                <div className="p-3 bg-blue-50 dark:bg-blue-900/10 rounded-lg border border-blue-100">
                                    <p className="text-[10px] font-black text-blue-600 uppercase">Yield Analysis</p>
                                    <p className="text-lg font-black text-blue-700 dark:text-blue-300">
                                        Manual pricing authority active
                                    </p>
                                </div>
                            </div>
                        </Card>

                        <Card title="Plot Identifier Configuration">
                            <div className="space-y-4">
                                <Input 
                                    label="Plot Number Prefix" 
                                    name="plotPrefix"
                                    value={formData.plotPrefix} 
                                    onChange={(e) => setFormData({...formData, plotPrefix: e.target.value.toUpperCase()})}
                                    className="font-mono font-bold uppercase"
                                />
                                <div className="flex flex-wrap gap-2 mt-2">
                                    <Badge variant="neutral">{formData.plotPrefix || 'REF'}-101</Badge>
                                    <Badge variant="neutral">{formData.plotPrefix || 'REF'}-102</Badge>
                                </div>
                            </div>
                        </Card>
                    </div>

                    <Card title="Inventory Partitioning">
                        <TableContainer className="border-0 shadow-none">
                            <table className="w-full text-sm">
                                <Thead>
                                    <tr>
                                        <Th>Plot Size</Th>
                                        <Th>Count</Th>
                                        <Th>Sold</Th>
                                        <Th>Zone/Phase</Th>
                                    </tr>
                                </Thead>
                                <Tbody>
                                    {formData.inventory.map((inv: any, idx: number) => (
                                        <Tr key={idx}>
                                            <Td>
                                                <Select 
                                                    value={inv.size} 
                                                    onChange={(e) => {
                                                        const newInv = [...formData.inventory];
                                                        newInv[idx].size = e.target.value;
                                                        setFormData({...formData, inventory: newInv});
                                                    }}
                                                    className="w-full text-xs"
                                                >
                                                    <option>70x100 ft</option>
                                                    <option>70x50 ft</option>
                                                    <option>60x80 ft</option>
                                                </Select>
                                            </Td>
                                            <Td>
                                                <input 
                                                    type="number" 
                                                    value={inv.count} 
                                                    onChange={(e) => {
                                                        const newInv = [...formData.inventory];
                                                        newInv[idx].count = Number(e.target.value);
                                                        setFormData({...formData, inventory: newInv});
                                                    }}
                                                    className="w-20 p-1 border rounded bg-white dark:bg-gray-950 focus:ring-1 focus:ring-blue-500" 
                                                />
                                            </Td>
                                            <Td>{inv.sold}</Td>
                                            <Td>
                                                <input 
                                                    type="text" 
                                                    value={inv.zone} 
                                                    onChange={(e) => {
                                                        const newInv = [...formData.inventory];
                                                        newInv[idx].zone = e.target.value;
                                                        setFormData({...formData, inventory: newInv});
                                                    }}
                                                    placeholder="Phase 1..."
                                                    className="w-full p-1 border rounded bg-white dark:bg-gray-950 focus:ring-1 focus:ring-blue-500" 
                                                />
                                            </Td>
                                        </Tr>
                                    ))}
                                </Tbody>
                            </table>
                            <div className="p-3 border-t border-gray-100 dark:border-gray-800">
                                <button 
                                    type="button" 
                                    onClick={() => setFormData({...formData, inventory: [...formData.inventory, { size: '70x100 ft', count: 0, sold: 0, zone: '' }]})}
                                    className="text-xs font-black text-blue-600 flex items-center gap-1 uppercase tracking-widest hover:text-blue-800"
                                >
                                    <PlusCircleIcon className="w-4 h-4" /> Add Row
                                </button>
                            </div>
                        </TableContainer>
                    </Card>
                </div>
            </form>

            <div className="fixed bottom-0 left-0 right-0 md:left-64 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md p-4 border-t border-gray-200 dark:border-gray-700 flex justify-end z-20 shadow-lg">
                <div className="container mx-auto px-6 flex justify-end gap-4">
                    <Button variant="secondary" onClick={onBack} disabled={isSaving}>Cancel</Button>
                    <Button type="submit" onClick={handleSubmit} className="shadow-lg px-8 py-3" style={{backgroundColor: '#D4AF37', borderColor: '#D4AF37'}} isLoading={isSaving}>
                        Confirm Acquisition
                    </Button>
                </div>
            </div>
        </div>
    );
};

