import React, { useState, useEffect } from 'react';
import { Property, Staff } from '../types';
import { 
  ArrowLeftIcon, 
  PrinterIcon, 
  PencilSquareIcon,
  BanknotesIcon,
  CheckCircleIcon,
  MapIcon
} from '../components/icons/DummyIcons';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select, Textarea } from '../components/ui/Input';
import { useProperties } from '../hooks/useAppData';

interface PropertiesPageProps {
  properties: Property[];
  onBack?: () => void;
  currentStaff: Staff;
  initialProperty?: Property | null;
}

const PropertiesPage: React.FC<PropertiesPageProps> = ({ properties: propsList, onBack, initialProperty }) => {
  const { saveProperty } = useProperties();
  const [viewingProperty, setViewingProperty] = useState<Property | null>(initialProperty || null);
  const [isEditMode, setIsEditMode] = useState(false);
  const [localPropData, setLocalPropData] = useState<Property | null>(initialProperty || null);

  useEffect(() => {
    if (initialProperty) {
        setViewingProperty(initialProperty);
        setLocalPropData({ ...initialProperty });
    }
  }, [initialProperty]);

  const formatCurrency = (amount: number) => `GHC ${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2 }).format(amount)}`;

  const handlePrint = () => {
    window.print();
  };

