              </Card>

              <Card title="Plot Identifier Configuration">
                <div className="space-y-4">
                  <Input 
                    label="Plot Number Prefix" 
                    value={(localPropData as any).plotPrefix || ''} 
                    readOnly={!isEditMode}
                    onChange={(e) => setLocalPropData({...localPropData, plotPrefix: e.target.value.toUpperCase()} as any)}
