                  <div className="flex flex-wrap gap-2 mt-2">
                    <Badge variant="neutral">{(localPropData as any).plotPrefix || 'REF'}-101</Badge>
                    <Badge variant="neutral">{(localPropData as any).plotPrefix || 'REF'}-102</Badge>
                  </div>
                </div>
              </Card>
            </div>

            <Card title="Inventory Partitioning">
               <TableContainer className="border-0 shadow-none">
                  <table className="w-full text-sm">
                    <Thead>
                      <tr>
                        <Th>Plot Size</Th>
                        <Th>Count</Th>
                        <Th>Sold</Th>
                        <Th>Zone/Phase</Th>
                      </tr>
                    </Thead>
                    <Tbody>
                      {localPropData.inventory.map((inv, idx) => (
                        <Tr key={idx}>
                          <Td>{inv.size}</Td>
                          <Td>
                            {isEditMode ? (
                              <input 
                                type="number" 
                                value={inv.count} 
                                onChange={(e) => {
                                  const newInv = [...localPropData.inventory];
                                  newInv[idx].count = Number(e.target.value);
                                  setLocalPropData({...localPropData, inventory: newInv});
                                }}
                                className="w-16 p-1 border rounded bg-white dark:bg-gray-950" 
                              />
                            ) : inv.count}
                          </Td>
                          <Td>{inv.sold}</Td>
                          <Td>
                            {isEditMode ? (
                              <input 
                                type="text" 
                                value={(inv as any).zone || ''} 
                                onChange={(e) => {
                                  const newInv = [...localPropData.inventory];
                                  (newInv[idx] as any).zone = e.target.value;
                                  setLocalPropData({...localPropData, inventory: newInv});
                                }}
                                className="w-full p-1 border rounded bg-white dark:bg-gray-950" 
                              />
                            ) : ((inv as any).zone || '—')}
                          </Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </table>
               </TableContainer>
            </Card>
          </section>

          <section className="space-y-6">
            <div className="border-b-4 border-amber-600 pb-2">
              <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase flex items-center gap-2">
                <MapIcon className="w-6 h-6 text-amber-600" />
                Page 2: Land Acquisition Details
              </h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Card title="Acquisition Metadata">
                <div className="space-y-4">
                  <Input 
                    label="Official Property Location" 
                    value={localPropData.location} 
                    readOnly={!isEditMode}
                    onChange={(e) => setLocalPropData({...localPropData, location: e.target.value})}
                    className={!isEditMode ? "bg-gray-50 dark:bg-gray-900/50" : ""}
                  />
                  <Select 
                    label="Registration Status" 
                    value={localPropData.registrationStatus} 
                    disabled={!isEditMode}
                    onChange={(e) => setLocalPropData({...localPropData, registrationStatus: e.target.value as any})}
                    className={!isEditMode ? "bg-gray-50 dark:bg-gray-900/50" : ""}
                  >
                    <option value="Titled">Titled</option>
                    <option value="Indenture">Indenture</option>
                    <option value="Plotted">Plotted</option>
                  </Select>
                  <div>
                    <label className="text-xs font-bold text-gray-500 uppercase">Acreage Capacity</label>
                    <Input 
                      type="number" 
                      value={localPropData.size} 
                      readOnly={!isEditMode}
                      onChange={(e) => setLocalPropData({...localPropData, size: Number(e.target.value)})}
                      className={!isEditMode ? "bg-gray-50 dark:bg-gray-900/50" : ""}
                    />
                  </div>
                </div>
              </Card>

              <Card title="Official Descriptions">
                <Textarea 
                  label="Detailed Property Remarks" 
                  value={localPropData.description} 
                  rows={6}
                  readOnly={!isEditMode}
                  onChange={(e) => setLocalPropData({...localPropData, description: e.target.value})}
                  className={!isEditMode ? "bg-gray-50 dark:bg-gray-900/50" : ""}
                />
              </Card>
            </div>
          </section>
        </div>

        <style>{`
          @media print {
            body { background: white; }
            .sidebar, header, nav, button, .print\\:hidden { display: none !important; }
            main { padding: 0 !important; margin: 0 !important; overflow: visible !important; }
            .container { max-width: 100% !important; width: 100% !important; padding: 0 !important; }
            #printable-dossier { margin: 0; padding: 0; }
            .break-after-page { page-break-after: always; }
            input, textarea, select { 
              border: none !important; 
              background: transparent !important; 
              padding: 0 !important; 
              appearance: none !important;
              color: black !important;
              box-shadow: none !important;
            }
            label { color: #666 !important; }
            .card { border: 1px solid #eee !important; box-shadow: none !important; margin-bottom: 2rem; }
          }
        `}</style>
      </div>
    );
  }

  return (
    <div className="flex items-center justify-center h-64 text-gray-500 italic">
        Select a property from Purchase & Sale Management to view its dossier.
    </div>
  );
};

