const ClientForm: React.FC<ClientFormProps> = ({ isOpen, onClose, onSave, onSaveAndPay, properties, editingClient, clients }) => {
    const [step, setStep] = useState(1);
    const [formData, setFormData] = useState<FormData>(initialFormData);
    const [photoPreview, setPhotoPreview] = useState<string | null>(null);
    const [pdfFile, setPdfFile] = useState<File | null>(null);
    const [photoFile, setPhotoFile] = useState<File | null>(null);
    const [touched, setTouched] = useState<Partial<Record<keyof FormData, boolean>>>({});
    const [isProcessing, setIsProcessing] = useState(false);

    // Authority Base Price
    const basePrice = useMemo(() => {
        const match = properties.find(p => p.location === formData.location);
        return match ? match.price : 0;
    }, [formData.location, properties]);

    // Availability Cross-Reference
    const takenPlots = useMemo(() => {
        const taken = new Set<string>();
        clients.forEach(c => {
            if (c.plot && c.plot !== 'N/A') {
                c.plot.split(',').forEach(p => taken.add(p.trim().toUpperCase()));
            }
        });
        return taken;
    }, [clients]);

    const availablePlotsForLocation = useMemo(() => {
        const prop = properties.find(p => p.location === formData.location);
        if (!prop || !prop.inventory) return [];

        const allPlots: { plotNumber: string; isTaken: boolean }[] = [];
        prop.inventory.forEach((inv: any) => {
            const prefix = inv.zone || 'P1';
            for (let i = 1; i <= inv.count; i++) {
                const pNum = `${prefix}-${i}`;
                allPlots.push({
                    plotNumber: pNum,
                    isTaken: takenPlots.has(pNum) && (!editingClient || !editingClient.plot.split(',').map(p => p.trim().toUpperCase()).includes(pNum))
                });
            }
        });
        return allPlots;
    }, [formData.location, properties, takenPlots, editingClient]);

    // Handle Plot Selection Logic
    const handlePlotsChange = (e: ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        const num = parseInt(value);
        setFormData(prev => ({ ...prev, numberOfPlots: value }));
        setTouched(prev => ({ ...prev, numberOfPlots: true }));
        if (!formData.location) return;
        if (isNaN(num) || num <= 0) return;
        const calculatedPrice = basePrice * num;
        setFormData(prev => ({ ...prev, numberOfPlots: value, price: calculatedPrice.toString() }));
    };

    const handleLocationChange = (e: ChangeEvent<HTMLSelectElement>) => {
        const loc = e.target.value;
        const match = properties.find(p => p.location === loc);
        const pCount = parseInt(formData.numberOfPlots) || 1;
        const priceValue = match ? (match.price * pCount).toString() : '';
        setFormData(prev => ({ ...prev, location: loc, price: priceValue, plotNumber: '' }));
    };

     useEffect(() => {
        if (isOpen && editingClient) {
            setFormData({
                surname: editingClient.surname,
                otherNames: editingClient.otherNames,
                dateOfBirth: editingClient.dateOfBirth || '',
                currentAddress: editingClient.location,
                telephone: editingClient.phone,
                email: editingClient.email,
                gender: editingClient.gender || 'Other',
                photo: editingClient.photo || '',
                placeOfWork: editingClient.professionalDetails?.placeOfWork || '',
                profession: editingClient.professionalDetails?.profession || '',
                position: editingClient.professionalDetails?.position || '',
                kinName: editingClient.nextOfKin.name,
                kinAddress: editingClient.nextOfKin.address || '',
                kinPhone: editingClient.nextOfKin.phone,
                kinRelationship: editingClient.nextOfKin.relationship,
                kinEmail: editingClient.nextOfKin.email || '',
                witnessName: editingClient.witness.name,
                witnessAddress: editingClient.witness.address,
                witnessPhone: editingClient.witness.phone,
                paymentDate: editingClient.regDate,
                paymentMethod: editingClient.payment.paymentHistory[0]?.method || 'Bank Transfer',
                location: editingClient.location,
                propertyType: editingClient.propertyType || 'Residential',
                plotNumber: editingClient.plot,
                numberOfPlots: (editingClient as any).numberOfPlots || '1',
                plannedDevelopmentYear: editingClient.plannedDevelopmentYear || new Date().getFullYear().toString(),
                filledFormPdf: editingClient.filledFormPdf,
                indentureName: editingClient.indenture.name,
                indentureAddress: editingClient.indenture.address,
                salesRep: editingClient.officeUse.salesRep,
                salesManager: editingClient.officeUse.salesManager,
                accountsHead: editingClient.officeUse.accountsHead,
                clerk: editingClient.officeUse.clerk,
                price: editingClient.payment.total.toString(),
            });
            setPhotoPreview(editingClient.photo || null);
            setTouched({});
        } else if (isOpen) {
            resetForm();
        }
    }, [isOpen, editingClient]);

    const validate = useCallback((): Partial<Record<keyof FormData, string>> => {
        const errors: Partial<Record<keyof FormData, string>> = {};
        const requiredFields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk', 'paymentDate', 'numberOfPlots', 'price'];
        requiredFields.forEach(field => {
            if (!formData[field]) errors[field] = 'This field cannot be left blank.';
        });
        if (formData.numberOfPlots && (parseInt(formData.numberOfPlots) <= 0 || isNaN(parseInt(formData.numberOfPlots)))) {
            errors.numberOfPlots = 'Number of plots must be a positive number.';
        }
        return errors;
    }, [formData]);

    const errors = useMemo(() => validate(), [validate]);
    const isFormValid = Object.keys(errors).length === 0;

    const handleBlur = (e: React.FocusEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name } = e.target as { name: keyof FormData };
        setTouched(prev => ({ ...prev, [name]: true }));
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (fieldName: keyof FormData) => (value: string) => {
        setFormData(prev => ({ ...prev, [fieldName]: value }));
    };

    const handlePhotoChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const allowedTypes = ['image/jpeg', 'image/png', 'image/jpg'];
            if (allowedTypes.includes(file.type)) {
                setPhotoFile(file);
                const reader = new FileReader();
                reader.onloadend = () => {
                    setPhotoPreview(reader.result as string);
                };
                reader.readAsDataURL(file);
            } else {
                 alert('Invalid file type. Please upload a .jpg, .jpeg, or .png file.');
                 e.target.value = '';
            }
        }
    };

    const handlePdfChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            if (file.type === 'application/pdf') {
                setPdfFile(file);
                setTouched(prev => ({ ...prev, filledFormPdf: true }));
            } else {
                alert('Please upload a PDF file.');
                e.target.value = '';
            }
        }
    };

    const handleNext = () => {
        const step1Fields: (keyof FormData)[] = ['surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress'];
        const step2Fields: (keyof FormData)[] = ['location', 'numberOfPlots', 'price', 'plotNumber', 'paymentDate', 'indentureName', 'indentureAddress'];
        const currentStepFields = step === 1 ? step1Fields : step2Fields;
        let isStepValid = true;
        const fieldsToTouch: Partial<Record<keyof FormData, boolean>> = {};
        currentStepFields.forEach(field => {
            fieldsToTouch[field] = true;
            if (errors[field]) isStepValid = false;
        });
        if (!isStepValid) {
            setTouched(prev => ({ ...prev, ...fieldsToTouch }));
            alert('Please complete all required fields correctly before continuing.');
            return;
        }
        setStep(prev => Math.min(prev + 1, 3));
    };
    const handleBack = () => setStep(prev => Math.max(prev - 1, 1));

    const handleAddPaymentDetails = async (e: FormEvent) => {
        e.preventDefault();
        if (!isFormValid) {
            const allFields = Object.keys(initialFormData) as (keyof FormData)[];
            const allTouched = allFields.reduce((acc, key) => ({...acc, [key]: true}), {});
            setTouched(allTouched);
            alert("Some fields contain invalid or incomplete data. Please correct them before saving.");
            return;
        }
        setIsProcessing(true);
        try {
            onSaveAndPay(formData, { photo: photoFile, pdf: pdfFile });
            resetForm();
            onClose();
        } catch (error) {
            console.error("Save failed:", error);
        } finally {
            setIsProcessing(false);
        }
    };

    const resetForm = () => {
        setFormData(initialFormData);
        setPhotoPreview(null);
        setPdfFile(null);
        setPhotoFile(null);
        setStep(1);
        setTouched({});
        setIsProcessing(false);
    };

    if (!isOpen) return null;

    const steps = [
        { name: 'Client Information', icon: <UserGroupIcon className="w-5 h-5" /> },
        { name: 'Acquisition Details', icon: <BuildingLibraryIcon className="w-5 h-5" /> },
        { name: 'Office Details', icon: <BriefcaseIcon className="w-5 h-5" /> },
    ];

    const isPropertyAvailable = properties && properties.length > 0;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" aria-modal="true" role="dialog">
            <div className="bg-gray-50 dark:bg-gray-900 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">{editingClient ? 'Edit Client Details' : 'New Client Registration'}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                    <nav aria-label="Progress">
                         <ol role="list" className="flex items-center">
                            {steps.map((s, stepIdx) => (
                                <li key={s.name} className={`relative ${stepIdx !== steps.length - 1 ? 'pr-8 sm:pr-20' : ''}`}>
                                    {step > stepIdx + 1 ? (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true"><div className="h-0.5 w-full bg-blue-600" /></div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-blue-600 rounded-full text-white">{s.icon}</div>
                                        </>
                                    ) : step === stepIdx + 1 ? (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true"><div className="h-0.5 w-full bg-gray-200 dark:bg-gray-700" /></div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-800 border-2 border-blue-600 rounded-full text-blue-600">{s.icon}</div>
                                        </>
                                    ) : (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true"><div className="h-0.5 w-full bg-gray-200 dark:bg-gray-700" /></div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-800 border-2 border-gray-300 dark:border-gray-600 rounded-full text-gray-400">{s.icon}</div>
                                        </>
                                    )}
                                     <span className="absolute -bottom-6 text-xs font-semibold text-center w-24 -left-8 text-gray-600 dark:text-gray-400">{s.name}</span>
                                </li>
                            ))}
                        </ol>
                    </nav>
                </div>

                <div className="p-6 overflow-y-auto flex-grow">
                    {step === 1 && (
                        <div className="animate-in fade-in duration-300">
                           <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                                <div className="sm:col-span-2">
                                    <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">Personal Information</h3>
                                    <div className="mt-4 grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
                                        <SmartInputField id="surname" label="Surname" value={formData.surname} onChange={handleChange} onBlur={handleBlur} required error={touched.surname ? errors.surname : undefined} isTouched={touched.surname} />
                                        <SmartInputField id="otherNames" label="Other Names" value={formData.otherNames} onChange={handleChange} onBlur={handleBlur} required error={touched.otherNames ? errors.otherNames : undefined} isTouched={touched.otherNames}/>
                                        <SmartInputField id="dateOfBirth" label="Date of Birth" type="date" value={formData.dateOfBirth} onChange={handleChange} onBlur={handleBlur} error={touched.dateOfBirth ? errors.dateOfBirth : undefined} isTouched={touched.dateOfBirth} />
                                         <SmartSelectField id="gender" label="Gender" value={formData.gender} onChange={handleChange} onBlur={handleBlur} error={touched.gender ? errors.gender : undefined} isTouched={touched.gender}>
                                            <option>Male</option>
                                            <option>Female</option>
                                            <option>Other</option>
                                        </SmartSelectField>
                                        <div className="sm:col-span-2">
                                            <SmartInputField id="currentAddress" label="Current Address" value={formData.currentAddress} onChange={handleChange} onBlur={handleBlur} required error={touched.currentAddress ? errors.currentAddress : undefined} isTouched={touched.currentAddress} />
                                        </div>
                                        <PhoneInput id="telephone" name="telephone" label="Telephone" value={formData.telephone} onChange={handlePhoneChange('telephone')} required error={touched.telephone ? errors.telephone : undefined} />
                                        <EmailInput id="email" name="email" label="Email Address" value={formData.email} onChange={(val) => setFormData(prev => ({...prev, email: val}))} error={touched.email ? errors.email : undefined} />
                                    </div>
                                </div>
                                <div className="sm:col-span-1">
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Passport-sized Photo</label>
                                    <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md">
                                        <div className="space-y-1 text-center">
                                            {photoPreview ? (
                                                <img src={photoPreview} alt="Client" className="mx-auto h-24 w-24 object-cover rounded-md" />
                                            ) : (
                                                <svg className="mx-auto h-12 w-12 text-gray-400" stroke="currentColor" fill="none" viewBox="0 0 48 48" aria-hidden="true"><path d="M28 8H12a4 4 0 00-4 4v20m32-12v8m0 0v8a4 4 0 01-4 4H12a4 4 0 01-4-4v-4m32-4l-3.172-3.172a4 4 0 00-5.656 0L28 28M8 32l9.172-9.172a4 4 0 015.656 0L28 28" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" /></svg>
                                            )}
                                            <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                                <label htmlFor="photo-upload" className="relative cursor-pointer bg-white dark:bg-gray-800 rounded-md font-medium text-blue-600 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                                                    <span>{photoFile ? 'Change photo' : 'Upload a file'}</span>
                                                    <input id="photo-upload" name="photo" type="file" className="sr-only" onChange={handlePhotoChange} accept=".jpg,.jpeg,.png" />
                                                </label>
                                                <p className="pl-1">or drag and drop</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                           </div>

                           <FormSection title="Professional Information">
                               <SmartInputField id="placeOfWork" label="Place of Work" value={formData.placeOfWork} onChange={handleChange} onBlur={handleBlur} error={touched.placeOfWork ? errors.placeOfWork : undefined} isTouched={touched.placeOfWork}/>
                               <SmartInputField id="profession" label="Profession" value={formData.profession} onChange={handleChange} onBlur={handleBlur} error={touched.profession ? errors.profession : undefined} isTouched={touched.profession}/>
                               <SmartInputField id="position" label="Position/Rank" value={formData.position} onChange={handleChange} onBlur={handleBlur} error={touched.position ? errors.position : undefined} isTouched={touched.position}/>
                           </FormSection>

                           <FormSection title="Next of Kin Details">
                               <SmartInputField id="kinName" label="Name" value={formData.kinName} onChange={handleChange} onBlur={handleBlur} required error={touched.kinName ? errors.kinName : undefined} isTouched={touched.kinName}/>
                               <SmartInputField id="kinRelationship" label="Relationship with Buyer" value={formData.kinRelationship} onChange={handleChange} onBlur={handleBlur} error={touched.kinRelationship ? errors.kinRelationship : undefined} isTouched={touched.kinRelationship}/>
                               <PhoneInput id="kinPhone" name="kinPhone" label="Telephone Number" value={formData.kinPhone} onChange={handlePhoneChange('kinPhone')} required error={touched.kinPhone ? errors.kinPhone : undefined} />
                               <EmailInput id="kinEmail" name="kinEmail" label="Email Address" value={formData.kinEmail} onChange={(val) => setFormData(prev => ({...prev, kinEmail: val}))} error={touched.kinEmail ? errors.kinEmail : undefined} />
                               <div className="sm:col-span-2">
                                    <SmartInputField id="kinAddress" label="Address" value={formData.kinAddress} onChange={handleChange} onBlur={handleBlur} error={touched.kinAddress ? errors.kinAddress : undefined} isTouched={touched.kinAddress}/>
                               </div>
                           </FormSection>
                        </div>
                    )}
                    {step === 2 && (
                        <div className="animate-in fade-in duration-300">
                             <FormSection title="Property & Transaction Details">
                                <div className="sm:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4">
                                    <SmartSelectField id="location" label="Location*" value={formData.location} onChange={handleLocationChange} onBlur={handleBlur} required disabled={!isPropertyAvailable} error={touched.location ? errors.location : undefined} isTouched={touched.location}>
                                        <option value="">{isPropertyAvailable ? '-- Select Location --' : 'No properties available'}</option>
                                        {properties.map(p => <option key={p.id} value={p.location}>{p.location}</option>)}
                                    </SmartSelectField>

                                    <SmartInputField id="numberOfPlots" label="Plots Required*" type="number" value={formData.numberOfPlots} onChange={handlePlotsChange} onBlur={handleBlur} required placeholder="1" error={touched.numberOfPlots ? errors.numberOfPlots : undefined} isTouched={touched.numberOfPlots} />

                                    <SmartInputField id="price" label="Total Price (GHC)*" value={formData.price} readOnly required error={touched.price ? errors.price : undefined} isTouched={touched.price} placeholder="Auto-calculated" />
                                </div>

                                <div className="sm:col-span-2 space-y-2">
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Select Plot(s)* <span className="text-gray-400 font-normal text-xs">(Based on CEO Hub Inventory)</span></label>
                                    {!formData.location ? (
                                        <div className="p-8 text-center border border-dashed rounded-lg bg-gray-50 dark:bg-gray-800 text-gray-400 text-sm">Please select a location first.</div>
                                    ) : (
                                        <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 gap-2 max-h-[200px] overflow-y-auto p-2 border border-gray-200 dark:border-gray-700 rounded-md scrollbar-thin">
                                            {availablePlotsForLocation.map(p => (
                                                <button
                                                    key={p.plotNumber}
                                                    type="button"
                                                    disabled={p.isTaken}
                                                    onClick={() => {
                                                        const current = formData.plotNumber.split(',').map(x => x.trim()).filter(Boolean);
                                                        const updated = current.includes(p.plotNumber) ? current.filter(x => x !== p.plotNumber) : [...current, p.plotNumber];
                                                        setFormData({ ...formData, plotNumber: updated.join(', ') });
                                                    }}
                                                    className={`px-2 py-1 text-[10px] font-bold rounded border transition-all ${
                                                        p.isTaken 
                                                        ? 'bg-gray-100 dark:bg-gray-800 text-gray-300 border-gray-200 dark:border-gray-700 cursor-not-allowed' 
                                                        : formData.plotNumber.split(', ').includes(p.plotNumber)
                                                            ? 'bg-blue-600 text-white border-blue-600 shadow-md'
                                                            : 'bg-white dark:bg-gray-900 text-gray-600 dark:text-gray-300 border-gray-300 dark:border-gray-600 hover:border-blue-500'
                                                    }`}
                                                    title={p.isTaken ? 'Already Taken' : 'Available'}
                                                >
                                                    {p.plotNumber}
                                                    {p.isTaken && <span className="block text-[8px] uppercase">Taken</span>}
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                    {errors.plotNumber && touched.plotNumber && <p className="text-xs text-red-500">{errors.plotNumber}</p>}
                                </div>

                                <SmartSelectField id="propertyType" label="Usage Category" value={formData.propertyType} onChange={handleChange} onBlur={handleBlur} error={touched.propertyType ? errors.propertyType : undefined} isTouched={touched.propertyType}>
                                    <option>Residential</option>
                                    <option>Commercial</option>
                                </SmartSelectField>
                                <SmartInputField id="plannedDevelopmentYear" label="Development Year" type="number" value={formData.plannedDevelopmentYear} onChange={handleChange} onBlur={handleBlur} error={touched.plannedDevelopmentYear ? errors.plannedDevelopmentYear : undefined} isTouched={touched.plannedDevelopmentYear}/>
                                <SmartInputField id="paymentDate" label="Reg. Date" type="date" value={formData.paymentDate} onChange={handleChange} onBlur={handleBlur} required error={touched.paymentDate ? errors.paymentDate : undefined} isTouched={touched.paymentDate}/>
                                <SmartSelectField id="paymentMethod" label="Method" value={formData.paymentMethod} onChange={handleChange} onBlur={handleBlur} error={touched.paymentMethod ? errors.paymentMethod : undefined} isTouched={touched.paymentMethod}>
                                    <option>Bank Transfer</option><option>Cash</option><option>MoMo</option><option>Cheque</option>
                                </SmartSelectField>
                                <div className={`sm:col-span-2 p-3 rounded-md border relative ${touched.filledFormPdf && errors.filledFormPdf ? 'border-red-500' : 'border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800'}`}>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Upload Form Scan</label>
                                    <div className="mt-1 flex items-center">
                                        <label htmlFor="filledFormPdf-upload" className="relative cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 focus-within:ring-2 focus-within:ring-blue-500">
                                            <span>{pdfFile ? pdfFile.name : (formData.filledFormPdf ? 'Uploaded' : 'Select PDF')}</span>
                                            <input id="filledFormPdf-upload" name="filledFormPdf" type="file" className="sr-only" onChange={handlePdfChange} accept="application/pdf" />
                                        </label>
                                    </div>
                                </div>
                             </FormSection>

                            <FormSection title="Indenture Name Preference">
                                <SmartInputField id="indentureName" label="Full Name" value={formData.indentureName} onChange={handleChange} onBlur={handleBlur} required error={touched.indentureName ? errors.indentureName : undefined} isTouched={touched.indentureName}/>
                                <SmartInputField id="indentureAddress" label="Address" value={formData.indentureAddress} onChange={handleChange} onBlur={handleBlur} required error={touched.indentureAddress ? errors.indentureAddress : undefined} isTouched={touched.indentureAddress}/>
                            </FormSection>
                        </div>
                    )}
                    {step === 3 && (
                        <div className="animate-in fade-in duration-300">
                             <FormSection title="Internal Office Review">
                                <SmartInputField id="salesRep" label="Intermediary Sales Rep" value={formData.salesRep} onChange={handleChange} onBlur={handleBlur} required error={touched.salesRep ? errors.salesRep : undefined} isTouched={touched.salesRep}/>
                                <SmartInputField id="salesManager" label="Approving Manager" value={formData.salesManager} onChange={handleChange} onBlur={handleBlur} required error={touched.salesManager ? errors.salesManager : undefined} isTouched={touched.salesManager}/>
                                <SmartInputField id="accountsHead" label="Accounts Approval" value={formData.accountsHead} onChange={handleChange} onBlur={handleBlur} required error={touched.accountsHead ? errors.accountsHead : undefined} isTouched={touched.accountsHead}/>
                                <SmartInputField id="clerk" label="Receiving Clerk" value={formData.clerk} onChange={handleChange} onBlur={handleBlur} required error={touched.clerk ? errors.clerk : undefined} isTouched={touched.clerk}/>
                            </FormSection>
                        </div>
                    )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>{step > 1 && <button type="button" onClick={handleBack} className="bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 transition-colors">Back</button>}</div>
                    <div>
                        {step < 3 ? (
                             <button type="button" onClick={handleNext} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors">Next Step</button>
                        ) : (
                            <button type="button" onClick={handleAddPaymentDetails} disabled={!isFormValid || isProcessing} className="bg-blue-600 text-white font-black uppercase tracking-widest py-2.5 px-8 rounded-lg hover:bg-blue-700 transition-all shadow-lg disabled:bg-gray-400">
                                {isProcessing ? 'Saving...' : 'Finish Registration'}
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ClientForm;

import React, { useState, useMemo } from 'react';
import { Client, Property } from '../types';
import { 
    ArrowLeftIcon, 
    UserCheckIcon, 
    CheckCircleIcon, 
    MapPinIcon, 
    ChevronDownIcon,
    EyeIcon,
    TagIcon,
    ClockIcon,
    LockClosedIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Select } from '../components/ui/Input';
import { Button } from '../components/ui/Button';
import { Badge } from '../components/ui/Badge';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { useClients } from '../hooks/useAppData';

interface AllocatePlotPageProps {
    onBack: () => void;
    clients: Client[];
    properties: Property[];
}

const AllocatePlotPage: React.FC<AllocatePlotPageProps> = ({ onBack, clients, properties }) => {
    const { saveClient } = useClients();

    const [selectedClientId, setSelectedClientId] = useState<number | ''>('');
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | ''>('');
    const [selectedPlots, setSelectedPlots] = useState<string[]>([]);
    const [isSaving, setIsSaving] = useState(false);
    const [allocationSuccess, setAllocationSuccess] = useState(false);

    const [isViewAllOpen, setIsViewAllOpen] = useState(false);
    const [viewAllLocationId, setViewAllLocationId] = useState<number | ''>('');
    const [statusFilter, setStatusFilter] = useState<'All' | 'Allocated' | 'Available'>('All');

    const selectedClient = useMemo(() => clients.find(c => c.id === selectedClientId), [selectedClientId, clients]);
    const selectedProperty = useMemo(() => properties.find(p => p.id === selectedPropertyId), [selectedPropertyId, properties]);

    const qualification = useMemo(() => {
        if (!selectedClient) return { isQualified: false, percentage: 0, status: 'N/A' };
        const total = selectedClient.payment.total || 1;
        const paid = selectedClient.payment.paid || 0;
        const percentage = (paid / total) * 100;
        const isQualified = percentage >= 70;
        return {
            percentage: Math.round(percentage),
            isQualified,
            status: isQualified ? 'Qualified (≥70%)' : 'Provisionally Flagged (<70%)'
        };
    }, [selectedClient]);

    const globalPlotStatus = useMemo(() => {
        const pool: Record<string, { allocated: boolean, owner?: string }> = {};
        clients.forEach(c => {
            if (c.plot && c.plot !== 'N/A') {
                c.plot.split(',').forEach(p => {
                    const plotNum = p.trim().toUpperCase();
                    if (plotNum) {
                        pool[plotNum] = { allocated: true, owner: c.name };
                    }
                });
            }
        });
        return pool;
    }, [clients]);

    const availablePlotsList = useMemo(() => {
        if (!selectedProperty || !selectedProperty.inventory) return [];
        const plots: { plotNumber: string; isTaken: boolean; owner?: string }[] = [];
        selectedProperty.inventory.forEach((inv: any) => {
            const prefix = inv.zone || 'P1';
            for (let i = 1; i <= inv.count; i++) {
                const pNum = `${prefix}-${i}`;
                plots.push({
                    plotNumber: pNum,
                    isTaken: globalPlotStatus[pNum]?.allocated || false,
                    owner: globalPlotStatus[pNum]?.owner
                });
            }
        });
        return plots;
    }, [selectedProperty, globalPlotStatus]);

    const masterPlotList = useMemo(() => {
        const prop = properties.find(p => p.id === viewAllLocationId);
        if (!prop || !prop.inventory) return [];

        const all: { plotNumber: string; size: string; allocatedTo: string | null; isProvisional: boolean }[] = [];
        prop.inventory.forEach((inv: any) => {
            const prefix = inv.zone || 'P1';
            for (let i = 1; i <= inv.count; i++) {
                const pNum = `${prefix}-${i}`;
                const ownerInfo = globalPlotStatus[pNum];

                let isProvisional = false;
                if (ownerInfo?.allocated) {
                    const client = clients.find(c => c.name === ownerInfo.owner);
                    if (client) {
                        const pct = (client.payment.paid / (client.payment.total || 1)) * 100;
                        isProvisional = pct < 70;
                    }
                }

                all.push({
                    plotNumber: pNum,
                    size: inv.size,
                    allocatedTo: ownerInfo?.owner || null,
                    isProvisional
                });
            }
        });

        return all.filter(p => {
            if (statusFilter === 'Allocated') return p.allocatedTo !== null;
            if (statusFilter === 'Available') return p.allocatedTo === null;
            return true;
        });
    }, [viewAllLocationId, properties, globalPlotStatus, clients, statusFilter]);

    const handlePlotToggle = (plot: string) => {
        if (globalPlotStatus[plot]?.allocated) return;
        setSelectedPlots(prev => prev.includes(plot) ? prev.filter(p => p !== plot) : [...prev, plot]);
    };

    const handleConfirmAllocation = async () => {
        if (!selectedClient || selectedPlots.length === 0) return;
        setIsSaving(true);
        try {
            const updatedClient: Client = {
                ...selectedClient,
                plot: selectedPlots.join(', '),
                interactions: [
                    { id: Date.now(), type: 'Note', date: new Date().toISOString(), agent: 'System', notes: `Plots ${selectedPlots.join(', ')} allocated at ${selectedProperty?.location}.` },
                    ...selectedClient.interactions
                ]
            };
            await saveClient(updatedClient);
            setAllocationSuccess(true);
            setTimeout(() => onBack(), 2000);
        } catch (error) {
            alert('Save failed.');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors"><ArrowLeftIcon className="w-5 h-5" /> Back</button>
                    <div className="flex items-center gap-4">
                        <UserCheckIcon className="w-10 h-10 text-blue-600" />
                        <div>
                            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Allocate Plot</h1>
                            <p className="text-gray-500 dark:text-gray-400 mt-1">Single source inventory partitioning and assignment.</p>
                        </div>
                    </div>
                </div>
            </div>

            {allocationSuccess && <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded shadow-md animate-bounce">Allocation Successful!</div>}

            <Card className="bg-white dark:bg-gray-800">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <Select label="1. Client" value={selectedClientId} onChange={(e) => { setSelectedClientId(Number(e.target.value)); setSelectedPlots([]); }}>
                        <option value="">-- Select --</option>
                        {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </Select>
                    <Select label="2. Location" value={selectedPropertyId} onChange={(e) => { setSelectedPropertyId(Number(e.target.value)); setSelectedPlots([]); }}>
                        <option value="">-- Select --</option>
                        {properties.map(p => <option key={p.id} value={p.id}>{p.location}</option>)}
                    </Select>
                </div>
                <div className="mt-4 pt-4 border-t border-gray-100 dark:border-gray-700">
                    <button onClick={() => setIsViewAllOpen(!isViewAllOpen)} className="text-sm font-bold text-indigo-600 hover:underline flex items-center gap-1">
                        <EyeIcon className="w-4 h-4" /> View Site Map Ledger
                    </button>
                    {isViewAllOpen && (
                        <div className="mt-4 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-xl border animate-in slide-in-from-top-2">
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                <Select label="Site" value={viewAllLocationId} onChange={(e) => setViewAllLocationId(e.target.value ? Number(e.target.value) : '')}>
                                    <option value="">-- Choose Location --</option>
                                    {properties.map(p => <option key={p.id} value={p.id}>{p.location}</option>)}
                                </Select>
                                <Select label="Filter" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as any)}>
                                    <option value="All">All</option>
                                    <option value="Allocated">Allocated</option>
                                    <option value="Available">Available</option>
                                </Select>
                            </div>
                            <TableContainer className="max-h-[300px]">
                                <table className="w-full text-xs">
                                    <Thead><tr><Th>Plot</Th><Th>Owner</Th><Th className="text-center">Status</Th></tr></Thead>
                                    <Tbody>
                                        {masterPlotList.map((p, i) => (
                                            <Tr key={i}>
                                                <Td className="font-mono font-bold">{p.plotNumber}</Td>
                                                <Td>{p.allocatedTo || '—'}</Td>
                                                <Td className="text-center">
                                                    <Badge variant={p.allocatedTo ? (p.isProvisional ? 'warning' : 'danger') : 'success'}>
                                                        {p.allocatedTo ? (p.isProvisional ? 'Provisional' : 'Permanent') : 'Available'}
                                                    </Badge>
                                                </Td>
                                            </Tr>
                                        ))}
                                    </Tbody>
                                </table>
                            </TableContainer>
                        </div>
                    )}
                </div>
            </Card>

            {selectedClient && selectedProperty && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4">
                    <Card title="Qualification Detail" className="lg:col-span-1">
                        <div className="text-center space-y-4">
                            <p className="text-[10px] font-black uppercase text-gray-400">Payment Status</p>
                            <p className={`text-lg font-bold ${qualification.isQualified ? 'text-green-600' : 'text-amber-600'}`}>{qualification.status}</p>
                            <div className="w-full bg-gray-200 h-2 rounded-full overflow-hidden">
                                <div className={`h-full ${qualification.isQualified ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${qualification.percentage}%` }}></div>
                            </div>
                        </div>
                    </Card>

                    <Card title={`3. Select Plot(s) for ${selectedProperty.location}`} className="lg:col-span-2">
                        <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 gap-2 max-h-[350px] overflow-y-auto scrollbar-thin p-1">
                            {availablePlotsList.map(plot => (
                                <button
                                    key={plot.plotNumber}
                                    disabled={plot.isTaken}
                                    onClick={() => handlePlotToggle(plot.plotNumber)}
                                    className={`p-2 rounded border text-[10px] font-bold flex flex-col items-center gap-1 transition-all ${
                                        plot.isTaken 
                                        ? 'bg-gray-100 text-gray-300 border-gray-200 cursor-not-allowed' 
                                        : selectedPlots.includes(plot.plotNumber)
                                            ? 'bg-blue-600 text-white border-blue-600 scale-105'
                                            : 'bg-white text-gray-600 border-gray-300 hover:border-blue-500'
                                    }`}
                                >
                                    {plot.plotNumber}
                                    <span className="opacity-60">{plot.isTaken ? 'Taken' : 'Pick'}</span>
                                </button>
                            ))}
                        </div>
                        {selectedPlots.length > 0 && (
                            <div className="mt-6 flex justify-between items-center bg-blue-50 p-4 rounded-xl border border-blue-200">
                                <div>
                                    <p className="text-xs text-blue-800 font-bold uppercase">Ready for assignment:</p>
                                    <p className="text-sm font-black text-blue-900">{selectedPlots.join(', ')}</p>
                                </div>
                                <Button onClick={handleConfirmAllocation} isLoading={isSaving}>Confirm Selection</Button>
                            </div>
                        )}
                    </Card>
                </div>
            )}
            <style>{` .scrollbar-thin::-webkit-scrollbar { width: 4px; } .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; } `}</style>
        </div>
    );
};

export default AllocatePlotPage;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
    ChevronDownIcon, 
    DocumentPlusIcon, 
    MagnifyingGlassIcon, 
    UploadIcon 
} from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import ClientListItem from '../components/ClientListItem';
import { Client, Milestone, Property, Invoice, ActivityLog } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { VariableSizeList as List } from 'react-window';
import AutoSizer from 'react-virtualized-auto-sizer';
import { useClients } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';

interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string, context?: any) => void;
    setClientForInvoice: (client: Client) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (formData: FormData): boolean => {
    const requiredFields: (keyof FormData)[] = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    for (const field of requiredFields) {
        if (!formData[field] || String(formData[field]).trim() === '') return false;
    }
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [deletedClientInfo, setDeletedClientInfo] = useState<{ name: string; timeoutId: ReturnType<typeof setTimeout> } | null>(null);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    // Virtualization State
    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});

    // --- SCROLL ANIMATION LOGIC ---
    const [scrollOffset, setScrollOffset] = useState(0);
    const MAX_SCROLL = 80;

    const handleScroll = ({ scrollOffset: offset }: { scrollOffset: number }) => {
        setScrollOffset(Math.min(offset, MAX_SCROLL));
    };

    const headerOpacity = Math.max(0, 1 - scrollOffset / (MAX_SCROLL * 0.8));
    const headerHeight = Math.max(0, 48 - (scrollOffset / MAX_SCROLL) * 48);
    const controlsTranslate = (scrollOffset / MAX_SCROLL) * -52;

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const getItemSize = (index: number) => {
        const client = clients[index];
        return expandedIds[client?.id] ? 140 : 100;
    };

    const handleDeleteClick = useCallback((clientId: number) => {
        const client = clients.find(c => c.id === clientId);
        if (client) setClientToDelete(client);
    }, [clients]);

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);
            const timeoutId = setTimeout(() => setDeletedClientInfo(null), 3000);
            setDeletedClientInfo({ name: clientToDelete.name, timeoutId });
            setClientToDelete(null);
        }
    };

    const createClientObject = (formData: FormData, id: number, existingClient?: Client | null): Client => {
        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();
        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;
        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }
        const isComplete = isClientDataComplete(formData);
        const baseClient = existingClient || {
            id: id, status: 'Active Client', stage: milestones[0]?.acronym || 'N/A',
            payment: { total: baseTotal, paid: 0, balance: baseTotal, dueDate: 'N/A', planType: 'N/A', promoDetails: promoDetails, paymentHistory: [], installments: [] },
            interactions: [], documentation: { status: 'Pending' },
            officeUse: { commission: { type: 'Percentage', amount: 0, status: 'Pending' } }
        };
        return {
            ...baseClient, id, name: fullName, surname: formData.surname, otherNames: formData.otherNames, initials,
            regDate: formData.paymentDate, email: formData.email, phone: formData.telephone, dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'], location: formData.location, plot: formData.plotNumber, photo: formData.photo,
            propertyType: formData.propertyType, plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: { placeOfWork: formData.placeOfWork, profession: formData.profession, position: formData.position },
            witness: { name: formData.witnessName, address: formData.witnessAddress, phone: formData.witnessPhone },
            nextOfKin: { name: formData.kinName, phone: formData.kinPhone, relationship: formData.kinRelationship, email: formData.kinEmail, address: formData.kinAddress },
            indenture: { name: formData.indentureName, address: formData.indentureAddress },
            officeUse: { ...baseClient.officeUse, salesRep: formData.salesRep, salesManager: formData.salesManager, accountsHead: formData.accountsHead, clerk: formData.clerk },
            isComplete, filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClientAndRedirect = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            const newId = (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);
            let photoUrl = formData.photo;
            if (files?.photo) photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId, editingClient);

            const savedClient = await onSaveClient(newClient);
            setClientFormOpen(false);
            addActivityLog('Create', `Created client: ${newClient.name} and entering Account Management.`);

            setActivePage('Account Management', { id: savedClient.id });
            setClientForInvoice(savedClient);
        } catch (error) { 
            alert("Failed to save client."); 
        }
    };

    const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => {
        const client = clients[index];
        if (!client) return null;
        return (
            <ClientListItem 
                key={client.id} 
                client={client} 
                onViewDetails={onClientSelect} 
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }} 
                onDelete={handleDeleteClick} 
                milestones={milestones}
                style={style}
                isExpanded={!!expandedIds[client.id]}
                onToggleExpand={() => toggleExpand(client.id, index)}
            />
        );
    };

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            <div className="bg-gray-100 dark:bg-gray-950 z-20 flex-shrink-0 transition-all duration-300 ease-out"
                 style={{ transform: `translateY(${controlsTranslate}px)` }}>

                <div style={{ opacity: headerOpacity, height: headerHeight, overflow: 'hidden' }} 
                     className="flex flex-wrap items-center justify-between gap-4 px-1">
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">
                        Clients ({clients.length}{hasNextPage && '+'})
                    </h1>
                    <div className="flex items-center gap-3">
                        <button onClick={() => setImportWizardOpen(true)} className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-bold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 transition-all flex items-center gap-2 text-sm shadow-sm">
                            <UploadIcon className="w-4 h-4" /> Import
                        </button>
                        <button onClick={() => { setEditingClient(null); setClientFormOpen(true); }} className="bg-blue-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-blue-700 transition-all flex items-center gap-2 text-sm shadow-md">
                            <DocumentPlusIcon className="w-4 h-4" /> New Client
                        </button>
                    </div>
                </div>

                <div className="mt-4 bg-white dark:bg-gray-800 p-3 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 mx-1">
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-center">
                        <div className="md:col-span-6 relative">
                            <div className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400">
                                {isLoading ? <LoaderIcon className="animate-spin" /> : <MagnifyingGlassIcon />}
                            </div>
                            <input
                                type="text"
                                placeholder="Quick search database..."
                                className="bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg pl-9 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm dark:text-white"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <div className="md:col-span-3">
                            <select className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 py-2 px-3 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                                <option>All Statuses</option>
                                <option>Active Client</option>
                                <option>Refunded</option>
                                <option>Reallocated</option>
                            </select>
                        </div>
                        <div className="md:col-span-3">
                            <select className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 py-2 px-3 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                                <option>All Locations</option>
                                {properties.map(p => <option key={p.id}>{p.location}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <div className="hidden md:grid grid-cols-12 gap-4 px-5 py-3 text-[10px] font-black text-gray-400 uppercase tracking-widest bg-transparent">
                    <div className="col-span-4">Client Dossier</div>
                    <div className="col-span-2">Contact Details</div>
                    <div className="col-span-2">Allocation</div>
                    <div className="col-span-1 text-center">Status</div>
                    <div className="col-span-2">Financials</div>
                    <div className="col-span-1 text-right pr-2">Manage</div>
                </div>
            </div>

            <div className="flex-grow relative mt-1">
                <AutoSizer>
                    {({ height, width }) => (
                        <List
                            ref={listRef}
                            height={height}
                            itemCount={clients.length}
                            itemSize={getItemSize}
                            width={width}
                            onScroll={handleScroll}
                            className="scrollbar-thin"
                        >
                            {Row}
                        </List>
                    )}
                </AutoSizer>
            </div>

            {hasNextPage && !debouncedSearchTerm && (
                <div className="py-3 text-center border-t border-gray-200 dark:border-gray-800 flex-shrink-0">
                    <button 
                        onClick={() => fetchNextPage()} 
                        disabled={isFetchingNextPage}
                        className="text-blue-600 dark:text-blue-400 text-xs font-black uppercase tracking-widest hover:underline disabled:opacity-50"
                    >
                        {isFetchingNextPage ? 'Loading...' : 'Load More Results'}
                    </button>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={() => { setClientFormOpen(false); setEditingClient(null); }}
                onSave={handleSaveClientAndRedirect}
                onSaveAndPay={handleSaveClientAndRedirect}
                properties={properties}
                editingClient={editingClient}
                clients={clients}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={() => {}}
                requiredHeaders={requiredCsvHeaders}
                sampleHeaders=""
                sampleData=""
                wizardTitle="Import Client Data"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />
        </div>
    );
};

export default ClientsPage;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
    ChevronDownIcon, 
    DocumentPlusIcon, 
    MagnifyingGlassIcon, 
    UploadIcon 
} from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import ClientListItem from '../components/ClientListItem';
import { Client, Milestone, Property, Invoice, ActivityLog } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { VariableSizeList as List } from 'react-window';
import AutoSizer from 'react-virtualized-auto-sizer';
import { useClients } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';

interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string, context?: any) => void;
    setClientForInvoice: (client: Client) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (formData: FormData): boolean => {
    const requiredFields: (keyof FormData)[] = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    for (const field of requiredFields) {
        if (!formData[field] || String(formData[field]).trim() === '') return false;
    }
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [deletedClientInfo, setDeletedClientInfo] = useState<{ name: string; timeoutId: ReturnType<typeof setTimeout> } | null>(null);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    // Virtualization State
    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});

    // --- SCROLL ANIMATION LOGIC ---
    const [scrollOffset, setScrollOffset] = useState(0);
    const MAX_SCROLL = 80;

    const handleScroll = ({ scrollOffset: offset }: { scrollOffset: number }) => {
        setScrollOffset(Math.min(offset, MAX_SCROLL));
    };

    const headerOpacity = Math.max(0, 1 - scrollOffset / (MAX_SCROLL * 0.8));
    const headerHeight = Math.max(0, 48 - (scrollOffset / MAX_SCROLL) * 48);
    const controlsTranslate = (scrollOffset / MAX_SCROLL) * -52;

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const getItemSize = (index: number) => {
        const client = clients[index];
        return expandedIds[client?.id] ? 140 : 100;
    };

    const handleDeleteClick = useCallback((clientId: number) => {
        const client = clients.find(c => c.id === clientId);
        if (client) setClientToDelete(client);
    }, [clients]);

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);
            const timeoutId = setTimeout(() => setDeletedClientInfo(null), 3000);
            setDeletedClientInfo({ name: clientToDelete.name, timeoutId });
            setClientToDelete(null);
        }
    };

    const createClientObject = (formData: FormData, id: number, existingClient?: Client | null): Client => {
        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();
        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;
        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }
        const isComplete = isClientDataComplete(formData);
        const baseClient = existingClient || {
            id: id, status: 'Active Client', stage: milestones[0]?.acronym || 'N/A',
            payment: { total: baseTotal, paid: 0, balance: baseTotal, dueDate: 'N/A', planType: 'N/A', promoDetails: promoDetails, paymentHistory: [], installments: [] },
            interactions: [], documentation: { status: 'Pending' },
            officeUse: { commission: { type: 'Percentage', amount: 0, status: 'Pending' } }
        };
        return {
            ...baseClient, id, name: fullName, surname: formData.surname, otherNames: formData.otherNames, initials,
            regDate: formData.paymentDate, email: formData.email, phone: formData.telephone, dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'], location: formData.location, plot: formData.plotNumber, photo: formData.photo,
            propertyType: formData.propertyType, plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: { placeOfWork: formData.placeOfWork, profession: formData.profession, position: formData.position },
            witness: { name: formData.witnessName, address: formData.witnessAddress, phone: formData.witnessPhone },
            nextOfKin: { name: formData.kinName, phone: formData.kinPhone, relationship: formData.kinRelationship, email: formData.kinEmail, address: formData.kinAddress },
            indenture: { name: formData.indentureName, address: formData.indentureAddress },
            officeUse: { ...baseClient.officeUse, salesRep: formData.salesRep, salesManager: formData.salesManager, accountsHead: formData.accountsHead, clerk: formData.clerk },
            isComplete, filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClientAndRedirect = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            // Check if we have a valid ID or if we're creating a new one
            const newId = editingClient ? editingClient.id : (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

            if (!newId) {
                alert("Error: Client ID could not be generated. Please retry.");
                return;
            }

            let photoUrl = formData.photo;
            if (files?.photo) photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId, editingClient);

            const savedClient = await onSaveClient(newClient);

            if (!savedClient) {
                alert("Error: Client data not saved correctly.");
                return;
            }

            setClientFormOpen(false);
            addActivityLog(editingClient ? 'Update' : 'Create', `Processed client: ${newClient.name}. Opening acquisition details.`);

            // NAVIGATION FIX: Instead of Account Management, go to Client Details (Dossier)
            // Client Details page handles "Acquisition Details" layout.
            onClientSelect(savedClient);

        } catch (error) { 
            console.error("Save failed:", error);
            alert("Failed to save client. Navigation aborted."); 
        }
    };

    const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => {
        const client = clients[index];
        if (!client) return null;
        return (
            <ClientListItem 
                key={client.id} 
                client={client} 
                onViewDetails={onClientSelect} 
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }} 
                onDelete={handleDeleteClick} 
                milestones={milestones}
                style={style}
                isExpanded={!!expandedIds[client.id]}
                onToggleExpand={() => toggleExpand(client.id, index)}
            />
        );
    };

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            <div className="bg-gray-100 dark:bg-gray-950 z-20 flex-shrink-0 transition-all duration-300 ease-out"
                 style={{ transform: `translateY(${controlsTranslate}px)` }}>

                <div style={{ opacity: headerOpacity, height: headerHeight, overflow: 'hidden' }} 
                     className="flex flex-wrap items-center justify-between gap-4 px-1">
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">
                        Clients ({clients.length}{hasNextPage && '+'})
                    </h1>
                    <div className="flex items-center gap-3">
                        <button onClick={() => setImportWizardOpen(true)} className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-bold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 transition-all flex items-center gap-2 text-sm shadow-sm">
                            <UploadIcon className="w-4 h-4" /> Import
                        </button>
                        <button onClick={() => { setEditingClient(null); setClientFormOpen(true); }} className="bg-blue-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-blue-700 transition-all flex items-center gap-2 text-sm shadow-md">
                            <DocumentPlusIcon className="w-4 h-4" /> New Client
                        </button>
                    </div>
                </div>

                <div className="mt-4 bg-white dark:bg-gray-800 p-3 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 mx-1">
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-center">
                        <div className="md:col-span-6 relative">
                            <div className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400">
                                {isLoading ? <LoaderIcon className="animate-spin" /> : <MagnifyingGlassIcon />}
                            </div>
                            <input
                                type="text"
                                placeholder="Quick search database..."
                                className="bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg pl-9 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm dark:text-white"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <div className="md:col-span-3">
                            <select className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 py-2 px-3 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                                <option>All Statuses</option>
                                <option>Active Client</option>
                                <option>Refunded</option>
                                <option>Reallocated</option>
                            </select>
                        </div>
                        <div className="md:col-span-3">
                            <select className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 py-2 px-3 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                                <option>All Locations</option>
                                {properties.map(p => <option key={p.id}>{p.location}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <div className="hidden md:grid grid-cols-12 gap-4 px-5 py-3 text-[10px] font-black text-gray-400 uppercase tracking-widest bg-transparent">
                    <div className="col-span-4">Client Dossier</div>
                    <div className="col-span-2">Contact Details</div>
                    <div className="col-span-2">Allocation</div>
                    <div className="col-span-1 text-center">Status</div>
                    <div className="col-span-2">Financials</div>
                    <div className="col-span-1 text-right pr-2">Manage</div>
                </div>
            </div>

            <div className="flex-grow relative mt-1">
                <AutoSizer>
                    {({ height, width }) => (
                        <List
                            ref={listRef}
                            height={height}
                            itemCount={clients.length}
                            itemSize={getItemSize}
                            width={width}
                            onScroll={handleScroll}
                            className="scrollbar-thin"
                        >
                            {Row}
                        </List>
                    )}
                </AutoSizer>
            </div>

            {hasNextPage && !debouncedSearchTerm && (
                <div className="py-3 text-center border-t border-gray-200 dark:border-gray-800 flex-shrink-0">
                    <button 
                        onClick={() => fetchNextPage()} 
                        disabled={isFetchingNextPage}
                        className="text-blue-600 dark:text-blue-400 text-xs font-black uppercase tracking-widest hover:underline disabled:opacity-50"
                    >
                        {isFetchingNextPage ? 'Loading...' : 'Load More Results'}
                    </button>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={() => { setClientFormOpen(false); setEditingClient(null); }}
                onSave={handleSaveClientAndRedirect}
                onSaveAndPay={handleSaveClientAndRedirect}
                properties={properties}
                editingClient={editingClient}
                clients={clients}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={() => {}}
                requiredHeaders={requiredCsvHeaders}
                sampleHeaders=""
                sampleData=""
                wizardTitle="Import Client Data"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />
        </div>
    );
};

