interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string, context?: any) => void;
    setClientForInvoice: (client: Client) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

const isClientDataComplete = (formData: FormData): boolean => {
    const requiredFields: (keyof FormData)[] = [ 'surname', 'otherNames', 'currentAddress', 'telephone', 'kinName', 'kinPhone', 'witnessName', 'witnessPhone', 'witnessAddress', 'location', 'plotNumber', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];
    for (const field of requiredFields) {
        if (!formData[field] || String(formData[field]).trim() === '') return false;
    }
    return true;
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [deletedClientInfo, setDeletedClientInfo] = useState<{ name: string; timeoutId: ReturnType<typeof setTimeout> } | null>(null);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});

    const [scrollOffset, setScrollOffset] = useState(0);
    const MAX_SCROLL = 80;

    const handleScroll = ({ scrollOffset: offset }: { scrollOffset: number }) => {
        setScrollOffset(Math.min(offset, MAX_SCROLL));
    };

    const headerOpacity = Math.max(0, 1 - scrollOffset / (MAX_SCROLL * 0.8));
    const headerHeight = Math.max(0, 48 - (scrollOffset / MAX_SCROLL) * 48);
    const controlsTranslate = (scrollOffset / MAX_SCROLL) * -52;

    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearchTerm(searchTerm);
        }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const toggleExpand = (id: number, index: number) => {
        setExpandedIds(prev => ({ ...prev, [id]: !prev[id] }));
        if (listRef.current) {
            listRef.current.resetAfterIndex(index);
        }
    };

    const getItemSize = (index: number) => {
        const client = clients[index];
        return expandedIds[client?.id] ? 140 : 100;
    };

    const handleDeleteClick = useCallback((clientId: number) => {
        const client = clients.find(c => c.id === clientId);
        if (client) setClientToDelete(client);
    }, [clients]);

    const confirmDeleteClient = async () => {
        if (clientToDelete) {
            await onDeleteClient(clientToDelete.id);
            addActivityLog('Delete', `Deleted client: ${clientToDelete.name}`);
            const timeoutId = setTimeout(() => setDeletedClientInfo(null), 3000);
            setDeletedClientInfo({ name: clientToDelete.name, timeoutId });
            setClientToDelete(null);
        }
    };

    const createClientObject = (formData: FormData, id: number, existingClient?: Client | null): Client => {
        const fullName = `${formData.surname} ${formData.otherNames}`;
        const nameParts = fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();
        const selectedProperty = properties.find(p => p.location === formData.location);
        let propertyPrice = selectedProperty ? selectedProperty.price : 200000;
        const plotCount = formData.plotNumber.split(',').map(p => p.trim()).filter(Boolean).length || 1;
        let baseTotal = propertyPrice * plotCount;
        let promoDetails: string | undefined = undefined;
        if (selectedProperty && selectedProperty.discount && new Date(selectedProperty.discount.endDate) >= new Date()) {
            baseTotal *= (1 - selectedProperty.discount.percentage / 100);
            promoDetails = `${selectedProperty.discount.percentage}% discount applied (Ends ${selectedProperty.discount.endDate})`;
        }
        const isComplete = isClientDataComplete(formData);

        // Milestone logic: Start with SFR
        const baseClient = existingClient || {
            id: id, status: 'Active Client', stage: 'SFR',
            payment: { total: baseTotal, paid: 0, balance: baseTotal, dueDate: 'N/A', planType: 'N/A', promoDetails: promoDetails, paymentHistory: [], installments: [] },
            interactions: [], documentation: { status: 'Pending' },
            officeUse: { commission: { type: 'Percentage', amount: 0, status: 'Pending' } }
        };
        return {
            ...baseClient, id, name: fullName, surname: formData.surname, otherNames: formData.otherNames, initials,
            regDate: formData.paymentDate, email: formData.email, phone: formData.telephone, dateOfBirth: formData.dateOfBirth,
            gender: formData.gender as Client['gender'], location: formData.location, plot: formData.plotNumber, photo: formData.photo,
            propertyType: formData.propertyType, plannedDevelopmentYear: formData.plannedDevelopmentYear,
            professionalDetails: { placeOfWork: formData.placeOfWork, profession: formData.profession, position: formData.position },
            witness: { name: formData.witnessName, address: formData.witnessAddress, phone: formData.witnessPhone },
            nextOfKin: { name: formData.kinName, phone: formData.kinPhone, relationship: formData.kinRelationship, email: formData.kinEmail, address: formData.kinAddress },
            indenture: { name: formData.indentureName, address: formData.indentureAddress },
            officeUse: { ...baseClient.officeUse, salesRep: formData.salesRep, salesManager: formData.salesManager, accountsHead: formData.accountsHead, clerk: formData.clerk },
            isComplete, filledFormPdf: formData.filledFormPdf,
        };
    };

    const handleSaveClientAndRedirect = async (formData: FormData, files?: { photo?: File | null, pdf?: File | null }) => {
        try {
            const isNew = !editingClient;
            const newId = editingClient ? editingClient.id : (clients.length > 0 ? Math.max(...clients.map(c => c.id)) + 1 : 1);

            if (!newId) {
                alert("Error: Client ID could not be generated. Please retry.");
                return;
            }

            let photoUrl = formData.photo;
            if (files?.photo) photoUrl = await uploadFile(files.photo, `clients/${newId}/photos/${files.photo.name}`);
            let pdfUrl = formData.filledFormPdf;
            if (files?.pdf) pdfUrl = await uploadFile(files.pdf, `clients/${newId}/documents/${files.pdf.name}`);

            const updatedFormData = { ...formData, photo: photoUrl, filledFormPdf: pdfUrl };
            const newClient = createClientObject(updatedFormData, newId, editingClient);

            const savedClient = await onSaveClient(newClient);

            if (isNew) {
                // Milestone Trigger: SFR
                await addMilestone({
                    clientId: newId,
                    milestoneCode: 'SFR',
                    dateCompleted: new Date().toISOString().split('T')[0],
                    notes: 'Initial client registration.'
                });
            }

            if (!savedClient) {
                alert("Error: Client data not saved correctly.");
                return;
            }

            setClientFormOpen(false);
            addActivityLog(editingClient ? 'Update' : 'Create', `Processed client: ${newClient.name}. Opening details.`);
            onClientSelect(savedClient);

        } catch (error) { 
            console.error("Save failed:", error);
            alert("Failed to save client."); 
        }
    };

    const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => {
        const client = clients[index];
        if (!client) return null;
        return (
            <ClientListItem 
                key={client.id} 
                client={client} 
                onViewDetails={onClientSelect} 
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }} 
                onDelete={handleDeleteClick} 
                milestones={milestones}
                style={style}
                isExpanded={!!expandedIds[client.id]}
                onToggleExpand={() => toggleExpand(client.id, index)}
            />
        );
    };

    const requiredCsvHeaders = [ 'surname', 'otherNames', 'dateOfBirth', 'currentAddress', 'telephone', 'email', 'gender', 'placeOfWork', 'profession', 'position', 'kinName', 'kinAddress', 'kinPhone', 'kinRelationship', 'kinEmail', 'witnessName', 'witnessAddress', 'witnessPhone', 'paymentDate', 'paymentMethod', 'location', 'plotNumber', 'propertyType', 'plannedDevelopmentYear', 'indentureName', 'indentureAddress', 'salesRep', 'salesManager', 'accountsHead', 'clerk' ];

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            <div className="bg-gray-100 dark:bg-gray-950 z-20 flex-shrink-0 transition-all duration-300 ease-out"
                 style={{ transform: `translateY(${controlsTranslate}px)` }}>

                <div style={{ opacity: headerOpacity, height: headerHeight, overflow: 'hidden' }} 
                     className="flex flex-wrap items-center justify-between gap-4 px-1">
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">
                        Clients ({clients.length}{hasNextPage && '+'})
                    </h1>
                    <div className="flex items-center gap-3">
                        <button onClick={() => setImportWizardOpen(true)} className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-bold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 transition-all flex items-center gap-2 text-sm shadow-sm">
                            <UploadIcon className="w-4 h-4" /> Import
                        </button>
                        <button onClick={() => { setEditingClient(null); setClientFormOpen(true); }} className="bg-blue-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-blue-700 transition-all flex items-center gap-2 text-sm shadow-md">
                            <DocumentPlusIcon className="w-4 h-4" /> New Client
                        </button>
                    </div>
                </div>

                <div className="mt-4 bg-white dark:bg-gray-800 p-3 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 mx-1">
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-center">
                        <div className="md:col-span-6 relative">
                            <div className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400">
                                {isLoading ? <LoaderIcon className="animate-spin" /> : <MagnifyingGlassIcon />}
                            </div>
                            <input
                                type="text"
                                placeholder="Quick search database..."
                                className="bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg pl-9 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm dark:text-white"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <div className="md:col-span-3">
                            <select className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 py-2 px-3 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                                <option>All Statuses</option>
                                <option>Active Client</option>
                                <option>Refunded</option>
                                <option>Reallocated</option>
                            </select>
                        </div>
                        <div className="md:col-span-3">
                            <select className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 py-2 px-3 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                                <option>All Locations</option>
                                {properties.map(p => <option key={p.id}>{p.location}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <div className="hidden md:grid grid-cols-12 gap-4 px-5 py-3 text-[10px] font-black text-gray-400 uppercase tracking-widest bg-transparent">
                    <div className="col-span-4">Client Dossier</div>
                    <div className="col-span-2">Contact Details</div>
                    <div className="col-span-2">Allocation</div>
                    <div className="col-span-1 text-center">Status</div>
                    <div className="col-span-2">Financials</div>
                    <div className="col-span-1 text-right pr-2">Manage</div>
                </div>
            </div>

            <div className="flex-grow relative mt-1">
                <AutoSizer>
                    {({ height, width }) => (
                        <List
                            ref={listRef}
                            height={height}
                            itemCount={clients.length}
                            itemSize={getItemSize}
                            width={width}
                            onScroll={handleScroll}
                            className="scrollbar-thin"
                        >
                            {Row}
                        </List>
                    )}
                </AutoSizer>
            </div>

            {hasNextPage && !debouncedSearchTerm && (
                <div className="py-3 text-center border-t border-gray-200 dark:border-gray-800 flex-shrink-0">
                    <button 
                        onClick={() => fetchNextPage()} 
                        disabled={isFetchingNextPage}
                        className="text-blue-600 dark:text-blue-400 text-xs font-black uppercase tracking-widest hover:underline disabled:opacity-50"
                    >
                        {isFetchingNextPage ? 'Loading...' : 'Load More Results'}
                    </button>
                </div>
            )}

            <ClientForm
                isOpen={isClientFormOpen}
                onClose={() => { setClientFormOpen(false); setEditingClient(null); }}
                onSave={handleSaveClientAndRedirect}
                onSaveAndPay={handleSaveClientAndRedirect}
                properties={properties}
                editingClient={editingClient}
                clients={clients}
            />

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={() => {}}
                requiredHeaders={requiredCsvHeaders}
                sampleHeaders=""
                sampleData=""
                wizardTitle="Import Client Data"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={confirmDeleteClient}
                itemName={clientToDelete?.name || ''}
                itemType="Client"
            />
        </div>
    );
};

export default ClientsPage;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, Invoice, PaymentTransaction, Staff, Role, AppNotification, Property, MilestoneRecord } from '../types';
import { 
    BellIcon,
    UserCircleIcon,
    ClockIcon,
    CheckCircleIcon,
    LockClosedIcon,
    BanknotesIcon,
    ShieldCheckIcon,
    DocumentTextIcon,
    PlusCircleIcon,
    ChartBarIcon
} from '../components/icons/DummyIcons';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input, Select } from '../components/ui/Input';
import { TableContainer, Thead, Tbody, Tr, Th, Td } from '../components/ui/Table';
import { Badge } from '../components/ui/Badge';
import { RecordPaymentModal } from '../components/FinancialRecordEditor';
import { FinancialReportsView } from '../components/FinancialReportsView';
import { NotificationCenter } from '../components/NotificationCenter';
import { useNotificationTriggers } from '../hooks/useNotificationTriggers';
import { useAuth } from '../context/AuthContext';
import { useProperties, useMilestones } from '../hooks/useAppData';
import { addMilestone } from '../services/dbService';

interface AccountManagementPageProps {
  clients: Client[];
  onSaveClient: (client: Client) => Promise<Client>;
  onClientSelect?: (client: Client) => void;
  invoices: Invoice[];
  onSaveInvoice: (invoice: Invoice) => Promise<void>;
  clientForInvoice: Client | null;
  setClientForInvoice: (client: Client | null) => void;
  receiptPattern: any; 
  setReceiptPattern: any;
  setReceiptAlerts: any;
  currentStaff: Staff;
  roles: Role[];
  setActivePage: (page: string, context?: any) => void;
  overrideClientId?: number | null;
  isEmbedded?: boolean;
}

const AccountManagementPage: React.FC<AccountManagementPageProps> = ({ 
    clients, onSaveClient, clientForInvoice, setClientForInvoice, currentStaff, roles, setActivePage, overrideClientId = null, isEmbedded = false
}) => {
  const { properties } = useProperties();
  const [viewMode, setViewMode] = useState<'list' | 'alerts' | 'reports'>('list');
  const [activeSubModule, setActiveSubModule] = useState<'overview' | 'history'>('overview');
  const [selectedClientId, setSelectedClientId] = useState<number | null>(overrideClientId);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [installmentOption, setInstallmentOption] = useState<string>('Outright');

  const { milestones } = useMilestones(selectedClientId || undefined);

  useEffect(() => {
    if (overrideClientId !== null) {
      setSelectedClientId(overrideClientId);
    }
  }, [overrideClientId]);

  const selectedClient = useMemo(() => 
    clients.find(c => c.id === (selectedClientId || clientForInvoice?.id))
  , [clients, selectedClientId, clientForInvoice]);

  const isCEO = useMemo(() => currentStaff.roleId === 'CEO', [currentStaff]);

  const canMakePayment = useMemo(() => {
    return ['CEO', 'Administrator', 'Chief Accountant'].includes(currentStaff.roleId);
  }, [currentStaff]);

  const originalPricePerPlot = useMemo(() => {
    if (!selectedClient) return 0;
    const matchingProperty = properties.find(p => p.location === selectedClient.location);
    return matchingProperty ? matchingProperty.price : 0;
  }, [selectedClient, properties]);

  const discountAmount = selectedClient?.payment.promoDetails ? (originalPricePerPlot * 0.1) : 0; 
  const priceAfterDiscount = originalPricePerPlot - discountAmount;

  const emiBreakdown = useMemo(() => {
    if (installmentOption === 'Outright') return null;
    let months = parseInt(installmentOption) || 1;
    return {
      monthlyAmount: priceAfterDiscount / months,
      installments: months,
      totalPayable: priceAfterDiscount
    };
  }, [installmentOption, priceAfterDiscount]);

  const paymentAggregation = useMemo(() => {
    if (!selectedClient) return { land: 0, indenture: 0 };
    return selectedClient.payment.paymentHistory.reduce((acc, txn) => {
        const type = (txn as any).type || 'Land';
        if (type === 'Land') acc.land += txn.amount;
        if (type === 'Indenture') acc.indenture += txn.amount;
        return acc;
    }, { land: 0, indenture: 0 });
  }, [selectedClient]);

  const handleInitialSave = async () => {
    if (!selectedClient) return;
    setIsSaving(true);
    try {
        const updatedClient = {
            ...selectedClient,
            payment: {
                ...selectedClient.payment,
                isInitialized: true,
                planType: installmentOption,
                total: priceAfterDiscount,
                balance: priceAfterDiscount - selectedClient.payment.paid
            }
        };
        await onSaveClient(updatedClient);
    } finally {
        setIsSaving(false);
    }
  };

  const handleRecordPayment = async (client: Client, paymentData: any) => {
    const newTransaction: PaymentTransaction = { 
        ...paymentData, 
        id: `TXN-${Date.now()}`, 
        status: 'Success' 
    };

    const newPaid = client.payment.paid + newTransaction.amount;
    const newBalance = client.payment.balance - newTransaction.amount;

    const updatedClient = {
        ...client,
        payment: {
            ...client.payment,
            paymentHistory: [...client.payment.paymentHistory, newTransaction],
            paid: newPaid,
            balance: newBalance,
        }
    };
    await onSaveClient(updatedClient);

    // MILESTONE TRIGGER: PLR (Full Land Payment)
    if (newBalance <= 0) {
        await addMilestone({
            clientId: client.id,
            milestoneCode: 'PLR',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Full payment for land received.'
        });
    }

    // MILESTONE TRIGGER: PFI (Indenture Payment)
    if (paymentData.type === 'Indenture') {
        await addMilestone({
            clientId: client.id,
            milestoneCode: 'PFI',
            dateCompleted: new Date().toISOString().split('T')[0],
            notes: 'Payment for indenture recorded.'
        });
    }

    setIsPaymentModalOpen(false);
  };

  const formatCurrency = (amount: number) => `₵${new Intl.NumberFormat('en-GH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)}`;

  const generatedNotifications = useNotificationTriggers(clients);
  const [localNotifications, setLocalNotifications] = useState<AppNotification[]>([]);

  useEffect(() => {
    setLocalNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newAlerts = generatedNotifications.filter(n => !existingIds.has(n.id));
        return [...prev, ...newAlerts];
    });
  }, [generatedNotifications]);

  const currentRoleName = roles.find(r => r.id === currentStaff.roleId)?.name || 'Staff';
  const roleAlerts = localNotifications.filter(n => n.recipientRole === currentRoleName && !n.isRead);

  if (viewMode === 'reports') return <FinancialReportsView onBack={() => setViewMode('list')} clients={clients} staffList={[]} />;

  return (
    <div className={`flex flex-col ${isEmbedded ? 'h-auto' : 'h-[calc(100vh-120px)]'} space-y-6`}>
      {!isEmbedded && (
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
              <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Account Management</h1>
              <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm font-medium">Standard bookkeeping ledger and transactional audit.</p>
          </div>
          <div className="flex gap-3">
            <Button 
              variant={roleAlerts.length > 0 ? 'primary' : 'secondary'} 
              onClick={() => setViewMode(viewMode === 'alerts' ? 'list' : 'alerts')} 
              icon={<BellIcon className="w-5 h-5" />}
              className="relative"
            >
                Role Alerts
                {roleAlerts.length > 0 && (
                    <span className="absolute -top-1 -right-1 flex h-4 w-4">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500 text-[10px] text-white items-center justify-center font-bold">{roleAlerts.length}</span>
                    </span>
                )}
            </Button>
            <Button variant="secondary" onClick={() => setViewMode('reports')} icon={<ChartBarIcon className="w-5 h-5" />}>
                Reconciliation
            </Button>
          </div>
        </div>
      )}

      <div className="flex-grow flex gap-6 overflow-hidden">
        <div className="w-64 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm flex flex-col shrink-0 overflow-hidden">
          {!isEmbedded && (
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/50">
               <Select 
                label="Select Account" 
                value={selectedClientId || ''} 
                onChange={(e) => {
                    setSelectedClientId(Number(e.target.value));
                    setClientForInvoice(null);
                }}
              >
                <option value="">-- Choose Client --</option>
                {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </Select>
            </div>
          )}
          <nav className="p-2 space-y-1">
            <button 
              onClick={() => setActiveSubModule('overview')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'overview' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <DocumentTextIcon className="w-5 h-5" />
              Overview
            </button>
            <button 
              onClick={() => setActiveSubModule('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-bold transition-all ${activeSubModule === 'history' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700'}`}
            >
              <ClockIcon className="w-5 h-5" />
              History
            </button>
          </nav>
        </div>

        <div className="flex-grow overflow-y-auto pr-2 scrollbar-thin">
            {viewMode === 'alerts' ? (
                <NotificationCenter 
                    notifications={localNotifications}
                    currentRole={currentRoleName}
                    onReschedule={() => {}}
                    onMarkRead={(id) => setLocalNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n))}
                />
            ) : !selectedClient ? (
                <div className="h-full flex flex-col items-center justify-center bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 opacity-40 py-20">
                  <UserCircleIcon className="w-16 h-16 text-gray-300 mb-4" />
                  <p className="text-xl font-black uppercase text-gray-400">
                    {isEmbedded ? 'Client data unavailable. Please return to Clients list.' : 'Select a Client to view financial records'}
                  </p>
                </div>
            ) : activeSubModule === 'overview' ? (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <Card title="Active Account Ledger">
                        <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Property Location</p>
                                <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.location || '—'}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Number of Plots</p>
                                <p className="text-sm font-bold text-gray-900 dark:text-white">{selectedClient.plot.split(',').length}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Price Per Plot</p>
                                <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(originalPricePerPlot)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Discount Applied</p>
                                <Badge variant={discountAmount > 0 ? 'success' : 'neutral'}>{discountAmount > 0 ? 'YES' : 'NO'}</Badge>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">EMI Selection</p>
                                <Badge variant="info">{selectedClient.payment.planType || 'N/A'}</Badge>
                            </div>
                        </div>
                        <div className="mt-8 border-t border-gray-100 dark:border-gray-700 pt-6">
                            <Button 
                                onClick={handleInitialSave}
                                disabled={!!(selectedClient.payment as any).isInitialized}
                                isLoading={isSaving}
                                icon={<CheckCircleIcon className="w-5 h-5" />}
                                className="w-full md:w-auto px-12 py-3"
                            >
                                {(selectedClient.payment as any).isInitialized ? 'Details Locked' : 'Save Payment Details'}
                            </Button>
                        </div>
                    </Card>

                    <Card title="Payment Details">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <Input label="Original Price Per Plot" value={formatCurrency(originalPricePerPlot)} readOnly className="bg-gray-50 font-bold" />
                            <Input label="Price After Discount" value={formatCurrency(priceAfterDiscount)} readOnly className="bg-gray-50 font-bold text-green-600" />
                            <Select 
                                label="Installment Options*" 
                                value={installmentOption} 
                                onChange={(e) => setInstallmentOption(e.target.value)}
                                disabled={!!(selectedClient.payment as any).isInitialized}
                            >
                                <option value="Outright">Outright</option>
                                <option value="3">3 Months</option>
                                <option value="6">6 Months</option>
                                <option value="12">12 Months</option>
                            </Select>
                        </div>
                        {emiBreakdown && (
                            <div className="mt-8 p-6 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-100 dark:border-blue-800 animate-in slide-in-from-top-2">
                                <h4 className="text-xs font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                    <BanknotesIcon className="w-4 h-4" /> EMI Calculation Breakdown
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                    <div>
                                        <p className="text-[10px] font-black text-blue-400 uppercase">Monthly Installment</p>
                                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(emiBreakdown.monthlyAmount)}</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-black text-blue-400 uppercase">Term Length</p>
                                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{emiBreakdown.installments} Months</p>
                                    </div>
                                    <div>
                                        <p className="text-[10px] font-black text-blue-400 uppercase">Total Commitment</p>
                                        <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(emiBreakdown.totalPayable)}</p>
                                    </div>
                                </div>
                            </div>
                        )}
                    </Card>

                    <Card title="Current Ledger Standing" className="bg-gray-50/50 dark:bg-gray-900/20 border-dashed">
                         <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Contract Total</p>
                                <p className="text-2xl font-black text-gray-900 dark:text-white">{formatCurrency(selectedClient.payment.total)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Amount Paid</p>
                                <p className="text-2xl font-black text-green-600">{formatCurrency(selectedClient.payment.paid)}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Outstanding Balance</p>
                                <p className={`text-2xl font-black ${selectedClient.payment.balance < 0 ? 'text-purple-600' : 'text-red-600'}`}>
                                    {formatCurrency(selectedClient.payment.balance)}
                                    {selectedClient.payment.balance < 0 && <span className="text-[10px] block uppercase text-purple-400 font-black">Account Overpaid</span>}
                                </p>
                            </div>
                        </div>
                    </Card>
                </div>
            ) : (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <Card title="Transactional Ledger History" action={
                        <div className="flex gap-2">
                             <Button 
                                variant="primary" 
                                size="sm" 
                                disabled={!canMakePayment}
                                onClick={() => setIsPaymentModalOpen(true)}
                                icon={<PlusCircleIcon className="w-4 h-4" />}
                                title={!canMakePayment ? "Insufficient permissions" : "Post new payment"}
                            >
                                Make Payment
                            </Button>
                            <Button 
                                variant="secondary" 
                                size="sm" 
                                disabled={!isCEO}
                                onClick={() => setActivePage('Amendment Form', selectedClient)}
                                icon={<ShieldCheckIcon className="w-4 h-4" />}
                            >
                                Authorize Amendment
                            </Button>
                        </div>
                    }>
                        <TableContainer className="border-0 shadow-none">
                            <table className="w-full text-sm text-left">
                                <Thead>
                                    <tr>
                                        <Th>Type</Th>
                                        <Th>Expected Date</Th>
                                        <Th>Actual Date</Th>
                                        <Th className="text-right">Amount Paid</Th>
                                        <Th className="text-center">Status</Th>
                                        <Th className="text-right">Balance</Th>
                                    </tr>
                                </Thead>
                                <Tbody>
                                    {selectedClient.payment.paymentHistory.length === 0 ? (
                                        <Tr>
                                            <Td colSpan={6} className="text-center py-12 text-gray-400 italic">No historical transactions found.</Td>
                                        </Tr>
                                    ) : (
                                        selectedClient.payment.paymentHistory.map((txn, idx) => {
                                            const isOverdue = new Date(txn.date) > new Date(selectedClient.payment.dueDate);
                                            const isFuture = new Date(txn.date) > new Date();
                                            return (
                                                <Tr key={txn.id || idx}>
                                                    <Td className="font-bold text-gray-600 dark:text-gray-400">{(txn as any).type || 'Land'}</Td>
                                                    <Td className="text-gray-500 font-medium">{selectedClient.payment.dueDate || '—'}</Td>
                                                    <Td className="font-bold text-gray-900 dark:text-white">{txn.date || '—'}</Td>
                                                    <Td className="text-right font-black text-green-600">{formatCurrency(txn.amount)}</Td>
                                                    <Td className="text-center">
                                                        <Badge variant={isFuture ? 'info' : (isOverdue ? 'danger' : 'success')}>
                                                            {isFuture ? 'SCHEDULED' : (isOverdue ? 'OVERDUE' : 'ON TRACK')}
                                                        </Badge>
                                                    </Td>
                                                    <Td className="text-right font-black text-gray-900 dark:text-white">
                                                        {formatCurrency(selectedClient.payment.total - selectedClient.payment.paymentHistory.slice(0, idx + 1).reduce((s,t)=>s+t.amount,0))}
                                                    </Td>
                                                </Tr>
                                            );
                                        })
                                    )}
                                </Tbody>
                            </table>
                        </TableContainer>

                        <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4 border-t border-gray-100 dark:border-gray-700 pt-6">
                            <div className="p-4 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-100 dark:border-blue-900/50">
                                <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Total Land Payments Made</p>
                                <p className="text-xl font-black text-blue-700 dark:text-blue-300">{formatCurrency(paymentAggregation.land)}</p>
                            </div>
                            <div className="p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-xl border border-emerald-100 dark:border-emerald-900/50">
                                <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Total Indenture Payments Made</p>
                                <p className="text-xl font-black text-emerald-700 dark:text-blue-300">{formatCurrency(paymentAggregation.indenture)}</p>
                            </div>
                        </div>
                    </Card>
                </div>
            )}
        </div>

        {selectedClient && (
            <RecordPaymentModal 
                isOpen={isPaymentModalOpen} 
                onClose={() => setIsPaymentModalOpen(false)} 
                client={selectedClient}
