import { db } from './firebase';
import { collection, getDocs, doc, setDoc, deleteDoc, query, limit, startAfter, where, orderBy, QueryDocumentSnapshot, DocumentData, addDoc } from 'firebase/firestore';
import { Client, AmendmentRequest, MilestoneRecord } from '../types';

const CLIENTS_COL = 'clients';
const AMENDMENTS_COL = 'amendments';
const MILESTONES_COL = 'milestones';

const sanitizeData = <T>(data: T, seen = new WeakSet()): T => {
    if (data === null || typeof data !== 'object') return data;
    if (seen.has(data)) return undefined as any;
    seen.add(data);
    if (data instanceof Date) return data.toISOString() as any;
    if (Array.isArray(data)) {
        return data.map(item => sanitizeData(item, seen)).filter(i => i !== undefined) as any;
    }
    const sanitizedObj: any = {};
    for (const [key, value] of Object.entries(data)) {
        if (value !== undefined && typeof value !== 'function') {
            const sanitizedValue = sanitizeData(value, seen);
            if (sanitizedValue !== undefined) {
                sanitizedObj[key] = sanitizedValue;
            }
        }
    }
    return sanitizedObj as T;
};

const fetchCollection = async <T>(colName: string): Promise<T[]> => {
    try {
        const snapshot = await getDocs(collection(db, colName));
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as T));
    } catch (error) {
        console.error(`Error fetching ${colName}:`, error);
        return [];
    }
};

export const fetchClientsPaginated = async (lastDoc: QueryDocumentSnapshot<DocumentData> | null, pageSize: number = 20) => {
    try {
        let q = query(collection(db, CLIENTS_COL), orderBy('id', 'desc'), limit(pageSize));
        if (lastDoc) {
            q = query(collection(db, CLIENTS_COL), orderBy('id', 'desc'), startAfter(lastDoc), limit(pageSize));
        }
        const snapshot = await getDocs(q);
        const data = snapshot.docs.map(doc => doc.data() as Client);
        const lastVisible = snapshot.docs[snapshot.docs.length - 1];
        return { data, lastDoc: lastVisible };
    } catch (error) {
        console.error("Error fetching paginated clients:", error);
        return { data: [], lastDoc: null };
    }
};

export const searchClients = async (searchTerm: string) => {
    try {
        const q = query(
            collection(db, CLIENTS_COL),
            where('name', '>=', searchTerm),
            where('name', '<=', searchTerm + '\uf8ff'),
            limit(50)
        );
        const snapshot = await getDocs(q);
        return snapshot.docs.map(doc => doc.data() as Client);
    } catch (error) {
        console.error("Error searching clients:", error);
        return [];
    }
};

export const fetchClients = () => fetchCollection<Client>(CLIENTS_COL); 
export const persistClient = async (client: Client) => {
    await setDoc(doc(db, CLIENTS_COL, String(client.id)), sanitizeData(client));
};
export const removeClient = async (id: number) => {
    await deleteDoc(doc(db, CLIENTS_COL, String(id)));
};

export const fetchAmendments = () => fetchCollection<AmendmentRequest>(AMENDMENTS_COL);
export const persistAmendment = async (amendment: AmendmentRequest) => {
    await setDoc(doc(db, AMENDMENTS_COL, String(amendment.id)), sanitizeData(amendment));
};

// --- Milestones Collection ---
export const fetchMilestones = () => fetchCollection<MilestoneRecord>(MILESTONES_COL);
export const fetchMilestonesForClient = async (clientId: number) => {
    const q = query(collection(db, MILESTONES_COL), where('clientId', '==', clientId));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as MilestoneRecord));
};
export const persistMilestone = async (milestone: MilestoneRecord) => {
    // Unique composite key to prevent duplicates
    const docId = `${milestone.clientId}_${milestone.milestoneCode}`;
    await setDoc(doc(db, MILESTONES_COL, docId), sanitizeData(milestone));
};

import { useQuery, useMutation, useQueryClient, useInfiniteQuery } from '@tanstack/react-query';
import * as dbService from '../services/dbService';
import { auth } from '../services/firebase';
import { 
    Client, Property, Invoice, Staff, Lead, Promotion, 
    ActivityLog, Role, AmendmentRequest, CompanySettings, MilestoneRecord 
} from '../types';
import React, { useState } from 'react';

// --- Clients ---
export const useClients = (searchTerm: string = '') => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const {
        data,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
        isLoading
    } = useInfiniteQuery({
        queryKey: ['clients', searchTerm],
        queryFn: ({ pageParam }) => 
            searchTerm 
                ? dbService.searchClients(searchTerm).then(data => ({ data, lastDoc: null }))
                : dbService.fetchClientsPaginated(pageParam as any),
        initialPageParam: null,
        getNextPageParam: (lastPage) => lastPage.lastDoc,
        enabled: isAuthenticated,
    });

    const clients = data?.pages.flatMap(page => page.data) || [];

    const saveClientMutation = useMutation({
        mutationFn: async (client: Client) => {
            const isNew = !clients.some(c => c.id === client.id);
            const result = await dbService.persistClient(client);

            // Trigger: SFR (Initial)
            if (isNew) {
                await dbService.persistMilestone({
                    clientId: client.id,
                    milestoneCode: 'SFR',
                    dateCompleted: new Date().toISOString().split('T')[0],
                    notes: 'Initial registration received.'
                });
            }

            // Trigger: ACA (Assign Client Address)
            if (client.location && client.location !== 'N/A') {
                await dbService.persistMilestone({
                    clientId: client.id,
                    milestoneCode: 'ACA',
                    dateCompleted: new Date().toISOString().split('T')[0],
                    notes: `Address assigned: ${client.location}`
                });
            }

            return result;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const deleteClientMutation = useMutation({
        mutationFn: dbService.removeClient,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return {
        clients,
        isLoading,
        hasNextPage,
        fetchNextPage,
        isFetchingNextPage,
        saveClient: (client: Client) => saveClientMutation.mutateAsync(client),
        deleteClient: (id: number) => deleteClientMutation.mutateAsync(id)
    };
};

// --- Milestones ---
export const useMilestones = (clientId?: number) => {
    const queryClient = useQueryClient();
    const { data: milestones = [], isLoading } = useQuery({
        queryKey: ['milestones', clientId],
        queryFn: () => clientId ? dbService.fetchMilestonesForClient(clientId) : dbService.fetchMilestones(),
    });

    const saveMilestoneMutation = useMutation({
        mutationFn: dbService.persistMilestone,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['milestones'] });
        }
    });

    return { 
        milestones, 
        isLoading, 
        saveMilestone: saveMilestoneMutation.mutateAsync 
    };
};

// --- Properties ---
export const useProperties = () => {
    const queryClient = useQueryClient();
    const isAuthenticated = !!auth.currentUser;

    const { data: properties = [] } = useQuery({
        queryKey: ['properties'],
        queryFn: dbService.fetchProperties,
        staleTime: 1000 * 60 * 10,
        enabled: isAuthenticated,
    });

    const savePropertyMutation = useMutation({
        mutationFn: dbService.persistProperty,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['properties'] })
    });

    const deletePropertyMutation = useMutation({
        mutationFn: dbService.removeProperty,
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['properties'] })
    });

    return {
