                                icon={<PlusCircleIcon className="w-4 h-4" />}
                                title={!canMakePayment ? "Insufficient permissions" : "Post new payment"}
                            >
                                Make Payment
                            </Button>
                            <Button 
                                variant="secondary" 
                                size="sm" 
                                disabled={!isCEO}
                                onClick={() => setActivePage('Amendment Form', selectedClient)}
                                icon={<ShieldCheckIcon className="w-4 h-4" />}
                            >
                                Authorize Amendment
