            </DetailSection>

            <DetailSection title="Office Use" icon={<BriefcaseIcon className="w-5 h-5 text-blue-600 dark:text-blue-400" />}>
                    <InfoField label="Sales Representative" value={client.officeUse.salesRep} />
                    <InfoField label="Sales Manager" value={client.officeUse.salesManager} />
                    <InfoField label="Accounts Head" value={client.officeUse.accountsHead} />
                    <InfoField label="Clerk" value={client.officeUse.clerk} />
            </DetailSection>
            </div>
            <div className="lg:col-span-1 space-y-6">
            <PaymentSummary payment={client.payment} />
            <InteractionHistory interactions={client.interactions} />
            </div>
        </div>
      )}

      {activeTab === 'financials' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
              <AccountManagementPage 
                  clients={[client]}
                  onSaveClient={saveClient}
                  invoices={invoices}
                  onSaveInvoice={saveInvoice}
                  clientForInvoice={null}
                  setClientForInvoice={() => {}}
                  receiptPattern={null}
                  setReceiptPattern={() => {}}
                  setReceiptAlerts={() => {}}
                  currentStaff={currentStaff}
                  roles={roles}
                  setActivePage={setActivePage}
                  overrideClientId={client.id}
                  isEmbedded={true}
              />
          </div>
      )}

      <DocumentPickupModal 
        isOpen={isPickupModalOpen}
        onClose={() => setIsPickupModalOpen(false)}
        onConfirm={handleDocumentPickup}
        clientName={client.name}
        clientId={client.id}
      />
    </div>
  );
};

