import React, { useState, useMemo, useEffect } from 'react';
import { Client, MilestoneRecord } from '../types';
import { ArrowLeftIcon, FolderIcon, UserCheckIcon, CheckCircleIcon, ClockIcon, InformationCircleIcon } from '../components/icons/DummyIcons';
import { Select } from '../components/ui/Input';
import { Card } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';
import { useMilestones } from '../hooks/useAppData';

const MILESTONE_DEFINITIONS = [
    { code: 'SFR', label: 'Submitted Form Received', desc: 'Initial registration form logged in system.', icon: <FolderIcon className="w-5 h-5" /> },
    { code: 'PLR', label: 'Payment for Land Received', desc: 'Full cost of plot(s) settled by client.', icon: <CheckCircleIcon className="w-5 h-5" /> },
    { code: 'PFI', label: 'Payment For Indenture', desc: 'Indenture processing fees paid.', icon: <InformationCircleIcon className="w-5 h-5" /> },
    { code: '3MP', label: '3 Months Processing', desc: 'Standard turnaround time for legal docs.', icon: <ClockIcon className="w-5 h-5" /> },
    { code: 'IR', label: 'Indenture Ready', desc: 'Documents signed and ready for pick-up.', icon: <UserCheckIcon className="w-5 h-5" /> },
    { code: 'DPU', label: 'Picked-Up For Signing', desc: 'Client collected docs to execute physically.', icon: <FolderIcon className="w-5 h-5" /> },
    { code: 'CPD', label: 'Final Document Pickup', desc: 'Handover of finalized title documents.', icon: <CheckCircleIcon className="w-5 h-5" /> },
    { code: 'ACA', label: 'Address Assigned', desc: 'Digital coordinates and physical address set.', icon: <UserCheckIcon className="w-5 h-5" /> },
];

interface ClientDocumentationPageProps {
    onBack: () => void;
    clients: Client[];
    onSaveClient: (client: Client) => Promise<Client>;
}

const ClientDocumentationPage: React.FC<ClientDocumentationPageProps> = ({ onBack, clients }) => {
    const [selectedClientId, setSelectedClientId] = useState<number | ''>('');
    const { milestones, saveMilestone } = useMilestones(selectedClientId ? Number(selectedClientId) : undefined);

    const selectedClient = useMemo(() => 
        clients.find(c => c.id === Number(selectedClientId))
    , [clients, selectedClientId]);

    // Handle 3MP and IR automatic generation logic when viewing
    useEffect(() => {
        const autoTrigger = async () => {
            if (!selectedClient) return;
            const pfi = milestones.find(m => m.milestoneCode === 'PFI');
            if (pfi) {
                const pfiDate = new Date(pfi.dateCompleted);
                const threeMonthsLater = new Date(pfiDate);
                threeMonthsLater.setMonth(threeMonthsLater.getMonth() + 3);

                const now = new Date();

                // If 3 months passed since PFI, log 3MP and IR
                if (now >= threeMonthsLater) {
                    if (!milestones.some(m => m.milestoneCode === '3MP')) {
                        await saveMilestone({
                            clientId: selectedClient.id,
                            milestoneCode: '3MP',
                            dateCompleted: threeMonthsLater.toISOString().split('T')[0],
                            notes: 'System auto-generated milestone.'
                        });
                    }
                    if (!milestones.some(m => m.milestoneCode === 'IR')) {
                        await saveMilestone({
                            clientId: selectedClient.id,
                            milestoneCode: 'IR',
                            dateCompleted: now.toISOString().split('T')[0],
                            notes: 'Processing period completed.'
                        });
                    }
                }
            }
        };
        autoTrigger();
    }, [selectedClient, milestones, saveMilestone]);

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div>
                <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-2 transition-colors">
                    <ArrowLeftIcon className="w-5 h-5" /> Back to Administration
                </button>
                <div className="flex items-center gap-4">
                    <FolderIcon className="w-10 h-10 text-orange-600 dark:text-orange-400" />
                    <div>
                        <h1 className="text-3xl font-black text-gray-900 dark:text-white tracking-tight uppercase">Milestone Progress Tracker</h1>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">Unified documentation lifecycle and fulfillment audit.</p>
                    </div>
                </div>
            </div>

            <Card className="p-4 bg-gray-50 dark:bg-gray-900/50 border-dashed border-2">
                <Select 
                    label="Select Client Dossier" 
                    value={selectedClientId} 
                    onChange={e => setSelectedClientId(e.target.value)}
                >
                    <option value="">-- Choose a client to view progress --</option>
                    {clients.map(c => <option key={c.id} value={c.id}>{c.name} ({c.plot})</option>)}
                </Select>
            </Card>

            {selectedClient ? (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
                    <Card title="Timeline Overview" className="lg:col-span-2 p-0 overflow-hidden">
                        <div className="p-8 space-y-0 relative">
                            {/* Vertical Line */}
                            <div className="absolute left-[3.25rem] top-10 bottom-10 w-0.5 bg-gray-200 dark:bg-gray-700"></div>

                            {MILESTONE_DEFINITIONS.map((def, idx) => {
                                const record = milestones.find(m => m.milestoneCode === def.code);
                                const isCompleted = !!record;

                                return (
                                    <div key={def.code} className={`flex items-start gap-6 pb-12 last:pb-0 relative z-10 transition-opacity ${isCompleted ? 'opacity-100' : 'opacity-40'}`}>
                                        <div className={`w-12 h-12 rounded-full flex items-center justify-center border-4 ${isCompleted ? 'bg-green-600 border-green-100 dark:border-green-900/30 text-white' : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 text-gray-400 shadow-inner'}`}>
                                            {def.icon}
                                        </div>
                                        <div className="flex-grow pt-1">
                                            <div className="flex justify-between items-start">
                                                <h3 className={`font-black text-lg uppercase tracking-tight ${isCompleted ? 'text-gray-900 dark:text-white' : 'text-gray-400'}`}>
                                                    {def.label}
                                                </h3>
                                                {isCompleted ? (
                                                    <Badge variant="success" className="font-bold">{record.dateCompleted}</Badge>
                                                ) : (
                                                    <Badge variant="neutral">Pending</Badge>
                                                )}
                                            </div>
                                            <p className="text-sm text-gray-500 mt-1">{def.desc}</p>
                                            {record?.notes && (
                                                <p className="text-xs italic text-blue-600 dark:text-blue-400 mt-2 p-2 bg-blue-50 dark:bg-blue-900/10 rounded-lg border border-blue-100 dark:border-blue-900/30">
                                                    Note: {record.notes}
                                                </p>
                                            )}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </Card>

                    <div className="space-y-6">
                        <Card title="Dossier Health">
                             <div className="text-center space-y-4">
                                <div className="inline-flex items-center justify-center w-24 h-24 rounded-full border-8 border-green-100 dark:border-green-900/30 bg-green-50 dark:bg-green-900/10">
                                    <span className="text-2xl font-black text-green-600">
                                        {Math.round((milestones.length / MILESTONE_DEFINITIONS.length) * 100)}%
                                    </span>
                                </div>
                                <p className="text-sm text-gray-600 dark:text-gray-400 font-medium">Lifecycle Completion</p>
                                <div className="pt-4 border-t border-gray-100 dark:border-gray-800 text-left space-y-2">
                                    <div className="flex justify-between text-xs">
                                        <span className="text-gray-400 uppercase font-black">Registered</span>
                                        <span className="font-bold">{selectedClient.regDate}</span>
                                    </div>
                                    <div className="flex justify-between text-xs">
                                        <span className="text-gray-400 uppercase font-black">Current Node</span>
                                        <Badge variant="info">{(milestones[milestones.length-1]?.milestoneCode) || 'None'}</Badge>
                                    </div>
                                </div>
                             </div>
                        </Card>

                        <Card title="Quick Audit Action">
                             <p className="text-xs text-gray-500 leading-relaxed mb-4">Milestones are automatically triggered by system events. Use this page to verify compliance with the 3-month legal turnaround period.</p>
                             <Button variant="secondary" className="w-full text-[10px] font-black uppercase tracking-widest" onClick={() => window.print()}>Export Fulfillment Report</Button>
                        </Card>
                    </div>
                </div>
            ) : (
                <div className="py-32 text-center bg-white dark:bg-gray-800 rounded-2xl border-2 border-dashed border-gray-100 dark:border-gray-800 opacity-50">
                    <InformationCircleIcon className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                    <p className="text-lg font-black text-gray-400 uppercase tracking-widest">Select a client account above to begin audit</p>
                </div>
            )}
        </div>
    );
};

