import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { 
    ChevronDownIcon, 
    DocumentPlusIcon, 
    MagnifyingGlassIcon, 
    UploadIcon 
} from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import ClientListItem from '../components/ClientListItem';
import { Client, Milestone, Property, Invoice, ActivityLog } from '../types';
import ClientForm, { FormData } from '../components/ClientForm';
import CSVImportWizard from '../components/CSVImportWizard';
import DeleteConfirmationModal from '../components/DeleteConfirmationModal';
import { VariableSizeList as List } from 'react-window';
import AutoSizer from 'react-virtualized-auto-sizer';
import { useClients } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';

interface ClientsPageProps {
    onClientSelect: (client: Client) => void;
    clients?: Client[]; 
    onSaveClient: (client: Client) => Promise<Client>;
    onDeleteClient: (clientId: number) => Promise<void>;
    properties: Property[];
    milestones: Milestone[];
    setActivePage: (page: string, context?: any) => void;
    setClientForInvoice: (client: Client) => void;
    invoices: Invoice[];
    addActivityLog: (type: ActivityLog['type'], description: string) => void;
}

// Logic to determine if a record is complete based on strictly required app fields
const checkCompleteness = (data: any): boolean => {
    const criticalFields = ['surname', 'otherNames', 'telephone', 'location'];
    return criticalFields.every(f => data[f] && String(data[f]).trim() !== '');
};

const ClientsPage: React.FC<ClientsPageProps> = ({ onClientSelect, onSaveClient, onDeleteClient, properties, milestones, setActivePage, setClientForInvoice, invoices, addActivityLog }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
    const { clients, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } = useClients(debouncedSearchTerm);

    const [isClientFormOpen, setClientFormOpen] = useState(false);
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [isImportWizardOpen, setImportWizardOpen] = useState(false);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);

    const listRef = useRef<List>(null);
    const [expandedIds, setExpandedIds] = useState<Record<number, boolean>>({});
    const [scrollOffset, setScrollOffset] = useState(0);

    useEffect(() => {
        const handler = setTimeout(() => { setDebouncedSearchTerm(searchTerm); }, 500);
        return () => clearTimeout(handler);
    }, [searchTerm]);

    const handleImportData = async (importedList: any[]) => {
        const currentMaxId = clients.length > 0 ? Math.max(...clients.map(c => c.id)) : 0;

        const preparedClients = importedList.map((raw, index) => {
            const isComplete = checkCompleteness(raw);
            const fullName = `${raw.surname || ''} ${raw.otherNames || ''}`.trim();
            const initials = ((raw.surname?.[0] || '') + (raw.otherNames?.[0] || '')).toUpperCase();

            return {
                id: currentMaxId + index + 1,
                name: fullName || 'Imported Client',
                surname: raw.surname || '',
                otherNames: raw.otherNames || '',
                initials: initials || 'IC',
                regDate: raw.regDate || new Date().toISOString().split('T')[0],
                email: raw.email || '',
                phone: raw.telephone || '',
                location: raw.location || 'N/A',
                plot: raw.plotNumber || 'N/A',
                status: 'Active Client' as const,
                stage: milestones[0]?.acronym || 'REG',
                payment: { total: 0, paid: 0, balance: 0, dueDate: 'N/A', planType: 'N/A', paymentHistory: [], installments: [] },
                interactions: [{ id: 1, type: 'Note', date: new Date().toISOString(), agent: 'System', notes: 'Record created via Bulk Import.' }],
                witness: { name: '', address: '', phone: '' },
                nextOfKin: { name: '', phone: '', relationship: '' },
                indenture: { name: fullName, address: '' },
                officeUse: { salesRep: '', salesManager: '', accountsHead: '', clerk: '', commission: { type: 'Percentage', amount: 0, status: 'Pending' } },
                documentation: { status: 'Pending' },
                isComplete: isComplete,
                filledFormPdf: null,
            } as Client;
        });

        // Use standard save logic
        await Promise.all(preparedClients.map(c => onSaveClient(c)));
        addActivityLog('Import', `Successfully imported ${preparedClients.length} clients.`);
        setImportWizardOpen(false);
    };

    const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => {
        const client = clients[index];
        if (!client) return null;
        return (
            <ClientListItem 
                key={client.id} 
                client={client} 
                onViewDetails={onClientSelect} 
                onEdit={(c) => { setEditingClient(c); setClientFormOpen(true); }} 
                onDelete={(id) => setClientToDelete(clients.find(c => c.id === id) || null)} 
                milestones={milestones}
                style={style}
                isExpanded={!!expandedIds[client.id]}
                onToggleExpand={() => {
                    setExpandedIds(prev => ({ ...prev, [client.id]: !prev[client.id] }));
                    if (listRef.current) listRef.current.resetAfterIndex(index);
                }}
            />
        );
    };

    return (
        <div className="flex flex-col h-[calc(100vh-100px)] overflow-hidden">
            <div className="bg-gray-100 dark:bg-gray-950 z-20 flex-shrink-0 p-1">
                <div className="flex flex-wrap items-center justify-between gap-4">
                    <h1 className="text-3xl font-black text-gray-900 dark:text-white uppercase tracking-tight">
                        Clients ({clients.length})
                    </h1>
                    <div className="flex items-center gap-3">
                        <button onClick={() => setImportWizardOpen(true)} className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-bold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-700 hover:bg-gray-50 flex items-center gap-2 text-sm shadow-sm">
                            <UploadIcon className="w-4 h-4" /> Bulk Import
                        </button>
                        <button onClick={() => { setEditingClient(null); setClientFormOpen(true); }} className="bg-blue-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2 text-sm shadow-md">
                            <DocumentPlusIcon className="w-4 h-4" /> New Client
                        </button>
                    </div>
                </div>

                <div className="mt-4 bg-white dark:bg-gray-800 p-3 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                    <div className="relative">
                        <div className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400">
                            {isLoading ? <LoaderIcon className="animate-spin" /> : <MagnifyingGlassIcon />}
                        </div>
                        <input
                            type="text"
                            placeholder="Search clients..."
                            className="bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg pl-9 pr-4 py-2 w-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm dark:text-white"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                </div>
            </div>

            <div className="flex-grow relative mt-1">
                <AutoSizer>
                    {({ height, width }) => (
                        <List
                            ref={listRef}
                            height={height}
                            itemCount={clients.length}
                            itemSize={(idx) => expandedIds[clients[idx]?.id] ? 140 : 100}
                            width={width}
                            className="scrollbar-thin"
                        >
                            {Row}
                        </List>
                    )}
                </AutoSizer>
            </div>

            <CSVImportWizard
                isOpen={isImportWizardOpen}
                onClose={() => setImportWizardOpen(false)}
                onImport={handleImportData}
                requiredHeaders={['surname', 'otherNames', 'telephone', 'location']}
                sampleHeaders="Surname,Other Names,Telephone,Email,Location,Plot Number"
                sampleData="Doe,John,0241234567,john@doe.com,East Legon Hills,P-101"
                wizardTitle="Import Bulk Client Data"
            />

            <DeleteConfirmationModal
                isOpen={!!clientToDelete}
                onClose={() => setClientToDelete(null)}
                onConfirm={async () => { if(clientToDelete) { await onDeleteClient(clientToDelete.id); setClientToDelete(null); } }}
                itemName={clientToDelete?.name || ''}
            />

            <ClientForm isOpen={isClientFormOpen} onClose={() => setClientFormOpen(false)} properties={properties} editingClient={editingClient} clients={clients} onSave={async (f) => { await onSaveClient(f as any); setClientFormOpen(false); }} onSaveAndPay={() => {}} />
        </div>
    );
};

