import React, { useState, useCallback, ChangeEvent } from 'react';
import { XIcon } from './icons/XIcon';
import { UploadIcon, DocumentTextIcon, ExclamationTriangleIcon, CheckCircleIcon, ChevronLeftIcon, ChevronRightIcon, InformationCircleIcon } from './icons/DummyIcons';
// FIX: Added Button import
import { Button } from './ui/Button';

interface CSVImportWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (data: any[]) => void;
  requiredHeaders: string[]; // These are "Target" fields in our app
  sampleHeaders: string;
  sampleData: string;
  wizardTitle: string;
}

// Logic: Map varied Excel headers to internal App keys
const FUZZY_MAP: Record<string, string[]> = {
    surname: ['surname', 'last name', 'lastname', 'family name'],
    otherNames: ['other names', 'first name', 'firstname', 'given name', 'middle name'],
    telephone: ['telephone', 'phone', 'phone no', 'phone number', 'contact', 'mobile', 'tel'],
    email: ['email', 'email address', 'mail'],
    currentAddress: ['current address', 'address', 'residential address', 'location'],
    location: ['property location', 'site', 'project'],
    plotNumber: ['plot', 'plot number', 'plot no', 'unit'],
    regDate: ['date', 'registration date', 'reg date', 'payment date'],
};

const CSVImportWizard: React.FC<CSVImportWizardProps> = ({ isOpen, onClose, onImport, requiredHeaders, sampleHeaders, sampleData, wizardTitle }) => {
    const [step, setStep] = useState(1);
    const [file, setFile] = useState<File | null>(null);
    const [parsedData, setParsedData] = useState<any[]>([]);
    const [validationResults, setValidationResults] = useState<{ data: any; status: 'Complete' | 'Partial' | 'Empty'; missing: string[] }[]>([]);
    const [errors, setErrors] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const resetWizard = useCallback(() => {
        setStep(1);
        setFile(null);
        setParsedData([]);
        setValidationResults([]);
        setErrors([]);
        setIsLoading(false);
    }, []);

    const handleClose = useCallback(() => {
        resetWizard();
        onClose();
    }, [resetWizard, onClose]);

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const selectedFile = e.target.files[0];
            setFile(selectedFile);
            setErrors([]);
        }
    };

    const parseCSVLine = (text: string) => {
        const result = [];
        let cell = '';
        let inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (char === '"') {
                if (inQuotes && text[i + 1] === '"') { cell += '"'; i++; } 
                else { inQuotes = !inQuotes; }
            } else if (char === ',' && !inQuotes) { result.push(cell.trim()); cell = ''; } 
            else { cell += char; }
        }
        result.push(cell.trim());
        return result;
    };

    const processFile = useCallback(() => {
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
                if (lines.length < 2) {
                    setErrors(['File is empty or missing data rows.']);
                    setIsLoading(false);
                    return;
                }

                // 1. Intelligent Header Mapping
                const rawHeaders = parseCSVLine(lines[0].replace(/^\uFEFF/, '')).map(h => h.toLowerCase());
                const headerMap: Record<string, number> = {};

                Object.entries(FUZZY_MAP).forEach(([appKey, aliases]) => {
                    const foundIndex = rawHeaders.findIndex(rh => aliases.includes(rh) || rh.includes(appKey.toLowerCase()));
                    if (foundIndex !== -1) headerMap[appKey] = foundIndex;
                });

                // 2. Data Extraction with Lax Validation
                const results = [];
                for (let i = 1; i < lines.length; i++) {
                    const values = parseCSVLine(lines[i]);
                    const rowData: any = {};

                    // Populate based on map
                    Object.keys(FUZZY_MAP).forEach(key => {
                        const idx = headerMap[key];
                        rowData[key] = idx !== undefined ? values[idx] : '';
                    });

                    // Check if row is identifiable (at least a name or phone)
                    const isIdentifiable = rowData.surname || rowData.otherNames || rowData.telephone;
                    if (!isIdentifiable) continue;

                    // Identify missing fields for the "Partial" flag
                    const missingFields = requiredHeaders.filter(rh => !rowData[rh] || rowData[rh].trim() === '');

                    results.push({
                        data: rowData,
                        status: (missingFields.length === 0 ? 'Complete' : 'Partial') as 'Complete' | 'Partial',
                        missing: missingFields
                    });
                }

                setValidationResults(results);
                setParsedData(results.map(r => r.data));
                setStep(3);
            } catch (err) {
                setErrors(['Parsing failed. Check file format.']);
            } finally {
                setIsLoading(false);
            }
        };
        reader.readAsText(file);
    }, [file, requiredHeaders]);

    return (
        <div className="fixed inset-0 bg-slate-900/70 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">{wizardTitle}</h2>
                    <button onClick={handleClose} className="text-gray-400 hover:text-gray-600"><XIcon className="w-6 h-6" /></button>
                </div>

                <div className="p-6 overflow-y-auto flex-grow bg-gray-50 dark:bg-gray-900">
                   {step === 1 && (
                        <div className="space-y-4">
                            <h3 className="text-lg font-semibold">Bulk Import Instructions</h3>
                            <p className="text-sm text-gray-600 dark:text-gray-400">
                                You can upload any Excel/CSV export. The system will automatically attempt to match your columns (e.g. "Phone" to "Telephone").
                            </p>
                            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 rounded-lg text-sm text-blue-800 dark:text-blue-300">
                                <strong>Logic Rules:</strong>
                                <ul className="list-disc ml-5 mt-2 space-y-1">
                                    <li>Rows with missing data <strong>will be accepted</strong>.</li>
                                    <li>Identified records with missing fields will be marked as <strong>"Incomplete"</strong>.</li>
                                    <li>You can manually complete these records in the Client Dossier later.</li>
                                </ul>
                            </div>
                            <Button onClick={() => setStep(2)}>I Understand, Proceed</Button>
                        </div>
                   )}

                   {step === 2 && (
                       <div className="text-center py-10">
                            <div className="max-w-xs mx-auto border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-10">
                                <UploadIcon className="w-12 h-12 mx-auto text-gray-400 mb-4" />
                                <input type="file" id="file-up" className="hidden" onChange={handleFileChange} accept=".csv" />
                                <label htmlFor="file-up" className="cursor-pointer text-blue-600 font-bold hover:underline">
                                    {file ? file.name : "Select CSV File"}
                                </label>
                            </div>
                            {file && <Button className="mt-6" onClick={processFile} isLoading={isLoading}>Analyze Data</Button>}
                       </div>
                   )}

                   {step === 3 && (
                        <div className="space-y-4">
                            <div className="flex justify-between items-center">
                                <h3 className="font-bold">Preview: {parsedData.length} records found</h3>
                                <div className="flex gap-4">
                                    <span className="flex items-center gap-1 text-xs font-bold text-green-600"><CheckCircleIcon className="w-4 h-4"/> Ready</span>
                                    <span className="flex items-center gap-1 text-xs font-bold text-amber-500"><InformationCircleIcon className="w-4 h-4"/> Partial</span>
                                </div>
                            </div>
                            <div className="border rounded-lg overflow-hidden max-h-80 overflow-y-auto">
                                <table className="w-full text-xs text-left">
                                    <thead className="bg-gray-100 dark:bg-gray-700 sticky top-0">
                                        <tr>
                                            <th className="p-2">Status</th>
                                            <th className="p-2">Name</th>
                                            <th className="p-2">Phone</th>
                                            <th className="p-2">Details</th>
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white dark:bg-gray-800 divide-y dark:divide-gray-700">
                                        {validationResults.map((res, i) => (
                                            <tr key={i}>
                                                <td className="p-2">
                                                    {res.status === 'Complete' ? 
                                                        <span className="text-green-500 font-bold">Ready</span> : 
                                                        <span className="text-amber-500 font-bold">Partial</span>
                                                    }
                                                </td>
                                                <td className="p-2">{res.data.surname} {res.data.otherNames}</td>
                                                <td className="p-2">{res.data.telephone}</td>
                                                <td className="p-2 text-gray-400">
                                                    {res.missing.length > 0 ? `Missing: ${res.missing.join(', ')}` : 'Full Data'}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                            <div className="flex justify-end gap-3 mt-6">
                                <Button variant="secondary" onClick={() => setStep(2)}>Change File</Button>
                                <Button onClick={() => onImport(parsedData)}>Import All Records</Button>
