// @ts-ignore
import { createUserWithEmailAndPassword, signOut } from "firebase/auth";
import { secondaryAuth, auth } from "./firebase";

/**
 * Registers a new user in Firebase Authentication using a secondary app instance.
 * This ensures the current admin user is not signed out when creating a new account.
 * 
 * @param email - The email for the new user
 * @param password - The password for the new user
 * @returns Object containing the created User and a signOut function for the secondary instance
 */
export const registerUser = async (email: string, password: string) => {
    try {
        const normalizedEmail = email.trim().toLowerCase();
        const userCredential = await createUserWithEmailAndPassword(secondaryAuth, normalizedEmail, password);

        // Immediately sign out from the secondary instance to prevent session persistence
        const cleanup = () => signOut(secondaryAuth);

        return {
            user: userCredential.user,
            cleanup
        };
    } catch (error: any) {
        console.error("Error registering user in Firebase Auth:", error);
        throw error;
    }
};

