                                                    <td className="py-3 font-semibold text-gray-700 dark:text-gray-200">{module.name}</td>
                                                    {['view', 'create', 'edit', 'delete', 'approve'].map((key) => (
                                                        <td key={key} className="text-center py-2">
                                                            <input type="checkbox" className="form-checkbox h-4 w-4 rounded text-blue-600 bg-gray-100 border-gray-300 focus:ring-blue-500"
                                                                checked={permissions[key as keyof typeof permissions]}
                                                                onChange={(e) => handlePermissionChange(module.id as AppModuleName, key, e.target.checked)} />
                                                        </td>
                                                    ))}
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        ) : (
                            <div className="text-center py-20 text-gray-400">Select a role to manage access.</div>
                        )}
                    </div>
                </div>
            )}

            {activeTab === 'staff' && canManageStaff && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="font-bold text-xl text-gray-800 dark:text-white">Staff Directory</h2>
                        <button onClick={() => {setEditingStaff(null); setStaffModalOpen(true);}} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2">
                            <PlusCircleIcon className="w-5 h-5" /> New Account
                        </button>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-50 dark:bg-gray-900 text-gray-500">
                                <tr><th className="px-4 py-3">Member</th><th className="px-4 py-3">Department</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Actions</th></tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                {staff.map(member => (
                                    <tr key={member.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30">
                                        <td className="px-4 py-3 flex items-center gap-3">
                                            {member.photo ? <img src={member.photo} className="w-8 h-8 rounded-full object-cover"/> : <div className="w-8 h-8 rounded-full bg-gray-200 dark:bg-gray-600 flex items-center justify-center font-bold text-xs">{member.initials}</div>}
                                            <div>
                                                <div className="font-bold text-gray-900 dark:text-white">{member.fullName}</div>
                                                <div className="text-xs text-gray-500">{member.email}</div>
                                            </div>
                                        </td>
                                        <td className="px-4 py-3"><RolePill role={roles.find(r => r.id === member.roleId)!} /></td>
                                        <td className="px-4 py-3"><span className={`px-2 py-0.5 text-xs font-bold rounded-full ${member.status === 'Active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{member.status}</span></td>
                                        <td className="px-4 py-3 text-right">
                                            <div className="flex justify-end gap-1">
                                                <button onClick={() => onViewStaffActivity(member)} className="p-1.5 text-gray-400 hover:text-blue-600"><EyeIcon className="w-5 h-5"/></button>
                                                <button onClick={() => { setEditingStaff(member); setStaffModalOpen(true); }} className="p-1.5 text-gray-400 hover:text-indigo-600"><PencilIcon className="w-5 h-5"/></button>
                                                <button onClick={() => handleDeleteClick(member)} className="p-1.5 text-gray-400 hover:text-red-600"><TrashIcon className="w-5 h-5"/></button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            <UserFormModal 
                isOpen={isStaffModalOpen}
                onClose={() => { setStaffModalOpen(false); setEditingStaff(null); }}
                onSave={handleSaveStaff}
                editingUser={editingStaff}
                roles={roles}
            />

            {staffToDelete && (
                <div className="fixed inset-0 bg-black/60 z-[60] flex justify-center items-center p-4">
                    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-sm w-full p-6 border border-gray-200 dark:border-gray-700">
                        <div className="flex items-center justify-center w-12 h-12 mx-auto bg-red-100 rounded-full mb-4">
                            <TrashIcon className="w-6 h-6 text-red-600" />
                        </div>
                        <h3 className="text-lg font-bold text-center text-gray-900 dark:text-white mb-2">Delete Account?</h3>
                        <p className="text-center text-sm text-gray-500 mb-6">Are you sure you want to remove <strong>{staffToDelete.fullName}</strong>? Access will be revoked immediately.</p>
                        <div className="flex justify-center gap-3">
                            <button onClick={() => setStaffToDelete(null)} className="px-4 py-2 bg-gray-100 rounded-lg text-sm font-bold">Cancel</button>
                            <button onClick={confirmDeleteStaff} className="px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-bold">Delete</button>
                        </div>
                    </div>
                </div>
            )}

            {isRoleModalOpen && (
                <div className="fixed inset-0 bg-black/60 z-50 flex justify-center items-center p-4">
                    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md">
                        <form onSubmit={handleSaveRole}>
                            <div className="flex justify-between items-center p-4 border-b border-gray-200 dark:border-gray-700"><h3 className="text-lg font-bold dark:text-white">{editingRole ? 'Edit Role' : 'Create Role'}</h3></div>
                            <div className="p-6 space-y-4">
                                <div><label className="text-sm font-bold text-gray-500 uppercase">Role Name</label><input type="text" value={newRoleData.name} onChange={e => setNewRoleData({...newRoleData, name: e.target.value})} className="w-full mt-1 p-2 border rounded dark:bg-gray-900 dark:border-gray-700 dark:text-white" required /></div>
                                <div><label className="text-sm font-bold text-gray-500 uppercase">Description</label><textarea value={newRoleData.description} onChange={e => setNewRoleData({...newRoleData, description: e.target.value})} className="w-full mt-1 p-2 border rounded dark:bg-gray-900 dark:border-gray-700 dark:text-white" required /></div>
                            </div>
                            <div className="p-4 bg-gray-50 dark:bg-gray-900 flex justify-end gap-2 rounded-b-lg"><button type="button" onClick={() => setRoleModalOpen(false)} className="px-4 py-2 text-sm font-bold">Cancel</button><button type="submit" className="bg-blue-600 text-white py-2 px-4 rounded font-bold text-sm">Save</button></div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React, { useState, useMemo, ChangeEvent } from 'react';
import { Staff, Role, AppModuleName, CompanySettings } from '../types';
import { APP_MODULES } from '../data/mockData';
import { ShieldCheckIcon, UsersIcon, PlusCircleIcon, PencilIcon, TrashIcon, EyeIcon, UserCircleIcon, BuildingLibraryIcon, UploadIcon } from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import UserFormModal from '../components/UserFormModal';
import { PhoneInput } from '../components/ui/PhoneInput';
import { EmailInput } from '../components/ui/EmailInput';
import { usePermissions } from '../context/DataContext';
import { useStaff, useRoles, useCompanySettings } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';
import { useAuth } from '../context/AuthContext';
import { registerStaffAccount, normalizeEmail } from '../services/authService';

interface SettingsPageProps {
    currentStaff: Staff;
    staff: Staff[];
    roles: Role[];
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    onViewStaffActivity: (staff: Staff) => void;
    companySettings: CompanySettings;
    setCompanySettings: (value: React.SetStateAction<CompanySettings>) => Promise<void>;
    onUpdateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
}

const SettingsPage: React.FC<SettingsPageProps> = ({ currentStaff, staff, roles, setRoles, onViewStaffActivity, companySettings, setCompanySettings, onUpdateStaff }) => {
    const { deleteStaff } = useStaff();
    const { rolePermissions, updateRolePermission, initRolePermissions } = usePermissions();
    const { updateCurrentUser } = useAuth();

    const [activeTab, setActiveTab] = useState('profile');
    const [selectedRole, setSelectedRole] = useState<Role | null>(roles[0] || null);

    const [isStaffModalOpen, setStaffModalOpen] = useState(false);
    const [isRoleModalOpen, setRoleModalOpen] = useState(false);
    const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
    const [editingRole, setEditingRole] = useState<Role | null>(null);
    const [newRoleData, setNewRoleData] = useState({ name: '', description: '' });

    const [staffToDelete, setStaffToDelete] = useState<Staff | null>(null);
    const [isSavingStaff, setIsSavingStaff] = useState(false);

    const [profileData, setProfileData] = useState({ fullName: currentStaff.fullName, email: currentStaff.email, phone: currentStaff.phone || '' });
    const [companyData, setCompanyData] = useState({ name: companySettings.name });
    const [profilePhotoPreview, setProfilePhotoPreview] = useState<string | null>(currentStaff.photo || null);

    // FIX: Added missing state for logo previews to resolve compilation errors
    const [appLogoLightPreview, setAppLogoLightPreview] = useState<string | null>(companySettings.appLogoLight || null);
    const [appLogoDarkPreview, setAppLogoDarkPreview] = useState<string | null>(companySettings.appLogoDark || null);

    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'success' | 'error'>('idle');
    const [saveMessage, setSaveMessage] = useState('');

    const [profileSaveStatus, setProfileSaveStatus] = useState<'idle' | 'saving' | 'success' | 'error'>('idle');
    const [profileSaveMessage, setProfileSaveMessage] = useState('');

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff.roleId), [currentStaff, roles]);
    const canManageStaff = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);
    const canManageCompany = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);

    const handleSaveStaff = async (staffData: Partial<Staff>) => {
        setIsSavingStaff(true);
        try {
            if (editingStaff) {
                // Update existing document
                await onUpdateStaff(editingStaff.id, staffData);
            } else {
                // Atomic Auth + DB Creation
                await registerStaffAccount({
                    email: normalizeEmail(staffData.email!),
                    password: staffData.password!,
                    fullName: staffData.fullName!,
                    roleId: staffData.roleId!,
                    phone: staffData.phone
                });
            }
            setStaffModalOpen(false);
            setEditingStaff(null);
        } catch (error: any) {
            alert(`Error: ${error.message || 'System failed to synchronize account.'}`);
        } finally {
            setIsSavingStaff(false);
        }
    }

    // FIX: Implemented handleDeleteClick to resolve compilation error
    const handleDeleteClick = (member: Staff) => {
        setStaffToDelete(member);
    };

    // FIX: Implemented confirmDeleteStaff to resolve compilation error
    const confirmDeleteStaff = async () => {
        if (!staffToDelete) return;
        try {
            await deleteStaff(staffToDelete.id);
            setStaffToDelete(null);
        } catch (error) {
            alert("Failed to delete staff account.");
        }
    };

    const handlePermissionChange = async (moduleId: AppModuleName, permission: string, value: boolean) => {
        if (!selectedRole) return;
        await updateRolePermission(selectedRole.id, moduleId, permission, value);
    };

    const handleSaveRole = async (e: React.FormEvent) => {
        e.preventDefault();
        const roleData = newRoleData;
        if (editingRole) {
            setRoles(prev => prev.map(r => r.id === editingRole.id ? { ...editingRole, ...roleData } : r));
        } else {
            const newRoleId = roleData.name;
            const newRole: Role = { id: newRoleId, ...roleData };
            setRoles(prev => [...prev, newRole]); 
            await initRolePermissions(newRoleId);
        }
        setRoleModalOpen(false);
        setEditingRole(null);
        setNewRoleData({ name: '', description: '' });
    };

    const handleDeleteRole = (roleId: string) => {
        if (window.confirm("Are you sure you want to delete this role?")) {
            if (staff.some(u => u.roleId === roleId)) {
                alert("Cannot delete role. It is assigned to active staff members.");
                return;
            }
            setRoles(prev => prev.filter(r => r.id !== roleId));
        }
    };

    const handleProfileFormChange = (e: ChangeEvent<HTMLInputElement>) => {
        setProfileData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleProfilePhotoChange = async (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            try {
                const url = await uploadFile(file, `staff/${currentStaff.id}/profile/${file.name}`);
                await onUpdateStaff(currentStaff.id, { photo: url });
                updateCurrentUser({ photo: url });
                setProfilePhotoPreview(url); 
            } catch (error) {
                alert("Failed to upload photo.");
            }
        }
    };

    const handleSaveProfile = async () => {
        setProfileSaveStatus('saving');
        try {
            await onUpdateStaff(currentStaff.id, profileData);
            updateCurrentUser(profileData);
            setProfileSaveStatus('success');
            setProfileSaveMessage('Profile updated!');
            setTimeout(() => setProfileSaveStatus('idle'), 3000);
        } catch (error) {
            setProfileSaveStatus('error');
        }
    };

    const handleLogoUpload = async (file: File, type: keyof CompanySettings, previewSetter: React.Dispatch<React.SetStateAction<string | null>>) => {
        try {
            const url = await uploadFile(file, `system/branding/${type}/${file.name}`);
            setCompanySettings(prev => ({ ...prev, [type]: url }));
            const reader = new FileReader();
            reader.onloadend = () => previewSetter(reader.result as string);
            reader.readAsDataURL(file);
        } catch (error) {
            alert(`Failed to upload logo.`);
        }
    };

    const handleSaveCompanySettings = async () => {
        setSaveStatus('saving');
        try {
            await setCompanySettings(prev => ({ ...prev, name: companyData.name }));
            setSaveStatus('success');
            setTimeout(() => setSaveStatus('idle'), 3000);
        } catch (error) {
            setSaveStatus('error');
        }
    };

    const RolePill: React.FC<{ role: Role }> = ({ role }) => {
        return <span className={`px-2 py-1 text-xs font-semibold rounded-full border bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-800`}>{role ? role.name : 'Unknown Role'}</span>
    }

    const tabs = [
        { id: 'profile', name: 'My Profile', icon: <UserCircleIcon className="w-5 h-5" /> },
        { id: 'company', name: 'Company Settings', icon: <BuildingLibraryIcon className="w-5 h-5" />, disabled: !canManageCompany },
        { id: 'roles', name: 'Roles & Permissions', icon: <ShieldCheckIcon className="w-5 h-5" />, disabled: !canManageStaff },
        { id: 'staff', name: 'Staff Accounts', icon: <UsersIcon className="w-5 h-5" />, disabled: !canManageStaff },
    ];

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">System Settings</h1>

            <div className="flex border-b border-gray-200 dark:border-gray-700">
                {tabs.map(tab => !tab.disabled && (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-2 px-4 py-3 font-semibold transition-colors ${activeTab === tab.id ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white'}`}>
                        {tab.icon} {tab.name}
                    </button>
                ))}
            </div>

            {activeTab === 'profile' && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Edit Your Profile</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
                        <div className="md:col-span-1 flex flex-col items-center">
                            {profilePhotoPreview ? (
                                <img src={profilePhotoPreview} alt="Profile" className="w-32 h-32 rounded-full object-cover mb-4 border-4 border-gray-100 dark:border-gray-700" />
                            ) : (
                                <div className="w-32 h-32 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center mb-4"><UserCircleIcon className="w-20 h-20 text-gray-400 dark:text-gray-500" /></div>
                            )}
                            <label htmlFor="photo-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600">
                                Change Photo
                                <input id="photo-upload" name="photo" type="file" className="sr-only" onChange={handleProfilePhotoChange} accept="image/*" />
                            </label>
                        </div>
                        <div className="md:col-span-2 space-y-4">
                            <div>
                                <label className="text-gray-700 dark:text-gray-300">Full Name</label>
                                <input type="text" name="fullName" value={profileData.fullName} onChange={handleProfileFormChange} className="w-full mt-1 p-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded" />
                            </div>
                             <div>
                                <EmailInput label="Email" name="email" value={profileData.email} onChange={(val) => setProfileData(prev => ({...prev, email: val}))} />
                            </div>
                             <div>
                                <PhoneInput label="Phone" name="phone" value={profileData.phone} onChange={(val) => setProfileData(prev => ({...prev, phone: val}))} />
                            </div>
                            <div className="flex justify-end items-center gap-3 mt-4">
                                {profileSaveMessage && <span className="text-sm font-medium text-green-600">{profileSaveMessage}</span>}
                                <button onClick={handleSaveProfile} disabled={profileSaveStatus === 'saving'} className="flex items-center gap-2 bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700">
                                    {profileSaveStatus === 'saving' && <LoaderIcon className="w-4 h-4 animate-spin" />} Save Changes
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'company' && canManageCompany && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Company Profile</h2>
                    <div className="space-y-6">
                        <div>
                            <label className="text-gray-700 dark:text-gray-300 font-semibold">Application Name</label>
                            <input type="text" value={companyData.name} onChange={e => setCompanyData({name: e.target.value})} className="w-full mt-1 p-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded" />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="text-gray-700 dark:text-gray-300 font-semibold">App Logo (Light)</label>
                                <div className="flex items-center gap-4 mt-2">
                                    {appLogoLightPreview && <img src={appLogoLightPreview} className="h-12 w-auto border rounded p-1 bg-gray-50" />}
                                    <label className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border rounded text-sm hover:bg-gray-50 flex items-center gap-2">
                                        <UploadIcon className="w-4 h-4"/> Upload
                                        <input type="file" className="sr-only" onChange={(e) => e.target.files?.[0] && handleLogoUpload(e.target.files[0], 'appLogoLight', setAppLogoLightPreview)} />
                                    </label>
                                </div>
                            </div>
                            <div>
                                <label className="text-gray-700 dark:text-gray-300 font-semibold">App Logo (Dark)</label>
                                <div className="flex items-center gap-4 mt-2">
                                    {appLogoDarkPreview && <img src={appLogoDarkPreview} className="h-12 w-auto border rounded p-1 bg-gray-900" />}
                                    <label className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border rounded text-sm hover:bg-gray-50 flex items-center gap-2">
                                        <UploadIcon className="w-4 h-4"/> Upload
                                        <input type="file" className="sr-only" onChange={(e) => e.target.files?.[0] && handleLogoUpload(e.target.files[0], 'appLogoDark', setAppLogoDarkPreview)} />
                                    </label>
                                </div>
                            </div>
                        </div>
                        <div className="flex justify-end pt-4 gap-3">
                            <button onClick={handleSaveCompanySettings} disabled={saveStatus === 'saving'} className="flex items-center gap-2 bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700">
                                {saveStatus === 'saving' && <LoaderIcon className="w-4 h-4 animate-spin" />} Save Company Settings
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'roles' && canManageStaff && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-1 bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="font-bold text-lg text-gray-800 dark:text-white">Roles</h2>
                            <button onClick={() => { setEditingRole(null); setRoleModalOpen(true); }} className="text-sm font-semibold text-blue-600 hover:text-blue-800 flex items-center gap-1">
                                <PlusCircleIcon className="w-4 h-4" /> New Role
                            </button>
                        </div>
                        <div className="space-y-2">
                            {roles.map(role => (
                                <button key={role.id} onClick={() => setSelectedRole(role)} className={`w-full text-left p-3 rounded-md transition-colors ${selectedRole?.id === role.id ? 'bg-blue-50 dark:bg-blue-900/30' : 'hover:bg-gray-50 dark:hover:bg-gray-700'}`}>
                                    <h3 className="font-semibold text-gray-900 dark:text-white">{role.name}</h3>
                                    <p className="text-xs text-gray-500">{role.description}</p>
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="lg:col-span-2 bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                        {selectedRole ? (
                            <div>
                                <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4 border-b pb-2">{selectedRole.name} Module Access</h2>
                                <table className="w-full text-sm">
                                    <thead>
                                        <tr className="text-left text-gray-400 font-bold uppercase text-[10px] tracking-widest">
                                            <th className="py-2">Module</th><th className="text-center">View</th><th className="text-center">Create</th><th className="text-center">Edit</th><th className="text-center">Delete</th><th className="text-center">Approve</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                        {APP_MODULES.map(module => {
                                            const permissions = rolePermissions.find(rp => rp.roleId === selectedRole.id && rp.moduleId === module.id)?.permissions || { view: false, create: false, edit: false, delete: false, approve: false };
                                            return (
                                                <tr key={module.id}>
                                                    <td className="py-3 font-semibold text-gray-700 dark:text-gray-200">{module.name}</td>
                                                    {['view', 'create', 'edit', 'delete', 'approve'].map((key) => (
                                                        <td key={key} className="text-center py-2">
                                                            <input type="checkbox" className="form-checkbox h-4 w-4 rounded text-blue-600 bg-gray-100 border-gray-300 focus:ring-blue-500"
                                                                checked={permissions[key as keyof typeof permissions]}
                                                                onChange={(e) => handlePermissionChange(module.id as AppModuleName, key, e.target.checked)} />
                                                        </td>
                                                    ))}
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        ) : (
                            <div className="text-center py-20 text-gray-400">Select a role to manage access.</div>
                        )}
                    </div>
                </div>
            )}

            {activeTab === 'staff' && canManageStaff && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="font-bold text-xl text-gray-800 dark:text-white">Staff Directory</h2>
                        <button onClick={() => {setEditingStaff(null); setStaffModalOpen(true);}} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 flex items-center gap-2">
                            <PlusCircleIcon className="w-5 h-5" /> New Account
                        </button>
