/**
 * Sanitizes data for Firestore by removing undefined values and handling potential circular references.
 * Firestore does not allow circular references or undefined values.
 */
const sanitizeData = <T>(data: T, seen = new WeakSet()): T => {
    // Handle primitives and null
    if (data === null || typeof data !== 'object') return data;

    // Prevent circular references
    if (seen.has(data as object)) {
        console.warn("Circular reference detected and removed during sanitization");
        return null as any; 
    }

    // Add to seen set before recursing
    seen.add(data as object);

    // Handle Dates
    if (data instanceof Date) return data.toISOString() as any;

    // Handle Arrays
    if (Array.isArray(data)) {
        return data.map(item => sanitizeData(item, seen)) as any;
    }

    // Handle Objects
    const sanitizedObj: any = {};
    for (const [key, value] of Object.entries(data)) {
        // Skip undefined values as Firestore throws on them
        if (value === undefined) continue;

        // Skip functions
        if (typeof value === 'function') continue;

        const sanitizedValue = sanitizeData(value, seen);
        sanitizedObj[key] = sanitizedValue;
    }
    return sanitizedObj as T;
};

const fetchCollection = async <T>(colName: string): Promise<T[]> => {
    try {
        const snapshot = await getDocs(collection(db, colName));
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as T));
    } catch (error) {
        console.error(`Error fetching ${colName}:`, error);
        return [];
    }
};

