// --- Seeding ---
export const seedDatabase = async () => {
    const batch = writeBatch(db);

    const propertiesSnap = await getDocs(collection(db, PROPERTIES_COL));
    const shouldSeedData = propertiesSnap.empty;

    if (shouldSeedData) {
        PROPERTIES.forEach(p => batch.set(doc(db, PROPERTIES_COL, String(p.id)), sanitizeData(p)));
        INVOICES.forEach(i => batch.set(doc(db, INVOICES_COL, String(i.id)), sanitizeData(i)));
        PROMOTIONS.forEach(p => batch.set(doc(db, PROMOTIONS_COL, String(p.id)), sanitizeData(p)));
        ROLES.forEach(r => batch.set(doc(db, ROLES_COL, String(r.id)), sanitizeData(r)));
        AMENDMENT_REQUESTS.forEach(a => batch.set(doc(db, AMENDMENTS_COL, String(a.id)), sanitizeData(a)));
        batch.set(doc(db, SETTINGS_COL, 'main'), sanitizeData(COMPANY_SETTINGS));
    }

    const ceoPermissionsRef = doc(db, PERMISSIONS_COL, 'CEO');
    try {
        const ceoPermissionsSnap = await getDoc(ceoPermissionsRef);
        const shouldSeedPermissions = !ceoPermissionsSnap.exists();

        if (shouldSeedPermissions) {
            const permissionsByRole: Record<string, any> = {};
            ROLE_PERMISSIONS.forEach(rp => {
                if (!permissionsByRole[rp.roleId]) permissionsByRole[rp.roleId] = {};
                permissionsByRole[rp.roleId][rp.moduleId] = rp.permissions;
            });

            Object.entries(permissionsByRole).forEach(([roleId, modules]) => {
                batch.set(doc(db, PERMISSIONS_COL, roleId), { modules });
            });
        }

        if (shouldSeedData || shouldSeedPermissions) {
            await batch.commit();
        }
    } catch (e) {
        console.error("Seeding check failed:", e);
    }
};

// @ts-ignore
import { createUserWithEmailAndPassword, deleteUser, signOut, signInWithEmailAndPassword } from "firebase/auth";
import { doc, setDoc, serverTimestamp } from "firebase/firestore";
import { secondaryAuth, db, auth } from "./firebase";

/**
 * Normalizes email strings to prevent login mismatches (trailing spaces, casing)
 */
export const normalizeEmail = (email: string) => email.trim().toLowerCase();

/**
 * Authenticates a user with the primary Firebase instance.
 */
export const loginWithEmail = async (email: string, password: string) => {
    try {
        const normalized = normalizeEmail(email);
        const userCredential = await signInWithEmailAndPassword(auth, normalized, password);
        return userCredential.user;
    } catch (error: any) {
        console.error("Login attempt failed:", error);
        throw error;
    }
};

/**
 * Registers a new staff member atomically.
 * Uses secondaryAuth to keep the current admin session active.
 */
export const registerStaffAccount = async (staffData: {
    email: string;
    password: string;
    fullName: string;
    roleId: string;
    phone?: string;
}) => {
    const email = normalizeEmail(staffData.email);
    let createdUser: any = null;

    try {
        // 1. Create Auth Account via secondary instance
        const userCredential = await createUserWithEmailAndPassword(secondaryAuth, email, staffData.password);
        createdUser = userCredential.user;

        // 2. Prepare Firestore Document
        const nameParts = staffData.fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();

        const userProfile = {
            id: createdUser.uid, // Use UID as Document ID for 1:1 mapping
            uid: createdUser.uid,
            fullName: staffData.fullName,
            initials,
            email: email,
            phone: staffData.phone || '',
            roleId: staffData.roleId,
            status: 'Active',
            createdAt: serverTimestamp(),
            lastLogin: 'Never'
        };

        // 3. Persist to Firestore
        await setDoc(doc(db, "user", createdUser.uid), userProfile);

        // 4. Immediately sign out of secondary app to clean up state
        await signOut(secondaryAuth);

        return { success: true, user: createdUser };
    } catch (error: any) {
        console.error("Atomic Registration Failed:", error);

        // Rollback: If user was created in Auth but DB failed, remove them
        if (createdUser) {
            try {
                await deleteUser(createdUser);
            } catch (cleanupError) {
                console.error("Rollback failed:", cleanupError);
            }
        }
        throw error;
    }
};

/**
 * Signs up a user using the main auth instance (Self-registration).
 */
export const signup = async (email: string, password: string) => {
    try {
        const normalized = normalizeEmail(email);
        const userCredential = await createUserWithEmailAndPassword(auth, normalized, password);
        return userCredential.user;
    } catch (error: any) {
        console.error("Error signing up:", error);
        throw error;
    }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Staff } from '../types';
import { useActivityLogs } from '../hooks/useAppData';
import { auth, db } from '../services/firebase';
// @ts-ignore
import { signInWithEmailAndPassword, signOut, onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { normalizeEmail } from '../services/authService';

interface AuthContextType {
    currentStaff: Staff | null;
    login: (email: string, password: string) => Promise<{ success: boolean; message: string }>;
    logout: () => Promise<void>;
    updateCurrentUser: (updates: Partial<Staff>) => void;
    isAuthenticated: boolean;
    loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { addActivityLog } = useActivityLogs();
    const [currentStaff, setCurrentStaff] = useState<Staff | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: any) => {
            if (firebaseUser) {
                try {
                    // Precise Lookup by UID
                    const userRef = doc(db, "user", firebaseUser.uid);
                    const userSnap = await getDoc(userRef);

                    if (userSnap.exists()) {
                        setCurrentStaff(userSnap.data() as Staff);
                    } else {
                        // AUTO-HEALING: Profile sync
                        console.warn("Profile missing. Initiating auto-repair for:", firebaseUser.email);
                        const nameParts = (firebaseUser.displayName || 'Staff User').split(' ');
                        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();

                        const repairedProfile: Staff = {
                            id: firebaseUser.uid,
                            fullName: firebaseUser.displayName || 'Staff User',
                            initials,
                            email: normalizeEmail(firebaseUser.email),
                            phone: '',
                            roleId: 'Sales Representative',
                            status: 'Active',
                            lastLogin: new Date().toISOString()
                        };

                        await setDoc(doc(db, "user", firebaseUser.uid), repairedProfile);
                        setCurrentStaff(repairedProfile);
                    }
                } catch (error) {
                    console.error("Auth Session Verification Failed:", error);
                    setCurrentStaff(null);
                }
            } else {
                setCurrentStaff(null);
            }
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const login = async (email: string, password: string) => {
        try {
            // Trim and lowercase to prevent credential mismatches
            const normalizedEmail = normalizeEmail(email);
            if (!normalizedEmail || !password) {
                return { success: false, message: 'Please enter both email and password.' };
            }

            await signInWithEmailAndPassword(auth, normalizedEmail, password);
            return { success: true, message: 'Login successful' };
        } catch (error: any) {
            console.error("Firebase login error:", error.code, error.message);

            // Standardizing error messages for 'invalid-credential' 
            // (which covers wrong password, user-not-found, etc. in modern Firebase Auth)
            let message = 'Verification failed. Please check your email and password.';

            if (error.code === 'auth/invalid-credential') {
                message = 'Invalid email or password. Please verify your credentials.';
            } else if (error.code === 'auth/user-disabled') {
                message = 'This account has been disabled. Please contact the administrator.';
            } else if (error.code === 'auth/too-many-requests') {
                message = 'Too many failed login attempts. Please try again later.';
            } else if (error.code === 'auth/network-request-failed') {
                message = 'Network error. Please check your internet connection.';
            }

            return { success: false, message };
        }
    };

    const logout = async () => {
        if (currentStaff) {
            addActivityLog('Logout', `User ${currentStaff.fullName} logged out.`, currentStaff.id);
        }
        await signOut(auth);
        setCurrentStaff(null);
    };

    const updateCurrentUser = (updates: Partial<Staff>) => {
        if (currentStaff) {
            setCurrentStaff({ ...currentStaff, ...updates });
        }
    };

    return (
        <AuthContext.Provider value={{
            currentStaff,
            login,
            logout,
            updateCurrentUser,
            isAuthenticated: !!currentStaff,
            loading
        }}>
            {!loading && children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

