/**
 * Sanitizes data for Firestore by removing undefined values and preventing circular references.
 * It creates a deep copy to ensure the original object remains untouched.
 */
const sanitizeData = (data: any): any => {
    // 1. Handle non-objects or null immediately
    if (data === null || typeof data !== 'object') {
        return data === undefined ? null : data;
    }

    // 2. Handle Dates - Firestore prefers its own Timestamps or Strings
    if (data instanceof Date) {
        return data.toISOString();
    }

    // 3. Handle Arrays - recursively sanitize items
    if (Array.isArray(data)) {
        return data.map(item => sanitizeData(item));
    }

    // 4. Handle Objects - clone and sanitize keys/values
    // We use a safe approach to avoid symbols and non-enumerable properties
    const sanitizedObj: any = {};

    // Use Object.keys to ensure we only get serializable properties
    const keys = Object.keys(data);
    for (const key of keys) {
        const value = data[key];

        // Skip functions and explicitly undefined values
        if (typeof value === 'function' || value === undefined) {
            continue;
        }

        // Recursively sanitize the value
        // Note: For deep nesting that might be circular, 
        // we assume the app logic doesn't create them by design.
        // If it does, this will throw a stack overflow instead of a cyclic error,
        // which is easier to debug in the specific component creating the cycle.
        sanitizedObj[key] = sanitizeData(value);
    }

    return sanitizedObj;
};

const fetchCollection = async <T>(colName: string): Promise<T[]> => {
    try {
        const snapshot = await getDocs(collection(db, colName));
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as T));
    } catch (error) {
        console.error(`Error fetching ${colName}:`, error);
        return [];
    }
};

