            {children}
        </select>
        {isTouched && !error && required && (
            <CheckCircleIcon className="absolute right-8 top-[37px] w-5 h-5 text-green-500 pointer-events-none" />
        )}
        {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
    </div>
);

const FormSection: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
    <div className="mt-6 pt-6 border-t border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">{title}</h3>
        <div className="mt-4 grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
            {children}
        </div>
    </div>
);

const initialFormData: FormData = {
    surname: '',
    otherNames: '',
    dateOfBirth: '',
    currentAddress: '',
    telephone: '',
    email: '',
    gender: 'Other',
    photo: '',
    placeOfWork: '',
    profession: '',
    position: '',
    kinName: '',
    kinAddress: '',
    kinPhone: '',
    kinRelationship: '',
    kinEmail: '',
    witnessName: '',
    witnessAddress: '',
    witnessPhone: '',
    paymentDate: new Date().toISOString().split('T')[0],
    paymentMethod: 'Bank Transfer',
    location: '',
    propertyType: 'Residential',
    plotNumber: '',
    numberOfPlots: '1',
    plannedDevelopmentYear: new Date().getFullYear().toString(),
    filledFormPdf: null,
    indentureName: '',
    indentureAddress: '',
    salesRep: '',
    salesManager: '',
    accountsHead: '',
    clerk: '',
    price: '',
};

const ClientForm: React.FC<ClientFormProps> = ({ isOpen, onClose, onSave, onSaveAndPay, properties, editingClient, clients }) => {
    const [step, setStep] = useState(1);
    const [formData, setFormData] = useState<FormData>(initialFormData);
    const [photoPreview, setPhotoPreview] = useState<string | null>(null);
    const [pdfFile, setPdfFile] = useState<File | null>(null);
    const [photoFile, setPhotoFile] = useState<File | null>(null);
    const [touched, setTouched] = useState<Partial<Record<keyof FormData, boolean>>>({});
    const [isProcessing, setIsProcessing] = useState(false);

    // Dropdown UI state
    const [isPlotDropdownOpen, setIsPlotDropdownOpen] = useState(false);
    const plotDropdownRef = useRef<HTMLDivElement>(null);

    // Authority Base Price
    const basePrice = useMemo(() => {
        const match = properties.find(p => p.location === formData.location);
        return match ? match.price : 0;
    }, [formData.location, properties]);

    // Availability Cross-Reference
    const takenPlots = useMemo(() => {
        const taken = new Set<string>();
        clients.forEach(c => {
            if (c.plot && c.plot !== 'N/A') {
                c.plot.split(',').forEach(p => taken.add(p.trim().toUpperCase()));
            }
        });
        return taken;
    }, [clients]);

    const availablePlotsForLocation = useMemo(() => {
        const prop = properties.find(p => p.location === formData.location);
        if (!prop || !prop.inventory) return [];

        const allPlots: { plotNumber: string; isTaken: boolean }[] = [];
        prop.inventory.forEach((inv: any) => {
            const prefix = inv.zone || 'P1';
            for (let i = 1; i <= inv.count; i++) {
                const pNum = `${prefix}-${i}`;
                allPlots.push({
                    plotNumber: pNum,
                    isTaken: takenPlots.has(pNum) && (!editingClient || !editingClient.plot.split(',').map(p => p.trim().toUpperCase()).includes(pNum))
                });
            }
        });
        return allPlots;
    }, [formData.location, properties, takenPlots, editingClient]);

    // Handle Plot Selection Logic
    const handlePlotsChange = (e: ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        const num = parseInt(value);
        setFormData(prev => ({ ...prev, numberOfPlots: value }));
        setTouched(prev => ({ ...prev, numberOfPlots: true }));
        if (!formData.location) return;
        if (isNaN(num) || num <= 0) return;
        const calculatedPrice = basePrice * num;
        setFormData(prev => ({ ...prev, numberOfPlots: value, price: calculatedPrice.toString() }));
    };

    const handleLocationChange = (e: ChangeEvent<HTMLSelectElement>) => {
        const loc = e.target.value;
        const match = properties.find(p => p.location === loc);
        const pCount = parseInt(formData.numberOfPlots) || 1;
        const priceValue = match ? (match.price * pCount).toString() : '';
        setFormData(prev => ({ ...prev, location: loc, price: priceValue, plotNumber: '' }));
    };

    const togglePlotSelection = (plotNumber: string) => {
        const current = formData.plotNumber.split(',').map(x => x.trim()).filter(Boolean);
        const updated = current.includes(plotNumber) 
            ? current.filter(x => x !== plotNumber) 
            : [...current, plotNumber];
        setFormData(prev => ({ ...prev, plotNumber: updated.join(', ') }));
        setTouched(prev => ({ ...prev, plotNumber: true }));
    };

    // Close plot dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (plotDropdownRef.current && !plotDropdownRef.current.contains(event.target as Node)) {
                setIsPlotDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

     useEffect(() => {
        if (isOpen && editingClient) {
            setFormData({
                surname: editingClient.surname,
                otherNames: editingClient.otherNames,
                dateOfBirth: editingClient.dateOfBirth || '',
                currentAddress: editingClient.location,
                telephone: editingClient.phone,
                email: editingClient.email,
                gender: editingClient.gender || 'Other',
                photo: editingClient.photo || '',
                placeOfWork: editingClient.professionalDetails?.placeOfWork || '',
                profession: editingClient.professionalDetails?.profession || '',
                position: editingClient.professionalDetails?.position || '',
                kinName: editingClient.nextOfKin.name,
                kinAddress: editingClient.nextOfKin.address || '',
                kinPhone: editingClient.nextOfKin.phone,
                kinRelationship: editingClient.nextOfKin.relationship,
                kinEmail: editingClient.nextOfKin.email || '',
                witnessName: editingClient.witness.name,
                witnessAddress: editingClient.witness.address,
                witnessPhone: editingClient.witness.phone,
                paymentDate: editingClient.regDate,
                paymentMethod: editingClient.payment.paymentHistory[0]?.method || 'Bank Transfer',
                location: editingClient.location,
                propertyType: editingClient.propertyType || 'Residential',
                plotNumber: editingClient.plot,
                numberOfPlots: (editingClient as any).numberOfPlots || '1',
                plannedDevelopmentYear: editingClient.plannedDevelopmentYear || new Date().getFullYear().toString(),
                filledFormPdf: editingClient.filledFormPdf,
                indentureName: editingClient.indenture.name,
                indentureAddress: editingClient.indenture.address,
                salesRep: editingClient.officeUse.salesRep,
                salesManager: editingClient.officeUse.salesManager,
                accountsHead: editingClient.officeUse.accountsHead,
                clerk: editingClient.officeUse.clerk,
                price: editingClient.payment.total.toString(),
            });
            setPhotoPreview(editingClient.photo || null);
            setTouched({});
        } else if (isOpen) {
            resetForm();
        }
    }, [isOpen, editingClient]);

    const validate = useCallback((): Partial<Record<keyof FormData, string>> => {
        const errors: Partial<Record<keyof FormData, string>> = {};
        // Critical fields required for save
        const requiredFields: (keyof FormData)[] = ['surname', 'otherNames', 'telephone', 'location', 'plotNumber'];
        requiredFields.forEach(field => {
            if (!formData[field]) errors[field] = 'This field cannot be left blank.';
        });
        if (formData.numberOfPlots && (parseInt(formData.numberOfPlots) <= 0 || isNaN(parseInt(formData.numberOfPlots)))) {
            errors.numberOfPlots = 'Number of plots must be a positive number.';
        }
        return errors;
    }, [formData]);

    const errors = useMemo(() => validate(), [validate]);
    const isFormValid = Object.keys(errors).length === 0;

    const handleBlur = (e: React.FocusEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name } = e.target as { name: keyof FormData };
        setTouched(prev => ({ ...prev, [name]: true }));
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (fieldName: keyof FormData) => (value: string) => {
        setFormData(prev => ({ ...prev, [fieldName]: value }));
    };

    const handlePhotoChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const allowedTypes = ['image/jpeg', 'image/png', 'image/jpg'];
            if (allowedTypes.includes(file.type)) {
                setPhotoFile(file);
                const reader = new FileReader();
                reader.onloadend = () => {
                    setPhotoPreview(reader.result as string);
                };
                reader.readAsDataURL(file);
            } else {
                 alert('Invalid file type. Please upload a .jpg, .jpeg, or .png file.');
                 e.target.value = '';
            }
        }
    };

    const handlePdfChange = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            if (file.type === 'application/pdf') {
                setPdfFile(file);
                setTouched(prev => ({ ...prev, filledFormPdf: true }));
            } else {
                alert('Please upload a PDF file.');
                e.target.value = '';
            }
        }
    };

    const handleNext = () => {
        setStep(prev => Math.min(prev + 1, 3));
    };

    const handleBack = () => setStep(prev => Math.max(prev - 1, 1));

    const handleAddPaymentDetails = async (e: FormEvent) => {
        e.preventDefault();
        // Relax validation for dev flow to ensure "Finish" works
        if (!formData.surname || !formData.otherNames || !formData.location || !formData.plotNumber) {
            alert("Critical details (Name, Location, Plot) are required to finish registration.");
            return;
        }
        setIsProcessing(true);
        try {
            // Trigger the "Save and Move to Financials" flow
            onSaveAndPay(formData, { photo: photoFile, pdf: pdfFile });
            // Component cleanup handled via onSaveAndPay caller (ClientsPage)
        } catch (error) {
            console.error("Save failed:", error);
            setIsProcessing(false);
        }
    };

    const resetForm = () => {
        setFormData(initialFormData);
        setPhotoPreview(null);
        setPdfFile(null);
        setPhotoFile(null);
        setStep(1);
        setTouched({});
        setIsProcessing(false);
    };

    if (!isOpen) return null;

    const steps = [
        { name: 'Client Information', icon: <UserGroupIcon className="w-5 h-5" /> },
        { name: 'Acquisition Details', icon: <BuildingLibraryIcon className="w-5 h-5" /> },
        { name: 'Office Details', icon: <BriefcaseIcon className="w-5 h-5" /> },
    ];

    const isPropertyAvailable = properties && properties.length > 0;
    const selectedPlots = formData.plotNumber.split(',').map(x => x.trim()).filter(Boolean);

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4" aria-modal="true" role="dialog">
            <div className="bg-gray-50 dark:bg-gray-900 rounded-lg shadow-xl w-full max-w-4xl max-h-[95vh] flex flex-col transform transition-all">
                <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-t-lg">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">{editingClient ? 'Edit Client Details' : 'New Client Registration'}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                    <nav aria-label="Progress">
                         <ol role="list" className="flex items-center">
                            {steps.map((s, stepIdx) => (
                                <li key={s.name} className={`relative ${stepIdx !== steps.length - 1 ? 'pr-8 sm:pr-20' : ''}`}>
                                    {step > stepIdx + 1 ? (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true"><div className="h-0.5 w-full bg-blue-600" /></div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-blue-600 rounded-full text-white">{s.icon}</div>
                                        </>
                                    ) : step === stepIdx + 1 ? (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true"><div className="h-0.5 w-full bg-gray-200 dark:bg-gray-700" /></div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-800 border-2 border-blue-600 rounded-full text-blue-600">{s.icon}</div>
                                        </>
                                    ) : (
                                        <>
                                        <div className="absolute inset-0 flex items-center" aria-hidden="true"><div className="h-0.5 w-full bg-gray-200 dark:bg-gray-700" /></div>
                                        <div className="relative w-8 h-8 flex items-center justify-center bg-white dark:bg-gray-800 border-2 border-gray-300 dark:border-gray-600 rounded-full text-gray-400">{s.icon}</div>
                                        </>
                                    )}
                                     <span className="absolute -bottom-6 text-xs font-semibold text-center w-24 -left-8 text-gray-600 dark:text-gray-400">{s.name}</span>
                                </li>
                            ))}
                        </ol>
                    </nav>
                </div>

                <div className="p-6 overflow-y-auto flex-grow">
                    {step === 1 && (
                        <div className="animate-in fade-in duration-300">
                           <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                                <div className="sm:col-span-2">
                                    <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">Personal Information</h3>
                                    <div className="mt-4 grid grid-cols-1 gap-y-6 gap-x-4 sm:grid-cols-2">
                                        <SmartInputField id="surname" label="Surname" value={formData.surname} onChange={handleChange} onBlur={handleBlur} required error={touched.surname ? errors.surname : undefined} isTouched={touched.surname} />
                                        <SmartInputField id="otherNames" label="Other Names" value={formData.otherNames} onChange={handleChange} onBlur={handleBlur} required error={touched.otherNames ? errors.otherNames : undefined} isTouched={touched.otherNames}/>
                                        <SmartInputField id="dateOfBirth" label="Date of Birth" type="date" value={formData.dateOfBirth} onChange={handleChange} onBlur={handleBlur} error={touched.dateOfBirth ? errors.dateOfBirth : undefined} isTouched={touched.dateOfBirth} />
                                         <SmartSelectField id="gender" label="Gender" value={formData.gender} onChange={handleChange} onBlur={handleBlur} error={touched.gender ? errors.gender : undefined} isTouched={touched.gender}>
                                            <option>Male</option>
                                            <option>Female</option>
                                            <option>Other</option>
                                        </SmartSelectField>
                                        <div className="sm:col-span-2">
                                            <SmartInputField id="currentAddress" label="Current Address" value={formData.currentAddress} onChange={handleChange} onBlur={handleBlur} required error={touched.currentAddress ? errors.currentAddress : undefined} isTouched={touched.currentAddress} />
                                        </div>
                                        <PhoneInput id="telephone" name="telephone" label="Telephone" value={formData.telephone} onChange={handlePhoneChange('telephone')} required error={touched.telephone ? errors.telephone : undefined} />
                                        <EmailInput id="email" name="email" label="Email Address" value={formData.email} onChange={(val) => setFormData(prev => ({...prev, email: val}))} error={touched.email ? errors.email : undefined} />
                                    </div>
                                </div>
                                <div className="sm:col-span-1">
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Passport-sized Photo</label>
                                    <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 dark:border-gray-600 border-dashed rounded-md">
                                        <div className="space-y-1 text-center">
                                            {photoPreview ? (
                                                <img src={photoPreview} alt="Client" className="mx-auto h-24 w-24 object-cover rounded-md" />
                                            ) : (
                                                <svg className="mx-auto h-12 w-12 text-gray-400" stroke="currentColor" fill="none" viewBox="0 0 48 48" aria-hidden="true"><path d="M28 8H12a4 4 0 00-4 4v20m32-12v8m0 0v8a4 4 0 01-4 4H12a4 4 0 01-4-4v-4m32-4l-3.172-3.172a4 4 0 00-5.656 0L28 28M8 32l9.172-9.172a4 4 0 015.656 0L28 28" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" /></svg>
                                            )}
                                            <div className="flex text-sm text-gray-600 dark:text-gray-400">
                                                <label htmlFor="photo-upload" className="relative cursor-pointer bg-white dark:bg-gray-800 rounded-md font-medium text-blue-600 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                                                    <span>{photoFile ? 'Change photo' : 'Upload a file'}</span>
                                                    <input id="photo-upload" name="photo" type="file" className="sr-only" onChange={handlePhotoChange} accept=".jpg,.jpeg,.png" />
                                                </label>
                                                <p className="pl-1">or drag and drop</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                           </div>

                           <FormSection title="Professional Information">
                               <SmartInputField id="placeOfWork" label="Place of Work" value={formData.placeOfWork} onChange={handleChange} onBlur={handleBlur} error={touched.placeOfWork ? errors.placeOfWork : undefined} isTouched={touched.placeOfWork}/>
                               <SmartInputField id="profession" label="Profession" value={formData.profession} onChange={handleChange} onBlur={handleBlur} error={touched.profession ? errors.profession : undefined} isTouched={touched.profession}/>
                               <SmartInputField id="position" label="Position/Rank" value={formData.position} onChange={handleChange} onBlur={handleBlur} error={touched.position ? errors.position : undefined} isTouched={touched.position}/>
                           </FormSection>

                           <FormSection title="Next of Kin Details">
                               <SmartInputField id="kinName" label="Name" value={formData.kinName} onChange={handleChange} onBlur={handleBlur} required error={touched.kinName ? errors.kinName : undefined} isTouched={touched.kinName}/>
                               <SmartInputField id="kinRelationship" label="Relationship with Buyer" value={formData.kinRelationship} onChange={handleChange} onBlur={handleBlur} error={touched.kinRelationship ? errors.kinRelationship : undefined} isTouched={touched.kinRelationship}/>
                               <PhoneInput id="kinPhone" name="kinPhone" label="Telephone Number" value={formData.kinPhone} onChange={handlePhoneChange('kinPhone')} required error={touched.kinPhone ? errors.kinPhone : undefined} />
                               <EmailInput id="kinEmail" name="kinEmail" label="Email Address" value={formData.kinEmail} onChange={(val) => setFormData(prev => ({...prev, kinEmail: val}))} error={touched.kinEmail ? errors.kinEmail : undefined} />
                               <div className="sm:col-span-2">
                                    <SmartInputField id="kinAddress" label="Address" value={formData.kinAddress} onChange={handleChange} onBlur={handleBlur} error={touched.kinAddress ? errors.kinAddress : undefined} isTouched={touched.kinAddress}/>
                               </div>
                           </FormSection>

                           {/* NEW: Witness Details Section */}
                           <FormSection title="Witness Details">
                               <SmartInputField 
                                   id="witnessName" 
                                   label="Witness Name" 
                                   value={formData.witnessName} 
                                   onChange={handleChange} 
                                   onBlur={handleBlur} 
                                   isTouched={touched.witnessName} 
                               />
                               <PhoneInput 
                                   id="witnessPhone" 
                                   name="witnessPhone" 
                                   label="Witness Phone" 
                                   value={formData.witnessPhone} 
                                   onChange={handlePhoneChange('witnessPhone')} 
                               />
                               <div className="sm:col-span-2">
                                   <SmartInputField 
                                       id="witnessAddress" 
                                       label="Witness Address" 
                                       value={formData.witnessAddress} 
                                       onChange={handleChange} 
                                       onBlur={handleBlur} 
                                       isTouched={touched.witnessAddress} 
                                   />
                               </div>
                           </FormSection>
                        </div>
                    )}
                    {step === 2 && (
                        <div className="animate-in fade-in duration-300">
                             <FormSection title="Property & Transaction Details">
                                <div className="sm:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4">
                                    <SmartSelectField id="location" label="Location*" value={formData.location} onChange={handleLocationChange} onBlur={handleBlur} required disabled={!isPropertyAvailable} error={touched.location ? errors.location : undefined} isTouched={touched.location}>
                                        <option value="">{isPropertyAvailable ? '-- Select Location --' : 'No properties available'}</option>
                                        {properties.map(p => <option key={p.id} value={p.location}>{p.location}</option>)}
                                    </SmartSelectField>

                                    <SmartInputField id="numberOfPlots" label="Plots Required*" type="number" value={formData.numberOfPlots} onChange={handlePlotsChange} onBlur={handleBlur} required placeholder="1" error={touched.numberOfPlots ? errors.numberOfPlots : undefined} isTouched={touched.numberOfPlots} />

                                    <SmartInputField id="price" label="Total Price (GHC)*" value={formData.price} readOnly required error={touched.price ? errors.price : undefined} isTouched={touched.price} placeholder="Auto-calculated" />
                                </div>

                                <div className="sm:col-span-2 space-y-2 relative" ref={plotDropdownRef}>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Select Plot(s)* <span className="text-gray-400 font-normal text-xs">(Based on CEO Hub Inventory)</span></label>

                                    {/* Multi-Select Dropdown Toggle */}
                                    <div 
                                        onClick={() => formData.location && setIsPlotDropdownOpen(!isPlotDropdownOpen)}
                                        className={`min-h-[42px] flex flex-wrap gap-2 items-center p-2 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm cursor-pointer transition-all ${!formData.location ? 'opacity-50 cursor-not-allowed bg-gray-100 dark:bg-gray-800' : 'hover:border-blue-500'}`}
                                    >
                                        {selectedPlots.length > 0 ? (
                                            selectedPlots.map(plot => (
                                                <Badge 
                                                    key={plot} 
                                                    variant="info" 
                                                    className="flex items-center gap-1.5 py-1 px-2 text-[11px]"
                                                >
                                                    {plot}
                                                    <XMarkIcon 
                                                        className="w-3.5 h-3.5 cursor-pointer hover:text-red-500" 
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            togglePlotSelection(plot);
                                                        }}
                                                    />
                                                </Badge>
                                            ))
                                        ) : (
                                            <span className="text-gray-400 text-sm pl-1">
                                                {formData.location ? '-- Choose plot numbers --' : 'Select a location first'}
                                            </span>
                                        )}
                                        <div className="ml-auto pr-1">
                                            <ChevronDownIcon className={`w-4 h-4 text-gray-400 transition-transform ${isPlotDropdownOpen ? 'rotate-180' : ''}`} />
                                        </div>
                                    </div>

                                    {/* Dropdown Menu */}
                                    {isPlotDropdownOpen && formData.location && (
                                        <div className="absolute z-50 left-0 right-0 mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-xl overflow-hidden animate-in slide-in-from-top-1 duration-200">
                                            <div className="max-h-[250px] overflow-y-auto scrollbar-thin divide-y divide-gray-100 dark:divide-gray-700">
                                                {availablePlotsForLocation.length > 0 ? (
                                                    availablePlotsForLocation.map(p => (
                                                        <label 
                                                            key={p.plotNumber}
                                                            className={`flex items-center gap-3 px-4 py-2.5 transition-colors ${p.isTaken ? 'opacity-50 bg-gray-50 dark:bg-gray-900/50 cursor-not-allowed' : 'hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer'}`}
                                                        >
                                                            <input 
                                                                type="checkbox"
                                                                disabled={p.isTaken}
                                                                checked={selectedPlots.includes(p.plotNumber)}
                                                                onChange={() => togglePlotSelection(p.plotNumber)}
                                                                className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500 dark:border-gray-600 bg-white dark:bg-gray-700"
                                                            />
                                                            <div className="flex-grow">
                                                                <span className={`text-sm font-bold ${selectedPlots.includes(p.plotNumber) ? 'text-blue-600 dark:text-blue-400' : 'text-gray-700 dark:text-gray-200'}`}>
                                                                    {p.plotNumber}
                                                                </span>
                                                                {p.isTaken && (
                                                                    <span className="ml-2 text-[10px] uppercase font-black text-red-500">Taken</span>
                                                                )}
                                                            </div>
                                                            {selectedPlots.includes(p.plotNumber) && (
                                                                <CheckCircleIcon className="w-4 h-4 text-blue-600" />
                                                            )}
                                                        </label>
                                                    ))
                                                ) : (
                                                    <div className="p-8 text-center text-gray-500 text-sm">No plots found for this location.</div>
                                                )}
                                            </div>
                                        </div>
                                    )}

                                    {errors.plotNumber && touched.plotNumber && <p className="text-xs text-red-500 mt-1">{errors.plotNumber}</p>}
                                </div>

                                <SmartSelectField id="propertyType" label="Usage Category" value={formData.propertyType} onChange={handleChange} onBlur={handleBlur} error={touched.propertyType ? errors.propertyType : undefined} isTouched={touched.propertyType}>
                                    <option>Residential</option>
                                    <option>Commercial</option>
                                </SmartSelectField>
                                <SmartInputField id="plannedDevelopmentYear" label="Development Year" type="number" value={formData.plannedDevelopmentYear} onChange={handleChange} onBlur={handleBlur} error={touched.plannedDevelopmentYear ? errors.plannedDevelopmentYear : undefined} isTouched={touched.plannedDevelopmentYear}/>
                                <SmartInputField id="paymentDate" label="Reg. Date" type="date" value={formData.paymentDate} onChange={handleChange} onBlur={handleBlur} required error={touched.paymentDate ? errors.paymentDate : undefined} isTouched={touched.paymentDate}/>
                                <SmartSelectField id="paymentMethod" label="Method" value={formData.paymentMethod} onChange={handleChange} onBlur={handleBlur} error={touched.paymentMethod ? errors.paymentMethod : undefined} isTouched={touched.paymentMethod}>
                                    <option>Bank Transfer</option><option>Cash</option><option>MoMo</option><option>Cheque</option>
                                </SmartSelectField>
                                <div className={`sm:col-span-2 p-3 rounded-md border relative ${touched.filledFormPdf && errors.filledFormPdf ? 'border-red-500' : 'border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800'}`}>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Upload Form Scan</label>
                                    <div className="mt-1 flex items-center">
                                        <label htmlFor="filledFormPdf-upload" className="relative cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 focus-within:ring-2 focus-within:ring-blue-500">
                                            <span>{pdfFile ? pdfFile.name : (formData.filledFormPdf ? 'Uploaded' : 'Select PDF')}</span>
                                            <input id="filledFormPdf-upload" name="filledFormPdf" type="file" className="sr-only" onChange={handlePdfChange} accept="application/pdf" />
                                        </label>
                                    </div>
                                </div>
                             </FormSection>

                            <FormSection title="Indenture Name Preference">
                                <SmartInputField id="indentureName" label="Full Name" value={formData.indentureName} onChange={handleChange} onBlur={handleBlur} required error={touched.indentureName ? errors.indentureName : undefined} isTouched={touched.indentureName}/>
                                <SmartInputField id="indentureAddress" label="Address" value={formData.indentureAddress} onChange={handleChange} onBlur={handleBlur} required error={touched.indentureAddress ? errors.indentureAddress : undefined} isTouched={touched.indentureAddress}/>
                            </FormSection>
                        </div>
                    )}
                    {step === 3 && (
                        <div className="animate-in fade-in duration-300">
                             <FormSection title="Internal Office Review">
                                <SmartInputField id="salesRep" label="Intermediary Sales Rep" value={formData.salesRep} onChange={handleChange} onBlur={handleBlur} required error={touched.salesRep ? errors.salesRep : undefined} isTouched={touched.salesRep}/>
                                <SmartInputField id="salesManager" label="Approving Manager" value={formData.salesManager} onChange={handleChange} onBlur={handleBlur} required error={touched.salesManager ? errors.salesManager : undefined} isTouched={touched.salesManager}/>
                                <SmartInputField id="accountsHead" label="Accounts Approval" value={formData.accountsHead} onChange={handleChange} onBlur={handleBlur} required error={touched.accountsHead ? errors.accountsHead : undefined} isTouched={touched.accountsHead}/>
                                <SmartInputField id="clerk" label="Receiving Clerk" value={formData.clerk} onChange={handleChange} onBlur={handleBlur} required error={touched.clerk ? errors.clerk : undefined} isTouched={touched.clerk}/>
                            </FormSection>
                        </div>
                    )}
                </div>

                <div className="flex justify-between items-center p-5 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 rounded-b-lg">
                    <div>{step > 1 && <button type="button" onClick={handleBack} className="bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-semibold py-2 px-4 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 transition-colors">Back</button>}</div>
                    <div>
                        {step < 3 ? (
                             <button type="button" onClick={handleNext} className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors">Next Step</button>
                        ) : (
                            <button type="button" onClick={handleAddPaymentDetails} disabled={isProcessing} className="bg-blue-600 text-white font-black uppercase tracking-widest py-2.5 px-8 rounded-lg hover:bg-blue-700 transition-all shadow-lg disabled:bg-gray-400">
                                {isProcessing ? 'Saving...' : 'Finish Registration'}
                            </button>
                        )}
                    </div>
                </div>
            </div>
            <style>{`
                .scrollbar-thin::-webkit-scrollbar { width: 6px; }
                .scrollbar-thin::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                .dark .scrollbar-thin::-webkit-scrollbar-thumb { background: #334155; }
            `}</style>
        </div>
    );
};

export default ClientForm;

import React, { useState, useEffect, FormEvent, ChangeEvent } from 'react';
import { Staff, Role } from '../types';
import { XIcon } from './icons/XIcon';
import { PhoneInput } from './ui/PhoneInput';
import { EmailInput } from './ui/EmailInput';
import { LockClosedIcon, ShieldCheckIcon } from './icons/DummyIcons';
import { Badge } from './ui/Badge';

interface StaffFormModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (staffData: Partial<Staff>) => void;
    editingUser: Staff | null;
    roles: Role[];
}

const UserFormModal: React.FC<StaffFormModalProps> = ({ isOpen, onClose, onSave, editingUser, roles }) => {
    const [formData, setFormData] = useState({
        fullName: '',
        phone: '',
        email: '',
        roleId: '',
        password: '',
        status: 'Active' as Staff['status'],
    });

    useEffect(() => {
        if (isOpen) {
            if (editingUser) {
                setFormData({
                    fullName: editingUser.fullName,
                    phone: editingUser.phone || '',
                    email: editingUser.email,
                    roleId: editingUser.roleId,
                    password: '',
                    status: editingUser.status,
                });
            } else {
                setFormData({
                    fullName: '',
                    phone: '',
                    email: '',
                    roleId: roles.find(r => r.name === 'Sales Representative')?.id || roles[0]?.id || '',
                    password: '',
                    status: 'Active',
                });
            }
        }
    }, [isOpen, editingUser, roles]);

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({...prev, [name]: value}));
    };

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        if(!editingUser && !formData.password) {
            alert("Password is required for new staff members.");
            return;
        }
        onSave(formData);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-lg border border-gray-200 dark:border-gray-700 overflow-hidden flex flex-col">
                <form onSubmit={handleSubmit} className="flex flex-col h-full">
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                        <h3 className="text-xl font-bold text-gray-800 dark:text-white">
                            {editingUser ? 'Edit Staff Account' : 'Create New Staff Account'}
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 transition-colors">
                            <XIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="p-6 space-y-6 overflow-y-auto max-h-[70vh]">
                        {/* Section 1: Profile Details */}
                        <div className="space-y-4">
                            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest border-b border-gray-100 dark:border-gray-700 pb-2">Profile Details</h4>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="md:col-span-2">
                                    <label htmlFor="fullName" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Full Name*</label>
                                    <input type="text" name="fullName" id="fullName" value={formData.fullName} onChange={handleChange} required className="mt-1 input-class" />
                                </div>
                                <div>
                                    <PhoneInput label="Phone Number" id="phone" name="phone" value={formData.phone} onChange={(val) => setFormData(prev => ({...prev, phone: val}))} />
                                </div>
                                <div>
                                    <label htmlFor="status" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Account Status*</label>
                                    <select name="status" id="status" value={formData.status} onChange={handleChange} required className="mt-1 input-class">
                                        <option value="Active">Active</option>
                                        <option value="Inactive">Inactive</option>
                                    </select>
                                </div>
                                <div className="md:col-span-2">
                                    <label htmlFor="roleId" className="block text-sm font-medium text-gray-700 dark:text-gray-300">System Role*</label>
                                    <select name="roleId" id="roleId" value={formData.roleId} onChange={handleChange} required className="mt-1 input-class">
                                        {roles.map(role => <option key={role.id} value={role.id}>{role.name}</option>)}
                                    </select>
                                </div>
                            </div>
                        </div>

                        {/* Section 2: Login Information */}
                        <div className="space-y-4 pt-4 border-t border-gray-100 dark:border-gray-700">
                            <div className="flex items-center justify-between">
                                <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest">Login Information</h4>
                                {editingUser && (
                                    <Badge variant="success" className="flex items-center gap-1">
                                        <ShieldCheckIcon className="w-3 h-3" /> Password Configured
                                    </Badge>
                                )}
                            </div>

                            <div className="grid grid-cols-1 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Login Email</label>
                                    <div className="mt-1 relative rounded-md shadow-sm">
                                        <input
                                            type="email"
                                            value={formData.email}
                                            readOnly={!!editingUser}
                                            disabled={!!editingUser}
                                            onChange={(e) => setFormData(prev => ({...prev, email: e.target.value}))}
                                            className={`input-class ${editingUser ? 'bg-gray-50 dark:bg-gray-900 cursor-not-allowed text-gray-500' : ''}`}
                                            placeholder="staff@faim.com"
                                            required
                                        />
                                        {editingUser && (
                                            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                                                <LockClosedIcon className="h-4 w-4 text-gray-400" />
                                            </div>
                                        )}
                                    </div>
                                    {editingUser && <p className="mt-1 text-[10px] text-gray-400 italic">Login identifier is managed by system administrators.</p>}
                                </div>

                                <div>
                                    <label htmlFor="password" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                                        {editingUser ? 'Reset Account Password' : 'Initial Password*'}
                                    </label>
                                    <input 
                                        type="password" 
                                        name="password" 
                                        id="password" 
                                        value={formData.password} 
                                        onChange={handleChange} 
                                        placeholder={editingUser ? 'Leave blank to keep existing password' : 'Enter secure password'} 
                                        className="mt-1 input-class font-mono" 
                                    />
                                    {editingUser && <p className="mt-1 text-[10px] text-gray-400">Security note: Only enter a value here if you wish to overwrite the current login password.</p>}
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="p-5 bg-gray-50 dark:bg-gray-900 flex justify-end gap-3 border-t border-gray-200 dark:border-gray-700">
                        <button 
                            type="button" 
                            onClick={onClose} 
                            className="bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 font-bold py-2.5 px-5 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-700 transition-all text-sm"
                        >
                            Cancel
                        </button>
                        <button 
                            type="submit" 
                            className="bg-blue-600 text-white font-black uppercase tracking-widest py-2.5 px-6 rounded-lg hover:bg-blue-700 transition-all shadow-md hover:shadow-lg active:scale-[0.98] text-sm"
                        >
                            {editingUser ? 'Save Changes' : 'Create Account'}
                        </button>
                    </div>
                </form>
                <style>{`
                    .input-class { 
                        display: block; 
                        width: 100%; 
                        padding: 0.625rem 0.75rem; 
                        background-color: white; 
                        border: 1px solid #D1D5DB; 
                        border-radius: 0.5rem; 
                        box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05); 
                        color: #111827; 
                        font-size: 0.875rem;
                        transition: all 0.2s;
                    } 
                    .dark .input-class { 
                        background-color: #0f172a; 
                        border-color: #374151; 
                        color: #ffffff; 
                    } 
                    .input-class:focus { 
                        outline: none; 
                        ring: 2px;
                        border-color: #3B82F6; 
                        box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
                    }
                `}</style>
            </div>
        </div>
    );
};

export default UserFormModal;

import React, { useState, useMemo, ChangeEvent, useEffect } from 'react';
import { Staff, Role, AppModuleName, CompanySettings } from '../types';
import { APP_MODULES } from '../data/mockData';
import { ShieldCheckIcon, UsersIcon, PlusCircleIcon, PencilIcon, TrashIcon, EyeIcon, UserCircleIcon, BuildingLibraryIcon, UploadIcon, CheckCircleIcon, XMarkIcon } from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import UserFormModal from '../components/UserFormModal';
import { PhoneInput } from '../components/ui/PhoneInput';
import { EmailInput } from '../components/ui/EmailInput';
import { usePermissions } from '../context/DataContext';
import { useStaff, useRoles, useCompanySettings } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';
import { useAuth } from '../context/AuthContext';
import { registerStaffAccount, normalizeEmail } from '../services/authService';

interface SettingsPageProps {
    currentStaff: Staff;
    staff: Staff[];
    roles: Role[];
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    onViewStaffActivity: (staff: Staff) => void;
    companySettings: CompanySettings;
    setCompanySettings: (value: React.SetStateAction<CompanySettings>) => Promise<void>;
    onUpdateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
}

const SettingsPage: React.FC<SettingsPageProps> = ({ currentStaff, staff, roles, setRoles, onViewStaffActivity, companySettings, setCompanySettings, onUpdateStaff }) => {
    const { deleteStaff } = useStaff();
    const { rolePermissions, updateRolePermission, initRolePermissions } = usePermissions();
    const { updateCurrentUser } = useAuth();

    const [activeTab, setActiveTab] = useState('profile');
    const [selectedRole, setSelectedRole] = useState<Role | null>(roles[0] || null);

    const [isStaffModalOpen, setStaffModalOpen] = useState(false);
    const [isRoleModalOpen, setRoleModalOpen] = useState(false);
    const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
    const [editingRole, setEditingRole] = useState<Role | null>(null);
    const [newRoleData, setNewRoleData] = useState({ name: '', description: '' });

    const [staffToDelete, setStaffToDelete] = useState<Staff | null>(null);
    const [isSavingStaff, setIsSavingStaff] = useState(false);

    // Feedback State
    const [actionFeedback, setActionFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

    const [profileData, setProfileData] = useState({ fullName: currentStaff.fullName, email: currentStaff.email, phone: currentStaff.phone || '' });
    const [companyData, setCompanyData] = useState({ name: companySettings.name });
    const [profilePhotoPreview, setProfilePhotoPreview] = useState<string | null>(currentStaff.photo || null);

    const [appLogoLightPreview, setAppLogoLightPreview] = useState<string | null>(companySettings.appLogoLight || null);
    const [appLogoDarkPreview, setAppLogoDarkPreview] = useState<string | null>(companySettings.appLogoDark || null);

    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'success' | 'error'>('idle');
    const [saveMessage, setSaveMessage] = useState('');

    const [profileSaveStatus, setProfileSaveStatus] = useState<'idle' | 'saving' | 'success' | 'error'>('idle');
    const [profileSaveMessage, setProfileSaveMessage] = useState('');

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff.roleId), [currentStaff, roles]);
    const canManageStaff = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);
    const canManageCompany = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);

    // Clear feedback after timeout
    useEffect(() => {
        if (actionFeedback) {
            const timer = setTimeout(() => setActionFeedback(null), 5000);
            return () => clearTimeout(timer);
        }
    }, [actionFeedback]);

    const handleSaveStaff = async (staffData: Partial<Staff>) => {
        setIsSavingStaff(true);
        setActionFeedback(null);
        try {
            if (editingStaff) {
                await onUpdateStaff(editingStaff.id, staffData);
                setActionFeedback({ type: 'success', message: 'Staff account updated successfully.' });
            } else {
                await registerStaffAccount({
                    email: normalizeEmail(staffData.email!),
                    password: staffData.password!,
                    fullName: staffData.fullName!,
                    roleId: staffData.roleId!,
                    phone: staffData.phone
                });
                setActionFeedback({ type: 'success', message: 'New staff account created successfully.' });
            }
            setStaffModalOpen(false);
            setEditingStaff(null);
        } catch (error: any) {
            console.error("Staff save error:", error);
            const errMsg = error.message || 'System failed to synchronize account.';
            setActionFeedback({ type: 'error', message: errMsg });
            alert(`Error: ${errMsg}`);
        } finally {
            setIsSavingStaff(false);
        }
    }

    const handleDeleteClick = (member: Staff) => {
        setStaffToDelete(member);
    };

    const confirmDeleteStaff = async () => {
        if (!staffToDelete) return;
        try {
            await deleteStaff(staffToDelete.id);
            setActionFeedback({ type: 'success', message: 'Staff account removed.' });
            setStaffToDelete(null);
        } catch (error) {
            alert("Failed to delete staff account.");
        }
    };

    const handlePermissionChange = async (moduleId: AppModuleName, permission: string, value: boolean) => {
        if (!selectedRole) return;
        await updateRolePermission(selectedRole.id, moduleId, permission, value);
    };

    const handleSaveRole = async (e: React.FormEvent) => {
        e.preventDefault();
        const roleData = newRoleData;
        if (editingRole) {
            setRoles(prev => prev.map(r => r.id === editingRole.id ? { ...editingRole, ...roleData } : r));
        } else {
            const newRoleId = roleData.name;
            const newRole: Role = { id: newRoleId, ...roleData };
            setRoles(prev => [...prev, newRole]); 
            await initRolePermissions(newRoleId);
        }
        setRoleModalOpen(false);
        setEditingRole(null);
        setNewRoleData({ name: '', description: '' });
    };

    const handleDeleteRole = (roleId: string) => {
        if (window.confirm("Are you sure you want to delete this role?")) {
            if (staff.some(u => u.roleId === roleId)) {
                alert("Cannot delete role. It is assigned to active staff members.");
                return;
            }
            setRoles(prev => prev.filter(r => r.id !== roleId));
        }
    };

    const handleProfileFormChange = (e: ChangeEvent<HTMLInputElement>) => {
        setProfileData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleProfilePhotoChange = async (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            try {
                const url = await uploadFile(file, `staff/${currentStaff.id}/profile/${file.name}`);
                await onUpdateStaff(currentStaff.id, { photo: url });
                updateCurrentUser({ photo: url });
                setProfilePhotoPreview(url); 
            } catch (error) {
                alert("Failed to upload photo.");
            }
        }
    };

    const handleSaveProfile = async () => {
        setProfileSaveStatus('saving');
        try {
            await onUpdateStaff(currentStaff.id, profileData);
            updateCurrentUser(profileData);
            setProfileSaveStatus('success');
            setProfileSaveMessage('Profile updated!');
            setTimeout(() => setProfileSaveStatus('idle'), 3000);
        } catch (error) {
            setProfileSaveStatus('error');
        }
    };

    const handleLogoUpload = async (file: File, type: keyof CompanySettings, previewSetter: React.Dispatch<React.SetStateAction<string | null>>) => {
        try {
            const url = await uploadFile(file, `system/branding/${type}/${file.name}`);
            setCompanySettings(prev => ({ ...prev, [type]: url }));
            const reader = new FileReader();
            reader.onloadend = () => previewSetter(reader.result as string);
            reader.readAsDataURL(file);
        } catch (error) {
            alert(`Failed to upload logo.`);
        }
    };

    const handleSaveCompanySettings = async () => {
        setSaveStatus('saving');
        try {
            await setCompanySettings(prev => ({ ...prev, name: companyData.name }));
            setSaveStatus('success');
            setTimeout(() => setSaveStatus('idle'), 3000);
        } catch (error) {
            setSaveStatus('error');
        }
    };

    const RolePill: React.FC<{ role: Role }> = ({ role }) => {
        return <span className={`px-2 py-1 text-xs font-semibold rounded-full border bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-800`}>{role ? role.name : 'Unknown Role'}</span>
    }

    const tabs = [
        { id: 'profile', name: 'My Profile', icon: <UserCircleIcon className="w-5 h-5" /> },
        { id: 'company', name: 'Company Settings', icon: <BuildingLibraryIcon className="w-5 h-5" />, disabled: !canManageCompany },
        { id: 'roles', name: 'Roles & Permissions', icon: <ShieldCheckIcon className="w-5 h-5" />, disabled: !canManageStaff },
        { id: 'staff', name: 'Staff Accounts', icon: <UsersIcon className="w-5 h-5" />, disabled: !canManageStaff },
    ];

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white">System Settings</h1>
                {actionFeedback && (
                    <div className={`flex items-center gap-3 px-4 py-2 rounded-lg border animate-in fade-in slide-in-from-top-4 duration-300 ${actionFeedback.type === 'success' ? 'bg-green-50 border-green-200 text-green-800 dark:bg-green-900/20 dark:border-green-800 dark:text-green-300' : 'bg-red-50 border-red-200 text-red-800 dark:bg-red-900/20 dark:border-red-800 dark:text-red-300'}`}>
                        {actionFeedback.type === 'success' ? <CheckCircleIcon className="w-5 h-5" /> : <XMarkIcon className="w-5 h-5" />}
                        <span className="text-sm font-bold">{actionFeedback.message}</span>
                        <button onClick={() => setActionFeedback(null)} className="ml-2 p-1 hover:bg-black/5 dark:hover:bg-white/5 rounded">
                            <XMarkIcon className="w-4 h-4 opacity-50" />
                        </button>
                    </div>
                )}
            </div>

            <div className="flex border-b border-gray-200 dark:border-gray-700 overflow-x-auto scrollbar-hide">
                {tabs.map(tab => !tab.disabled && (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-2 px-6 py-3 font-semibold transition-all whitespace-nowrap ${activeTab === tab.id ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400' : 'text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white'}`}>
                        {tab.icon} {tab.name}
                    </button>
                ))}
            </div>

            {activeTab === 'profile' && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Edit Your Profile</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
                        <div className="md:col-span-1 flex flex-col items-center">
                            {profilePhotoPreview ? (
                                <img src={profilePhotoPreview} alt="Profile" className="w-32 h-32 rounded-full object-cover mb-4 border-4 border-gray-100 dark:border-gray-700 shadow-sm" />
                            ) : (
                                <div className="w-32 h-32 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center mb-4 border-4 border-gray-100 dark:border-gray-700"><UserCircleIcon className="w-20 h-20 text-gray-400 dark:text-gray-500" /></div>
                            )}
                            <label htmlFor="photo-upload" className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors">
                                Change Photo
                                <input id="photo-upload" name="photo" type="file" className="sr-only" onChange={handleProfilePhotoChange} accept="image/*" />
                            </label>
                        </div>
                        <div className="md:col-span-2 space-y-4">
                            <div>
                                <label className="text-gray-700 dark:text-gray-300 font-medium">Full Name</label>
                                <input type="text" name="fullName" value={profileData.fullName} onChange={handleProfileFormChange} className="w-full mt-1 p-2.5 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 transition-all outline-none" />
                            </div>
                             <div>
                                <EmailInput label="Email" name="email" value={profileData.email} onChange={(val) => setProfileData(prev => ({...prev, email: val}))} />
                            </div>
                             <div>
                                <PhoneInput label="Phone" name="phone" value={profileData.phone} onChange={(val) => setProfileData(prev => ({...prev, phone: val}))} />
                            </div>
                            <div className="flex justify-end items-center gap-3 mt-4 pt-4 border-t dark:border-gray-700">
                                {profileSaveMessage && <span className="text-sm font-medium text-green-600 dark:text-green-400 flex items-center gap-1"><CheckCircleIcon className="w-4 h-4" /> {profileSaveMessage}</span>}
                                <button onClick={handleSaveProfile} disabled={profileSaveStatus === 'saving'} className="flex items-center gap-2 bg-blue-600 text-white font-bold py-2.5 px-6 rounded-lg hover:bg-blue-700 shadow-md active:scale-95 transition-all disabled:opacity-50">
                                    {profileSaveStatus === 'saving' && <LoaderIcon className="w-4 h-4 animate-spin" />} Update Profile
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'company' && canManageCompany && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4">Company Profile</h2>
                    <div className="space-y-6">
                        <div>
                            <label className="text-gray-700 dark:text-gray-300 font-semibold">Application Name</label>
                            <input type="text" value={companyData.name} onChange={e => setCompanyData({name: e.target.value})} className="w-full mt-1 p-2.5 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="text-gray-700 dark:text-gray-300 font-semibold">App Logo (Light)</label>
                                <div className="flex items-center gap-4 mt-2">
                                    <div className="w-16 h-16 border rounded-lg p-2 bg-gray-50 dark:bg-gray-900 flex items-center justify-center overflow-hidden">
                                        {appLogoLightPreview ? <img src={appLogoLightPreview} className="max-h-full max-w-full object-contain" /> : <PhotoIcon className="w-8 h-8 text-gray-300" />}
                                    </div>
                                    <label className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border rounded-lg text-sm hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors flex items-center gap-2">
                                        <UploadIcon className="w-4 h-4"/> Upload
                                        <input type="file" className="sr-only" onChange={(e) => e.target.files?.[0] && handleLogoUpload(e.target.files[0], 'appLogoLight', setAppLogoLightPreview)} />
                                    </label>
                                </div>
                            </div>
                            <div>
                                <label className="text-gray-700 dark:text-gray-300 font-semibold">App Logo (Dark)</label>
                                <div className="flex items-center gap-4 mt-2">
                                    <div className="w-16 h-16 border rounded-lg p-2 bg-gray-900 flex items-center justify-center overflow-hidden">
                                        {appLogoDarkPreview ? <img src={appLogoDarkPreview} className="max-h-full max-w-full object-contain" /> : <PhotoIcon className="w-8 h-8 text-gray-300" />}
                                    </div>
                                    <label className="cursor-pointer bg-white dark:bg-gray-700 py-2 px-3 border rounded-lg text-sm hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors flex items-center gap-2">
                                        <UploadIcon className="w-4 h-4"/> Upload
                                        <input type="file" className="sr-only" onChange={(e) => e.target.files?.[0] && handleLogoUpload(e.target.files[0], 'appLogoDark', setAppLogoDarkPreview)} />
                                    </label>
                                </div>
                            </div>
                        </div>
                        <div className="flex justify-end pt-4 gap-3 border-t dark:border-gray-700">
                            <button onClick={handleSaveCompanySettings} disabled={saveStatus === 'saving'} className="flex items-center gap-2 bg-blue-600 text-white font-bold py-2.5 px-6 rounded-lg hover:bg-blue-700 shadow-md transition-all active:scale-95 disabled:opacity-50">
                                {saveStatus === 'saving' && <LoaderIcon className="w-4 h-4 animate-spin" />} Save System Branding
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'roles' && canManageStaff && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-1 bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="font-bold text-lg text-gray-800 dark:text-white">Roles</h2>
                            <button onClick={() => { setEditingRole(null); setRoleModalOpen(true); }} className="text-sm font-bold text-blue-600 hover:text-blue-800 flex items-center gap-1 transition-colors">
                                <PlusCircleIcon className="w-4 h-4" /> New Role
                            </button>
                        </div>
                        <div className="space-y-2">
                            {roles.map(role => (
                                <button key={role.id} onClick={() => setSelectedRole(role)} className={`w-full text-left p-3 rounded-xl transition-all ${selectedRole?.id === role.id ? 'bg-blue-600 text-white shadow-lg' : 'hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-300'}`}>
                                    <h3 className={`font-bold ${selectedRole?.id === role.id ? 'text-white' : 'text-gray-900 dark:text-white'}`}>{role.name}</h3>
                                    <p className={`text-xs ${selectedRole?.id === role.id ? 'text-blue-100' : 'text-gray-500'}`}>{role.description}</p>
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="lg:col-span-2 bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                        {selectedRole ? (
                            <div>
                                <h2 className="font-bold text-xl text-gray-800 dark:text-white mb-4 border-b pb-4">{selectedRole.name} Module Access Control</h2>
                                <table className="w-full text-sm">
                                    <thead>
                                        <tr className="text-left text-gray-400 font-bold uppercase text-[10px] tracking-widest">
                                            <th className="py-3">Module Name</th><th className="text-center">View</th><th className="text-center">Create</th><th className="text-center">Edit</th><th className="text-center">Delete</th><th className="text-center">Approve</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                        {APP_MODULES.map(module => {
                                            const permissions = rolePermissions.find(rp => rp.roleId === selectedRole.id && rp.moduleId === module.id)?.permissions || { view: false, create: false, edit: false, delete: false, approve: false };
                                            return (
                                                <tr key={module.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/20 transition-colors">
                                                    <td className="py-4 font-bold text-gray-700 dark:text-gray-200">{module.name}</td>
                                                    {['view', 'create', 'edit', 'delete', 'approve'].map((key) => (
                                                        <td key={key} className="text-center py-2">
                                                            <input type="checkbox" className="form-checkbox h-4.5 w-4.5 rounded text-blue-600 bg-gray-100 border-gray-300 focus:ring-blue-500 cursor-pointer"
                                                                checked={permissions[key as keyof typeof permissions]}
                                                                onChange={(e) => handlePermissionChange(module.id as AppModuleName, key, e.target.checked)} />
                                                        </td>
                                                    ))}
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        ) : (
                            <div className="text-center py-20 text-gray-400 opacity-50 flex flex-col items-center">
                                <ShieldCheckIcon className="w-16 h-16 mb-2" />
                                <p className="font-bold">Select a role to manage access permissions</p>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {activeTab === 'staff' && canManageStaff && (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                    <div className="flex flex-wrap justify-between items-center mb-6 gap-4">
                        <h2 className="font-bold text-xl text-gray-800 dark:text-white">Staff Management</h2>
                        <button onClick={() => {setEditingStaff(null); setStaffModalOpen(true);}} className="bg-blue-600 text-white font-black uppercase tracking-widest text-xs py-3 px-6 rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-md hover:shadow-lg transition-all active:scale-95">
                            <PlusCircleIcon className="w-5 h-5" /> Register New Account
                        </button>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-50 dark:bg-gray-900 text-gray-500 border-b dark:border-gray-700">
                                <tr>
                                    <th className="px-4 py-4 font-black uppercase tracking-widest text-[10px]">Staff Member</th>
                                    <th className="px-4 py-4 font-black uppercase tracking-widest text-[10px]">Role / Department</th>
                                    <th className="px-4 py-4 font-black uppercase tracking-widest text-[10px]">Account Status</th>
                                    <th className="px-4 py-4 font-black uppercase tracking-widest text-[10px] text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                {staff.map(member => (
                                    <tr key={member.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors">
                                        <td className="px-4 py-4 flex items-center gap-4">
                                            {member.photo ? <img src={member.photo} className="w-10 h-10 rounded-full object-cover border-2 border-white dark:border-gray-700 shadow-sm"/> : <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-300 flex items-center justify-center font-black text-sm">{member.initials}</div>}
                                            <div>
                                                <div className="font-bold text-gray-900 dark:text-white">{member.fullName}</div>
                                                <div className="text-xs text-gray-500 font-medium">{member.email}</div>
                                            </div>
                                        </td>
                                        <td className="px-4 py-4">
                                            <RolePill role={roles.find(r => r.id === member.roleId)!} />
                                        </td>
                                        <td className="px-4 py-4">
                                            <Badge variant={member.status === 'Active' ? 'success' : 'danger'}>{member.status}</Badge>
                                        </td>
                                        <td className="px-4 py-4 text-right">
                                            <div className="flex justify-end gap-1">
                                                <button onClick={() => onViewStaffActivity(member)} className="p-2 text-gray-400 hover:text-blue-600 transition-colors" title="Activity Logs"><EyeIcon className="w-5 h-5"/></button>
                                                <button onClick={() => { setEditingStaff(member); setStaffModalOpen(true); }} className="p-2 text-gray-400 hover:text-indigo-600 transition-colors" title="Edit Profile"><PencilIcon className="w-5 h-5"/></button>
                                                <button onClick={() => handleDeleteClick(member)} className="p-2 text-gray-400 hover:text-red-600 transition-colors" title="Delete Account"><TrashIcon className="w-5 h-5"/></button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            <UserFormModal 
                isOpen={isStaffModalOpen}
                onClose={() => { setStaffModalOpen(false); setEditingStaff(null); }}
                onSave={handleSaveStaff}
                editingUser={editingStaff}
                roles={roles}
            />

            {staffToDelete && (
                <div className="fixed inset-0 bg-black/60 z-[60] flex justify-center items-center p-4 backdrop-blur-sm">
                    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl max-w-sm w-full p-8 border border-gray-200 dark:border-gray-700 animate-in zoom-in duration-200">
                        <div className="flex items-center justify-center w-16 h-16 mx-auto bg-red-100 dark:bg-red-900/30 rounded-full mb-6">
                            <TrashIcon className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-black text-center text-gray-900 dark:text-white mb-2 uppercase tracking-tight">Delete Account?</h3>
                        <p className="text-center text-sm text-gray-500 dark:text-gray-400 mb-8 leading-relaxed">You are about to remove <strong>{staffToDelete.fullName}</strong>. Access will be revoked immediately and this action is permanent.</p>
                        <div className="flex flex-col gap-3">
                            <button onClick={confirmDeleteStaff} className="w-full py-3 bg-red-600 text-white rounded-xl font-black uppercase tracking-widest text-sm shadow-lg shadow-red-600/20 hover:bg-red-700 transition-all active:scale-95">Confirm Deletion</button>
                            <button onClick={() => setStaffToDelete(null)} className="w-full py-3 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-bold rounded-xl transition-colors hover:bg-gray-200 text-sm">Keep Account</button>
                        </div>
                    </div>
                </div>
            )}

            {isRoleModalOpen && (
                <div className="fixed inset-0 bg-black/60 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
                    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md border border-gray-200 dark:border-gray-700 overflow-hidden">
                        <form onSubmit={handleSaveRole}>
                            <div className="flex justify-between items-center p-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900">
                                <h3 className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter">{editingRole ? 'Update System Role' : 'Define New System Role'}</h3>
                                <button type="button" onClick={() => setRoleModalOpen(false)} className="text-gray-400 hover:text-gray-600"><XMarkIcon className="w-6 h-6" /></button>
                            </div>
                            <div className="p-6 space-y-5">
                                <div><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1.5">Official Role Title</label><input type="text" value={newRoleData.name} onChange={e => setNewRoleData({...newRoleData, name: e.target.value})} className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-900 dark:text-white font-bold transition-all focus:ring-2 focus:ring-blue-500 outline-none" required placeholder="e.g. Sales Director" /></div>
                                <div><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1.5">Role Responsibility Description</label><textarea value={newRoleData.description} onChange={e => setNewRoleData({...newRoleData, description: e.target.value})} className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-lg dark:bg-gray-900 dark:text-white text-sm transition-all focus:ring-2 focus:ring-blue-500 outline-none" required rows={3} placeholder="Brief summary of duties..." /></div>
                            </div>
                            <div className="p-5 bg-gray-50 dark:bg-gray-900 flex justify-end gap-3 rounded-b-lg border-t dark:border-gray-700">
                                <button type="button" onClick={() => setRoleModalOpen(false)} className="px-5 py-2.5 text-sm font-bold text-gray-500 hover:text-gray-800 transition-colors">Discard</button>
                                <button type="submit" className="bg-blue-600 text-white py-2.5 px-6 rounded-lg font-black uppercase tracking-widest text-sm shadow-md hover:shadow-lg transition-all active:scale-95">Save Role</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React, { useState, useMemo, ChangeEvent, useEffect } from 'react';
import { Staff, Role, AppModuleName, CompanySettings } from '../types';
import { APP_MODULES } from '../data/mockData';
// FIX: Added PhotoIcon to the imports from DummyIcons
import { ShieldCheckIcon, UsersIcon, PlusCircleIcon, PencilIcon, TrashIcon, EyeIcon, UserCircleIcon, BuildingLibraryIcon, UploadIcon, CheckCircleIcon, XMarkIcon, PhotoIcon } from '../components/icons/DummyIcons';
import { LoaderIcon } from '../components/icons/LoaderIcon';
import UserFormModal from '../components/UserFormModal';
import { PhoneInput } from '../components/ui/PhoneInput';
import { EmailInput } from '../components/ui/EmailInput';
// FIX: Imported Badge component from ui/Badge
import { Badge } from '../components/ui/Badge';
import { usePermissions } from '../context/DataContext';
import { useStaff, useRoles, useCompanySettings } from '../hooks/useAppData';
import { uploadFile } from '../services/storageService';
import { useAuth } from '../context/AuthContext';
import { registerStaffAccount, normalizeEmail } from '../services/authService';

interface SettingsPageProps {
    currentStaff: Staff;
    staff: Staff[];
    roles: Role[];
    setRoles: React.Dispatch<React.SetStateAction<Role[]>>;
    onViewStaffActivity: (staff: Staff) => void;
    companySettings: CompanySettings;
    setCompanySettings: (value: React.SetStateAction<CompanySettings>) => Promise<void>;
    onUpdateStaff: (id: string, details: Partial<Staff>) => Promise<void>;
}

const SettingsPage: React.FC<SettingsPageProps> = ({ currentStaff, staff, roles, setRoles, onViewStaffActivity, companySettings, setCompanySettings, onUpdateStaff }) => {
    const { deleteStaff } = useStaff();
    const { rolePermissions, updateRolePermission, initRolePermissions } = usePermissions();
    const { updateCurrentUser } = useAuth();

    const [activeTab, setActiveTab] = useState('profile');
    const [selectedRole, setSelectedRole] = useState<Role | null>(roles[0] || null);

    const [isStaffModalOpen, setStaffModalOpen] = useState(false);
    const [isRoleModalOpen, setRoleModalOpen] = useState(false);
    const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
    const [editingRole, setEditingRole] = useState<Role | null>(null);
    const [newRoleData, setNewRoleData] = useState({ name: '', description: '' });

    const [staffToDelete, setStaffToDelete] = useState<Staff | null>(null);
    const [isSavingStaff, setIsSavingStaff] = useState(false);

    // Feedback State
    const [actionFeedback, setActionFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

    const [profileData, setProfileData] = useState({ fullName: currentStaff.fullName, email: currentStaff.email, phone: currentStaff.phone || '' });
    const [companyData, setCompanyData] = useState({ name: companySettings.name });
    const [profilePhotoPreview, setProfilePhotoPreview] = useState<string | null>(currentStaff.photo || null);

    const [appLogoLightPreview, setAppLogoLightPreview] = useState<string | null>(companySettings.appLogoLight || null);
    const [appLogoDarkPreview, setAppLogoDarkPreview] = useState<string | null>(companySettings.appLogoDark || null);

    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'success' | 'error'>('idle');
    const [saveMessage, setSaveMessage] = useState('');

    const [profileSaveStatus, setProfileSaveStatus] = useState<'idle' | 'saving' | 'success' | 'error'>('idle');
    const [profileSaveMessage, setProfileSaveMessage] = useState('');

    const userRole = useMemo(() => roles.find(r => r.id === currentStaff.roleId), [currentStaff, roles]);
    const canManageStaff = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);
    const canManageCompany = useMemo(() => userRole?.name === 'CEO' || userRole?.name === 'Administrator', [userRole]);

    // Clear feedback after timeout
    useEffect(() => {
        if (actionFeedback) {
            const timer = setTimeout(() => setActionFeedback(null), 5000);
            return () => clearTimeout(timer);
        }
    }, [actionFeedback]);

    const handleSaveStaff = async (staffData: Partial<Staff>) => {
        setIsSavingStaff(true);
        setActionFeedback(null);
        try {
            if (editingStaff) {
                await onUpdateStaff(editingStaff.id, staffData);
                setActionFeedback({ type: 'success', message: 'Staff account updated successfully.' });
            } else {
                await registerStaffAccount({
                    email: normalizeEmail(staffData.email!),
                    password: staffData.password!,
                    fullName: staffData.fullName!,
                    roleId: staffData.roleId!,
                    phone: staffData.phone
                });
                setActionFeedback({ type: 'success', message: 'New staff account created successfully.' });
            }
            setStaffModalOpen(false);
            setEditingStaff(null);
        } catch (error: any) {
            console.error("Staff save error:", error);
            const errMsg = error.message || 'System failed to synchronize account.';
            setActionFeedback({ type: 'error', message: errMsg });
            alert(`Error: ${errMsg}`);
        } finally {
            setIsSavingStaff(false);
        }
    }

    const handleDeleteClick = (member: Staff) => {
        setStaffToDelete(member);
    };

    const confirmDeleteStaff = async () => {
        if (!staffToDelete) return;
        try {
            await deleteStaff(staffToDelete.id);
            setActionFeedback({ type: 'success', message: 'Staff account removed.' });
            setStaffToDelete(null);
        } catch (error) {
            alert("Failed to delete staff account.");
        }
    };

    const handlePermissionChange = async (moduleId: AppModuleName, permission: string, value: boolean) => {
        if (!selectedRole) return;
        await updateRolePermission(selectedRole.id, moduleId, permission, value);
    };

    const handleSaveRole = async (e: React.FormEvent) => {
        e.preventDefault();
        const roleData = newRoleData;
        if (editingRole) {
            setRoles(prev => prev.map(r => r.id === editingRole.id ? { ...editingRole, ...roleData } : r));
        } else {
            const newRoleId = roleData.name;
            const newRole: Role = { id: newRoleId, ...roleData };
            setRoles(prev => [...prev, newRole]); 
            await initRolePermissions(newRoleId);
        }
        setRoleModalOpen(false);
        setEditingRole(null);
        setNewRoleData({ name: '', description: '' });
    };

    const handleDeleteRole = (roleId: string) => {
        if (window.confirm("Are you sure you want to delete this role?")) {
            if (staff.some(u => u.roleId === roleId)) {
                alert("Cannot delete role. It is assigned to active staff members.");
                return;
            }
            setRoles(prev => prev.filter(r => r.id !== roleId));
        }
    };

    const handleProfileFormChange = (e: ChangeEvent<HTMLInputElement>) => {
        setProfileData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleProfilePhotoChange = async (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            try {
                const url = await uploadFile(file, `staff/${currentStaff.id}/profile/${file.name}`);
                await onUpdateStaff(currentStaff.id, { photo: url });
                updateCurrentUser({ photo: url });
                setProfilePhotoPreview(url); 
            } catch (error) {
                alert("Failed to upload photo.");
            }
        }
    };

    const handleSaveProfile = async () => {
        setProfileSaveStatus('saving');
        try {
            await onUpdateStaff(currentStaff.id, profileData);
            updateCurrentUser(profileData);
            setProfileSaveStatus('success');
            setProfileSaveMessage('Profile updated!');
            setTimeout(() => setProfileSaveStatus('idle'), 3000);
        } catch (error) {
            setProfileSaveStatus('error');
        }
    };

    const handleLogoUpload = async (file: File, type: keyof CompanySettings, previewSetter: React.Dispatch<React.SetStateAction<string | null>>) => {
        try {
            const url = await uploadFile(file, `system/branding/${type}/${file.name}`);
            setCompanySettings(prev => ({ ...prev, [type]: url }));
            const reader = new FileReader();
            reader.onloadend = () => previewSetter(reader.result as string);
            reader.readAsDataURL(file);
        } catch (error) {
            alert(`Failed to upload logo.`);
        }
    };

