                    ) : (
                        <FaimLogoIcon className="w-24 h-24 text-blue-600 dark:text-blue-400 mb-4" />
                    )}
                    <p className="text-gray-500 dark:text-gray-400 text-[10px] font-black uppercase tracking-[0.2em]">Enterprise Resource Planning</p>
                </div>

                {error && (
                    <div className={`border-l-4 p-4 rounded-md animate-in fade-in slide-in-from-top-1 duration-200 ${initStatus === 'success' ? 'bg-green-50 border-green-500 text-green-700' : 'bg-red-50 dark:bg-red-900/20 border-red-500 text-red-700 dark:text-red-200'}`} role="alert">
                        <div className="flex items-start">
