import ThemeToggle from '../components/ThemeToggle';
import { useTheme } from '../context/ThemeContext';
import { registerStaffAccount } from '../services/authService';

interface LoginPageProps {
    onLogin: (email: string, password: string) => Promise<{ success: boolean, message: string }>;
    companySettings: CompanySettings;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin, companySettings }) => {
    const { theme } = useTheme();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);

    // Setup Helper State
    const [showInitHelper, setShowInitHelper] = useState(false);
    const [initStatus, setInitStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);
        setShowInitHelper(false);

        try {
            const result = await onLogin(email.trim(), password);

            if (!result.success) {
                setError(result.message);
                // Trigger helper if likely due to missing account in Auth (standard for new devs)
                if (result.message.includes('Incorrect') || result.message.includes('installation') || result.message.includes('No account')) {
                    setShowInitHelper(true);
                }
            }
        } catch (err) {
            setError('A system error prevented authentication. Check console for details.');
        } finally {
            setLoading(false);
        }
    };

    const handleInitializeSystem = async () => {
        setInitStatus('loading');
        setError('');
        try {
            // Attempt to register the default CEO account
            const result = await registerStaffAccount({
                email: 'ceo@faim.com',
                password: 'password', // Default dev password
                fullName: 'System Administrator',
                roleId: 'CEO'
            });

            if (result.success) {
                setInitStatus('success');
                setEmail('ceo@faim.com');
                setPassword('password');
                setError('Initialization complete! master account "ceo@faim.com" created.');
            }
        } catch (e: any) {
            console.error("Initialization error:", e);
            if (e.code === 'auth/email-already-in-use') {
                // If it already exists, just guide the user to login
                setInitStatus('success');
                setEmail('ceo@faim.com');
                setPassword('password');
                setError('Account "ceo@faim.com" is already registered. Please login with password: password');
            } else {
                setInitStatus('error');
                setError(`Initialization Failed: ${e.message || 'Check Firebase Console settings.'}`);
            }
        }
    };

    const activeAppLogo = theme === 'dark' ? (companySettings.appLogoDark || companySettings.appLogoLight) : (companySettings.appLogoLight || companySettings.appLogoDark);
    const activeCompanyLogo = theme === 'dark' ? (companySettings.companyLogoDark || companySettings.companyLogoLight) : (companySettings.companyLogoLight || companySettings.companyLogoDark);
    const legacyLogo = companySettings.logo;

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100 dark:bg-gray-950 p-4 transition-colors duration-200 relative">
            <div className="absolute top-4 left-4 flex items-center gap-3">
                {(activeCompanyLogo || legacyLogo) ? (
                    <img src={activeCompanyLogo || legacyLogo} alt="Logo" className="w-10 h-10 object-contain" />
                ) : (
                    <div className="w-10 h-10 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center">
                        <span className="text-xl">🏢</span>
                    </div>
                )}
                <span className="font-bold text-xl text-gray-800 dark:text-white tracking-wide">
                    {companySettings.name.split(' ')[0]}<span className="text-blue-500">.</span>
                </span>
            </div>

            <div className="absolute top-4 right-4">
                <ThemeToggle />
            </div>

            <div className="w-full max-w-md p-8 space-y-8 bg-white dark:bg-gray-800 rounded-xl shadow-2xl transition-colors duration-200 mt-12 sm:mt-0 border border-gray-100 dark:border-gray-700">
                <div className="flex flex-col items-center">
                    {activeAppLogo ? (
                        <img src={activeAppLogo} alt="FAIM Logo" className="w-32 h-32 object-contain mb-4" />
                    ) : (
                        <FaimLogoIcon className="w-24 h-24 text-blue-600 dark:text-blue-400 mb-4" />
                    )}
                    <p className="text-gray-500 dark:text-gray-400 text-[10px] font-black uppercase tracking-[0.2em]">Enterprise Resource Planning</p>
                </div>

                {error && (
                    <div className={`border-l-4 p-4 rounded-md animate-in fade-in slide-in-from-top-1 duration-200 ${initStatus === 'success' ? 'bg-green-50 dark:bg-green-900/20 border-green-500 text-green-700 dark:text-green-200' : 'bg-red-50 dark:bg-red-900/20 border-red-500 text-red-700 dark:text-red-200'}`} role="alert">
                        <div className="flex items-start">
                            {initStatus === 'success' ? <CheckCircleIcon className="w-5 h-5 mr-2 shrink-0" /> : <ExclamationTriangleIcon className="w-5 h-5 mr-2 shrink-0" />}
                            <p className="text-sm font-medium">{error}</p>
                        </div>

                        {showInitHelper && initStatus !== 'success' && (
                            <div className="mt-4 pt-4 border-t border-red-200 dark:border-red-800">
                                <p className="text-xs font-bold uppercase tracking-wider mb-2">Login helper (new dev setup):</p>
                                <button
                                    onClick={handleInitializeSystem}
                                    disabled={initStatus === 'loading'}
                                    className="w-full py-2 bg-blue-600 hover:bg-blue-700 text-white text-[10px] font-black uppercase tracking-widest rounded transition-all flex items-center justify-center gap-2"
                                >
                                    {initStatus === 'loading' ? <LoaderIcon className="w-3 h-3 animate-spin" /> : <AcademicCapIcon className="w-3 h-3" />}
                                    Register Master CEO Account
                                </button>
                                <p className="mt-2 text-[9px] opacity-60">This creates ceo@faim.com in Auth if missing. Password: password</p>
                            </div>
                        )}
                    </div>
                )}

                <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
                    <div className="rounded-md shadow-sm -space-y-px">
                        <div>
                            <input
                                id="email-address"
                                name="email"
                                type="email"
                                required
                                className="appearance-none rounded-none relative block w-full px-3 py-3 border border-gray-300 dark:border-gray-600 placeholder-gray-500 dark:placeholder-gray-400 text-gray-900 dark:text-white bg-white dark:bg-gray-900 rounded-t-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 focus:z-10 sm:text-sm"
                                placeholder="Email address"
                                value={email}
                                onChange={e => setEmail(e.target.value)}
                            />
                        </div>
                        <div className="relative">
                            <input
                                id="password"
                                name="password"
                                type={showPassword ? "text" : "password"}
                                required
                                className="appearance-none rounded-none relative block w-full px-3 py-3 border border-gray-300 dark:border-gray-600 placeholder-gray-500 dark:placeholder-gray-400 text-gray-900 dark:text-white bg-white dark:bg-gray-900 rounded-b-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 focus:z-10 sm:text-sm pr-10"
                                placeholder="Password"
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                            />
                            <button
                                type="button"
                                className="absolute inset-y-0 right-0 flex items-center pr-3 z-20 text-gray-400 hover:text-gray-600 dark:text-gray-400 dark:hover:text-gray-200 focus:outline-none"
                                onClick={() => setShowPassword(!showPassword)}
                            >
                                {showPassword ? <EyeSlashIcon className="w-5 h-5" /> : <EyeIcon className="w-5 h-5" />}
                            </button>
                        </div>
                    </div>

                    <div className="flex items-center justify-between">
                        <div className="flex items-center">
                            <input id="remember-me" name="remember-me" type="checkbox" className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700" />
                            <label htmlFor="remember-me" className="ml-2 block text-xs text-gray-900 dark:text-gray-300">Remember session</label>
                        </div>
                        <div className="text-xs">
                            <a href="#" className="font-bold text-blue-600 hover:text-blue-500 dark:text-blue-400">Recover password?</a>
                        </div>
                    </div>

                    <div>
                        <button
                            type="submit"
                            disabled={loading}
                            className="group relative w-full flex justify-center py-3 px-4 border border-transparent text-xs font-black uppercase tracking-widest rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-400 transition-all shadow-md active:scale-[0.98]"
                        >
                            {loading ? (
                                <span className="flex items-center gap-2">
                                    <LoaderIcon className="w-4 h-4 animate-spin" /> Verification...
                                </span>
                            ) : (
                                "Authenticate"
                            )}
                        </button>
                    </div>
                </form>

                <div className="pt-4 border-t border-gray-100 dark:border-gray-700 text-center">
                    <p className="text-[10px] text-gray-400 uppercase tracking-tighter">Authorized Personnel Only • IP Logged</p>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;

// @ts-ignore
import { createUserWithEmailAndPassword, deleteUser, signOut, signInWithEmailAndPassword } from "firebase/auth";
import { doc, setDoc, serverTimestamp, getDoc } from "firebase/firestore";
import { secondaryAuth, db, auth } from "./firebase";

/**
 * Normalizes email strings to prevent login mismatches (trailing spaces, casing)
 */
export const normalizeEmail = (email: string) => email.trim().toLowerCase();

/**
 * Authenticates a user with the primary Firebase instance.
 * Validates that a corresponding Firestore profile exists.
 */
export const loginWithEmail = async (email: string, password: string) => {
    try {
        const normalized = normalizeEmail(email);
        const userCredential = await signInWithEmailAndPassword(auth, normalized, password);
        const user = userCredential.user;

        // CRITICAL: Integrity Check - Ensure Firestore profile exists
        const userDoc = await getDoc(doc(db, "user", user.uid));
        if (!userDoc.exists()) {
            await signOut(auth);
            throw new Error("ACCOUNT_NOT_PROVISIONED");
        }

        return user;
    } catch (error: any) {
        console.error("Login attempt failed:", error);
        throw error;
    }
};

/**
 * Registers a new staff member atomically.
 * Uses secondaryAuth to keep the current admin session active.
 */
export const registerStaffAccount = async (staffData: {
    email: string;
    password: string;
    fullName: string;
    roleId: string;
    phone?: string;
}) => {
    // 1. Pre-flight Validation
    if (!secondaryAuth) {
        throw new Error("AUTH_SERVICE_UNAVAILABLE");
    }

    if (!staffData.password || staffData.password.length < 6) {
        throw new Error("WEAK_PASSWORD");
    }

    const email = normalizeEmail(staffData.email);
    let createdUser: any = null;

    try {
        // 2. Create Auth Account via secondary instance
        const userCredential = await createUserWithEmailAndPassword(secondaryAuth, email, staffData.password);
        createdUser = userCredential.user;

        // 3. Prepare Firestore Document
        const nameParts = staffData.fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();

        const userProfile = {
            id: createdUser.uid, // Use UID as Document ID for 1:1 mapping
            uid: createdUser.uid,
            fullName: staffData.fullName,
            initials,
            email: email,
            phone: staffData.phone || '',
            roleId: staffData.roleId,
            status: 'Active',
            createdAt: serverTimestamp(),
            lastLogin: 'Never'
        };

        // 4. Persist to Firestore
        await setDoc(doc(db, "user", createdUser.uid), userProfile);

        // 5. Immediately sign out of secondary app to clean up state
        await signOut(secondaryAuth);

        return { success: true, user: createdUser };
    } catch (error: any) {
        console.error("Atomic Registration Failed:", error);

        // Rollback: If user was created in Auth but DB failed, remove them to prevent desync
        if (createdUser) {
            try {
                await deleteUser(createdUser);
            } catch (cleanupError) {
                console.error("Rollback failed:", cleanupError);
            }
        }

        // Map common Firebase errors to actionable strings
        if (error.code === 'auth/email-already-in-use') throw new Error("EMAIL_EXISTS");
        if (error.code === 'auth/invalid-email') throw new Error("INVALID_EMAIL");
        if (error.code === 'auth/weak-password') throw new Error("WEAK_PASSWORD");

        throw error;
    }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Staff } from '../types';
import { useActivityLogs } from '../hooks/useAppData';
import { auth, db } from '../services/firebase';
// @ts-ignore
import { signInWithEmailAndPassword, signOut, onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { normalizeEmail } from '../services/authService';

interface AuthContextType {
    currentStaff: Staff | null;
    login: (email: string, password: string) => Promise<{ success: boolean; message: string }>;
    logout: () => Promise<void>;
    updateCurrentUser: (updates: Partial<Staff>) => void;
    isAuthenticated: boolean;
    loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { addActivityLog } = useActivityLogs();
    const [currentStaff, setCurrentStaff] = useState<Staff | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: any) => {
            if (firebaseUser) {
                try {
                    const userRef = doc(db, "user", firebaseUser.uid);
                    const userSnap = await getDoc(userRef);

                    if (userSnap.exists()) {
                        setCurrentStaff(userSnap.data() as Staff);
                    } else {
                        // CRITICAL: If Auth user exists but Firestore doc is missing, block access
                        console.error("Security alert: Auth session exists but profile document is missing.");
                        await signOut(auth);
                        setCurrentStaff(null);
                    }
                } catch (error) {
                    console.error("Auth Session Verification Failed:", error);
                    setCurrentStaff(null);
                }
            } else {
                setCurrentStaff(null);
            }
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const login = async (email: string, password: string) => {
        try {
            const normalizedEmail = normalizeEmail(email);

            if (!normalizedEmail || !password) {
                return { success: false, message: 'Required fields missing: email and password.' };
            }

            // Step 1: Attempt Firebase Auth login
            const userCredential = await signInWithEmailAndPassword(auth, normalizedEmail, password);
            const user = userCredential.user;

            // Step 2: Verify Firestore document existence immediately
            const userRef = doc(db, "user", user.uid);
            const userSnap = await getDoc(userRef);

            if (!userSnap.exists()) {
                await signOut(auth);
                return { 
                    success: false, 
                    message: 'Critical Error: Your account exists in the security database but is not fully provisioned in the staff registry. Please contact your System Administrator.' 
                };
            }

            return { success: true, message: 'Authenticated successfully' };
        } catch (error: any) {
            console.error("Firebase Login Error Code:", error.code, "| Message:", error.message);

            let message = 'Access denied. Please check your credentials.';

            switch (error.code) {
                case 'auth/invalid-credential':
                    message = 'Incorrect email or password.';
                    break;
                case 'auth/user-not-found':
                    message = 'No account found with this email.';
                    break;
                case 'auth/wrong-password':
                    message = 'The password entered is incorrect.';
                    break;
                case 'auth/user-disabled':
                    message = 'This account has been disabled by an administrator.';
                    break;
                case 'auth/too-many-requests':
                    message = 'Security alert: Too many failed attempts. Try again later.';
                    break;
                case 'auth/network-request-failed':
                    message = 'Connectivity issue: Please check your internet connection.';
                    break;
                default:
                    message = `Auth System Error: ${error.message}`;
            }

            return { success: false, message };
        }
    };

    const logout = async () => {
        if (currentStaff) {
            try {
                addActivityLog('Logout', `User ${currentStaff.fullName} terminated session.`, currentStaff.id);
            } catch (e) {
                console.warn("Log entry failed during signout");
            }
        }
        await signOut(auth);
        setCurrentStaff(null);
    };

    const updateCurrentUser = (updates: Partial<Staff>) => {
        if (currentStaff) {
            setCurrentStaff({ ...currentStaff, ...updates });
        }
    };

    return (
        <AuthContext.Provider value={{
            currentStaff,
            login,
            logout,
            updateCurrentUser,
            isAuthenticated: !!currentStaff,
            loading
        }}>
            {!loading && children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import React, { useState, useEffect, FormEvent, ChangeEvent } from 'react';
import { Staff, Role } from '../types';
import { XIcon } from './icons/XIcon';
import { PhoneInput } from './ui/PhoneInput';
import { EmailInput } from './ui/EmailInput';
import { LockClosedIcon, ShieldCheckIcon, ExclamationTriangleIcon } from './icons/DummyIcons';
import { Badge } from './ui/Badge';
import { LoaderIcon } from './icons/LoaderIcon';

interface StaffFormModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (staffData: Partial<Staff>) => Promise<void>;
    editingUser: Staff | null;
    roles: Role[];
}

const UserFormModal: React.FC<StaffFormModalProps> = ({ isOpen, onClose, onSave, editingUser, roles }) => {
    const [formData, setFormData] = useState({
        fullName: '',
        phone: '',
        email: '',
        roleId: '',
        password: '',
        status: 'Active' as Staff['status'],
    });
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (isOpen) {
            setError(null);
            if (editingUser) {
                setFormData({
                    fullName: editingUser.fullName,
                    phone: editingUser.phone || '',
                    email: editingUser.email,
                    roleId: editingUser.roleId,
                    password: '',
                    status: editingUser.status,
                });
            } else {
                setFormData({
                    fullName: '',
                    phone: '',
                    email: '',
                    roleId: roles.find(r => r.name === 'Sales Representative')?.id || roles[0]?.id || '',
                    password: '',
                    status: 'Active',
                });
            }
        }
    }, [isOpen, editingUser, roles]);

    const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({...prev, [name]: value}));
    };

    const handleSubmit = async (e: FormEvent) => {
        e.preventDefault();
        setError(null);

        // Security Validation
        if(!editingUser && (!formData.password || formData.password.length < 6)) {
            setError("Security Requirement: Password must be at least 6 characters long.");
            return;
        }

        setIsSaving(true);
        try {
            await onSave(formData);
        } catch (err: any) {
            setError(err.message || "An unexpected system error occurred.");
            setIsSaving(false); // Only stop loading if it failed so user can fix
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-lg border border-gray-200 dark:border-gray-700 overflow-hidden flex flex-col">
                <form onSubmit={handleSubmit} className="flex flex-col h-full">
                    <div className="flex justify-between items-center p-5 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                        <h3 className="text-xl font-bold text-gray-800 dark:text-white">
                            {editingUser ? 'Edit Staff Account' : 'Create New Staff Account'}
                        </h3>
                        <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 transition-colors">
                            <XIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="p-6 space-y-6 overflow-y-auto max-h-[70vh]">
                        {error && (
                            <div className="p-3 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded flex items-start gap-3 animate-in fade-in slide-in-from-top-1">
                                <ExclamationTriangleIcon className="w-5 h-5 text-red-600 shrink-0 mt-0.5" />
                                <p className="text-sm text-red-800 dark:text-red-200 font-medium">{error}</p>
                            </div>
                        )}

                        {/* Section 1: Profile Details */}
                        <div className="space-y-4">
                            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest border-b border-gray-100 dark:border-gray-700 pb-2">Profile Details</h4>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="md:col-span-2">
                                    <label htmlFor="fullName" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Full Name*</label>
                                    <input type="text" name="fullName" id="fullName" value={formData.fullName} onChange={handleChange} required className="mt-1 input-class" />
                                </div>
                                <div>
                                    <PhoneInput label="Phone Number" id="phone" name="phone" value={formData.phone} onChange={(val) => setFormData(prev => ({...prev, phone: val}))} />
                                </div>
                                <div>
                                    <label htmlFor="status" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Account Status*</label>
                                    <select name="status" id="status" value={formData.status} onChange={handleChange} required className="mt-1 input-class">
                                        <option value="Active">Active</option>
                                        <option value="Inactive">Inactive</option>
                                    </select>
                                </div>
                                <div className="md:col-span-2">
                                    <label htmlFor="roleId" className="block text-sm font-medium text-gray-700 dark:text-gray-300">System Role*</label>
                                    <select name="roleId" id="roleId" value={formData.roleId} onChange={handleChange} required className="mt-1 input-class">
                                        {roles.map(role => <option key={role.id} value={role.id}>{role.name}</option>)}
                                    </select>
                                </div>
                            </div>
                        </div>

                        {/* Section 2: Login Information */}
                        <div className="space-y-4 pt-4 border-t border-gray-100 dark:border-gray-700">
                            <div className="flex items-center justify-between">
                                <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest">Login Information</h4>
                                {editingUser && (
                                    <Badge variant="success" className="flex items-center gap-1">
                                        <ShieldCheckIcon className="w-3 h-3" /> Password Configured
                                    </Badge>
                                )}
                            </div>

                            <div className="grid grid-cols-1 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Login Email</label>
                                    <div className="mt-1 relative rounded-md shadow-sm">
                                        <input
                                            type="email"
                                            value={formData.email}
                                            readOnly={!!editingUser}
                                            disabled={!!editingUser}
                                            onChange={(e) => setFormData(prev => ({...prev, email: e.target.value}))}
                                            className={`input-class ${editingUser ? 'bg-gray-50 dark:bg-gray-900 cursor-not-allowed text-gray-500' : ''}`}
                                            placeholder="staff@faim.com"
                                            required
                                        />
                                        {editingUser && (
                                            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                                                <LockClosedIcon className="h-4 w-4 text-gray-400" />
                                            </div>
                                        )}
                                    </div>
                                    {editingUser && <p className="mt-1 text-[10px] text-gray-400 italic">Login identifier is managed by system administrators.</p>}
                                </div>

                                <div>
                                    <label htmlFor="password" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                                        {editingUser ? 'Reset Account Password' : 'Initial Password*'}
                                    </label>
                                    <input 
                                        type="password" 
                                        name="password" 
                                        id="password" 
                                        value={formData.password} 
                                        onChange={handleChange} 
                                        placeholder={editingUser ? 'Leave blank to keep existing password' : 'Min 6 characters'} 
                                        className={`mt-1 input-class font-mono ${error?.includes("Password") ? 'border-red-500 ring-1 ring-red-500' : ''}`} 
                                    />
                                </div>
                            </div>
                        </div>
                    </div>

