// @ts-ignore
import { createUserWithEmailAndPassword, deleteUser, signOut, signInWithEmailAndPassword } from "firebase/auth";
import { doc, setDoc, serverTimestamp, getDoc } from "firebase/firestore";
import { secondaryAuth, db, auth } from "./firebase";

/**
 * Normalizes email strings to prevent login mismatches (trailing spaces, casing)
 */
export const normalizeEmail = (email: string) => email.trim().toLowerCase();

/**
 * Authenticates a user with the primary Firebase instance.
 * Step 1 of Flow: Hard Identity Gate.
 * This function no longer validates Firestore profiles to prevent silent logouts.
 */
export const loginWithEmail = async (email: string, password: string) => {
    try {
        const normalized = normalizeEmail(email);
        const userCredential = await signInWithEmailAndPassword(auth, normalized, password);
        return userCredential.user;
    } catch (error: any) {
        console.error("Authentication Phase Failed:", error.code);
        // Map specific auth failure for clear UI feedback
        if (error.code === 'auth/invalid-credential' || error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password') {
            throw new Error("INVALID_CREDENTIALS");
        }
        throw error;
    }
};

/**
 * Registers a new staff member atomically.
 * Uses secondaryAuth to keep the current admin session active.
 */
export const registerStaffAccount = async (staffData: {
    email: string;
    password: string;
    fullName: string;
    roleId: string;
    phone?: string;
}) => {
    const email = normalizeEmail(staffData.email);
    let createdUser: any = null;

    try {
        // 1. Create Auth Identity
        const userCredential = await createUserWithEmailAndPassword(secondaryAuth, email, staffData.password);
        createdUser = userCredential.user;

        // 2. Prepare Firestore Profile (Deterministic Path: /user/{uid})
        const nameParts = staffData.fullName.split(' ');
        const initials = ((nameParts[0]?.[0] || '') + (nameParts[nameParts.length - 1]?.[0] || '')).toUpperCase();

        const userProfile = {
            id: createdUser.uid,
            uid: createdUser.uid,
            fullName: staffData.fullName,
            initials,
            email: email,
            phone: staffData.phone || '',
            roleId: staffData.roleId,
            status: 'Active',
            createdAt: serverTimestamp(),
            lastLogin: 'Never'
        };

        // 3. Persist Profile
        await setDoc(doc(db, "user", createdUser.uid), userProfile);

        // 4. State Cleanup (Secondary app only)
        await signOut(secondaryAuth);

        return { success: true, user: createdUser };
    } catch (error: any) {
        console.error("Atomic Registration Failure:", error);
        if (createdUser) {
            try {
                await deleteUser(createdUser);
            } catch (cleanupError) {
                console.error("Integrity Error: Orphaned Auth account exists.", cleanupError);
            }
        }
        throw error;
    }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Staff } from '../types';
import { useActivityLogs } from '../hooks/useAppData';
import { auth, db } from '../services/firebase';
// @ts-ignore
import { signInWithEmailAndPassword, signOut, onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore';
import { normalizeEmail } from '../services/authService';

interface AuthContextType {
    currentStaff: Staff | null;
    login: (email: string, password: string) => Promise<{ success: boolean; message: string }>;
    logout: () => Promise<void>;
    updateCurrentUser: (updates: Partial<Staff>) => void;
    isAuthenticated: boolean;
    loading: boolean;
    sessionStatus: 'idle' | 'authenticating' | 'resolving_profile' | 'bootstrapping' | 'ready' | 'error';
    authError: string | null;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { addActivityLog } = useActivityLogs();
    const [currentStaff, setCurrentStaff] = useState<Staff | null>(null);
    const [loading, setLoading] = useState(true);
    const [sessionStatus, setSessionStatus] = useState<'idle' | 'authenticating' | 'resolving_profile' | 'bootstrapping' | 'ready' | 'error'>('idle');
    const [authError, setAuthError] = useState<string | null>(null);

    // Step 2: Profile Resolution (Soft Gate)
    const resolveUserProfile = async (firebaseUser: any) => {
        try {
            setSessionStatus('resolving_profile');
            const userRef = doc(db, "user", firebaseUser.uid);
            const userSnap = await getDoc(userRef);

            if (userSnap.exists()) {
                setCurrentStaff(userSnap.data() as Staff);
                setSessionStatus('ready');
            } else {
                // Step 2b: Bootstrap State (Self-healing for missing docs)
                setSessionStatus('bootstrapping');
                const email = normalizeEmail(firebaseUser.email || '');
                const initials = (email.substring(0, 2)).toUpperCase();

                const newProfile: any = {
                    id: firebaseUser.uid,
                    uid: firebaseUser.uid,
                    fullName: email.split('@')[0], 
                    initials,
                    email: email,
                    roleId: 'Sales Representative', // Default non-CEO role
                    status: 'Active',
                    createdAt: serverTimestamp(),
                    lastLogin: new Date().toISOString()
                };

                await setDoc(userRef, newProfile);
                setCurrentStaff(newProfile as Staff);
                setSessionStatus('ready');
            }
        } catch (error: any) {
            console.error("Profile Resolution Error:", error);
            setAuthError(`Authorization Error: ${error.message}`);
            setSessionStatus('error');
            // CRITICAL: We do NOT signOut() here. We stay in 'error' status for the UI to handle.
        }
    };

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: any) => {
            if (firebaseUser) {
                await resolveUserProfile(firebaseUser);
            } else {
                setCurrentStaff(null);
                setSessionStatus('idle');
            }
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const login = async (email: string, password: string) => {
        setAuthError(null);
        setSessionStatus('authenticating');
        try {
            const normalizedEmail = normalizeEmail(email);
            // Step 1: Authentication Phase (Hard Identity Gate)
            await signInWithEmailAndPassword(auth, normalizedEmail, password);
            // The onAuthStateChanged observer handles the rest of the flow.
            return { success: true, message: 'Identity verified. Resolving session...' };
        } catch (error: any) {
            let message = 'Access denied. Please check your credentials.';
            if (error.code === 'auth/invalid-credential' || error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password') {
                message = 'Incorrect email or password.';
            } else if (error.code === 'auth/network-request-failed') {
                message = 'Connection error. Please check your internet.';
            }

            setAuthError(message);
            setSessionStatus('error');
            return { success: false, message };
        }
    };

    const logout = async () => {
        if (currentStaff) {
            try {
                addActivityLog('Logout', `User ${currentStaff.fullName} ended session.`, currentStaff.id);
            } catch (e) {}
        }
        setSessionStatus('idle');
        setAuthError(null);
        await signOut(auth);
        setCurrentStaff(null);
    };

    const updateCurrentUser = (updates: Partial<Staff>) => {
        if (currentStaff) {
            setCurrentStaff({ ...currentStaff, ...updates });
        }
    };

    return (
        <AuthContext.Provider value={{
            currentStaff,
            login,
            logout,
            updateCurrentUser,
            isAuthenticated: !!auth.currentUser,
            loading,
            sessionStatus,
            authError
        }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

