                <span className="font-bold text-xl text-gray-800 dark:text-white tracking-wide">
                    {companySettings.name.split(' ')[0]}<span className="text-blue-500">.</span>
                </span>
            </div>

            <div className="absolute top-4 right-4">
                <ThemeToggle />
            </div>

            <div className="w-full max-w-md p-8 space-y-8 bg-white dark:bg-gray-800 rounded-xl shadow-2xl transition-colors duration-200 mt-12 sm:mt-0 border border-gray-100 dark:border-gray-700">
                <div className="flex flex-col items-center">
                    {activeAppLogo ? (
                        <img src={activeAppLogo} alt="FAIM Logo" className="w-32 h-32 object-contain mb-4" />
                    ) : (
                        <FaimLogoIcon className="w-24 h-24 text-blue-600 dark:text-blue-400 mb-4" />
                    )}
                    <p className="text-gray-500 dark:text-gray-400 text-[10px] font-black uppercase tracking-[0.2em]">FAIM Enterprise Management</p>
                </div>

                {(error || isSystemError) && (
                    <div className={`border-l-4 p-4 rounded-md animate-in fade-in slide-in-from-top-1 duration-200 ${initStatus === 'success' ? 'bg-green-50 dark:bg-green-900/20 border-green-500 text-green-700 dark:text-green-200' : isSystemError ? 'bg-amber-50 dark:bg-amber-900/20 border-amber-500 text-amber-700 dark:text-amber-200' : 'bg-red-50 dark:bg-red-900/20 border-red-500 text-red-700 dark:text-red-200'}`} role="alert">
                        <div className="flex items-start">
